#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADS1115 I2C address
#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERSION 0x00

// ADS1115 configuration values
#define ADS1115_CONFIG_SINGLE_SHOT 0x8000  // Start single conversion
#define ADS1115_CONFIG_MUX_AIN0_GND 0x4000  // AIN0 single-ended
#define ADS1115_CONFIG_PGA_4_096V 0x0040   // PGA = +/-4.096V
#define ADS1115_CONFIG_DR_128SPS 0x0060    // 128 SPS
#define ADS1115_CONFIG_MODE_SINGLE 0x0100  // Single-shot mode
#define ADS1115_CONFIG_OS_SINGLE 0x8000   // Start a single conversion

// MLX91219 sensitivity and zero-current offset
#define MLX91219_SENSITIVITY 0.040  // 40mV/A
#define MLX91219_ZERO_CURRENT_OFFSET 2.5 // VCC/2

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
}

// Function to read the ADS1115 configuration register
int read_ads1115_config(int handle) {
    char buf[2];
    int result = i2cReadI2CBlockData(handle, ADS1115_REG_CONFIG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading ADS1115 config register: %d\n", result);
        return -1;
    }
    return (buf[0] << 8) | buf[1];
}

// Function to write the ADS1115 configuration register
int write_ads1115_config(int handle, unsigned short config) {
    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;
    int result = i2cWriteI2CBlockData(handle, ADS1115_REG_CONFIG, buf+1, 2);
    if (result != 2) {
        fprintf(stderr, "Error writing ADS1115 config register: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read the ADS1115 conversion register
int16_t read_ads1115_conversion(int handle) {
    char buf[2];
    int result = i2cReadI2CBlockData(handle, ADS1115_REG_CONVERSION, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading ADS1115 conversion register: %d\n", result);
        return -1;
    }
    return (buf[0] << 8) | buf[1];
}

// Function to read the current from the MLX91219 sensor
float read_mlx91219_current(int handle) {
    // Start single conversion
    unsigned short config = ADS1115_CONFIG_SINGLE_SHOT | ADS1115_CONFIG_MUX_AIN0_GND | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_OS_SINGLE;
    if (write_ads1115_config(handle, config) != 0) {
        return -1.0;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    // Read conversion register
    int16_t raw_value = read_ads1115_conversion(handle);
    if (raw_value == -1) {
        return -1.0;
    }

    // Convert raw value to voltage (assuming +/-4.096V range)
    float voltage = (float)raw_value * 4.096 / 32767.0;

    // Convert voltage to current using MLX91219 sensitivity and zero-current offset
    float current = (voltage - MLX91219_ZERO_CURRENT_OFFSET) / MLX91219_SENSITIVITY;

    return current;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read current from MLX91219 sensor
        float current = read_mlx91219_current(i2c_handle);

        // Log current to console
        if (current >= 0) {
            printf("Current: %.3f A\n", current);
        } else {
            fprintf(stderr, "Error reading current\n");
        }

        // Wait 500ms
        gpioDelay(500000);
    }

    // Close I2C bus and terminate pigpio library
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

