                gpioWrite(BUZZER_GPIO, 1); // Activate buzzer
                gpioDelay(BUZZER_DURATION * 1000000); // Wait for buzzer duration
                gpioWrite(BUZZER_GPIO, 0); // Deactivate buzzer
            }
        } else {
            log_event("Error reading temperature.");
        }

