    uint16_t config = 0x4003; // Single-shot, AIN0, +/-4.096V, 128 SPS
    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;

    if (i2cWriteDevice(i2c_config.handle, buf, 3) != 0) {
        fprintf(stderr, "Failed to write to I2C device: %s\n", strerror(errno));
        i2cClose(i2c_config.handle);
        return -1;
    }

    return 0;
}

