    uint8_t buf[2];
    int16_t raw_value;
    float voltage;

    // Start a single conversion
    uint16_t config = 0xC283; // Start single conversion, AIN0, +/-4.096V, 128 SPS
    char start_buf[3];
    start_buf[0] = ADS1115_REG_CONFIG;
    start_buf[1] = (config >> 8) & 0xFF;
    start_buf[2] = config & 0xFF;

    if (i2cWriteDevice(i2c_config.handle, start_buf, 3) != 0) {
        fprintf(stderr, "Failed to start conversion: %s\n", strerror(errno));
        return -1;
    }

    // Wait for conversion to complete (at least 8.5ms)
