    buf[0] = ADS1115_REG_CONVERT;
    if (i2cWriteDevice(i2c_config.handle, buf, 1) != 0) {
        fprintf(stderr, "Failed to write to I2C device: %s\n", strerror(errno));
        return -1;
    }

    if (i2cReadDevice(i2c_config.handle, (char *)buf, 2) != 2) {
        fprintf(stderr, "Failed to read from I2C device: %s\n", strerror(errno));
        return -1;
    }

    raw_value = (buf[0] << 8) | buf[1];

    // Convert to voltage
    voltage = (float)raw_value * ADC_VOLTAGE_RANGE / 32768.0f;

    // Convert to temperature
    *temperature = (voltage / ADC_VOLTAGE_RANGE) * TEMP_RANGE + TEMP_OFFSET;

