    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write to file
    printf("[%s] %s\n", timestamp, message);
    return 0;
}

void flame_callback(int gpio, int level, uint32_t tick) {
    uint32_t now = gpioTick();
    if (now - last_flame_event > DEBOUNCE_TIME * 1000) {
        log_event("Debounced flame event detected!");
        last_flame_event = now;
    }
}

void signal_handler(int signal) {
    running = 0;
}

void cleanup() {
    gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is off
    if (i2c_config.handle >= 0) {
        i2cClose(i2c_config.handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

