#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define FLAME_SENSOR_DIGITAL_PIN 4
#define MCP3008_CE0 8
#define MCP3008_CE1 7 // Added CE1 for the second sensor

// Define SPI parameters
#define SPI_CHANNEL 0 // CE0
#define SPI_CHANNEL_1 1 // CE1
#define SPI_SPEED 1000000 // 1 MHz

// Define temperature range for linear scaling
#define MIN_ADC 0
#define MAX_ADC 1023
#define MIN_TEMP 10.0
#define MAX_TEMP 40.0

// Global variables
int spi_handle;
int spi_handle_1;
FILE *fp;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_flame_sensor();
int read_mcp3008(int channel);
float calculate_temperature(int adc_value);
void log_data(int flame_detected, float temperature);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure to hold sensor data
typedef struct {
    int flame_detected;
    float temperature;
} sensor_data_t;

// Function to initialize the pigpio library and SPI
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (CE0)\n");
        gpioTerminate();
        return 1;
    }

    spi_handle_1 = spiOpen(SPI_CHANNEL_1, SPI_SPEED, 0); // Mode 0
    if (spi_handle_1 < 0) {
        fprintf(stderr, "SPI open failed (CE1)\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    fp = fopen("flame_data.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open flame_data.csv\n");
        spiClose(spi_handle);
        spiClose(spi_handle_1);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize == 0) {
        fprintf(fp, "Timestamp,Flame Detected,Temperature (C)\n");
    }

    return 0;
}

// Function to read the flame sensor's digital output
int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_DIGITAL_PIN);
}

// Function to read the MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int spi_result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (spi_result != 3) {
        fprintf(stderr, "SPI transfer failed (CE0): %d\n", spi_result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

int read_mcp3008_1(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int spi_result = spiXfer(spi_handle_1, spi_tx_buf, spi_rx_buf, 3);
    if (spi_result != 3) {
        fprintf(stderr, "SPI transfer failed (CE1): %d\n", spi_result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to calculate the ambient temperature from the ADC value
float calculate_temperature(int adc_value) {
    return MIN_TEMP + (float)(adc_value - MIN_ADC) * (MAX_TEMP - MIN_TEMP) / (MAX_ADC - MIN_ADC);
}

