#define MCP3008_CE1 7 // Added CE1 for the second sensor

// Define SPI parameters
#define SPI_CHANNEL 0 // CE0
#define SPI_CHANNEL_1 1 // CE1
#define SPI_SPEED 1000000 // 1 MHz

// Define temperature range for linear scaling
#define MIN_ADC 0
#define MAX_ADC 1023
#define MIN_TEMP 10.0
#define MAX_TEMP 40.0

// Global variables
int spi_handle;
int spi_handle_1;
FILE *fp;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_flame_sensor();
int read_mcp3008(int channel);
float calculate_temperature(int adc_value);
void log_data(int flame_detected, float temperature);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure to hold sensor data
typedef struct {
    int flame_detected;
    float temperature;
} sensor_data_t;

// Function to initialize the pigpio library and SPI
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (CE0)\n");
        gpioTerminate();
        return 1;
    }

    spi_handle_1 = spiOpen(SPI_CHANNEL_1, SPI_SPEED, 0); // Mode 0
    if (spi_handle_1 < 0) {
        fprintf(stderr, "SPI open failed (CE1)\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

