    printf("CO Monitor started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Calculate CO level
            float co_ppm = calculate_co_ppm(sensor_data.ox);

            // Log CO level
            if (log_co_level(co_ppm) != 0) {
                fprintf(stderr, "Failed to log CO level\n");
            }

            // Check for alert
            if (co_ppm > ALERT_THRESHOLD) {
                if (log_alert(co_ppm) != 0) {
                    fprintf(stderr, "Failed to log alert\n");
                }
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for the next reading
        sleep(READ_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

