float calculate_average_pressure_level(float pressure_1, float pressure_2);
void log_data(float average_pressure_level);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float pressure_level;
} sensor_data_t;

// Function to initialize I2C
int initialize_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02x: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Function to read sensor data
int read_sensor_data(int i2c_handle) {
    char buffer[2];
    int bytes_read = i2cReadDevice(i2c_handle, buffer, 2);

    if (bytes_read != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", bytes_read);
        return -1;
    }

    int16_t raw_data = (buffer[0] << 8) | buffer[1];
    return raw_data;
}

// Function to convert raw data to pressure level (dB)
float convert_to_pressure_level(int16_t raw_data) {
    // Assuming raw_data is a signed 16-bit integer representing the analog voltage
    // Convert raw data to voltage (assuming 16-bit ADC and 3.3V reference)
    float voltage = (float)raw_data / 32767.0 * 3.3;

    // Convert voltage to pressure using microphone sensitivity
    float pressure = voltage * (1.0 / (pow(10.0, MICROPHONE_SENSITIVITY_DBV_PA / 20.0)));

    // Convert pressure to dB
    float pressure_level_db = 20 * log10(pressure / REFERENCE_PRESSURE_PA);

    return pressure_level_db;
}

// Function to calculate the average pressure level
float calculate_average_pressure_level(float pressure_1, float pressure_2) {
    if (pressure_1 == ERROR_VALUE_DB || pressure_2 == ERROR_VALUE_DB) {
        return ERROR_VALUE_DB;
    }
    return (pressure_1 + pressure_2) / 2.0;
}

// Function to log data to file
void log_data(float average_pressure_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f dB\n", timestamp, average_pressure_level);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to close I2C and terminate pigpio
void cleanup() {
    if (i2c_handle_1 >= 0) {
        i2cClose(i2c_handle_1);
    }
    if (i2c_handle_2 >= 0) {
        i2cClose(i2c_handle_2);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("audio_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C for both sensors
    i2c_handle_1 = initialize_i2c(I2C_BUS, I2C_ADDR_1);
    if (i2c_handle_1 < 0) {
        cleanup();
        return 1;
    }

    i2c_handle_2 = initialize_i2c(I2C_BUS, I2C_ADDR_2);
    if (i2c_handle_2 < 0) {
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read data from both sensors
        int16_t raw_data_1 = read_sensor_data(i2c_handle_1);
        int16_t raw_data_2 = read_sensor_data(i2c_handle_2);

        float pressure_level_1 = ERROR_VALUE_DB;
        float pressure_level_2 = ERROR_VALUE_DB;

        if (raw_data_1 != -1) {
            pressure_level_1 = convert_to_pressure_level(raw_data_1);
        }

        if (raw_data_2 != -1) {
            pressure_level_2 = convert_to_pressure_level(raw_data_2);
        }

        // Calculate average pressure level
        float average_pressure_level = calculate_average_pressure_level(pressure_level_1, pressure_level_2);

        // Log data
        log_data(average_pressure_level);

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

