void log_data(time_t timestamp, double mic1_rms, double mic2_rms) {
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.4f,%.4f\n", timestamp_str, mic1_rms, mic2_rms);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Function to cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    control_led(0); // Turn off LED
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();
    exit(0);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    if (initialize()) {
        return 1;
    }

    Microphone mic1 = {0, SPI_CE0, 0, 0.0};
    Microphone mic2 = {1, SPI_CE1, 0, 0.0};
    int mic1_data[WINDOW_SIZE];
    int mic2_data[WINDOW_SIZE];

    int mic1_index = 0;
    int mic2_index = 0;

    printf("Audio monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC values
        mic1.adc_value = read_adc(mic1.spi_channel, mic1.channel);
        mic2.adc_value = read_adc(mic2.spi_channel, mic2.channel);

        // Store data in circular buffers
        mic1_data[mic1_index] = mic1.adc_value;
        mic2_data[mic2_index] = mic2.adc_value;

        mic1_index = (mic1_index + 1) % WINDOW_SIZE;
        mic2_index = (mic2_index + 1) % WINDOW_SIZE;

        // Calculate RMS values
        mic1.rms_value = calculate_rms(mic1_data, WINDOW_SIZE);
        mic2.rms_value = calculate_rms(mic2_data, WINDOW_SIZE);

        // Check if RMS values exceed threshold
        if (mic1.rms_value > RMS_THRESHOLD || mic2.rms_value > RMS_THRESHOLD) {
            control_led(1); // Turn on LED
            gpioDelay(500);  // Wait for 500 ms
            control_led(0); // Turn off LED
        }

        // Log data
        time_t current_time = time(NULL);
        log_data(current_time, mic1.rms_value, mic2.rms_value);

        gpioDelay(1); // Sample at 1 ms interval
    }

    cleanup();
    return 0;
}

