#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_CONFIG_REG 0x01
#define ADS1115_CONVERSION_REG 0x00
#define ADS1115_FULL_SCALE_VOLTAGE 4.096 // +/- 4.096V
#define ADS1115_DATA_RATE 128 // 128 SPS
#define ADS1115_GAIN 2 // +/- 2x
#define MLX91204_VREF 5.0 // 5V reference
#define MLX91204_VZERO 0.5 // 0.5V zero current output
#define MLX91204_SENSITIVITY (MLX91204_VREF - MLX91204_VZERO) / 100.0 // 40mV/A
#define OVERCURRENT_THRESHOLD 50.0 // 50A
#define LED_GPIO 17
#define SAMPLE_RATE 10 // Hz
#define BUFFER_SIZE 100

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float current_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int initialize_pigpio();
int initialize_i2c();
int read_ads1115(int *raw_value);
float convert_to_current(int raw_value);
void update_circular_buffer(float current);
float calculate_average_current();
void control_led(float average_current);
void signal_handler(int signal);

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read from ADS1115
int read_ads1115(int *raw_value) {
    char config[3];
    int16_t raw;

    // Configure ADS1115 for single-ended A0, 4.096V, 128 SPS, single conversion
    config[0] = ADS1115_CONFIG_REG;
    config[1] = 0x43; // Single conversion, AIN0, +/-4.096V, 128 SPS, single-shot mode
    config[2] = 0x83; // MSB: OS=1 (start single conversion), MUX[2:0]=000 (AIN0), PGA[2:0]=011 (+/-4.096V), MODE=1 (single-shot), DR[2:0]=011 (128 SPS), COMP_MODE=0 (traditional comparator), COMP_POL=0 (active low), COMP_LAT=0 (non-latching), COMP_QUE[1:0]=11 (disable comparator)

    if (i2cWriteDevice(i2c_handle, config, 3) != 0) {
        fprintf(stderr, "Failed to write to ADS1115 config register\n");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    // Read conversion register
    char data[2];
    data[0] = ADS1115_CONVERSION_REG;
    if (i2cWriteDevice(i2c_handle, data, 1) != 0) {
        fprintf(stderr, "Failed to write to ADS1115 conversion register\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Failed to read from ADS1115 conversion register\n");
        return -1;
    }

    raw = (data[0] << 8) | data[1];
    *raw_value = raw;

    return 0;
}

// Function to convert raw ADC value to current
float convert_to_current(int raw_value) {
    float voltage = (float)raw_value * ADS1115_FULL_SCALE_VOLTAGE / 32768.0; // 16-bit ADC
    float current = (voltage - MLX91204_VZERO) / MLX91204_SENSITIVITY;
    return current;
}

// Function to update the circular buffer
void update_circular_buffer(float current) {
    current_buffer[buffer_index] = current;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to calculate the average current from the buffer
float calculate_average_current() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += current_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Function to control the LED based on the average current
void control_led(float average_current) {
    if (average_current > OVERCURRENT_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize circular buffer with zeros
    for (int i = 0; i < BUFFER_SIZE; i++) {
        current_buffer[i] = 0.0;
    }

    int raw_value;
    float current;
    float average_current;

    // Main loop
    while (!terminate) {
        // Read from ADS1115
        if (read_ads1115(&raw_value) == 0) {
            // Convert to current
            current = convert_to_current(raw_value);

            // Update circular buffer
            update_circular_buffer(current);

            // Calculate average current
            average_current = calculate_average_current();

            // Control LED
            control_led(average_current);

            // Print current and average current (for debugging)
            printf("Current: %.2f A, Average Current: %.2f A\n", current, average_current);
        } else {
            fprintf(stderr, "Failed to read from ADS1115\n");
        }

        // Delay for 100ms (10Hz sampling rate)
        gpioDelay(100000); // 100ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn LED off
    gpioTerminate();

    return 0;
}

