// TCS34725 I2C address
#define TCS34725_ADDRESS 0x29

// TCS34725 registers
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_CONTROL 0x0F
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A

// Enable register values
#define TCS34725_ENABLE_PON 0x01
#define TCS34725_ENABLE_AEN 0x02

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_color_data(uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue);
int log_color_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize the TCS34725 sensor
int initialize_sensor() {
    // Set integration time to 2.4 ms (0xFF)
    if (i2cWriteByteData(i2c_handle, TCS34725_ATIME, 0xFF) < 0) {
        fprintf(stderr, "Error writing to ATIME register\n");
        return -1;
    }

    // Set gain to 4x (0x01)
    if (i2cWriteByteData(i2c_handle, TCS34725_CONTROL, 0x01) < 0) {
        fprintf(stderr, "Error writing to CONTROL register\n");
        return -1;
    }

    // Power on and enable ADC
    if (i2cWriteByteData(i2c_handle, TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) < 0) {
        fprintf(stderr, "Error writing to ENABLE register\n");
        return -1;
    }

    // Wait for 3 ms
    gpioDelay(3000);

    return 0;
}

// Function to read color data from the sensor
int read_color_data(uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    char buf[8];
    int retries = 0;
    int result;

    while (retries < 3) {
        result = i2cReadI2CBlockData(i2c_handle, TCS34725_CDATA, buf, 8);
        if (result == 8) {
            *clear = (buf[1] << 8) | buf[0];
            *red   = (buf[3] << 8) | buf[2];
            *green = (buf[5] << 8) | buf[4];
            *blue  = (buf[7] << 8) | buf[6];
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(1000); // Wait 1 ms before retrying
        }
    }

    fprintf(stderr, "I2C read failed after 3 retries\n");
    return -1; // Failure after retries
}

