#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL_0 0
#define MCP3008_CHANNEL_1 1
#define CS_PIN 8 // GPIO8 (CE0)
#define LOG_FILE "moisture_log.csv"

// Global variables
static volatile int keep_running = 1;
static struct gpiod_line *cs_line = NULL;
static FILE *log_file = NULL;

// Function prototypes
int spi_init(void);
int spi_read_channel(int channel);
float map_adc_to_moisture(int adc_value);
int log_data(float moisture1, float moisture2);
void signal_handler(int sig);
int gpio_init(void);
void gpio_cleanup(void);

// SPI Initialization
int spi_init(void) {
    int fd;
    uint8_t mode = SPI_MODE;
    uint8_t bits = SPI_BITS_PER_WORD;
    uint32_t speed = SPI_SPEED;

    fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting SPI bits per word");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI Read Channel
int spi_read_channel(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];
    int fd = spi_init();

    if (fd < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return -1;
    }

    // MCP3008 command: start bit (1), single-ended mode (1), channel (3 bits), don't care (3 bits)
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended, channel select
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error sending SPI message");
        close(fd);
        return -1;
    }

    close(fd);

    // Extract the ADC value from the response
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Map ADC Value to Moisture Percentage
float map_adc_to_moisture(int adc_value) {
    return (float)adc_value / 1023.0 * 100.0;
}

// Log Data to CSV File
int log_data(float moisture1, float moisture2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
        fprintf(log_file, "Timestamp,Moisture1,Moisture2\n");
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, moisture1, moisture2);
    fflush(log_file); // Ensure data is written immediately

    return 0;
}

// Signal Handler
void signal_handler(int sig) {
    printf("Caught signal %d, exiting...\n", sig);
    keep_running = 0;
}

// GPIO Initialization
int gpio_init(void) {
    struct gpiod_chip *chip;
    struct gpiod_line_request_config config;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    cs_line = gpiod_chip_get_line(chip, CS_PIN);
    if (!cs_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    memset(&config, 0, sizeof(config));
    config.consumer = "moisture_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(cs_line, &config, 0) < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(chip);
        return -1;
    }

    // Set CS high initially
    gpiod_line_set_value(cs_line, 1);

    return 0;
}

// GPIO Cleanup
void gpio_cleanup(void) {
    if (cs_line) {
        gpiod_line_set_value(cs_line, 1); // Set CS high before releasing
        gpiod_line_release(cs_line);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main(void) {
    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        return 1;
    }

    // Main loop
    while (keep_running) {
        int adc_value1 = spi_read_channel(MCP3008_CHANNEL_0);
        int adc_value2 = spi_read_channel(MCP3008_CHANNEL_1);

        if (adc_value1 < 0 || adc_value2 < 0) {
            fprintf(stderr, "Error reading ADC values\n");
        } else {
            float moisture1 = map_adc_to_moisture(adc_value1);
            float moisture2 = map_adc_to_moisture(adc_value2);

            if (log_data(moisture1, moisture2) < 0) {
                fprintf(stderr, "Error logging data\n");
            }
        }

        sleep(5);
    }

    // Cleanup
    gpio_cleanup();

    return 0;
}

