        }

        // Overcurrent protection
        if (current > OVERCURRENT_THRESHOLD) {
            printf("Overcurrent detected! Shutting down motor.\n");
            control_motor_shutdown(1); // Disable motor
            sleep(1);
            control_motor_shutdown(0); // Re-enable motor
            printf("Motor re-enabled.\n");
