#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <sys/time.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define MLX90817_ADDR 0x40
#define PRESSURE_REG 0x00
#define PRESSURE_SCALE 500.0
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_pressure(uint16_t *pressure_raw);
double convert_to_kPa(uint16_t pressure_raw);
int log_pressure(double pressure_kPa);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int mlx90817_address;
    const char *log_file_name;
} config_t;

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX90817_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read pressure value from the sensor
int read_pressure(uint16_t *pressure_raw) {
    char buf[2];
    int result;

    for (int i = 0; i < RETRY_COUNT; ++i) {
        result = i2cReadI2CBlockData(i2c_handle, PRESSURE_REG, buf, 2);
        if (result == 2) {
            *pressure_raw = (buf[0] << 8) | buf[1];
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (reg 0x%02X): %d (attempt %d)\n", PRESSURE_REG, result, i + 1);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }
    return -1; // Failure after retries
}

// Convert raw pressure value to kPa
double convert_to_kPa(uint16_t pressure_raw) {
    return ((double)pressure_raw / 65535.0) * PRESSURE_SCALE;
}

// Log pressure reading to file
int log_pressure(double pressure_kPa) {
    time_t now = time(NULL);
    struct tm *utc_tm = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc_tm);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, pressure_kPa);
    fflush(log_file); // Ensure data is written immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("pressure_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,pressure_kPa\n");
    }
    fflush(log_file);

    uint16_t pressure_raw;
    double pressure_kPa;

    // Main loop
    while (!terminate) {
        if (read_pressure(&pressure_raw) == 0) {
            pressure_kPa = convert_to_kPa(pressure_raw);
            if (log_pressure(pressure_kPa) != 0) {
                fprintf(stderr, "Error logging pressure.\n");
            }
        } else {
            fprintf(stderr, "Failed to read pressure after multiple retries.\n");
        }

        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

