// Constants
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define ADS1115_CONFIG_SINGLE_ENDED_AIN0 0x4003 // Single-ended AIN0, 4.096V, 128 SPS, Single conversion
#define ADS1115_CONFIG_SINGLE_ENDED_AIN1 0x4203 // Single-ended AIN1, 4.096V, 128 SPS, Single conversion
#define ADS1115_CONFIG_START_CONVERSION 0x8000
#define ADS1115_CONFIG_OS_SINGLE 0x8000
#define ADS1115_CONFIG_PGA_4_096V 0x0000
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_COMP_MODE_TRAD 0x0000
#define ADS1115_CONFIG_COMP_POL_LOW 0x0000
#define ADS1115_CONFIG_COMP_LAT_NON 0x0000
#define ADS1115_CONFIG_COMP_QUE_DISABLE 0x0003

#define PRESSURE_MIN 0.0
#define PRESSURE_MAX 400.0
#define PRESSURE_VOLTAGE_MIN 0.0
#define PRESSURE_VOLTAGE_MAX 5.0

#define TEMPERATURE_MIN 0.0
#define TEMPERATURE_MAX 100.0
#define TEMPERATURE_VOLTAGE_MIN 1.0
#define TEMPERATURE_VOLTAGE_MAX 2.0

#define LED_GPIO 17

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_ads1115(int handle, int config, int *value);
float adc_to_pressure(int adc_value);
float adc_to_temperature(int adc_value);
void control_led(float pressure);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, ADS1115_ADDR, 0); // Bus 1, address 0x48, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read ADC value from ADS1115
int read_ads1115(int handle, int config, int *value) {
    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    gpioDelay(10); // Wait for conversion

    buf[0] = ADS1115_REG_CONVERT;
    if (i2cWriteDevice(handle, buf, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    char read_buf[2];
    if (i2cReadDevice(handle, read_buf, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    *value = (read_buf[0] << 8) | read_buf[1];
    return 0;
}

// Convert ADC value to pressure (kPa)
float adc_to_pressure(int adc_value) {
    float voltage = (float)adc_value * 4.096 / 32768.0; // 4.096V full scale, 16-bit ADC
    return (voltage - PRESSURE_VOLTAGE_MIN) * (PRESSURE_MAX - PRESSURE_MIN) / (PRESSURE_VOLTAGE_MAX - PRESSURE_VOLTAGE_MIN);
}

// Convert ADC value to temperature (°C)
float adc_to_temperature(int adc_value) {
    float voltage = (float)adc_value * 4.096 / 32768.0; // 4.096V full scale, 16-bit ADC
    return (voltage - TEMPERATURE_VOLTAGE_MIN) * (TEMPERATURE_MAX - TEMPERATURE_MIN) / (TEMPERATURE_VOLTAGE_MAX - TEMPERATURE_VOLTAGE_MIN);
}

// Control LED based on pressure
void control_led(float pressure) {
    if (pressure > 105.0) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    int pressure_adc, temperature_adc;
    float pressure, temperature;

    // Main loop
    while (!terminate) {
        // Read pressure ADC value
        if (read_ads1115(i2c_handle, ADS1115_CONFIG_SINGLE_ENDED_AIN0, &pressure_adc) != 0) {
            fprintf(stderr, "Error reading pressure ADC, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Read temperature ADC value
        if (read_ads1115(i2c_handle, ADS1115_CONFIG_SINGLE_ENDED_AIN1, &temperature_adc) != 0) {
            fprintf(stderr, "Error reading temperature ADC, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Convert ADC values to pressure and temperature
        pressure = adc_to_pressure(pressure_adc);
        temperature = adc_to_temperature(temperature_adc);

        // Control LED
        control_led(pressure);

        // Print pressure and temperature
        printf("Pressure: %.2f kPa, Temperature: %.2f °C\n", pressure, temperature);

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

