    signal(SIGTERM, signal_handler);

    if (setup() != 0) {
        return 1;
    }

    fprintf(stderr, "Methane monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = read_mcp3008(config.mcp3008_channel);
        if (adc_value >= 0) {
            float ppm = adc_to_ppm(adc_value);
            log_data(adc_value, ppm);
            check_alarm(ppm);
        } else {
            fprintf(stderr, "Error: Failed to read ADC value\n");
        }

        sleep(1);
    }

    cleanup();
    fprintf(stderr, "Methane monitoring stopped.\n");
    return 0;
}

