// Function to initialize the I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }

    // Configure ADS1115 for single-ended AIN0, +/-4.096V, 128 SPS, single-shot mode
    ads1115_config_t config;
    config.config = 0x4003; // Single-ended AIN0, +/-4.096V, 128 SPS, single-shot mode

    char buf[3];
    buf[0] = ADS1115_CONFIG_REG;
    buf[1] = (config.config >> 8) & 0xFF;
    buf[2] = config.config & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to ADS1115 config register: %d\n", result);
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Function to read the ADC value from the ADS1115
int16_t read_adc() {
    char buf[1];
    buf[0] = ADS1115_CONVERSION_REG;

    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to ADS1115 conversion register: %d\n", result);
        return -1;
    }

    char read_buf[2];
    result = i2cReadDevice(i2c_handle, read_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from ADS1115 conversion register: %d\n", result);
        return -1;
    }

    int16_t adc_value = (read_buf[0] << 8) | read_buf[1];
    return adc_value;
}

// Function to convert the ADC value to voltage
float convert_to_voltage(int16_t adc_value) {
    float voltage = (float)adc_value * ADS1115_FULL_SCALE_VOLTAGE / 32768.0;
    return voltage;
}

// Function to convert the voltage to pressure
float convert_to_pressure(float voltage) {
    float pressure = (voltage - SENSOR_OFFSET_VOLTAGE) / SENSOR_SENSITIVITY;
    return pressure;
}

// Function to log the pressure reading to a file
int log_pressure(float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    fprintf(fp, "%s, %.2f kPa\n", timestamp, pressure);
    fclose(fp);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    fprintf(stderr, "Pressure monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int16_t adc_value = read_adc();
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Convert ADC value to voltage
        float voltage = convert_to_voltage(adc_value);

        // Convert voltage to pressure
        float pressure = convert_to_pressure(voltage);

        // Validate pressure range
        if (pressure >= 0.0 && pressure <= 100.0) {
            // Log pressure reading
            if (log_pressure(pressure) != 0) {
                fprintf(stderr, "Error logging pressure reading\n");
            }
        } else {
            fprintf(stderr, "Pressure reading out of range: %.2f kPa\n", pressure);
        }

        // Wait for 1 second
        gpioDelay(1000);
    }

    // Close I2C connection
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    fprintf(stderr, "Pressure monitoring stopped.\n");

    return 0;
}

