#include <math.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define MCP3008_CHANNEL_HUMIDITY 0
#define MCP3008_CHANNEL_TEMPERATURE 1
#define HUMIDITY_SUPPLY_VOLTAGE 5.0
#define HUMIDITY_TRANSFER_FUNCTION_SLOPE 0.0315
#define HUMIDITY_TRANSFER_FUNCTION_INTERCEPT 0.824
#define TEMPERATURE_BETA 3950.0
#define TEMPERATURE_R0 10000.0
#define TEMPERATURE_RREF 10000.0 // Reference resistor value
#define TEMPERATURE_VREF 3.3 // Reference voltage for ADC
#define HUMIDITY_THRESHOLD 80.0
#define LOG_FILE "humidity_log.txt"
#define EMAIL_RECIPIENT "recipient@example.com" // Replace with your email

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float humidity;
    float temperature;
} SensorData;

// Function prototypes
int initialize_pigpio();
int initialize_spi();
int read_mcp3008(int channel);
float calculate_humidity(int adc_value);
float calculate_temperature(int adc_value);
void send_email_alert(float humidity);
void log_data(float humidity, float temperature);
void signal_handler(int signal);
void cleanup();

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to calculate humidity from ADC value
float calculate_humidity(int adc_value) {
    float voltage = (float)adc_value / 1023.0 * HUMIDITY_SUPPLY_VOLTAGE;
    float humidity = (voltage - HUMIDITY_TRANSFER_FUNCTION_INTERCEPT) / HUMIDITY_TRANSFER_FUNCTION_SLOPE;
    return humidity;
}

// Function to calculate temperature from ADC value
float calculate_temperature(int adc_value) {
    float voltage = (float)adc_value / 1023.0 * TEMPERATURE_VREF;
    float resistance = (TEMPERATURE_VREF / voltage - 1) * TEMPERATURE_RREF;
    float temperature = 1.0 / (TEMPERATURE_BETA / (log(resistance / TEMPERATURE_R0) + log(TEMPERATURE_R0) / TEMPERATURE_BETA) + 1.0 / 298.15) - 273.15;
    return temperature;
}

// Function to send email alert
void send_email_alert(float humidity) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tstruct);

    char command[256];
    snprintf(command, sizeof(command), "echo \"Subject: Humidity Alert\n\nHumidity exceeded threshold at %s: %.2f%%\" | ssmtp %s", timestamp, humidity, EMAIL_RECIPIENT);
    int result = system(command);
    if (result == -1) {
        fprintf(stderr, "Error sending email\n");
    }
}

// Function to log data to file
void log_data(float humidity, float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tstruct);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, humidity, temperature);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    spiClose(spi_handle);
    gpioTerminate();
    fprintf(stderr, "Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC values
        int humidity_adc = read_mcp3008(MCP3008_CHANNEL_HUMIDITY);
        int temperature_adc = read_mcp3008(MCP3008_CHANNEL_TEMPERATURE);

        if (humidity_adc == -1 || temperature_adc == -1) {
            fprintf(stderr, "Error reading ADC values, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Calculate humidity and temperature
        float humidity = calculate_humidity(humidity_adc);
        float temperature = calculate_temperature(temperature_adc);

        // Log data
        log_data(humidity, temperature);

        // Check humidity threshold and send email alert if necessary
        if (humidity > HUMIDITY_THRESHOLD) {
            send_email_alert(humidity);
        }

        // Print data to console
        printf("Humidity: %.2f%%, Temperature: %.2f°C\n", humidity, temperature);

        // Wait before next reading
        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

