#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3208_CHANNEL 0
#define VREF 3.3
#define LOG_FILE "temperature_log.csv"

// Global variables (to be minimized, but needed for signal handling)
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *cs_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_open(const char *device);
int spi_configure(int fd);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int spi_close(int fd);
int gpio_export(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_set_value(int pin, int value);
int gpio_get_value(int pin);
int read_mcp3208(int spi_fd, int channel);
float adc_to_voltage(int adc_value, float vref);
float voltage_to_celsius(float voltage);
int log_temperature(float temperature);
void signal_handler(int sig);

// SPI functions
int spi_open(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }
    return fd;
}

int spi_configure(int fd) {
    int mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        return -1;
    }

    int bits = SPI_BITS_PER_WORD;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting SPI bits per word");
        return -1;
    }

    int speed = SPI_SPEED;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI max speed");
        return -1;
    }

    return 0;
}

int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

int spi_close(int fd) {
    if (close(fd) < 0) {
        perror("Error closing SPI device");
        return -1;
    }
    return 0;
}

// GPIO functions
int gpio_export(int pin) {
    char buffer[3];
    ssize_t bytes_written;
    int fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        perror("Error opening /sys/class/gpio/export");
        return -1;
    }

    int len = snprintf(buffer, sizeof(buffer), "%d", pin);
    bytes_written = write(fd, buffer, len);
    close(fd);
    if (bytes_written < 0) {
        perror("Error writing to /sys/class/gpio/export");
        return -1;
    }
    return 0;
}

int gpio_set_direction(int pin, const char *direction) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Error opening GPIO direction file");
        return -1;
    }

    if (write(fd, direction, strlen(direction)) < 0) {
        perror("Error writing to GPIO direction file");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

int gpio_set_value(int pin, int value) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Error opening GPIO value file");
        return -1;
    }

    if (write(fd, value ? "1" : "0", 1) < 0) {
        perror("Error writing to GPIO value file");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

int gpio_get_value(int pin) {
    char path[64];
    char value_str[3];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    fd = open(path, O_RDONLY);
    if (fd < 0) {
        perror("Error opening GPIO value file");
        return -1;
    }

    if (read(fd, value_str, 3) < 0) {
        perror("Error reading GPIO value file");
        close(fd);
        return -1;
    }

    close(fd);
    return atoi(value_str);
}

// MCP3208 read function
int read_mcp3208(int spi_fd, int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // MCP3208 command: start bit (1), single-ended mode (1), channel (3 bits), don't care (3 bits)
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended, channel select
    tx_buf[2] = 0x00; // Don't care

    if (spi_transfer(spi_fd, tx_buf, rx_buf, 3) < 0) {
        fprintf(stderr, "SPI transfer failed in read_mcp3208\n");
        return -1;
    }

    // Extract the 12-bit ADC value from the response
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Conversion functions
float adc_to_voltage(int adc_value, float vref) {
    return ((float)adc_value / 4095.0) * vref;
}

float voltage_to_celsius(float voltage) {
    return (voltage - 0.5) / 0.01;
}

// Logging function
int log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a+");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }

        // Check if the file is empty and write the header if it is
        fseek(log_file, 0, SEEK_END);
        long file_size = ftell(log_file);
        if (file_size == 0) {
            fprintf(log_file, "timestamp,temperature_celsius\n");
        }
        fseek(log_file, 0, SEEK_END);
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = spi_open(SPI_DEVICE);
    if (spi_fd < 0) {
        return 1;
    }

    if (spi_configure(spi_fd) < 0) {
        spi_close(spi_fd);
        return 1;
