        gpiod_chip_close(gpio_chip);
        spi_close(spi_fd);
        return 1;
    }

    if (gpiod_line_request_output(cs_line, "temperature_sensor", 0) < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(gpio_chip);
        spi_close(spi_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
