            // Set CS high before exiting
            gpiod_line_set_value(cs_line, 1);
            break;
        }

        // Set CS high
        if (gpiod_line_set_value(cs_line, 1) < 0) {
            perror("Error setting CS high");
            break;
        }

        // Convert ADC value to voltage and temperature
        float voltage = adc_to_voltage(adc_value, VREF);
        float temperature = voltage_to_celsius(voltage);

        // Validate temperature range
        if (temperature < -40.0 || temperature > 125.0) {
            fprintf(stderr, "Temperature out of range: %.2f\n", temperature);
        } else {
            // Log temperature
            if (log_temperature(temperature) < 0) {
                fprintf(stderr, "Error logging temperature\n");
            }
        }

        // Wait 1 second
        sleep(1);
    }

    // Cleanup
    if (cs_line) {
        gpiod_line_release(cs_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
