#include <signal.h>
#include <string.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define CS_PIN 8
#define SUPPLY_VOLTAGE 3.3
#define ZERO_G_VOLTAGE 1.65
#define SENSITIVITY 0.300 // 300 mV/g
#define IMPACT_THRESHOLD 2.0
#define LOG_FILE "impact_log.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_acceleration(float voltage);
float calculate_magnitude(float x, float y, float z);
void log_data(int x, int y, int z, float magnitude);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(CS_PIN, 0); // Assert CS
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(CS_PIN, 1); // De-assert CS

    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return ((float)adc_value / 1023.0) * SUPPLY_VOLTAGE;
}

// Function to convert voltage to acceleration (g)
float voltage_to_acceleration(float voltage) {
    return (voltage - ZERO_G_VOLTAGE) / SENSITIVITY;
}

// Function to calculate acceleration magnitude
float calculate_magnitude(float x, float y, float z) {
    return sqrt(x * x + y * y + z * z);
}

// Function to log data to file
void log_data(int x, int y, int z, float magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d,%.3f", timestamp, x, y, z, magnitude);
    if (magnitude > IMPACT_THRESHOLD) {
        fprintf(log_file, ",IMPACT DETECTED\n");
    } else {
        fprintf(log_file, "\n");
    }
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed with code %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set CS pin as output
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // De-assert CS initially

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC values
        int x_adc = read_mcp3008(0);
        int y_adc = read_mcp3008(1);
        int z_adc = read_mcp3008(2);

        if (x_adc == -1 || y_adc == -1 || z_adc == -1) {
            fprintf(stderr, "Error: Failed to read ADC values\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC values to voltages
        float x_voltage = adc_to_voltage(x_adc);
        float y_voltage = adc_to_voltage(y_adc);
        float z_voltage = adc_to_voltage(z_adc);

        // Convert voltages to accelerations
        float x_acceleration = voltage_to_acceleration(x_voltage);
        float y_acceleration = voltage_to_acceleration(y_voltage);
        float z_acceleration = voltage_to_acceleration(z_voltage);

        // Calculate acceleration magnitude
        float magnitude = calculate_magnitude(x_acceleration, y_acceleration, z_acceleration);

        // Log data
        log_data(x_adc, y_adc, z_adc, magnitude);

        // Delay for 10 ms (100 Hz sampling rate)
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

