#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define SPI_MODE 0
#define ADC_CHANNEL 0
#define FLOW_MIN 0.0
#define FLOW_MAX 5.0
#define ADC_MIN 0
#define ADC_MAX 1023
#define VOLTAGE_MIN 0.0
#define VOLTAGE_MAX 3.3
#define LOG_FILE "flow_log.csv"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_adc(int channel);
float adc_to_flow(int adc_value);
void log_flow(float flow_rate);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_baud;
    int spi_mode;
    int adc_channel;
    float flow_min;
    float flow_max;
    int adc_min;
    int adc_max;
    float voltage_min;
    float voltage_max;
    char *log_file;
} config_t;

config_t config = {
    SPI_CHANNEL,
    SPI_BAUD,
    SPI_MODE,
    ADC_CHANNEL,
    FLOW_MIN,
    FLOW_MAX,
    ADC_MIN,
    ADC_MAX,
    VOLTAGE_MIN,
    VOLTAGE_MAX,
    LOG_FILE
};

// Function to read ADC value from MCP3008
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to convert ADC value to flow rate
float adc_to_flow(int adc_value) {
    // Linear scaling: 0-3.3V -> 0-5.0 L/min
    float flow_rate = ((float)adc_value / ADC_MAX) * (FLOW_MAX - FLOW_MIN) + FLOW_MIN;
    return flow_rate;
}

// Function to log flow rate to file
void log_flow(float flow_rate) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%06ld", ts.tv_nsec / 1000);

    fprintf(log_file, "%s,%.2f\n", timestamp, flow_rate);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(config.spi_channel, config.spi_baud, config.spi_mode);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed with code %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file %s\n", config.log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    return 0;
}

// Cleanup function
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    if (initialize()) {
        return 1;
    }

    fprintf(stderr, "Monitoring flow rate...\n");

    while (!terminate) {
        // Read ADC value
        int adc_value = read_adc(config.adc_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Try again
        }

        // Convert ADC value to flow rate
        float flow_rate = adc_to_flow(adc_value);

        // Validate flow rate
        if (flow_rate < config.flow_min || flow_rate > config.flow_max) {
            fprintf(stderr, "Error: Flow rate out of range: %.2f L/min\n", flow_rate);
        } else {
            // Log flow rate
            log_flow(flow_rate);
        }

        // Wait for 1 second
        time_sleep(1.0);
    }

    cleanup();
    fprintf(stderr, "Program terminated.\n");
    return 0;
}

