int i2c_fd = -1;
FILE *log_file = NULL;

// Structure to hold calibration data
typedef struct {
    int32_t c0;
    int32_t c1;
    int32_t c00;
    int32_t c10;
    int32_t c01;
    int32_t c11;
    int32_t c20;
    int32_t c21;
    int32_t c30;
} calibration_data_t;

calibration_data_t calibration;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

// Function to initialize the I2C bus
int init_i2c(int bus) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    return fd;
}

// Function to write a byte to the I2C device
int write_i2c(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// Function to read a block of data from the I2C device
int read_i2c(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing register address");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// Function to read calibration data from the sensor
int read_calibration_data(int fd, calibration_data_t *cal) {
    uint8_t data[24];
    if (read_i2c(fd, 0x31, data, 24) != 0) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    cal->c0 = (int32_t)((uint32_t)data[0] << 8 | data[1]);
    cal->c1 = (int32_t)((uint32_t)data[2] << 8 | data[3]);
    cal->c00 = (int32_t)((uint32_t)data[4] << 8 | data[5]);
    cal->c10 = (int32_t)((uint32_t)data[6] << 8 | data[7]);
    cal->c01 = (int32_t)((uint32_t)data[8] << 8 | data[9]);
    cal->c11 = (int32_t)((uint32_t)data[10] << 8 | data[11]);
    cal->c20 = (int32_t)((uint32_t)data[12] << 8 | data[13]);
    cal->c21 = (int32_t)((uint32_t)data[14] << 8 | data[15]);
    cal->c30 = (int32_t)((uint32_t)data[16] << 8 | data[17]);

    return 0;
}

// Function to trigger a measurement
int trigger_measurement(int fd) {
    uint8_t msb = (MEASUREMENT_COMMAND >> 8) & 0xFF;
    uint8_t lsb = MEASUREMENT_COMMAND & 0xFF;
    if (write_i2c(fd, 0x68, msb) != 0) return -1;
    if (write_i2c(fd, 0x45, lsb) != 0) return -1;
    return 0;
}

// Function to read raw sensor data
int read_sensor_data(int fd, int32_t *pressure, int32_t *temperature) {
    uint8_t data[6];
    if (read_i2c(fd, 0x00, data, 6) != 0) {
        fprintf(stderr, "Error reading sensor data\n");
        return -1;
    }

    *pressure = (int32_t)((uint32_t)data[0] << 16 | (uint32_t)data[1] << 8 | data[2]);
    *temperature = (int32_t)((uint32_t)data[3] << 16 | (uint32_t)data[4] << 8 | data[5]);

    return 0;
}

