#include <math.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL_0 0
#define MCP3008_CHANNEL_1 1
#define NUM_SAMPLES 1024

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold audio data
typedef struct {
    int left;
    int right;
} AudioSample;

// Function prototypes
int initialize_pigpio();
int initialize_spi();
int read_mcp3008(int channel);
AudioSample sample_audio();
AudioSample apply_noise_cancellation(AudioSample sample1, AudioSample sample2, float gain);
void output_csv(AudioSample sample);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract 10-bit ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Sample audio from both microphones
AudioSample sample_audio() {
    AudioSample sample;
    int left_value = read_mcp3008(MCP3008_CHANNEL_0);
    int right_value = read_mcp3008(MCP3008_CHANNEL_1);

    if (left_value < 0 || right_value < 0) {
        sample.left = 0; // Set to 0 in case of error
        sample.right = 0;
        return sample;
    }

    sample.left = left_value;
    sample.right = right_value;
    return sample;
}

// Apply noise cancellation algorithm
AudioSample apply_noise_cancellation(AudioSample sample1, AudioSample sample2, float gain) {
    AudioSample cancelled_sample;
    cancelled_sample.left = sample1.left - (int)(gain * sample2.left);
    cancelled_sample.right = sample1.right - (int)(gain * sample2.right);
    return cancelled_sample;
}

// Output audio data to CSV format
void output_csv(AudioSample sample) {
    printf("%d,%d\n", sample.left, sample.right);
}

// Cleanup resources
void cleanup() {
    spiClose(spi_handle);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    float gain = 1.0; // Default gain

    // Parse command-line arguments
    if (argc > 1) {
        gain = atof(argv[1]);
        if (gain <= 0) {
            fprintf(stderr, "Invalid gain value. Using default gain of 1.0\n");
            gain = 1.0;
        }
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    printf("Audio sampling started. Press Ctrl+C to terminate.\n");

    // Main loop
    while (!terminate) {
        AudioSample sample1 = sample_audio();
        AudioSample sample2 = sample_audio();

        if (sample1.left == 0 && sample1.right == 0 && sample2.left == 0 && sample2.right == 0) {
            // Check for sensor absence or bus error
            fprintf(stderr, "No audio data received. Check microphone connections.\n");
            gpioDelay(100000); // Wait 0.1 seconds before retrying
            continue;
        }

        AudioSample cancelled_sample = apply_noise_cancellation(sample1, sample2, gain);
        output_csv(cancelled_sample);
        gpioDelay(1000); // Delay for 1 ms (adjust as needed)
    }

    // Cleanup and exit
    cleanup();
    printf("Audio sampling terminated.\n");
    return 0;
}

