// Define MCP3008 channel
#define MCP3008_CHANNEL 0

// Define log file name
#define LOG_FILE "moisture_log.txt"

// Global variables for SPI handle and program state
int spi_handle = -1;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
char* get_iso8601_timestamp();
int log_moisture_reading(const char* timestamp, int reading);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    // Construct SPI message (MCP3008 datasheet)
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC reading (10 bits)
    int adc_reading = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_reading;
}

// Function to get ISO 8601 timestamp
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for timestamp

    if (timestamp == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for timestamp\n");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    return timestamp;
}

// Function to log moisture reading to file
int log_moisture_reading(const char* timestamp, int reading) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open log file: %s\n", LOG_FILE);
        return -1;
    }

    fprintf(fp, "%s,%d\n", timestamp, reading);
    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read moisture sensor value
        int moisture_reading = read_mcp3008(MCP3008_CHANNEL);
        if (moisture_reading < 0) {
            fprintf(stderr, "Error: Failed to read moisture sensor\n");
        } else {
            // Get timestamp
            char* timestamp = get_iso8601_timestamp();
            if (timestamp != NULL) {
                // Log moisture reading
                if (log_moisture_reading(timestamp, moisture_reading) != 0) {
                    fprintf(stderr, "Error: Failed to log moisture reading\n");
                }
                free(timestamp); // Free allocated memory
            } else {
                fprintf(stderr, "Error: Failed to get timestamp\n");
            }
        }

        // Wait for 60 seconds
        gpioDelay(60000000); // 60 seconds in microseconds
    }

    // Close SPI channel and terminate pigpio library
    spiClose(spi_handle);
    gpioTerminate();

    printf("Soil moisture monitoring stopped.\n");

    return 0;
}

