#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define BUZZER_GPIO 18
#define LOG_FILE "flame_log.txt"
#define AMBIENT_TEMP_FILE "ambient_temp.txt"
#define SAMPLE_INTERVAL_MS 500
#define MAX_RETRIES 3

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *buzzer_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device);
int spi_transfer(int fd, unsigned char *tx_buf, unsigned char *rx_buf, int len);
int read_mcp3008(int fd, int channel);
float read_temperature(const char *filename);
float compensate_voltage(float voltage, float temperature);
int detect_flame(float compensated_voltage);
int gpio_init(int gpio_pin);
int gpio_set_value(struct gpiod_line *line, int value);
int gpio_cleanup(struct gpiod_chip *chip, struct gpiod_line *line);
int log_data(FILE *fp, int raw_adc, float voltage, float compensated_voltage, float temperature, int flame_detected);
void signal_handler(int sig);

// SPI Initialization
int spi_init(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", device, strerror(errno));
        return -1;
    }

    // Set SPI mode (CPOL=0, CPHA=0)
    unsigned char mode = 0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    // Set SPI speed (1 MHz)
    unsigned int speed = 1000000; // 1 MHz
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// SPI Transfer
int spi_transfer(int fd, unsigned char *tx_buf, unsigned char *rx_buf, int len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = 1000000, // 1 MHz
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read MCP3008 Channel
int read_mcp3008(int fd, int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    int adc_value = -1;
    int retries = 0;

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended, channel select
    tx_buf[2] = 0x00; // Dummy byte

    while (retries < MAX_RETRIES) {
        if (spi_transfer(fd, tx_buf, rx_buf, 3) == 0) {
            // Extract ADC value (10 bits)
            adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
            if (adc_value >= 0 && adc_value <= 1023) {
                return adc_value;
            } else {
                fprintf(stderr, "ADC value out of range: %d\n", adc_value);
                fprintf(log_file, "ADC value out of range: %d\n", adc_value);
            }
        } else {
            fprintf(stderr, "SPI transfer failed, retrying (%d/%d)\n", retries + 1, MAX_RETRIES);
            fprintf(log_file, "SPI transfer failed, retrying (%d/%d)\n", retries + 1, MAX_RETRIES);
        }
        retries++;
        usleep(10000); // 10ms delay
    }

    fprintf(stderr, "Failed to read MCP3008 after %d retries\n", MAX_RETRIES);
    fprintf(log_file, "Failed to read MCP3008 after %d retries\n", MAX_RETRIES);
    return -1; // Indicate failure
}

// Read Temperature from File
float read_temperature(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening temperature file %s: %s\n", filename, strerror(errno));
        fprintf(log_file, "Error opening temperature file %s: %s\n", filename, strerror(errno));
        return 25.0; // Default temperature
    }

    float temperature;
    if (fscanf(fp, "%f", &temperature) != 1) {
        fprintf(stderr, "Error reading temperature from file %s\n", filename);
        fprintf(log_file, "Error reading temperature from file %s\n", filename);
        fclose(fp);
        return 25.0; // Default temperature
    }

    fclose(fp);
    return temperature;
}

// Compensate Voltage
float compensate_voltage(float voltage, float temperature) {
    return voltage + (temperature - 25.0) * 0.001;
}

// Detect Flame
int detect_flame(float compensated_voltage) {
    return (compensated_voltage > 1.0) ? 1 : 0;
}

// GPIO Initialization
int gpio_init(int gpio_pin) {
    struct gpiod_line_request_config config;

    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        fprintf(log_file, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    buzzer_line = gpiod_chip_get_line(gpio_chip, gpio_pin);
    if (!buzzer_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", gpio_pin, strerror(errno));
        fprintf(log_file, "Error getting GPIO line %d: %s\n", gpio_pin, strerror(errno));
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    memset(&config, 0, sizeof(config));
    config.consumer = "buzzer";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(buzzer_line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d: %s\n", gpio_pin, strerror(errno));
        fprintf(log_file, "Error requesting GPIO line %d: %s\n", gpio_pin, strerror(errno));
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// GPIO Set Value
int gpio_set_value(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        fprintf(stderr, "Error setting GPIO value: %s\n", strerror(errno));
        fprintf(log_file, "Error setting GPIO value: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// GPIO Cleanup
int gpio_cleanup(struct gpiod_chip *chip, struct gpiod_line *line) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return 0;
}

// Log Data
int log_data(FILE *fp, int raw_adc, float voltage, float compensated_voltage, float temperature, int flame_detected) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%d,%.3f,%.3f,%.3f,%d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            raw_adc, voltage, compensated_voltage, temperature, flame_detected);
    fflush(fp);
    return 0;
}

// Signal Handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    fprintf(log_file, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize signal handling
    signal(SIGINT, signal_handler);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        return 1;
    }

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        fprintf(log_file, "SPI initialization failed\n");
        fclose(log_file);
        return 1;
    }

    // Initialize GPIO
    if (gpio_init(BUZZER_GPIO) < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        fprintf(log_file, "GPIO initialization failed\n");
        close(spi_fd);
        fclose(log_file);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read temperature
        float temperature = read_temperature(AMBIENT_TEMP_FILE);

        // Read ADC value
        int raw_adc = read_mcp3008(spi_fd, 0);
        if (raw_adc < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            fprintf(log_file, "Failed to read ADC value\n");
            gpio_set_value(buzzer_line, 0); // Turn off buzzer
            continue; // Skip to next iteration
        }

        // Calculate voltage
        float voltage = (float)raw_adc / 1023.0 * 3.3;

        // Compensate voltage
        float compensated_voltage = compensate_voltage(voltage, temperature);

        // Detect flame
        int flame_detected = detect_flame(compensated_voltage);

        // Control buzzer
        if (flame_detected) {
            gpio_set_value(buzzer_line, 1); // Turn on buzzer
        } else {
            gpio_set_value(buzzer_line, 0); // Turn off buzzer
        }

        // Log data
        log_data(log_file, raw_adc, voltage, compensated_voltage, temperature, flame_detected);

        // Wait
        usleep(SAMPLE_INTERVAL_MS * 1000); // Convert ms to us
    }

    // Cleanup
    gpio_set_value(buzzer_line, 0); // Turn off buzzer
    gpio_cleanup(gpio_chip, buzzer_line);
    close(spi_fd);
    fclose(log_file);

    fprintf(stderr, "Program terminated gracefully.\n");
    return 0;
}

