#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define LED_GPIO 17
#define WATER_LEVEL_THRESHOLD_HIGH 75.0
#define WATER_LEVEL_THRESHOLD_LOW 70.0
#define JSON_FILE "water_levels.json"

// Global variables
int spi_handle;
FILE *json_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_percentage(int adc_value);
char* get_iso8601_timestamp();
int log_water_level(float percentage);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = 0x80 | (channel << 4); // Single-ended mode, channel selection
    tx_buffer[2] = 0x00; // Dummy byte

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result < 0) {
        fprintf(stderr, "Error: SPI transfer failed: %s\n", pigpio_error(result));
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) | rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to percentage
float convert_to_percentage(int adc_value) {
    return (float)adc_value / 1023.0 * 100.0;
}

// Function to get ISO 8601 timestamp with milliseconds
char* get_iso8601_timestamp() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    time_t t = ts.tv_sec;
    struct tm *tm_info = localtime(&t);

    char *timestamp = malloc(30 * sizeof(char));
    if (timestamp == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for timestamp\n");
        return NULL;
    }

    strftime(timestamp, 20, "%Y-%m-%dT%H:%M:%S", tm_info);
    snprintf(timestamp + 19, 11, ".%03ldZ", ts.tv_nsec / 1000000);

    return timestamp;
}

// Function to log water level to JSON file
int log_water_level(float percentage) {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        return -1;
    }

    fprintf(json_file, "{\"timestamp\": \"%s\", \"water_level\": %.2f}\n", timestamp, percentage);
    fflush(json_file);
    free(timestamp);
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %s\n", pigpio_error(spi_handle));
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Open JSON file
    json_file = fopen(JSON_FILE, "a+");
    if (json_file == NULL) {
        fprintf(stderr, "Error: Failed to open JSON file: %s\n", JSON_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is empty, if so, write the opening bracket
    fseek(json_file, 0, SEEK_END);
    long file_size = ftell(json_file);
    if (file_size == 0) {
        fprintf(json_file, "[");
    } else {
        // If the file is not empty, go back one character to overwrite the closing bracket
        fseek(json_file, -1, SEEK_END);
        fprintf(json_file, ",");
    }
    fflush(json_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            gpioDelay(500000); // Wait 0.5 seconds before retrying
            continue;
        }

        // Convert to percentage
        float water_level = convert_to_percentage(adc_value);

        // Log water level
        if (log_water_level(water_level) != 0) {
            fprintf(stderr, "Error: Failed to log water level\n");
        }

        // Control LED with hysteresis
        if (water_level > WATER_LEVEL_THRESHOLD_HIGH) {
            gpioWrite(LED_GPIO, 1); // Turn LED ON
        } else if (water_level < WATER_LEVEL_THRESHOLD_LOW) {
            gpioWrite(LED_GPIO, 0); // Turn LED OFF
        }

        // Print water level to stdout
        printf("Water Level: %.2f%%\n", water_level);

        // Wait 5 seconds
        gpioDelay(5000000);
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioWrite(LED_GPIO, 0); // Turn LED OFF
    spiClose(spi_handle);
    gpioTerminate();

    // Close JSON file and add the closing bracket
    fseek(json_file, -1, SEEK_END);
    fprintf(json_file, "]");
    fclose(json_file);

    printf("Exiting.\n");
    return 0;
}

