#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// Configuration structure
typedef struct {
    int spi_channel;
    int adc_channel;
    int min_raw_value;
    int max_raw_value;
    int moisture_threshold;
    int logging_frequency;
    char *recipient_email;
    char *msmtp_config_path;
} Config;

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_config(int argc, char *argv[], Config *config);
int initialize_pigpio();
int initialize_spi(int channel, int baud_rate);
int read_adc(int spi_handle, int channel);
float calculate_moisture_percentage(int raw_value, int min_raw, int max_raw);
int log_data(FILE *log_file, float moisture_percentage);
int send_email_alert(const char *email_body, const char *recipient_email, const char *msmtp_config_path);
void signal_handler(int signal);
void cleanup();

// Function to read configuration from command-line arguments
int read_config(int argc, char *argv[], Config *config) {
    if (argc != 9) {
        fprintf(stderr, "Usage: %s <spi_channel> <adc_channel> <min_raw_value> <max_raw_value> <moisture_threshold> <logging_frequency> <recipient_email> <msmtp_config_path>\n", argv[0]);
        return 1;
    }

    config->spi_channel = atoi(argv[1]);
    config->adc_channel = atoi(argv[2]);
    config->min_raw_value = atoi(argv[3]);
    config->max_raw_value = atoi(argv[4]);
    config->moisture_threshold = atoi(argv[5]);
    config->logging_frequency = atoi(argv[6]);
    config->recipient_email = strdup(argv[7]); // Duplicate the string to avoid issues with argv
    config->msmtp_config_path = strdup(argv[8]); // Duplicate the string to avoid issues with argv

    if (config->recipient_email == NULL || config->msmtp_config_path == NULL) {
        perror("strdup failed");
        return 1;
    }

    return 0;
}

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

