#define CS_PIN 8 // GPIO8 (CE0)
#define VREF 3.3f
#define SAMPLE_RATE 1 // seconds
#define NUM_CHANNELS 4

// Global variables
static volatile int keep_running = 1;
static FILE *log_file = NULL;
static struct gpiod_line *cs_line = NULL;
static int spi_fd = -1;

// Function prototypes
int spi_init(void);
int read_mcp3008(int channel);
float convert_to_voltage(int adc_value);
int log_data(float voltages[NUM_CHANNELS]);
void signal_handler(int sig);
void cleanup(void);

// Structure to hold configuration data
typedef struct {
    const char *spi_device;
    int cs_gpio;
    float vref;
    int sample_rate;
    int num_channels;
} config_t;

// SPI Initialization
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    int mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Configure SPI speed
    int speed = 1000000; // 1 MHz
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = 1000000; // 1 MHz
    transfer[0].bits_per_word = 8;

    // Assert CS low
    if (gpiod_line_set_value(cs_line, 0) < 0) {
        perror("Error setting CS low");
        return -1;
    }

    // Transfer data
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error during SPI transfer");
        // De-assert CS high
        if (gpiod_line_set_value(cs_line, 1) < 0) {
            perror("Error setting CS high after transfer error");
        }
        return -1;
    }

    // De-assert CS high
    if (gpiod_line_set_value(cs_line, 1) < 0) {
        perror("Error setting CS high");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

// Convert ADC value to voltage
float convert_to_voltage(int adc_value) {
    return ((float)adc_value / 1023.0f) * VREF;
}

// Log data to CSV file
int log_data(float voltages[NUM_CHANNELS]) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s", timestamp);
    for (int i = 0; i < NUM_CHANNELS; i++) {
        fprintf(log_file, ",%.3f", voltages[i]);
    }
    fprintf(log_file, "\n");
    fflush(log_file); // Ensure data is written immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("Caught signal %d, exiting...\n", sig);
    keep_running = 0;
}

// Cleanup resources
void cleanup(void) {
    printf("Cleaning up resources...\n");

    if (log_file != NULL) {
        fclose(log_file);
    }

    if (cs_line != NULL) {
        gpiod_line_release(cs_line);
    }

    if (spi_fd != -1) {
        close(spi_fd);
    }

    printf("Cleanup complete.\n");
}

int main(void) {
    config_t config = {
        .spi_device = SPI_DEVICE,
        .cs_gpio = CS_PIN,
        .vref = VREF,
        .sample_rate = SAMPLE_RATE,
        .num_channels = NUM_CHANNELS
    };

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize libgpiod
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    cs_line = gpiod_chip_get_line(chip, config.cs_gpio);
    if (!cs_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(cs_line, "spi_cs", 1) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(chip);
        return 1;
    }

    // Initialize SPI
    if (spi_init() < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("environmental_data.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Main loop
    float voltages[NUM_CHANNELS];
    while (keep_running) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int adc_value = read_mcp3008(i);
            if (adc_value < 0) {
                fprintf(stderr, "Error reading channel %d, retrying...\n", i);
                sleep(1); // Wait before retrying
                continue; // Skip to the next channel
            }
            voltages[i] = convert_to_voltage(adc_value);
        }

        if (log_data(voltages) < 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        sleep(config.sample_rate);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

