    time_t timestamp;
    int moisture_level;
    int pump_state;
} log_buffer[BUFFER_SIZE];

// Function prototypes
int read_mcp3008(int channel);
void control_pump(int state);
void sample_moisture();
void print_log();
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_data[3];
    spi_data[0] = 0x01; // Start bit
    spi_data[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_data[2] = 0x00;

    char rx_buffer[3];

    int result = spiXfer(spi_handle, spi_data, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to control the water pump
void control_pump(int state) {
    if (gpioWrite(PUMP_GPIO, state) != 0) {
        fprintf(stderr, "Error: Failed to write to GPIO %d\n", PUMP_GPIO);
    }
    pump_state = state;
}

// Function to sample moisture and control pump
void sample_moisture() {
    int moisture_level = read_mcp3008(0);
    if (moisture_level < 0) {
        fprintf(stderr, "Error: Failed to read moisture level\n");
        return;
    }

    // Hysteresis control
    if (moisture_level < MOISTURE_LOW_THRESHOLD && pump_state == 0) {
        control_pump(1); // Turn pump on
    } else if (moisture_level > MOISTURE_HIGH_THRESHOLD && pump_state == 1) {
        control_pump(0); // Turn pump off
    }

    // Log data
    time(&log_buffer[buffer_index].timestamp);
    log_buffer[buffer_index].moisture_level = moisture_level;
    log_buffer[buffer_index].pump_state = pump_state;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;

    printf("Moisture Level: %d, Pump State: %d\n", moisture_level, pump_state);
}

// Function to print the log buffer
void print_log() {
    printf("\n--- Log Buffer ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        struct tm *timeinfo = localtime(&log_buffer[i].timestamp);
        char timestamp_str[20];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("[%s] Moisture: %d, Pump: %d\n", timestamp_str, log_buffer[i].moisture_level, log_buffer[i].pump_state);
    }
    printf("--- End of Log ---\n\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    control_pump(0); // Turn pump off
    spiClose(spi_handle); // Close SPI
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output for pump control
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up timer function
    if (gpioSetTimerFuncEx(0, SAMPLE_INTERVAL * 1000, sample_moisture, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set timer function\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop (keep the program running until a signal is received)
    while (1) {
        print_log();
        gpioDelay(1000); // Sleep for 1 second
    }

    return 0;
}

