#define REG_MODE_CONFIG 0x06
#define REG_SPO2_CONFIG 0x08
#define REG_LED1_PA 0x09
#define REG_LED2_PA 0x0A
#define REG_PILOT_PA 0x0B
#define REG_MULTI_LED_CTRL1 0x11
#define REG_MULTI_LED_CTRL2 0x12
#define REG_TEMP_INTR 0x1F
#define REG_TEMP_FRAC 0x20
#define REG_TEMP_VALUE 0x21
#define REG_PROX_INT_THRESH 0x30
#define REG_REV_ID 0xFE
#define REG_PART_ID 0xFF

// Configuration values
#define SPO2_MODE 0x03
#define SPO2_CONFIG_VALUE 0x27
#define LED_PA_VALUE 0x24

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
