float calculate_spo2(int red, int ir);
int calculate_heart_rate(int *ir_data, int num_samples);
void log_data(float spo2, int heart_rate);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, MAX30102_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize MAX30102 sensor
int init_max30102() {
    // Verify sensor presence by reading Part ID
    int part_id = read_register(REG_PART_ID);
    if (part_id != 0x15) {
        fprintf(stderr, "Error: Invalid Part ID (0x%02X). Check I2C connection.\n", part_id);
        return -1;
    }

    // Reset the sensor
    if (write_register(REG_MODE_CONFIG, 0x40) < 0) {
        fprintf(stderr, "Error resetting sensor.\n");
        return -1;
