    if (write_register(REG_INTR_ENABLE_1, 0x00) < 0) {
        fprintf(stderr, "Error clearing interrupts.\n");
        return -1;
    }

    // Configure SpO2 mode
    if (write_register(REG_MODE_CONFIG, SPO2_MODE) < 0) {
        fprintf(stderr, "Error configuring SpO2 mode.\n");
        return -1;
    }

    // Set SPO2 configuration
    if (write_register(REG_SPO2_CONFIG, SPO2_CONFIG_VALUE) < 0) {
        fprintf(stderr, "Error setting SPO2 configuration.\n");
        return -1;
    }

    // Set LED pulse amplitudes
    if (write_register(REG_LED1_PA, LED_PA_VALUE) < 0) {
        fprintf(stderr, "Error setting LED1 amplitude.\n");
        return -1;
    }
    if (write_register(REG_LED2_PA, LED_PA_VALUE) < 0) {
        fprintf(stderr, "Error setting LED2 amplitude.\n");
        return -1;
    }

    return 0;
}

