int read_register(int reg) {
    int value = i2cReadByteData(i2c_handle, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, value);
        return -1;
    }
    return value;
}

// Write a single register to the MAX30102
int write_register(int reg, int value) {
    int result = i2cWriteByteData(i2c_handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Read FIFO data (6 bytes: 3 bytes red, 3 bytes IR)
int read_fifo_data(SensorData *data) {
    char buffer[6];
    int result = i2cReadI2CBlockData(i2c_handle, REG_FIFO_DATA, buffer, 6);
    if (result < 0) {
        fprintf(stderr, "Error reading FIFO data: %d\n", result);
        return -1;
    }

    data->red = (buffer[0] << 16 | buffer[1] << 8 | buffer[2]) & 0x3FFFF;
    data->ir = (buffer[3] << 16 | buffer[4] << 8 | buffer[5]) & 0x3FFFF;

    return 0;
}

// Calculate SpO2 using the ratio-of-ratios method
float calculate_spo2(int red, int ir) {
    // Simplified ratio-of-ratios algorithm (replace with a more accurate implementation if needed)
    float ratio = (float)ir / (float)red;
    float spo2 = 110 - 17.5 * ratio; // Example formula, needs calibration

    // Clamp SpO2 value
    if (spo2 < 90) spo2 = 90;
    if (spo2 > 100) spo2 = 100;

    return spo2;
}

// Calculate heart rate using peak detection on the IR signal
int calculate_heart_rate(int *ir_data, int num_samples) {
    if (num_samples < 3) return 0; // Need at least 3 samples for peak detection

    int peaks = 0;
    for (int i = 1; i < num_samples - 1; i++) {
        if (ir_data[i] > ir_data[i - 1] && ir_data[i] > ir_data[i + 1]) {
            peaks++;
        }
    }

    // Estimate heart rate (example: 60-200 BPM range)
    int heart_rate = (peaks * 60) / (num_samples / 10); // Assuming 10Hz sampling rate
    if (heart_rate < 60) heart_rate = 60;
    if (heart_rate > 200) heart_rate = 200;

    return heart_rate;
}

