    if (init_i2c() < 0) {
        cleanup();
        return 1;
    }

    // Initialize MAX30102 sensor
    if (init_max30102() < 0) {
        cleanup();
        return 1;
    }

    printf("MAX30102 initialized successfully.\n");

    // Main loop
    SensorData sensor_data;
    int ir_data[100]; // Buffer for IR data (10Hz * 10 seconds)
    int ir_index = 0;

    while (!terminate) {
        // Read FIFO data
        if (read_fifo_data(&sensor_data) == 0) {
            // Calculate SpO2
            float spo2 = calculate_spo2(sensor_data.red, sensor_data.ir);

            // Store IR data for heart rate calculation
            ir_data[ir_index] = sensor_data.ir;
            ir_index = (ir_index + 1) % 100;

            // Calculate heart rate every 10 seconds
            if (ir_index == 0) {
                int heart_rate = calculate_heart_rate(ir_data, 100);

                // Log data if SpO2 is below threshold or heart rate is above threshold
                if (spo2 < 95 || heart_rate > 100) {
                    log_data(spo2, heart_rate);
                }
            }
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
        }

        gpioDelay(1000); // Sample once per second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

