#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_CE 0
#define SPI_SPEED 1000000 // 1 MHz
#define VREF 3.3
#define CSV_FILE "analog_log.csv"
#define LOG_INTERVAL_MS 500

// Global variables
int spi_handle;
FILE *csv_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_voltage(int adc_value);
void log_data(int channel, float voltage);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure for SPI configuration (optional)
typedef struct {
    int channel;
    int ce;
    int speed;
} spi_config_t;

// Function to initialize the system
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Failed to open CSV file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "Timestamp,Channel,Voltage\n");
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    int count = 0;
    int result = -1;

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) & 0xFF; // Single-ended, channel select
    tx_buf[2] = 0x00; // Dummy byte

    while (count < 3) {
        int spi_result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
        if (spi_result == 3) {
            // Extract ADC value
            result = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
            break; // Exit loop on success
        } else {
            fprintf(stderr, "SPI transfer failed (attempt %d): %d\n", count + 1, spi_result);
            gpioDelay(10); // Small delay before retry
            count++;
        }
    }

    if (result == -1) {
        fprintf(stderr, "SPI transfer failed after multiple retries\n");
    }

    return result;
}

// Function to calculate voltage
float calculate_voltage(int adc_value) {
    return (adc_value / 1023.0) * VREF;
}

// Function to log data to CSV file
void log_data(int channel, float voltage) {
    time_t rawtime;
