    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set buzzer pin as output
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed with code %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    int buzzer_state = 0; // 0 = OFF, 1 = ON
    int adc_value;

    while (!terminate) {
        // Read ADC value
        adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            break; // Exit loop on error
        }

        printf("ADC Value: %d\n", adc_value);

        // Control buzzer based on ADC value and threshold
        if (adc_value < GAS_THRESHOLD && buzzer_state == 0) {
            control_buzzer(1); // Turn buzzer ON
            buzzer_state = 1;
            printf("Buzzer ON\n");
        } else if (adc_value >= GAS_THRESHOLD && buzzer_state == 1) {
            control_buzzer(0); // Turn buzzer OFF
            buzzer_state = 0;
            printf("Buzzer OFF\n");
        }

        // Wait 500ms
        gpioDelay(500000); // 500ms = 500000 microseconds
    }

    // Cleanup
    control_buzzer(0); // Ensure buzzer is OFF
    spiClose(spi_handle);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

