static struct gpiod_line *door_sensor_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_word(int fd, uint8_t reg);
int i2c_write_word(int fd, uint8_t reg, uint16_t value);
float read_distance();
float calculate_trigger_threshold(float baseline_distances[], int num_samples);
bool is_distance_below_threshold(float distance, float threshold);
void control_relay(bool activate);
bool read_door_sensor();
void log_event(const char *event);
void signal_handler(int sig);
int setup();
void cleanup();

// I2C read function
int i2c_read_word(int fd, uint8_t reg) {
    uint8_t buf[2];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        perror("I2C read failed");
        return -1;
    }
    return (buf[0] << 8) | buf[1];
}

// I2C write function
int i2c_write_word(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF;
    buf[2] = value & 0xFF;
    if (write(fd, buf, 3) != 3) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// Read distance from ADS1115
float read_distance() {
    // Configure ADS1115 for single-ended A0, +/-4.096V, 128 SPS, single-shot mode
    uint16_t config = 0x4003; // 0b0100000000000011
    if (i2c_write_word(i2c_fd, ADS1115_CONFIG_REG, config) < 0) {
        log_event("Error writing to ADS1115 config register");
        return -1.0;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    usleep(10000); // 10ms

    int16_t raw_value = i2c_read_word(i2c_fd, ADS1115_CONVERSION_REG);
    if (raw_value < 0) {
        log_event("Error reading from ADS1115 conversion register");
        return -1.0;
    }

    // Convert raw value to voltage
    float voltage = (float)raw_value * ADS1115_FULL_SCALE_RANGE / ADC_RESOLUTION;

    // Convert voltage to distance (GP2Y0A21YK0F approximation)
    // This is a simplified approximation.  A more accurate model would be needed.
    float distance = 10.0 / (voltage - 0.4) + 20.0; // Example approximation

    return distance;
}

// Calculate trigger threshold
float calculate_trigger_threshold(float baseline_distances[], int num_samples) {
    float sum = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum += baseline_distances[i];
    }
    return sum / num_samples * TRIGGER_THRESHOLD_PERCENTAGE;
}

// Check if distance is below threshold
bool is_distance_below_threshold(float distance, float threshold) {
    return distance < threshold;
}

// Control relay
void control_relay(bool activate) {
    if (relay_line) {
        int ret = gpiod_line_set_value(relay_line, activate ? 1 : 0);
        if (ret < 0) {
            perror("Failed to set relay value");
            log_event("Error setting relay value");
        }
    }
}

// Read door sensor
bool read_door_sensor() {
    if (door_sensor_line) {
        int value = gpiod_line_get_value(door_sensor_line);
        if (value < 0) {
            perror("Failed to read door sensor value");
            log_event("Error reading door sensor value");
            return false; // Return false on error
        }
        return (value == 0); // Active low
    }
    return false; // Return false if line is not initialized
}

// Log event
void log_event(const char *event) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp) {
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, event);
        fclose(fp);
    } else {
        perror("Failed to open log file");
    }
}

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Setup function
int setup() {
    // I2C setup
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return -1;
    }

    // GPIO setup
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return -1;
    }

    relay_line = gpiod_chip_get_line(gpio_chip, RELAY_PIN);
    if (!relay_line) {
        perror("Failed to get relay line");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return -1;
    }

    door_sensor_line = gpiod_chip_get_line(gpio_chip, DOOR_SENSOR_PIN);
    if (!door_sensor_line) {
        perror("Failed to get door sensor line");
        gpiod_line_release(relay_line);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return -1;
    }

    if (gpiod_line_request_output(relay_line, "door_lock", 0) < 0) {
        perror("Failed to request relay line as output");
        gpiod_line_release(door_sensor_line);
        gpiod_line_release(relay_line);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return -1;
    }

    if (gpiod_line_request_input(door_sensor_line, "door_sensor") < 0) {
        perror("Failed to request door sensor line as input");
        gpiod_line_release(relay_line);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0); // De-energize relay
        gpiod_line_release(relay_line);
    }
    if (door_sensor_line) {
        gpiod_line_release(door_sensor_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Setup
    if (setup() < 0) {
        fprintf(stderr, "Setup failed, exiting\n");
        return 1;
    }

    // Baseline calibration
    float baseline_distances[NUM_BASELINE_SAMPLES];
    printf("Calibrating...\n");
    for (int i = 0; i < NUM_BASELINE_SAMPLES; i++) {
        baseline_distances[i] = read_distance();
        if (baseline_distances[i] < 0) {
            log_event("Error during baseline calibration");
            cleanup();
            return 1;
        }
        usleep(BASELINE_SAMPLE_INTERVAL_MS * 1000); // Convert ms to us
    }

    float trigger_threshold = calculate_trigger_threshold(baseline_distances, NUM_BASELINE_SAMPLES);
    printf("Trigger threshold: %.2f\n", trigger_threshold);

    // Main loop
    bool door_open = false;
    while (!terminate) {
        float distance = read_distance();
        if (distance < 0) {
            log_event("Error reading distance, retrying...");
            usleep(200000); // 200ms
            continue;
        }

        if (is_distance_below_threshold(distance, trigger_threshold)) {
            printf("Distance below threshold: %.2f < %.2f\n", distance, trigger_threshold);
            control_relay(true);
            usleep(RELAY_ON_TIME_MS * 1000); // Convert ms to us
            control_relay(false);

            // Debounce
            usleep(DEBOUNCE_DELAY_MS * 1000);

            bool current_door_state = read_door_sensor();
            if (current_door_state) {
                log_event("door opened");
                door_open = true;
            } else {
                log_event("door not opened");
                door_open = false;
            }
        } else {
            printf("Distance above threshold: %.2f > %.2f\n", distance, trigger_threshold);
        }

        usleep(200000); // 200ms
    }

    // Cleanup and exit
    cleanup();
    printf("Exiting cleanly\n");
    return 0;
}

