#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <errno.h>

// Constants
#define SPI_BUS 0
#define SPI_DEVICE 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

#define CS0_PIN 8
#define CS1_PIN 7
#define CS2_PIN 25

#define ADC_CHANNEL 0

#define LOG_FILE "soil_moisture_log.csv"

// Global variables
static volatile int keep_running = 1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *cs0_line = NULL;
static struct gpiod_line *cs1_line = NULL;
static struct gpiod_line *cs2_line = NULL;
static int spi_fd = -1;
static FILE *log_file = NULL;

// Function prototypes
int spi_init(void);
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int read_mcp3008(int chip_select_pin, int channel);
int log_data(FILE *fp, int sensor1, int sensor2, int sensor3);
void signal_handler(int sig);
void cleanup(void);

// SPI Initialization
int spi_init(void) {
    char spi_device[20];
    snprintf(spi_device, sizeof(spi_device), "/dev/spidev%d.%d", SPI_BUS, SPI_DEVICE);

    spi_fd = open(spi_device, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set SPI speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// SPI Transfer
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// Read MCP3008 Channel
int read_mcp3008(int chip_select_pin, int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // Construct the SPI command
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    // Activate chip select
    if (chip_select_pin == CS0_PIN) {
        gpiod_line_set_value(cs0_line, 0);
    } else if (chip_select_pin == CS1_PIN) {
        gpiod_line_set_value(cs1_line, 0);
    } else if (chip_select_pin == CS2_PIN) {
        gpiod_line_set_value(cs2_line, 0);
    }

    // Perform the SPI transfer
    if (spi_transfer(tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "Error during SPI transfer for chip select %d\n", chip_select_pin);
        // Deactivate chip select
        if (chip_select_pin == CS0_PIN) {
            gpiod_line_set_value(cs0_line, 1);
        } else if (chip_select_pin == CS1_PIN) {
            gpiod_line_set_value(cs1_line, 1);
        } else if (chip_select_pin == CS2_PIN) {
            gpiod_line_set_value(cs2_line, 1);
        }
        return -1;
    }

    // Deactivate chip select
    if (chip_select_pin == CS0_PIN) {
        gpiod_line_set_value(cs0_line, 1);
    } else if (chip_select_pin == CS1_PIN) {
        gpiod_line_set_value(cs1_line, 1);
    } else if (chip_select_pin == CS2_PIN) {
        gpiod_line_set_value(cs2_line, 1);
    }

    // Extract the ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];

    return adc_value;
}

// Log Data to CSV
int log_data(FILE *fp, int sensor1, int sensor2, int sensor3) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%d,%d,%d\n", timestamp, sensor1, sensor2, sensor3);
    fflush(fp); // Ensure data is written to disk immediately

    return 0;
}

// Signal Handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received (%d).  Shutting down...\n", sig);
    keep_running = 0;
}

// Cleanup Resources
void cleanup(void) {
    fprintf(stderr, "Cleaning up resources...\n");

    if (log_file != NULL) {
        fclose(log_file);
    }

    if (cs0_line != NULL) {
        gpiod_line_set_value(cs0_line, 1); // Set high before release
        gpiod_line_release(cs0_line);
    }
    if (cs1_line != NULL) {
        gpiod_line_set_value(cs1_line, 1); // Set high before release
        gpiod_line_release(cs1_line);
    }
    if (cs2_line != NULL) {
        gpiod_line_set_value(cs2_line, 1); // Set high before release
        gpiod_line_release(cs2_line);
    }

    if (gpio_chip != NULL) {
        gpiod_chip_close(gpio_chip);
    }

    if (spi_fd != -1) {
        close(spi_fd);
    }
}

int main(void) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    cs0_line = gpiod_chip_get_line(gpio_chip, CS0_PIN);
    cs1_line = gpiod_chip_get_line(gpio_chip, CS1_PIN);
    cs2_line = gpiod_chip_get_line(gpio_chip, CS2_PIN);

    if (!cs0_line || !cs1_line || !cs2_line) {
        perror("Error getting GPIO line");
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(cs0_line, "soil_monitor", 1) < 0 ||
        gpiod_line_request_output(cs1_line, "soil_monitor", 1) < 0 ||
        gpiod_line_request_output(cs2_line, "soil_monitor", 1) < 0) {
        perror("Error requesting GPIO line as output");
        cleanup();
        return 1;
    }

    // Initialize SPI
    if (spi_init() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Check if the file is newly created and write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,sensor1,sensor2,sensor3\n");
    }
    rewind(log_file);

    // Main loop
    while (keep_running) {
        int sensor1_value = read_mcp3008(CS0_PIN, ADC_CHANNEL);
        int sensor2_value = read_mcp3008(CS1_PIN, ADC_CHANNEL);
        int sensor3_value = read_mcp3008(CS2_PIN, ADC_CHANNEL);

        if (sensor1_value == -1 || sensor2_value == -1 || sensor3_value == -1) {
            fprintf(stderr, "Error reading sensor data. Logging -1 for affected sensors.\n");
        }

        log_data(log_file, sensor1_value, sensor2_value, sensor3_value);

        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

