#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

// Constants
#define PUMP_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define DRY_VALUE 200
#define WET_VALUE 800
#define LOG_FILE "irrigation.log"

// Global variables
static volatile int running = 1;
static int threshold = 30;
static int duration = 10;
static int sleep_interval = 60;

// Function prototypes
int read_mcp3008(int channel);
float map_moisture(int adc_value);
void control_pump(int state);
void log_message(const char *message);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char buffer[3];
    int adc_value = -1;
    int retries = 3;

    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    buffer[2] = 0x00;

    while (retries > 0) {
        if (wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3) == 0) {
            adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];
            return adc_value;
        } else {
            log_message("SPI read failed, retrying...");
            retries--;
            gpioDelay(1000); // Wait 1 ms before retrying
        }
    }

    log_message("SPI read failed after multiple retries.");
    return -1; // Indicate failure
}

// Function to map ADC value to moisture percentage
float map_moisture(int adc_value) {
    float moisture = (float)(adc_value - DRY_VALUE) / (WET_VALUE - DRY_VALUE) * 100.0;
    if (moisture < 0) moisture = 0;
    if (moisture > 100) moisture = 100;
    return moisture;
}

// Function to control the water pump
void control_pump(int state) {
    gpioWrite(PUMP_GPIO, state);
    log_message(state ? "Pump activated" : "Pump deactivated");
}

// Function to log messages with timestamps
void log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_message("Received signal, shutting down...");
}

// Initialization function
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is off initially

    if (wiringPiSetup() == -1) {
        fprintf(stderr, "wiringPi initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    if (wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED) == -1) {
        fprintf(stderr, "wiringPi SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    control_pump(0); // Turn off pump
    gpioTerminate(); // Terminate pigpio
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atoi(optarg);
                break;
            case 'd':
                duration = atoi(optarg);
                break;
            case 's':
                sleep_interval = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d duration_seconds] [-s sleep_interval]\n", argv[0]);
                return 1;
        }
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    log_message("System started");

    while (running) {
        int adc_value = read_mcp3008(0);
        if (adc_value == -1) {
            log_message("Failed to read ADC value, skipping irrigation cycle.");
            sleep(sleep_interval);
            continue;
        }

        float moisture = map_moisture(adc_value);
        char log_buffer[100];
        snprintf(log_buffer, sizeof(log_buffer), "Moisture: %.2f%%, ADC: %d", moisture, adc_value);
        log_message(log_buffer);

        if (moisture < threshold) {
            log_message("Moisture below threshold, activating pump.");
            control_pump(1);
            gpioDelay(duration * 1000); // Convert seconds to milliseconds
            control_pump(0);
        }

        sleep(sleep_interval);
    }

    cleanup();
    log_message("System stopped");
    return 0;
}

