#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0
#define EMA_ALPHA 0.1
#define THRESHOLD_MARGIN 0.2
#define SAMPLE_INTERVAL_MS 10
#define LOG_FILE "/var/log/sound_events.log"

// Global variables
int spi_handle;
double ema = 0.0;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_adc(int channel);
double calculate_ema(int adc_value, double alpha);
int detect_peak(int adc_value, double ema, double margin);
void log_peak(int adc_value);
void signal_handler(int signal);

// Function to read ADC value from MCP3008
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to calculate exponential moving average
double calculate_ema(int adc_value, double alpha) {
    return alpha * adc_value + (1 - alpha) * ema;
}

// Function to detect a peak
int detect_peak(int adc_value, double ema, double margin) {
    return (adc_value > ema * (1 + margin));
}

// Function to log a peak to a file
void log_peak(int adc_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return;
    }

    fprintf(fp, "%s, %d\n", timestamp, adc_value);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Sound level monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: ADC read failed\n");
            break; // Exit loop on error
        }

        // Calculate EMA
        ema = calculate_ema(adc_value, EMA_ALPHA);

        // Detect peak
        if (detect_peak(adc_value, ema, THRESHOLD_MARGIN)) {
            printf("Peak detected: ADC value = %d, EMA = %.2f\n", adc_value, ema);
            log_peak(adc_value);
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Clean up
    spiClose(spi_handle);
    gpioTerminate();

    printf("Sound level monitoring stopped.\n");
    return 0;
}

