#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// PCF8591 I2C address
#define PCF8591_ADDR 0x48

// I2C bus
#define I2C_BUS 1

// Global variable for I2C handle
int i2c_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCtrl+C pressed. Cleaning up and exiting...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, PCF8591_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("I2C device opened successfully. Handle: %d\n", i2c_handle);

    // Main loop
    while (1) {
        unsigned char control_byte = 0x40; // Single-ended AIN0, disable analog output
        unsigned char data[2];

        // Write control byte to the PCF8591
        int write_result = i2cWriteByte(i2c_handle, control_byte);
        if (write_result != 0) {
            fprintf(stderr, "I2C write failed: %d\n", write_result);
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }

        // Dummy read to discard the previous conversion result
        int dummy_read = i2cReadByte(i2c_handle);
        if (dummy_read < 0) {
            fprintf(stderr, "I2C dummy read failed: %d\n", dummy_read);
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }

        // Read the current sample
        int read_result = i2cReadByte(i2c_handle);
        if (read_result < 0) {
            fprintf(stderr, "I2C read failed: %d\n", read_result);
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }

        // Print the sample value
        printf("Sample value: %d\n", read_result);

        // Wait for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // The program should never reach here due to the infinite loop.
    // However, for completeness, close I2C and terminate pigpio.
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

