#include <unistd.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define ADS1115_CONFIG_SINGLE_ENDED_0 0x4003 // Single-ended AIN0, 4.096V, Single-shot mode
#define ADS1115_CONFIG_START_CONVERSION 0x8000
#define ADS1115_CONFIG_OS_SINGLE 0x8000
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0060
#define ADS1115_CONFIG_COMP_MODE_TRAD 0x0000
#define ADS1115_CONFIG_COMP_POL_LOW 0x0000
#define ADS1115_CONFIG_COMP_LAT_NON 0x0000
#define ADS1115_CONFIG_COMP_QUE_DISABLE 0x0003

#define GPIO_MOTOR_SHUTDOWN 27
#define THRESHOLD_GAUSS 500.0
#define CIRCULAR_BUFFER_SIZE 10
#define VCC 3.3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float magnetic_field_buffer[CIRCULAR_BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int read_ads1115(int i2c_handle);
float voltage_to_gauss(int16_t raw_voltage);
void update_circular_buffer(float gauss);
float calculate_rolling_average();
void signal_handler(int signal);

// Function to read from ADS1115
int read_ads1115(int i2c_handle) {
    char config[3];
    char data[2];
    int16_t raw_value;

    // Configure ADS1115 for single-ended AIN0, 4.096V, single-shot mode
    config[0] = ADS1115_REG_CONFIG;
    config[1] = (ADS1115_CONFIG_OS_SINGLE | ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_COMP_MODE_TRAD | ADS1115_CONFIG_COMP_POL_LOW | ADS1115_CONFIG_COMP_LAT_NON | ADS1115_CONFIG_COMP_QUE_DISABLE) >> 8;
    config[2] = ADS1115_CONFIG_SINGLE_ENDED_0 >> 8;

    if (i2cWriteDevice(i2c_handle, config, 3) != 0) {
        syslog(LOG_ERR, "Failed to write configuration to ADS1115");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10 ms

    // Read conversion result
    config[0] = ADS1115_REG_CONVERT;
    if (i2cWriteDevice(i2c_handle, config, 1) != 0) {
        syslog(LOG_ERR, "Failed to write conversion register address");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        syslog(LOG_ERR, "Failed to read conversion data");
        return -1;
    }

    raw_value = (data[0] << 8) | data[1];
    return raw_value;
}

// Function to convert raw voltage to Gauss
float voltage_to_gauss(int16_t raw_voltage) {
    float voltage = (float)raw_voltage * VCC / 32767.0; // 16-bit ADC
    if (voltage < 0.0 || voltage > VCC) {
        syslog(LOG_ERR, "Invalid voltage reading: %f", voltage);
        return -1.0; // Indicate an error
    }

    // SS49E transfer function (example values, adjust as needed)
    float zero_field_output = 2.5; // V
    float sensitivity = 0.0014; // V/Gauss

    float gauss = (voltage - zero_field_output) / sensitivity;
    return gauss;
}

// Function to update the circular buffer
void update_circular_buffer(float gauss) {
    magnetic_field_buffer[buffer_index] = gauss;
    buffer_index = (buffer_index + 1) % CIRCULAR_BUFFER_SIZE;
}

// Function to calculate the rolling average
float calculate_rolling_average() {
    float sum = 0.0;
    for (int i = 0; i < CIRCULAR_BUFFER_SIZE; i++) {
        sum += magnetic_field_buffer[i];
    }
    return sum / CIRCULAR_BUFFER_SIZE;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Received signal %d, terminating...", signal);
    terminate = 1;
}

int main() {
    // Initialize syslog
    openlog("magnetic_sensor", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Set GPIO27 as output
    gpioSetMode(GPIO_MOTOR_SHUTDOWN, PI_OUTPUT);
    gpioWrite(GPIO_MOTOR_SHUTDOWN, 0); // Initially LOW

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    syslog(LOG_INFO, "Magnetic sensor monitoring started");

    // Main loop
    while (!terminate) {
        int16_t raw_voltage = read_ads1115(i2c_handle);
        if (raw_voltage >= 0) {
            float gauss = voltage_to_gauss(raw_voltage);
            if (gauss >= 0.0) {
                update_circular_buffer(gauss);
                float rolling_average = calculate_rolling_average();

                syslog(LOG_INFO, "Raw Voltage: %d, Gauss: %f, Rolling Average: %f", raw_voltage, gauss, rolling_average);

                if (rolling_average > THRESHOLD_GAUSS) {
                    syslog(LOG_WARNING, "Threshold exceeded! Rolling Average: %f", rolling_average);
                    gpioWrite(GPIO_MOTOR_SHUTDOWN, 1); // Set HIGH
                } else {
                    gpioWrite(GPIO_MOTOR_SHUTDOWN, 0); // Set LOW
                }
            }
        } else {
            syslog(LOG_ERR, "Failed to read sensor data");
        }

        gpioDelay(1000000); // 1 Hz
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(GPIO_MOTOR_SHUTDOWN, 0); // Set LOW
    gpioTerminate();
    closelog();

    return 0;
}

