#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define PUMP_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define MOISTURE_THRESHOLD 300
#define WATERING_DURATION 10 // seconds
#define READ_INTERVAL 60      // seconds
#define LOG_FILE "watering_events.txt"

// Global variables
int spi_handle;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
void control_pump(int state);
void log_event(const char *event);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01;                           // Start bit
    tx_buffer[1] = (0x08 | channel) << 4;           // Single-ended mode, channel select
    tx_buffer[2] = 0x00;                           // Don't care

    int spi_result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (spi_result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", spi_result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    // Validate ADC value
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Error: Invalid ADC value: %d\n", adc_value);
        return -1;
    }

    return adc_value;
}

// Function to control the water pump
void control_pump(int state) {
    gpioWrite(PUMP_GPIO, state);
}

// Function to log events to a file
void log_event(const char *event) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s: %s\n", timestamp, event);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, shutting down...\n", signal);
    log_event("Program shutdown");
    control_pump(0); // Deactivate pump
    spiClose(spi_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (channel %d)\n", SPI_CHANNEL);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil moisture monitoring and watering system started.\n");
    log_event("Program started");

    while (program_running) {
        // Read soil moisture
        int moisture_level = read_mcp3008(0);
        if (moisture_level < 0) {
            fprintf(stderr, "Error: Failed to read moisture level\n");
            log_event("Error reading moisture level");
            program_running = 0; // Exit loop on error
            continue;              // Skip to next iteration
        }

        // Control pump based on moisture level
        if (moisture_level < MOISTURE_THRESHOLD) {
            printf("Moisture level: %d, below threshold. Activating pump.\n", moisture_level);
            log_event("Moisture level below threshold, activating pump");
            control_pump(1); // Activate pump
            gpioDelay(WATERING_DURATION * 1000000); // Wait for watering duration (microseconds)
            control_pump(0); // Deactivate pump
            printf("Pump deactivated.\n");
            log_event("Pump deactivated");
        } else {
            printf("Moisture level: %d, above threshold.\n", moisture_level);
            log_event("Moisture level above threshold");
        }

        gpioDelay(READ_INTERVAL * 1000000); // Wait for read interval (microseconds)
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_pump(0); // Deactivate pump
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

