#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define MCP3008_CHANNEL 0 // MCP3008 channel connected to rain sensor

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
int map_adc_to_intensity(int adc_value);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        terminate = 1;
    }
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];
    int adc_value;

    // Construct SPI message (MCP3008 single-ended read)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | (channel << 4)); // Single-ended, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer data
    int spi_result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (spi_result != 0) {
        fprintf(stderr, "Error during SPI transfer: %d\n", spi_result);
        return -1; // Indicate error
    }

    // Extract ADC value (10 bits)
    adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to map ADC value to rainfall intensity level
int map_adc_to_intensity(int adc_value) {
    // Linear mapping: 0-1023 -> 0-10
    return (int)(((float)adc_value / 1023.0) * 10.0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value from MCP3008
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value, retrying...\n");
            sleep(1); // Wait before retrying
            continue; // Skip to the next iteration
        }

        // Map ADC value to rainfall intensity
        int intensity = map_adc_to_intensity(adc_value);

        // Get current timestamp
        time_t rawtime;
        struct tm *timeinfo;
        time(&rawtime);
        timeinfo = localtime(&rawtime);

