#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <getopt.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define ADS1115_CONFIG_SINGLE_ENDED_0 0x4003 // Single-ended AIN0, 4.096V, Single-shot
#define ADS1115_CONFIG_START_CONVERSION 0x8000
#define ADS1115_CONFIG_OS_SINGLE 0x8000
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128SPS 0x0060
#define ADS1115_CONFIG_COMP_QUE_DISABLE 0x0003

#define GPIO_LED 17
#define DEFAULT_THRESHOLD 100.0

// Global variables
int i2c_handle;
double threshold = DEFAULT_THRESHOLD;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int read_ads1115(int *raw_value);
double convert_to_gauss(int raw_value);
void blink_led(int duration_ms);
void signal_handler(int signal);
void cleanup();

// Structure to hold ADS1115 configuration
typedef struct {
    unsigned int os_single : 1;   // Start single conversion
    unsigned int mux : 4;         // Input multiplexer configuration
    unsigned int pga : 3;         // Programmable gain amplifier
    unsigned int mode : 1;        // Operation mode (single-shot or continuous)
    unsigned int dr : 3;          // Data rate
    unsigned int comp_mode : 1;   // Comparator mode (traditional or window)
    unsigned int comp_pol : 1;    // Comparator polarity (active low or active high)
    unsigned int comp_lat : 1;    // Comparator latch (non-latching or latching)
    unsigned int comp_que : 2;    // Comparator queue and disable
} ads1115_config_t;

// Function to initialize the pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to initialize the I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read the ADS1115 ADC
int read_ads1115(int *raw_value) {
    char config[3];
    char data[2];
    int16_t raw;

    // Construct the configuration register value
    ads1115_config_t config_data;
    config_data.os_single = 1;   // Start single conversion
    config_data.mux = 0x04;      // AIN0 single-ended
    config_data.pga = 0x04;      // +/-4.096V
    config_data.mode = 0;        // Single-shot mode
    config_data.dr = 0x04;       // 128 SPS
    config_data.comp_mode = 0;   // Traditional comparator
    config_data.comp_pol = 0;    // Active low comparator
    config_data.comp_lat = 0;    // Non-latching comparator
    config_data.comp_que = 0x03; // Disable comparator

    config[0] = ADS1115_REG_CONFIG;
    config[1] = (config_data.os_single << 15 | config_data.mux << 12 | config_data.pga << 9 | config_data.mode << 8 | config_data.dr << 5 | config_data.comp_mode << 4 | config_data.comp_pol << 3 | config_data.comp_lat << 2 | config_data.comp_que) >> 8;
    config[2] = (config_data.os_single << 15 | config_data.mux << 12 | config_data.pga << 9 | config_data.mode << 8 | config_data.dr << 5 | config_data.comp_mode << 4 | config_data.comp_pol << 3 | config_data.comp_lat << 2 | config_data.comp_que) & 0xFF;

    if (i2cWriteDevice(i2c_handle, config, 3) != 3) {
        fprintf(stderr, "Failed to write to I2C device\n");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10 ms

    // Read the conversion register
    config[0] = ADS1115_REG_CONVERT;
    if (i2cWriteDevice(i2c_handle, config, 1) != 1) {
        fprintf(stderr, "Failed to write to I2C device for conversion read\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Failed to read from I2C device\n");
        return -1;
    }

    raw = (data[0] << 8) | data[1];
    *raw_value = raw;

    return 0;
}

// Function to convert the raw ADC value to Gauss
double convert_to_gauss(int raw_value) {
    // 16-bit ADC, 4.096V range, 0.001 V/Gauss
    double voltage = (raw_value * 4.096) / 32767.0;
    return voltage / 0.001;
}

// Function to blink the LED
void blink_led(int duration_ms) {
    int num_blinks = duration_ms / 100; // Each blink is 100ms
    for (int i = 0; i < num_blinks; ++i) {
        gpioWrite(GPIO_LED, 1); // Turn LED on
        gpioDelay(50000);       // 50ms
        gpioWrite(GPIO_LED, 0); // Turn LED off
        gpioDelay(50000);       // 50ms
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    gpioWrite(GPIO_LED, 0); // Turn off LED
    i2cClose(i2c_handle);   // Close I2C device
    gpioTerminate();        // Terminate pigpio
}

int main(int argc, char *argv[]) {
    int opt;
    int raw_value;
    double gauss;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        if (read_ads1115(&raw_value) == 0) {
            // Convert to Gauss
            gauss = convert_to_gauss(raw_value);

            // Print the magnetic field strength
            printf("Magnetic Field: %.2f Gauss\n", gauss);

            // Check if the threshold is exceeded
            if (gauss > threshold) {
                blink_led(1000); // Blink for 1 second
            }
        } else {
            fprintf(stderr, "Failed to read ADC value\n");
        }

        gpioDelay(100000); // 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

