#define VREF 3.3
#define NUM_CHANNELS 3
#define SAMPLE_INTERVAL 5 // seconds

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int read_mcp3008(int channel);
float convert_to_voltage(int adc_value);
int log_data(float channel0_voltage, float channel1_voltage, float channel2_voltage);
void signal_handler(int signal);
void cleanup();

// Structure to hold configuration data
typedef struct {
    int spi_channel;
    int spi_speed;
    float vref;
    int num_channels;
    int sample_interval;
} Config;

Config config = {SPI_CHANNEL, SPI_SPEED, VREF, NUM_CHANNELS, SAMPLE_INTERVAL};

int main() {
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        int adc0 = read_mcp3008(0);
        int adc1 = read_mcp3008(1);
        int adc2 = read_mcp3008(2);

        if (adc0 == -1 || adc1 == -1 || adc2 == -1) {
            fprintf(stderr, "Error reading ADC values. Retrying.\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        float voltage0 = convert_to_voltage(adc0);
        float voltage1 = convert_to_voltage(adc1);
        float voltage2 = convert_to_voltage(adc2);

        if (log_data(voltage0, voltage1, voltage2) != 0) {
            fprintf(stderr, "Error logging data. Retrying.\n");
        }

        gpioDelay(config.sample_interval * 1000); // Delay for 5 seconds
    }

    cleanup();
    return 0;
}

