#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

// Constants
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0
#define NOISE_THRESHOLD 500
#define PWM_FREQUENCY 100 // Hz
#define PWM_RANGE 1000000 // 100% duty cycle
#define LOG_FILE "vibration_log.txt"

// Global variables
int spi_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device);
int read_adc(int channel);
void set_motor_pwm(int gpio, int duty_cycle);
void log_event(int adc_value, int duty_cycle);
void signal_handler(int signal);
void cleanup();

// SPI Initialization
int spi_init(const char *device) {
    int fd;
    uint8_t mode = SPI_MODE;
    uint8_t bits = SPI_BITS_PER_WORD;
    uint32_t speed = SPI_SPEED;

    fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting SPI bits per word");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// ADC Reading
int read_adc(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// PWM Control
void set_motor_pwm(int gpio, int duty_cycle) {
    gpioPWM(gpio, duty_cycle);
}

// Logging
void log_event(int adc_value, int duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s - ADC: %d, Duty Cycle: %d\n", timestamp, adc_value, duty_cycle);
    fflush(log_file); // Ensure immediate write to file
}

// Signal Handler
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE);
    if (spi_fd < 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes for vibration motors
    gpioSetMode(17, PI_OUTPUT);
    gpioSetMode(27, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(17, PWM_FREQUENCY);
    gpioSetPWMfrequency(27, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(17, PWM_RANGE);
    gpioSetPWMrange(27, PWM_RANGE);

    // Initialize duty cycle to 0
    set_motor_pwm(17, 0);
    set_motor_pwm(27, 0);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Vibration motor control started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC, skipping iteration\n");
            usleep(10000); // 10 ms
            continue;
        }

        if (adc_value > NOISE_THRESHOLD) {
            int duty_cycle = (int)(((float)adc_value / 1023.0) * PWM_RANGE);
            set_motor_pwm(17, duty_cycle);
            set_motor_pwm(27, duty_cycle);
            log_event(adc_value, duty_cycle);
        } else {
            set_motor_pwm(17, 0);
            set_motor_pwm(27, 0);
        }

        usleep(10000); // 10 ms
    }

    cleanup();
    return 0;
}

