#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define BH1750_ADDR 0x23
#define BH1750_CMD 0x11
#define LOG_FILE "tamper_log.csv"
#define SAMPLE_INTERVAL 5 // seconds

// Global variables
int spi_handle = -1;
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_db(int adc_value);
int read_bh1750();
int log_data(float sound_level_db, float light_level_lux, int error_code);
void signal_handler(int signal);
int setup();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to dB (example formula)
float adc_to_db(int adc_value) {
    // This is a placeholder.  Calibration is needed for accurate dB values.
    // The formula may need adjustment based on the microphone and amplifier.
    float voltage = (float)adc_value / 1023.0 * 3.3; // Assuming 3.3V reference
    float db = 20 * log10(voltage / 0.00002); // Example formula, adjust as needed
    return db;
}

// Function to read light level from BH1750
int read_bh1750() {
    char buf[2];
    int lux;

    if (i2cWriteByte(i2c_handle, BH1750_CMD) != 0) {
        fprintf(stderr, "Error: Failed to write to BH1750\n");
        return -1;
    }
    gpioDelay(180000); // 180 ms

    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read from BH1750\n");
        return -1;
    }

    lux = (buf[0] << 8) | buf[1];
    return lux;
}

// Function to log data to CSV file
int log_data(float sound_level_db, float light_level_lux, int error_code) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f,%d\n", timestamp, sound_level_db, light_level_lux, error_code);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler for graceful shutdown
