// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD 30
#define NUM_SENSORS 3
#define MAX_RETRIES 3

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture_percentage(int adc_value);
void control_pump(int pump_state);
void log_data(int sensor_id, int adc_value, float moisture_percentage);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (channel %d): %d\n", channel, result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture_percentage(int adc_value) {
    // Assuming 0V = 0% moisture, 3.3V = 100% moisture
    // VH400 output is 0-3V
    float voltage = (float)adc_value / 1023.0 * 3.3; // Convert ADC value to voltage
    float moisture_percentage = (voltage / 3.3) * 100.0; // Calculate moisture percentage
    return moisture_percentage;
}

// Function to control the water pump
void control_pump(int pump_state) {
    gpioWrite(PUMP_GPIO, pump_state);
}

// Function to log data to the console
void log_data(int sensor_id, int adc_value, float moisture_percentage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Sensor %d: ADC Value = %d, Moisture = %.2f%%\n", timestamp, sensor_id, adc_value, moisture_percentage);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil Moisture Monitoring System started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int adc_value = -1;
            int retries = 0;

            // Retry loop for reading ADC value
            while (adc_value == -1 && retries < MAX_RETRIES) {
                adc_value = read_mcp3008(i);
                if (adc_value == -1) {
                    fprintf(stderr, "Error: Failed to read sensor %d, retrying (%d/%d)...\n", i, retries + 1, MAX_RETRIES);
                    retries++;
                    gpioDelay(100); // Wait before retrying
                }
            }

            if (adc_value != -1) {
                float moisture_percentage = calculate_moisture_percentage(adc_value);

                // Control pump based on moisture level
                if (moisture_percentage < MOISTURE_THRESHOLD) {
                    control_pump(1); // Turn pump ON
                } else {
                    control_pump(0); // Turn pump OFF
                }

                log_data(i, adc_value, moisture_percentage);
            } else {
                fprintf(stderr, "Error: Failed to read sensor %d after %d retries.\n", i, MAX_RETRIES);
            }
        }

        gpioDelay(60000); // Wait 60 seconds
    }

    // Cleanup
    control_pump(0); // Turn pump OFF
    spiClose(spi_handle);
    gpioTerminate();

    printf("Soil Moisture Monitoring System terminated.\n");
    return 0;
}

