// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define FAN_GPIO 18
#define CO2_THRESHOLD 700
#define CO2_SLOPE 0.5
#define CO2_INTERCEPT -50
#define ADC_MIN 0
#define ADC_MAX 1023

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_co2_ppm(int adc_value);
void control_fan(int fan_state);
void log_data(int adc_value, float co2_ppm, int fan_state);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (channel %d): %d\n", channel, result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    // Validate ADC value
    if (adc_value < ADC_MIN || adc_value > ADC_MAX) {
        fprintf(stderr, "Error: ADC value out of range: %d\n", adc_value);
        return -1;
    }

    return adc_value;
}

// Function to calculate CO2 ppm
float calculate_co2_ppm(int adc_value) {
    return CO2_SLOPE * adc_value + CO2_INTERCEPT;
}

// Function to control the ventilation fan
void control_fan(int fan_state) {
    gpioWrite(FAN_GPIO, fan_state);
}

// Function to log data to file
void log_data(int adc_value, float co2_ppm, int fan_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%d,%.2f,%d\n", timestamp, adc_value, co2_ppm, fan_state);
    fflush(log_file); // Ensure data is written to disk immediately
}

