    if (adc_value < ADC_MIN || adc_value > ADC_MAX) {
        fprintf(stderr, "Error: ADC value out of range: %d\n", adc_value);
        return -1;
    }

    return adc_value;
}

// Function to calculate CO2 ppm
float calculate_co2_ppm(int adc_value) {
    return CO2_SLOPE * adc_value + CO2_INTERCEPT;
}

// Function to control the ventilation fan
void control_fan(int fan_state) {
    gpioWrite(FAN_GPIO, fan_state);
}

// Function to log data to file
void log_data(int adc_value, float co2_ppm, int fan_state) {
    time_t now = time(NULL);
