        gpioTerminate();
        return 1;
    }

    // Set FAN_GPIO as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Air quality monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value from MQ-135 sensor (channel 0)
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value, retrying in 5 seconds...\n");
            gpioDelay(5000000); // 5 seconds
            continue;
        }

        // Calculate CO2 ppm
        float co2_ppm = calculate_co2_ppm(adc_value);

        // Control fan based on CO2 level
        int fan_state = (co2_ppm > CO2_THRESHOLD) ? 1 : 0;
        control_fan(fan_state);

