        }

        // Convert ADC value to distance
        float distance = adc_to_distance(adc_value);

        // Check for proximity
        if (distance < PROXIMITY_THRESHOLD) {
            if (!proximity_detected) {
                // Debounce check
                time_t current_time = time(NULL);
                if (difftime(current_time, last_trigger_time) >= DEBOUNCE_DELAY) {
                    // Trigger relay
                    control_relay(1); // Activate relay
                    log_event("Door opened (simulated)");
                    proximity_detected = 1;
                    last_trigger_time = current_time;
                }
            }
        } else {
            // Reset proximity detection
            proximity_detected = 0;
            control_relay(0); // Deactivate relay
        }

        // Polling interval
        gpioDelay(100); // 100 ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_relay(0); // Deactivate relay
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

