#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define VALVE_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define PWM_FREQUENCY 100
#define PWM_RANGE 100
#define LOG_FILE "irrigation.log"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float average_adc_values(int adc0, int adc1, int adc2);
void set_valve_position(float average_adc);
void log_data(int adc0, int adc1, int adc2, float average_adc, int valve_position);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message (MCP3008 single-ended read)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Perform SPI transaction
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (channel %d): %d\n", channel, result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to average ADC values
float average_adc_values(int adc0, int adc1, int adc2) {
    int valid_count = 0;
    float sum = 0.0;

    if (adc0 >= 0) {
        sum += adc0;
        valid_count++;
    }
    if (adc1 >= 0) {
        sum += adc1;
        valid_count++;
    }
    if (adc2 >= 0) {
        sum += adc2;
        valid_count++;
    }

    if (valid_count == 0) {
        return 0.0; // Or some other default value
    }

    return sum / valid_count;
}

// Function to set valve position based on average ADC value
void set_valve_position(float average_adc) {
    // Map ADC value (0-1023) to valve position (0-100%)
    int valve_position = (int)(100.0 - (average_adc / 1023.0) * 100.0);

    // Ensure valve position is within valid range
    if (valve_position < 0) {
        valve_position = 0;
    } else if (valve_position > 100) {
        valve_position = 100;
    }

    // Set PWM duty cycle
    gpioPWM(VALVE_GPIO, valve_position);
}

// Function to log data to file
void log_data(int adc0, int adc1, int adc2, float average_adc, int valve_position) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d, %d, %d, %.2f, %d\n", timestamp, adc0, adc1, adc2, average_adc, valve_position);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, shutting down...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file: %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set valve GPIO as output
    gpioSetMode(VALVE_GPIO, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(VALVE_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(VALVE_GPIO, PWM_RANGE);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Irrigation control system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC values from sensors
        int adc0 = read_mcp3008(0);
        int adc1 = read_mcp3008(1);
        int adc2 = read_mcp3008(2);

        // Calculate average ADC value
        float average_adc = average_adc_values(adc0, adc1, adc2);

        // Set valve position
        set_valve_position(average_adc);

        // Log data
        log_data(adc0, adc1, adc2, average_adc, gpioGetPWMdutycycle(VALVE_GPIO));

        // Wait 5 seconds
        sleep(5);
    }

    // Shutdown sequence
    printf("Shutting down...\n");

    // Close valve
    gpioPWM(VALVE_GPIO, 0);

    // Close SPI
    spiClose(spi_handle);

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    printf("Irrigation control system stopped.\n");

    return 0;
}

