// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define MCP3008_CHANNEL 0
#define LOG_FILE "soil_data.txt"
#define RETRY_COUNT 5
#define RETRY_DELAY_BASE 100 // milliseconds

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture_percentage(int adc_value);
void log_data(float moisture_percentage);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];
    int count, delay;

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | (channel << 4)); // Single-ended mode, channel selection
    spi_tx_buf[2] = 0x00; // Don't care

    for (count = 0; count < RETRY_COUNT; count++) {
        if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) == 0) {
            // Extract ADC value (10 bits)
            int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
            return adc_value;
        } else {
            fprintf(stderr, "SPI communication error (attempt %d/%d). Retrying...\n", count + 1, RETRY_COUNT);
            delay = RETRY_DELAY_BASE * (1 << count); // Exponential backoff
            gpioDelay(delay * 1000); // Convert milliseconds to microseconds
        }
    }

    fprintf(stderr, "Failed to read MCP3008 after %d attempts. Skipping reading.\n", RETRY_COUNT);
    return -1; // Indicate failure
}

// Function to calculate moisture percentage
float calculate_moisture_percentage(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Invalid ADC value: %d. Returning -1.0\n", adc_value);
        return -1.0;
    }
    return 100.0 - ((float)adc_value / 1023.0) * 100.0;
}

// Function to log data to file
