    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value != -1) {
            float moisture_percentage = calculate_moisture_percentage(adc_value);
            if (moisture_percentage != -1.0) {
                printf("Moisture: %.2f%%\n", moisture_percentage);
                log_data(moisture_percentage);
            }
        }
        gpioDelay(5000000); // 5 seconds
    }

    // Cleanup
    spiClose(spi_handle);
    gpioTerminate();

    printf("Soil moisture monitoring stopped.\n");
    return 0;
}

