#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

// Define GPIO pins
#define TRIG_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18
#define MCP3008_CHANNEL 0

// Define PWM parameters
#define PWM_RANGE 1000
#define PWM_FREQUENCY 40000 // 40 kHz

// Define LDR calibration parameters
#define LDR_MIN 0
#define LDR_MAX 1023
#define LDR_MIN_VOLTAGE 0.0
#define LDR_MAX_VOLTAGE 3.3

// Define Theremin frequency and volume ranges
#define MIN_FREQUENCY 220.0
#define MAX_FREQUENCY 880.0

// Define timeout values
#define ECHO_TIMEOUT_US 50000 // 50ms
#define SPI_TIMEOUT_US 10000  // 10ms

// Global variables
volatile sig_atomic_t program_running = 1;
double last_valid_distance = 0.0;
int last_valid_volume = 500; // 50% duty cycle

// Function prototypes
void signal_handler(int signal);
double measure_distance();
int read_ldr();
void set_frequency(double frequency);
void set_volume(int volume);
void load_calibration_data();
void save_calibration_data();
void log_data(double distance, int volume);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to measure distance using HC-SR04
double measure_distance() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIG_PIN, 0);

    long long start_time = 0, end_time = 0;

    // Wait for echo to start
    int timeout_count = 0;
    while (gpioRead(ECHO_PIN) == 0 && timeout_count < ECHO_TIMEOUT_US) {
        timeout_count++;
        gpioDelay(1); // Check every microsecond
    }

    if (timeout_count >= ECHO_TIMEOUT_US) {
        fprintf(stderr, "Error: Echo start timeout\n");
        return -1.0; // Indicate error
    }

    start_time = gpioTick();

    // Wait for echo to end
    timeout_count = 0;
    while (gpioRead(ECHO_PIN) == 1 && timeout_count < ECHO_TIMEOUT_US) {
        timeout_count++;
        gpioDelay(1);
    }

    if (timeout_count >= ECHO_TIMEOUT_US) {
        fprintf(stderr, "Error: Echo end timeout\n");
        return -1.0; // Indicate error
    }

    end_time = gpioTick();

    double pulse_duration = (double)(end_time - start_time);
    double distance = pulse_duration / 29.0 / 2.0; // Speed of sound: 29 us/cm

    return distance;
}

// Function to read LDR value from MCP3008
int read_ldr() {
    unsigned char buffer[3];
    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | MCP3008_CHANNEL) << 4; // Single-ended mode, channel selection
    buffer[2] = 0x00;

    if (wiringPiSPIDataRW(0, buffer, 3) == -1) {
        fprintf(stderr, "Error: SPI read failed\n");
        return -1; // Indicate error
    }

    int adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];
    return adc_value;
}

// Function to set PWM frequency
void set_frequency(double frequency) {
    int pwm_range = PWM_RANGE;
    int pwm_clock = 19200000 / pwm_range / frequency; // Calculate clock divider

    if (pwm_clock < 1) pwm_clock = 1;
    if (pwm_clock > 4095) pwm_clock = 4095;

    gpioSetPWMfrequency(PWM_PIN, frequency);
    gpioSetPWMrange(PWM_PIN, pwm_range);
    gpioSetPWMrange(PWM_PIN, pwm_range);
    gpioPWM(PWM_PIN, 0); // Ensure PWM is off before changing frequency
    gpioSetPWMfrequency(PWM_PIN, frequency);
}

// Function to set PWM duty cycle (volume)
void set_volume(int volume) {
    if (volume < 0) volume = 0;
    if (volume > PWM_RANGE) volume = PWM_RANGE;
    gpioPWM(PWM_PIN, volume);
}

// Function to load calibration data from file
void load_calibration_data() {
    FILE *fp = fopen("theremin_config.txt", "r");
    if (fp == NULL) {
        printf("Calibration data file not found, using default values.\n");
        return;
    }

    double distance;
    int volume;

    if (fscanf(fp, "%lf %d", &distance, &volume) == 2) {
        last_valid_distance = distance;
        last_valid_volume = volume;
        printf("Calibration data loaded: Distance=%.2f, Volume=%d\n", distance, volume);
    } else {
        printf("Error reading calibration data, using default values.\n");
    }

    fclose(fp);
}

// Function to save calibration data to file
void save_calibration_data() {
    FILE *fp = fopen("theremin_config.txt", "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open calibration data file for writing\n");
        return;
    }

    fprintf(fp, "%.2f %d", last_valid_distance, last_valid_volume);
    fclose(fp);
}

// Function to log data to file
void log_data(double distance, int volume) {
    FILE *fp = fopen("theremin_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file for writing\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Distance=%.2f, Volume=%d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            distance, volume);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error: wiringPi initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize wiringPi SPI
    if (wiringPiSPISetup(0, 1000000) == -1) {
        fprintf(stderr, "Error: wiringPi SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    // Load calibration data
    load_calibration_data();

    // Set PWM frequency
    set_frequency(440.0); // Initial frequency

    // Set PWM duty cycle
    set_volume(last_valid_volume);

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Theremin-like instrument started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Measure distance
        double distance = measure_distance();
        if (distance < 0) {
            distance = last_valid_distance; // Use last valid distance
        } else {
            last_valid_distance = distance;
        }

        // Read LDR value
        int ldr_value = read_ldr();
        if (ldr_value < 0) {
            ldr_value = last_valid_volume; // Use last valid volume
        } else {
            last_valid_volume = ldr_value;
        }

        // Map distance to frequency
        double frequency = MIN_FREQUENCY + (distance / 100.0) * (MAX_FREQUENCY - MIN_FREQUENCY); // Assuming max distance of 100cm
        if (frequency < MIN_FREQUENCY) frequency = MIN_FREQUENCY;
        if (frequency > MAX_FREQUENCY) frequency = MAX_FREQUENCY;

        // Map LDR value to volume
        int volume = (int)(((float)ldr_value / LDR_MAX) * PWM_RANGE);

        // Set PWM frequency and volume
        set_frequency(frequency);
        set_volume(volume);

        // Log data
        log_data(distance, volume);

        // Delay
        gpioDelay(50); // 50ms delay
    }

    // Save calibration data
    save_calibration_data();

    // Stop PWM
    set_volume(0);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

