#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define SERVER_IP "127.0.0.1" // Replace with your server IP
#define SERVER_PORT 12345
#define LOG_FILE "alcohol_log.txt"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 100

// Global variables
int spi_handle;
int socket_fd;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_ppm(int adc_value);
void classify_alcohol_level(float ppm);
void log_data(const char *timestamp, int adc_value, float ppm, const char *classification);
void send_data(const char *timestamp, int adc_value, float ppm, const char *classification);
void signal_handler(int signal);
int setup();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char tx[3];
    unsigned char rx[3];
    int adc_value = -1;
    int retries = 0;

    tx[0] = 0x01; // Start bit
    tx[1] = (channel << 4) | 0x80; // Single-ended, channel select
    tx[2] = 0x00;

    while (retries < RETRY_COUNT) {
        if (spiXfer(spi_handle, tx, rx, 3) == 0) {
            adc_value = ((rx[1] & 0x03) << 8) | rx[2];
            return adc_value;
        } else {
            fprintf(log_file, "%s SPI transfer failed (attempt %d). Retrying...\n", __func__, retries + 1);
            fflush(log_file);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }

    fprintf(log_file, "%s SPI transfer failed after %d attempts. Error code: %d\n", __func__, RETRY_COUNT, spi_handle);
    fflush(log_file);
    return -1; // Indicate failure
}

// Function to convert ADC value to PPM
float adc_to_ppm(int adc_value) {
    return (adc_value * 0.5) - 10.0;
}

// Function to classify alcohol level
void classify_alcohol_level(float ppm) {
    if (ppm > 50.0) {
        printf("Alcohol detected! Limit exceeded.\n");
    } else if (ppm < 20.0) {
        printf("Sobriety confirmed.\n");
    } else {
        printf("Alcohol level within acceptable range.\n");
    }
}

// Function to log data to file
void log_data(const char *timestamp, int adc_value, float ppm, const char *classification) {
    fprintf(log_file, "%s, ADC: %d, PPM: %.2f, Classification: %s\n", timestamp, adc_value, ppm, classification);
    fflush(log_file);
}

// Function to send data to server
void send_data(const char *timestamp, int adc_value, float ppm, const char *classification) {
    char message[256];
    snprintf(message, sizeof(message), "%s, ADC: %d, PPM: %.2f, Classification: %s", timestamp, adc_value, ppm, classification);

    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(SERVER_PORT);
    if (inet_pton(AF_INET, SERVER_IP, &server_addr.sin_addr) <= 0) {
        fprintf(log_file, "%s Invalid server IP address\n", __func__);
        fflush(log_file);
        return;
    }

    if (sendto(socket_fd, message, strlen(message), 0, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        fprintf(log_file, "%s Failed to send data to server\n", __func__);
        fflush(log_file);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Setup function
int setup() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Create UDP socket
    socket_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (socket_fd < 0) {
        fprintf(stderr, "Failed to create socket\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (socket_fd >= 0) {
        close(socket_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    if (setup() != 0) {
        return 1;
    }

    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value == -1) {
            fprintf(log_file, "Failed to read ADC value\n");
            fflush(log_file);
            gpioDelay(1000000); // Wait 1 second before retrying
            continue;
        }

        // Convert ADC value to PPM
        float ppm = adc_to_ppm(adc_value);

        // Classify alcohol level
        classify_alcohol_level(ppm);

        // Get current timestamp
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[80];

        time(&rawtime);
        timeinfo = gmtime(&rawtime);

        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

        // Log data
        log_data(timestamp, adc_value, ppm, "N/A"); // Classification is not available yet

        // Classify and log again after classification
        if (ppm > 50.0) {
            classify_alcohol_level(ppm);
            log_data(timestamp, adc_value, ppm, "Alcohol detected! Limit exceeded.");
        } else if (ppm < 20.0) {
            classify_alcohol_level(ppm);
            log_data(timestamp, adc_value, ppm, "Sobriety confirmed.");
        } else {
            classify_alcohol_level(ppm);
            log_data(timestamp, adc_value, ppm, "Alcohol level within acceptable range.");
        }

        // Send data to server
        send_data(timestamp, adc_value, ppm, "N/A"); // Classification is not available yet

        // Classify and send again after classification
        if (ppm > 50.0) {
            send_data(timestamp, adc_value, ppm, "Alcohol detected! Limit exceeded.");
        } else if (ppm < 20.0) {
            send_data(timestamp, adc_value, ppm, "Sobriety confirmed.");
        } else {
            send_data(timestamp, adc_value, ppm, "Alcohol level within acceptable range.");
        }

        // Wait for 1 second
        gpioDelay(1000000);
    }

    cleanup();
    return 0;
}

