#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Motor 1
#define MOTOR1_ENABLE 18
#define MOTOR1_DIRECTION 23

// Motor 2
#define MOTOR2_ENABLE 24
#define MOTOR2_DIRECTION 25

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// ADC Channels
#define ADC_CHANNEL_MOTOR1 0
#define ADC_CHANNEL_MOTOR2 1

// Speed Limits
#define MIN_SPEED 50
#define MAX_SPEED 255

// Motion Profile Parameters
#define ACCELERATION_TIME 1.0 // seconds
#define DECELERATION_TIME 1.0 // seconds
#define HOLD_TIME 2.0         // seconds
#define PAUSE_TIME 5.0        // seconds

// Global Variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int read_adc(int channel);
float map_speed(int adc_value);
void set_motor_speed(int motor, int speed);
void set_motor_direction(int motor, int direction);
void motion_profile();
void signal_handler(int signal);

// Function to read ADC value from MCP3008
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01;                           // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4;           // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00;                           // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (%d)\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to map ADC value to speed factor using logarithmic function
float map_speed(int adc_value) {
    // Clamp ADC value to 0-1023 range
    if (adc_value < 0) adc_value = 0;
    if (adc_value > 1023) adc_value = 1023;

    // Logarithmic mapping
    float speed_factor = log10(1.0 + (float)adc_value / 1023.0) * 10.0; // Scale to 0-10
    speed_factor = pow(speed_factor, 2.0); // Further scale to 0-100

    return speed_factor;
}

// Function to set motor speed using gpioPWM
void set_motor_speed(int motor, int speed) {
    if (motor != 1 && motor != 2) {
        fprintf(stderr, "Error: Invalid motor number %d\n", motor);
        return;
    }

    if (speed < MIN_SPEED) speed = MIN_SPEED;
    if (speed > MAX_SPEED) speed = MAX_SPEED;

    int gpio_pin = (motor == 1) ? MOTOR1_ENABLE : MOTOR2_ENABLE;
    gpioPWM(gpio_pin, speed);
}

// Function to set motor direction using gpioWrite
void set_motor_direction(int motor, int direction) {
    if (motor != 1 && motor != 2) {
        fprintf(stderr, "Error: Invalid motor number %d\n", motor);
        return;
    }

    int gpio_pin = (motor == 1) ? MOTOR1_DIRECTION : MOTOR2_DIRECTION;
    gpioWrite(gpio_pin, direction);
}

// Function to execute the motion profile
void motion_profile() {
    float speed_factor1, speed_factor2;
    int speed1, speed2;
    float acceleration_steps = (float)ACCELERATION_TIME * 1000.0 / 10.0; // 10ms delay
    float deceleration_steps = (float)DECELERATION_TIME * 1000.0 / 10.0;
    float hold_time_ms = HOLD_TIME * 1000.0;
    float pause_time_ms = PAUSE_TIME * 1000.0;
    int i;

    // Forward
    for (i = 0; i < acceleration_steps; i++) {
        speed_factor1 = map_speed(read_adc(ADC_CHANNEL_MOTOR1));
        speed_factor2 = map_speed(read_adc(ADC_CHANNEL_MOTOR2));

        speed1 = MIN_SPEED + (int)((float)(MAX_SPEED - MIN_SPEED) * (float)i / acceleration_steps * speed_factor1 / 100.0);
        speed2 = MIN_SPEED + (int)((float)(MAX_SPEED - MIN_SPEED) * (float)i / acceleration_steps * speed_factor2 / 100.0);

        set_motor_speed(1, speed1);
        set_motor_speed(2, speed2);
        set_motor_direction(1, 1); // Forward
        set_motor_direction(2, 0); // Backward
        gpioDelay(10000); // 10ms
    }

    set_motor_speed(1, MAX_SPEED);
    set_motor_speed(2, MAX_SPEED);
    set_motor_direction(1, 1); // Forward
    set_motor_direction(2, 0); // Backward
    gpioDelay((int)hold_time_ms * 1000); // Hold

    for (i = 0; i < deceleration_steps; i++) {
        speed_factor1 = map_speed(read_adc(ADC_CHANNEL_MOTOR1));
        speed_factor2 = map_speed(read_adc(ADC_CHANNEL_MOTOR2));

        speed1 = MIN_SPEED + (int)((float)(MAX_SPEED - MIN_SPEED) * (1.0 - (float)i / deceleration_steps) * speed_factor1 / 100.0);
        speed2 = MIN_SPEED + (int)((float)(MAX_SPEED - MIN_SPEED) * (1.0 - (float)i / deceleration_steps) * speed_factor2 / 100.0);

        set_motor_speed(1, speed1);
        set_motor_speed(2, speed2);
        set_motor_direction(1, 1); // Forward
        set_motor_direction(2, 0); // Backward
        gpioDelay(10000); // 10ms
    }

    gpioDelay((int)pause_time_ms * 1000);

    // Reverse
    for (i = 0; i < acceleration_steps; i++) {
        speed_factor1 = map_speed(read_adc(ADC_CHANNEL_MOTOR1));
        speed_factor2 = map_speed(read_adc(ADC_CHANNEL_MOTOR2));

        speed1 = MIN_SPEED + (int)((float)(MAX_SPEED - MIN_SPEED) * (float)i / acceleration_steps * speed_factor1 / 100.0);
        speed2 = MIN_SPEED + (int)((float)(MAX_SPEED - MIN_SPEED) * (float)i / acceleration_steps * speed_factor2 / 100.0);

        set_motor_speed(1, speed1);
        set_motor_speed(2, speed2);
        set_motor_direction(1, 0); // Backward
        set_motor_direction(2, 1); // Forward
        gpioDelay(10000); // 10ms
    }

    set_motor_speed(1, MAX_SPEED);
    set_motor_speed(2, MAX_SPEED);
    set_motor_direction(1, 0); // Backward
    set_motor_direction(2, 1); // Forward
    gpioDelay((int)hold_time_ms * 1000); // Hold

    for (i = 0; i < deceleration_steps; i++) {
        speed_factor1 = map_speed(read_adc(ADC_CHANNEL_MOTOR1));
        speed_factor2 = map_speed(read_adc(ADC_CHANNEL_MOTOR2));

        speed1 = MIN_SPEED + (int)((float)(MAX_SPEED - MIN_SPEED) * (1.0 - (float)i / deceleration_steps) * speed_factor1 / 100.0);
        speed2 = MIN_SPEED + (int)((float)(MAX_SPEED - MIN_SPEED) * (1.0 - (float)i / deceleration_steps) * speed_factor2 / 100.0);

        set_motor_speed(1, speed1);
        set_motor_speed(2, speed2);
        set_motor_direction(1, 0); // Backward
        set_motor_direction(2, 1); // Forward
        gpioDelay(10000); // 10ms
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating program...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Configure GPIO pins for Motor 1
    gpioSetMode(MOTOR1_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR1_DIRECTION, PI_OUTPUT);

    // Configure GPIO pins for Motor 2
    gpioSetMode(MOTOR2_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR2_DIRECTION, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(MOTOR1_ENABLE, 255);
    gpioSetPWMrange(MOTOR2_ENABLE, 255);

    // Set PWM frequency (e.g., 1000 Hz)
    gpioSetPWMfrequency(MOTOR1_ENABLE, 1000);
    gpioSetPWMfrequency(MOTOR2_ENABLE, 1000);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        motion_profile();
    }

    // Cleanup
    set_motor_speed(1, 0);
    set_motor_speed(2, 0);
    spiClose(spi_handle);
    gpioTerminate();

    fprintf(stderr, "Program terminated successfully.\n");
    return 0;
}

