        speed_factor2 = map_speed(read_adc(ADC_CHANNEL_MOTOR2));

        speed1 = MIN_SPEED + (int)((float)(MAX_SPEED - MIN_SPEED) * (1.0 - (float)i / deceleration_steps) * speed_factor1 / 100.0);
        speed2 = MIN_SPEED + (int)((float)(MAX_SPEED - MIN_SPEED) * (1.0 - (float)i / deceleration_steps) * speed_factor2 / 100.0);

        set_motor_speed(1, speed1);
        set_motor_speed(2, speed2);
        set_motor_direction(1, 0); // Backward
        set_motor_direction(2, 1); // Forward
        gpioDelay(10000); // 10ms
    }
}

