// Define noise threshold percentage
#define NOISE_THRESHOLD_PERCENTAGE 10

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calibrate_sound_level(int num_samples);
int check_sound_level(int sound_level, float average_sound_level, float threshold);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to calibrate sound level
float calibrate_sound_level(int num_samples) {
    float sum = 0.0;
    for (int i = 0; i < num_samples; i++) {
        int sound_level = read_mcp3008(0);
        if (sound_level == -1) {
            fprintf(stderr, "Error: Failed to read sound level during calibration\n");
            return -1.0; // Indicate error
        }
        sum += sound_level;
        gpioDelay(10000); // 10ms delay
    }
    return sum / num_samples;
}

// Function to check sound level against threshold
int check_sound_level(int sound_level, float average_sound_level, float threshold) {
    return (sound_level > (average_sound_level * (1 + threshold / 100.0)));
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Calibrate sound level
    float average_sound_level = calibrate_sound_level(500); // Calibrate for 5 seconds (500 * 10ms)
    if (average_sound_level < 0) {
        fprintf(stderr, "Error: Calibration failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Average sound level: %.2f\n", average_sound_level);

    // Set noise threshold
    float noise_threshold = average_sound_level * (1 + NOISE_THRESHOLD_PERCENTAGE / 100.0);
    printf("Noise threshold: %.2f\n", noise_threshold);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sound level
        int sound_level = read_mcp3008(0);
        if (sound_level == -1) {
            fprintf(stderr, "Error: Failed to read sound level\n");
            continue; // Try again
        }

        // Check if sound level exceeds threshold
        if (check_sound_level(sound_level, average_sound_level, NOISE_THRESHOLD_PERCENTAGE)) {
            // Activate LED with debouncing
            gpioWrite(LED_PIN, 1); // Turn LED on
            gpioDelay(10000);      // 10ms delay
            gpioWrite(LED_PIN, 0); // Turn LED off
        }

        gpioDelay(10000); // 10ms delay
    }

    // Cleanup
    gpioWrite(LED_PIN, 0); // Turn LED off
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

