    *state = *state + kalman_gain * (measurement - *state);
    *covariance = (1 - kalman_gain) * *covariance;

    return *state;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure SPI interface
    spi_handle = spiOpen(SPI_CHANNEL, 1000000, 0); // Channel 0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set CS pin as output
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Deselect the chip initially

    // Set signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC values from MCP3008
        int x_adc = read_mcp3008(0);
        int y_adc = read_mcp3008(1);
        int z_adc = read_mcp3008(2);

        if (x_adc < 0 || y_adc < 0 || z_adc < 0) {
            fprintf(stderr, "Error: Failed to read ADC values\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC values to voltages
        float x_voltage = adc_to_voltage(x_adc);
        float y_voltage = adc_to_voltage(y_adc);
        float z_voltage = adc_to_voltage(z_adc);

        // Convert voltages to acceleration values (in g)
        float x_acceleration = voltage_to_acceleration(x_voltage);
        float y_acceleration = voltage_to_acceleration(y_voltage);
        float z_acceleration = voltage_to_acceleration(z_voltage);

        // Apply Kalman filter
        x_state = kalman_filter(x_acceleration, &x_state, &x_covariance);
        y_state = kalman_filter(y_acceleration, &y_state, &y_covariance);
        z_state = kalman_filter(z_acceleration, &z_state, &z_covariance);

        // Print filtered acceleration values
        printf("X: %.2f g, Y: %.2f g, Z: %.2f g\n", x_state, y_state, z_state);

        // Delay for 100 ms (10 Hz sampling rate)
        gpioDelay(100000); // 100000 microseconds = 100 milliseconds
    }

    // Close SPI interface and terminate pigpio library
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

