#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <errno.h>

// Define sensor GPIO pins
#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define SENSOR3_GPIO 27

// Define constants
#define VCC 3.3
#define VQUIESCENT (VCC / 2.0)
#define SENSITIVITY 0.025 // V/mT
#define LOG_FILE "magnetic_log.txt"

// Global variables
static volatile int running = 1;
FILE *log_file = NULL;

// Structure to hold sensor data
typedef struct {
    int gpio;
    float magnetic_field;
} sensor_data_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read sensor value from GPIO pin
float read_sensor(int gpio) {
    int value = gpioRead(gpio);
    if (value == PI_BAD_GPIO) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", gpio, strerror(errno));
        return -1.0; // Indicate error
    }
    return (float)value * VCC; // Simulate analog value
}

// Function to calculate magnetic field strength in mT
float calculate_magnetic_field(float voltage) {
    return (voltage - VQUIESCENT) / SENSITIVITY;
}

// Function to log sensor data to file
void log_data(sensor_data_t sensor1, sensor_data_t sensor2, sensor_data_t sensor3) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return;
    }

    // Check if the file is empty, if so, write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,sensor1_mT,sensor2_mT,sensor3_mT\n");
    }

    // Get current timestamp
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

    // Write data to file
    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", buf, sensor1.magnetic_field, sensor2.magnetic_field, sensor3.magnetic_field);
    fflush(log_file); // Flush the buffer to ensure data is written to disk
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);
    gpioSetMode(SENSOR3_GPIO, PI_INPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        // Read sensor values
        float sensor1_voltage = read_sensor(SENSOR1_GPIO);
        float sensor2_voltage = read_sensor(SENSOR2_GPIO);
        float sensor3_voltage = read_sensor(SENSOR3_GPIO);

        // Check for errors during sensor reading
        if (sensor1_voltage == -1.0 || sensor2_voltage == -1.0 || sensor3_voltage == -1.0) {
            fprintf(stderr, "Error reading sensor data, skipping logging.\n");
            gpioDelay(100); // Wait 100ms before next iteration
            continue;
        }

        // Calculate magnetic field strengths
        float sensor1_magnetic_field = calculate_magnetic_field(sensor1_voltage);
        float sensor2_magnetic_field = calculate_magnetic_field(sensor2_voltage);
        float sensor3_magnetic_field = calculate_magnetic_field(sensor3_voltage);

        // Data validation
        if (sensor1_magnetic_field < -100.0 || sensor1_magnetic_field > 100.0) {
            fprintf(stderr, "Warning: Sensor 1 magnetic field out of range: %.2f mT\n", sensor1_magnetic_field);
        }
        if (sensor2_magnetic_field < -100.0 || sensor2_magnetic_field > 100.0) {
            fprintf(stderr, "Warning: Sensor 2 magnetic field out of range: %.2f mT\n", sensor2_magnetic_field);
        }
        if (sensor3_magnetic_field < -100.0 || sensor3_magnetic_field > 100.0) {
            fprintf(stderr, "Warning: Sensor 3 magnetic field out of range: %.2f mT\n", sensor3_magnetic_field);
        }

        // Prepare sensor data for logging
        sensor_data_t sensor1_data = {SENSOR1_GPIO, sensor1_magnetic_field};
        sensor_data_t sensor2_data = {SENSOR2_GPIO, sensor2_magnetic_field};
        sensor_data_t sensor3_data = {SENSOR3_GPIO, sensor3_magnetic_field};

        // Log data to file
        log_data(sensor1_data, sensor2_data, sensor3_data);

        // Wait for 100 milliseconds
        gpioDelay(100);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

