#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define PUMP_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define MOISTURE_THRESHOLD 30
#define LOG_FILE "watering.log"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
void control_pump(int state);
void log_event(const char *message);
void signal_handler(int signal);

// Function to read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        log_event("Error: Invalid MCP3008 channel.");
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        log_event("Error: SPI transfer failed.");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to control the water pump
void control_pump(int state) {
    gpioWrite(PUMP_GPIO, state);
    char message[50];
    sprintf(message, "Pump set to %s", state ? "ON" : "OFF");
    log_event(message);
}

// Function to log events to a file
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write to file
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    program_running = 0;
    log_event("Received signal, shutting down...");
    control_pump(0); // Turn off the pump
    spiClose(spi_handle);
    gpioTerminate();
    fclose(log_file);
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    log_event("Program started");

    // Set pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Initialize SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        log_event("Error: SPI initialisation failed.");
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        int moisture_level = read_mcp3008(0);
        if (moisture_level < 0) {
            log_event("Error reading moisture level.");
        } else {
            char message[100];
            sprintf(message, "Moisture level: %d", moisture_level);
            log_event(message);

            if (moisture_level < (1024 * MOISTURE_THRESHOLD) / 100) {
                control_pump(1); // Turn on pump
            } else {
                control_pump(0); // Turn off pump
            }
        }

        gpioDelay(60000); // Wait 60 seconds
    }

    // Cleanup (should not reach here if signal handler works)
    control_pump(0);
    spiClose(spi_handle);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

