#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>
#include <mosquitto.h>
#include <cjson/cJSON.h>

#define MQTT_BROKER "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/led_control"
#define MQTT_CLIENT_ID "rpi_led_control"
#define GPIO_PIN 17

static struct mosquitto *mosq = NULL;
static volatile int running = 1;

// Function to log errors with timestamps
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] ERROR: %s\n", timestamp, message);
}

// Function to parse JSON payload
int parse_json_payload(const char *payload, int *led_state) {
    cJSON *json = cJSON_Parse(payload);
    if (json == NULL) {
        const char *error_ptr = cJSON_GetErrorPtr();
        if (error_ptr != NULL) {
            log_error(error_ptr);
        }
        return 1; // Error parsing JSON
    }

    cJSON *led_state_json = cJSON_GetObjectItemCaseSensitive(json, "led_state");
    if (cJSON_IsBool(led_state_json)) {
        *led_state = led_state_json->valueint;
    } else {
        log_error("Invalid JSON format: 'led_state' is not a boolean.");
        cJSON_Delete(json);
        return 1; // Invalid JSON format
    }

    cJSON_Delete(json);
    return 0; // Success
}

// Function to set LED state
void set_led_state(int led_state) {
    gpioWrite(GPIO_PIN, led_state);
}

// MQTT message callback function
void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        int led_state;
        if (parse_json_payload(message->payload, &led_state) == 0) {
            set_led_state(led_state);
        } else {
            log_error("Failed to parse JSON payload.");
        }
    } else {
        log_error("Received empty message.");
    }
}

// MQTT connect callback function
void connect_callback(struct mosquitto *mosq, void *userdata, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        printf("Connected to MQTT broker.\n");
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    } else {
        log_error("Failed to connect to MQTT broker.");
    }
}

// MQTT disconnect callback function
void disconnect_callback(struct mosquitto *mosq, void *userdata, int rc) {
    if (rc != 0) {
        printf("Disconnected from MQTT broker with error code %d. Attempting to reconnect...\n", rc);
        // Implement exponential backoff reconnection
        int delay = 1; // Initial delay of 1 second
        while (running) {
            mosquitto_reconnect(mosq);
            sleep(delay);
            if (mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60) == MOSQ_ERR_SUCCESS) {
                printf("Reconnected to MQTT broker.\n");
                return; // Exit the loop if reconnection is successful
            }
            delay *= 2; // Exponential backoff
            if (delay > 60) {
                delay = 60; // Maximum delay of 60 seconds
            }
        }
    } else {
        printf("Disconnected from MQTT broker cleanly.\n");
    }
}

// Signal handler for clean shutdown
void signal_handler(int signum) {
    running = 0;
    printf("Received signal %d, shutting down...\n", signum);
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
    }
    gpioWrite(GPIO_PIN, 0); // Turn off LED
    gpioTerminate(); // Release pigpio resources
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Turn off LED on startup

    // Initialize libmosquitto
    mosquitto_lib_init();

    // Create a new mosquitto client instance
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        log_error("Failed to create mosquitto client instance.");
        gpioTerminate();
        mosquitto_lib_cleanup();
        return 1;
    }

    // Set callback functions
    mosquitto_connect_callback_set(mosq, connect_callback);
    mosquitto_disconnect_callback_set(mosq, disconnect_callback);
    mosquitto_message_callback_set(mosq, message_callback);

    // Connect to the MQTT broker
    if (mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60) != MOSQ_ERR_SUCCESS) {
        log_error("Failed to connect to MQTT broker.");
        gpioTerminate();
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return 1;
    }

    // Start the MQTT loop
    mosquitto_loop_start(mosq);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Keep the program running until a signal is received
    while (running) {
        sleep(1);
    }

    // Clean up and exit
    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    gpioWrite(GPIO_PIN, 0); // Turn off LED
    gpioTerminate(); // Release pigpio resources
    mosquitto_lib_cleanup();

    return 0;
}

