// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 18

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up and exiting...\n", signal);
    program_running = 0;
}

// Function to read the sound sensor
int read_sound_sensor() {
    return gpioRead(SOUND_SENSOR_PIN);
}

// Function to activate the alarm LED
void activate_alarm_led() {
    gpioWrite(ALARM_LED_PIN, 1); // Turn LED on
    gpioDelay(1000);             // Wait for 1 second
    gpioWrite(ALARM_LED_PIN, 0); // Turn LED off
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    gpioSetMode(ALARM_LED_PIN, PI_OUTPUT);

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read the sound sensor
        int sound_level = read_sound_sensor();

        // Print the sound level
        printf("Sound level: %d\n", sound_level);

        // Check if sound is detected
        if (sound_level == 0) {
            activate_alarm_led();
        }

        // Delay for 100 milliseconds
        gpioDelay(100);
    }

    // Clean up GPIO resources before exiting
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

