    char data[6];
    if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_PRESS_MSB, data, 6) != 6) {
        fprintf(stderr, "Error reading raw data: %d\n", i2c_handle);
        return -1;
    }

    *pressure = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | ((int32_t)data[2] >> 4);
    *temperature = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | ((int32_t)data[5] >> 4);

    return 0;
}

// Function to compensate temperature
double compensate_temperature(int32_t raw_temp, bmp280_calib_data calib) {
    double var1, var2, T;
    double T_fine;

    var1 = (((double)raw_temp) / 16384.0 - ((double)calib.dig_T1) / 1024.0) * ((double)calib.dig_T2);
    var2 = ((((double)raw_temp) / 131072.0 - ((double)calib.dig_T1) / 8192.0) * (((double)raw_temp) / 131072.0 - ((double)calib.dig_T1) / 8192.0)) * ((double)calib.dig_T3);
    T_fine = (var1 + var2);
    T = (var1 + var2) / 5120.0;
    return T;
}

// Function to compensate pressure
double compensate_pressure(int32_t raw_pressure, bmp280_calib_data calib, double t_fine) {
    double var1, var2, p;

    var1 = ((double)t_fine / 2.0) - 64000.0;
    var2 = var1 * var1 * ((double)calib.dig_P6) / 32768.0;
    var2 = var2 + var1 * ((double)calib.dig_P5) * 2.0;
    var2 = (var2 / 4.0) + (((double)calib.dig_P4) * 65536.0);
    var1 = (((double)calib.dig_P3) * var1 * var1 / 524288.0 + ((double)calib.dig_P2) * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * ((double)calib.dig_P1);

    if (var1 == 0)
    {
        return 0;
    }

    p = 1048576.0 - (double)raw_pressure;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = ((double)calib.dig_P9) * p * p / 2147483648.0;
    var2 = p * ((double)calib.dig_P8) / 32768.0;
    p = p + (var1 + var2 + ((double)calib.dig_P7)) / 16.0;

    return p;
}

// Function to calculate altitude
double calculate_altitude(double pressure, double sea_level_pressure) {
    return 44330.0 * (1.0 - pow(pressure / sea_level_pressure, 0.1903));
}

// Function to log data to a file
int log_data(double altitude) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, altitude);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Function to send data to a server
int send_data_to_server(double altitude) {
    int sock = 0, valread;
    struct sockaddr_in serv_addr;
    char buffer[1024] = {0};
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    if ((sock = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        fprintf(stderr, "Socket creation error: %s\n", strerror(errno));
        return -1;
    }

    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(server_port);

    // Convert IPv4 and IPv6 addresses from text to binary form
    if (inet_pton(AF_INET, server_ip, &serv_addr.sin_addr) <= 0) {
        fprintf(stderr, "Invalid address/ Address not supported: %s\n", server_ip);
        close(sock);
        return -1;
    }

    if (connect(sock, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        fprintf(stderr, "Connection Failed: %s\n", strerror(errno));
        close(sock);
        return -1;
    }

    snprintf(buffer, sizeof(buffer), "%s,%.2f", timestamp, altitude);
    send(sock, buffer, strlen(buffer), 0);
    close(sock);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-s") == 0 && i + 1 < argc) {
            server_ip = argv[i + 1];
            i++;
        } else if (strcmp(argv[i], "-p") == 0 && i + 1 < argc) {
            server_port = atoi(argv[i + 1]);
            i++;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Verify chip ID
    char chip_id;
    if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_CHIPID, &chip_id, 1) != 1) {
        fprintf(stderr, "Error reading chip ID: %d\n", i2c_handle);
        cleanup();
        return 1;
    }

    if (chip_id != 0x58) {
        fprintf(stderr, "Incorrect chip ID: 0x%02X\n", chip_id);
        cleanup();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(&calib) != 0) {
        cleanup();
        return 1;
    }

    // Configure BMP280 for normal mode
    char config_data[1];
    config_data[0] = 0b00100111; // Temperature oversampling x1, pressure oversampling x1, normal mode
    if (i2cWriteI2CBlockData(i2c_handle, BMP280_REG_CTRL_MEAS, config_data, 1) != 1) {
        fprintf(stderr, "Error writing to CTRL_MEAS register: %d\n", i2c_handle);
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("altitude_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        int32_t raw_temperature, raw_pressure;
        double temperature, pressure, altitude;

        // Read raw data
        if (read_raw_data(&raw_temperature, &raw_pressure) != 0) {
            fprintf(stderr, "Error reading raw data, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Compensate temperature and pressure
        temperature = compensate_temperature(raw_temperature, calib);
        pressure = compensate_pressure(raw_pressure, calib, temperature);

        // Calculate altitude
        altitude = calculate_altitude(pressure, sea_level_pressure);

        // Log data
        if (log_data(altitude) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Send data to server
        if (send_data_to_server(altitude) != 0) {
            fprintf(stderr, "Error sending data to server\n");
        }

        printf("Altitude: %.2f meters\n", altitude);

        gpioDelay(5000); // Wait 5 seconds
    }

    return 0;
}

