#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

// Constants
#define I2C_DEVICE "/dev/i2c-1"
#define SPI_DEVICE "/dev/spidev0.0"
#define BH1750_ADDR 0x23
#define LOG_FILE "environmental_log.txt"
#define SAMPLE_INTERVAL_SEC 1

// Global variables
static volatile int keep_running = 1;
static int i2c_fd = -1;
static int spi_fd = -1;
static FILE *log_file = NULL;

// Function prototypes
int init_i2c();
int init_spi();
int read_bh1750(int fd);
int read_mcp3008(int fd, int channel);
float convert_to_lux(int raw_value);
int log_data(float light_level, int sound_level);
void signal_handler(int sig);
void cleanup();

// Structure to hold sensor data (optional)
typedef struct {
    float light_level;
    int sound_level;
} sensor_data_t;

// Initialize I2C
int init_i2c() {
    int fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Initialize SPI
int init_spi() {
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    unsigned char mode = 0; // SPI_MODE_0
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Configure SPI bits per word
    unsigned char bits = 8;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Error setting SPI bits per word");
        close(fd);
        return -1;
    }

    // Configure SPI max speed
    unsigned int speed = 1000000; // 1 MHz
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting SPI max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// Read data from BH1750 sensor
int read_bh1750(int fd) {
    unsigned char config[] = {0x10}; // Continuous high-resolution mode
    if (write(fd, config, 1) != 1) {
        perror("Error writing to BH1750");
        return -1;
    }

    usleep(180000); // Wait for measurement (at least 180ms)

    unsigned char buffer[2];
    if (read(fd, buffer, 2) != 2) {
        perror("Error reading from BH1750");
        return -1;
    }

    return (buffer[0] << 8) | buffer[1];
}

// Read data from MCP3008 ADC
int read_mcp3008(int fd, int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00;

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 3,
        .speed_hz = 1000000, // 1 MHz
        .delay_usecs = 0,
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error sending SPI message");
        return -1;
    }

    return ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
}

// Convert raw ADC value to lux (example calibration)
float convert_to_lux(int raw_value) {
    // This is a placeholder.  Calibration is needed for accurate results.
    return (float)raw_value * 0.1; // Example conversion
}

// Log data to file
int log_data(float light_level, int sound_level) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }

    fprintf(log_file, "%s, Light: %.2f lux, Sound: %d\n", timestamp, light_level, sound_level);
    fflush(log_file); // Ensure data is written immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("Caught signal %d, exiting...\n", sig);
    keep_running = 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c();
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed. Continuing without I2C.\n");
    }

    // Initialize SPI
    spi_fd = init_spi();
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Continuing without SPI.\n");
    }

    printf("Environmental monitoring started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        float light_level = -1.0;
        int sound_level = -1;

        // Read sensor data
        if (i2c_fd != -1) {
            int raw_light = read_bh1750(i2c_fd);
            if (raw_light >= 0) {
                light_level = convert_to_lux(raw_light);
            } else {
                fprintf(stderr, "Error reading light sensor.\n");
            }
        }

        if (spi_fd != -1) {
            int raw_sound = read_mcp3008(spi_fd, 0);
            if (raw_sound >= 0) {
                sound_level = raw_sound;
            } else {
                fprintf(stderr, "Error reading sound sensor.\n");
            }
        }

        // Log data
        if (log_data(light_level, sound_level) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    printf("Environmental monitoring stopped.\n");
    return 0;
}

