        fprintf(stderr, "I2C initialization failed. Continuing without I2C.\n");
    }

    // Initialize SPI
    spi_fd = init_spi();
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Continuing without SPI.\n");
    }

    printf("Environmental monitoring started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        float light_level = -1.0;
        int sound_level = -1;

        // Read sensor data
        if (i2c_fd != -1) {
            int raw_light = read_bh1750(i2c_fd);
            if (raw_light >= 0) {
                light_level = convert_to_lux(raw_light);
            } else {
                fprintf(stderr, "Error reading light sensor.\n");
            }
        }

        if (spi_fd != -1) {
            int raw_sound = read_mcp3008(spi_fd, 0);
            if (raw_sound >= 0) {
                sound_level = raw_sound;
            } else {
                fprintf(stderr, "Error reading sound sensor.\n");
            }
        }

        // Log data
        if (log_data(light_level, sound_level) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    printf("Environmental monitoring stopped.\n");
    return 0;
}

