#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define I2C_BUS 1
#define DAC_ADDRESS 0x62
#define TEMP_MIN 0.0
#define TEMP_MAX 50.0
#define VOLTAGE_MIN 0.0
#define VOLTAGE_MAX 3.3
#define LOG_FILE "temperature_log.txt"

// Global variables
int spi_handle = -1;
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_celsius(int adc_value);
float celsius_to_voltage(float celsius);
int write_dac_voltage(float voltage);
void log_data(int adc_value, float celsius, float voltage);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to Celsius
float adc_to_celsius(int adc_value) {
    float voltage = (adc_value * 3.3) / 1024.0;
    float celsius = (voltage - 0.5) * 100.0;
    return celsius;
}

// Function to convert Celsius to DAC voltage
float celsius_to_voltage(float celsius) {
    float voltage = ((celsius - TEMP_MIN) / (TEMP_MAX - TEMP_MIN)) * (VOLTAGE_MAX - VOLTAGE_MIN) + VOLTAGE_MIN;
    return voltage;
}

// Function to write voltage to MCP4725 DAC
int write_dac_voltage(float voltage) {
    // Convert voltage to DAC value (12-bit)
    int dac_value = (int)((voltage / VOLTAGE_MAX) * 4095.0);

    // Construct I2C message (2 bytes: command + 12-bit DAC value)
    char i2c_tx_buf[3];
    i2c_tx_buf[0] = 0x40; // Write DAC value command
    i2c_tx_buf[1] = (dac_value >> 4) & 0xFF; // Upper 8 bits
    i2c_tx_buf[2] = (dac_value << 4) & 0xF0; // Lower 4 bits

    // Write to I2C
    int result = i2cWriteDevice(i2c_handle, i2c_tx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: I2C write failed with code %d\n", result);
        return -1;
    }

    return 0;
}

// Function to log data to file
void log_data(int adc_value, float celsius, float voltage) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %d, %.2f, %.2f\n", timestamp, adc_value, celsius, voltage);
    fflush(log_file); // Ensure data is written to disk immediately
    printf("%s, %d, %.2f, %.2f\n", timestamp, adc_value, celsius, voltage);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 500kHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, DAC_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Retry
        }

        // Convert ADC value to Celsius
        float celsius = adc_to_celsius(adc_value);

        // Convert Celsius to voltage
        float voltage = celsius_to_voltage(celsius);

        // Write voltage to DAC
        if (write_dac_voltage(voltage) != 0) {
            fprintf(stderr, "Error: Failed to write DAC voltage\n");
        }

        // Log data
        log_data(adc_value, celsius, voltage);

        // Wait 0.5 seconds
        gpioDelay(500000); // 500ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

