#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>

// Define the GPIO chip name and relay pins
#define GPIOCHIP "gpiochip0"
const int relay_pins[] = {17, 22, 23, 24};
const int num_relays = sizeof(relay_pins) / sizeof(relay_pins[0]);

// Global variables for GPIO chip and lines
struct gpiod_chip *chip = NULL;
struct gpiod_line *lines[4] = {NULL, NULL, NULL, NULL};

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Deactivate all relays
    for (int i = 0; i < num_relays; i++) {
        if (lines[i] != NULL) {
            gpiod_line_set_value(lines[i], 0);
        }
    }

    // Release GPIO lines
    for (int i = 0; i < num_relays; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }

    // Close GPIO chip
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Request GPIO lines for output
    for (int i = 0; i < num_relays; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            perror("Error getting GPIO line");
            // Cleanup already allocated lines
            for (int j = 0; j < i; j++) {
                if (lines[j] != NULL) {
                    gpiod_line_release(lines[j]);
                }
            }
            gpiod_chip_close(chip);
            return 1;
        }

        struct gpiod_line_request_config config;
        config.consumer = "relay_control";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

        if (gpiod_line_request(lines[i], &config, 0) < 0) {
            perror("Error requesting GPIO line for output");
            // Cleanup already allocated lines
            for (int j = 0; j <= i; j++) {
                if (lines[j] != NULL) {
                    gpiod_line_release(lines[j]);
                }
            }
            gpiod_chip_close(chip);
            return 1;
        }
    }

    // Main loop
    while (1) {
        for (int i = 0; i < num_relays; i++) {
            // Activate relay
            if (gpiod_line_set_value(lines[i], 1) < 0) {
                perror("Error setting GPIO line value");
                // Cleanup and exit
                for (int j = 0; j < num_relays; j++) {
                    if (lines[j] != NULL) {
                        gpiod_line_release(lines[j]);
                    }
                }
                gpiod_chip_close(chip);
                return 1;
            }

            // Wait for 1 second
            sleep(1);

            // Deactivate relay
            if (gpiod_line_set_value(lines[i], 0) < 0) {
                perror("Error setting GPIO line value");
                // Cleanup and exit
                for (int j = 0; j < num_relays; j++) {
                    if (lines[j] != NULL) {
                        gpiod_line_release(lines[j]);
                    }
                }
                gpiod_chip_close(chip);
                return 1;
            }

            // Wait for 1 second
            sleep(1);
        }
    }

    return 0;
}

