#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define MOTOR_IN1 17
#define MOTOR_IN2 18
#define MOTOR_ENA 27

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define rain level threshold
#define RAIN_THRESHOLD 5

// Define motor speed
#define MOTOR_SPEED 150

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_rain_sensor();
int adc_to_rain_level(int adc_value);
void close_window();
void open_window();
void log_rain_reading(int rain_level);
void signal_handler(int signal);

// Function to read the rain sensor value from the MCP3008
int read_rain_sensor() {
    unsigned char tx[3];
    unsigned char rx[3];
    int adc_value;

    // Construct the SPI message to read from channel 0
    tx[0] = 0x01; // Start bit
    tx[1] = 0x80; // Single-ended, channel 0 (0x08 << 4)
    tx[2] = 0x00; // Don't care

    // Perform the SPI transaction
    if (spiXfer(spi_handle, tx, rx, 3) != 0) {
        fprintf(stderr, "Error: SPI transaction failed\n");
        return -1; // Indicate error
    }

    // Extract the ADC value from the received data
    adc_value = ((rx[1] & 0x03) << 8) | rx[2];

    return adc_value;
}

// Function to convert the ADC value to a rain level (0-10)
int adc_to_rain_level(int adc_value) {
    // Map ADC value (0-1023) to rain level (0-10)
    // Higher ADC value means less rain (drier)
    return 10 - (int)(((float)adc_value / 1023.0) * 10.0);
}

// Function to close the window
void close_window() {
    printf("Closing window...\n");
    gpioWrite(MOTOR_IN1, 1);
    gpioWrite(MOTOR_IN2, 0);
    gpioPWM(MOTOR_ENA, MOTOR_SPEED);
    gpioDelay(3000); // 3 seconds
    gpioWrite(MOTOR_IN1, 0);
    gpioWrite(MOTOR_IN2, 0);
    gpioPWM(MOTOR_ENA, 0);
    printf("Window closed.\n");
}

// Function to open the window
void open_window() {
    printf("Opening window...\n");
    gpioWrite(MOTOR_IN1, 0);
    gpioWrite(MOTOR_IN2, 1);
    gpioPWM(MOTOR_ENA, MOTOR_SPEED);
    gpioDelay(3000); // 3 seconds
    gpioWrite(MOTOR_IN1, 0);
    gpioWrite(MOTOR_IN2, 0);
    gpioPWM(MOTOR_ENA, 0);
    printf("Window opened.\n");
}

// Function to log the rain reading to a file
void log_rain_reading(int rain_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Rain Level: %d\n", timestamp, rain_level);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    int rain_level;
    int adc_value;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes for motor control
    gpioSetMode(MOTOR_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR_ENA, PI_OUTPUT);

    // Set PWM range and frequency
    gpioSetPWMrange(MOTOR_ENA, 255);
    gpioSetPWMfrequency(MOTOR_ENA, 1000); // 1 kHz

    // Open log file
    log_file = fopen("rain_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read rain sensor value
        adc_value = read_rain_sensor();
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read rain sensor\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to rain level
        rain_level = adc_to_rain_level(adc_value);

        // Log the rain reading
        log_rain_reading(rain_level);

        // Control the window based on rain level
        if (rain_level >= RAIN_THRESHOLD) {
            close_window();
        } else {
            open_window();
        }

        // Wait for 1 second
        gpioDelay(1000);
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

