#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins
#define ADC_PIN 26
#define LED_PIN 16

// Define threshold and debounce time
#define THRESHOLD 700
#define DEBOUNCE_TIME 50

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_pigpio();
int setup_gpio();
int read_adc();
int detect_clap(int adc_value);
void control_led(int on);
void print_timestamped_message();
void debounce();
void signal_handler(int signal);

// Structure to hold configuration data
typedef struct {
    int adc_pin;
    int led_pin;
    int threshold;
    int debounce_time;
} Config;

Config config = {ADC_PIN, LED_PIN, THRESHOLD, DEBOUNCE_TIME};

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Setup GPIO pins
    if (setup_gpio() != 0) {
        fprintf(stderr, "Failed to setup GPIO pins. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    printf("Clap detector started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read ADC value
        int adc_value = read_adc();

        // Detect clap
        if (detect_clap(adc_value)) {
            // Control LED
            control_led(1);

            // Print timestamped message
            print_timestamped_message();

            // Debounce
            debounce();
        }

        // Small delay to avoid busy-waiting
        gpioDelay(1000); // 1 ms
    }

    // Clean up and exit
    gpioTerminate();
    printf("Clap detector stopped.\n");
    return 0;
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Setup GPIO pins
int setup_gpio() {
    // Set ADC pin as input
    if (gpioSetMode(config.adc_pin, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set ADC pin as input\n");
        return 1;
    }

    // Set LED pin as output
    if (gpioSetMode(config.led_pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin as output\n");
        return 1;
    }

    return 0;
}

// Read ADC value using bit-banging
int read_adc() {
    int adc_value = 0;
    int i;

    // Set pin to output and drive low
    gpioSetMode(config.adc_pin, PI_OUTPUT);
    gpioWrite(config.adc_pin, 0);
    gpioDelay(1); // Small delay

    // Set pin to input
    gpioSetMode(config.adc_pin, PI_INPUT);
    gpioDelay(1); // Small delay

    // Sample the pin 10 times
    for (i = 0; i < 10; i++) {
        gpioDelay(10); // Delay for sampling
        adc_value = (adc_value << 1) | gpioRead(config.adc_pin);
    }

    return adc_value;
}

// Detect clap based on ADC value
int detect_clap(int adc_value) {
    return (adc_value > config.threshold) ? 1 : 0;
}

// Control LED state
void control_led(int on) {
    gpioWrite(config.led_pin, on);
}

// Print timestamped message
void print_timestamped_message() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] Clap detected!\n", timestamp);
}

// Debounce function
void debounce() {
    gpioDelay(config.debounce_time * 1000); // Debounce time in milliseconds
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    control_led(0); // Turn off LED
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

