#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define GPIO_PIN 17
#define GPIO_PATH "/sys/class/gpio"
#define LOG_FILE "distance_log.txt"
#define A 26.0
#define B -6.0

static volatile int keep_running = 1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig) {
    printf("Caught signal %d, exiting gracefully.\n", sig);
    keep_running = 0;
}

// Function to export the GPIO pin
int gpio_export(int pin) {
    char export_path[64];
    FILE *fp;

    snprintf(export_path, sizeof(export_path), GPIO_PATH "/export");
    fp = fopen(export_path, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s for writing: %s\n", export_path, strerror(errno));
        return -1;
    }
    fprintf(fp, "%d", pin);
    fclose(fp);
    return 0;
}

// Function to unexport the GPIO pin
int gpio_unexport(int pin) {
    char unexport_path[64];
    FILE *fp;

    snprintf(unexport_path, sizeof(unexport_path), GPIO_PATH "/unexport");
    fp = fopen(unexport_path, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s for writing: %s\n", unexport_path, strerror(errno));
        return -1;
    }
    fprintf(fp, "%d", pin);
    fclose(fp);
    return 0;
}

// Function to set the GPIO direction (in or out)
int gpio_set_direction(int pin, const char *direction) {
    char direction_path[64];
    FILE *fp;

    snprintf(direction_path, sizeof(direction_path), GPIO_PATH "/gpio%d/direction", pin);
    fp = fopen(direction_path, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s for writing: %s\n", direction_path, strerror(errno));
        return -1;
    }
    fprintf(fp, "%s", direction);
    fclose(fp);
    return 0;
}

// Function to read the GPIO value
int gpio_read(int pin) {
    char value_path[64];
    FILE *fp;
    char value_str[3];

    snprintf(value_path, sizeof(value_path), GPIO_PATH "/gpio%d/value", pin);
    fp = fopen(value_path, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s for reading: %s\n", value_path, strerror(errno));
        return -1;
    }
    if (fgets(value_str, sizeof(value_str), fp) == NULL) {
        fprintf(stderr, "Error reading from %s: %s\n", value_str, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return atoi(value_str);
}

// Function to convert GPIO reading to voltage
float gpio_to_voltage(int gpio_value) {
    return (float)gpio_value * 3.3;
}

// Function to calculate distance from voltage
float voltage_to_distance(float voltage) {
    return A / voltage + B;
}

// Function to log the distance to a file
int log_distance(float distance) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s for appending: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    fprintf(fp, "%s, Distance: %.2f mm\n", timestamp, distance);
    fclose(fp);
    return 0;
}

int main() {
    int gpio_value;
    float voltage, distance;

    // Set up signal handling for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Export the GPIO pin
    if (gpio_export(GPIO_PIN) != 0) {
        fprintf(stderr, "Failed to export GPIO %d. Exiting.\n", GPIO_PIN);
        return 1;
    }

    // Set the GPIO direction to input
    if (gpio_set_direction(GPIO_PIN, "in") != 0) {
        fprintf(stderr, "Failed to set GPIO %d direction to input. Exiting.\n", GPIO_PIN);
        gpio_unexport(GPIO_PIN);
        return 1;
    }

    printf("Pet Feeder Proximity Sensor Running...\n");

    while (keep_running) {
        // Read the GPIO value
        gpio_value = gpio_read(GPIO_PIN);
        if (gpio_value == -1) {
            fprintf(stderr, "Failed to read GPIO %d. Retrying in 1 second.\n", GPIO_PIN);
            sleep(1);
            continue;
        }

        // Convert GPIO value to voltage
        voltage = gpio_to_voltage(gpio_value);

        // Calculate distance
        distance = voltage_to_distance(voltage);

        // Log the distance
        if (log_distance(distance) != 0) {
            fprintf(stderr, "Failed to log distance.\n");
        }

        // Check proximity and print message
        if (distance < 200.0) {
            printf("Feeder Activated\n");
        } else {
            printf("Feeder Idle\n");
        }

        sleep(1); // Wait for 1 second
    }

    // Unexport the GPIO pin before exiting
    if (gpio_unexport(GPIO_PIN) != 0) {
        fprintf(stderr, "Failed to unexport GPIO %d.\n", GPIO_PIN);
    }

    printf("Exiting.\n");
    return 0;
}

