#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

// Constants
#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define DRY_ADC 800
#define WET_ADC 300
#define MOISTURE_THRESHOLD 30.0
#define PUMP_ON 1
#define PUMP_OFF 0
#define SAMPLE_INTERVAL_SEC 60

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device);
int spi_read_adc(int channel);
float calculate_moisture_percentage(int adc_value, int dry_adc, int wet_adc);
int gpio_init(const char *chip, int pin);
int gpio_set_value(struct gpiod_line *line, int value);
int log_data(float moisture_percentage, int pump_status);
void signal_handler(int sig);
void cleanup();

// SPI Initialization
int spi_init(const char *device) {
    int fd;
    unsigned int mode = SPI_MODE_0;
    unsigned int bits_per_word = 8;
    unsigned int speed = 1000000; // 1 MHz

    fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits_per_word) == -1) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI Read ADC
int spi_read_adc(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // MCP3008 single-ended read command
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended, channel select
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = 1000000; // 1 MHz
    transfer[0].bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Calculate Moisture Percentage
float calculate_moisture_percentage(int adc_value, int dry_adc, int wet_adc) {
    float percentage = 100.0 - ((float)(adc_value - wet_adc) / (float)(dry_adc - wet_adc)) * 100.0;
    if (percentage < 0.0) percentage = 0.0;
    if (percentage > 100.0) percentage = 100.0;
    return percentage;
}

// GPIO Initialization
int gpio_init(const char *chip, int pin) {
    struct gpiod_line_request_config config;

    gpio_chip = gpiod_chip_open_by_name(chip);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, pin);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    memset(&config, 0, sizeof(config));
    config.consumer = "soil_moisture";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(gpio_line, &config, 0) < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// GPIO Set Value
int gpio_set_value(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

// Log Data
int log_data(float moisture_percentage, int pump_status) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s, Moisture: %.2f%%, Pump: %s\n", timestamp, moisture_percentage, pump_status ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal Handler
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        terminate = 1;
    }
}

// Cleanup
void cleanup() {
    printf("Cleaning up resources...\n");

    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    int pump_status = PUMP_OFF;
    int adc_value;
    float moisture_percentage;

    // Signal handling
    signal(SIGINT, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize GPIO
    if (gpio_init(GPIO_CHIP, GPIO_PIN) < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("soil_moisture.log", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC value
        adc_value = spi_read_adc(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Retrying in %d seconds.\n", SAMPLE_INTERVAL_SEC);
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        // Calculate moisture percentage
        moisture_percentage = calculate_moisture_percentage(adc_value, DRY_ADC, WET_ADC);

        // Control pump
        if (moisture_percentage < MOISTURE_THRESHOLD && pump_status == PUMP_OFF) {
            if (gpio_set_value(gpio_line, PUMP_ON) == 0) {
                pump_status = PUMP_ON;
                printf("Pump turned ON.\n");
            } else {
                fprintf(stderr, "Error turning pump ON.\n");
            }
        } else if (moisture_percentage >= MOISTURE_THRESHOLD && pump_status == PUMP_ON) {
            if (gpio_set_value(gpio_line, PUMP_OFF) == 0) {
                pump_status = PUMP_OFF;
                printf("Pump turned OFF.\n");
            } else {
                fprintf(stderr, "Error turning pump OFF.\n");
            }
        }

        // Log data
        if (log_data(moisture_percentage, pump_status) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        printf("Moisture: %.2f%%, Pump: %s\n", moisture_percentage, pump_status ? "ON" : "OFF");

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

