#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <errno.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 8
#define LOG_FILE "magnetic_log.txt"
#define SAMPLE_INTERVAL_MS 500

// Global variables (to be cleaned up on exit)
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device);
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int read_mcp3008(int channel);
float calculate_magnetic_field(int adc_value);
int log_data(time_t timestamp, float magnetic_field);
void cleanup(int signal);

// SPI Initialization
int spi_init(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", device, strerror(errno));
        return -1;
    }

    // Set SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    // Set bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    // Set max speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting max speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// SPI Transfer
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read MCP3008 Channel
int read_mcp3008(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    // Assert CS low
    if (gpiod_line_set_value(gpio_line, 0) < 0) {
        fprintf(stderr, "Error setting CS low: %s\n", strerror(errno));
        return -1;
    }

    // Transfer data
    if (spi_transfer(tx_buf, rx_buf, 3) < 0) {
        // De-assert CS high
        if (gpiod_line_set_value(gpio_line, 1) < 0) {
            fprintf(stderr, "Error setting CS high after transfer error: %s\n", strerror(errno));
        }
        return -1;
    }

    // De-assert CS high
    if (gpiod_line_set_value(gpio_line, 1) < 0) {
        fprintf(stderr, "Error setting CS high: %s\n", strerror(errno));
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Calculate Magnetic Field
float calculate_magnetic_field(int adc_value) {
    float vout_mv = (float)adc_value * 3300.0 / 1023.0;
    float magnetic_field_mt = (vout_mv - 1650.0) / 100.0;
    return magnetic_field_mt;
}

// Log Data
int log_data(time_t timestamp, float magnetic_field) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%ld,%.2f\n", timestamp, magnetic_field);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Signal Handler
void cleanup(int signal) {
    printf("Cleaning up and exiting...\n");

    // Close SPI device
    if (spi_fd != -1) {
        close(spi_fd);
    }

    // Release GPIO line
    if (gpio_line != NULL) {
        gpiod_line_release(gpio_line);
    }

    // Close GPIO chip
    if (gpio_chip != NULL) {
        gpiod_chip_close(gpio_chip);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

int main() {
    // Install signal handlers
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed.\n");
        return 1;
    }

    // Initialize GPIO
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        close(spi_fd);
        return 1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_LINE);
    if (!gpio_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return 1;
    }

    if (gpiod_line_request_output(gpio_line, "magnetic_sensor", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line as output: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading MCP3008, skipping sample.\n");
            usleep(SAMPLE_INTERVAL_MS * 1000); // Sleep for the sample interval
            continue;
        }

        // Calculate magnetic field
        float magnetic_field = calculate_magnetic_field(adc_value);

        // Get timestamp
        time_t timestamp = time(NULL);

        // Log data
        if (log_data(timestamp, magnetic_field) < 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        // Sleep for the sample interval
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    cleanup(0);

    return 0;
}

