#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <time.h>
#include <string.h>

// Define GPIO pins for the sensors
#define SENSOR1_PIN 4
#define SENSOR2_PIN 17

// Define the GPIO chip name
#define GPIOCHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_line *sensor1_line = NULL;
struct gpiod_line *sensor2_line = NULL;
struct gpiod_chip *chip = NULL;

// Function prototypes
int read_sensor(struct gpiod_line *line);
int debounce_sensor(struct gpiod_line *line);
void log_sensor_state(int sensor1_state, int sensor2_state);
void check_alert(int sensor1_state, int sensor2_state);
void signal_handler(int sig);

// Function to read the sensor state
int read_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor value: %s\n", gpiod_line_get_name(line));
        return -1; // Indicate an error
    }
    return value;
}

// Function to debounce the sensor reading
int debounce_sensor(struct gpiod_line *line) {
    int readings[5];
    int i;

    for (i = 0; i < 5; i++) {
        readings[i] = read_sensor(line);
        if (readings[i] < 0) return -1; // Propagate error
        usleep(2000); // 2 ms delay
    }

    int low_count = 0;
    for (i = 0; i < 5; i++) {
        if (readings[i] == 0) {
            low_count++;
        }
    }

    return (low_count >= 3) ? 0 : 1; // Return the majority value
}

// Function to log the sensor state with timestamp
void log_sensor_state(int sensor1_state, int sensor2_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Sensor 1: %d, Sensor 2: %d\n", timestamp, sensor1_state, sensor2_state);
}

// Function to check for the alert condition
void check_alert(int sensor1_state, int sensor2_state) {
    if (sensor1_state == 0 && sensor2_state == 0) {
        printf("ALERT: Both sensors detect object\n");
    }
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (sensor1_line) {
        gpiod_line_release(sensor1_line);
    }
    if (sensor2_line) {
        gpiod_line_release(sensor2_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIOCHIP);
        return 1;
    }

    // Get the GPIO lines for the sensors
    sensor1_line = gpiod_chip_get_line(chip, SENSOR1_PIN);
    if (!sensor1_line) {
        fprintf(stderr, "Error getting GPIO line for sensor 1 (pin %d)\n", SENSOR1_PIN);
        gpiod_chip_close(chip);
        return 1;
    }

    sensor2_line = gpiod_chip_get_line(chip, SENSOR2_PIN);
    if (!sensor2_line) {
        fprintf(stderr, "Error getting GPIO line for sensor 2 (pin %d)\n", SENSOR2_PIN);
        gpiod_line_release(sensor1_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the GPIO lines as input
    if (gpiod_line_request_input(sensor1_line, "sensor1") < 0) {
        fprintf(stderr, "Error requesting GPIO line for sensor 1 as input\n");
        gpiod_line_release(sensor1_line);
        gpiod_line_release(sensor2_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_input(sensor2_line, "sensor2") < 0) {
        fprintf(stderr, "Error requesting GPIO line for sensor 2 as input\n");
        gpiod_line_release(sensor1_line);
        gpiod_line_release(sensor2_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        int sensor1_state = debounce_sensor(sensor1_line);
        int sensor2_state = debounce_sensor(sensor2_line);

        if (sensor1_state < 0 || sensor2_state < 0) {
            fprintf(stderr, "Error during sensor reading, exiting...\n");
            break;
        }

        log_sensor_state(sensor1_state, sensor2_state);
        check_alert(sensor1_state, sensor2_state);

        sleep(1); // Wait for 1 second
    }

    // Cleanup (in case the loop breaks due to an error)
    signal_handler(SIGINT);

    return 0;
}

