    // Release GPIO lines
    if (sensor1_line) {
        gpiod_line_release(sensor1_line);
    }
    if (sensor2_line) {
        gpiod_line_release(sensor2_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIOCHIP);
        return 1;
    }

    // Get the GPIO lines for the sensors
    sensor1_line = gpiod_chip_get_line(chip, SENSOR1_PIN);
    if (!sensor1_line) {
        fprintf(stderr, "Error getting GPIO line for sensor 1 (pin %d)\n", SENSOR1_PIN);
        gpiod_chip_close(chip);
        return 1;
    }

    sensor2_line = gpiod_chip_get_line(chip, SENSOR2_PIN);
    if (!sensor2_line) {
        fprintf(stderr, "Error getting GPIO line for sensor 2 (pin %d)\n", SENSOR2_PIN);
        gpiod_line_release(sensor1_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the GPIO lines as input
    if (gpiod_line_request_input(sensor1_line, "sensor1") < 0) {
        fprintf(stderr, "Error requesting GPIO line for sensor 1 as input\n");
        gpiod_line_release(sensor1_line);
        gpiod_line_release(sensor2_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_input(sensor2_line, "sensor2") < 0) {
        fprintf(stderr, "Error requesting GPIO line for sensor 2 as input\n");
        gpiod_line_release(sensor1_line);
        gpiod_line_release(sensor2_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        int sensor1_state = debounce_sensor(sensor1_line);
        int sensor2_state = debounce_sensor(sensor2_line);

        if (sensor1_state < 0 || sensor2_state < 0) {
            fprintf(stderr, "Error during sensor reading, exiting...\n");
            break;
        }

        log_sensor_state(sensor1_state, sensor2_state);
        check_alert(sensor1_state, sensor2_state);

        sleep(1); // Wait for 1 second
    }

    // Cleanup (in case the loop breaks due to an error)
    signal_handler(SIGINT);

    return 0;
}

