#include <string.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define MCP3008_CHANNEL 0
#define READ_DELAY 60
#define MIN_ADC 300
#define MAX_ADC 800
#define LOG_FILE "soil_moisture_log.csv"

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
double calculate_moisture_level(int adc_value);
void log_data(double moisture_level);
void signal_handler(int signal);
int spi_setup(int channel, int baud);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx_buf[3];
    char rx_buf[3];

    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = 0x80 | (channel << 4); // Single-ended, channel select
    tx_buf[2] = 0x00; // Dummy byte

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed. Retrying...\n");
        gpioDelay(1000); // Wait 1 second before retrying
        return read_mcp3008(channel); // Recursive retry
    }

    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return adc_value;
}

// Function to calculate moisture level as a percentage
double calculate_moisture_level(int adc_value) {
    double moisture_level = 100.0 - ((adc_value - MIN_ADC) / (double)(MAX_ADC - MIN_ADC)) * 100.0;
    if (moisture_level < 0.0) moisture_level = 0.0;
    if (moisture_level > 100.0) moisture_level = 100.0;
    return moisture_level;
}

// Function to log data to a CSV file
void log_data(double moisture_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return;
    }

    fprintf(fp, "%s,%.2f\n", timestamp, moisture_level);
    fclose(fp);

    printf("%s,%.2f\n", timestamp, moisture_level);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to setup SPI
int spi_setup(int channel, int baud) {
    int handle = spiOpen(channel, baud, 0); // SPI channel 0, 1MHz, mode 0
    if (handle < 0) {
        fprintf(stderr, "Error: Could not open SPI channel %d: %d\n", channel, handle);
        return -1;
    }
    return handle;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Setup SPI
    spi_handle = spi_setup(SPI_CHANNEL, SPI_BAUD);
    if (spi_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);

        // Calculate moisture level
        double moisture_level = calculate_moisture_level(adc_value);

        // Log data
        log_data(moisture_level);

        // Delay
        sleep(READ_DELAY);
    }

    // Cleanup
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

