#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <sys/wait.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define IMAGE_WIDTH 1280
#define IMAGE_HEIGHT 720
#define DEBOUNCE_DELAY_MS 200
#define POLL_INTERVAL_MS 50

static volatile int running = 1;

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to construct the image filename
char* construct_filename() {
    char *timestamp = get_iso8601_timestamp();
    char *filename = (char*)malloc(100 * sizeof(char)); // Allocate memory for the filename
    snprintf(filename, 100, "/home/pi/security_cam/%s.jpg", timestamp);
    free(timestamp);
    return filename;
}

// Function to check if a directory exists
int directory_exists(const char *path) {
    struct stat st;
    return (stat(path, &st) == 0 && S_ISDIR(st.st_mode));
}

// Function to create a directory
int create_directory(const char *path) {
    return mkdir(path, 0777); // Create directory with read, write, and execute permissions for all users
}

// Function to capture an image using libcamera-still
int capture_image(const char *filename) {
    char *command = (char*)malloc(200 * sizeof(char)); // Allocate memory for the command string
    snprintf(command, 200, "libcamera-still -o %s --width %d --height %d --encoding jpeg", filename, IMAGE_WIDTH, IMAGE_HEIGHT);
    pid_t pid = fork();

    if (pid == 0) {
        // Child process
        char *args[] = {"libcamera-still", "-o", filename, "--width", "1280", "--height", "720", "--encoding", "jpeg", NULL};
        execvp("libcamera-still", args);
        perror("execvp failed"); // This will only be printed if execvp fails
        exit(EXIT_FAILURE); // Exit the child process if execvp fails
    } else if (pid > 0) {
        // Parent process
        int status;
        waitpid(pid, &status, 0);
        if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
            return 0; // Success
        } else {
            return -1; // Failure
        }
    } else {
        perror("fork failed");
        return -1; // Failure
    }
}

// Function to log an event to syslog
void log_event(const char *message) {
    syslog(LOG_INFO, "%s", message);
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    running = 0;
    log_event("Received signal, shutting down...");
}

int main() {
    openlog("motion_detector", LOG_PID, LOG_USER);
    log_event("Starting motion detector...");

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_event("pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Configure GPIO17 as input with pull-down resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int last_state = gpioRead(GPIO_PIN);
    int current_state;

    while (running) {
        current_state = gpioRead(GPIO_PIN);

        if (current_state != last_state) {
            // Debounce delay
            gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Convert ms to microseconds
            current_state = gpioRead(GPIO_PIN); // Re-read the GPIO

            if (current_state != last_state) {
                last_state = current_state;

                if (current_state == 1) {
                    log_event("Motion detected!");

                    // Construct filename
                    char *filename = construct_filename();

                    // Check if directory exists, create if not
                    if (!directory_exists("/home/pi/security_cam")) {
                        if (create_directory("/home/pi/security_cam") != 0) {
                            log_event("Failed to create directory /home/pi/security_cam");
                            free(filename);
                            continue; // Skip to the next iteration
                        }
                    }

                    // Capture image
                    int capture_result = capture_image(filename);

                    if (capture_result == 0) {
                        char log_message[100];
                        snprintf(log_message, 100, "Image captured: %s", filename);
                        log_event(log_message);
                    } else {
                        log_event("Image capture failed");
                    }

                    free(filename);
                }
            }
        }

        gpioDelay(POLL_INTERVAL_MS * 1000); // Convert ms to microseconds
    }

    // Clean up
    gpioTerminate();
    closelog();
    log_event("Motion detector stopped.");
    return 0;
}

