#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>
#include <time.h>
#include <errno.h>
#include <signal.h>

#define DEVICE_NAME "/dev/video0"
#define FRAME_WIDTH 640
#define FRAME_HEIGHT 480
#define NUM_BUFFERS 4
#define LOG_FILE "frame_log.txt"

// Structure to hold video buffer information
struct buffer {
    void   *start;
    size_t  length;
};

// Global variables
int fd = -1; // File descriptor for the video device
struct buffer *buffers = NULL; // Array of video buffers
unsigned int n_buffers = 0; // Number of video buffers
FILE *log_file = NULL; // File pointer for the log file

// Function prototypes
int open_device(const char *device_name);
int init_device(int fd, int width, int height);
int start_capturing(int fd);
int stop_capturing(int fd);
int uninit_device(int fd);
int close_device(int fd);
int map_buffers(int fd, unsigned int n_buffers);
int unmap_buffers(int fd, unsigned int n_buffers);
int read_frame(int fd, struct buffer *buf);
int log_timestamp(FILE *log_file, unsigned long long timestamp);
void signal_handler(int signum);

// Function to open the video device
int open_device(const char *device_name) {
    int fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (fd == -1) {
        perror("Error opening device");
        return -1;
    }
    return fd;
}

// Function to initialize the video device
int init_device(int fd, int width, int height) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;

    // Check device capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("Error querying capabilities");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        return -1;
    }

    // Set video format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = width;
    fmt.fmt.pix.height = height;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("Error setting format");
        return -1;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("Error requesting buffers");
        return -1;
    }

    if (req.count < NUM_BUFFERS) {
        fprintf(stderr, "Insufficient buffer memory\n");
        return -1;
    }

    return 0;
}

// Function to start capturing
int start_capturing(int fd) {
    unsigned int i;
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    for (i = 0; i < n_buffers; ++i) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            perror("Error queuing buffer");
            return -1;
        }
    }

    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("Error starting capture");
        return -1;
    }

    return 0;
}

// Function to stop capturing
int stop_capturing(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        perror("Error stopping capture");
        return -1;
    }
    return 0;
}

// Function to uninitialize the device
int uninit_device(int fd) {
    if (buffers) {
        unmap_buffers(fd, n_buffers);
        free(buffers);
        buffers = NULL;
    }
    return 0;
}

// Function to close the device
int close_device(int fd) {
    if (fd != -1) {
        close(fd);
    }
    return 0;
}

// Function to map the buffers
int map_buffers(int fd, unsigned int n_buffers) {
    buffers = calloc(n_buffers, sizeof(*buffers));
    if (!buffers) {
        perror("Out of memory");
        return -1;
    }

    for (unsigned int i = 0; i < n_buffers; ++i) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
            perror("Error querying buffer");
            return -1;
        }

        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (buffers[i].start == MAP_FAILED) {
            perror("Error mapping buffer");
            return -1;
        }
    }
    return 0;
}

// Function to unmap the buffers
int unmap_buffers(int fd, unsigned int n_buffers) {
    for (unsigned int i = 0; i < n_buffers; ++i) {
        if (munmap(buffers[i].start, buffers[i].length) == -1) {
            perror("Error unmapping buffer");
            return -1;
        }
    }
    return 0;
}

// Function to read a frame
int read_frame(int fd, struct buffer *buf) {
    struct v4l2_buffer vbuf;
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        perror("Error during select");
        return -1;
    }

    if (r == 0) {
        fprintf(stderr, "Select timeout\n");
        return -1;
    }

    memset(&vbuf, 0, sizeof(vbuf));
    vbuf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    vbuf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &vbuf) == -1) {
        perror("Error dequeuing buffer");
        return -1;
    }

    buf->start = buffers[vbuf.index].start;
    buf->length = buffers[vbuf.index].length;

    if (ioctl(fd, VIDIOC_QBUF, &vbuf) == -1) {
        perror("Error queuing buffer");
        return -1;
    }

    return 0;
}

// Function to log the timestamp
int log_timestamp(FILE *log_file, unsigned long long timestamp) {
    if (fprintf(log_file, "%llu\n", timestamp) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("Received SIGINT, shutting down...\n");
        if (fd != -1) {
            stop_capturing(fd);
            uninit_device(fd);
            close_device(fd);
        }
        if (buffers) {
            unmap_buffers(fd, n_buffers);
            free(buffers);
        }
        if (log_file) {
            fclose(log_file);
        }
        exit(0);
    }
}

int main() {
    struct buffer frame_buffer;
    struct timespec ts;
    unsigned long long timestamp_us;

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Open the device
    fd = open_device(DEVICE_NAME);
    if (fd == -1) {
        return EXIT_FAILURE;
    }

    // Initialize the device
    if (init_device(fd, FRAME_WIDTH, FRAME_HEIGHT) == -1) {
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Map the buffers
    if (map_buffers(fd, NUM_BUFFERS) == -1) {
        uninit_device(fd);
        close_device(fd);
        return EXIT_FAILURE;
    }
    n_buffers = NUM_BUFFERS;

    // Start capturing
    if (start_capturing(fd) == -1) {
        unmap_buffers(fd, n_buffers);
        uninit_device(fd);
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        stop_capturing(fd);
        unmap_buffers(fd, n_buffers);
        uninit_device(fd);
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Main loop to capture and log frames
    while (1) {
        if (read_frame(fd, &frame_buffer) == 0) {
            // Get timestamp
            if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
                timestamp_us = (unsigned long long)ts.tv_sec * 1000000 + (unsigned long long)ts.tv_nsec / 1000;
                // Log timestamp
                if (log_timestamp(log_file, timestamp_us) != 0) {
                    fprintf(stderr, "Error logging timestamp, continuing...\n");
                }
            } else {
                perror("Error getting timestamp");
            }
        } else {
            fprintf(stderr, "Error reading frame, continuing...\n");
        }
    }

    // The following lines will never be reached in normal execution
    // because the program exits in the signal handler.
    stop_capturing(fd);
    unmap_buffers(fd, n_buffers);
    uninit_device(fd);
    close_device(fd);
    fclose(log_file);

    return EXIT_SUCCESS;
}

