    struct v4l2_buffer vbuf;
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        perror("Error during select");
        return -1;
    }

    if (r == 0) {
        fprintf(stderr, "Select timeout\n");
        return -1;
    }

    memset(&vbuf, 0, sizeof(vbuf));
    vbuf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    vbuf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &vbuf) == -1) {
        perror("Error dequeuing buffer");
        return -1;
    }

    buf->start = buffers[vbuf.index].start;
    buf->length = buffers[vbuf.index].length;

    if (ioctl(fd, VIDIOC_QBUF, &vbuf) == -1) {
        perror("Error queuing buffer");
        return -1;
    }

    return 0;
}

