    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        perror("Error dequeuing buffer");
        return -1;
    }

    frame->data = (unsigned char *)buffers[buf.index].start;
    frame->size = buffers[buf.index].length;

    if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        perror("Error queuing buffer");
        return -1;
    }

    return 0;
}

// Function to send a frame over UDP
int send_frame_udp(const char *server_ip, int server_port, const frame_data_t *frame) {
    int frame_index = 0; // Example frame index
    int total_fragments = 1; // Example total fragments
    int fragment_index = 0; // Example fragment index
    size_t payload_size = frame->size; // Example payload size

    // Calculate the number of fragments needed
    int num_fragments = (frame->size + MAX_FRAGMENT_SIZE - 1) / MAX_FRAGMENT_SIZE;
    total_fragments = num_fragments;

    // Create the header
    unsigned char header[HEADER_SIZE];
    memcpy(header, &frame_index, sizeof(frame_index));
    memcpy(header + sizeof(frame_index), &fragment_index, sizeof(fragment_index));
    memcpy(header + sizeof(frame_index) + sizeof(fragment_index), &total_fragments, sizeof(total_fragments));
    memcpy(header + sizeof(frame_index) + sizeof(fragment_index) + sizeof(total_fragments), &payload_size, sizeof(payload_size));

    // Send the header
    ssize_t bytes_sent = sendto(sockfd, header, HEADER_SIZE, 0, (struct sockaddr *)&servaddr, sizeof(servaddr));
    if (bytes_sent != HEADER_SIZE) {
        perror("Error sending header");
        return -1;
    }

    // Send the frame data in fragments
    for (fragment_index = 0; fragment_index < num_fragments; fragment_index++) {
        size_t fragment_offset = fragment_index * MAX_FRAGMENT_SIZE;
        size_t fragment_size = (fragment_offset + MAX_FRAGMENT_SIZE < frame->size) ? MAX_FRAGMENT_SIZE : (frame->size - fragment_offset);

        bytes_sent = sendto(sockfd, frame->data + fragment_offset, fragment_size, 0, (struct sockaddr *)&servaddr, sizeof(servaddr));
        if (bytes_sent != (ssize_t)fragment_size) {
            perror("Error sending frame data");
            return -1;
        }
    }

    return 0;
}

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, stopping...\n", signum);
        stop_flag = 1;
    }
}

int main(int argc, char *argv[]) {
    const char *server_ip;
    int server_port;

    // Check command-line arguments
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return EXIT_FAILURE;
    }

    server_ip = argv[1];
    server_port = atoi(argv[2]);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the video device
    fd = open_device(DEVICE_NAME);
    if (fd == -1) {
        return EXIT_FAILURE;
    }

    // Initialize the video device
    if (init_device(fd, WIDTH, HEIGHT, YUYV_FORMAT) == -1) {
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Initialize memory mapping
    if (init_mmap(fd, buffers, NUM_BUFFERS) == -1) {
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Start capturing
    if (start_capturing(fd) == -1) {
        uninit_mmap(fd, buffers, NUM_BUFFERS);
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Create UDP socket
    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd == -1) {
        perror("Error creating socket");
        stop_capturing(fd);
        uninit_mmap(fd, buffers, NUM_BUFFERS);
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Configure server address
    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(server_port);
    if (inet_pton(AF_INET, server_ip, &servaddr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(sockfd);
        stop_capturing(fd);
        uninit_mmap(fd, buffers, NUM_BUFFERS);
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Main loop
    int frame_count = 0;
    while (!stop_flag) {
        // Read a frame
        if (read_frame(fd, buffers, &frame) == -1) {
            fprintf(stderr, "Error reading frame, exiting...\n");
            break;
        }

        // Send the frame over UDP
        if (send_frame_udp(server_ip, server_port, &frame) == -1) {
            fprintf(stderr, "Error sending frame, exiting...\n");
            break;
        }

        frame_count++;
        printf("Sent frame %d\n", frame_count);
    }

    // Stop capturing
    stop_capturing(fd);

    // Uninitialize memory mapping
    uninit_mmap(fd, buffers, NUM_BUFFERS);

    // Close the video device
    close_device(fd);

    // Close the socket
    close(sockfd);

    printf("Program finished.\n");
    return EXIT_SUCCESS;
}

