#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define TILT_UP_PIN 6
#define TILT_DOWN_PIN 7
#define PAN_LEFT_PIN 8
#define PAN_RIGHT_PIN 9

// Define servo limits
#define SERVO_MIN 50
#define SERVO_MAX 100

// Define PWM frequency
#define PWM_FREQUENCY 50

// Global variables for servo positions
int pan_position = 75;
int tilt_position = 75;

// Function prototypes
int set_servo_position(int gpio, int position);
int read_button(int gpio);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    set_servo_position(PAN_SERVO_PIN, 75); // Set to mid-position
    set_servo_position(TILT_SERVO_PIN, 75); // Set to mid-position
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Function to set servo position using software PWM
int set_servo_position(int gpio, int position) {
    if (position < SERVO_MIN || position > SERVO_MAX) {
        fprintf(stderr, "Error: Servo position out of range (%d)\n", position);
        return -1;
    }

    int pulse_width = (int)(((float)(position - SERVO_MIN) / (SERVO_MAX - SERVO_MIN)) * 1000.0 + 1000.0);
    gpioServo(gpio, pulse_width);
    return 0;
}

// Function to read button state
int read_button(int gpio) {
    return !gpioRead(gpio); // Active low
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set GPIO modes
    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_UP_PIN, PI_INPUT);
    gpioSetMode(TILT_DOWN_PIN, PI_INPUT);
    gpioSetMode(PAN_LEFT_PIN, PI_INPUT);
    gpioSetMode(PAN_RIGHT_PIN, PI_INPUT);

    // Enable pull-up resistors on button pins
    gpioSetPullUpDown(TILT_UP_PIN, PI_PUD_UP);
    gpioSetPullUpDown(TILT_DOWN_PIN, PI_PUD_UP);
    gpioSetPullUpDown(PAN_LEFT_PIN, PI_PUD_UP);
    gpioSetPullUpDown(PAN_RIGHT_PIN, PI_PUD_UP);

    // Set PWM frequency (not strictly needed with gpioServo, but good practice)
    gpioSetPWMfrequency(PAN_SERVO_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(TILT_SERVO_PIN, PWM_FREQUENCY);

    // Main loop
    while (1) {
        // Read button states
        int tilt_up_pressed = read_button(TILT_UP_PIN);
        int tilt_down_pressed = read_button(TILT_DOWN_PIN);
        int pan_left_pressed = read_button(PAN_LEFT_PIN);
        int pan_right_pressed = read_button(PAN_RIGHT_PIN);

        // Update servo positions
        if (tilt_up_pressed) {
            tilt_position += 5;
            if (tilt_position > SERVO_MAX) {
                tilt_position = SERVO_MAX;
            }
        }
        if (tilt_down_pressed) {
            tilt_position -= 5;
            if (tilt_position < SERVO_MIN) {
                tilt_position = SERVO_MIN;
            }
        }
        if (pan_left_pressed) {
            pan_position -= 5;
            if (pan_position < SERVO_MIN) {
                pan_position = SERVO_MIN;
            }
        }
        if (pan_right_pressed) {
            pan_position += 5;
            if (pan_position > SERVO_MAX) {
                pan_position = SERVO_MAX;
            }
        }

        // Set servo positions
        set_servo_position(PAN_SERVO_PIN, pan_position);
        set_servo_position(TILT_SERVO_PIN, tilt_position);

        // Delay
        gpioDelay(50000); // 50 ms
    }

