#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <jpeglib.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <math.h>

#define CLEAR(x) memset(&(x), 0, sizeof(x))

struct buffer {
    void   *start;
    size_t  length;
};

static char            *dev_name   = "/dev/video0";
static int              fd          = -1;
struct buffer          *buffers     = NULL;
static unsigned int     n_buffers   = 0;
static int              out_buf     = -1;
static int              force_format = 0;
static int              frame_count = 0;
static int              jpeg_quality = 75;

static void errno_exit(const char * s)
{
    fprintf(stderr, "%s error %d, %s\n", s, errno, strerror(errno));
    exit(EXIT_FAILURE);
}

static int xioctl(int fh, int request, void *arg)
{
        int r;

        do {
                r = ioctl(fh, request, arg);
        } while (-1 == r && EINTR == errno);

        return r;
}

static int read_frame(void)
{
    struct v4l2_buffer buf;
    fd_set              fds;
    struct timeval      tv;
    int                 r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2;
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);

    if (-1 == r) {
        if (EINTR == errno) {
            return -1;
        }

        errno_exit("select");
    }

    if (0 == r) {
        fprintf(stderr, "select timeout\n");
        return -1;
    }

    CLEAR(buf);

    buf.type   = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (-1 == xioctl(fd, VIDIOC_DQBUF, &buf)) {
        errno_exit("VIDIOC_DQBUF");
    }

    assert(buf.index < n_buffers);

    return buf.index;
}

static void process_frame(int index)
{
    unsigned char *yuyv_frame = buffers[index].start;
    unsigned char *rgb_frame  = malloc(640 * 480 * 3);
    if (!rgb_frame) {
        fprintf(stderr, "Failed to allocate memory for RGB frame\n");
        exit(EXIT_FAILURE);
    }

    // YUYV to RGB24 conversion
    for (int i = 0, j = 0; i < 640 * 480 * 2; i += 4, j += 6) {
        unsigned char Y1 = yuyv_frame[i];
        unsigned char U  = yuyv_frame[i + 1];
        unsigned char Y2 = yuyv_frame[i + 2];
        unsigned char V  = yuyv_frame[i + 3];

        int R1 = Y1 + 1.370705 * (V - 128);
        int G1 = Y1 - 0.698001 * (V - 128) - 0.336331 * (U - 128);
        int B1 = Y1 + 1.732446 * (U - 128);

        int R2 = Y2 + 1.370705 * (V - 128);
        int G2 = Y2 - 0.698001 * (V - 128) - 0.336331 * (U - 128);
        int B2 = Y2 + 1.732446 * (U - 128);

        R1 = (R1 < 0) ? 0 : ((R1 > 255) ? 255 : R1);
        G1 = (G1 < 0) ? 0 : ((G1 > 255) ? 255 : G1);
        B1 = (B1 < 0) ? 0 : ((B1 > 255) ? 255 : B1);

        R2 = (R2 < 0) ? 0 : ((R2 > 255) ? 255 : R2);
        G2 = (G2 < 0) ? 0 : ((G2 > 255) ? 255 : G2);
        B2 = (B2 < 0) ? 0 : ((B2 > 255) ? 255 : B2);

        rgb_frame[j]   = R1;
        rgb_frame[j + 1] = G1;
        rgb_frame[j + 2] = B1;
        rgb_frame[j + 3] = R2;
        rgb_frame[j + 4] = G2;
        rgb_frame[j + 5] = B2;
    }

    // 5x5 Box Blur
    unsigned char *blurred_frame = malloc(640 * 480 * 3);
    if (!blurred_frame) {
        fprintf(stderr, "Failed to allocate memory for blurred frame\n");
        free(rgb_frame);
        exit(EXIT_FAILURE);
    }

    for (int y = 0; y < 480; y++) {
        for (int x = 0; x < 640; x++) {
            int r_sum = 0, g_sum = 0, b_sum = 0;
            int count = 0;

            for (int i = -2; i <= 2; i++) {
                for (int j = -2; j <= 2; j++) {
                    int nx = x + i;
                    int ny = y + j;

                    if (nx >= 0 && nx < 640 && ny >= 0 && ny < 480) {
                        r_sum += rgb_frame[(ny * 640 + nx) * 3];
                        g_sum += rgb_frame[(ny * 640 + nx) * 3 + 1];
                        b_sum += rgb_frame[(ny * 640 + nx) * 3 + 2];
                        count++;
                    }
                }
            }

            blurred_frame[(y * 640 + x) * 3]   = r_sum / count;
            blurred_frame[(y * 640 + x) * 3 + 1] = g_sum / count;
            blurred_frame[(y * 640 + x) * 3 + 2] = b_sum / count;
        }
    }

    // Save as JPEG
    char filename[64];
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(filename, sizeof(filename), "capture_%Y%m%d_%H%M%S.jpg", timeinfo);

    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;

    FILE *outfile = fopen(filename, "wb");
    if (!outfile) {
        fprintf(stderr, "Error opening output file\n");
        free(rgb_frame);
        free(blurred_frame);
        exit(EXIT_FAILURE);
    }

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);

    jpeg_stdio_dest(&cinfo, outfile);

    cinfo.image_width = 640;
    cinfo.image_height = 480;
    cinfo.input_components = 3;
    cinfo.in_color_space = JCS_RGB;

    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, jpeg_quality, TRUE);

    jpeg_start_compress(&cinfo, TRUE);

    JSAMPROW row_pointer[1];
    int row_stride = 640 * 3;

    while (cinfo.next_scanline < cinfo.image_height) {
        row_pointer[0] = &blurred_frame[cinfo.next_scanline * row_stride];
        jpeg_write_scanlines(&cinfo, row_pointer, 1);
    }

    jpeg_finish_compress(&cinfo);
    fclose(outfile);
    jpeg_destroy_compress(&cinfo);

    free(rgb_frame);
    free(blurred_frame);

    printf("Saved frame %d as %s\n", frame_count++, filename);
}

static void stop_capturing(void)
{
    if (-1 == xioctl(fd, VIDIOC_STREAMOFF, &type)) {
        errno_exit("VIDIOC_STREAMOFF");
    }
}

static void start_capturing(void)
{
    unsigned int i;
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    for (i = 0; i < n_buffers; ++i) {
        struct v4l2_buffer buf;

        CLEAR(buf);
        buf.type        = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory      = V4L2_MEMORY_MMAP;
        buf.index       = i;

        if (-1 == xioctl(fd, VIDIOC_QBUF, &buf)) {
            errno_exit("VIDIOC_QBUF");
        }
    }

    if (-1 == xioctl(fd, VIDIOC_STREAMON, &type)) {
        errno_exit("VIDIOC_STREAMON");
    }
}

static void uninit_device(void)
{
    unsigned int i;

    for (i = 0; i < n_buffers; ++i)
        if (-1 == munmap(buffers[i].start, buffers[i].length))
            errno_exit("munmap");

    free(buffers);
}

static void init_mmap(void)
{
    struct v4l2_requestbuffers req;

    CLEAR(req);

    req.count               = 4;
    req.type                = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory              = V4L2_MEMORY_MMAP;

    if (-1 == xioctl(fd, VIDIOC_REQBUFS, &req)) {
        if (EINVAL == errno) {
            fprintf(stderr, "%s does not support memory mapping\n", dev_name);
            exit(EXIT_FAILURE);
        } else {
            errno_exit("VIDIOC_REQBUFS");
        }
    }

    if (req.count < 2) {
        fprintf(stderr, "Insufficient buffer memory on %s\n", dev_name);
        exit(EXIT_FAILURE);
    }

    buffers = calloc(req.count, sizeof(*buffers));

    if (!buffers) {
        fprintf(stderr, "Out of memory\n");
        exit(EXIT_FAILURE);
    }

    for (n_buffers = 0; n_buffers < req.count; ++n_buffers) {
        struct v4l2_buffer buf;

        CLEAR(buf);

        buf.type        = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory      = V4L2_MEMORY_MMAP;
        buf.index       = n_buffers;

        if (-1 == xioctl(fd, VIDIOC_QUERYBUF, &buf))
            errno_exit("VIDIOC_QUERYBUF");

        buffers[n_buffers].length = buf.length;
        buffers[n_buffers].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (MAP_FAILED == buffers[n_buffers].start)
            errno_exit("mmap");
    }
}

static void init_device(void)
{
    struct v4l2_capability cap;
    struct v4l2_cropcap cropcap;
    struct v4l2_crop crop;
    struct v4l2_format fmt;
    unsigned int min;

    if (-1 == xioctl(fd, VIDIOC_QUERYCAP, &cap)) {
        if (EINVAL == errno) {
            fprintf(stderr, "%s is no V4L2 device\n", dev_name);
            exit(EXIT_FAILURE);
        } else {
            errno_exit("VIDIOC_QUERYCAP");
        }
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is no video capture device\n", dev_name);
        exit(EXIT_FAILURE);
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", dev_name);
        exit(EXIT_FAILURE);
    }

    // Select video input, video standard and tune here.
    CLEAR(cropcap);

    cropcap.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    if (0 == xioctl(fd, VIDIOC_CROPCAP, &cropcap)) {
        crop.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        crop.c = cropcap.defrect;

        if (-1 == xioctl(fd, VIDIOC_S_CROP, &crop)) {
            // Errors ignored
        }
    } else {
        // Errors ignored
    }

    CLEAR(fmt);

    fmt.type                = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width       = 640;
    fmt.fmt.pix.height      = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field       = V4L2_FIELD_INTERLACED;

    if (-1 == xioctl(fd, VIDIOC_S_FMT, &fmt)) {
        errno_exit("VIDIOC_S_FMT");
    }

    // Note VIDIOC_S_FMT may change width and height.
    min = fmt.fmt.pix.width * 2; /* YUYV */
    if (fmt.fmt.pix.bytesperline < min)
        fmt.fmt.pix.bytesperline = min;
    min = fmt.fmt.pix.bytesperline * fmt.fmt.pix.height;
    if (fmt.fmt.pix.sizeimage < min)
        fmt.fmt.pix.sizeimage = min;

    init_mmap();
}

static void close_device(void)
{
    if (-1 == close(fd))
        errno_exit("close");

    fd = -1;
}

static void open_device(void)
{
    struct v4l2_capability cap;

    fd = open(dev_name, O_RDWR | O_NONBLOCK, 0);

    if (-1 == fd) {
        fprintf(stderr, "Cannot open '%s': %d, %s\n", dev_name, errno, strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (-1 == xioctl(fd, VIDIOC_QUERYCAP, &cap)) {
        if (EINVAL == errno) {
            fprintf(stderr, "%s is no V4L2 device\n", dev_name);
            exit(EXIT_FAILURE);
        } else {
            errno_exit("VIDIOC_QUERYCAP");
        }
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is no video capture device\n", dev_name);
        exit(EXIT_FAILURE);
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", dev_name);
        exit(EXIT_FAILURE);
    }
}

static void mainloop(void)
{
    unsigned int i;
    unsigned int count;

    count = 1; // Capture only one frame

    while (count > 0) {
        int index = read_frame();

        if (index < 0) {
            break;
        }

        process_frame(index);

        if (-1 == xioctl(fd, VIDIOC_QBUF, &buffers[index].type)) {
            errno_exit("VIDIOC_QBUF");
        }

        count--;
    }
}

static void signal_handler(int signum)
{
    if (signum != SIGINT && signum != SIGTERM)
        return;

    fprintf(stderr, "Signal received, stopping...\n");

    stop_capturing();
    close_device();
    uninit_device();

    exit(EXIT_SUCCESS);
}

int main(int argc, char **argv)
{
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    enum v4l2_buf_type type;

    while (argc > 1) {
        --argc;
        ++argv;

        if (!strcmp(*argv, "-d")) {
            if (argc > 1) {
                --argc;
                ++argv;
                dev_name = *argv;
            }
        } else if (!strcmp(*argv, "-f")) {
            force_format = 1;
        } else if (!strcmp(*argv, "-q")) {
            if (argc > 1) {
                --argc;
                ++argv;
                jpeg_quality = atoi(*argv);
                if (jpeg_quality < 1 || jpeg_quality > 100) {
                    fprintf(stderr, "JPEG quality must be between 1 and 100\n");
                    exit(EXIT_FAILURE);
                }
            }
        } else {
            fprintf(stderr, "Unknown argument %s\n", *argv);
            exit(EXIT_FAILURE);
        }
    }

    signal(SIGINT,  signal_handler);
    signal(SIGTERM, signal_handler);

    open_device();
    init_device();
    start_capturing();
    mainloop();
    stop_capturing();
    close_device();
    uninit_device();

    return 0;
}

