#include <errno.h>

#define DEVICE_NAME "/dev/video0"
#define MAX_FRAME_SIZES 10
#define MAX_FRAME_INTERVALS 5

// Function to print error messages and exit
void error_exit(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
    exit(EXIT_FAILURE);
}

// Function to query camera capabilities
int query_camera_capabilities(int fd) {
    struct v4l2_capability cap;

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP failed");
        return -1;
    }

    printf("Driver: %s\n", cap.driver);
    printf("Card: %s\n", cap.card);
    printf("Bus Info: %s\n", cap.bus_info);
    printf("Version: %u.%u.%u\n", (cap.version >> 16) & 0xFF, (cap.version >> 8) & 0xFF, cap.version & 0xFF);
    printf("Capabilities: %08x\n", cap.capabilities);

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: Device does not support video capture\n");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: Device does not support streaming\n");
        return -1;
    }

    return 0;
}

// Function to enumerate supported frame sizes
int enumerate_frame_sizes(int fd) {
    struct v4l2_frmsizeenum fs;
    int i = 0;

    fs.index = 0;
    fs.pixel_format = V4L2_PIX_FMT_YUYV; // Common format

    printf("Supported Resolutions:\n");
    while (1) {
        if (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &fs) < 0) {
            if (errno == EINVAL) {
                break; // No more frame sizes
            } else {
                perror("VIDIOC_ENUM_FRAMESIZES failed");
                return -1;
            }
        }

        if (fs.type == V4L2_FRMSIZE_TYPE_DISCRETE) {
            printf("  %dx%d\n", fs.discrete.width, fs.discrete.height);
        } else if (fs.type == V4L2_FRMSIZE_TYPE_CONTINUOUS) {
            printf("  Continuous range: %dx%d - %dx%d\n", fs.continuous.min_width, fs.continuous.min_height, fs.continuous.max_width, fs.continuous.max_height);
        } else if (fs.type == V4L2_FRMSIZE_TYPE_STEPWISE) {
            printf("  Stepwise range: %dx%d - %dx%d, step %dx%d\n", fs.stepwise.min_width, fs.stepwise.min_height, fs.stepwise.max_width, fs.stepwise.max_height, fs.stepwise.step_width, fs.stepwise.step_height);
        } else {
            fprintf(stderr, "Error: Unknown frame size type\n");
            return -1;
        }

        fs.index++;
        if (fs.index >= MAX_FRAME_SIZES) {
            fprintf(stderr, "Warning: Maximum frame sizes reached.  Some sizes may be missing.\n");
            break;
        }
    }

    return 0;
}

// Function to enumerate supported frame intervals
int enumerate_frame_intervals(int fd, int width, int height) {
    struct v4l2_frmivalenum fi;
    int i = 0;

    fi.index = 0;
    fi.pixel_format = V4L2_PIX_FMT_YUYV; // Common format
    fi.width = width;
    fi.height = height;

    printf("  Supported Frame Rates (%dx%d):\n", width, height);
    while (1) {
        if (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &fi) < 0) {
            if (errno == EINVAL) {
                break; // No more frame intervals
            } else {
                perror("VIDIOC_ENUM_FRAMEINTERVALS failed");
                return -1;
            }
        }

        if (fi.type == V4L2_FRMIVAL_TYPE_DISCRETE) {
            printf("    %d/%d\n", fi.discrete.numerator, fi.discrete.denominator);
        } else if (fi.type == V4L2_FRMIVAL_TYPE_CONTINUOUS) {
            printf("    Continuous range: %d/%d - %d/%d\n", fi.continuous.min_numerator, fi.continuous.min_denominator, fi.continuous.max_numerator, fi.continuous.max_denominator);
        } else if (fi.type == V4L2_FRMIVAL_TYPE_STEPWISE) {
            printf("    Stepwise range: %d/%d - %d/%d, step %d/%d\n", fi.stepwise.min_numerator, fi.stepwise.min_denominator, fi.stepwise.max_numerator, fi.stepwise.max_denominator, fi.stepwise.step_numerator, fi.stepwise.step_denominator);
        } else {
            fprintf(stderr, "Error: Unknown frame interval type\n");
            return -1;
        }

        fi.index++;
        if (fi.index >= MAX_FRAME_INTERVALS) {
            fprintf(stderr, "Warning: Maximum frame intervals reached.  Some intervals may be missing.\n");
            break;
        }
    }

    return 0;
}

// Function to check autofocus support
int check_autofocus_support(int fd) {
    struct v4l2_queryctrl qc;

    qc.id = V4L2_CID_FOCUS_AUTO;

    if (ioctl(fd, VIDIOC_QUERYCTRL, &qc) < 0) {
        if (errno == EINVAL) {
            printf("Autofocus control not supported\n");
            return 0;
        } else {
            perror("VIDIOC_QUERYCTRL failed");
            return -1;
        }
    }

    if (qc.flags & V4L2_CTRL_FLAG_DISABLED) {
        printf("Autofocus control disabled\n");
        return 0;
    }

    printf("Autofocus control supported\n");
    return 1;
}

int main() {
    int fd;

    // Open the device
    fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        perror("Failed to open device");
        error_exit("Failed to open device");
    }

    // Query camera capabilities
    if (query_camera_capabilities(fd) < 0) {
        close(fd);
        error_exit("Failed to query camera capabilities");
    }

    // Enumerate supported frame sizes
    if (enumerate_frame_sizes(fd) < 0) {
        close(fd);
        error_exit("Failed to enumerate frame sizes");
    }

    // Check autofocus support
    if (check_autofocus_support(fd) < 0) {
        close(fd);
        error_exit("Failed to check autofocus support");
    }

    // Close the device
    close(fd);

    return 0;
}

