#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define UP_BUTTON_PIN 6
#define DOWN_BUTTON_PIN 7
#define LEFT_BUTTON_PIN 8
#define RIGHT_BUTTON_PIN 9

// Define servo pulse width limits
#define SERVO_MIN_PULSE_WIDTH 1000
#define SERVO_MAX_PULSE_WIDTH 2000

// Define center position
#define SERVO_CENTER_POSITION 1500

// Define movement increment
#define SERVO_MOVEMENT_INCREMENT 10

// Global variables for servo positions
int pan_position = SERVO_CENTER_POSITION;
int tilt_position = SERVO_CENTER_POSITION;

// Function prototypes
void initialize_gpio();
void set_servo_position(int pin, int position);
int read_button(int pin);
void move_servo(int pin, int direction);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioServo(PAN_SERVO_PIN, 0); // Stop PWM on pan servo
    gpioServo(TILT_SERVO_PIN, 0); // Stop PWM on tilt servo
    gpioTerminate(); // Terminate pigpio
    exit(0); // Exit program
}

// Function to initialize GPIO pins
void initialize_gpio() {
    // Set servo pins as outputs
    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);

