#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <curl/curl.h>
#include <pigpio.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <errno.h>

#define GPIO_PIN 17
#define DEBOUNCE_TIME 2 // seconds
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_QUALITY 85
#define SERVER_URL "http://localhost:8080/upload" // Default server URL

static volatile int running = 1;
static time_t last_motion_time = 0;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, exiting gracefully...\n");
    running = 0;
}

// Function to initialize pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    return 0;
}

// Function to capture a timestamped JPEG image
int capture_image(char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "libcamera-still -o %s -n -t 1 --width %d --height %d --quality %d", filename, IMAGE_WIDTH, IMAGE_HEIGHT, IMAGE_QUALITY);

    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "Error executing libcamera-still command\n");
        return -1;
    } else if (WEXITSTATUS(status) != 0) {
        fprintf(stderr, "libcamera-still command failed with exit status %d\n", WEXITSTATUS(status));
        return -1;
    }

    return 0;
}

// Function to get the current timestamp in ISO 8601 format with microseconds
int get_timestamp(char *timestamp) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    strftime(timestamp, 30, "%Y-%m-%dT%H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), 10, ".%06ldZ", ts.tv_nsec / 1000);

    return 0;
}

// Function to create the motion_captures directory if it doesn't exist
int create_directory(const char *path) {
    if (mkdir(path, 0777) == -1) {
        if (errno != EEXIST) {
            fprintf(stderr, "Error creating directory %s: %s\n", path, strerror(errno));
            return -1;
        }
    }
    return 0;
}

// Function to send a JSON payload to the server
int send_data(const char *filename, const char *timestamp, int motion_status) {
    CURL *curl;
    CURLcode res;
    char json_payload[512];

    snprintf(json_payload, sizeof(json_payload), 
             "{\"filename\": \"%s\", \"timestamp\": \"%s\", \"motion\": %d, \"gpio_pin\": %d}",
             filename, timestamp, motion_status, GPIO_PIN);

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, SERVER_URL);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_payload);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }

        curl_easy_cleanup(curl);
    }
    curl_global_cleanup();
    return (res == CURLE_OK) ? 0 : -1;
}

int main(int argc, char *argv[]) {
    char server_ip[64] = "localhost"; // Default IP
    int server_port = 8080;           // Default port

    if (argc > 1) {
        strncpy(server_ip, argv[1], sizeof(server_ip) - 1);
        server_ip[sizeof(server_ip) - 1] = '\0'; // Ensure null termination
    }
    if (argc > 2) {
        server_port = atoi(argv[2]);
    }

    snprintf(SERVER_URL, 256, "http://%s:%d/upload", server_ip, server_port);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize_gpio() != 0) {
        return 1;
    }

    if (create_directory("motion_captures") != 0) {
        gpioTerminate();
        return 1;
    }

    while (running) {
        int motion_detected = gpioRead(GPIO_PIN);

        if (motion_detected) {
            time_t current_time = time(NULL);
            if (difftime(current_time, last_motion_time) >= DEBOUNCE_TIME) {
                char timestamp[30];
                get_timestamp(timestamp);

                char filename[128];
                snprintf(filename, sizeof(filename), "motion_captures/motion_%s.jpg", timestamp);

                if (capture_image(filename) == 0) {
                    if (send_data(filename, timestamp, 1) != 0) {
                        fprintf(stderr, "Failed to send data to server\n");
                    }
                } else {
                    fprintf(stderr, "Failed to capture image\n");
                }

                last_motion_time = current_time;
            }
        } else {
            // Check if it's been a while since the last motion
            time_t current_time = time(NULL);
            if (last_motion_time != 0 && difftime(current_time, last_motion_time) >= DEBOUNCE_TIME) {
                char timestamp[30];
                get_timestamp(timestamp);

                char filename[128];
                snprintf(filename, sizeof(filename), "motion_captures/no_motion_%s.jpg", timestamp);

                if (capture_image(filename) == 0) {
                    if (send_data(filename, timestamp, 0) != 0) {
                        fprintf(stderr, "Failed to send data to server\n");
                    }
                } else {
                    fprintf(stderr, "Failed to capture image\n");
                }

                last_motion_time = current_time;
            }
        }

        gpioDelay(100); // Check every 100ms
    }

    gpioTerminate();
    return 0;
}

