#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <fcntl.h>
#include <syslog.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define IMAGE_DIR "/home/pi/images"
#define LOG_FILE "/home/pi/motion_capture.log"
#define DEBOUNCE_MS 50
#define TIMEOUT_S 1

static volatile int running = 1;
static int gpio_handle = -1;
static FILE *log_file = NULL;

// Function to generate a timestamped filename
char* generate_filename() {
    time_t rawtime;
    struct tm *timeinfo;
    char *filename = (char*)malloc(64 * sizeof(char));
    if (filename == NULL) {
        perror("Failed to allocate memory for filename");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(filename, 64, "%Y%m%d_%H%M%S_%3d.jpg", timeinfo);
    return filename;
}

// Function to capture an image using libcamera-still
int capture_image(const char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "libcamera-still -o %s --width 640 --height 480 -q 85 --timeout 2000 --nopreview", filename);
    int status = system(command);
    if (status == -1) {
        perror("Failed to execute libcamera-still");
        return -1;
    }
    return WEXITSTATUS(status);
}

// Function to log an event to the log file
void log_event(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
    syslog(LOG_INFO, "%s: %s", timestamp, message);
}

// Function to handle motion detection
void handle_motion() {
    char *filename = generate_filename();
    if (filename == NULL) {
        log_event("Failed to generate filename");
        return;
    }

    int status = capture_image(filename);
    if (status != 0) {
        char error_message[128];
        snprintf(error_message, sizeof(error_message), "Image capture failed with status %d", status);
        log_event(error_message);
    } else {
        char log_message[128];
        snprintf(log_message, sizeof(log_message), "Image captured: %s", filename);
        log_event(log_message);
    }

    free(filename);
}

// Callback function for GPIO interrupt
void motion_detected_callback(int gpio, int level, uint32_t tick) {
    if (level == 0) { // Falling edge
        gpioDelay(DEBOUNCE_MS * 1000); // Debounce
        handle_motion();
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_event("Received signal, shutting down...");
    if (gpio_handle != -1) {
        gpioSetAlertFuncEx(gpio_handle, NULL, NULL); // Disable callback
        gpioTerminate();
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    closelog();
    exit(0);
}

int main() {
    // Initialize syslog
    openlog("motion_capture", LOG_PID | LOG_CONS, LOG_USER);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_event("pigpio initialisation failed");
        fclose(log_file);
        closelog();
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Open GPIO handle
    gpio_handle = gpioInitialise();
    if (gpio_handle < 0) {
        log_event("Failed to open GPIO handle");
        gpioTerminate();
        fclose(log_file);
        closelog();
        return 1;
    }

    // Set alert function for falling edge detection
    if (gpioSetAlertFuncEx(gpio_handle, motion_detected_callback, NULL) != 0) {
        log_event("Failed to set alert function");
        gpioTerminate();
        fclose(log_file);
        closelog();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Motion capture service started");

    // Main loop
    while (running) {
        sleep(1); // Check for signals every second
    }

    return 0;
}

