    openlog("motion_capture", LOG_PID | LOG_CONS, LOG_USER);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_event("pigpio initialisation failed");
        fclose(log_file);
        closelog();
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Open GPIO handle
    gpio_handle = gpioInitialise();
    if (gpio_handle < 0) {
        log_event("Failed to open GPIO handle");
        gpioTerminate();
        fclose(log_file);
        closelog();
        return 1;
    }

    // Set alert function for falling edge detection
    if (gpioSetAlertFuncEx(gpio_handle, motion_detected_callback, NULL) != 0) {
        log_event("Failed to set alert function");
        gpioTerminate();
        fclose(log_file);
        closelog();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Motion capture service started");

    // Main loop
    while (running) {
        sleep(1); // Check for signals every second
    }

    return 0;
}

