int main()
{
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    enum v4l2_buf_type type;
    unsigned int i;
    unsigned char *cropped_frame = NULL;
    size_t cropped_frame_size = CROP_WIDTH * CROP_HEIGHT * 2; // YUYV

    // Install signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open device
    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening device");
        return EXIT_FAILURE;
    }

    // Query capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(fd);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        close(fd);
        return EXIT_FAILURE;
    }

    // Set format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(fd);
        return EXIT_FAILURE;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = 1; // Single buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(fd);
        return EXIT_FAILURE;
    }

    n_buffers = req.count;
    buffers = calloc(n_buffers, sizeof(*buffers));
    if (!buffers) {
        perror("Out of memory");
        close(fd);
        return EXIT_FAILURE;
    }

    // Map buffers
    for (i = 0; i < n_buffers; ++i) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("Error querying buffer");
            close(fd);
            free(buffers);
            return EXIT_FAILURE;
        }

        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (buffers[i].start == MAP_FAILED) {
            perror("Error mapping buffer");
            close(fd);
            free(buffers);
            return EXIT_FAILURE;
        }
    }

    // Queue buffer
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        close(fd);
        for (unsigned int j = 0; j < n_buffers; ++j) {
            if (buffers[j].start != NULL) {
                munmap(buffers[j].start, buffers[j].length);
            }
        }
        free(buffers);
        return EXIT_FAILURE;
    }

    // Start streaming
    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting streaming");
        close(fd);
        for (unsigned int j = 0; j < n_buffers; ++j) {
            if (buffers[j].start != NULL) {
                munmap(buffers[j].start, buffers[j].length);
            }
        }
        free(buffers);
        return EXIT_FAILURE;
    }

    // Select for I/O
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2;  // Timeout of 2 seconds
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        perror("Error during select");
        close(fd);
        for (unsigned int j = 0; j < n_buffers; ++j) {
            if (buffers[j].start != NULL) {
                munmap(buffers[j].start, buffers[j].length);
            }
        }
        free(buffers);
        return EXIT_FAILURE;
    } else if (r == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        close(fd);
        for (unsigned int j = 0; j < n_buffers; ++j) {
            if (buffers[j].start != NULL) {
                munmap(buffers[j].start, buffers[j].length);
            }
        }
        free(buffers);
        return EXIT_FAILURE;
    }

    // Dequeue buffer
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        close(fd);
        for (unsigned int j = 0; j < n_buffers; ++j) {
            if (buffers[j].start != NULL) {
                munmap(buffers[j].start, buffers[j].length);
            }
        }
        free(buffers);
        return EXIT_FAILURE;
    }

    // Verify format
    if (buf.width != 640 || buf.height != 480 || buf.bytesperline != 1280 || buf.field != V4L2_FIELD_NONE) {
        fprintf(stderr, "Captured format does not match requested format\n");
        close(fd);
        for (unsigned int j = 0; j < n_buffers; ++j) {
            if (buffers[j].start != NULL) {
                munmap(buffers[j].start, buffers[j].length);
            }
        }
        free(buffers);
        return EXIT_FAILURE;
    }

    // Allocate memory for cropped frame
    cropped_frame = malloc(cropped_frame_size);
    if (!cropped_frame) {
        perror("Out of memory");
        close(fd);
        for (unsigned int j = 0; j < n_buffers; ++j) {
            if (buffers[j].start != NULL) {
                munmap(buffers[j].start, buffers[j].length);
            }
        }
        free(buffers);
        return EXIT_FAILURE;
    }

    // Crop frame
    unsigned char *src = (unsigned char *)buffers[0].start;
    unsigned char *dst = cropped_frame;

    for (int y = 0; y < CROP_HEIGHT; ++y) {
        for (int x = 0; x < CROP_WIDTH; ++x) {
            // Calculate source and destination offsets
            int src_offset = (CROP_Y + y) * 1280 + (CROP_X + x) * 2;
            int dst_offset = y * CROP_WIDTH * 2 + x * 2;

            // Copy 4 bytes (Y0, U, Y1, V) as a unit
            memcpy(dst + dst_offset, src + src_offset, 4);
        }
    }

    // Open output file
    output_file = fopen("cropped.yuv", "wb");
    if (!output_file) {
        perror("Error opening output file");
        close(fd);
        for (unsigned int j = 0; j < n_buffers; ++j) {
            if (buffers[j].start != NULL) {
                munmap(buffers[j].start, buffers[j].length);
            }
        }
        free(buffers);
        free(cropped_frame);
        return EXIT_FAILURE;
    }

    // Write cropped frame to file
    if (fwrite(cropped_frame, 1, cropped_frame_size, output_file) != cropped_frame_size) {
        perror("Error writing to output file");
        fclose(output_file);
        close(fd);
        for (unsigned int j = 0; j < n_buffers; ++j) {
            if (buffers[j].start != NULL) {
                munmap(buffers[j].start, buffers[j].length);
            }
        }
        free(buffers);
        free(cropped_frame);
        return EXIT_FAILURE;
    }

    // Requeue buffer
    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error requeuing buffer");
        fclose(output_file);
        close(fd);
        for (unsigned int j = 0; j < n_buffers; ++j) {
            if (buffers[j].start != NULL) {
                munmap(buffers[j].start, buffers[j].length);
            }
        }
        free(buffers);
        free(cropped_frame);
        return EXIT_FAILURE;
    }

    // Stop streaming
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Error stopping streaming");
        fclose(output_file);
        close(fd);
        for (unsigned int j = 0; j < n_buffers; ++j) {
            if (buffers[j].start != NULL) {
                munmap(buffers[j].start, buffers[j].length);
            }
        }
        free(buffers);
        free(cropped_frame);
        return EXIT_FAILURE;
    }

    // Clean up
    fclose(output_file);
    close(fd);
    for (unsigned int i = 0; i < n_buffers; ++i) {
        munmap(buffers[i].start, buffers[i].length);
    }
    free(buffers);
    free(cropped_frame);

    printf("Frame captured and cropped successfully\n");
    return EXIT_SUCCESS;
}

