#include <pigpio.h>

// Define GPIO pins for pan and tilt servos
#define PAN_GPIO 17
#define TILT_GPIO 18

// Define PWM frequency (50 Hz)
#define PWM_FREQUENCY 50

// Define pulse width limits (microseconds)
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500

// Define angle limits (degrees)
#define MIN_ANGLE 0
#define MAX_ANGLE 180

// Define angle increment
#define ANGLE_INCREMENT 5

// Global variables for pan and tilt angles
int pan_angle = 90;
int tilt_angle = 90;

// Function prototypes
int angle_to_pulse_width(int angle);
int set_servo_angle(int gpio, int angle);
void signal_handler(int signal);

// Function to convert angle (0-180) to pulse width (500-2500)
int angle_to_pulse_width(int angle) {
    return (int)(((float)angle / 180.0) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) + MIN_PULSE_WIDTH);
}

// Function to set the servo angle
int set_servo_angle(int gpio, int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Angle out of range (0-180).\n");
        return -1; // Indicate failure
    }

    int pulse_width = angle_to_pulse_width(angle);
    if (gpioPWM(gpio, pulse_width) != 0) {
        fprintf(stderr, "Error: Failed to set PWM for GPIO %d.\n", gpio);
        return -1; // Indicate failure
    }

    return 0; // Indicate success
}

// Signal handler for Ctrl+C and 'q' input
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Set servos to neutral position
    if (set_servo_angle(PAN_GPIO, 90) != 0) {
        fprintf(stderr, "Error: Failed to set pan servo to neutral.\n");
    }
    if (set_servo_angle(TILT_GPIO, 90) != 0) {
        fprintf(stderr, "Error: Failed to set tilt servo to neutral.\n");
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1; // Exit with error code
    }

    // Set GPIO modes for pan and tilt servos
    gpioSetMode(PAN_GPIO, PI_OUTPUT);
    gpioSetMode(TILT_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(TILT_GPIO, PWM_FREQUENCY);

    // Set PWM range (optional, but recommended for finer control)
    gpioSetPWMrange(PAN_GPIO, 2500); // Range of 0-2500
    gpioSetPWMrange(TILT_GPIO, 2500);

    // Register signal handler for Ctrl+C and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Pan-Tilt Camera Control\n");
    printf("Use arrow keys to move, 'q' to quit.\n");

    // Main loop
    while (1) {
        int c = getchar();

        switch (c) {
            case 'a': // Left arrow key
                pan_angle -= ANGLE_INCREMENT;
                if (pan_angle < MIN_ANGLE) {
                    pan_angle = MIN_ANGLE;
                }
                if (set_servo_angle(PAN_GPIO, pan_angle) != 0) {
                    fprintf(stderr, "Error setting pan angle.\n");
                }
                break;
            case 'd': // Right arrow key
                pan_angle += ANGLE_INCREMENT;
                if (pan_angle > MAX_ANGLE) {
                    pan_angle = MAX_ANGLE;
                }
                if (set_servo_angle(PAN_GPIO, pan_angle) != 0) {
                    fprintf(stderr, "Error setting pan angle.\n");
                }
                break;
            case 'w': // Up arrow key
                tilt_angle += ANGLE_INCREMENT;
                if (tilt_angle > MAX_ANGLE) {
                    tilt_angle = MAX_ANGLE;
                }
                if (set_servo_angle(TILT_GPIO, tilt_angle) != 0) {
                    fprintf(stderr, "Error setting tilt angle.\n");
                }
                break;
            case 's': // Down arrow key
                tilt_angle -= ANGLE_INCREMENT;
                if (tilt_angle < MIN_ANGLE) {
                    tilt_angle = MIN_ANGLE;
                }
                if (set_servo_angle(TILT_GPIO, tilt_angle) != 0) {
                    fprintf(stderr, "Error setting tilt angle.\n");
                }
                break;
            case 'q': // 'q' key to quit
                signal_handler(SIGINT); // Call signal handler to exit gracefully
                break;
            default:
                // Ignore other inputs
                break;
        }

        usleep(100000); // 100 ms delay
    }

    return 0; // This line will not be reached due to the infinite loop
}

