// Function to read CPU temperature from /sys/class/thermal/thermal_zone0/temp
int read_cpu_temp() {
    FILE *fp;
    int temp = -1;

    fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open temperature file.\n");
        return -1;
    }

    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "Error: Could not read temperature from file.\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return temp / 1000; // Convert to degrees Celsius
}

// Function to read CPU usage percentage from /proc/stat
int read_cpu_usage() {
    FILE *fp;
    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    unsigned long long prev_user, prev_nice, prev_system, prev_idle, prev_iowait, prev_irq, prev_softirq, prev_steal, prev_guest, prev_guest_nice;
    static unsigned long long prev_total = 0;
    static unsigned long long prev_idle_total = 0;
    int usage = 0;

    fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open /proc/stat file.\n");
        return -1;
    }

    if (fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        fprintf(stderr, "Error: Could not read CPU stats from /proc/stat.\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);

    unsigned long long total = user + nice + system + idle + iowait + irq + softirq + steal + guest + guest_nice;
    unsigned long long idle_total = idle + iowait;

    if (prev_total != 0) {
        unsigned long long total_diff = total - prev_total;
        unsigned long long idle_diff = idle_total - prev_idle_total;

        usage = (100 * (total_diff - idle_diff)) / total_diff;
    }

    prev_total = total;
    prev_idle_total = idle_total;

    return usage;
}

// Function to display text on the OLED screen
void display_text(int x, int y, const char *text) {
    int i, j, k;
    unsigned char buffer[OLED_WIDTH * OLED_HEIGHT / 8];
    memset(buffer, 0, sizeof(buffer));

    for (i = 0; text[i] != '\0'; i++) {
        char c = text[i];
        if (c < 32 || c > 126) c = 0; // Handle out-of-range characters (use space)
        c -= 32; // Adjust index to font array

        for (j = 0; j < 5; j++) {
            for (k = 0; k < 8; k++) {
                if ((font[c][j] >> k) & 0x01) {
                    int pixel_x = x + (i * 6) + j; // 6 pixels per character (5 + 1 space)
                    int pixel_y = y + k;
                    if (pixel_x >= 0 && pixel_x < OLED_WIDTH && pixel_y >= 0 && pixel_y < OLED_HEIGHT) {
                        int byte_index = pixel_x / 8;
                        int bit_index = pixel_x % 8;
                        buffer[byte_index + (pixel_y * (OLED_WIDTH / 8))] |= (1 << bit_index);
                    }
                }
            }
        }
    }

    // Send data to OLED
    char data[OLED_WIDTH * OLED_HEIGHT / 8 + 1];
    data[0] = 0x40; // Data command
    memcpy(data + 1, buffer, OLED_WIDTH * OLED_HEIGHT / 8);

    if (i2cWriteDevice(i2c_handle, data, OLED_WIDTH * OLED_HEIGHT / 8 + 1) != OLED_WIDTH * OLED_HEIGHT / 8 + 1) {
        fprintf(stderr, "Error: I2C write failed (text).\n");
        gpioTerminate();
        exit(1);
    }
}

// Function to clear the OLED display
void clear_display() {
    char clear_data[OLED_WIDTH * OLED_HEIGHT / 8 + 1];
    clear_data[0] = 0x40; // Data command
    memset(clear_data + 1, 0x00, OLED_WIDTH * OLED_HEIGHT / 8);

    if (i2cWriteDevice(i2c_handle, clear_data, OLED_WIDTH * OLED_HEIGHT / 8 + 1) != OLED_WIDTH * OLED_HEIGHT / 8 + 1) {
        fprintf(stderr, "Error: I2C write failed (clear).\n");
        gpioTerminate();
        exit(1);
    }
}

// Function to initialize the SSD1306 OLED display
void oled_init() {
    // Initialization sequence (adjust as needed for your specific OLED)
    char init_data[] = {
        0x00, // Command stream
        0xAE, // Display off
        0xD5, // Set display clock divide ratio/oscillator frequency
        0x80, // --ratio
        0xA8, // Set multiplex ratio
        0x3F, // --ratio
        0xD3, // Set display offset
        0x00, // --offset
        0x40, // Set start line address
        0x8D, // Charge pump setting
        0x14, // --enable
        0x20, // Set memory addressing mode
        0x00, // --mode
        0xA1, // Set segment re-map
        0xC8, // Set COM output scan direction
        0xDA, // Set COM pins hardware configuration
        0x12, // --config
        0x81, // Set contrast control
        0xCF, // --contrast
        0xD9, // Set pre-charge period
        0xF1, // --period
        0xDB, // Set VCOM deselect level
        0x40, // --level
        0xA4, // Set entire display on/off
        0xA6, // Set normal/inverse display
        0xAF  // Display on
    };

    if (i2cWriteDevice(i2c_handle, init_data, sizeof(init_data)) != sizeof(init_data)) {
        fprintf(stderr, "Error: I2C write failed (init).\n");
        gpioTerminate();
        exit(1);
    }
}

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, OLED_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize OLED display
    oled_init();

    // Set up signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read CPU temperature
        int temp = read_cpu_temp();
        char temp_str[20];
        if (temp == -1) {
            strcpy(temp_str, "Temp Err");
        } else {
            sprintf(temp_str, "Temp: %d C", temp);
        }

        // Read CPU usage
        int usage = read_cpu_usage();
        char usage_str[20];
        if (usage == -1) {
            strcpy(usage_str, "Usage Err");
        } else {
            sprintf(usage_str, "Usage: %d%%", usage);
        }

        // Clear the display
        clear_display();

        // Display temperature and usage
        display_text(0, 0, temp_str);
        display_text(0, 16, usage_str);

        // Wait for 1 second
        sleep(1);
    }

    // Close I2C connection and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

