#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>

// Constants
#define FLOW_SENSOR_GPIO 17
#define PULSES_PER_LITER 450.0
#define LCD_I2C_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_HEIGHT 2

// Global variables
volatile int pulse_count = 0;
double total_volume = 0.0;
int i2c_handle;
int running = 1;

// Function prototypes
void pulse_counter(int gpio, int level, uint32_t tick, void *user_data);
double calculate_flow_rate(int pulses);
double calculate_total_volume(double flow_rate, double time_interval);
void update_lcd(double flow_rate, double total_volume);
void signal_handler(int signal);

// Interrupt handler for pulse counting
void pulse_counter(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == PI_HIGH) {
        pulse_count++;
    }
}

// Function to calculate flow rate in liters per minute
double calculate_flow_rate(int pulses) {
    return (double)pulses / PULSES_PER_LITER * 60.0;
}

// Function to calculate total volume in liters
double calculate_total_volume(double flow_rate, double time_interval) {
    return total_volume + flow_rate * time_interval / 60.0;
}

// Function to update the LCD display
void update_lcd(double flow_rate, double total_volume) {
    char line1[17], line2[17];

    snprintf(line1, sizeof(line1), "Flow: %.2f L/min", flow_rate);
    snprintf(line2, sizeof(line2), "Total: %.2f L", total_volume);

    // Clear the LCD
    char clear_cmd[2] = {0x01, 0x00}; // Clear display command
    if (i2cWriteDevice(i2c_handle, clear_cmd, 1) != 0) {
        fprintf(stderr, "Error: Failed to clear LCD\n");
        return;
    }
    gpioDelay(2); // Delay for clear command to execute

    // Set cursor to the first line
    char set_cursor_cmd[2] = {0x80, 0x00}; // Set cursor to address 0
    if (i2cWriteDevice(i2c_handle, set_cursor_cmd, 1) != 0) {
        fprintf(stderr, "Error: Failed to set cursor to line 1\n");
        return;
    }

    // Write the first line
    if (i2cWriteDevice(i2c_handle, line1, strlen(line1)) != 0) {
        fprintf(stderr, "Error: Failed to write to LCD line 1\n");
        return;
    }

    // Set cursor to the second line
    char set_cursor_cmd2[2] = {0xC0, 0x00}; // Set cursor to address 0x40
    if (i2cWriteDevice(i2c_handle, set_cursor_cmd2, 1) != 0) {
        fprintf(stderr, "Error: Failed to set cursor to line 2\n");
        return;
    }

    // Write the second line
    if (i2cWriteDevice(i2c_handle, line2, strlen(line2)) != 0) {
        fprintf(stderr, "Error: Failed to write to LCD line 2\n");
        return;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as input
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);

    // Set pull-up/down resistor (optional, adjust as needed)
    gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_UP);

    // Initialize I2C
    i2c_handle = i2cOpen(1, LCD_I2C_ADDR, 0); // Bus 1, address 0x27, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up interrupt handler for pulse counting
    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, pulse_counter, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set ISR function\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    time_t start_time, current_time;
    time(&start_time);
    while (running) {
        time(&current_time);
        double time_elapsed = difftime(current_time, start_time);

        // Calculate flow rate and total volume every 1 second
        if (time_elapsed >= 1.0) {
            double flow_rate = calculate_flow_rate(pulse_count);
            total_volume = calculate_total_volume(flow_rate, 1.0);
            printf("Flow Rate: %.2f L/min, Total Volume: %.2f L\n", flow_rate, total_volume);
            pulse_count = 0; // Reset pulse count
            time(&start_time); // Reset start time
        }

        // Update LCD every 10 seconds
        if (time_elapsed >= 10.0) {
            update_lcd(flow_rate, total_volume);
            time(&start_time); // Reset start time
        }

        gpioDelay(100); // Small delay to reduce CPU usage
    }

    // Cleanup
    gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, NULL, NULL); // Disable interrupt
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

