#define SPI_SPEED 1000000 // 1 MHz
#define I2C_ADDR 0x27
#define I2C_BUS 1
#define WIND_SPEED_FACTOR 0.5 // m/s per pulse
#define WIND_DIRECTION_MIN_ADC 0
#define WIND_DIRECTION_MAX_ADC 1023
#define WIND_DIRECTION_MIN_ANGLE 0
#define WIND_DIRECTION_MAX_ANGLE 359
#define WIND_DIRECTION_STUCK_THRESHOLD 5 // seconds
#define WIND_SPEED_STUCK_THRESHOLD 5 // seconds

// Global variables
static volatile int anemometer_count = 0;
static volatile int spi_handle = -1;
static volatile int i2c_handle = -1;
static volatile int running = 1;
static volatile int last_wind_direction_adc = -1;
static volatile double last_wind_speed = -1.0;
static volatile time_t last_wind_direction_change = 0;
static volatile time_t last_wind_speed_change = 0;

// Function prototypes
void anemometer_isr(int gpio, int level, uint32_t tick, void *user);
int read_wind_direction();
double calculate_wind_speed(int pulse_count);
void display_data(double wind_speed, int wind_direction);
void signal_handler(int signal);
