void cleanup();

// Anemometer interrupt service routine
void anemometer_isr(int gpio, int level, uint32_t tick, void *user)
{
    if (level == PI_HIGH) // Rising edge
    {
        anemometer_count++;
    }
}

// Function to read wind direction from MCP3008
int read_wind_direction()
{
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];
    int adc_value;

    // MCP3008 configuration: single-ended channel 0, start bit
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = 0x80; // Single-ended, channel 0 (10000000)
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1; // Indicate error
    }

    // Extract the 10-bit ADC value from the response
    adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to calculate wind speed
double calculate_wind_speed(int pulse_count)
{
    return pulse_count * WIND_SPEED_FACTOR;
}

