    if (gpioSetISRFuncEx(ANEMOMETER_GPIO, RISING_EDGE, 0, anemometer_isr, NULL) != 0)
    {
        fprintf(stderr, "Error: Failed to set up interrupt on GPIO %d\n", ANEMOMETER_GPIO);
        gpioTerminate();
        return 1;
    }

