    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0)
    {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0)
    {
        fprintf(stderr, "Error: I2C open failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup function
void cleanup()
{
    // Disable interrupt
    gpioSetISRFuncEx(ANEMOMETER_GPIO, RISING_EDGE, 0, NULL, NULL);

    // Close SPI and I2C
    if (spi_handle >= 0) spiClose(spi_handle);
    if (i2c_handle >= 0) i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();
}

int main()
{
    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize())
    {
        return 1;
    }

    int pulse_count;
    double wind_speed;
    int wind_direction;
    time_t current_time;

    while (running)
    {
        // Read wind direction
        wind_direction = read_wind_direction();
        if (wind_direction == -1) {
