        }

        // Calculate wind speed
        pulse_count = anemometer_count;
        anemometer_count = 0; // Reset pulse count
        wind_speed = calculate_wind_speed(pulse_count);

        // Check for stuck wind direction
        current_time = time(NULL);
        if (last_wind_direction_adc != -1 && wind_direction == last_wind_direction_adc) {
            if (difftime(current_time, last_wind_direction_change) > WIND_DIRECTION_STUCK_THRESHOLD) {
                fprintf(stderr, "Warning: Wind direction sensor stuck at %d\n", wind_direction);
            }
        } else {
            last_wind_direction_change = current_time;
        }

        // Check for stuck wind speed
        if (last_wind_speed != -1.0 && wind_speed == last_wind_speed) {
            if (difftime(current_time, last_wind_speed_change) > WIND_SPEED_STUCK_THRESHOLD) {
                fprintf(stderr, "Warning: Wind speed sensor stuck at %.1f\n", wind_speed);
            }
        } else {
            last_wind_speed_change = current_time;
        }

        // Display data
        display_data(wind_speed, wind_direction);

        // Update last known values
        last_wind_speed = wind_speed;

        // Wait 500 ms
        gpioDelay(500);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

