#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <wiringPiI2C.h>

// Constants
#define FLOW_SENSOR_GPIO 17
#define LCD_I2C_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_CHR 1
#define LCD_CMD 0

#define LCD_BACKLIGHT 0x08  // Enable backlight
#define ENABLE 0b00000100 // Enable bit

// Global variables
volatile int pulse_count = 0;
int lcd_fd;
int running = 1;

// Function prototypes
void pulse_counter(int gpio, int level, uint32_t tick, void *user_data);
float calculate_flow_rate(int pulses);
void lcd_init();
void lcd_byte(int bits, int mode);
void lcd_string(const char *s);
void lcd_clear();
void lcd_set_cursor(int col, int row);
void signal_handler(int signal);

// Pulse counter function
void pulse_counter(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == PI_HIGH) {
        pulse_count++;
    }
}

// Calculate flow rate in L/min
float calculate_flow_rate(int pulses) {
    return (float)pulses / 7.5 / 10.0; // Calibration factor: 7.5 pulses/L, 10 seconds
}

// LCD initialization function
void lcd_init() {
    // Initialise display
    lcd_byte(0x33, LCD_CMD); // Initialise
    lcd_byte(0x32, LCD_CMD); // Initialise
    lcd_byte(0x06, LCD_CMD); // Cursor move direction
    lcd_byte(0x0C, LCD_CMD); // Turn on display, cursor off, blink off
    lcd_byte(0x28, LCD_CMD); // Data length, number of lines, font size
    lcd_byte(0x01, LCD_CMD); // Clear display
    gpioDelay(500);          // Delay 500ms
}

// Send byte to LCD in 4 bit mode
void lcd_byte(int bits, int mode) {
    // Send byte to data pins
    // bits = the data
    // mode = 1 for data, 0 for command
    int bits_high = mode | (bits & 0xF0) | LCD_BACKLIGHT;
    int bits_low = mode | ((bits << 4) & 0xF0) | LCD_BACKLIGHT;

    // High bits
    wiringPiI2CWriteReg8(lcd_fd, 0, bits_high);
    gpioDelay(1); // Delay 1ms
    wiringPiI2CWriteReg8(lcd_fd, 0, bits_high | ENABLE);
    gpioDelay(1); // Delay 1ms
    wiringPiI2CWriteReg8(lcd_fd, 0, bits_high & ~ENABLE);
    gpioDelay(1); // Delay 1ms

    // Low bits
    wiringPiI2CWriteReg8(lcd_fd, 0, bits_low);
    gpioDelay(1); // Delay 1ms
    wiringPiI2CWriteReg8(lcd_fd, 0, bits_low | ENABLE);
    gpioDelay(1); // Delay 1ms
    wiringPiI2CWriteReg8(lcd_fd, 0, bits_low & ~ENABLE);
    gpioDelay(1); // Delay 1ms
}

// Send string to LCD
void lcd_string(const char *s) {
    while (*s) {
        lcd_byte(*s++, LCD_CHR);
    }
}

// Clear LCD display
void lcd_clear() {
    lcd_byte(0x01, LCD_CMD);
    gpioDelay(500); // Delay 500ms
}

// Set cursor position
void lcd_set_cursor(int col, int row) {
    int row_offsets[] = {0x00, 0x40};
    lcd_byte(0x80 | (col + row_offsets[row]), LCD_CMD);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO mode for the flow sensor
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_UP); // Enable pull-up resistor

    // Set alert function for pulse counting
    gpioSetAlertFuncEx(FLOW_SENSOR_GPIO, pulse_counter, NULL);

    // Initialize wiringPi I2C
    lcd_fd = wiringPiI2CSetup(LCD_I2C_ADDR);
    if (lcd_fd == -1) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize LCD
    lcd_init();
    lcd_clear();
    lcd_set_cursor(0, 0);
    lcd_string("Flow Rate:");

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        int current_pulse_count = pulse_count;
        pulse_count = 0; // Reset pulse count for the next interval
        float flow_rate = calculate_flow_rate(current_pulse_count);
        char flow_rate_str[17];
        snprintf(flow_rate_str, sizeof(flow_rate_str), "X.XX L/min");
        if (flow_rate >= 0.0 && flow_rate < 100.0) {
            snprintf(flow_rate_str, sizeof(flow_rate_str), "%.2f L/min", flow_rate);
        } else if (flow_rate >= 100.0) {
            snprintf(flow_rate_str, sizeof(flow_rate_str), "100+ L/min");
        }

        lcd_set_cursor(0, 1);
        lcd_string(flow_rate_str);
        gpioDelay(1000); // Delay 1 second
    }

    // Cleanup
    gpioTerminate();
    return 0;
}

