void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to set the state of a row
void set_row(int row, int state) {
    switch (row) {
        case 0: gpioWrite(ROW1, state); break;
        case 1: gpioWrite(ROW2, state); break;
        case 2: gpioWrite(ROW3, state); break;
        case 3: gpioWrite(ROW4, state); break;
        case 4: gpioWrite(ROW5, state); break;
        case 5: gpioWrite(ROW6, state); break;
        case 6: gpioWrite(ROW7, state); break;
        case 7: gpioWrite(ROW8, state); break;
