#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <math.h>

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define row and column pin numbers
const int row_pins[] = {2, 3, 4, 17, 27, 22, 10, 9};
const int col_pins[] = {14, 15, 18, 23, 24, 25, 8, 7};

// Define the number of rows and columns
#define NUM_ROWS 8
#define NUM_COLS 8

// Global variables for GPIO chip and lines
struct gpiod_chip *chip;
struct gpiod_line *row_lines[NUM_ROWS];
struct gpiod_line *col_lines[NUM_COLS];

// Signal handler for Ctrl+C and SIGTERM
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    for (int i = 0; i < NUM_ROWS; i++) {
        if (row_lines[i]) {
            gpiod_line_release(row_lines[i]);
        }
    }
    for (int i = 0; i < NUM_COLS; i++) {
        if (col_lines[i]) {
            gpiod_line_release(col_lines[i]);
        }
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to set the state of a row
int set_row(int row, int state) {
    int ret = gpiod_line_set_value(row_lines[row], state);
    if (ret < 0) {
        fprintf(stderr, "Error setting row %d to %d: %s\n", row, state, strerror(-ret));
        return -1;
    }
    return 0;
}

// Function to set the state of a column
int set_column(int col, int state) {
    int ret = gpiod_line_set_value(col_lines[col], state);
    if (ret < 0) {
        fprintf(stderr, "Error setting column %d to %d: %s\n", col, state, strerror(-ret));
        return -1;
    }
    return 0;
}

// Function to clear the matrix
int clear_matrix() {
    for (int i = 0; i < NUM_COLS; i++) {
        if (set_column(i, 1) < 0) return -1; // Set column HIGH
    }
    for (int i = 0; i < NUM_ROWS; i++) {
        if (set_row(i, 0) < 0) return -1; // Set row LOW
    }
    return 0;
}

// Function to generate the wave pattern for a column
int generate_wave_pattern(int col, float time) {
    float amplitude = 0.5; // Adjust amplitude for brightness
    float frequency = 0.5; // Adjust frequency for wave speed
    float phase = 0.5 * M_PI; // Adjust phase for wave offset

    for (int row = 0; row < NUM_ROWS; row++) {
        float y = amplitude * sin(2 * M_PI * frequency * time + row * (M_PI / NUM_ROWS) + phase);
        int state = (y > 0) ? 1 : 0; // Set row HIGH if y > 0, LOW otherwise
        if (set_row(row, state) < 0) return -1;
    }
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIOCHIP, strerror(errno));
        return 1;
    }

    // Request row lines for output
    for (int i = 0; i < NUM_ROWS; i++) {
        row_lines[i] = gpiod_chip_get_line(chip, row_pins[i]);
        if (!row_lines[i]) {
            fprintf(stderr, "Error getting row line %d: %s\n", row_pins[i], strerror(errno));
            goto cleanup;
        }
        struct gpiod_line_request_config config;
        memset(&config, 0, sizeof(config));
        config.consumer = "led_matrix";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
        int ret = gpiod_line_request(row_lines[i], &config, 0);
        if (ret < 0) {
            fprintf(stderr, "Error requesting row line %d: %s\n", row_pins[i], strerror(-ret));
            goto cleanup;
        }
    }

    // Request column lines for output
    for (int i = 0; i < NUM_COLS; i++) {
        col_lines[i] = gpiod_chip_get_line(chip, col_pins[i]);
        if (!col_lines[i]) {
            fprintf(stderr, "Error getting column line %d: %s\n", col_pins[i], strerror(errno));
            goto cleanup;
        }
        struct gpiod_line_request_config config;
        memset(&config, 0, sizeof(config));
        config.consumer = "led_matrix";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
        int ret = gpiod_line_request(col_lines[i], &config, 0);
        if (ret < 0) {
            fprintf(stderr, "Error requesting column line %d: %s\n", col_pins[i], strerror(-ret));
            goto cleanup;
        }
    }

    // Main loop
    while (1) {
        for (int col = 0; col < NUM_COLS; col++) {
            if (clear_matrix() < 0) {
                goto cleanup;
            }

            if (set_column(col, 0) < 0) {
                goto cleanup;
            }

            for (float time = 0; time < 1; time += 0.01) {
                if (generate_wave_pattern(col, time) < 0) {
                    goto cleanup;
                }
                usleep(1000); // Small delay for smooth wave
            }

            usleep(150000); // Delay between columns (150 ms)
        }
    }

cleanup:
    // Release GPIO lines
    for (int i = 0; i < NUM_ROWS; i++) {
        if (row_lines[i]) {
            gpiod_line_release(row_lines[i]);
        }
    }
    for (int i = 0; i < NUM_COLS; i++) {
        if (col_lines[i]) {
            gpiod_line_release(col_lines[i]);
        }
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 1;
}

