// Si1145 I2C address
#define SI1145_ADDR 0x60

// Si1145 register addresses
#define SI1145_REG_PART_ID 0x00
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_ALS_VIS_DATA1 0x23
#define SI1145_REG_PS1_DATA0 0x24
#define SI1145_REG_PS1_DATA1 0x25
#define SI1145_REG_COMMAND 0x18

// Si1145 commands
#define SI1145_RESET 0x01

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_si1145();
int read_si1145_data(int *proximity, int *ambient_light);
void log_data(int proximity, int ambient_light);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

// Initialize the Si1145 sensor
int init_si1145() {
    // Reset the sensor
    if (i2cWriteByteData(i2c_handle, SI1145_REG_COMMAND, SI1145_RESET) < 0) {
        fprintf(stderr, "Error resetting Si1145: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Verify PART ID
    int part_id = i2cReadByteData(i2c_handle, SI1145_REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART ID: %s\n", strerror(errno));
        return -1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Incorrect PART ID: 0x%02X\n", part_id);
        return -1;
    }

    // Configure the sensor (example configuration)
    if (i2cWriteByteData(i2c_handle, 0x07, 0x03) < 0) { // PS1_ADCMUX = Large IR
