#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define SENSOR_PIN 4
#define LED_PIN 17

// Define GPIO chip names
#define GPIOCHIP_NAME_4 "gpiochip4"
#define GPIOCHIP_NAME_0 "gpiochip0"

// Define log file name
#define LOG_FILE "proximity.log"

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *sensor_line = NULL;
static struct gpiod_line *led_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio(void);
int read_sensor(void);
int control_led(int state);
int log_event(void);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully.\n", sig);
}

// Initialize GPIO lines
int initialize_gpio(void) {
    struct gpiod_line_request_config config;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP_NAME_4);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIOCHIP_NAME_4, strerror(errno));
        chip = gpiod_chip_open_by_name(GPIOCHIP_NAME_0);
        if (!chip) {
            fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIOCHIP_NAME_0, strerror(errno));
            return -1;
        }
        fprintf(stderr, "Using fallback GPIO chip '%s'.\n", GPIOCHIP_NAME_0);
    }

    // Get sensor line
    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor_line) {
        fprintf(stderr, "Error getting sensor line %d: %s\n", SENSOR_PIN, strerror(errno));
        return -1;
    }

    // Get LED line
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Error getting LED line %d: %s\n", LED_PIN, strerror(errno));
        return -1;
    }

    // Request sensor line for input
    memset(&config, 0, sizeof(config));
    config.consumer = "proximity_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    if (gpiod_line_request(sensor_line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting sensor line for input: %s\n", strerror(errno));
        return -1;
    }

    // Request LED line for output
    memset(&config, 0, sizeof(config));
    config.consumer = "proximity_led";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    if (gpiod_line_request(led_line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting LED line for output: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read sensor value
int read_sensor(void) {
    int value = gpiod_line_get_value(sensor_line);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor value: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

// Control LED state
int control_led(int state) {
    if (gpiod_line_set_value(led_line, state) < 0) {
        fprintf(stderr, "Error setting LED value: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Log event to file
int log_event(void) {
    time_t rawtime;
    struct tm *info;
    char buffer[80];

    time(&rawtime);
    info = gmtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%SZ", info);

    fprintf(log_file, "%s Object detected\n", buffer);
    fflush(log_file); // Ensure the log is written immediately

    return 0;
}

// Cleanup GPIO resources
void cleanup_gpio(void) {
    printf("Cleaning up GPIO resources.\n");

    // Release GPIO lines
    if (sensor_line) {
        gpiod_line_release(sensor_line);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }
}

int main(void) {
    int sensor_value;
    int last_sensor_value = 1; // Assume no object initially

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed.\n");
        cleanup_gpio();
        return 1;
    }

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor value
        sensor_value = read_sensor();
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor, exiting.\n");
            break;
        }

        // Check for falling edge (HIGH to LOW)
        if (last_sensor_value == 1 && sensor_value == 0) {
            // Object detected
            printf("Object detected!\n");

            // Blink LED
            if (control_led(1) == 0) {
                usleep(100000); // 100 ms
                if (control_led(0) != 0) {
                    fprintf(stderr, "Error turning off LED.\n");
                }
            } else {
                fprintf(stderr, "Error turning on LED.\n");
            }

            // Log event
            if (log_event() != 0) {
                fprintf(stderr, "Error logging event.\n");
            }
        }

        last_sensor_value = sensor_value;
        usleep(100000); // 100 ms
    }

    // Cleanup and exit
    cleanup_gpio();
    printf("Exiting.\n");
    return 0;
}

