#include <signal.h>
#include <string.h>
#include <errno.h>

// Si1145 I2C address
#define SI1145_ADDR 0x60

// Si1145 register addresses
#define PART_ID 0x00
#define HW_KEY 0x07
#define CH_LIST 0x4F
#define MEAS_RATE_PS1 0x08
#define MEAS_RATE_ALS 0x09
#define ALS_IR_ADCMUX 0x0A
#define PS1_ADCMUX 0x0B
#define PS2_ADCMUX 0x0C
#define PS3_ADCMUX 0x0D
#define PS_LED21 0x0E
#define PS_LED3 0x0F
#define ALS_VIS_ADCMUX 0x10
#define ALS_IR_ADC_GAIN 0x11
#define PS1_ADC_GAIN 0x12
#define PS2_ADC_GAIN 0x13
#define PS3_ADC_GAIN 0x14
#define PS_LED12_SELECT 0x15
#define PS_LED1_SELECT 0x16
#define COMMAND 0x30
#define PS1_DATA0 0x18
#define PS1_DATA1 0x19
#define ALS_VIS_DATA0 0x22
#define ALS_VIS_DATA1 0x23

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_si1145();
int read_si1145_data(uint16_t *proximity, uint16_t *ambient_light);
void log_data(uint16_t proximity, uint16_t ambient_light);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize the Si1145 sensor
int init_si1145() {
    int status;

    // Verify PART_ID
    status = i2cWriteByteData(i2c_handle, PART_ID, 0x00); // Dummy write to read
    if (status < 0) {
        fprintf(stderr, "Error writing to PART_ID register: %d\n", status);
        return -1;
    }
    int part_id = i2cReadByteData(i2c_handle, PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART_ID register: %d\n", part_id);
        return -1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Error: Incorrect PART_ID (0x%02X)\n", part_id);
        return -1;
    }

    // Write HW_KEY
    status = i2cWriteByteData(i2c_handle, HW_KEY, 0x17);
    if (status < 0) {
        fprintf(stderr, "Error writing to HW_KEY register: %d\n", status);
        return -1;
    }

    // Set CH_LIST to enable PS1 and ALS_VIS
    status = i2cWriteByteData(i2c_handle, CH_LIST, 0x77); // Enable PS1 and ALS_VIS
    if (status < 0) {
        fprintf(stderr, "Error writing to CH_LIST register: %d\n", status);
        return -1;
    }

    // Configure measurement rates
    status = i2cWriteByteData(i2c_handle, MEAS_RATE_PS1, 0x08); // 8 * 25ms = 200ms
    if (status < 0) {
        fprintf(stderr, "Error writing to MEAS_RATE_PS1 register: %d\n", status);
        return -1;
    }
    status = i2cWriteByteData(i2c_handle, MEAS_RATE_ALS, 0x08); // 8 * 25ms = 200ms
    if (status < 0) {
        fprintf(stderr, "Error writing to MEAS_RATE_ALS register: %d\n", status);
        return -1;
    }

    // Configure ALS_IR_ADCMUX
    status = i2cWriteByteData(i2c_handle, ALS_IR_ADCMUX, 0x03); // Enable ALS_IR_ADC
    if (status < 0) {
        fprintf(stderr, "Error writing to ALS_IR_ADCMUX register: %d\n", status);
        return -1;
    }

    // Configure PS1_ADCMUX
    status = i2cWriteByteData(i2c_handle, PS1_ADCMUX, 0x03); // Enable PS1_ADC
    if (status < 0) {
        fprintf(stderr, "Error writing to PS1_ADCMUX register: %d\n", status);
        return -1;
    }

    // Configure ALS_VIS_ADCMUX
    status = i2cWriteByteData(i2c_handle, ALS_VIS_ADCMUX, 0x03); // Enable ALS_VIS_ADC
    if (status < 0) {
        fprintf(stderr, "Error writing to ALS_VIS_ADCMUX register: %d\n", status);
        return -1;
    }

    return 0;
}

// Read proximity and ambient light data from the Si1145 sensor
int read_si1145_data(uint16_t *proximity, uint16_t *ambient_light) {
    int status;

    // Trigger measurements
    status = i2cWriteByteData(i2c_handle, COMMAND, 0x06); // ALS_FORCE
    if (status < 0) {
        fprintf(stderr, "Error writing to COMMAND register (ALS_FORCE): %d\n", status);
        return -1;
    }
    status = i2cWriteByteData(i2c_handle, COMMAND, 0x07); // PS_FORCE
    if (status < 0) {
        fprintf(stderr, "Error writing to COMMAND register (PS_FORCE): %d\n", status);
        return -1;
    }

    // Read proximity data
    int ps1_data0 = i2cReadByteData(i2c_handle, PS1_DATA0);
    if (ps1_data0 < 0) {
        fprintf(stderr, "Error reading PS1_DATA0 register: %d\n", ps1_data0);
        return -1;
    }
    int ps1_data1 = i2cReadByteData(i2c_handle, PS1_DATA1);
    if (ps1_data1 < 0) {
        fprintf(stderr, "Error reading PS1_DATA1 register: %d\n", ps1_data1);
        return -1;
    }
    *proximity = (uint16_t)((ps1_data1 << 8) | ps1_data0);

    // Read ambient light data
    int als_vis_data0 = i2cReadByteData(i2c_handle, ALS_VIS_DATA0);
    if (als_vis_data0 < 0) {
        fprintf(stderr, "Error reading ALS_VIS_DATA0 register: %d\n", als_vis_data0);
        return -1;
    }
    int als_vis_data1 = i2cReadByteData(i2c_handle, ALS_VIS_DATA1);
    if (als_vis_data1 < 0) {
        fprintf(stderr, "Error reading ALS_VIS_DATA1 register: %d\n", als_vis_data1);
        return -1;
    }
    *ambient_light = (uint16_t)((als_vis_data1 << 8) | als_vis_data0);

    return 0;
}

// Log data to CSV file
void log_data(uint16_t proximity, uint16_t ambient_light) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%u,%u\n", timestamp, proximity, ambient_light);
    fflush(log_file);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize Si1145 sensor
    if (init_si1145() != 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("biometric_data.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Install signal handler
    signal(SIGINT, signal_handler);

    uint16_t proximity, ambient_light;

    // Main loop
    while (!terminate) {
        if (read_si1145_data(&proximity, &ambient_light) == 0) {
            log_data(proximity, ambient_light);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Close I2C bus and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

