#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0       // cm
#define MAX_DISTANCE 400.0     // cm
#define WATERING_THRESHOLD 15.0  // cm
#define TIMEOUT_US 30000        // 30ms
#define TRIGGER_PULSE_US 10      // 10us trigger pulse

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold GPIO configuration
typedef struct {
    int trigger_pin;
    int echo_pin;
} gpio_config_t;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio(gpio_config_t *config);
void trigger_pulse(int trigger_pin);
long long measure_pulse_width(int echo_pin);
double calculate_distance(long long pulse_width);
void log_data(const char *message);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize GPIO pins
int initialize_gpio(gpio_config_t *config) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(config->trigger_pin, PI_OUTPUT);
    gpioSetMode(config->echo_pin, PI_INPUT);

    // Set pull-down resistor on echo pin to avoid floating input
    gpioSetPullUpDown(config->echo_pin, PI_PUD_DOWN);

    return 0;
}

// Generate a 10 microsecond trigger pulse
void trigger_pulse(int trigger_pin) {
    gpioWrite(trigger_pin, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(trigger_pin, 0);
}

// Measure the echo pulse width using edge events
long long measure_pulse_width(int echo_pin) {
    long long start_time = 0, end_time = 0;
    int start_sec, start_micros, end_sec, end_micros;
    int timeout = 0;

    // Wait for the echo pin to go high
    while (gpioRead(echo_pin) == 0 && timeout < TIMEOUT_US) {
        gpioTime(PI_TIME_RELATIVE, &start_sec, &start_micros);
        start_time = (long long)start_sec * 1000000 + start_micros;
        gpioDelay(1); // Small delay to avoid busy-waiting
        timeout++;
    }

    if (timeout >= TIMEOUT_US) {
        return -1; // Timeout occurred
    }

    // Wait for the echo pin to go low
    timeout = 0;
    while (gpioRead(echo_pin) == 1 && timeout < TIMEOUT_US) {
        gpioTime(PI_TIME_RELATIVE, &end_sec, &end_micros);
        end_time = (long long)end_sec * 1000000 + end_micros;
        gpioDelay(1); // Small delay to avoid busy-waiting
        timeout++;
    }

    if (timeout >= TIMEOUT_US) {
        return -1; // Timeout occurred
    }

    return end_time - start_time;
}

// Calculate distance in centimeters
double calculate_distance(long long pulse_width) {
    return (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // Convert us to s
}

// Log data to file with ISO-8601 timestamp
void log_data(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    gpio_config_t gpio_config = {TRIGGER_PIN, ECHO_PIN};
    long long pulse_width;
    double distance;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio(&gpio_config) != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    printf("Plant watering reminder system started.\n");

    while (running) {
        // Trigger the sensor
        trigger_pulse(gpio_config.trigger_pin);

        // Measure the pulse width
        pulse_width = measure_pulse_width(gpio_config.echo_pin);

        if (pulse_width < 0) {
            log_data("Timeout occurred while measuring pulse width.");
        } else {
            // Calculate the distance
            distance = calculate_distance(pulse_width);

            // Validate the distance
            if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
                char message[50];
                snprintf(message, sizeof(message), "Distance: %.2f cm", distance);
                log_data(message);

                // Check if watering is needed
                if (distance < WATERING_THRESHOLD) {
                    log_data("Time to water the plant!");
                }
            } else {
                log_data("Distance out of range.");
            }
        }

        // Wait for 60 seconds
        gpioDelay(60000000); // 60 seconds in microseconds
    }

    // Cleanup and exit
    cleanup();
    printf("Exiting.\n");
    return 0;
}

