}

// Function to initialize the APDS9960 sensor
int initialize_apds9960() {
    int status;

    // Verify sensor ID
    status = i2cWriteByteData(i2c_handle, APDS9960_ID, 0xAB);
    if (status != 0) {
        fprintf(stderr, "Error writing to ID register: %d\n", status);
        return -1;
    }

    // Enable proximity and color sensing
    status = i2cWriteByteData(i2c_handle, APDS9960_ENABLE, 0x03);
    if (status != 0) {
        fprintf(stderr, "Error writing to ENABLE register: %d\n", status);
        return -1;
    }

    // Set ALS integration time
    status = i2cWriteByteData(i2c_handle, APDS9960_ATIME, 0xDB);
    if (status != 0) {
        fprintf(stderr, "Error writing to ATIME register: %d\n", status);
        return -1;
    }

    // Set wait time
    status = i2cWriteByteData(i2c_handle, APDS9960_WTIME, 0xF6);
    if (status != 0) {
