        return -1;
    }

    // Set proximity gain
    status = i2cWriteByteData(i2c_handle, APDS9960_CONFIG2, 0x01);
    if (status != 0) {
        fprintf(stderr, "Error writing to CONFIG2 register: %d\n", status);
        return -1;
    }

    return 0;
}

