    }

    *clear = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    *red   = (uint16_t)buf[2] | ((uint16_t)buf[3] << 8);
    *green = (uint16_t)buf[4] | ((uint16_t)buf[5] << 8);
    *blue  = (uint16_t)buf[6] | ((uint16_t)buf[7] << 8);

    *proximity = buf[7];

