    i2c_handle = i2cOpen(1, APDS9960_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize APDS9960 sensor
    if (initialize_apds9960() != 0) {
        fprintf(stderr, "APDS9960 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("color_proximity_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_apds9960_data(&red, &green, &blue, &clear, &proximity) == 0) {
            // Check proximity threshold
            if (proximity > PROXIMITY_THRESHOLD) {
                // Log data
                log_data(red, green, blue, clear, proximity);
            }
        } else {
            fprintf(stderr, "Error reading sensor data, re-initializing...\n");
            // Re-initialize I2C and sensor
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(1, APDS9960_I2C_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
                terminate = 1; // Exit loop if re-initialization fails
                continue;        // Skip the rest of the loop
            }
            if (initialize_apds9960() != 0) {
                fprintf(stderr, "APDS9960 re-initialization failed\n");
                terminate = 1; // Exit loop if re-initialization fails
                continue;        // Skip the rest of the loop
            }
