#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Si1182 I2C address
#define SI1182_ADDR 0x5A

// Si1182 register addresses
#define PART_ID 0x00
#define MEAS_RATE0 0x08
#define PS_DATA0 0x24
#define PS_DATA1 0x25
#define COMMAND 0x47

// Commands
#define RESET 0x01
#define START 0x02

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t running = 1;

// Function prototypes
int init_i2c();
int read_register(int reg);
int write_register(int reg, int value);
int read_proximity_data();
float calculate_bpm(int proximity_value);
int log_data(float bpm);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor configuration
typedef struct {
    int meas_rate;
} sensor_config_t;

// Function to initialize the I2C interface
int init_i2c() {
    i2c_handle = i2cOpen(1, SI1182_ADDR, 0); // Bus 1, address 0x5A, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read a register from the Si1182
int read_register(int reg) {
    int value = i2cReadByteData(i2c_handle, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return value;
}

// Function to write a register to the Si1182
int write_register(int reg, int value) {
    int result = i2cWriteByteData(i2c_handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read proximity data from the Si1182
int read_proximity_data() {
    int low = read_register(PS_DATA0);
    int high = read_register(PS_DATA1);

    if (low < 0 || high < 0) {
        return -1; // Indicate error
    }

    return (high << 8) | low; // Combine into 16-bit value
}

// Function to calculate BPM from proximity data (placeholder)
float calculate_bpm(int proximity_value) {
    // This is a placeholder.  A real implementation would
    // analyze the proximity signal to estimate heart rate.
    // For example, it might look for peaks or changes in frequency.
    // This simple example just returns a value based on the proximity value.
    return (float)proximity_value / 100.0; // Example calculation
}

// Function to log data to a CSV file
int log_data(float bpm) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f\n", timestamp, bpm);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Cleanup function to close I2C and file
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("heartrate.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Write header if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,bpm\n");
    }
    fflush(log_file);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Si1182 configuration
    sensor_config_t config = { .meas_rate = 0x0A }; // Example measurement rate

    // Reset the sensor
    if (write_register(COMMAND, RESET) != 0) {
        cleanup();
        return 1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Start continuous proximity measurement
    if (write_register(MEAS_RATE0, config.meas_rate) != 0) {
        cleanup();
        return 1;
    }
    if (write_register(COMMAND, START) != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (running) {
        int proximity_value = read_proximity_data();
        if (proximity_value >= 0) {
            float bpm = calculate_bpm(proximity_value);
            log_data(bpm);
        } else {
            fprintf(stderr, "Error reading proximity data, skipping sample.\n");
        }

        gpioDelay(100); // 100ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

