}

// Initialize VL53L0X sensor
int init_vl53l0x() {
    // Check sensor presence
    if (i2cReadByteData(i2c_handle, 0x00) < 0) {
        fprintf(stderr, "Error: VL53L0X sensor not found at address 0x%02X\n", VL53L0X_ADDR);
        return -1;
    }

    // No explicit initialization needed for basic ranging
    return 0;
}

// Read distance from VL53L0X sensor
int read_distance(uint16_t *distance) {
    // Start a single measurement
    if (i2cWriteByteData(i2c_handle, SYSRANGE_START, 0x01) < 0) {
