#define TRIGGER_REG 0x00
#define DISTANCE_REG 0x01
#define DISTANCE_LENGTH 2
#define SAMPLE_INTERVAL_MS 200
#define TRIGGER_PULSE_US 10
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int open_i2c_bus();
int trigger_measurement(int handle);
int read_distance(int handle, int *distance);
int log_distance(const char *timestamp, int distance);
void signal_handler(int signal);
char* get_timestamp(char *timestamp_str, size_t size);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus() {
    int handle = i2cOpen(I2C_BUS, CH101_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", handle);
        return -1;
    }
    return handle;
}

// Trigger measurement
int trigger_measurement(int handle) {
    char buf[1] = {0x01}; // Trigger value
    int result = i2cWriteDevice(handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to trigger measurement: %d\n", result);
        return -1;
    }
    gpioDelay(TRIGGER_PULSE_US); // Wait for trigger pulse
    return 0;
}

// Read distance
int read_distance(int handle, int *distance) {
    char buf[1] = {DISTANCE_REG};
    int result = i2cWriteDevice(handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to write to distance register: %d\n", result);
        return -1;
    }

    char data[DISTANCE_LENGTH];
    result = i2cReadDevice(handle, data, DISTANCE_LENGTH);
    if (result != DISTANCE_LENGTH) {
        fprintf(stderr, "Failed to read distance data: %d\n", result);
        return -1;
    }

    *distance = (data[0] << 8) | data[1];
    return 0;
}

// Log distance
int log_distance(const char *timestamp, int distance) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s, %d\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk
    printf("%s, %d\n", timestamp, distance);
    return 0;
}

// Get timestamp
char* get_timestamp(char *timestamp_str, size_t size) {
    time_t timer;
    struct tm* tm_info;

    time(&timer);
    tm_info = localtime(&timer);

    strftime(timestamp_str, size, "%Y-%m-%d %H:%M:%S", tm_info);
    return timestamp_str;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    i2c_handle = open_i2c_bus();
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    char timestamp_str[20]; // Buffer for timestamp
    int distance;
    int retries;

    // Main loop
    while (!terminate) {
        retries = 0;
        while (retries < MAX_RETRIES) {
            if (trigger_measurement(i2c_handle) == 0) {
                gpioDelay(50); // Wait for measurement
                if (read_distance(i2c_handle, &distance) == 0) {
                    get_timestamp(timestamp_str, sizeof(timestamp_str));
                    if (log_distance(timestamp_str, distance) != 0) {
                        fprintf(stderr, "Failed to log distance\n");
                    }
                    break; // Exit retry loop on success
                } else {
                    fprintf(stderr, "Failed to read distance, retry %d\n", retries + 1);
                }
            } else {
                fprintf(stderr, "Failed to trigger measurement, retry %d\n", retries + 1);
            }
            retries++;
            gpioDelay(10); // Small delay before retry
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Max retries reached, skipping sample\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS); // Sample every 200ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

