#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ICU20201_ADDR 0x6A
#define LED_GPIO 17
#define DISTANCE_THRESHOLD 20.0 // cm
#define I2C_RETRY_COUNT 3

// ICU-20201 Register Addresses (Example - Refer to Datasheet)
#define ICU20201_REG_WHO_AM_I 0x0F
#define ICU20201_REG_MEASURE 0x00
#define ICU20201_REG_DISTANCE_HIGH 0x01
#define ICU20201_REG_DISTANCE_LOW 0x02

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_gpio();
int read_distance(float *distance);
int log_distance(float distance);
int control_led(float distance);
void signal_handler(int signal);
void cleanup();

// Structure for sensor configuration (example)
typedef struct {
    int measure_reg;
    int high_byte_reg;
    int low_byte_reg;
} sensor_config_t;

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// I2C initialization function
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ICU20201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }

    // Verify sensor presence (example)
    int who_am_i = i2cReadByteData(i2c_handle, ICU20201_REG_WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        i2cClose(i2c_handle);
        return -1;
    }
    printf("WHO_AM_I value: 0x%X\n", who_am_i);

    return 0;
}

// GPIO initialization function
int init_gpio() {
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", LED_GPIO);
        return -1;
    }
    gpioWrite(LED_GPIO, 0); // Initially turn the LED off
    return 0;
}

// Function to read distance from the sensor
int read_distance(float *distance) {
    int high_byte, low_byte;
    int retries = I2C_RETRY_COUNT;

    while (retries > 0) {
        // Trigger measurement (example - refer to datasheet)
        if (i2cWriteByteData(i2c_handle, ICU20201_REG_MEASURE, 0x01) < 0) {
            fprintf(stderr, "Error triggering measurement: %d\n", i2c_handle);
            retries--;
            gpioDelay(10); // Small delay before retry
            continue;
        }

        gpioDelay(50); // Wait for measurement to complete (adjust as needed)

        high_byte = i2cReadByteData(i2c_handle, ICU20201_REG_DISTANCE_HIGH);
        if (high_byte < 0) {
            fprintf(stderr, "Error reading high byte: %d\n", high_byte);
            retries--;
            gpioDelay(10);
            continue;
        }

        low_byte = i2cReadByteData(i2c_handle, ICU20201_REG_DISTANCE_LOW);
        if (low_byte < 0) {
            fprintf(stderr, "Error reading low byte: %d\n", low_byte);
            retries--;
            gpioDelay(10);
            continue;
        }

        // Combine high and low bytes to get the distance value
        int distance_raw = (high_byte << 8) | low_byte;

        // Convert raw value to centimeters (example - refer to datasheet)
        *distance = (float)distance_raw / 10.0; // Example conversion

        return 0; // Success
    }

    fprintf(stderr, "Failed to read distance after %d retries\n", I2C_RETRY_COUNT);
    return -1; // Failure
}

// Function to log distance to a file
int log_distance(float distance) {
    FILE *fp = fopen("distance_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    fprintf(fp, "%s, %.2f cm\n", timestamp, distance);
    fclose(fp);
    return 0;
}

// Function to control the LED based on distance
int control_led(float distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
    return 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(LED_GPIO, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        cleanup();
        return 1;
    }

    float distance;

    // Main loop
    while (!terminate) {
        if (read_distance(&distance) == 0) {
            printf("Distance: %.2f cm\n", distance);
            log_distance(distance);
            control_led(distance);
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }

        gpioDelay(100); // Wait 100 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

