#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x60
#define PROXIMITY_REG 0x18
#define AMBIENT_REG 0x16
#define LOG_FILE "biometric_log.txt"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define SLEEP_MS 500

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sensor_data(int i2c_handle, uint16_t *proximity, uint16_t *ambient);
int log_data(FILE *log_file, uint16_t proximity, uint16_t ambient);
void signal_handler(int signal);
int initialize();
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Function to read sensor data with retries
int read_sensor_data(int i2c_handle, uint16_t *proximity, uint16_t *ambient) {
    int retries = 0;
    int result;
    uint8_t buffer[4];

    while (retries < RETRY_COUNT) {
        // Read proximity data
        result = i2cReadI2CBlockData(i2c_handle, PROXIMITY_REG, (char *)buffer, 2);
        if (result == 2) {
            *proximity = (buffer[1] << 8) | buffer[0];
            break; // Success, exit retry loop
        } else {
            fprintf(stderr, "I2C read proximity failed (attempt %d): %s\n", retries + 1, strerror(errno));
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Failed to read proximity after %d retries\n", RETRY_COUNT);
        return -1; // Indicate failure
    }

    retries = 0;
    while (retries < RETRY_COUNT) {
        // Read ambient light data
        result = i2cReadI2CBlockData(i2c_handle, AMBIENT_REG, (char *)buffer + 2, 2);
        if (result == 2) {
            *ambient = (buffer[3] << 8) | buffer[2];
            break; // Success, exit retry loop
        } else {
            fprintf(stderr, "I2C read ambient failed (attempt %d): %s\n", retries + 1, strerror(errno));
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Failed to read ambient after %d retries\n", RETRY_COUNT);
        return -1; // Indicate failure
    }

    return 0; // Indicate success
}

// Function to log data to file
int log_data(FILE *log_file, uint16_t proximity, uint16_t ambient) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s, Proximity: %u, Ambient: %u\n", timestamp, proximity, ambient) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    uint16_t proximity, ambient;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(i2c_handle, &proximity, &ambient) == 0) {
            if (log_data(log_file, proximity, ambient) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(SLEEP_MS * 1000); // Delay in microseconds
    }

    // Cleanup
    cleanup();

    return 0;
}

