#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>

// Define constants
#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDRESS 0x50
#define COMMAND_FRAME {0x50, 0x0A, 0x00, 0x01}
#define RESPONSE_LENGTH 15
#define DISTANCE_OFFSET 11
#define DISTANCE_LENGTH 2
#define INTRUSION_THRESHOLD 1000
#define SAMPLE_RATE 10 // Hz
#define SAMPLE_PERIOD_MS (1000 / SAMPLE_RATE)
#define CYCLE_DELAY_MS 100

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_write(int fd, uint8_t address, uint8_t *data, int length);
int i2c_read(int fd, uint8_t address, uint8_t *data, int length);
int request_distance_measurement(int fd, uint8_t address);
int read_distance_data(int fd, uint8_t address, uint8_t *data);
uint16_t parse_distance(uint8_t *data);
void log_intrusion(uint16_t distance);
void signal_handler(int signal);

// I2C write function
int i2c_write(int fd, uint8_t address, uint8_t *data, int length) {
    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error: Could not set I2C slave address");
        return -1;
    }

    if (write(fd, data, length) != length) {
        perror("Error: Could not write to I2C device");
        return -1;
    }

    return 0;
}

// I2C read function
int i2c_read(int fd, uint8_t address, uint8_t *data, int length) {
    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error: Could not set I2C slave address");
        return -1;
    }

    if (read(fd, data, length) != length) {
        perror("Error: Could not read from I2C device");
        return -1;
    }

    return 0;
}

// Request distance measurement
int request_distance_measurement(int fd, uint8_t address) {
    uint8_t command_frame[] = COMMAND_FRAME;
    if (i2c_write(fd, address, command_frame, sizeof(command_frame)) != 0) {
        fprintf(stderr, "Error: Failed to send command frame\n");
        return -1;
    }
    return 0;
}

// Read distance data
int read_distance_data(int fd, uint8_t address, uint8_t *data) {
    if (i2c_read(fd, address, data, RESPONSE_LENGTH) != 0) {
        fprintf(stderr, "Error: Failed to read response data\n");
        return -1;
    }
    return 0;
}

// Parse distance data
uint16_t parse_distance(uint8_t *data) {
    return (uint16_t)((data[DISTANCE_OFFSET] << 8) | data[DISTANCE_OFFSET + 1]);
}

// Log intrusion event
void log_intrusion(uint16_t distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Distance: %d mm\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error: Could not open I2C bus");
        return 1;
    }

    // Open log file
    log_file = fopen("intrusion_log.txt", "a");
    if (log_file == NULL) {
        perror("Error: Could not open log file");
        close(i2c_fd);
        return 1;
    }

    printf("Starting intrusion detection system...\n");

    while (program_running) {
        uint16_t total_distance = 0;
        int num_samples = 0;

        // Sample sensor multiple times
        for (int i = 0; i < SAMPLE_RATE; ++i) {
            uint8_t response[RESPONSE_LENGTH];

            if (request_distance_measurement(i2c_fd, SENSOR_ADDRESS) == 0) {
                usleep(SAMPLE_PERIOD_MS * 1000); // Wait for measurement
                if (read_distance_data(i2c_fd, SENSOR_ADDRESS, response) == 0) {
                    if (response[0] == 0x50) {
                        uint16_t distance = parse_distance(response);
                        total_distance += distance;
                        num_samples++;
                    } else {
                        fprintf(stderr, "Error: Invalid header byte: 0x%02X\n", response[0]);
                    }
                }
            }
        }

        // Calculate average distance
        uint16_t average_distance = 0;
        if (num_samples > 0) {
            average_distance = total_distance / num_samples;
        }

        // Check for intrusion
        if (average_distance < INTRUSION_THRESHOLD) {
            log_intrusion(average_distance);
        }

        usleep(CYCLE_DELAY_MS * 1000); // Delay between cycles
    }

    // Close resources
    close(i2c_fd);
    fclose(log_file);

    printf("Exiting.\n");
    return 0;
}

