#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define constants
#define I2C_BUS "/dev/i2c-1"
#define MLX75030_ADDR 0x4C
#define DISTANCE_REG 0x00
#define DISTANCE_REG_SIZE 2
#define DISTANCE_FACTOR 0.125f

// Global variables
int i2c_fd = -1;
volatile sig_atomic_t terminate = 0;

// Structure to hold program state
typedef struct {
    int i2c_fd;
    int address;
    float distance_factor;
} ProgramState;

// Function prototypes
int i2c_open(const char *bus);
int i2c_set_slave_address(int fd, int address);
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len);
float convert_to_mm(uint16_t raw_distance);
void log_distance(float distance);
void signal_handler(int sig);
void cleanup(ProgramState *state);

// Function to open the I2C bus
int i2c_open(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", bus, strerror(errno));
        return -1;
    }
    return fd;
}

// Function to set the I2C slave address
int i2c_set_slave_address(int fd, int address) {
    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", address, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read bytes from the I2C device
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, data, len) != len) {
        fprintf(stderr, "Error reading data: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to convert raw distance to millimetres
float convert_to_mm(uint16_t raw_distance) {
    return (float)raw_distance * DISTANCE_FACTOR;
}

// Function to log the distance
void log_distance(float distance) {
    printf("Distance: %.2f mm\n", distance);
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    fprintf(stderr, "Received signal %d, terminating...\n", sig);
    terminate = 1;
}

// Cleanup function to close the I2C file descriptor
void cleanup(ProgramState *state) {
    if (state->i2c_fd != -1) {
        close(state->i2c_fd);
        fprintf(stderr, "I2C device closed.\n");
    }
}

int main() {
    ProgramState state = { .i2c_fd = -1, .address = MLX75030_ADDR, .distance_factor = DISTANCE_FACTOR };
    struct timespec sleep_time = { .tv_sec = 0, .tv_nsec = 500000000 }; // 500 ms
    uint8_t distance_data[2];
    uint16_t raw_distance;
    float distance_mm;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the I2C bus
    state.i2c_fd = i2c_open(I2C_BUS);
    if (state.i2c_fd < 0) {
        return 1;
    }

    // Set the I2C slave address
    if (i2c_set_slave_address(state.i2c_fd, state.address) < 0) {
        cleanup(&state);
        return 1;
    }

    // Verify the device is present (read a register)
    if (i2c_read_bytes(state.i2c_fd, DISTANCE_REG, distance_data, DISTANCE_REG_SIZE) < 0) {
        fprintf(stderr, "Error reading from device, check if MLX75030 is connected.\n");
        cleanup(&state);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read the distance register
        if (i2c_read_bytes(state.i2c_fd, DISTANCE_REG, distance_data, DISTANCE_REG_SIZE) == 0) {
            // Combine the bytes to form the raw distance value
            raw_distance = (distance_data[1] << 8) | distance_data[0];

            // Convert the raw distance to millimetres
            distance_mm = convert_to_mm(raw_distance);

            // Log the distance
            log_distance(distance_mm);
        } else {
            fprintf(stderr, "I2C read error, retrying...\n");
        }

        // Sleep for 500 ms
        if (nanosleep(&sleep_time, NULL) != 0) {
            fprintf(stderr, "nanosleep interrupted: %s\n", strerror(errno));
        }
    }

    // Cleanup and exit
    cleanup(&state);
    return 0;
}

