    buf[0] = REG_SYSTEM_CONFIG; // System Configuration Register
    buf[1] = 0x01; // Reset bit
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing to system config register\n");
        return -1;
    }
    gpioDelay(10000); // Wait for reset

    // Configure for continuous mode (example)
    buf[0] = REG_SYSTEM_CONFIG; // System Configuration Register
    buf[1] = 0x03; // Continuous mode
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing to system config register\n");
        return -1;
    }

    return 0;
}

// Function to read data from the OPT3101 sensor
int read_opt3101(sensor_data_t *data) {
    char reg_addr;
    char read_buf[6]; // 2 bytes distance, 2 bytes ambient, 2 bytes error

    // Read channel 0 distance
    reg_addr = REG_CHANNEL0_DISTANCE;
    if (i2cWriteDevice(i2c_handle, &reg_addr, 1) != 0) {
        fprintf(stderr, "Error writing to channel 0 distance register\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, read_buf, 2) != 2) {
        fprintf(stderr, "Error reading channel 0 distance\n");
        return -1;
    }
    data->distance = (read_buf[0] << 8) | read_buf[1];

    // Read ambient light
    reg_addr = REG_AMBIENT_LIGHT;
    if (i2cWriteDevice(i2c_handle, &reg_addr, 1) != 0) {
        fprintf(stderr, "Error writing to ambient light register\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, read_buf, 2) != 2) {
        fprintf(stderr, "Error reading ambient light\n");
        return -1;
    }
    data->ambient_light = (read_buf[0] << 8) | read_buf[1];

    // Read error flags
    reg_addr = REG_ERROR_FLAGS;
    if (i2cWriteDevice(i2c_handle, &reg_addr, 1) != 0) {
        fprintf(stderr, "Error writing to error flags register\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, read_buf, 2) != 2) {
        fprintf(stderr, "Error reading error flags\n");
        return -1;
    }
    data->error_flags = read_buf[0];

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, OPT3101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize OPT3101 sensor
    if (init_opt3101() != 0) {
        fprintf(stderr, "OPT3101 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_opt3101(&sensor_data) == 0) {
            // Log data to console
            printf("Distance: %u mm, Ambient: %u, Error: %u\n", sensor_data.distance, sensor_data.ambient_light, sensor_data.error_flags);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait 500 ms
        gpioDelay(500000);
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

