#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 200000       // 200 ms
#define MAX_PULSE_US 38000       // Maximum pulse duration (38 ms)

// Global variables
volatile int pulse_start = 0;
volatile int pulse_end = 0;
volatile int pulse_width = 0;
volatile int echo_received = 0;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

// Trigger pulse function
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Echo callback function
void echo_callback(int gpio, int level, uint32_t tick) {
    if (gpio == ECHO_PIN) {
        if (level == 1) {
            pulse_start = tick;
            echo_received = 1; // Indicate rising edge received
        } else if (level == 0) {
            if (echo_received == 1) {
                pulse_end = tick;
                pulse_width = pulse_end - pulse_start;
                echo_received = 2; // Indicate falling edge received
            }
        }
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on echo pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Set alert function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Set signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Trigger the ultrasonic sensor
        trigger_pulse();

        // Wait for echo pulse or timeout
        int timeout_count = 0;
        while (echo_received != 2 && timeout_count < TIMEOUT_US) {
            gpioDelay(1); // Delay 1 us
            timeout_count++;
        }

        // Check for timeout
        if (timeout_count >= TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo falling edge\n");
            echo_received = 0; // Reset flag
            continue;           // Skip to next iteration
        }

        // Check for invalid pulse duration
        if (pulse_width <= 0 || pulse_width > MAX_PULSE_US) {
            fprintf(stderr, "Invalid pulse duration: %d us\n", pulse_width);
            echo_received = 0; // Reset flag
            continue;           // Skip to next iteration
        }

        // Calculate distance in centimeters
        float distance = (pulse_width * SPEED_OF_SOUND) / 2000000.0;

        // Get current timestamp
        time_t rawtime;
        struct tm *timeinfo;
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        char timestamp[80];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Log the distance with timestamp
        printf("%s Distance: %.2f cm\n", timestamp, distance);

        // Reset echo_received flag for next measurement
        echo_received = 0;

        // Wait for 1 second
        gpioDelay(1000000); // 1 second
    }

    // Terminate pigpio library (should not reach here in normal execution)
    gpioTerminate();
    return 0;
}

