#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define MAGIC_WORD {0x02, 0x01, 0x04, 0x03, 0x06, 0x05, 0x08, 0x07}
#define RANGE_RESOLUTION 0.0486 // meters per bin
#define THRESHOLD_DISTANCE 1.0  // meters
#define LED_GPIO 17
#define RANGE_BINS 64
#define DATA_FRAME_SIZE (RANGE_BINS * 2) // 16-bit integers
#define HEADER_SIZE 8

// Global variables
int uart_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure for configuration
typedef struct {
    char uart_device[20];
    int baud_rate;
    int led_gpio;
    float range_resolution;
    float threshold_distance;
} Config;

// Function prototypes
int initialize_uart(const char *device, int baud_rate);
int read_uart_data(int fd, unsigned char *buffer, int size);
int validate_magic_word(const unsigned char *buffer);
int parse_range_profile(const unsigned char *buffer, short *range_profile);
float calculate_distance(short range_profile_value);
void detect_intrusion(float distance);
void log_intrusion(float distance);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize UART
int initialize_uart(const char *device, int baud_rate) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = baud_rate | CS8 | CLOCAL | CREAD;  // 8N1, no parity
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0;                               // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read doesn't block
    tty.c_cc[VTIME] = 5; // 0.5 seconds read timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

// Read data from UART
int read_uart_data(int fd, unsigned char *buffer, int size) {
    ssize_t bytes_read = read(fd, buffer, size);
    if (bytes_read == -1) {
        perror("Error reading from UART");
        return -1;
    } else if (bytes_read != size) {
        fprintf(stderr, "Warning: Read %zd bytes, expected %d\n", bytes_read, size);
    }
    return (int)bytes_read;
}

// Validate magic word
int validate_magic_word(const unsigned char *buffer) {
    unsigned char magic_word[] = MAGIC_WORD;
    for (int i = 0; i < HEADER_SIZE; i++) {
        if (buffer[i] != magic_word[i]) {
            return 0; // Invalid magic word
        }
    }
    return 1; // Valid magic word
}

// Parse range profile data
int parse_range_profile(const unsigned char *buffer, short *range_profile) {
    for (int i = 0; i < RANGE_BINS; i++) {
        range_profile[i] = (short)((buffer[2 * i] & 0xFF) | ((buffer[2 * i + 1] & 0xFF) << 8));
    }
    return 0;
}

// Calculate distance from range profile value
float calculate_distance(short range_profile_value) {
    // Assuming range_profile_value is proportional to the distance
    // This is a simplified model; calibration is needed for accuracy
    return (float)range_profile_value * RANGE_RESOLUTION;
}

// Detect intrusion
void detect_intrusion(float distance) {
    if (distance < THRESHOLD_DISTANCE) {
        printf("Intrusion detected! Distance: %.2f meters\n", distance);
        gpioWrite(LED_GPIO, 1); // Turn on LED
        gpioDelay(2000);        // Wait for 2 seconds
        gpioWrite(LED_GPIO, 0); // Turn off LED
        log_intrusion(distance);
    }
}

// Log intrusion to file
void log_intrusion(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (uart_fd != -1) {
        close(uart_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
}

int main() {
    // Configuration
    Config config = {
        .uart_device = UART_DEVICE,
        .baud_rate = BAUD_RATE,
        .led_gpio = LED_GPIO,
        .range_resolution = RANGE_RESOLUTION,
        .threshold_distance = THRESHOLD_DISTANCE
    };

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(config.led_gpio, PI_OUTPUT);
    gpioWrite(config.led_gpio, 0); // Ensure LED is off initially

    // Initialize UART
    uart_fd = initialize_uart(config.uart_device, config.baud_rate);
    if (uart_fd == -1) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("intrusion_log.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,distance_meters\n");
    }

    unsigned char buffer[HEADER_SIZE + DATA_FRAME_SIZE];
    short range_profile[RANGE_BINS];

    printf("Starting intrusion detection...\n");

    while (!terminate) {
        // Read data from UART
        if (read_uart_data(uart_fd, buffer, HEADER_SIZE + DATA_FRAME_SIZE) == HEADER_SIZE + DATA_FRAME_SIZE) {
            // Validate magic word
            if (validate_magic_word(buffer)) {
                // Parse range profile
                if (parse_range_profile(buffer + HEADER_SIZE, range_profile) == 0) {
                    // Calculate distance (example: using the first range bin)
                    float distance = calculate_distance(range_profile[0]);
                    detect_intrusion(distance);
                } else {
                    fprintf(stderr, "Error parsing range profile\n");
                }
            } else {
                fprintf(stderr, "Invalid magic word\n");
            }
        } else {
            fprintf(stderr, "Error reading data from UART\n");
        }

        usleep(10000); // 10ms delay
    }

    cleanup();
    return 0;
}

