#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x69
#define DISTANCE_HIGH_REG 0x31
#define DISTANCE_LOW_REG 0x32
#define ALERT_GPIO 17
#define DISTANCE_THRESHOLD 10.0 // cm
#define SAMPLE_INTERVAL_MS 100
#define SERVER_IP "127.0.0.1" // Replace with your server IP
#define SERVER_PORT 12345

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_distance(int i2c_handle, uint16_t *distance);
char *get_iso8601_timestamp(char *timestamp_str, size_t timestamp_str_size);
int log_distance(const char *timestamp, uint16_t distance);
int send_distance_to_server(const char *timestamp, uint16_t distance);
void trigger_alert(int gpio_pin);
void signal_handler(int signal);
int check_sensor_presence(int i2c_handle);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, terminating...\n");
}

// Function to read distance from the sensor
int read_distance(int i2c_handle, uint16_t *distance) {
    char buf[2];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, DISTANCE_HIGH_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading distance data: %d\n", result);
        return -1;
    }

    *distance = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

// Function to get ISO 8601 timestamp
char *get_iso8601_timestamp(char *timestamp_str, size_t timestamp_str_size) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp_str, timestamp_str_size, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp_str;
}

// Function to log distance to file
int log_distance(const char *timestamp, uint16_t distance) {
    FILE *fp = fopen("distance_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    fprintf(fp, "%s, %u\n", timestamp, distance);
    fclose(fp);
    return 0;
}

// Function to send distance to server
int send_distance_to_server(const char *timestamp, uint16_t distance) {
    int sock = 0, valread;
    struct sockaddr_in serv_addr;
    char buffer[1024] = {0};

    if ((sock = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        fprintf(stderr, "Socket creation error: %s\n", strerror(errno));
        return -1;
    }

    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(SERVER_PORT);

    // Convert IPv4 and IPv6 addresses from text to binary form
    if (inet_pton(AF_INET, SERVER_IP, &serv_addr.sin_addr) <= 0) {
        fprintf(stderr, "Invalid address/ Address not supported: %s\n", SERVER_IP);
        close(sock);
        return -1;
    }

    if (connect(sock, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        fprintf(stderr, "Connection Failed: %s\n", strerror(errno));
        close(sock);
        return -1;
    }

    snprintf(buffer, sizeof(buffer), "%s, %u", timestamp, distance);
    send(sock, buffer, strlen(buffer), 0);
    close(sock);
    return 0;
}

// Function to trigger alert
void trigger_alert(int gpio_pin) {
    gpioWrite(gpio_pin, 1); // Set GPIO high
    gpioDelay(1000);        // Wait for 1 second
    gpioWrite(gpio_pin, 0); // Set GPIO low
}

// Function to check sensor presence
int check_sensor_presence(int i2c_handle) {
    char buf[1];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 1); // Read a byte from register 0x00
    if (result < 0) {
        fprintf(stderr, "Error checking sensor presence: %d\n", result);
        return 0; // Assume sensor is not present if there's an error
    }
    return 1; // Sensor is present
}

int main() {
    char timestamp[32];
    uint16_t distance;
    int pigpio_init_result;

    // Initialize pigpio
    pigpio_init_result = gpioInitialise();
    if (pigpio_init_result < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", pigpio_init_result);
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check sensor presence
    if (!check_sensor_presence(i2c_handle)) {
        fprintf(stderr, "Sensor not found at address 0x%02x\n", I2C_ADDRESS);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(ALERT_GPIO, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read distance
        if (read_distance(i2c_handle, &distance) == 0) {
            // Get timestamp
            get_iso8601_timestamp(timestamp, sizeof(timestamp));

            // Log distance
            if (log_distance(timestamp, distance) != 0) {
                fprintf(stderr, "Error logging distance\n");
            }

            // Send distance to server
            if (send_distance_to_server(timestamp, distance) != 0) {
                fprintf(stderr, "Error sending distance to server\n");
            }

            // Trigger alert if distance is below threshold
            if (distance < (uint16_t)(DISTANCE_THRESHOLD * 10.0)) { // Assuming distance is in mm
                trigger_alert(ALERT_GPIO);
            }
        } else {
            fprintf(stderr, "Error reading distance, retrying...\n");
        }

        // Sleep for the specified interval
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Convert ms to us
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

