#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// VL53L1X I2C address
#define VL53L1X_ADDR 0x29

// VL53L1X register addresses
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SYSTEM_START 0x0000
#define VL53L1X_REG_RESULT_INTERRUPT_STATUS 0x013
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x078
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x078

// Distance thresholds (mm)
#define STOP_THRESHOLD 300
#define APPROACH_THRESHOLD 600
#define SLOW_THRESHOLD 1200

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance(uint16_t *distance);
void log_distance(uint16_t distance);
void print_parking_message(uint16_t distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize VL53L1X sensor
int init_vl53l1x() {
    // Verify sensor presence
    int model_id = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID);
    if (model_id < 0) {
        fprintf(stderr, "Error reading model ID: %d\n", model_id);
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Incorrect model ID: 0x%02X\n", model_id);
        return -1;
    }

    // Software reset
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSTEM_START, 0x00) < 0) {
        fprintf(stderr, "Error writing software reset: %d\n", i2c_handle);
        return -1;
    }
    gpioDelay(2); // Wait 2 ms

    // Start continuous back-to-back ranging
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSTEM_START, 0x01) < 0) {
        fprintf(stderr, "Error writing system start: %d\n", i2c_handle);
        return -1;
    }

    return 0;
}

// Read distance from VL53L1X sensor
int read_distance(uint16_t *distance) {
    // Poll for data ready
    int timeout = 100; // 100 ms timeout
    while (timeout > 0) {
        int status = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_INTERRUPT_STATUS);
        if (status < 0) {
            fprintf(stderr, "Error reading interrupt status: %d\n", status);
            return -1;
        }
        if (status & 0x01) {
            break; // Data ready
        }
        gpioDelay(1); // Wait 1 ms
        timeout--;
    }

    if (timeout == 0) {
        fprintf(stderr, "Timeout waiting for data ready\n");
        return -1;
    }

    // Read distance
    char data[2];
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, data, 2) < 0) {
        fprintf(stderr, "Error reading distance: %d\n", i2c_handle);
        return -1;
    }

    *distance = (data[0] << 8) | data[1]; // Big-endian

    // Clear interrupt
    if (i2cWriteByteData(i2c_handle, 0x014, 0x01) < 0) {
        fprintf(stderr, "Error clearing interrupt: %d\n", i2c_handle);
        return -1;
    }

    return 0;
}

// Log distance to file
void log_distance(uint16_t distance) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%u\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk
}

// Print parking guidance message
void print_parking_message(uint16_t distance) {
    if (distance < STOP_THRESHOLD) {
        printf("STOP\n");
    } else if (distance < APPROACH_THRESHOLD) {
        printf("APPROACH\n");
    } else if (distance < SLOW_THRESHOLD) {
        printf("SLOW\n");
    } else {
        printf("CLEAR\n");
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() < 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header row if file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,distance_mm\n");
    }
    rewind(log_file);

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t distance;

    // Main loop
    while (!terminate) {
        if (read_distance(&distance) == 0) {
            log_distance(distance);
            print_parking_message(distance);
