#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define CH201_ADDR 0x45
#define LED_GPIO 18
#define DISTANCE_MIN 50  // mm
#define DISTANCE_MAX 500 // mm
#define FREQ_MIN 10.0   // Hz
#define FREQ_MAX 1.0    // Hz
#define SAMPLE_INTERVAL 100 // ms
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY 10 // ms

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_distance(uint16_t *distance);
float calculate_frequency(uint16_t distance);
void control_led(float frequency);
void log_data(uint16_t distance, float frequency);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data (optional)
typedef struct {
    uint16_t distance;
    float frequency;
} sensor_data_t;

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, CH201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read distance from the CH201 sensor
int read_distance(uint16_t *distance) {
    char reg = 0x00; // Example register to read from (adjust as needed)
    char buf[2];
    int retries = I2C_RETRY_COUNT;

    while (retries > 0) {
        if (i2cWriteDevice(i2c_handle, &reg, 1) != 0) {
            fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
            gpioDelay(I2C_RETRY_DELAY * 1000); // Delay in microseconds
            retries--;
            continue;
        }

        if (i2cReadDevice(i2c_handle, buf, 2) == 2) {
            *distance = (buf[0] << 8) | buf[1]; // Combine the two bytes
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
            gpioDelay(I2C_RETRY_DELAY * 1000); // Delay in microseconds
            retries--;
        }
    }

    fprintf(stderr, "Failed to read distance after multiple retries.\n");
    return -1; // Failure
}

// Calculate blink frequency based on distance
float calculate_frequency(uint16_t distance) {
    float frequency = (float)(distance - DISTANCE_MIN) / (DISTANCE_MAX - DISTANCE_MIN) * (FREQ_MIN - FREQ_MAX) + FREQ_MAX;
    if (frequency < FREQ_MIN) frequency = FREQ_MIN;
    if (frequency > FREQ_MAX) frequency = FREQ_MAX;
    return frequency;
}

// Control the LED based on the calculated frequency
void control_led(float frequency) {
    static uint32_t last_tick = 0;
    uint32_t current_tick = gpioTick();
    uint32_t period = (uint32_t)(1000000.0 / frequency); // Period in microseconds
    uint32_t half_period = period / 2;

    if (current_tick - last_tick >= half_period * 1000) { // Check if half period has passed
        gpioWrite(LED_GPIO, !gpioRead(LED_GPIO)); // Toggle LED state
        last_tick = current_tick;
    }
}

// Log the distance and frequency to stdout
void log_data(uint16_t distance, float frequency) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s, Distance: %d mm, Frequency: %.2f Hz\n", timestamp, distance, frequency);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    gpioWrite(LED_GPIO, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t distance;
    float frequency;

    // Main loop
    while (!terminate) {
        if (read_distance(&distance) == 0) {
            frequency = calculate_frequency(distance);
            control_led(frequency);
            log_data(distance, frequency);
        } else {
            fprintf(stderr, "Failed to read distance. Retrying I2C initialization.\n");
            i2cClose(i2c_handle);
            if (init_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                terminate = 1; // Exit loop if re-initialization fails
            }
        }

        gpioDelay(SAMPLE_INTERVAL * 1000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

