int read_distance(int *distance) {
    char buf[1];
    char data[2];
    int retries = 0;

    buf[0] = MEASURE_CMD;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(i2c_handle, buf, MEASURE_CMD_LEN) != MEASURE_CMD_LEN) {
            fprintf(stderr, "Error writing to I2C device (attempt %d): %d\n", retries + 1, i2c_handle);
