        if (i2cReadDevice(i2c_handle, data, DISTANCE_DATA_LEN) != DISTANCE_DATA_LEN) {
            fprintf(stderr, "Error reading from I2C device (attempt %d): %d\n", retries + 1, i2c_handle);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
            continue;
        }

        *distance = (data[0] << 8) | data[1];
        return 0; // Success
    }

    fprintf(stderr, "Failed to read distance after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
