#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

// Define constants
#define I2C_BUS "/dev/i2c-1"
#define CH101_ADDR 0x49
#define MEAS_TRIGGER_REG 0x04
#define MEAS_STATUS_REG 0x06
#define DIST_HIGH_REG 0x08
#define DIST_LOW_REG 0x09
#define DATA_READY_BIT 0x01
#define TIMEOUT_MS 50
#define SAMPLE_INTERVAL_MS 500

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_write(int fd, uint8_t reg, uint8_t value);
int i2c_read(int fd, uint8_t reg, uint8_t *value);
int i2c_read_block(int fd, uint8_t reg, uint8_t *data, int len);
int trigger_measurement(int fd);
int read_distance(int fd, int *distance_mm);
int log_data(const char *timestamp, int distance_mm);
void signal_handler(int sig);
int setup();
void cleanup();

// I2C write function
int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address for read: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "Error reading from I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// I2C read block function
int i2c_read_block(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address for block read: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, data, len) != len) {
        fprintf(stderr, "Error reading block from I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Trigger measurement function
int trigger_measurement(int fd) {
    return i2c_write(fd, MEAS_TRIGGER_REG, 0x01);
}

// Read distance function
int read_distance(int fd, int *distance_mm) {
    uint8_t dist_high, dist_low;

    if (i2c_read(fd, DIST_HIGH_REG, &dist_high) != 0) return -1;
    if (i2c_read(fd, DIST_LOW_REG, &dist_low) != 0) return -1;

    *distance_mm = (dist_high << 8) | dist_low;
    return 0;
}

// Log data function
int log_data(const char *timestamp, int distance_mm) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }
    fprintf(log_file, "%s,%d\n", timestamp, distance_mm);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received (%d). Terminating...\n", sig);
    terminate = 1;
}

// Setup function
int setup() {
    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return -1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, CH101_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return -1;
    }

    // Open log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return -1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    return 0;
}

// Cleanup function
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    if (setup() != 0) {
        return 1;
    }

    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = SAMPLE_INTERVAL_MS * 1000000; // 500 ms

    while (!terminate) {
        int distance_mm;
        struct timespec start_time, current_time;
        clock_gettime(CLOCK_MONOTONIC, &start_time);

        // Trigger measurement
        if (trigger_measurement(i2c_fd) != 0) {
            fprintf(stderr, "Error triggering measurement. Skipping sample.\n");
            nanosleep(&sleep_time, NULL);
            continue;
        }

        // Poll for data ready with timeout
        int timeout = TIMEOUT_MS;
        int data_ready = 0;
        while (timeout > 0 && !data_ready) {
            uint8_t status;
            if (i2c_read(i2c_fd, MEAS_STATUS_REG, &status) == 0) {
                if (status & DATA_READY_BIT) {
                    data_ready = 1;
                }
            } else {
                fprintf(stderr, "Error reading measurement status. Skipping sample.\n");
                nanosleep(&sleep_time, NULL);
                terminate = 1; // Exit loop on error
                break;
            }
            usleep(1000); // Check every 1 ms
            timeout--;
        }

        if (!data_ready) {
            fprintf(stderr, "Timeout waiting for data ready. Skipping sample.\n");
            nanosleep(&sleep_time, NULL);
            continue;
        }

        // Read distance
        if (read_distance(i2c_fd, &distance_mm) != 0) {
            fprintf(stderr, "Error reading distance. Skipping sample.\n");
            nanosleep(&sleep_time, NULL);
            continue;
        }

        // Get timestamp
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[30];
        time(&rawtime);
        timeinfo = gmtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

        // Log data
        if (log_data(timestamp, distance_mm) != 0) {
            fprintf(stderr, "Error logging data. Skipping sample.\n");
        }

        // Sleep
        nanosleep(&sleep_time, NULL);
    }

    cleanup();
    return 0;
}

