#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Define constants
#define I2C_BUS 1
#define MLX75030_ADDR 0x4C
#define DISTANCE_REG 0x00 // Example register address, adjust as needed
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define READ_INTERVAL_MS 100

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t distance;
    struct timespec timestamp;
} sensor_data_t;

// Function prototypes
int init_pigpio();
int init_i2c();
int read_distance(uint16_t *distance);
void log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX75030_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read distance from the sensor with retries
int read_distance(uint16_t *distance) {
    char buf[2];
    int result, retries = 0;

    while (retries < RETRY_COUNT) {
        result = i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, buf, 2);
        if (result == 2) {
            *distance = (buf[0] << 8) | buf[1]; // Assuming big-endian
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "Failed to read distance after %d retries\n", RETRY_COUNT);
    return -1; // Failure
}

// Log data to the console
void log_data(sensor_data_t data) {
    char timestamp_str[30];
    struct tm *tm_info;

    tm_info = localtime(&data.timestamp.tv_sec);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", tm_info);
    printf("%s.%03ld: Distance = %u mm\n", timestamp_str, data.timestamp.tv_nsec / 1000000, data.distance);
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    printf("MLX75030 Distance Sensor Reader\n");

    // Main loop
    while (!terminate) {
        uint16_t distance;
        sensor_data_t data;

        // Read distance
        if (read_distance(&distance) == 0) {
            // Get timestamp
            if (clock_gettime(CLOCK_REALTIME, &data.timestamp) == 0) {
                data.distance = distance;
                // Log data
                log_data(data);
            } else {
                fprintf(stderr, "Failed to get timestamp\n");
            }
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }

        // Delay for 100 ms
        gpioDelay(READ_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

