#include <errno.h>

// VL53L4CX I2C address
#define VL53L4CX_ADDR 0x29

// VL53L4CX register addresses
#define VL53L4CX_REG_SOFT_RESET 0x7FFF
#define VL53L4CX_REG_START_RANGING 0x0009
#define VL53L4CX_REG_INTERRUPT_STATUS 0x0046
#define VL53L4CX_REG_DISTANCE_HIGH 0x0096
#define VL53L4CX_REG_DISTANCE_LOW 0x0097

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l4cx_init();
int vl53l4cx_start_ranging();
int vl53l4cx_read_distance(uint16_t *distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// VL53L4CX initialization function
int vl53l4cx_init() {
    int status;

    // Soft reset
    status = i2cWriteByteData(i2c_handle, VL53L4CX_REG_SOFT_RESET, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error: Failed to write to soft reset register: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(10); // Wait 10 ms

    // Start ranging
    status = i2cWriteByteData(i2c_handle, VL53L4CX_REG_START_RANGING, 0x00);
    if (status < 0) {
        fprintf(stderr, "Error: Failed to write to start ranging register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// VL53L4CX start ranging function
int vl53l4cx_start_ranging() {
    // This function is not strictly necessary for VL53L4CX, but it's good practice
    // to include it for consistency with other sensors.
    return 0; // No error
}

// VL53L4CX read distance function
int vl53l4cx_read_distance(uint16_t *distance) {
    int status;
    uint8_t high_byte, low_byte;

    // Poll interrupt status register
    status = i2cReadByteData(i2c_handle, VL53L4CX_REG_INTERRUPT_STATUS);
    if (status < 0) {
        fprintf(stderr, "Error: Failed to read interrupt status register: %s\n", strerror(errno));
        return -1;
    }

    if ((status & 0x01) == 0) {
        // Interrupt not set, skip reading distance
        return 0;
    }

    // Read distance data
    status = i2cReadByteData(i2c_handle, VL53L4CX_REG_DISTANCE_HIGH);
    if (status < 0) {
        fprintf(stderr, "Error: Failed to read distance high byte: %s\n", strerror(errno));
        return -1;
    }
    high_byte = (uint8_t)status;

    status = i2cReadByteData(i2c_handle, VL53L4CX_REG_DISTANCE_LOW);
    if (status < 0) {
        fprintf(stderr, "Error: Failed to read distance low byte: %s\n", strerror(errno));
        return -1;
    }
    low_byte = (uint8_t)status;

    *distance = (uint16_t)((high_byte << 8) | low_byte);

    return 0;
}

