#include <time.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define BUZZER_GPIO 22
#define DISTANCE_THRESHOLD 100 // mm
#define RETRY_DELAY_MS 100
#define MAX_RETRIES 3

// VL53L1X register addresses
#define SOFT_RESET 0x0001
#define I2C_SLAVE__DEVICE_ADDRESS 0x0001
#define SYSTEM__MODE_START 0x0007
#define RESULT__FINAL_CROSSTALK_CORRECTED_DISTANCE_MM 0x0096

// Global variables
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_vl53l1x();
int read_distance();
void control_buzzer(int distance);
void signal_handler(int signal);
int write_byte(int reg, int data);
int read_byte(int reg, int *data);
int read_word(int reg, int *data);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to write a byte to a VL53L1X register
int write_byte(int reg, int data) {
    char buf[2];
    buf[0] = reg;
    buf[1] = data;
    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read a byte from a VL53L1X register
int read_byte(int reg, int *data) {
    int result = i2cWriteDevice(i2c_handle, (char *)&reg, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing register address for read 0x%02X: %d\n", reg, result);
        return -1;
    }
    result = i2cReadDevice(i2c_handle, (char *)data, 1);
    if (result != 0) {
        fprintf(stderr, "Error reading from register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read a word (2 bytes) from a VL53L1X register
int read_word(int reg, int *data) {
    char buf[1];
    buf[0] = reg;
    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing register address for read 0x%02X: %d\n", reg, result);
        return -1;
    }
    char read_buf[2];
    result = i2cReadDevice(i2c_handle, read_buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error reading from register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *data = (read_buf[0] << 8) | read_buf[1];
    return 0;
}

// Function to initialize the VL53L1X sensor
int init_vl53l1x() {
    int retries = 0;
    int status = 0;

    while (retries < MAX_RETRIES) {
        // Soft reset
        if (write_byte(SOFT_RESET, 0x01) != 0) {
            fprintf(stderr, "Soft reset failed, retrying...\n");
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
            continue;
        }
        gpioDelay(10000); // Wait for reset to complete (10ms)

        // Set I2C address (optional, but good practice)
        if (write_byte(I2C_SLAVE__DEVICE_ADDRESS, VL53L1X_ADDR) != 0) {
            fprintf(stderr, "Setting I2C address failed, retrying...\n");
            gpioDelay(RETRY_DELAY_MS * 1000);
            retries++;
            continue;
