        if (read_word(RESULT__FINAL_CROSSTALK_CORRECTED_DISTANCE_MM, &distance) == 0) {
            status = 1; // Read successful
            break;
        } else {
            fprintf(stderr, "Reading distance failed, retrying...\n");
            gpioDelay(RETRY_DELAY_MS * 1000);
            retries++;
        }
    }

    if (status == 0) {
        fprintf(stderr, "Failed to read distance after %d retries.\n", MAX_RETRIES);
        return -1; // Return error value
    }

    return distance;
}

