#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 17

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 50000        // 50ms timeout
#define MIN_DISTANCE 2.0       // Minimum measurable distance (cm)
#define MAX_DISTANCE 400.0     // Maximum measurable distance (cm)
#define MIN_ANGLE -90.0        // Minimum servo angle (degrees)
#define MAX_ANGLE 90.0         // Maximum servo angle (degrees)

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
void triggerSensor();
long pulseIn(int pin, int level, int timeout);
float calculateDistance(long pulseWidth);
int mapDistanceToAngle(float distance);
void setServoAngle(int angle);
void logData(float distance, int angle);
void signalHandler(int signal);

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the pulse width on the echo pin
long pulseIn(int pin, int level, int timeout) {
    long startTime = 0, endTime = 0;
    long pulseWidth = 0;

    // Wait for the pulse to start
    while (gpioRead(pin) != level) {
        startTime = gpioTick();
        if (startTime == 0) return -1; // Error: gpioTick() failed
        if (gpioTick() - startTime > timeout) return -1; // Timeout
    }

    // Measure the pulse width
    startTime = gpioTick();
    while (gpioRead(pin) == level) {
        endTime = gpioTick();
        if (endTime == 0) return -1; // Error: gpioTick() failed
        if (endTime - startTime > timeout) return -1; // Timeout
    }

    pulseWidth = endTime - startTime;
    return pulseWidth;
}

// Function to calculate the distance in centimeters
float calculateDistance(long pulseWidth) {
    return (float)pulseWidth * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Function to map the distance to a servo angle
int mapDistanceToAngle(float distance) {
    // Clamp distance to the valid range
    if (distance < MIN_DISTANCE) {
        distance = MIN_DISTANCE;
    } else if (distance > MAX_DISTANCE) {
        distance = MAX_DISTANCE;
    }

    // Map distance to angle
    float angle = (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE) * (MAX_ANGLE - MIN_ANGLE) + MIN_ANGLE;
    return (int)angle;
}

// Function to set the servo angle
void setServoAngle(int angle) {
    // Ensure angle is within the valid range
    if (angle < MIN_ANGLE) {
        angle = MIN_ANGLE;
    } else if (angle > MAX_ANGLE) {
        angle = MAX_ANGLE;
    }

    // Calculate pulse width (1ms + (angle / 180) * 1ms)
    int pulseWidth = 1000 + (int)((float)(angle - MIN_ANGLE) / (MAX_ANGLE - MIN_ANGLE) * 1000.0);

    gpioServo(SERVO_PIN, pulseWidth);
}

// Function to log the data to a file
void logData(float distance, int angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Distance: %.2f cm, Angle: %d degrees\n", timestamp, distance, angle);
    fflush(log_file); // Ensure data is written to the file immediately
}

// Signal handler for graceful shutdown
void signalHandler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Open the log file
    log_file = fopen("sensor_data.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    printf("Parking assist system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Trigger the sensor
        triggerSensor();

        // Measure the pulse width
        long pulseWidth = pulseIn(ECHO_PIN, 1, TIMEOUT_US);

        // Check for timeout or error
        if (pulseWidth < 0) {
            fprintf(stderr, "Timeout or error reading echo pulse\n");
            logData(-1.0, -1); // Log error
        } else {
            // Calculate the distance
            float distance = calculateDistance(pulseWidth);

            // Map the distance to a servo angle
            int angle = mapDistanceToAngle(distance);

            // Set the servo angle
            setServoAngle(angle);

            // Log the data
            logData(distance, angle);
        }

        // Wait for 200ms
        gpioDelay(200000);
    }

    // Stop the servo
    setServoAngle(0);

    // Close the log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    printf("Parking assist system stopped.\n");

    return 0;
}

