#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define BUZZER_PIN 22

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define DISTANCE_RANGE_MIN 2.0  // cm
#define DISTANCE_RANGE_MAX 400.0 // cm
#define BUZZER_THRESHOLD 30.0   // cm
#define TRIGGER_PULSE_DURATION 10 // us
#define TIMEOUT_US 50000         // us (50ms)

// Global variables
volatile uint32_t start_tick = 0;
volatile uint32_t end_tick = 0;
volatile int echo_received = 0;
volatile int timeout_flag = 0;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// Function to generate a trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_DURATION);
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin interrupt
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        // Rising edge
        start_tick = tick;
        echo_received = 1; // Indicate that a rising edge was received
        timeout_flag = 0;  // Reset timeout flag
    } else if (level == 0) {
        // Falling edge
        if (echo_received) {
            end_tick = tick;
            echo_received = 0; // Reset echo_received flag
        }
    } else if (level == PI_TIMEOUT) {
        // Timeout occurred
        timeout_flag = 1;
        echo_received = 0; // Reset echo_received flag
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    gpioTerminate();          // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Register interrupt callback for echo pin
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to register interrupt callback\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Parking sensor started. Press Ctrl+C to exit.\n");

    while (1) {
        // Trigger the sensor
        trigger_pulse();
        echo_received = 0; // Reset echo_received flag before triggering
        timeout_flag = 0;  // Reset timeout flag before triggering

        // Wait for echo or timeout
        int timeout_count = 0;
        while (!echo_received && !timeout_flag && timeout_count < 100) {
            gpioDelay(1000); // Wait 1ms
            timeout_count++;
        }

        // Calculate distance
        double distance = -1.0; // Initialize to an invalid value
        if (echo_received) {
            uint32_t diff = end_tick - start_tick;
            if (diff > 0) {
                double time_taken = (double)diff / 1000000.0; // Time in seconds
                distance = (time_taken * SPEED_OF_SOUND) / 2.0;
            } else {
                fprintf(stderr, "Error: Invalid time difference\n");
            }
        } else if (timeout_flag) {
            fprintf(stderr, "Error: Timeout occurred\n");
        }

        // Validate distance
        if (distance >= DISTANCE_RANGE_MIN && distance <= DISTANCE_RANGE_MAX) {
            // Display distance
            printf("Distance: %.2f cm\n", distance);

            // Control buzzer
            if (distance < BUZZER_THRESHOLD) {
                gpioWrite(BUZZER_PIN, 1); // Turn on buzzer
            } else {
                gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
            }
        } else {
            fprintf(stderr, "Error: Invalid distance reading\n");
        }

        gpioDelay(100000); // Wait 100ms
    }

    return 0;
}

