// Function to write a byte to a VL53L1X register
int vl53l1x_write_byte(int reg, int data) {
    char buf[2];
    buf[0] = reg;
    buf[1] = data;
    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to VL53L1X register 0x%02x: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read a byte from a VL53L1X register
int vl53l1x_read_byte(int reg, int *data) {
    int result = i2cWriteDevice(i2c_handle, (char *)&reg, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing register address for read: %d\n", result);
        return -1;
    }
    result = i2cReadDevice(i2c_handle, (char *)data, 1);
    if (result != 0) {
        fprintf(stderr, "Error reading from VL53L1X register 0x%02x: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read a word (2 bytes) from a VL53L1X register
int vl53l1x_read_word(int reg, int *data) {
    char buf[1];
    buf[0] = reg;
    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing register address for read: %d\n", result);
        return -1;
    }
    result = i2cReadDevice(i2c_handle, (char *)data, 2);
    if (result != 0) {
        fprintf(stderr, "Error reading from VL53L1X register 0x%02x: %d\n", reg, result);
        return -1;
    }
    *data = (*data << 8) | ((*data >> 8) & 0xFF); // Swap bytes for big-endian
    return 0;
}

