// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SERVO_PIN 18
#define DISTANCE_THRESHOLD 200 // mm
#define SERVO_OPEN_PULSE 2000  // us
#define SERVO_CLOSE_PULSE 1000 // us
#define SERVO_NEUTRAL_PULSE 1500 // us
#define MQTT_BROKER "localhost" // Replace with your broker address
#define MQTT_PORT 1883
#define MQTT_GATE_TOPIC "gate_control"
#define MQTT_STATUS_TOPIC "gate_status"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
struct mosquitto *mqtt_client = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance();
void servo_set_pulse(int pulse_width);
void log_event(const char *event);
void mqtt_connect_callback(struct mosquitto *mosq, void *userdata, int result);
void mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
void mqtt_disconnect_callback(struct mosquitto *mosq, void *userdata, int rc);
void signal_handler(int signal);
