#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SHUTDOWN_PIN 23
#define INTERRUPT_PIN 24
#define SERVO_PIN 18
#define DISTANCE_THRESHOLD_OPEN 500 // 50 cm in mm
#define DISTANCE_THRESHOLD_CLOSE 600 // 60 cm in mm
#define SERVO_OPEN_PULSE_WIDTH 2000 // 2000 us
#define SERVO_CLOSE_PULSE_WIDTH 1000 // 1000 us
#define SERVO_NEUTRAL_PULSE_WIDTH 1500 // 1500 us
#define SERVO_FREQUENCY 50 // Hz

// Global variables
int i2c_handle;
volatile int gate_state = 0; // 0: closed, 1: open
volatile int distance = 0;
volatile int running = 1;

// Function prototypes
int init_vl53l1x();
int read_distance();
void open_gate();
void close_gate();
void stop_gate();
void log_event(const char *event);
void interrupt_handler(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// VL53L1X register addresses (Example - adjust based on datasheet)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_RANGING_RESULT_FINAL_CROSSTALK_CORRECTIONS_ENABLES 0x001E
#define VL53L1X_REG_RANGING_RESULT_FINAL_CROSSTALK_CORRECTION_VALUE 0x001F
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// Function to read a register from the VL53L1X
int read_register(int reg, uint8_t *data, int len) {
    char buf[1];
    buf[0] = reg;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 1) {
        fprintf(stderr, "Error writing register address for read.\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, (char *)data, len) != len) {
        fprintf(stderr, "Error reading register data.\n");
        return -1;
    }
    return 0;
}

// Function to write a register to the VL53L1X
int write_register(int reg, uint8_t data) {
    char buf[2];
    buf[0] = reg;
    buf[1] = data;
    if (i2cWriteDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing register data.\n");
        return -1;
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SHUTDOWN_PIN, PI_OUTPUT);
    gpioSetMode(INTERRUPT_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set PWM frequency for servo motor
    gpioSetPWMfrequency(SERVO_PIN, SERVO_FREQUENCY);
    gpioSetPWMrange(SERVO_PIN, 2000); // Set PWM range to 2000 for 1ms resolution

    // Set initial servo position (closed)
    stop_gate();

    // Set interrupt handler for VL53L1X interrupt pin
    gpioSetAlertFunc(INTERRUPT_PIN, interrupt_handler);

    printf("Smart Parking Gate System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read distance from VL53L1X sensor
        distance = read_distance();

        // Check for errors during distance reading
        if (distance < 0) {
            fprintf(stderr, "Error reading distance. Retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Gate control logic with hysteresis
        if (distance < DISTANCE_THRESHOLD_OPEN && gate_state == 0) {
            open_gate();
        } else if (distance > DISTANCE_THRESHOLD_CLOSE && gate_state == 1) {
            close_gate();
        }

        gpioDelay(50); // Delay to avoid excessive CPU usage
    }

    // Cleanup and exit
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Smart Parking Gate System stopped.\n");
    return 0;
}

// Initialize VL53L1X sensor
int init_vl53l1x() {
    uint8_t model_id;

    // Check sensor model ID
    if (read_register(VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id, 1) != 0) {
        fprintf(stderr, "Error reading model ID\n");
        return -1;
    }

    if (model_id != 0xEACC) {
        fprintf(stderr, "Incorrect model ID: 0x%02X\n", model_id);
        return -1;
    }

    // Configure VL53L1X for continuous ranging mode (Example configuration)
    // This is a simplified example.  Refer to the VL53L1X datasheet for full configuration.
    if (write_register(0x02d8, 0x01) != 0) return -1; // Set timing budget
    if (write_register(0x02d9, 0x00) != 0) return -1; // Set inter-measurement period
    if (write_register(0x0088, 0x00) != 0) return -1; // Set inter-measurement period
    if (write_register(0x0080, 0x01) != 0) return -1; // Start ranging

    return 0;
}

// Read distance from VL53L1X sensor
int read_distance() {
    uint8_t range_status;
    uint8_t distance_msb, distance_lsb;
    int distance;

    // Read range status
    if (read_register(VL53L1X_REG_RESULT_RANGE_STATUS, &range_status, 1) != 0) {
        fprintf(stderr, "Error reading range status\n");
        return -1;
    }

    // Read distance data
    if (read_register(VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, &distance_msb, 1) != 0) {
        fprintf(stderr, "Error reading distance MSB\n");
        return -1;
    }
    if (read_register(VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 + 1, &distance_lsb, 1) != 0) {
        fprintf(stderr, "Error reading distance LSB\n");
        return -1;
    }

    distance = (distance_msb << 8) | distance_lsb;

    return distance;
}

// Open the gate
void open_gate() {
    gpioPWM(SERVO_PIN, SERVO_OPEN_PULSE_WIDTH);
    gate_state = 1;
    log_event("Gate opened");
    printf("Gate opened (Distance: %d mm)\n", distance);
}

// Close the gate
void close_gate() {
    gpioPWM(SERVO_PIN, SERVO_CLOSE_PULSE_WIDTH);
    gate_state = 0;
    log_event("Gate closed");
    printf("Gate closed (Distance: %d mm)\n", distance);
}

// Stop the gate (neutral position)
void stop_gate() {
    gpioPWM(SERVO_PIN, SERVO_NEUTRAL_PULSE_WIDTH);
    log_event("Gate stopped");
    printf("Gate stopped (Distance: %d mm)\n", distance);
}

// Log events to file
void log_event(const char *event) {
    FILE *fp = fopen("parking_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s - %s - Distance: %d mm\n", s, event, distance);
    fclose(fp);
}

// Interrupt handler for VL53L1X interrupt pin
void interrupt_handler(int gpio, int level, uint32_t tick) {
    // This function is called when the VL53L1X interrupt pin changes state.
    // You can add code here to handle the interrupt, such as reading the distance
    // and updating the gate state.
    // For this example, we simply log the event.
    log_event("VL53L1X interrupt triggered");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received, stopping...\n");
    running = 0;
    stop_gate(); // Stop the gate before exiting
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

