#include <unistd.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GATE_OPEN_GPIO 18
#define GATE_CLOSE_GPIO 19
#define DISTANCE_THRESHOLD 200 // mm
#define LOG_FILE "gate_events.log"

// VL53L1X register addresses (example, adjust as needed)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L1X_REG_SYSRANGE_START 0x0040
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance(uint16_t *distance);
void control_gate(int distance);
void log_event(const char *event);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// Initialize VL53L1X sensor
int init_vl53l1x() {
    // Soft reset
    char buf[2];
    buf[0] = 0x00; // Reset register address
    buf[1] = 0x01; // Reset value
    if (i2cWriteI2CBlockData(i2c_handle, buf[0], buf + 1, 1) != 0) {
        fprintf(stderr, "Error: VL53L1X soft reset failed\n");
        return -1;
    }
    gpioDelay(10000); // Wait for reset to complete

    // Check device ID (example)
    buf[0] = VL53L1X_REG_IDENTIFICATION_MODEL_ID;
    if (i2cWriteI2CBlockData(i2c_handle, buf[0], buf, 1) != 0) {
        fprintf(stderr, "Error: Failed to write to VL53L1X register\n");
        return -1;
    }
    char model_id;
    if (i2cReadI2CBlockData(i2c_handle, buf[0], &model_id, 1) != 1) {
        fprintf(stderr, "Error: Failed to read from VL53L1X register\n");
        return -1;
    }

    if (model_id != 0xEACC) {
        fprintf(stderr, "Error: Incorrect VL53L1X model ID: 0x%02X\n", model_id);
        return -1;
    }

    // Configure timing budget (example: 33ms)
    buf[0] = 0x001E; // Timing budget register address
    buf[1] = 0x00; // Timing budget value (33ms)
    if (i2cWriteI2CBlockData(i2c_handle, buf[0], buf + 1, 1) != 0) {
        fprintf(stderr, "Error: Failed to write timing budget to VL53L1X\n");
        return -1;
    }

    return 0;
}

// Read distance from VL53L1X sensor
int read_distance(uint16_t *distance) {
    char buf[1];
    char data[2];

    // Start ranging
    buf[0] = VL53L1X_REG_SYSRANGE_START;
    if (i2cWriteI2CBlockData(i2c_handle, buf[0], buf, 1) != 0) {
        fprintf(stderr, "Error: Failed to start ranging\n");
        return -1;
    }

    // Wait for measurement to be ready (polling, can be improved with interrupts)
    gpioDelay(10000); // Wait 10ms

    // Read distance
    buf[0] = VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0;
    if (i2cWriteI2CBlockData(i2c_handle, buf[0], buf, 1) != 0) {
        fprintf(stderr, "Error: Failed to write to VL53L1X register\n");
        return -1;
    }
    if (i2cReadI2CBlockData(i2c_handle, buf[0], data, 2) != 2) {
        fprintf(stderr, "Error: Failed to read distance from VL53L1X\n");
        return -1;
    }

    *distance = (data[0] << 8) | data[1];
    return 0;
}

// Control gate actuator
void control_gate(int distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(GATE_OPEN_GPIO, 1);
        gpioWrite(GATE_CLOSE_GPIO, 0);
        log_event("Gate opened");
    } else {
        gpioWrite(GATE_OPEN_GPIO, 0);
        gpioWrite(GATE_CLOSE_GPIO, 1);
        log_event("Gate closed");
    }
}

// Log event to file
void log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *gmtime(&t);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file); // Ensure immediate write
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(GATE_OPEN_GPIO, PI_OUTPUT);
    gpioSetMode(GATE_CLOSE_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t distance;

    // Main loop
    while (!terminate) {
        if (read_distance(&distance) == 0) {
            printf("Distance: %d mm\n", distance);
            control_gate(distance);
        } else {
            fprintf(stderr, "Error: Failed to read distance\n");
            log_event("Error: Failed to read distance");
        }

        gpioDelay(500000); // 500 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(GATE_OPEN_GPIO, 0);
    gpioWrite(GATE_CLOSE_GPIO, 0);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

