// I2C write function
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read_byte(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// MPR121 initialization function
int mpr121_init(int fd) {
    // Soft reset
    if (i2c_write_byte(fd, MPR121_ELECONFIG0, 0x63) < 0) return -1;
    usleep(10000); // Wait for reset

    // Verify sensor presence (read MHD_R register)
    uint8_t mhd_r;
    if (i2c_read_byte(fd, MPR121_MHDR, &mhd_r) < 0) return -1;

    // Baseline filtering
    if (i2c_write_byte(fd, MPR121_MHDR, 0x01) < 0) return -1;
    if (i2c_write_byte(fd, MPR121_NHDR, 0x01) < 0) return -1;
    if (i2c_write_byte(fd, MPR121_NCLR, 0x0E) < 0) return -1;
    if (i2c_write_byte(fd, MPR121_FDLR, 0x00) < 0) return -1;

    // Auto-configuration thresholds
    if (i2c_write_byte(fd, MPR121_ELE0_TOUCHTH, 0x0B) < 0) return -1;
    if (i2c_write_byte(fd, MPR121_ELE0_RELEASETH, 0x0C) < 0) return -1;
    if (i2c_write_byte(fd, MPR121_ELE1_TOUCHTH, 0x0B) < 0) return -1;
    if (i2c_write_byte(fd, MPR121_ELE1_RELEASETH, 0x0C) < 0) return -1;
    if (i2c_write_byte(fd, MPR121_ELE2_TOUCHTH, 0x0B) < 0) return -1;
    if (i2c_write_byte(fd, MPR121_ELE2_RELEASETH, 0x0C) < 0) return -1;
    if (i2c_write_byte(fd, MPR121_ELE3_TOUCHTH, 0x0B) < 0) return -1;
    if (i2c_write_byte(fd, MPR121_ELE3_RELEASETH, 0x0C) < 0) return -1;
    if (i2c_write_byte(fd, MPR121_ELE4_TOUCHTH, 0x0B) < 0) return -1;
    if (i2c_write_byte(fd, MPR121_ELE4_RELEASETH, 0x0C) < 0) return -1;
    if (i2c_write_byte(fd, MPR121_ELE5_TOUCHTH, 0x0B) < 0) return -1;
    if (i2c_write_byte(fd, MPR121_ELE5_RELEASETH, 0x0C) < 0) return -1;
    if (i2c_write_byte(fd, MPR121_ELE6_TOUCHTH, 0x0B) < 0) return -1;
    if (i2c_write_byte(fd, MPR121_ELE6_RELEASETH, 0x0C) < 0) return -1;
    if (i2c_write_byte(fd, MPR121_ELE7_TOUCHTH, 0x0B) < 0) return -1;
    if (i2c_write_byte(fd, MPR121_ELE7_RELEASETH, 0x0C) < 0) return -1;
    if (i2c_write_byte(fd, MPR121_ELE8_TOUCHTH, 0x0B) < 0) return -1;
    if (i2c_write_byte(fd, MPR121_ELE8_RELEASETH, 0x0C) < 0) return -1;
    if (i2c_write_byte(fd, MPR121_ELE9_TOUCHTH, 0x0B) < 0) return -1;
    if (i2c_write_byte(fd, MPR121_ELE9_RELEASETH, 0x0C) < 0) return -1;
    if (i2c_write_byte(fd, MPR121_ELE10_TOUCHTH, 0x0B) < 0) return -1;
    if (i2c_write_byte(fd, MPR121_ELE10_RELEASETH, 0x0C) < 0) return -1;
    if (i2c_write_byte(fd, MPR121_ELE11_TOUCHTH, 0x0B) < 0) return -1;
    if (i2c_write_byte(fd, MPR121_ELE11_RELEASETH, 0x0C) < 0) return -1;

    // Enable all electrodes in run mode
    if (i2c_write_byte(fd, MPR121_ELECONFIG0, 0x0C) < 0) return -1;

    return 0;
}

// Read touch status function
int read_touch_status(int fd, uint16_t *touch_status) {
    uint8_t touch_status_l, touch_status_h;

    if (i2c_read_byte(fd, MPR121_TOUCHSTATUS_L, &touch_status_l) < 0) return -1;
    if (i2c_read_byte(fd, MPR121_TOUCHSTATUS_H, &touch_status_h) < 0) return -1;

    *touch_status = (touch_status_h << 8) | touch_status_l;
    return 0;
}

// Set LED pattern function
void set_led_pattern(int gpio, uint8_t pattern) {
    gpio_set_value(gpio_lines[gpio], (pattern != 0) ? 1 : 0);
}

// Log event function
void log_event(int electrode) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char buf[64];
    strftime(buf, sizeof(buf) - 1, "%Y-%m-%d %H:%M:%S", t);
    printf("%s - Electrode %d touched\n", buf, electrode);
}

// Signal handler function
void signal_handler(int sig) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", sig);
}

// I2C open function
int i2c_open(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }
    return fd;
}

// I2C close function
void i2c_close(int fd) {
    close(fd);
}

// GPIO set value function
void gpio_set_value(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        perror("Failed to set GPIO value");
    }
}

// GPIO request line function
void gpio_request_line(struct gpiod_chip *chip, int offset, const char *consumer) {
    struct gpiod_line *line = gpiod_chip_get_line(chip, offset);
    if (!line) {
        perror("Failed to get GPIO line");
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_output(line, consumer, 0) < 0) {
        perror("Failed to request GPIO line as output");
        exit(EXIT_FAILURE);
    }
    gpio_lines[offset] = line;
}

// GPIO release line function
void gpio_release_line(struct gpiod_line *line) {
    if (line) {
        gpiod_line_release(line);
    }
}

// GPIO release chip function
void gpio_release_chip(struct gpiod_chip *chip) {
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // I2C initialization
    i2c_fd = i2c_open(I2C_BUS);
    if (i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    // MPR121 initialization
    if (mpr121_init(i2c_fd) < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        i2c_close(i2c_fd);
        return EXIT_FAILURE;
    }

    // GPIO initialization
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        i2c_close(i2c_fd);
        return EXIT_FAILURE;
    }

    int led_gpios[] = LED_GPIOS;
    for (int i = 0; i < NUM_LEDS; i++) {
        gpio_request_line(gpio_chip, led_gpios[i], "proximity_art");
    }

    // Main loop
    uint16_t touch_status;
    int active_electrode = -1;

    while (program_running) {
        if (read_touch_status(i2c_fd, &touch_status) == 0) {
            // Determine active electrode
            for (int i = 0; i < NUM_ELECTRODES; i++) {
                if (touch_status & (1 << i)) {
                    active_electrode = i;
                    break;
                }
            }

            // Set LED pattern
            if (active_electrode != -1) {
                set_led_pattern(active_electrode, led_patterns[active_electrode]);
                log_event(active_electrode);
            } else {
                // No electrode active
                for (int i = 0; i < NUM_LEDS; i++) {
                    set_led_pattern(i, 0);
                }
                printf("No electrode active\n");
            }
        } else {
            fprintf(stderr, "Failed to read touch status\n");
        }

        usleep(POLL_INTERVAL_MS * 1000); // Poll every 50ms
    }

    // Cleanup
    for (int i = 0; i < NUM_LEDS; i++) {
        gpio_release_line(gpio_lines[i]);
    }
    gpio_release_chip(gpio_chip);
    i2c_close(i2c_fd);

    return EXIT_SUCCESS;
}

