#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0       // cm
#define MAX_DISTANCE 400.0     // cm
#define TIMEOUT_US 30000        // 30 ms
#define TRIGGER_PULSE_US 10     // 10 us trigger pulse

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static int pigpio_initialized = 0;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void trigger_pulse();
long measure_pulse_width();
double calculate_distance(long pulse_width);
void log_distance(double distance);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        running = 0;
    }
}

// Initialize GPIO using pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    pigpio_initialized = 1;

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    return 0;
}

// Generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

// Measure the echo pulse width with timeout
long measure_pulse_width() {
    long start_time = 0, end_time = 0;
    int timeout = 0;

    // Wait for rising edge
    while (gpioRead(ECHO_PIN) == 0) {
        start_time = gpioTick();
        if (start_time == 0) {
            fprintf(stderr, "Error getting start time\n");
            return -1;
        }
        timeout++;
        if (timeout > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for rising edge\n");
            return -1;
        }
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    timeout = 0;
    // Wait for falling edge
    while (gpioRead(ECHO_PIN) == 1) {
        end_time = gpioTick();
        if (end_time == 0) {
            fprintf(stderr, "Error getting end time\n");
            return -1;
        }
        timeout++;
        if (timeout > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for falling edge\n");
            return -1;
        }
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    return end_time - start_time;
}

// Calculate distance in centimeters
double calculate_distance(long pulse_width) {
    return (pulse_width * 0.0343) / 2.0;
}

// Log distance to file with ISO 8601 timestamp
void log_distance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");

    if (pigpio_initialized) {
        gpioTerminate();
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    printf("Distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        trigger_pulse();
        long pulse_width = measure_pulse_width();

        if (pulse_width > 0) {
            double distance = calculate_distance(pulse_width);

            if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
                log_distance(distance);
                printf("Distance: %.2f cm\n", distance);
            } else {
                fprintf(stderr, "Distance out of range: %.2f cm\n", distance);
                log_distance(-1.0); // Log an error value
            }
        } else {
            fprintf(stderr, "Error measuring pulse width or timeout.\n");
            log_distance(-1.0); // Log an error value
        }

        gpioDelay(1000); // Wait 1 second
    }

    cleanup();
    return 0;
}

