    gpioDelay(10); // 10 microseconds
    gpioWrite(TRIG_PIN, 0);
}

// Function to calculate distance in meters
double calculate_distance(int pulse_width) {
    return (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // Convert pulse_width to seconds and divide by 2
}

// Function to log distance to a file
void log_distance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

