    }
}

// Interrupt service routine (ISR) for echo pin
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        pulse_start = tick;
        echo_received = 1; // Indicate that an echo has been received
    } else if (level == 0 && echo_received == 1) {
        pulse_end = tick;
        if (pulse_start > pulse_end) {
            // Handle tick wrap-around
            pulse_width = (0xFFFFFFFF - pulse_start) + pulse_end;
        } else {
            pulse_width = pulse_end - pulse_start;
        }
        echo_received = 0; // Reset the flag
    }
}

