        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set up interrupt service routine (ISR)
    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error setting up ISR!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        trigger_pulse();
        gpioDelay(1000); // Wait 1 second

        // Validate pulse width
        if (pulse_width > 0 && pulse_width < 25000) { // 58us to 25ms
            double distance = calculate_distance(pulse_width);
            log_distance(distance);
            printf("Distance: %.4f m\n", distance);
        } else {
            fprintf(stderr, "Invalid pulse width: %d\n", pulse_width);
        }
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL); // Disable ISR
    fclose(log_file);
    gpioTerminate();

    return 0;
}

