#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>
#include <string.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define XSHUT_GPIO 27
#define DISTANCE_REG 0x0014
#define STATUS_REG 0x0016
#define CONTINUOUS_MODE_REG 0x0018
#define TIMEOUT_REG 0x0019
#define START_RANGING_REG 0x0020

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_sensor();
int read_distance(uint16_t *distance);
int read_status(uint8_t *status);
void log_data(uint16_t distance, uint8_t status);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Received signal %d, terminating...", signal);
    terminate = 1;
}

// Initialize the VL53L1X sensor
int init_sensor() {
    // Set XSHUT_GPIO as output and high
    gpioSetMode(XSHUT_GPIO, PI_OUTPUT);
    gpioWrite(XSHUT_GPIO, 1);
    gpioDelay(100); // Wait for sensor to power up

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %d", i2c_handle);
        return -1;
    }

    // Configure sensor registers
    if (i2cWriteByteData(i2c_handle, CONTINUOUS_MODE_REG, 0x00) < 0) {
        syslog(LOG_ERR, "Failed to write to CONTINUOUS_MODE_REG");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, TIMEOUT_REG, 0x00) < 0) {
        syslog(LOG_ERR, "Failed to write to TIMEOUT_REG");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, START_RANGING_REG, 0x01) < 0) {
        syslog(LOG_ERR, "Failed to write to START_RANGING_REG");
        return -1;
    }

    syslog(LOG_INFO, "Sensor initialized successfully");
    return 0;
}

// Read distance from the sensor
int read_distance(uint16_t *distance) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, buf, 2) != 2) {
        syslog(LOG_ERR, "Failed to read distance data");
        return -1;
    }
    *distance = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

// Read status from the sensor
int read_status(uint8_t *status) {
    char buf[1];
    if (i2cReadI2CBlockData(i2c_handle, STATUS_REG, buf, 1) != 1) {
        syslog(LOG_ERR, "Failed to read status data");
        return -1;
    }
    *status = (uint8_t)buf[0];
    return 0;
}

// Log data to syslog
void log_data(uint16_t distance, uint8_t status) {
    char timestamp[30];
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tstruct);

    syslog(LOG_INFO, "%s, Distance: %d mm, Status: %d", timestamp, distance, status);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open syslog
    openlog("vl53l1x_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the sensor
    if (init_sensor() != 0) {
        syslog(LOG_ERR, "Sensor initialization failed, exiting");
        closelog();
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint16_t distance;
        uint8_t status;

        if (read_distance(&distance) == 0 && read_status(&status) == 0) {
            log_data(distance, status);
        } else {
            syslog(LOG_ERR, "Failed to read sensor data");
        }

        gpioDelay(100); // Wait 100ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();
    closelog();

    return 0;
}

