#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GATE_GPIO 24
#define DISTANCE_THRESHOLD 20 // cm
#define LOG_FILE "gate_log.txt"

// VL53L1X register addresses
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SYSRANGE_START 0x0015
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0083
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0089

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance(uint16_t *distance);
void control_gate(int distance);
void log_message(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    log_message("Received signal, shutting down...");
}

// Initialize VL53L1X sensor
int init_vl53l1x() {
    uint8_t model_id;

    // Read model ID
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, (char *)&model_id, 1) != 1) {
        log_message("Error reading model ID");
        return -1;
    }

    if (model_id != 0xEA) {
        log_message("Incorrect model ID");
        return -1;
    }

    // Set ranging mode to short
    if (i2cWriteByteData(i2c_handle, 0x0021, 0x00) != 0) {
        log_message("Error setting ranging mode");
        return -1;
    }

    // Start ranging
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSRANGE_START, 0x01) != 0) {
        log_message("Error starting ranging");
        return -1;
    }

    log_message("VL53L1X initialized successfully");
    return 0;
}

// Read distance from VL53L1X sensor
int read_distance(uint16_t *distance) {
    uint8_t range_status;
    uint8_t data[2];

    // Read range status
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS, (char *)&range_status, 1) != 1) {
        log_message("Error reading range status");
        return -1;
    }

    // Read distance data
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, (char *)data, 2) != 2) {
        log_message("Error reading distance data");
        return -1;
    }

    *distance = (data[0] << 8) | data[1];

    // Convert to cm
    *distance /= 10;

    return 0;
}

// Control gate actuator
void control_gate(int distance) {
    static int gate_open = 0; // Track gate state

    if (distance < DISTANCE_THRESHOLD && !gate_open) {
        gpioWrite(GATE_GPIO, 1); // Open gate
        gate_open = 1;
        log_message("Gate opened");
    } else if (distance >= DISTANCE_THRESHOLD && gate_open) {
        gpioWrite(GATE_GPIO, 0); // Close gate
        gate_open = 0;
        log_message("Gate closed");
    }
}

// Log messages to file
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write
}

int main() {
    uint16_t distance;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

