        gpioTerminate();
        return 1;
    }

    // Set GPIO24 as output
    gpioSetMode(GATE_GPIO, PI_OUTPUT);
    gpioWrite(GATE_GPIO, 0); // Initialize gate to closed state
    log_message("Gate initialized to closed state");

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
