#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0       // cm
#define MAX_DISTANCE 400.0     // cm
#define MIN_ANGLE 0.0          // degrees
#define MAX_ANGLE 180.0        // degrees
#define MIN_PULSE_WIDTH 500.0  // us
#define MAX_PULSE_WIDTH 2500.0 // us
#define TIMEOUT_US 30000        // 30 ms
#define MEASUREMENT_INTERVAL_MS 100 // 100 ms
#define MOVING_AVG_SIZE 5

// Global variables
volatile int pulse_width = 0;
volatile int timeout_flag = 0;
volatile int data_ready = 0;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Moving average filter
float distance_history[MOVING_AVG_SIZE];
int history_index = 0;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
float calculate_distance(int pulse_width);
float moving_average(float new_value);
float distance_to_angle(float distance);
int angle_to_pulse_width(float angle);
void set_servo_angle(float angle);
void log_data(float distance, float angle);
void signal_handler(int signal);

// Function to generate a 10 us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick) {
    static uint32_t start_tick = 0;

    if (level == 1) {
        start_tick = tick;
        timeout_flag = 0; // Reset timeout flag on rising edge
    } else if (level == 0) {
        uint32_t end_tick = tick;
        if (end_tick < start_tick) {
            // Handle tick counter wrap-around
            pulse_width = (0xFFFFFFFF - start_tick) + end_tick;
        } else {
            pulse_width = end_tick - start_tick;
        }
        data_ready = 1; // Set data ready flag
    } else if (level == PI_TIMEOUT) {
        timeout_flag = 1; // Set timeout flag
    }
}

// Function to calculate distance from pulse width
float calculate_distance(int pulse_width) {
    return (pulse_width * SPEED_OF_SOUND) / 2000000.0; // Convert us to s
}

// Function to apply moving average filter
float moving_average(float new_value) {
    distance_history[history_index] = new_value;
    history_index = (history_index + 1) % MOVING_AVG_SIZE;

    float sum = 0.0;
    for (int i = 0; i < MOVING_AVG_SIZE; i++) {
        sum += distance_history[i];
    }
    return sum / MOVING_AVG_SIZE;
}

// Function to map distance to angle using logarithmic mapping
float distance_to_angle(float distance) {
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        return -1.0; // Indicate invalid distance
    }

    // Logarithmic mapping
    float log_distance = log10(distance / MIN_DISTANCE);
    float log_range = log10(MAX_DISTANCE / MIN_DISTANCE);
    float normalized_distance = log_distance / log_range;

    // Map to angle range
    return normalized_distance * (MAX_ANGLE - MIN_ANGLE) + MIN_ANGLE;
}

// Function to map angle to pulse width
int angle_to_pulse_width(float angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        return -1; // Indicate invalid angle
    }

    // Map to pulse width range
    return (int)((angle / (MAX_ANGLE - MIN_ANGLE)) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) + MIN_PULSE_WIDTH);
}

// Function to set servo angle
void set_servo_angle(float angle) {
    int pulse_width_us = angle_to_pulse_width(angle);
    if (pulse_width_us != -1) {
        gpioServo(SERVO_PIN, pulse_width_us);
    } else {
        gpioServo(SERVO_PIN, angle_to_pulse_width(90.0)); // Set to default angle
    }
}

// Function to log data to CSV file
void log_data(float distance, float angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, distance, angle);
    fflush(log_file); // Flush the buffer to ensure data is written immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set PWM frequency for servo (optional, but recommended)
    gpioSetPWMfrequency(SERVO_PIN, 50); // 50 Hz

    // Register alert callback for echo pin
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to register alert callback\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Distance (cm),Angle (degrees)\n");
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Trigger ultrasonic sensor
        trigger_pulse();
        data_ready = 0; // Reset data ready flag
        timeout_flag = 0; // Reset timeout flag

        // Wait for data or timeout
        int timeout_count = 0;
        while (!data_ready && !timeout_flag && timeout_count < 100) {
            gpioDelay(1); // Wait 1 ms
            timeout_count++;
        }

        float distance = -1.0;
        float angle = -1.0;

        if (timeout_flag) {
            // Timeout occurred
            distance = -1.0;
            angle = -1.0;
            set_servo_angle(90.0); // Set servo to default position
        } else {
            // Calculate distance
            distance = calculate_distance(pulse_width);

            // Apply moving average filter
            distance = moving_average(distance);

            // Map distance to angle
            angle = distance_to_angle(distance);

            // Set servo angle
            set_servo_angle(angle);
        }

        // Log data
        log_data(distance, angle);

        // Wait before next measurement
        gpioDelay(MEASUREMENT_INTERVAL_MS);
    }

    // Cleanup
    set_servo_angle(90.0); // Set servo to default position before exiting
    fclose(log_file);
    gpioTerminate();

    return 0;
}

