#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_LED 17
#define BUFFER_SIZE 10
#define DISTANCE_THRESHOLD 200 // mm

// VL53L1X register addresses (Example - adjust based on datasheet)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L1X_REG_SYSRANGE_START 0x0040
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Global variables
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Circular buffer structure
typedef struct {
    int buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int init_vl53l1x();
int read_distance();
void add_to_buffer(CircularBuffer *cb, int value);
int get_average_distance(CircularBuffer *cb);
void control_led(int state);
void signal_handler(int signal);
void init_circular_buffer(CircularBuffer *cb);

// Initialize circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Add value to circular buffer
void add_to_buffer(CircularBuffer *cb, int value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Get average distance from circular buffer
int get_average_distance(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0; // Or some other default value
    }
    int sum = 0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Initialize VL53L1X sensor
int init_vl53l1x() {
    // Example initialization sequence (adjust based on datasheet)
    if (i2cWriteByteData(i2c_handle, 0x00, 0x01) < 0) return -1; // Example register write
    if (i2cWriteByteData(i2c_handle, 0x01, 0x02) < 0) return -1; // Example register write
    if (i2cWriteByteData(i2c_handle, 0x02, 0x03) < 0) return -1; // Example register write

    // Enable signal rate check (example)
    if (i2cWriteByteData(i2c_handle, 0x08, 0x01) < 0) return -1;

    // Configure cross-talk compensation (example)
    if (i2cWriteByteData(i2c_handle, 0x09, 0x10) < 0) return -1;

    // Start ranging
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSRANGE_START, 0x01) < 0) return -1;

    return 0;
}

// Read distance from VL53L1X sensor
int read_distance() {
    int distance = -1; // Default to error value
    int retries = 3;

    while (retries > 0) {
        distance = i2cReadWordData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
        if (distance >= 0) {
            break; // Success, exit retry loop
        } else {
            fprintf(stderr, "I2C read error, retrying...\n");
            gpioDelay(10); // Small delay before retry
            retries--;
        }
    }

