#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <getopt.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1102_ADDR 0x60
#define PROX_REG_HIGH 0x08
#define PROX_REG_LOW 0x09
#define GPIO_PIN 27
#define DEFAULT_THRESHOLD 1000
#define DEFAULT_I2C_ADDRESS SI1102_ADDR
#define DEFAULT_SERVER_IP "127.0.0.1"
#define DEFAULT_SERVER_PORT 12345

// Global variables
static int i2c_handle;
static int threshold = DEFAULT_THRESHOLD;
static int i2c_address = DEFAULT_I2C_ADDRESS;
static char *server_ip = DEFAULT_SERVER_IP;
static int server_port = DEFAULT_SERVER_PORT;
static FILE *log_file;
static volatile int running = 1;
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

// Structure for passing data to the interrupt handler thread
typedef struct {
    int prox_value;
} interrupt_data_t;

// Function prototypes
int init_i2c(int address);
int read_proximity(int handle);
int configure_gpio(int pin);
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data);
void *log_thread(void *arg);
void signal_handler(int signal);
int send_udp_message(const char *message, const char *ip_address, int port);
void log_message(const char *message);

// Function to initialize I2C
int init_i2c(int address) {
    i2c_handle = i2cOpen(I2C_BUS, address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read proximity value from the sensor
int read_proximity(int handle) {
    int prox_value = i2cReadWordData(handle, PROX_REG_HIGH);
    if (prox_value < 0) {
        fprintf(stderr, "Error reading proximity data: %d\n", prox_value);
        return -1;
    }
    return prox_value;
}

// Function to configure GPIO pin for interrupt
int configure_gpio(int pin) {
    if (gpioSetMode(pin, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        return -1;
    }
    if (gpioSetPullUpDown(pin, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error setting GPIO pull-up/down\n");
        return -1;
    }
    return 0;
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio; (void)level; (void)tick; // unused parameters
    int prox_value = read_proximity(i2c_handle);
    if (prox_value >= 0) {
        interrupt_data_t data;
        data.prox_value = prox_value;
        pthread_t log_thread_id;
        if (pthread_create(&log_thread_id, NULL, log_thread, &data) != 0) {
            fprintf(stderr, "Error creating log thread\n");
        }
        pthread_detach(log_thread_id); // Detach the thread to automatically release resources
    }
}

// Logging thread function
void *log_thread(void *arg) {
    interrupt_data_t *data = (interrupt_data_t *)arg;
    char message[256];
    snprintf(message, sizeof(message), "%s,%d,%s\n", __TIME__, data->prox_value, (data->prox_value > threshold) ? "ALERT" : "SAFE");
    log_message(message);
    return NULL;
}

// Function to log messages to file
void log_message(const char *message) {
    pthread_mutex_lock(&log_mutex);
    if (log_file != NULL) {
        fprintf(log_file, "%s", message);
        fflush(log_file); // Ensure immediate write to file
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
    pthread_mutex_unlock(&log_mutex);
}

// Function to send UDP message
int send_udp_message(const char *message, const char *ip_address, int port) {
    int sockfd;
    struct sockaddr_in servaddr;

    // Creating socket file descriptor
    if ((sockfd = socket(AF_INET, SOCK_DGRAM, 0)) < 0) {
        perror("socket creation failed");
        return -1;
    }

    memset(&servaddr, 0, sizeof(servaddr));

    // Filling server information
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(port);
    if (inet_pton(AF_INET, ip_address, &servaddr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(sockfd);
        return -1;
    }

    if (sendto(sockfd, (const char *)message, strlen(message), 0, (const struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        perror("sendto failed");
        close(sockfd);
        return -1;
    }

    close(sockfd);
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        running = 0;
    }
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:t:i:p:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 0);
                break;
            case 't':
                threshold = atoi(optarg);
                break;
            case 'i':
                server_ip = optarg;
                break;
            case 'p':
                server_port = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold] [-i server_ip] [-p server_port]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c(i2c_address) != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure GPIO
    if (configure_gpio(GPIO_PIN) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("proximity.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Set up interrupt handler
    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting up interrupt handler\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        sleep(1); // Reduce CPU usage
    }

    // Clean up
    gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, NULL, NULL); // Disable interrupt
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Exiting cleanly.\n");
    return 0;
}

