#define MAX_FREQ 2000.0   // Hz
#define TIMEOUT_US 100000  // 100 ms
#define TRIGGER_PULSE_US 10 // 10 us

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
void signal_handler(int signal);
float get_distance();
float map_distance_to_frequency(float distance);
void set_buzzer_frequency(float frequency);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0;
        gpioPWM(BUZZER_PIN, 0); // Stop PWM
        gpioTerminate();       // Terminate pigpio
        exit(0);
    }
}

// Function to measure distance using HC-SR04
float get_distance() {
    gpioWrite(TRIGGER_PIN, 0); // Ensure trigger is low
    gpioDelay(2);              // Wait 2 us

    gpioWrite(TRIGGER_PIN, 1); // Send 10 us trigger pulse
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);

    uint32_t start_tick = 0;
    uint32_t end_tick = 0;

    // Wait for echo to go high (with timeout)
    int timeout_count = 0;
    while (gpioRead(ECHO_PIN) == 0 && timeout_count < TIMEOUT_US) {
        timeout_count++;
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    if (timeout_count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo pulse timeout (start)\n");
        return -1.0; // Indicate error
    }

    start_tick = gpioTick();

    // Wait for echo to go low (with timeout)
    timeout_count = 0;
    while (gpioRead(ECHO_PIN) == 1 && timeout_count < TIMEOUT_US) {
        timeout_count++;
        gpioDelay(1);
    }

    if (timeout_count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo pulse timeout (end)\n");
        return -1.0; // Indicate error
    }

    end_tick = gpioTick();

    uint32_t pulse_width = end_tick - start_tick;

    // Calculate distance in centimeters (speed of sound: 343 m/s)
    // distance = (pulse_width * 0.000001) * 34300 / 2
    float distance = (float)pulse_width / 29.0 / 2.0; // Simplified calculation

    return distance;
}

