float map_distance_to_frequency(float distance) {
    float frequency = MIN_FREQ + (MAX_FREQ - MIN_FREQ) * (MAX_DISTANCE - distance) / (MAX_DISTANCE - MIN_DISTANCE);
    if (frequency < MIN_FREQ) {
        frequency = MIN_FREQ;
    } else if (frequency > MAX_FREQ) {
        frequency = MAX_FREQ;
    }
    return frequency;
}

// Function to set the buzzer frequency using hardware PWM
void set_buzzer_frequency(float frequency) {
    int range = 1000000 / frequency; // Calculate PWM range
    if (range <= 0) {
        range = 1; // Ensure a valid range
    }
    gpioHardwarePWM(BUZZER_PIN, (int)frequency, 500); // 50% duty cycle
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set pull-down resistor on ECHO_PIN
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float last_valid_distance = 0.0;
    float distance, frequency;

    printf("Theremin-like instrument running. Press Ctrl+C to exit.\n");

    while (program_running) {
        distance = get_distance();

        if (distance > 0) {
            last_valid_distance = distance;
            frequency = map_distance_to_frequency(distance);
            set_buzzer_frequency(frequency);
            printf("Distance: %.2f cm, Frequency: %.2f Hz\n", distance, frequency);
        } else {
            fprintf(stderr, "Error: Invalid distance reading. Using last valid distance: %.2f cm\n", last_valid_distance);
            frequency = map_distance_to_frequency(last_valid_distance);
            set_buzzer_frequency(frequency);
        }

        gpioDelay(10000); // 10 ms delay
    }

    return 0;
}

