#define MIN_DISTANCE 2.0   // cm
#define MAX_DISTANCE 400.0 // cm
#define TIMEOUT_US 50000    // 50 ms
#define TRIGGER_PULSE_US 10  // 10 us trigger pulse

// Global flag for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to measure the echo pulse width
int measure_pulse_width(int echo_pin) {
    int start_tick, end_tick, pulse_width;

    // Wait for the echo pin to go high (rising edge)
    int timeout_count = 0;
    while (gpioRead(echo_pin) == 0 && timeout_count < TIMEOUT_US) {
        gpioDelay(1); // Small delay to avoid busy-waiting
        timeout_count++;
    }

    if (timeout_count >= TIMEOUT_US) {
        return -1; // Timeout occurred
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go low (falling edge)
    timeout_count = 0;
    while (gpioRead(echo_pin) == 1 && timeout_count < TIMEOUT_US) {
        gpioDelay(1);
        timeout_count++;
    }

    if (timeout_count >= TIMEOUT_US) {
        return -1; // Timeout occurred
    }

    end_tick = gpioTick();

    pulse_width = end_tick - start_tick;
    if (pulse_width < 0) {
        pulse_width += 0xFFFFFFFF; // Handle tick rollover
    }

    return pulse_width;
}

// Function to calculate the distance in centimeters
float calculate_distance(int pulse_width) {
    return (float)pulse_width / 2.0 / SPEED_OF_SOUND;
}

// Function to validate the distance
int validate_distance(float distance) {
    return (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) ? 1 : 0;
}

// Function to print the distance and handle the "Too close!" message
void print_distance(float distance) {
    printf("Distance: %.2f cm\n", distance);
    if (distance < 10.0) {
        printf("Too close!\n");
    }
}

