    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Send trigger pulse
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(TRIGGER_PULSE_US);
        gpioWrite(TRIGGER_PIN, 0);

        // Measure echo pulse width
        int pulse_width = measure_pulse_width(ECHO_PIN);

        // Check for timeout
        if (pulse_width == -1) {
            fprintf(stderr, "Timeout occurred\n");
        } else {
            // Calculate distance
            float distance = calculate_distance(pulse_width);

            // Validate distance
            if (validate_distance(distance)) {
                // Print distance
                print_distance(distance);
            } else {
                printf("Invalid reading\n");
            }
        }

        // Wait 500 ms
        gpioDelay(500000);
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

