// Constants
#define I2C_BUS "/dev/i2c-1"
#define SI1175_ADDR 0x60
#define ALS_VISIBLE_LOW 0x22
#define ALS_VISIBLE_HIGH 0x23
#define CSV_FILENAME "proximity_log.csv"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
uint16_t read_als_visible(int fd);
char* get_iso8601_timestamp();
int log_data(const char *timestamp, uint16_t als_visible);
void signal_handler(int sig);
int setup();
void cleanup();

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", sig);
}

// I2C read register function
int i2c_read_reg(int fd, uint8_t reg) {
    uint8_t buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, buf, 1) != 1) {
        perror("Failed to read register value");
        return -1;
    }
    return buf[0];
}

// I2C write register function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write register");
        return -1;
    }
    return 0;
}

// Read ALS Visible value
uint16_t read_als_visible(int fd) {
    int low = i2c_read_reg(fd, ALS_VISIBLE_LOW);
    int high = i2c_read_reg(fd, ALS_VISIBLE_HIGH);

    if (low == -1 || high == -1) {
        return 0; // Indicate error with 0
    }

    return (uint16_t)((high << 8) | low);
}

// Get ISO-8601 timestamp
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp
    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

