#include <string.h>
#include <unistd.h>

// Si1120 I2C address
#define SI1120_ADDR 0x60

// Si1120 register addresses
#define SI1120_REG_PART_ID 0x00
#define SI1120_REG_ALS_DATA0 0x22
#define SI1120_REG_ALS_DATA1 0x23
#define SI1120_REG_PS1_DATA0 0x18
#define SI1120_REG_PS1_DATA1 0x19
#define SI1120_REG_RESET 0x30

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int si1120_init();
int si1120_read_als();
int si1120_read_proximity();
void log_data(int als, int proximity);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize the Si1120 sensor
int si1120_init() {
    int retries = 3;
    int result;

    // Reset the sensor
    while (retries > 0) {
        result = i2cWriteByteData(i2c_handle, SI1120_REG_RESET, 0x01);
        if (result == 0) break; // Success
        fprintf(stderr, "Error resetting Si1120, retrying...\n");
        gpioDelay(10); // 10 ms delay
        retries--;
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to reset Si1120 after multiple retries.\n");
        return -1;
    }

    gpioDelay(10); // Wait for reset to complete

    // Verify Part ID
    retries = 3;
    while (retries > 0) {
        int part_id = i2cReadByteData(i2c_handle, SI1120_REG_PART_ID);
        if (part_id >= 0 && part_id == 0x41) {
            fprintf(stderr, "Si1120 Part ID: 0x%02X (OK)\n", part_id);
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading Part ID, retrying...\n");
            retries--;
            gpioDelay(10);
        }
    }
    fprintf(stderr, "Failed to read correct Part ID from Si1120 after multiple retries.\n");
    return -1; // Failure
}

// Function to read ALS data from the Si1120 sensor
int si1120_read_als() {
    int retries = 3;
    int result;
    int als_low, als_high;

    while (retries > 0) {
        als_low = i2cReadByteData(i2c_handle, SI1120_REG_ALS_DATA0);
        als_high = i2cReadByteData(i2c_handle, SI1120_REG_ALS_DATA1);

        if (als_low >= 0 && als_high >= 0) {
            int als = (als_high << 8) | als_low;
            return als;
        } else {
            fprintf(stderr, "Error reading ALS data, retrying...\n");
            retries--;
            gpioDelay(10);
        }
    }
    fprintf(stderr, "Failed to read ALS data after multiple retries.\n");
    return -1; // Failure
}

// Function to read proximity data from the Si1120 sensor
int si1120_read_proximity() {
    int retries = 3;
    int result;
    int prox_low, prox_high;

    while (retries > 0) {
        prox_low = i2cReadByteData(i2c_handle, SI1120_REG_PS1_DATA0);
        prox_high = i2cReadByteData(i2c_handle, SI1120_REG_PS1_DATA1);

        if (prox_low >= 0 && prox_high >= 0) {
            int proximity = (prox_high << 8) | prox_low;
            return proximity;
        } else {
            fprintf(stderr, "Error reading proximity data, retrying...\n");
            retries--;
            gpioDelay(10);
        }
    }
    fprintf(stderr, "Failed to read proximity data after multiple retries.\n");
    return -1; // Failure
}

// Function to log the ALS and proximity data to a file
void log_data(int als, int proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, ALS: %d, Proximity: %d\n", timestamp, als, proximity);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SI1120_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the Si1120 sensor
    if (si1120_init() != 0) {
        fprintf(stderr, "Si1120 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen("si1120_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int als = si1120_read_als();
        int proximity = si1120_read_proximity();

        if (als >= 0 && proximity >= 0) {
