#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_ADDR 0x60
#define I2C_BUS 1
#define LOG_FILE "proximity_log.txt"

// Si1145 Registers
#define REG_HW_KEY 0x07
#define REG_MEAS_RATE 0x06
#define REG_INT_CFG 0x1A
#define REG_ALS_VIS_IR_ADC_COUNTER 0x21
#define REG_ALS_VIS_ADC_GAIN 0x24
#define REG_PS_ADC_COUNTER 0x22
#define REG_PS_LED21 0x0C
#define REG_PS_LED3 0x0F
#define REG_PS_ADC_MISC 0x11
#define REG_PS_ADC_GAIN 0x0D
#define REG_COMMAND 0x80

// Commands
#define CMD_PS_FORCE 0x03

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_proximity(uint16_t *proximity_value);
void log_data(uint16_t proximity_value);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Function to initialize the Si1145 sensor
int initialize_sensor() {
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cWriteByteData(i2c_handle, REG_HW_KEY, 0x03);
        if (result != 0) {
            fprintf(stderr, "Error writing to REG_HW_KEY: %d\n", result);
            log_data(0); // Log error
            retries--;
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

        result = i2cWriteByteData(i2c_handle, REG_MEAS_RATE, 0x02);
        if (result != 0) {
            fprintf(stderr, "Error writing to REG_MEAS_RATE: %d\n", result);
            log_data(0); // Log error
            retries--;
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

        result = i2cWriteByteData(i2c_handle, REG_INT_CFG, 0x00);
        if (result != 0) {
            fprintf(stderr, "Error writing to REG_INT_CFG: %d\n", result);
            log_data(0); // Log error
            retries--;
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

        result = i2cWriteByteData(i2c_handle, REG_ALS_VIS_IR_ADC_COUNTER, 0x0B);
        if (result != 0) {
            fprintf(stderr, "Error writing to REG_ALS_VIS_IR_ADC_COUNTER: %d\n", result);
            log_data(0); // Log error
            retries--;
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

        result = i2cWriteByteData(i2c_handle, REG_ALS_VIS_ADC_GAIN, 0x00);
        if (result != 0) {
            fprintf(stderr, "Error writing to REG_ALS_VIS_ADC_GAIN: %d\n", result);
            log_data(0); // Log error
            retries--;
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

        result = i2cWriteByteData(i2c_handle, REG_PS_ADC_COUNTER, 0x49);
        if (result != 0) {
            fprintf(stderr, "Error writing to REG_PS_ADC_COUNTER: %d\n", result);
            log_data(0); // Log error
            retries--;
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

        result = i2cWriteByteData(i2c_handle, REG_PS_LED21, 0x03);
        if (result != 0) {
            fprintf(stderr, "Error writing to REG_PS_LED21: %d\n", result);
            log_data(0); // Log error
            retries--;
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

        result = i2cWriteByteData(i2c_handle, REG_PS_LED3, 0x0F);
        if (result != 0) {
            fprintf(stderr, "Error writing to REG_PS_LED3: %d\n", result);
            log_data(0); // Log error
            retries--;
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

        result = i2cWriteByteData(i2c_handle, REG_PS_ADC_MISC, 0x03);
        if (result != 0) {
            fprintf(stderr, "Error writing to REG_PS_ADC_MISC: %d\n", result);
            log_data(0); // Log error
            retries--;
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

        result = i2cWriteByteData(i2c_handle, REG_PS_ADC_GAIN, 0x07);
        if (result != 0) {
            fprintf(stderr, "Error writing to REG_PS_ADC_GAIN: %d\n", result);
            log_data(0); // Log error
            retries--;
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

        result = i2cWriteByteData(i2c_handle, REG_COMMAND, CMD_PS_FORCE);
        if (result != 0) {
            fprintf(stderr, "Error writing to REG_COMMAND: %d\n", result);
            log_data(0); // Log error
            retries--;
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

        printf("Sensor initialized successfully.\n");
        return 0; // Success
    }

    fprintf(stderr, "Failed to initialize sensor after multiple retries.\n");
    return -1; // Failure
}

// Function to read proximity data from the Si1145 sensor
int read_proximity(uint16_t *proximity_value) {
    int retries = 3;
    int result;
    uint8_t low_byte, high_byte;

    while (retries > 0) {
        result = i2cReadByteData(i2c_handle, 0x16); // PS1_DATA0
        if (result < 0) {
            fprintf(stderr, "Error reading PS1_DATA0: %d\n", result);
            log_data(0); // Log error
            retries--;
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }
        low_byte = (uint8_t)result;

        result = i2cReadByteData(i2c_handle, 0x17); // PS1_DATA1
        if (result < 0) {
