#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define BUZZER_PIN 27

// Define distance threshold (cm)
#define DISTANCE_THRESHOLD 20.0

// Define speed of sound (cm/us)
#define SPEED_OF_SOUND 0.0343

// Global variables
volatile uint32_t rising_edge_tick = 0;
volatile uint32_t falling_edge_tick = 0;
volatile int echo_received = 0; // Flag to indicate echo received

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

// Function to generate a 10 us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us delay
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin interrupt
void echo_callback(int gpio, int level, uint32_t tick) {
    if (gpio == ECHO_PIN) {
        if (level == 1) { // Rising edge
            rising_edge_tick = tick;
            echo_received = 1; // Set the flag
        } else if (level == 0 && echo_received == 1) { // Falling edge
            falling_edge_tick = tick;
            echo_received = 0; // Reset the flag
        }
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set TRIGGER_PIN as output\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set ECHO_PIN as input\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set BUZZER_PIN as output\n");
        gpioTerminate();
        return 1;
    }

    // Set alert function for echo pin
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for ECHO_PIN\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Generate trigger pulse
        trigger_pulse();

        // Wait for echo pulse to be received (with timeout)
        int timeout_counter = 0;
        while (echo_received == 0 && timeout_counter < 1000) {
            gpioDelay(1); // Small delay to avoid busy-waiting
            timeout_counter++;
        }

        if (echo_received == 0) {
            fprintf(stderr, "Timeout waiting for echo pulse\n");
            gpioWrite(BUZZER_PIN, 0); // Ensure buzzer is off on timeout
            continue; // Skip distance calculation and buzzer control
        }

        // Calculate pulse width
        uint32_t pulse_width = falling_edge_tick - rising_edge_tick;

        // Calculate distance in centimeters
        float distance = (pulse_width * SPEED_OF_SOUND) / 2.0;

        // Print distance to stdout
        printf("Distance: %.2f cm\n", distance);

        // Control buzzer based on distance
        if (distance < DISTANCE_THRESHOLD) {
            gpioWrite(BUZZER_PIN, 1); // Activate buzzer
        } else {
            gpioWrite(BUZZER_PIN, 0); // Deactivate buzzer
        }

        // Wait for 1 second
        gpioDelay(1000);
    }

    // This point should not be reached due to the infinite loop
    gpioTerminate();
    return 0;
}

