#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

// Constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 50000        // 50ms timeout for echo

// Global variable for program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    printf("\nCaught signal, exiting gracefully...\n");
}

// Function to measure distance using HC-SR04
float getDistance() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    uint32_t start_tick = 0;
    uint32_t end_tick = 0;

    // Wait for echo to start (with timeout)
    int timeout_count = 0;
    while (gpioRead(ECHO_PIN) == 0 && timeout_count < TIMEOUT_US) {
        timeout_count++;
        gpioDelay(1); // Check every 1 us
    }

    if (timeout_count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo start timeout\n");
        return -1.0; // Indicate timeout error
    }

    start_tick = gpioTick();

    // Wait for echo to end (with timeout)
    timeout_count = 0;
    while (gpioRead(ECHO_PIN) == 1 && timeout_count < TIMEOUT_US) {
        timeout_count++;
        gpioDelay(1); // Check every 1 us
    }

    if (timeout_count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo end timeout\n");
        return -1.0; // Indicate timeout error
    }

    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;

    // Calculate distance in centimeters
    float distance = (float)diff * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance, convert us to s

    return distance;
}

// Function to set servo angle
void setServoAngle(int angle) {
    // Map angle (0-180) to pulse width (500-2500 us)
    int pulse_width = 500 + (int)((float)angle / 180.0 * 2000.0);
    gpioServo(SERVO_PIN, pulse_width);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Parking assist system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        float distance = getDistance();

        if (distance < 0) {
            fprintf(stderr, "Error: Distance measurement failed\n");
        } else {
            printf("Distance: %.2f cm\n", distance);

            // Calculate servo angle based on distance
            int angle;
            if (distance > 200) {
                angle = 0;
            } else if (distance < 20) {
                angle = 180;
            } else {
                angle = (int)((200.0 - distance) / (200.0 - 20.0) * 180.0);
            }

            setServoAngle(angle);
        }

        gpioDelay(100); // Delay 100ms
    }

    // Cleanup
    setServoAngle(90); // Set servo to a safe position before exiting
    gpioTerminate();

    return 0;
}

