#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

// Constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0       // cm
#define MAX_DISTANCE 400.0     // cm
#define MIN_ANGLE 0.0          // degrees
#define MAX_ANGLE 180.0        // degrees
#define TIMEOUT_US 50000        // 50ms timeout

// Global variable for program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    printf("\nCtrl+C pressed. Stopping servo and exiting.\n");
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse width with timeout
long measurePulseWidth() {
    long start_tick, end_tick, pulse_width;

    // Wait for the echo pin to go high with timeout
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every microsecond
    }

    if (count >= TIMEOUT_US) {
        return -1; // Timeout
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go low with timeout
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every microsecond
    }

    if (count >= TIMEOUT_US) {
        return -1; // Timeout
    }

    end_tick = gpioTick();

    pulse_width = end_tick - start_tick;
    if (pulse_width < 0) {
        pulse_width += 0xFFFFFFFF; // Handle tick rollover
    }

    return pulse_width;
}

// Function to calculate distance in centimeters
float calculateDistance(long pulse_width) {
    if (pulse_width < 0) {
        return -1.0; // Indicate error
    }
    return (float)pulse_width * 0.0343 / 2.0;
}

// Function to map distance to angle
float mapDistanceToAngle(float distance) {
    if (distance < MIN_DISTANCE) {
        return MIN_ANGLE;
    } else if (distance > MAX_DISTANCE) {
        return MAX_ANGLE;
    } else {
        return (distance - MIN_DISTANCE) * (MAX_ANGLE - MIN_ANGLE) / (MAX_DISTANCE - MIN_DISTANCE);
    }
}

// Function to set the servo angle
void setServoAngle(float angle) {
    // Convert angle to pulse width (500us - 2500us)
    int pulse_width = (int)(500 + (angle / MAX_ANGLE) * 2000);
    gpioServo(SERVO_PIN, pulse_width);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Parking Assist System running. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Trigger the sensor
        triggerSensor();

        // Measure the echo pulse width
        long pulse_width = measurePulseWidth();

        // Calculate the distance
        float distance = calculateDistance(pulse_width);

        // Map distance to angle
        float angle = mapDistanceToAngle(distance);

        // Set the servo angle
        setServoAngle(angle);

        // Print the distance and angle
        printf("Distance: %.2f cm, Angle: %.2f degrees\n", distance, angle);

        // Delay for 100ms
        gpioDelay(100000);
    }

    // Stop the servo
    gpioServo(SERVO_PIN, 0);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

