#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI7005_ADDR 0x40
#define CONFIG_REG 0x03
#define TEMP_REG 0x01
#define HUMID_REG 0x02

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int open_i2c_bus();
int write_i2c(int handle, int reg, int data);
int read_i2c(int handle, int reg, int *data);
float convert_temperature(unsigned int raw_temp);
float convert_humidity(unsigned int raw_humidity);
void log_data(float temperature, float humidity);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus() {
    int handle = i2cOpen(I2C_BUS, SI7005_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", handle);
        return -1;
    }
    return handle;
}

// Write to I2C device
int write_i2c(int handle, int reg, int data) {
    int result = i2cWriteByteData(handle, reg, data);
    if (result < 0) {
        fprintf(stderr, "I2C write failed: %d\n", result);
        return -1;
    }
    return 0;
}

// Read from I2C device
int read_i2c(int handle, int reg, int *data) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        return -1;
    }
    *data = result;
    return 0;
}

// Convert raw temperature to Celsius
float convert_temperature(unsigned int raw_temp) {
    return (175.72 * raw_temp) / 65536.0 - 46.85;
}

// Convert raw humidity to percentage
float convert_humidity(unsigned int raw_humidity) {
    return (125.0 * raw_humidity) / 65536.0 - 6.0;
}

// Log temperature and humidity data
void log_data(float temperature, float humidity) {
    printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
}

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    i2c_handle = open_i2c_bus();
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Write to CONFIG register
        if (write_i2c(i2c_handle, CONFIG_REG, 0x00) != 0) {
            i2cClose(i2c_handle);
            i2c_handle = open_i2c_bus();
            if (i2c_handle < 0) {
                gpioTerminate();
                return 1;
            }
            continue; // Retry the loop
        }
        gpioDelay(10); // Wait 10 ms

        // Read temperature register
        int raw_temp;
        if (read_i2c(i2c_handle, TEMP_REG, &raw_temp) != 0) {
            i2cClose(i2c_handle);
            i2c_handle = open_i2c_bus();
            if (i2c_handle < 0) {
                gpioTerminate();
                return 1;
            }
            continue; // Retry the loop
        }

        // Read humidity register
        int raw_humidity;
        if (read_i2c(i2c_handle, HUMID_REG, &raw_humidity) != 0) {
            i2cClose(i2c_handle);
            i2c_handle = open_i2c_bus();
            if (i2c_handle < 0) {
                gpioTerminate();
                return 1;
            }
            continue; // Retry the loop
        }

        // Convert raw data to temperature and humidity
        float temperature = convert_temperature((unsigned int)raw_temp);
        float humidity = convert_humidity((unsigned int)raw_humidity);

        // Log the data
        log_data(temperature, humidity);

        // Wait 2 seconds
        sleep(2);
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

