        fprintf(stderr, "Error resetting device\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset

    // Clear sleep mode bit
    if (write_register(handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error clearing sleep mode\n");
        return -1;
    }

    // Set sample rate divider
    if (write_register(handle, SMPLRT_DIV, 7) < 0) {
        fprintf(stderr, "Error setting sample rate divider\n");
        return -1;
    }

    // Configure accelerometer range
    if (write_register(handle, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error configuring accelerometer range\n");
        return -1;
    }

    // Configure gyroscope range
    if (write_register(handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error configuring gyroscope range\n");
        return -1;
    }

    return 0;
}

// Function to read accelerometer and gyroscope data
int read_mpu6050_data(int handle, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z)
{
    char buffer[14];
    int result = i2cReadI2CBlockData(handle, ACCEL_XOUT_H, buffer, 14);
    if (result < 0) {
        fprintf(stderr, "Error reading data block: %d\n", result);
        return -1;
    }

    *accel_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *accel_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *accel_z = (int16_t)((buffer[4] << 8) | buffer[5]);
    *gyro_x  = (int16_t)((buffer[8] << 8) | buffer[9]);
    *gyro_y  = (int16_t)((buffer[10] << 8) | buffer[11]);
    *gyro_z  = (int16_t)((buffer[12] << 8) | buffer[13]);

    return 0;
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050(i2c_handle) < 0) {
        fprintf(stderr, "MPU-6050 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("MPU-6050 data logger started. Press Ctrl+C to exit.\n");

    // Main loop
    int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
    while (!terminate) {
        if (read_mpu6050_data(i2c_handle, &accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) == 0) {
            printf("Accel: X=%6d, Y=%6d, Z=%6d  Gyro: X=%6d, Y=%6d, Z=%6d\n",
                   accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }
        gpioDelay(100); // 100 ms delay
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("MPU-6050 data logger stopped.\n");

    return 0;
}

