#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

// SHT40 I2C address
#define SHT40_ADDR 0x44

// SHT40 commands
#define SHT40_MEASURE_HIGH 0xFD

// CRC-8 polynomial
#define CRC8_POLYNOMIAL 0x31

// Global variables for I2C handle and pigpio initialization status
int i2c_handle = -1;
int pigpio_initialized = 0;

// Function prototypes
int sht40_read_data(int i2c_handle, float *temperature, float *humidity);
uint8_t crc8(const uint8_t *data, size_t len);
void signal_handler(int signal);

// CRC-8 checksum calculation function
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read temperature and humidity from SHT40
int sht40_read_data(int i2c_handle, float *temperature, float *humidity) {
    uint8_t data[6];
    uint16_t raw_temperature, raw_humidity;
    uint8_t crc_temperature, crc_humidity;

    // Send measurement command
    if (i2cWriteByteData(i2c_handle, 0, SHT40_MEASURE_HIGH) != 0) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Wait for measurement to complete (at least 10 ms)
    gpioDelay(10000); // 10 ms

    // Read 6 bytes of data
    if (i2cReadI2CBlockData(i2c_handle, 0, (char *)data, 6) != 6) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Extract raw temperature and humidity values
    raw_temperature = (data[0] << 8) | data[1];
    raw_humidity = (data[3] << 8) | data[4];

    // Extract CRC values
    crc_temperature = data[2];
    crc_humidity = data[5];

    // CRC validation
    uint8_t calculated_crc_temperature = crc8(data, 2);
    uint8_t calculated_crc_humidity = crc8(data + 3, 2);

    if (crc_temperature != calculated_crc_temperature) {
        fprintf(stderr, "Temperature CRC check failed!\n");
        return -1;
    }

    if (crc_humidity != calculated_crc_humidity) {
        fprintf(stderr, "Humidity CRC check failed!\n");
        return -1;
    }

    // Convert raw values to temperature and humidity
    *temperature = -45.0 + 175.0 * (float)raw_temperature / 65535.0;
    *humidity = -6.0 + 125.0 * (float)raw_humidity / 65535.0;

    // Clamp humidity to 0-100%
    if (*humidity < 0.0) *humidity = 0.0;
    if (*humidity > 100.0) *humidity = 100.0;

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, shutting down...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (pigpio_initialized) {
        gpioTerminate();
    }
    exit(0);
}

int main() {
    float temperature, humidity;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    pigpio_initialized = 1;

    // Open I2C bus
    i2c_handle = i2cOpen(1, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        if (sht40_read_data(i2c_handle, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f °C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data. Re-opening I2C bus...\n");
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(1, SHT40_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C device: %s\n", strerror(errno));
                gpioTerminate();
                return 1;
            }
        }

        gpioDelay(5000000); // 5 seconds
    }

    return 0;
}

