#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define MLX90614_ADDR 0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define TEMP_SCALE 0.02
#define TEMP_OFFSET -273.15
#define LOG_FILE "temperature_log.csv"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
double read_temperature(int reg);
void log_temperature(double ambient_temp, double object_temp);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data (optional)
typedef struct {
    double ambient_temp;
    double object_temp;
} sensor_data_t;

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read temperatures
        double ambient_temp = read_temperature(AMBIENT_TEMP_REG);
        double object_temp = read_temperature(OBJECT_TEMP_REG);

        // Log temperatures
        log_temperature(ambient_temp, object_temp);

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_fd = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_fd);
        return 1;
    }
    return 0;
}

// Read temperature from sensor
double read_temperature(int reg) {
    int raw_data = i2cReadWordData(i2c_fd, reg);
    if (raw_data < 0) {
        fprintf(stderr, "Failed to read temperature from register 0x%02X: %d\n", reg, raw_data);
        return -1000.0; // Indicate error with a very low temperature
    }
    return (double)raw_data * TEMP_SCALE + TEMP_OFFSET;
}

// Log temperature to file
void log_temperature(double ambient_temp, double object_temp) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, ambient_temp, object_temp);
        fflush(log_file); // Ensure data is written to disk
    } else {
        fprintf(stderr, "Log file is not open\n");
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed, exiting...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_fd >= 0) {
        i2cClose(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

