#define SDP810_ADDR 0x25
#define MEASURE_CMD_1 0x36
#define MEASURE_CMD_2 0x08
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF
#define LOG_FILE "pressure_log.csv"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t pressure_raw;
    int16_t temperature_raw;
    int16_t scale_factor_pressure;
    int16_t scale_factor_temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int configure_sensor();
int read_sensor_data(sensor_data_t *data);
uint8_t calculate_crc(const uint8_t *data, size_t len);
int validate_crc(const uint8_t *data, size_t len);
float convert_pressure(int16_t raw_pressure, int16_t scale_factor_pressure);
float convert_temperature(int16_t raw_temperature, int16_t scale_factor_temperature);
int log_data(float pressure, float temperature);
void signal_handler(int signal);

// Function to initialize the I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to configure the SDP810 sensor
int configure_sensor() {
    char cmd[2] = {MEASURE_CMD_1, MEASURE_CMD_2};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error configuring sensor: %d\n", result);
        return -1;
    }
    gpioDelay(1); // Wait at least 1 ms
    return 0;
}

// Function to read data from the SDP810 sensor
int read_sensor_data(sensor_data_t *data) {
    uint8_t buffer[9];
    int result = i2cReadDevice(i2c_handle, (char *)buffer, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    // Extract raw data and CRC values
    data->pressure_raw = (int16_t)((buffer[0] << 8) | buffer[1]);
    uint8_t pressure_crc = buffer[2];
    data->temperature_raw = (int16_t)((buffer[3] << 8) | buffer[4]);
    uint8_t temperature_crc = buffer[5];
    data->scale_factor_pressure = (int16_t)((buffer[6] << 8) | buffer[7]);
    uint8_t scale_factor_crc = buffer[8];

    // Validate CRC values
    if (validate_crc(buffer, 3) != 0) {
        fprintf(stderr, "Pressure CRC validation failed\n");
        return -1;
    }
    if (validate_crc(buffer + 3, 3) != 0) {
        fprintf(stderr, "Temperature CRC validation failed\n");
        return -1;
    }
    if (validate_crc(buffer + 6, 3) != 0) {
        fprintf(stderr, "Scale Factor CRC validation failed\n");
        return -1;
    }

    return 0;
}

// Function to calculate CRC-8 checksum
uint8_t calculate_crc(const uint8_t *data, size_t len) {
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to validate CRC-8 checksum
int validate_crc(const uint8_t *data, size_t len) {
    uint8_t calculated_crc = calculate_crc(data, len - 1);
    return (calculated_crc != data[len - 1]);
}

// Function to convert raw pressure to Pascals
float convert_pressure(int16_t raw_pressure, int16_t scale_factor_pressure) {
    return (float)raw_pressure / scale_factor_pressure;
}

// Function to convert raw temperature to Celsius
float convert_temperature(int16_t raw_temperature, int16_t scale_factor_temperature) {
    return (float)raw_temperature / scale_factor_temperature;
}

// Function to log data to a CSV file
int log_data(float pressure, float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return -1;
    }

    // Check if the file is empty and write the header if needed
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "timestamp,pressure_Pa,temperature_C\n");
    }

    // Get current UTC time in ISO 8601 format
    time_t rawtime;
    struct tm *info;
    char timestamp[30];
    time(&rawtime);
    info = gmtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", info);

    // Write data to the file
    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);

    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure sensor
    if (configure_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Convert data
            float pressure = convert_pressure(sensor_data.pressure_raw, sensor_data.scale_factor_pressure);
            float temperature = convert_temperature(sensor_data.temperature_raw, sensor_data.scale_factor_temperature);

            // Log data
            if (log_data(pressure, temperature) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Close I2C connection and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

