#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SHT40_ADDR 0x44
#define MEASURE_HIGH_REPEATABILITY 0xFD
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF
#define LOG_FILE "sht40_log.txt"
#define MEASUREMENT_DELAY_MS 10
#define READ_DELAY_S 5

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_open(const char *bus);
int i2c_write(int fd, uint8_t addr, uint8_t *data, int len);
int i2c_read(int fd, uint8_t addr, uint8_t *data, int len);
uint8_t crc8(const uint8_t *data, int len);
int sht40_read_measurement(int fd, float *temperature, float *humidity);
int log_data(FILE *fp, float temperature, float humidity);
void signal_handler(int sig);

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// I2C open function
int i2c_open(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    return fd;
}

// I2C write function
int i2c_write(int fd, uint8_t addr, uint8_t *data, int len) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }
    ssize_t bytes_written = write(fd, data, len);
    if (bytes_written != len) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, uint8_t addr, uint8_t *data, int len) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        return -1;
    }
    ssize_t bytes_read = read(fd, data, len);
    if (bytes_read != len) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// SHT40 read measurement function
int sht40_read_measurement(int fd, float *temperature, float *humidity) {
    uint8_t cmd = MEASURE_HIGH_REPEATABILITY;
    uint8_t data[6];

    if (i2c_write(fd, SHT40_ADDR, &cmd, 1) < 0) {
        fprintf(stderr, "Error writing measurement command\n");
        return -1;
    }

    usleep(MEASUREMENT_DELAY_MS * 1000); // Wait for measurement

    if (i2c_read(fd, SHT40_ADDR, data, 6) < 0) {
        fprintf(stderr, "Error reading measurement data\n");
        return -1;
    }

    // CRC validation
    if (crc8(data, 2) != data[2] || crc8(data + 3, 2) != data[5]) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    // Convert raw data to temperature and humidity
    uint16_t raw_temperature = (data[0] << 8) | data[1];
    uint16_t raw_humidity = (data[3] << 8) | data[4];

    *temperature = -45.0 + 175.0 * (float)raw_temperature / 65535.0;
    *humidity = 100.0 * (float)raw_humidity / 65535.0;

    return 0;
}

// Log data function
int log_data(FILE *fp, float temperature, float humidity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = i2c_open(I2C_BUS);
    if (i2c_fd < 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    float temperature, humidity;

    // Main loop
    while (!terminate) {
        if (sht40_read_measurement(i2c_fd, &temperature, &humidity) == 0) {
            if (log_data(log_file, temperature, humidity) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading SHT40 measurement\n");
        }

        sleep(READ_DELAY_S);
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

