#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI7015_ADDR 0x40
#define TEMP_CMD 0xF3
#define HUM_CMD 0xF5
#define SAMPLE_INTERVAL 5 // seconds

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int open_i2c_bus();
int read_sensor_data(int handle, unsigned char command, float *value);
int log_data(float temperature, float humidity);
void print_data(float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus() {
    int handle = i2cOpen(I2C_BUS, SI7015_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return -1;
    }
    return handle;
}

// Read sensor data
int read_sensor_data(int handle, unsigned char command, float *value) {
    char buf[2];
    int result;

    result = i2cWriteByteData(handle, command, 0); // Send command
    if (result < 0) {
        fprintf(stderr, "Failed to write command: %s\n", strerror(errno));
        return -1;
    }

    gpioDelay(20); // Wait for measurement (adjust as needed)

    result = i2cReadI2CBlockData(handle, 0, buf, 2); // Read 2 bytes
    if (result < 0) {
        fprintf(stderr, "Failed to read data: %s\n", strerror(errno));
        return -1;
    }

    unsigned int raw_value = (buf[0] << 8) | buf[1];

    // Convert raw value to temperature or humidity
    if (command == TEMP_CMD) {
        *value = (175.72 * raw_value / 65536.0) - 46.85;
    } else if (command == HUM_CMD) {
        *value = (125.0 * raw_value / 65536.0) - 6.0;
        if (*value < 0.0) *value = 0.0;
        if (*value > 100.0) *value = 100.0;
    } else {
        fprintf(stderr, "Invalid command\n");
        return -1;
    }

    return 0;
}

// Log data to file
int log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen("sensor_data.txt", "a");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
            return -1;
        }
    }

    fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Print data to console
void print_data(float temperature, float humidity) {
    printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    i2c_handle = open_i2c_bus();
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read temperature
        if (read_sensor_data(i2c_handle, TEMP_CMD, &sensor_data.temperature) != 0) {
            fprintf(stderr, "Failed to read temperature, retrying...\n");
            gpioDelay(1000); // Wait before retrying
            continue;
        }

        // Read humidity
        if (read_sensor_data(i2c_handle, HUM_CMD, &sensor_data.humidity) != 0) {
            fprintf(stderr, "Failed to read humidity, retrying...\n");
            gpioDelay(1000); // Wait before retrying
            continue;
        }

        // Log and print data
        if (log_data(sensor_data.temperature, sensor_data.humidity) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }
        print_data(sensor_data.temperature, sensor_data.humidity);

        gpioDelay(SAMPLE_INTERVAL * 1000); // Wait for the next sample
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

