// Constants
#define I2C_BUS "/dev/i2c-1"
#define SDP800_ADDRESS 0x25
#define MEASURE_COMMAND 0x362F
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF
#define DATA_FILE "airflow_data.txt"
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t pressure_raw;
    int16_t temperature_raw;
    int16_t scale_factor_raw;
} sensor_data_t;

// Function prototypes
int i2c_init(const char *bus, int address);
int i2c_write(int fd, uint16_t command);
int i2c_read(int fd, uint8_t *data, int len);
uint8_t crc8(const uint8_t *data, int len);
int validate_crc(const uint8_t *data, int len);
int16_t convert_raw_to_pa(int16_t raw_pressure, int16_t scale_factor);
float convert_raw_to_celsius(int16_t raw_temperature);
int log_data(FILE *fp, int16_t pressure_pa, float temperature_c);
void signal_handler(int sig);
void cleanup();

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC validation function
int validate_crc(const uint8_t *data, int len) {
    uint8_t crc = crc8(data, len - 1);
    return (crc == data[len - 1]);
}

// I2C initialization function
int i2c_init(const char *bus, int address) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// I2C write function
int i2c_write(int fd, uint16_t command) {
    uint8_t data[2];
    data[0] = (command >> 8) & 0xFF;
    data[1] = command & 0xFF;

    if (write(fd, data, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }

    return 0;
}

// I2C read function
int i2c_read(int fd, uint8_t *data, int len) {
    if (read(fd, data, len) != len) {
        perror("Error reading from I2C device");
        return -1;
    }

    return 0;
}

