        perror("Error writing to log file");
        return -1;
    }

    fflush(fp); // Ensure data is written immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", sig);
}

// Cleanup function to close resources
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = i2c_init(I2C_BUS, SDP800_ADDRESS);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(DATA_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Pressure (Pa),Temperature (C)\n");
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        // Trigger continuous measurement
        if (i2c_write(i2c_fd, MEASURE_COMMAND) < 0) {
            fprintf(stderr, "Failed to trigger measurement. Retrying...\n");
            usleep(SAMPLE_INTERVAL_MS * 1000); // Wait before retrying
            continue;
        }

        // Wait for measurement to complete
        usleep(45000); // 45 ms

        // Read data
        uint8_t data[9];
        if (i2c_read(i2c_fd, data, 9) < 0) {
            fprintf(stderr, "Failed to read data. Retrying...\n");
            usleep(SAMPLE_INTERVAL_MS * 1000); // Wait before retrying
            continue;
        }

        // Validate CRC for pressure
        if (!validate_crc(data, 3)) {
            fprintf(stderr, "Pressure CRC validation failed. Retrying...\n");
            usleep(SAMPLE_INTERVAL_MS * 1000); // Wait before retrying
            continue;
        }

        // Validate CRC for temperature
        if (!validate_crc(data + 3, 3)) {
            fprintf(stderr, "Temperature CRC validation failed. Retrying...\n");
            usleep(SAMPLE_INTERVAL_MS * 1000); // Wait before retrying
            continue;
