            usleep(SAMPLE_INTERVAL_MS * 1000); // Wait before retrying
            continue;
        }

        // Extract raw data
        sensor_data_t sensor_data;
        sensor_data.pressure_raw = (data[0] << 8) | data[1];
        sensor_data.temperature_raw = (data[3] << 8) | data[4];
        sensor_data.scale_factor_raw = (data[6] << 8) | data[7];

        // Convert raw data
        int16_t pressure_pa = convert_raw_to_pa(sensor_data.pressure_raw, sensor_data.scale_factor_raw);
        float temperature_c = convert_raw_to_celsius(sensor_data.temperature_raw);

