#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define STS30_ADDR 0x4A
#define MEASURE_CMD 0x2C06
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL 0xFF
#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG_FILE "error_log.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_temperature(float *temperature);
int validate_crc(uint8_t data[], int len);
int log_temperature(float temperature);
int log_error(const char *message);
void signal_handler(int signal);

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC_INITIAL;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, STS30_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        return -1;
    }
    return 0;
}

// Read temperature from the sensor
int read_temperature(float *temperature) {
    uint8_t cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    uint8_t data[3];

    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 2) {
        log_error("Failed to write measurement command");
        return -1;
    }

    gpioDelay(15); // Wait for conversion

    if (i2cReadDevice(i2c_handle, (char *)data, 3) != 3) {
        log_error("Failed to read temperature data");
        return -1;
    }

    if (validate_crc(data, 2) != 0) {
        log_error("CRC validation failed");
        return -1;
    }

    uint16_t raw_temp = (data[0] << 8) | data[1];
    *temperature = -45.0 + 175.0 * (raw_temp / 65535.0);

    return 0;
}

// Validate CRC checksum
int validate_crc(uint8_t data[], int len) {
    uint8_t calculated_crc = crc8(data, len);
    if (calculated_crc != data[len]) {
        return -1;
    }
    return 0;
}

// Log temperature to file
int log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        log_error("Failed to open log file");
        return -1;
    }

    fprintf(fp, "%s, %.2f\n", timestamp, temperature);
    fclose(fp);
    return 0;
}

// Log error to file
int log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open error log file");
        return -1;
    }

    fprintf(fp, "%s, %s\n", timestamp, message);
    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    float temperature;

    while (!terminate) {
        if (read_temperature(&temperature) == 0) {
            if (log_temperature(temperature) != 0) {
                log_error("Failed to log temperature");
            }
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            log_error("Failed to read temperature");
        }

        sleep(5);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

