    struct tm *timeinfo;
    char timestamp[20];

    timeinfo = localtime(&data.timestamp);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.pressure, data.temperature);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

