void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("airflow_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Send measurement command
    if (send_command(i2c_handle, MEASUREMENT_COMMAND) != 0) {
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        char buffer[6];
        int16_t raw_pressure, raw_temperature;
        float pressure, temperature;
        sensor_data_t data;

        // Read data from sensor
        if (read_data(i2c_handle, buffer, 6) != 0) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Validate CRC for pressure
        if (!validate_crc(buffer, 3)) {
            fprintf(stderr, "Pressure CRC validation failed!\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Validate CRC for temperature
        if (!validate_crc(buffer + 3, 3)) {
            fprintf(stderr, "Temperature CRC validation failed!\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Convert raw data to physical values
        raw_pressure = (buffer[0] << 8) | buffer[1];
        raw_temperature = (buffer[3] << 8) | buffer[4];

        pressure = convert_pressure(raw_pressure);
        temperature = convert_temperature(raw_temperature);

        // Get timestamp
        data.timestamp = time(NULL);
        data.pressure = pressure;
        data.temperature = temperature;

        // Log data
        log_data(data);

        // Wait 1 second
        gpioDelay(1000);
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

