#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// SCD40 I2C address
#define SCD40_ADDR 0x62

// SCD40 commands
#define CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define CMD_STOP_PERIODIC_MEASUREMENT 0x3F86
#define CMD_READ_MEASUREMENT 0xEC05
#define CMD_DATA_READY 0xE4B8

// CRC polynomial
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int open_i2c_bus();
int send_command(int handle, uint16_t command);
int read_data(int handle, uint8_t *data, int count);
uint8_t calculate_crc(uint16_t data);
int verify_crc(uint16_t data, uint8_t crc);
int read_scd40_data(int handle, uint16_t *co2, uint16_t *temperature, uint16_t *humidity);
int log_data(uint16_t co2, uint16_t temperature, uint16_t humidity);
void signal_handler(int signal);

// CRC-8 calculation function
uint8_t calculate_crc(uint16_t data) {
    uint8_t crc = CRC_INIT;
    uint8_t data_bytes[2];
    data_bytes[0] = (data >> 8) & 0xFF;
    data_bytes[1] = data & 0xFF;

    for (int i = 0; i < 2; i++) {
        crc ^= data_bytes[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC verification function
int verify_crc(uint16_t data, uint8_t crc) {
    uint8_t calculated_crc = calculate_crc(data);
    return (calculated_crc == crc);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus() {
    int handle = i2cOpen(1, SCD40_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", handle);
        return -1;
    }
    return handle;
}

// Send a command to the SCD40
int send_command(int handle, uint16_t command) {
    uint8_t buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, (char *)buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to send command 0x%04X: %d\n", command, result);
        return -1;
    }
    return 0;
}

// Read data from the SCD40
int read_data(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Read SCD40 data
int read_scd40_data(int handle, uint16_t *co2, uint16_t *temperature, uint16_t *humidity) {
    uint8_t data[9];
    uint8_t crc;

    // Check data ready flag
    if (send_command(handle, CMD_DATA_READY) != 0) return -1;
    gpioDelay(1000); // Wait 1 ms
    uint8_t ready_data[2];
    if (read_data(handle, ready_data, 2) != 0) return -1;
    uint16_t ready_flag = (ready_data[0] << 8) | ready_data[1];
    if ((ready_flag & 0x0001) == 0) {
        fprintf(stderr, "Data not ready\n");
        return -1;
    }

    // Read measurement data
    if (send_command(handle, CMD_READ_MEASUREMENT) != 0) return -1;
    gpioDelay(1000); // Wait 1 ms
    if (read_data(handle, data, 9) != 0) return -1;

    // Verify CRC for CO2
    crc = data[2];
    if (!verify_crc((data[0] << 8) | data[1], crc)) {
        fprintf(stderr, "CO2 CRC check failed\n");
        return -1;
    }
    *co2 = (data[0] << 8) | data[1];

    // Verify CRC for temperature
    crc = data[5];
    if (!verify_crc((data[3] << 8) | data[4], crc)) {
        fprintf(stderr, "Temperature CRC check failed\n");
        return -1;
    }
    *temperature = (data[3] << 8) | data[4];

    // Verify CRC for humidity
    crc = data[8];
    if (!verify_crc((data[6] << 8) | data[7], crc)) {
        fprintf(stderr, "Humidity CRC check failed\n");
        return -1;
    }
    *humidity = (data[6] << 8) | data[7];

    return 0;
}

// Log data to file
int log_data(uint16_t co2, uint16_t temperature, uint16_t humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%u,%.2f,%.2f\n", timestamp, co2, -45.0 + 175.0 * temperature / 65535.0, 100.0 * humidity / 65535.0);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    i2c_handle = open_i2c_bus();
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Start periodic measurement
    if (send_command(i2c_handle, CMD_START_PERIODIC_MEASUREMENT) != 0) {
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioDelay(1000); // Wait 1 second

    uint16_t co2, temperature, humidity;

    // Main loop
    while (!terminate) {
        if (read_scd40_data(i2c_handle, &co2, &temperature, &humidity) == 0) {
            log_data(co2, temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read SCD40 data\n");
        }
        sleep(5);
    }

    // Stop periodic measurement
    if (send_command(i2c_handle, CMD_STOP_PERIODIC_MEASUREMENT) != 0) {
        fprintf(stderr, "Failed to stop periodic measurement\n");
    }

    // Close I2C bus and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

