        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioDelay(1000); // Wait 1 second

    uint16_t co2, temperature, humidity;

    // Main loop
    while (!terminate) {
        if (read_scd40_data(i2c_handle, &co2, &temperature, &humidity) == 0) {
            log_data(co2, temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read SCD40 data\n");
        }
        sleep(5);
    }

    // Stop periodic measurement
    if (send_command(i2c_handle, CMD_STOP_PERIODIC_MEASUREMENT) != 0) {
        fprintf(stderr, "Failed to stop periodic measurement\n");
    }

    // Close I2C bus and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

