#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// SCD40 I2C address
#define SCD40_ADDR 0x62

// SCD40 commands
#define START_PERIODIC_MEASUREMENT 0x21B1
#define STOP_PERIODIC_MEASUREMENT 0x3F86
#define GET_DATA_READY_STATUS 0xE4B8
#define READ_MEASUREMENT 0xEC05

// GPIO pin for LED
#define LED_PIN 17

// Circular buffer size
#define BUFFER_SIZE 20

// Structure to hold sensor data
typedef struct {
    uint16_t co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Circular buffer structure
typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global variables
int i2c_handle;
circular_buffer_t buffer;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int start_periodic_measurement();
int stop_periodic_measurement();
int get_data_ready_status();
int read_measurement(uint16_t *co2, float *temperature, float *humidity);
uint8_t crc8(const uint8_t *data, int len);
int validate_checksum(uint16_t data, uint8_t crc);
void add_to_buffer(circular_buffer_t *buffer, sensor_data_t data);
int get_from_buffer(circular_buffer_t *buffer, int index, sensor_data_t *data);
void control_led(float co2);
void signal_handler(int signal);

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(1, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Start periodic measurement
int start_periodic_measurement() {
    uint8_t cmd[2] = {(START_PERIODIC_MEASUREMENT >> 8) & 0xFF, START_PERIODIC_MEASUREMENT & 0xFF};
    int result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Start periodic measurement failed: %d\n", result);
        return -1;
    }
    return 0;
}

// Stop periodic measurement
int stop_periodic_measurement() {
    uint8_t cmd[2] = {(STOP_PERIODIC_MEASUREMENT >> 8) & 0xFF, STOP_PERIODIC_MEASUREMENT & 0xFF};
    int result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Stop periodic measurement failed: %d\n", result);
        return -1;
    }
    return 0;
}

// Get data ready status
int get_data_ready_status() {
    uint8_t cmd[2] = {(GET_DATA_READY_STATUS >> 8) & 0xFF, GET_DATA_READY_STATUS & 0xFF};
    uint8_t buffer[2];
    int result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Get data ready status write failed: %d\n", result);
        return -1;
    }
    result = i2cReadDevice(i2c_handle, (char *)buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Get data ready status read failed: %d\n", result);
        return -1;
    }
    return ((buffer[0] << 8) | buffer[1]);
}

// Read measurement data
int read_measurement(uint16_t *co2, float *temperature, float *humidity) {
    uint8_t cmd[2] = {(READ_MEASUREMENT >> 8) & 0xFF, READ_MEASUREMENT & 0xFF};
    uint8_t buffer[9];
    int result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Read measurement write failed: %d\n", result);
        return -1;
    }
    result = i2cReadDevice(i2c_handle, (char *)buffer, 9);
    if (result != 9) {
        fprintf(stderr, "Read measurement read failed: %d\n", result);
        return -1;
    }

    // Extract data
    uint16_t raw_co2 = (buffer[0] << 8) | buffer[1];
    uint16_t raw_temperature = (buffer[3] << 8) | buffer[4];
    uint16_t raw_humidity = (buffer[6] << 8) | buffer[7];

    // CRC validation
    if (!validate_checksum(raw_co2, buffer[2])) {
        fprintf(stderr, "CO2 CRC validation failed\n");
        return -1;
    }
    if (!validate_checksum(raw_temperature, buffer[5])) {
        fprintf(stderr, "Temperature CRC validation failed\n");
        return -1;
    }
    if (!validate_checksum(raw_humidity, buffer[8])) {
        fprintf(stderr, "Humidity CRC validation failed\n");
        return -1;
    }

    // Convert to physical values
    *co2 = raw_co2;
    *temperature = -45 + 175 * (raw_temperature / 65535.0);
    *humidity = 100 * (raw_humidity / 65535.0);

    return 0;
}

// CRC-8 checksum calculation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate checksum
int validate_checksum(uint16_t data, uint8_t crc) {
    uint8_t data_bytes[2];
    data_bytes[0] = (data >> 8) & 0xFF;
    data_bytes[1] = data & 0xFF;
    uint8_t calculated_crc = crc8(data_bytes, 2);
    return (calculated_crc == crc);
}

// Add data to circular buffer
void add_to_buffer(circular_buffer_t *buffer, sensor_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Get data from circular buffer
int get_from_buffer(circular_buffer_t *buffer, int index, sensor_data_t *data) {
    if (index < 0 || index >= buffer->count) {
        return -1; // Invalid index
    }
    int actual_index = (buffer->head - buffer->count + index + BUFFER_SIZE) % BUFFER_SIZE;
    *data = buffer->data[actual_index];
    return 0;
}

// Control LED based on CO2 level
void control_led(float co2) {
    if (co2 > 1000) {
        gpioWrite(LED_PIN, 1); // Turn LED on
    } else {
        gpioWrite(LED_PIN, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, stopping...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    buffer.head = 0;
    buffer.count = 0;

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Start periodic measurement
    if (start_periodic_measurement() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Check if data is ready
        int data_ready = get_data_ready_status();
        if (data_ready < 0) {
            fprintf(stderr, "Error getting data ready status, retrying...\n");
            sleep(1);
            continue;
        }

        if ((data_ready & 0x01) == 0) {
            sleep(1); // Wait for data to be ready
            continue;
        }

        // Read measurement data
        uint16_t raw_co2;
        float temperature, humidity;
        if (read_measurement(&raw_co2, &temperature, &humidity) == 0) {
            // Create sensor data
            sensor_data_t data;
            data.co2 = raw_co2;
            data.temperature = temperature;
            data.humidity = humidity;

            // Add data to circular buffer
            add_to_buffer(&buffer, data);

            // Print data
            printf("CO2: %d ppm, Temperature: %.2f °C, Humidity: %.2f %%\n", data.co2, data.temperature, data.humidity);

            // Control LED
            control_led(data.co2);
        } else {
            fprintf(stderr, "Error reading measurement data, retrying...\n");
        }

        sleep(5); // Measurement interval
    }

    // Stop periodic measurement
    if (stop_periodic_measurement() != 0) {
        fprintf(stderr, "Error stopping periodic measurement\n");
    }

    // Close I2C
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

