#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define GPIO_PIN 4
#define LOG_FILE "temperature_log.txt"
#define TIMEOUT_US 50000 // 50ms
#define MAX_FAILURES 3

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_temperature(double *temperature);
int log_temperature(double temperature);
void signal_handler(int signal);
void cleanup();

int main() {
    double temperature;
    int failures = 0;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        if (read_temperature(&temperature) == 0) {
            if (temperature >= -40.0 && temperature <= 150.0) {
                if (log_temperature(temperature) != 0) {
                    fprintf(stderr, "Failed to log temperature.\n");
                }
                failures = 0; // Reset failure count
            } else {
                fprintf(stderr, "Temperature out of range: %.2f\n", temperature);
                if (log_temperature(-999.0) != 0) { // Log error
                    fprintf(stderr, "Failed to log error.\n");
                }
                failures++;
            }
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
            if (log_temperature(-999.0) != 0) { // Log error
                fprintf(stderr, "Failed to log error.\n");
            }
            failures++;
        }

        if (failures >= MAX_FAILURES) {
            fprintf(stderr, "SENSOR MALFUNCTION\n");
            if (log_temperature(-998.0) != 0) { // Log malfunction
                fprintf(stderr, "Failed to log malfunction.\n");
            }
            failures = 0; // Reset failure count to avoid repeated logging
        }

        sleep(5);
    }

    // Cleanup
    cleanup();

    return 0;
}

int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    gpioSetMode(GPIO_PIN, PI_INPUT);
    return 0;
}

int read_temperature(double *temperature) {
    uint32_t start_tick, end_tick, high_tick, low_tick;
    int timeout = 0;

    // Measure high time
    start_tick = gpioTick();
    while (gpioRead(GPIO_PIN) == 0) {
        end_tick = gpioTick();
        if (end_tick - start_tick > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for rising edge\n");
            return 1;
        }
        timeout++;
        if (timeout > 1000) return 1; //Prevent infinite loop
    }
    high_tick = gpioTick() - start_tick;

    // Measure low time
    start_tick = gpioTick();
    while (gpioRead(GPIO_PIN) == 1) {
        end_tick = gpioTick();
        if (end_tick - start_tick > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for falling edge\n");
            return 1;
        }
        timeout++;
        if (timeout > 1000) return 1; //Prevent infinite loop
    }
    low_tick = gpioTick() - start_tick;

    // Calculate temperature
    if (low_tick == 0) {
        fprintf(stderr, "Division by zero error\n");
        return 1;
    }
    *temperature = 4215.0 - (2143.0 * (double)high_tick / (double)low_tick);

    return 0;
}

int log_temperature(double temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, temperature);
        fflush(log_file); // Ensure data is written to disk
        return 0;
    } else {
        fprintf(stderr, "Log file is not open\n");
        return 1;
    }
}

void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    program_running = 0;
}

void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

