#define SHT35_ADDR 0x44
#define MEASUREMENT_COMMAND 0x2400
#define CRC_POLYNOMIAL 0x31
#define LOG_FILE "environmental_data.txt"
#define OFFSET_AMPLITUDE_TEMP 2.0
#define OFFSET_AMPLITUDE_HUMID 5.0
#define OFFSET_PERIOD 3600.0 // seconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int open_i2c_bus();
int write_i2c(int handle, uint16_t command);
int read_i2c(int handle, char *buffer, int count);
uint8_t calculate_crc(const uint8_t *data, int len);
int validate_crc(const uint8_t *data, int len);
int read_sensor_data(int handle, float *temperature, float *humidity);
float apply_temperature_offset(float temperature, float time_offset);
float apply_humidity_offset(float humidity, float time_offset);
int log_data(float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open I2C bus
    if (open_i2c_bus() != 0) {
        fprintf(stderr, "Failed to open I2C bus. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        sensor_data_t sensor_data;
        time_t current_time = time(NULL);
        float time_offset = (float)(current_time % (int)OFFSET_PERIOD);

        // Read sensor data
        if (read_sensor_data(i2c_handle, &sensor_data.temperature, &sensor_data.humidity) != 0) {
            fprintf(stderr, "Failed to read sensor data.\n");
            continue; // Skip to the next iteration
        }

        // Apply sinusoidal offsets
        sensor_data.temperature = apply_temperature_offset(sensor_data.temperature, time_offset);
        sensor_data.humidity = apply_humidity_offset(sensor_data.humidity, time_offset);

        // Log data
        if (log_data(sensor_data.temperature, sensor_data.humidity) != 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup
    cleanup();

    return 0;
}

// Initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus() {
    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Write to I2C
int write_i2c(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "I2C write failed: %d\n", result);
        return 1;
    }
    return 0;
}

// Read from I2C
int read_i2c(int handle, char *buffer, int count) {
    int result = i2cReadDevice(handle, buffer, count);
    if (result != count) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        return 1;
    }
    return 0;
}

// Calculate CRC
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC
int validate_crc(const uint8_t *data, int len) {
    uint8_t crc = calculate_crc(data, len - 1);
    return (crc == data[len - 1]);
}

// Read sensor data
int read_sensor_data(int handle, float *temperature, float *humidity) {
    int retries = 3;
    while (retries > 0) {
        // Send measurement command
        if (write_i2c(handle, MEASUREMENT_COMMAND) != 0) {
            fprintf(stderr, "Failed to send measurement command. Retrying...\n");
            retries--;
            sleep(1);
            continue;
        }

        // Wait for measurement (at least 15 ms)
        gpioDelay(15000); // 15 ms

        // Read 6 bytes of data
        char buffer[6];
        if (read_i2c(handle, buffer, 6) != 0) {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
            retries--;
            sleep(1);
            continue;
        }

        // Validate CRC for temperature
        if (!validate_crc((uint8_t *)buffer, 2)) {
            fprintf(stderr, "Temperature CRC validation failed. Retrying...\n");
            retries--;
            sleep(1);
            continue;
        }

        // Validate CRC for humidity
        if (!validate_crc((uint8_t *)buffer + 2, 2)) {
            fprintf(stderr, "Humidity CRC validation failed. Retrying...\n");
            retries--;
            sleep(1);
            continue;
        }

        // Convert raw data to temperature and humidity
        int temperature_raw = (buffer[0] << 8) | buffer[1];
        int humidity_raw = (buffer[3] << 8) | buffer[4];

        *temperature = -45.0 + (175.0 * (float)temperature_raw / 65535.0);
        *humidity = 100.0 * (float)humidity_raw / 65535.0;

        return 0; // Success
    }

    // All retries failed
    fprintf(stderr, "Failed to read sensor data after multiple retries.\n");
    *temperature = NAN;
    *humidity = NAN;
    return 1; // Failure
}

// Apply temperature offset
float apply_temperature_offset(float temperature, float time_offset) {
    return temperature + OFFSET_AMPLITUDE_TEMP * sin(2 * M_PI * time_offset / OFFSET_PERIOD);
}

// Apply humidity offset
float apply_humidity_offset(float humidity, float time_offset) {
    return humidity + OFFSET_AMPLITUDE_HUMID * sin(2 * M_PI * time_offset / OFFSET_PERIOD);
}

// Log data
int log_data(float temperature, float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity) < 0) {
        fprintf(stderr, "Failed to write to log file.\n");
        return 1;
    }

    fflush(log_file);
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    gpioTerminate();
}

