            fprintf(stderr, "Retrying in %d seconds...\n", SAMPLE_INTERVAL_SEC);
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        // Validate CRC checksums
        if (validate_crc(data, 2) != 0 || validate_crc(data + 3, 2) != 0) {
