        raw_humidity = (data[3] << 8) | data[4];
        if (convert_data(raw_temperature, raw_humidity, &temperature, &humidity) != 0) {
            fprintf(stderr, "Retrying in %d seconds...\n", SAMPLE_INTERVAL_SEC);
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        // Log data
