#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define HUMIDITY_CMD 0xF5
#define TEMPERATURE_CMD 0xF3
#define RESET_CMD 0xFE
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0x00
#define TIMEOUT_MS 100
#define LOG_INTERVAL_S 5

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_open(int bus, int addr);
int i2c_write(int fd, unsigned char *data, int len);
int i2c_read(int fd, unsigned char *data, int len);
int i2c_close(int fd);
int si7021_read_humidity(int fd, float *humidity);
int si7021_read_temperature(int fd, float *temperature);
int si7021_reset(int fd);
int validate_crc(unsigned char data[], int len);
int log_data(FILE *fp, float temperature, float humidity);
void signal_handler(int sig);

// CRC-8 calculation function
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = CRC_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// I2C open function
int i2c_open(int bus, int addr) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }
    return fd;
}

// I2C write function
int i2c_write(int fd, unsigned char *data, int len) {
    int bytes_written = write(fd, data, len);
    if (bytes_written != len) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, unsigned char *data, int len) {
    int bytes_read = read(fd, data, len);
    if (bytes_read != len) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// I2C close function
int i2c_close(int fd) {
    close(fd);
    return 0;
}

// Si7021 reset function
int si7021_reset(int fd) {
    unsigned char reset_cmd = RESET_CMD;
    if (i2c_write(fd, &reset_cmd, 1) != 0) {
        fprintf(stderr, "Error resetting Si7021\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete
    return 0;
}

// Si7021 read humidity function
int si7021_read_humidity(int fd, float *humidity) {
    unsigned char humidity_cmd = HUMIDITY_CMD;
    unsigned char data[3];
    int retries = 3;
    struct timespec start_time, current_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    while (retries > 0) {
        if (i2c_write(fd, &humidity_cmd, 1) != 0) {
            fprintf(stderr, "Error writing humidity command\n");
            retries--;
            gpioDelay(10); // Wait before retrying
            continue;
        }

        clock_gettime(CLOCK_MONOTONIC, &current_time);
        long elapsed_ms = (current_time.tv_sec - start_time.tv_sec) * 1000 + (current_time.tv_nsec - start_time.tv_nsec) / 1000000;
        if (elapsed_ms > TIMEOUT_MS) {
            fprintf(stderr, "Timeout waiting for humidity data\n");
            retries--;
            gpioDelay(10); // Wait before retrying
            continue;
        }

        if (i2c_read(fd, data, 3) != 0) {
            fprintf(stderr, "Error reading humidity data\n");
