#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASURE_CMD 0x362F
#define CRC8_POLYNOMIAL 0x31
#define SCALE_FACTOR_REG 0x00
#define SCALE_FACTOR_SIZE 3
#define DATA_SIZE 9
#define SAMPLE_INTERVAL_US 1000000 // 1 second

// Global variables
int i2c_handle;
FILE *data_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int open_i2c_bus();
int write_command(int handle, uint16_t command);
int read_data(int handle, char *buffer, int count);
uint8_t calculate_crc(const char *data, int len);
int validate_crc(const char *data, int len);
float convert_pressure(int16_t raw_pressure, float scale_factor);
float convert_temperature(int16_t raw_temperature);
int log_data(float pressure, float temperature);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t calculate_crc(const char *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC-8 validation function
int validate_crc(const char *data, int len) {
    uint8_t crc_calculated = calculate_crc(data, len - 1);
    return (crc_calculated == data[len - 1]);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus() {
    int handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", handle);
        return -1;
    }
    return handle;
}

// Write command to the sensor
int write_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to write command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from the sensor
int read_data(int handle, char *buffer, int count) {
    int result = i2cReadDevice(handle, buffer, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Convert raw pressure to Pascals
float convert_pressure(int16_t raw_pressure, float scale_factor) {
    return (float)raw_pressure / scale_factor - 1000.0;
}

// Convert raw temperature to Celsius
float convert_temperature(int16_t raw_temperature) {
    return (float)raw_temperature / 200.0 - 45.0;
}

// Log data to file
int log_data(float pressure, float temperature) {
    if (fwrite(&pressure, sizeof(float), 1, data_file) != 1) {
        fprintf(stderr, "Failed to write pressure to file\n");
        return -1;
    }
    if (fwrite(&temperature, sizeof(float), 1, data_file) != 1) {
        fprintf(stderr, "Failed to write temperature to file\n");
        return -1;
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (data_file != NULL) {
        fclose(data_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    i2c_handle = open_i2c_bus();
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    // Open data file
    data_file = fopen("airflow.dat", "wb");
    if (data_file == NULL) {
        fprintf(stderr, "Failed to open data file\n");
        cleanup();
        return 1;
    }

    // Write continuous measurement command
    if (write_command(i2c_handle, MEASURE_CMD) != 0) {
        cleanup();
        return 1;
    }

    // Read scale factor
    char scale_factor_buffer[SCALE_FACTOR_SIZE];
    if (read_data(i2c_handle, scale_factor_buffer, SCALE_FACTOR_SIZE) != 0) {
        cleanup();
        return 1;
    }

    uint8_t scale_factor_msb = scale_factor_buffer[0];
    uint8_t scale_factor_lsb = scale_factor_buffer[1];
    uint8_t scale_factor_crc = scale_factor_buffer[2];

    uint8_t calculated_crc = calculate_crc((const char *)scale_factor_buffer, SCALE_FACTOR_SIZE - 1);
    if (calculated_crc != scale_factor_crc) {
        fprintf(stderr, "Scale factor CRC check failed\n");
        cleanup();
        return 1;
    }

    float scale_factor = (float)((scale_factor_msb << 8) | scale_factor_lsb);

    // Main loop
    while (!terminate) {
        char data_buffer[DATA_SIZE];
        if (read_data(i2c_handle, data_buffer, DATA_SIZE) != 0) {
            fprintf(stderr, "Failed to read sensor data, retrying...\n");
            gpioDelay(100000); // Wait 0.1 seconds before retrying
            continue;
        }

        // Validate CRC for pressure
        if (!validate_crc(data_buffer, 3)) {
            fprintf(stderr, "Pressure CRC check failed\n");
            continue;
        }

        // Validate CRC for temperature
        if (!validate_crc(data_buffer + 3, 3)) {
            fprintf(stderr, "Temperature CRC check failed\n");
            continue;
        }

        // Extract raw pressure and temperature
        int16_t raw_pressure = (data_buffer[0] << 8) | data_buffer[1];
        int16_t raw_temperature = (data_buffer[3] << 8) | data_buffer[4];

        // Convert pressure and temperature
        float pressure = convert_pressure(raw_pressure, scale_factor);
        float temperature = convert_temperature(raw_temperature);

        // Log data
        if (log_data(pressure, temperature) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

