    if (result != count) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return 1;
    }
    return 0;
}

// Calculate CRC-8
uint8_t calculate_crc(const char *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= (uint8_t)data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

