int validate_crc(const char *data, int len) {
    uint8_t crc_calculated = calculate_crc(data, len - 1);
    uint8_t crc_received = (uint8_t)data[len - 1];

    if (crc_calculated != crc_received) {
        fprintf(stderr, "CRC mismatch: calculated=0x%02X, received=0x%02X\n", crc_calculated, crc_received);
        return 1;
    }
    return 0;
}

