// Constants
#define I2C_BUS 1
#define I2C_ADDR 0x28
#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "flow_log.txt"

// Sensor calibration values
#define ZERO_SLPM_COUNTS 1638
#define TEN_SLPM_COUNTS 14745

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sensor_data(int i2c_handle, uint16_t *raw_data);
float convert_to_flow_rate(uint16_t raw_data);
void set_fan_speed(float flow_rate);
void log_data(FILE *log_file, float pressure_Pa);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, shutting down...\n");
    terminate = 1;
}

// Function to read sensor data
int read_sensor_data(int i2c_handle, uint16_t *raw_data) {
    char buf[2];
    int result = i2cReadDevice(i2c_handle, buf, 2);

    if (result != 2) {
        fprintf(stderr, "Error reading sensor data: %s\n", strerror(errno));
        return -1; // Indicate failure
    }

    *raw_data = (buf[0] << 8) | buf[1];
    return 0; // Indicate success
}

// Function to convert raw data to flow rate (SLPM)
float convert_to_flow_rate(uint16_t raw_data) {
    // Mask off status bits and shift right by 2
    uint16_t flow_data = raw_data & 0x3FFF; // Keep only the 14 data bits

    // Linear transfer function
    float flow_rate = (float)(flow_data - ZERO_SLPM_COUNTS) * 10.0f / (TEN_SLPM_COUNTS - ZERO_SLPM_COUNTS);

    // Clamp the flow rate to the range [0, 10]
    if (flow_rate < 0.0f) {
        flow_rate = 0.0f;
    } else if (flow_rate > 10.0f) {
        flow_rate = 10.0f;
    }

    return flow_rate;
}

// Function to set fan speed based on flow rate
void set_fan_speed(float flow_rate) {
    // Scale flow rate (0-10 SLPM) to PWM duty cycle (0-100%)
    int duty_cycle = (int)(flow_rate / 10.0f * 100.0f);

    // Set PWM duty cycle
    gpioPWM(FAN_GPIO, duty_cycle);
}

// Function to log data to file
void log_data(FILE *log_file, float pressure_Pa) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f\n", timestamp, pressure_Pa);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Configure fan GPIO as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_GPIO, 100); // Set PWM range to 0-100

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t raw_data;
    float flow_rate;
    float pressure_Pa;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_handle, &raw_data) == 0) {
            // Convert to flow rate
            flow_rate = convert_to_flow_rate(raw_data);

            // Calculate pressure in Pascals (example conversion, adjust as needed)
            pressure_Pa = flow_rate * 10.0f; // Example: 1 SLPM = 10 Pa

            // Set fan speed
            set_fan_speed(flow_rate);

            // Log data
            log_data(log_file, pressure_Pa);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Shutdown sequence
    fprintf(stderr, "Shutting down...\n");
    gpioPWM(FAN_GPIO, 0); // Turn off fan
    i2cClose(i2c_handle); // Close I2C bus
    fclose(log_file); // Close log file
    gpioTerminate(); // Terminate pigpio

    return 0;
}

