#define CTRL_REG1 0x10
#define PRESS_OUT_XL 0x28
#define PRESS_OUT_L 0x29
#define PRESS_OUT_H 0x2A
#define TEMP_OUT_L 0x2B
#define TEMP_OUT_H 0x2C

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_who_am_i();
int configure_sensor();
int read_pressure(int32_t *pressure);
int read_temperature(int16_t *temperature);
float convert_pressure(int32_t raw_pressure);
float convert_temperature(int16_t raw_temperature);
int log_data(float pressure, float temperature);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, LPS33HW_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read WHO_AM_I register
int read_who_am_i() {
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0xB1) {
        fprintf(stderr, "WHO_AM_I value incorrect: 0x%02X\n", who_am_i);
        return -1;
    }
    return 0;
}

// Configure CTRL_REG1 register
int configure_sensor() {
    int status = i2cWriteByteData(i2c_handle, CTRL_REG1, 0xB0);
    if (status < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1: %d\n", status);
        return -1;
    }
    return 0;
}

// Read pressure data
int read_pressure(int32_t *pressure) {
    char buffer[3];
    int status = i2cReadI2CBlockData(i2c_handle, PRESS_OUT_XL, buffer, 3);
    if (status < 0) {
        fprintf(stderr, "Error reading pressure data: %d\n", status);
        return -1;
    }

    *pressure = (int32_t)buffer[0] | ((int32_t)buffer[1] << 8) | ((int32_t)buffer[2] << 16);
    return 0;
}

// Read temperature data
int read_temperature(int16_t *temperature) {
    char buffer[2];
    int status = i2cReadI2CBlockData(i2c_handle, TEMP_OUT_L, buffer, 2);
    if (status < 0) {
        fprintf(stderr, "Error reading temperature data: %d\n", status);
        return -1;
    }

