        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int32_t raw_pressure;
        int16_t raw_temperature;
        float pressure, temperature;

        // Read pressure and temperature
        if (read_pressure(&raw_pressure) == 0 && read_temperature(&raw_temperature) == 0) {
            // Convert data
            pressure = convert_pressure(raw_pressure);
            temperature = convert_temperature(raw_temperature);

            // Log data
            log_data(pressure, temperature);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Delay for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    // Close I2C handle and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

