#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define STLM75_ADDR 0x48
#define TEMP_REG 0x00
#define LED_GPIO 17
#define BUFFER_SIZE 10
#define TEMP_THRESHOLD 28.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
float read_temperature();
void update_circular_buffer(float temperature);
float calculate_average_temperature();
void control_led(float average_temperature);
void signal_handler(int signal);

// Function to read temperature from STLM75
float read_temperature() {
    int raw_data;
    int retries = 3; // Number of retries

    while (retries > 0) {
        raw_data = i2cReadWordData(i2c_handle, TEMP_REG);
        if (raw_data >= 0) {
            // Success
            break;
        } else {
            // Error, retry after a short delay
            fprintf(stderr, "I2C read error, retrying...\n");
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }

    if (retries == 0) {
        fprintf(stderr, "Failed to read temperature after multiple retries.\n");
        return -273.15; // Return absolute zero as error indicator
    }

    // Swap bytes (big-endian to little-endian)
    raw_data = ((raw_data & 0xFF00) >> 8) | ((raw_data & 0x00FF) << 8);

    // Extract 9-bit temperature value (shift right by 7 bits)
    int16_t temp_value = (raw_data >> 7) & 0x1FF; // Mask to get only 9 bits

    // Convert to Celsius (divide by 2)
    float temperature = (float)temp_value / 2.0;

    return temperature;
}

// Function to update the circular buffer
void update_circular_buffer(float temperature) {
    temperature_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to calculate the average temperature
float calculate_average_temperature() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += temperature_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Function to control the LED
void control_led(float average_temperature) {
    if (average_temperature > TEMP_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating program...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, STLM75_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize circular buffer with 0.0
    for (int i = 0; i < BUFFER_SIZE; i++) {
        temperature_buffer[i] = 0.0;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();

        if (temperature > -273.0) { // Check for valid temperature reading
            update_circular_buffer(temperature);
            float average_temperature = calculate_average_temperature();
            control_led(average_temperature);

            printf("Temperature: %.2f °C, Average Temperature: %.2f °C\n", temperature, average_temperature);
        } else {
            fprintf(stderr, "Invalid temperature reading, skipping.\n");
        }

        gpioDelay(1000000); // 1 second delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

