#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// SCD30 I2C address
#define SCD30_I2C_ADDR 0x61

// SCD30 commands
#define SCD30_CMD_START_PERIODIC_MEASUREMENT 0x0010
#define SCD30_CMD_READ_MEASUREMENT 0x0300
#define SCD30_CMD_GET_DATA_READY 0x0202
#define SCD30_CMD_STOP_PERIODIC_MEASUREMENT 0x0104

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float co2;
    float temperature;
    float humidity;
} sensor_data_t;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to write a command to the SCD30
int write_command(int handle, uint16_t command) {
    uint8_t buf[2];
    buf[0] = command >> 8;
    buf[1] = command & 0xFF;
    if (i2cWriteDevice(handle, (char *)buf, 2) != 2) {
        fprintf(stderr, "Error writing command 0x%04X\n", command);
        return -1;
    }
    return 0;
}

// Function to read data from the SCD30
int read_data(int handle, uint8_t *data, int len) {
    if (i2cReadDevice(handle, (char *)data, len) != len) {
        fprintf(stderr, "Error reading data\n");
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(int handle, sensor_data_t *data) {
    uint8_t buffer[18];
    uint32_t co2_raw, temperature_raw, humidity_raw;
    uint8_t co2_crc, temperature_crc, humidity_crc;

    // Poll data ready flag
    if (write_command(handle, SCD30_CMD_GET_DATA_READY) != 0) return -1;
    uint8_t ready_flag[2];
    if (read_data(handle, ready_flag, 2) != 0) return -1;
    if (crc8(ready_flag, 2) != 0) return -1;

    if ((ready_flag[0] & 0x01) == 0) {
        fprintf(stderr, "Data not ready\n");
        return -1;
    }

    // Read measurement data
    if (write_command(handle, SCD30_CMD_READ_MEASUREMENT) != 0) return -1;
    if (read_data(handle, buffer, 18) != 0) return -1;

    // CRC check
    co2_crc = crc8(buffer, 2);
    temperature_crc = crc8(buffer + 6, 2);
    humidity_crc = crc8(buffer + 12, 2);

    if (co2_crc != buffer[2] || temperature_crc != buffer[8] || humidity_crc != buffer[14]) {
        fprintf(stderr, "CRC mismatch\n");
        return -1;
    }

    // Convert raw data to float values
    co2_raw = (buffer[0] << 8) | buffer[1];
    temperature_raw = (buffer[6] << 8) | buffer[7];
    humidity_raw = (buffer[12] << 8) | buffer[13];

    data->co2 = *((float *)&buffer[0]);
    data->temperature = *((float *)&buffer[6]);
    data->humidity = *((float *)&buffer[12]);

    return 0;
}

// Function to log sensor data to a file
int log_data(FILE *file, float co2, float temperature, float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(file, "%s,%.2f,%.2f,%.2f\n", timestamp, co2, temperature, humidity);
    fflush(file);

    return 0;
}

// Function to control ventilation based on CO2 level
void control_ventilation(float co2) {
    if (co2 < 800.0) {
        printf("Ventilation: OFF\n");
    } else if (co2 >= 800.0 && co2 <= 1199.0) {
        printf("Ventilation: LOW\n");
    } else {
        printf("Ventilation: HIGH\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SCD30_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
