#define I2C_BUS 1
#define SDP32_ADDR 0x21
#define MEASURE_CMD_1 0x36
#define MEASURE_CMD_2 0x2F
#define CRC8_POLYNOMIAL 0x31
#define DEFAULT_INTERVAL_MS 1000

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure_pa;
    float temperature_c;
    float scale_factor;
} sensor_data_t;

// Function prototypes
int init_i2c();
int send_command(int handle, uint8_t cmd1, uint8_t cmd2);
int read_data(int handle, char *buffer, int count);
uint8_t calculate_crc(const uint8_t *data, int len);
int verify_crc(const uint8_t *data, int len);
int read_sensor_data(int handle, sensor_data_t *data);
void convert_data(const char *buffer, sensor_data_t *data);
void log_data(const sensor_data_t *data);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC-8 verification function
int verify_crc(const uint8_t *data, int len) {
    uint8_t crc = calculate_crc(data, len);
    return (crc == data[len]);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP32_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

