int read_sensor_data(int handle, sensor_data_t *data) {
    char buffer[9];
    if (read_data(handle, buffer, 9) != 0) {
        return -1;
    }

    if (!verify_crc((uint8_t *)buffer, 2) || !verify_crc((uint8_t *)buffer + 3, 2) || !verify_crc((uint8_t *)buffer + 6, 2)) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }

    convert_data(buffer, data);
    return 0;
}

