    int16_t raw_pressure = (buffer[0] << 8) | buffer[1];
    int16_t raw_temperature = (buffer[3] << 8) | buffer[4];
    int16_t raw_scale_factor = (buffer[6] << 8) | buffer[7];

    data->scale_factor = (float)raw_scale_factor / 65536.0f;
    data->pressure_pa = (float)raw_pressure / data->scale_factor;
    data->temperature_c = (float)raw_temperature / 65536.0f * 200.0f - 45.0f;
}

// Log data to the console
void log_data(const sensor_data_t *data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    printf("%s - Pressure: %.2f Pa, Temperature: %.2f °C, Scale Factor: %.6f\n",
           timestamp, data->pressure_pa, data->temperature_c, data->scale_factor);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int interval_ms = DEFAULT_INTERVAL_MS;

    // Parse command-line arguments
    if (argc > 1) {
        interval_ms = atoi(argv[1]);
        if (interval_ms <= 0) {
            fprintf(stderr, "Invalid interval, using default: %d ms\n", DEFAULT_INTERVAL_MS);
            interval_ms = DEFAULT_INTERVAL_MS;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Send measurement command
    if (send_command(i2c_handle, MEASURE_CMD_1, MEASURE_CMD_2) != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(i2c_handle, &sensor_data) == 0) {
            log_data(&sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }
        gpioDelay(interval_ms * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

