#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASURE_CMD 0x3615
#define CRC_POLY 0x31
#define CRC_INIT 0xFF
#define SCALE_FACTOR_PRESSURE_OFFSET 0
#define SCALE_FACTOR_PRESSURE_LENGTH 2
#define SCALE_FACTOR_TEMP_OFFSET 2
#define SCALE_FACTOR_TEMP_LENGTH 2
#define PRESSURE_OFFSET 4
#define PRESSURE_LENGTH 2
#define TEMPERATURE_OFFSET 6
#define TEMPERATURE_LENGTH 2

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_pigpio();
int open_i2c_bus();
int send_command(int handle, uint16_t command);
int read_data(int handle, char *buffer, int count);
uint8_t calculate_crc(const char *data, int len);
int validate_crc(const char *data, int len);
int read_sensor_data(int handle, sensor_data_t *data);
void convert_data(const char *data, sensor_data_t *converted_data);
void log_data(const sensor_data_t *data);
void signal_handler(int signal);

// CRC-8 calculation function
uint8_t calculate_crc(const char *data, int len) {
    uint8_t crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC validation function
int validate_crc(const char *data, int len) {
    uint8_t crc = calculate_crc(data, len - 1);
    return (crc == data[len - 1]);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus() {
    int handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return -1;
    }
    return handle;
}

// Send command to the sensor
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to send command: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read data from the sensor
int read_data(int handle, char *buffer, int count) {
    int result = i2cReadDevice(handle, buffer, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(int handle, sensor_data_t *data) {
    char buffer[9];
    if (read_data(handle, buffer, 9) != 0) {
        return -1;
    }

    if (!validate_crc(buffer, 3) || !validate_crc(buffer + 3, 3) || !validate_crc(buffer + 6, 3)) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    convert_data(buffer, data);
    return 0;
}

// Convert raw data to physical units
void convert_data(const char *data, sensor_data_t *converted_data) {
    int16_t raw_pressure = (data[PRESSURE_OFFSET] << 8) | data[PRESSURE_OFFSET + 1];
    int16_t raw_temperature = (data[TEMPERATURE_OFFSET] << 8) | data[TEMPERATURE_OFFSET + 1];

