#define CRC_POLY 0x31
#define CRC_INIT 0xFF
#define SCALE_FACTOR_PRESSURE_OFFSET 0
#define SCALE_FACTOR_PRESSURE_LENGTH 2
#define SCALE_FACTOR_TEMP_OFFSET 2
#define SCALE_FACTOR_TEMP_LENGTH 2
#define PRESSURE_OFFSET 4
#define PRESSURE_LENGTH 2
#define TEMPERATURE_OFFSET 6
#define TEMPERATURE_LENGTH 2

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_pigpio();
int open_i2c_bus();
int send_command(int handle, uint16_t command);
int read_data(int handle, char *buffer, int count);
uint8_t calculate_crc(const char *data, int len);
