// HDC1000 I2C address
#define HDC1000_ADDR 0x40

// HDC1000 register addresses
#define TEMPERATURE_REG 0x00
#define HUMIDITY_REG 0x01
#define CONFIGURATION_REG 0x02

// Global variable for I2C handle
int i2c_handle = -1;

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to initialize the HDC1000 sensor
int init_hdc1000() {
    // Configure the sensor for temperature and humidity measurement at 14-bit resolution
    // and enable the measurement mode.
    uint16_t config_value = 0x0000; // Reset value
    config_value |= (1 << 12); // Enable temperature and humidity measurement

    // Write the configuration value to the configuration register
    char buf[3];
    buf[0] = CONFIGURATION_REG;
    buf[1] = (config_value >> 8) & 0xFF; // MSB
    buf[2] = config_value & 0xFF;      // LSB

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to configuration register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read temperature and humidity from the HDC1000 sensor
int read_hdc1000(float *temperature, float *humidity) {
    // Write the temperature register pointer to the sensor
    char reg = TEMPERATURE_REG;
    int result = i2cWriteDevice(i2c_handle, &reg, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to temperature register: %s\n", strerror(errno));
        return -1;
    }

    // Wait for the measurement to complete (at least 20 ms)
    gpioDelay(20000); // 20 ms

    // Read 4 bytes (2 bytes temperature + 2 bytes humidity) from the sensor
    char data[4];
    result = i2cReadDevice(i2c_handle, data, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading data from sensor: %s\n", strerror(errno));
        return -1;
    }

    // Convert the raw data to temperature and humidity
    uint16_t raw_temperature = (data[0] << 8) | data[1];
    uint16_t raw_humidity = (data[2] << 8) | data[3];

    *temperature = ((float)raw_temperature / 65536.0) * 165.0 - 40.0;
    *humidity = ((float)raw_humidity / 65536.0) * 100.0;

    return 0;
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the I2C device
    i2c_handle = i2cOpen(1, HDC1000_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize the HDC1000 sensor
    if (init_hdc1000() != 0) {
        fprintf(stderr, "HDC1000 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        float temperature, humidity;

        // Read temperature and humidity from the sensor
        if (read_hdc1000(&temperature, &humidity) == 0) {
            // Print the temperature and humidity to the console
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read temperature and humidity\n");
        }

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds
    }

    // The following lines will never be reached because of the infinite loop
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

