    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    float temperature;
    time_t rawtime;
    struct tm * timeinfo;

    // Main loop
    while (!terminate) {
        if (read_temperature(i2c_handle, &temperature) == 0) {
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            char timestamp[80];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            printf("%s Temperature: %.2f °C\n", timestamp, temperature);
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
        }

        sleep(SLEEP_SECONDS);
    }

    // Cleanup
    cleanup_i2c();
    gpioTerminate();

    return 0;
}

