// ICP-10101 I2C address
#define ICP10101_ADDR 0x63

// I2C bus
#define I2C_BUS 1

// Calibration data register address
#define CALIB_DATA_ADDR 0x50

// Measurement command
#define MEASURE_CMD 0x40

// Measurement delay (ms)
#define MEASURE_DELAY 7

// Number of calibration coefficients
#define NUM_CALIB_COEFFS 4

// Structure to hold calibration coefficients
typedef struct {
    int16_t T1;
    int16_t T2;
    int16_t T3;
    int16_t P1;
    int16_t P2;
    int16_t P3;
    int16_t P4;
    int16_t P5;
    int16_t P6;
    int16_t P7;
    int16_t P8;
    int16_t P9;
    int16_t P10;
} calibration_data_t;

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_calibration_data(int i2c_handle, calibration_data_t *calib_data);
int trigger_measurement(int i2c_handle);
int read_raw_data(int i2c_handle, int32_t *temperature, int32_t *pressure);
double compensate_temperature(int32_t raw_temperature, const calibration_data_t *calib_data);
double compensate_pressure(int32_t raw_pressure, int32_t raw_temperature, const calibration_data_t *calib_data);
void log_data(double temperature, double pressure);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to read calibration data from the sensor
int read_calibration_data(int i2c_handle, calibration_data_t *calib_data) {
    char buf[24]; // Buffer to hold calibration data (4 coefficients * 6 bytes each)
    int result = i2cReadI2CBlockData(i2c_handle, CALIB_DATA_ADDR, buf, 24);

    if (result < 0) {
        fprintf(stderr, "Error reading calibration data: %d\n", result);
        return -1;
    }

    // Extract calibration coefficients from the buffer
    calib_data->T1 = (int16_t)((buf[0] << 8) | buf[1]);
    calib_data->T2 = (int16_t)((buf[2] << 8) | buf[3]);
    calib_data->T3 = (int16_t)((buf[4] << 8) | buf[5]);
    calib_data->P1 = (int16_t)((buf[6] << 8) | buf[7]);
    calib_data->P2 = (int16_t)((buf[8] << 8) | buf[9]);
    calib_data->P3 = (int16_t)((buf[10] << 8) | buf[11]);
    calib_data->P4 = (int16_t)((buf[12] << 8) | buf[13]);
    calib_data->P5 = (int16_t)((buf[14] << 8) | buf[15]);
    calib_data->P6 = (int16_t)((buf[16] << 8) | buf[17]);
    calib_data->P7 = (int16_t)((buf[18] << 8) | buf[19]);
    calib_data->P8 = (int16_t)((buf[20] << 8) | buf[21]);
    calib_data->P9 = (int16_t)((buf[22] << 8) | buf[23]);

    return 0;
}

// Function to trigger a measurement
int trigger_measurement(int i2c_handle) {
    int result = i2cWriteByteData(i2c_handle, 0x00, MEASURE_CMD);
    if (result < 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read raw temperature and pressure data
int read_raw_data(int i2c_handle, int32_t *temperature, int32_t *pressure) {
    char buf[6];
    int result = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 6);

    if (result < 0) {
        fprintf(stderr, "Error reading raw data: %d\n", result);
        return -1;
    }

    *temperature = (int32_t)((buf[0] << 8) | buf[1]);
    *pressure = (int32_t)((buf[2] << 24) | (buf[3] << 16) | (buf[4] << 8) | buf[5]);

    return 0;
}

// Function to compensate temperature
double compensate_temperature(int32_t raw_temperature, const calibration_data_t *calib_data) {
    double T = (double)raw_temperature;
    double temperature = calib_data->T1 + T * calib_data->T2 + T * T * calib_data->T3;
    return temperature;
}

// Function to compensate pressure
double compensate_pressure(int32_t raw_pressure, int32_t raw_temperature, const calibration_data_t *calib_data) {
    double P = (double)raw_pressure;
    double T = (double)raw_temperature;
    double pressure = calib_data->P1 + P * calib_data->P2 + P * P * calib_data->P3 + P * P * P * calib_data->P4 + P * P * P * P * calib_data->P5 + P * P * P * P * P * calib_data->P6 + P * P * P * P * P * P * calib_data->P7 + P * P * P * P * P * P * P * calib_data->P8 + P * P * P * P * P * P * P * P * calib_data->P9;
    return pressure;
}

// Function to log data with timestamp
void log_data(double temperature, double pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n", timestamp, temperature, pressure);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, ICP10101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    calibration_data_t calib_data;

    // Read calibration data
    if (read_calibration_data(i2c_handle, &calib_data) != 0) {
        fprintf(stderr, "Failed to read calibration data. Exiting.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int32_t raw_temperature, raw_pressure;

        // Trigger measurement
        if (trigger_measurement(i2c_handle) != 0) {
            fprintf(stderr, "Failed to trigger measurement. Continuing.\n");
            continue;
        }

        // Wait for measurement to complete
        gpioDelay(MEASURE_DELAY * 1000); // Convert ms to us

        // Read raw data
        if (read_raw_data(i2c_handle, &raw_temperature, &raw_pressure) != 0) {
            fprintf(stderr, "Failed to read raw data. Continuing.\n");
            continue;
        }

        // Compensate temperature and pressure
        double temperature = compensate_temperature(raw_temperature, &calib_data);
        double pressure = compensate_pressure(raw_pressure, raw_temperature, &calib_data);

        // Log data
        log_data(temperature, pressure);

        // Wait 5 seconds
        sleep(5);
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

