#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define constants
#define I2C_BUS "/dev/i2c-1"
#define MLX90819_ADDR 0x60
#define PRESSURE_MSB_REG 0xAA
#define PRESSURE_LSB_REG 0xAB
#define SCALE_FACTOR 0.1

// Global variables
int i2c_fd = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
float convert_to_kPa(uint16_t raw_pressure);
void log_data(float pressure_kPa);
void signal_handler(int sig);
int setup_i2c();

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, exiting gracefully.\n", sig);
    terminate = 1;
}

// I2C read function
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, data, len) != len) {
        fprintf(stderr, "Error reading data: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// I2C write function
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing data: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Data conversion function
float convert_to_kPa(uint16_t raw_pressure) {
    return (float)raw_pressure * SCALE_FACTOR;
}

// Data logging function
void log_data(float pressure_kPa) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("%s Pressure: %.2f kPa\n", timestamp, pressure_kPa);
}

// I2C setup function
int setup_i2c() {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, MLX90819_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = setup_i2c();
    if (i2c_fd < 0) {
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint8_t data[2];
        uint16_t raw_pressure;

        // Trigger measurement (optional, some sensors may auto-trigger)
        // Example: i2c_write_byte(i2c_fd, 0x00, 0x01); // Replace 0x00 and 0x01 with actual register and value

        // Read pressure data
        if (i2c_read_bytes(i2c_fd, PRESSURE_MSB_REG, data, 2) == 0) {
            raw_pressure = (data[0] << 8) | data[1];
            float pressure_kPa = convert_to_kPa(raw_pressure);
            log_data(pressure_kPa);
        } else {
            fprintf(stderr, "Error reading pressure data.\n");
        }

        sleep(1);
    }

    // Cleanup
    close(i2c_fd);
    return 0;
}

