#define PRESSURE_SCALE_FACTOR 60.0
#define TEMPERATURE_SCALE_FACTOR 200.0
#define LOG_FILE "pressure_log.txt"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_write(int fd, uint8_t address, uint16_t command);
int i2c_read(int fd, uint8_t address, uint8_t *data, int length);
uint8_t crc8(const uint8_t *data, int len);
int validate_crc(uint16_t data, uint8_t crc);
float convert_pressure(int16_t raw_pressure);
float convert_temperature(int16_t raw_temperature);
int log_data(float pressure, float temperature);
void signal_handler(int sig);

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC validation function
int validate_crc(uint16_t data, uint8_t crc) {
    uint8_t crc_calculated = crc8((uint8_t *)&data, 2);
    return (crc_calculated == crc);
}

// I2C write function
int i2c_write(int fd, uint8_t address, uint16_t command) {
    uint8_t buf[3];
    buf[0] = address;
    buf[1] = (command >> 8) & 0xFF;
    buf[2] = command & 0xFF;

    if (write(fd, buf, 3) != 3) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, uint8_t address, uint8_t *data, int length) {
    uint8_t addr = address;
    if (write(fd, &addr, 1) != 1) {
        perror("I2C address write failed");
        return -1;
    }

    if (read(fd, data, length) != length) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

