    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SDP800_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Send continuous measurement command
    if (i2c_write(i2c_fd, SDP800_ADDRESS, MEASURE_COMMAND) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint8_t data[9];
        int16_t raw_pressure, raw_temperature;
        uint8_t crc_pressure, crc_temperature;

