        // Extract raw values and CRCs
        raw_pressure = (data[0] << 8) | data[1];
        crc_pressure = data[2];
        raw_temperature = (data[3] << 8) | data[4];
        crc_temperature = data[5];

        // Validate CRCs
        if (!validate_crc((uint16_t)raw_pressure, crc_pressure) || !validate_crc((uint16_t)raw_temperature, crc_temperature)) {
            fprintf(stderr, "CRC validation failed, retrying...\n");
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        // Convert raw values to physical units
        float pressure = convert_pressure(raw_pressure);
        float temperature = convert_temperature(raw_temperature);

        // Log the data
        if (log_data(pressure, temperature) < 0) {
            fprintf(stderr, "Failed to log data, retrying...\n");
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);
    }

