#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/stat.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SDP800_ADDRESS 0x25
#define MEASURE_COMMAND_1 0x36
#define MEASURE_COMMAND_2 0x2F
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF
#define PRESSURE_SCALE_FACTOR 60.0
#define LOG_FILE "airflow_log.csv"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sdp800(int i2c_handle, int *raw_pressure);
float calculate_pressure(int raw_pressure);
int verify_crc(uint8_t data[], int len, uint8_t checksum);
int log_data(float pressure);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read data from SDP800 sensor
int read_sdp800(int i2c_handle, int *raw_pressure) {
    char buf[3];
    char cmd[2] = {MEASURE_COMMAND_1, MEASURE_COMMAND_2};

    if (i2cWriteDevice(i2c_handle, cmd, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    gpioDelay(8); // Wait for measurement

    if (i2cReadDevice(i2c_handle, buf, 3) != 3) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    uint8_t data[2] = {buf[0], buf[1]};
    uint8_t checksum = buf[2];

    if (!verify_crc(data, 2, checksum)) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }

    *raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

// Calculate pressure in Pascals
float calculate_pressure(int raw_pressure) {
    return (float)raw_pressure / PRESSURE_SCALE_FACTOR;
}

// Verify CRC checksum
int verify_crc(uint8_t data[], int len, uint8_t checksum) {
    uint8_t calculated_crc = crc8(data, len);
    return (calculated_crc == checksum);
}

// Log data to CSV file
int log_data(float pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return -1;
    }

    // Check if the file is empty, if so, write the header
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "Timestamp,Pressure(Pa)\n");
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f\n", timestamp, pressure);
    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int raw_pressure;
    float pressure;

    // Main loop
    while (!terminate) {
        if (read_sdp800(i2c_handle, &raw_pressure) == 0) {
            pressure = calculate_pressure(raw_pressure);
            if (log_data(pressure) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

