#include <signal.h>
#include <unistd.h>
#include <sys/stat.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define HIH6130_ADDR 0x27
#define MEASUREMENT_COMMAND 0x00
#define LOG_FILE "environmental_data.log"
#define LOG_FILE_SIZE_LIMIT 1048576 // 1 MB

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_sensor_data(uint16_t *raw_temperature, uint16_t *raw_humidity);
float convert_temperature(uint16_t raw_temperature);
float convert_humidity(uint16_t raw_humidity);
int log_data(float temperature, float humidity);
void signal_handler(int signal);
int truncate_log_file(const char *filename, size_t max_size);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, HIH6130_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Reads temperature and humidity data from the sensor
int read_sensor_data(uint16_t *raw_temperature, uint16_t *raw_humidity) {
    char buf[4];
    int result;

    // Trigger measurement
    result = i2cWriteByte(i2c_handle, MEASUREMENT_COMMAND);
    if (result != 0) {
        fprintf(stderr, "Error writing measurement command: %d\n", result);
        return -1;
    }

    // Wait for measurement to complete (at least 40ms)
    gpioDelay(50000); // 50ms

    // Read 4 bytes of data
    result = i2cReadDevice(i2c_handle, buf, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    // Validate status bits
    uint8_t status = (buf[0] >> 6) & 0x03;
    if (status != 0) {
        fprintf(stderr, "Error: Invalid status bits (0x%02X)\n", status);
        return -1;
    }

    // Extract raw temperature and humidity values
    *raw_humidity = ((uint16_t)buf[0] & 0x3F) << 8 | (uint16_t)buf[1];
    *raw_temperature = ((uint16_t)buf[2] << 6) | ((uint16_t)buf[3] >> 2);

    return 0;
}

// Converts raw temperature data to Celsius
float convert_temperature(uint16_t raw_temperature) {
    return (float)raw_temperature * 165.0 / 16383.0 - 40.0;
}

// Converts raw humidity data to percentage relative humidity
float convert_humidity(uint16_t raw_humidity) {
    return (float)raw_humidity * 100.0 / 16383.0;
}

// Logs temperature and humidity data to a file with ISO-8601 timestamp
int log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
    fclose(fp);

    return 0;
}

// Truncates the log file if it exceeds the specified size
int truncate_log_file(const char *filename, size_t max_size) {
    struct stat st;
    if (stat(filename, &st) == 0) {
        if (st.st_size > max_size) {
            FILE *fp = fopen(filename, "w");
            if (fp == NULL) {
                fprintf(stderr, "Error opening log file for truncation: %s\n", filename);
                return -1;
            }
            fclose(fp);
            printf("Log file truncated.\n");
        }
    } else {
        fprintf(stderr, "Error getting log file size: %s\n", filename);
        return -1;
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint16_t raw_temperature, raw_humidity;

        // Read sensor data
        if (read_sensor_data(&raw_temperature, &raw_humidity) == 0) {
            // Convert data
            float temperature = convert_temperature(raw_temperature);
            float humidity = convert_humidity(raw_humidity);

            // Log data
            if (log_data(temperature, humidity) != 0) {
                fprintf(stderr, "Error logging data\n");
            }

            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Truncate log file
        if (truncate_log_file(LOG_FILE, LOG_FILE_SIZE_LIMIT) != 0) {
            fprintf(stderr, "Error truncating log file\n");
        }

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds
    }

    // Close I2C connection and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

