#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Configuration
#define GPIO_PIN 4
#define TICK_TIME_US 3
#define SYNC_PULSE_TICKS 56
#define NIBBLE_MIN_TICKS (36 * TICK_TIME_US)
#define NIBBLE_MAX_TICKS (813 * TICK_TIME_US)
#define CHECKSUM_ERROR -1
#define TIMEOUT_ERROR -2
#define BUS_ERROR -3

// Calibration parameters (replace with actual values from datasheet)
#define SCALE 0.1  // Example scale factor
#define OFFSET 0.0 // Example offset

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold sensor data
typedef struct {
    int status;
    int data[3];
    int checksum;
} SENTData;

// Function prototypes
int initialize_gpio();
SENTData read_sent_data();
int validate_checksum(SENTData data);
float convert_to_pressure(int raw_value);
void log_pressure(float pressure);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP); // Enable pull-up resistor

    return 0;
}

// Function to read SENT data
SENTData read_sent_data() {
    SENTData data = {0, {0, 0, 0}, 0};
    int i, j;
    int tick;

    // Wait for the start of the sync pulse
    while (gpioRead(GPIO_PIN) == 1 && running) {
        gpioDelay(1000); // Wait 1ms
    }

    if (!running) return data; // Exit if signal received

    // Read sync pulse
    tick = gpioTick();
    while (gpioRead(GPIO_PIN) == 0 && running) {
        gpioDelay(1000); // Wait 1ms
    }
    if (!running) return data;
    int sync_pulse_ticks = gpioTick() - tick;

    if (sync_pulse_ticks < (SYNC_PULSE_TICKS * 0.8) || sync_pulse_ticks > (SYNC_PULSE_TICKS * 1.2)) {
        fprintf(stderr, "Error: Invalid sync pulse width: %d ticks\n", sync_pulse_ticks);
        data.status = BUS_ERROR;
        return data;
    }

    // Read status nibble
    data.status = 0;
    for (i = 0; i < 4; i++) {
        tick = gpioTick();
        while (gpioRead(GPIO_PIN) == 1 && running) {
            gpioDelay(1000); // Wait 1ms
        }
        if (!running) return data;
        int pulse_width = gpioTick() - tick;

        if (pulse_width < NIBBLE_MIN_TICKS || pulse_width > NIBBLE_MAX_TICKS) {
            fprintf(stderr, "Error: Invalid status nibble pulse width: %d ticks\n", pulse_width);
            data.status = BUS_ERROR;
            return data;
        }

        data.status <<= 4;
        data.status |= (pulse_width / (NIBBLE_MAX_TICKS / 15)); // Approximate conversion to 4-bit value
    }

    // Read data nibbles
    for (i = 0; i < 3; i++) {
        data.data[i] = 0;
        for (j = 0; j < 4; j++) {
            tick = gpioTick();
            while (gpioRead(GPIO_PIN) == 1 && running) {
                gpioDelay(1000); // Wait 1ms
            }
            if (!running) return data;
            int pulse_width = gpioTick() - tick;

            if (pulse_width < NIBBLE_MIN_TICKS || pulse_width > NIBBLE_MAX_TICKS) {
                fprintf(stderr, "Error: Invalid data nibble pulse width: %d ticks\n", pulse_width);
                data.status = BUS_ERROR;
                return data;
            }

            data.data[i] <<= 4;
