#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define DEVICE_ID_REG 0x06
#define TEMPERATURE_REG 0x00
#define TEMPERATURE_SCALE 0.0078125
#define FILENAME "greenhouse_temps.dat"

// Global variables
int i2c_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int verify_device_id();
float read_temperature();
int write_temperature_to_file(float temperature);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Verify device ID
int verify_device_id() {
    int id = i2cReadWordData(i2c_handle, DEVICE_ID_REG);
    if (id < 0) {
        fprintf(stderr, "Error reading device ID: %d\n", id);
        return -1;
    }
    if (id != 0x0117) {
        fprintf(stderr, "Error: Invalid device ID: 0x%X\n", id);
        return -1;
    }
    printf("Device ID verified: 0x%X\n", id);
    return 0;
}

// Read temperature from sensor
float read_temperature() {
    int raw_temp = i2cReadWordData(i2c_handle, TEMPERATURE_REG);
    if (raw_temp < 0) {
        fprintf(stderr, "Error reading temperature: %d\n", raw_temp);
        return -1000.0; // Indicate error with a very low temperature
    }
    // Convert to signed 16-bit integer
    int16_t signed_temp = (int16_t)raw_temp;
    return signed_temp * TEMPERATURE_SCALE;
}

// Write temperature to file
int write_temperature_to_file(float temperature) {
    uint32_t temp_float = *(uint32_t*)&temperature; // Cast float to uint32_t
    if (fwrite(&temp_float, sizeof(uint32_t), 1, fp) != 1) {
        fprintf(stderr, "Error writing to file\n");
        return -1;
    }
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Verify device ID
    if (verify_device_id() != 0) {
        cleanup();
        return 1;
    }

    // Open file for writing
    fp = fopen(FILENAME, "ab");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();
        if (temperature > -999.0) { // Check for read error
            if (write_temperature_to_file(temperature) != 0) {
                fprintf(stderr, "Error writing temperature to file, exiting\n");
                break;
            }
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Error reading temperature, retrying in 60 seconds\n");
        }

        sleep(60);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

