#define CRC8_INITIAL_VALUE 0xFF
#define LOG_FILE "environmental_data.txt"

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int open_i2c_bus();
int send_command(int handle, uint8_t command);
int read_data(int handle, uint8_t *data, int count);
uint8_t calculate_crc(const uint8_t *data, int len);
int validate_crc(const uint8_t *data, int len);
int read_sensor_data(int handle, float *temperature, float *humidity);
int log_data(float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC-8 validation function
int validate_crc(const uint8_t *data, int len) {
    uint8_t crc = calculate_crc(data, len - 1);
    return (crc == data[len - 1]);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus() {
    int handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return -1;
    }
    return handle;
}

// Send command to the sensor
int send_command(int handle, uint8_t command) {
    int result = i2cWriteByteData(handle, command, 0); // SHT40 doesn't use register address
    if (result < 0) {
        fprintf(stderr, "Failed to send command: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read data from the sensor
int read_data(int handle, uint8_t *data, int count) {
    int bytes_read = i2cReadI2CBlockData(handle, 0, (char *)data, count); // SHT40 doesn't use register address
    if (bytes_read < 0) {
        fprintf(stderr, "Failed to read data: %s\n", strerror(errno));
        return -1;
    }
    return bytes_read;
}

// Read sensor data
int read_sensor_data(int handle, float *temperature, float *humidity) {
    uint8_t data[6];

    if (send_command(handle, MEASURE_HIGH_PRECISION) < 0) {
        return -1;
    }

    gpioDelay(10); // Wait for conversion (at least 8.5 ms)

    if (read_data(handle, data, 6) < 0) {
        return -1;
    }

    if (!validate_crc(data, 3) || !validate_crc(data + 3, 3)) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    uint16_t raw_temp = (data[0] << 8) | data[1];
    uint16_t raw_hum = (data[3] << 8) | data[4];

    *temperature = -45.0 + 175.0 * (raw_temp / 65535.0);
    *humidity = -6.0 + 125.0 * (raw_hum / 65535.0);

    return 0;
}

// Log data to file
int log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
            return -1;
        }
    }

    fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%RH\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() < 0) {
        return 1;
    }

    // Open I2C bus
    i2c_handle = open_i2c_bus();
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    float temperature, humidity;

    while (!terminate) {
        if (read_sensor_data(i2c_handle, &temperature, &humidity) == 0) {
            if (log_data(temperature, humidity) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

