#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// SHTC3 I2C address
#define SHTC3_ADDR 0x70

// SHTC3 measurement command (normal power, clock stretching disabled)
#define SHTC3_MEASURE_CMD 0x7866

// CRC-8 polynomial
#define CRC8_POLYNOMIAL 0x31

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c();
int send_command(int handle, uint16_t command);
int read_data(int handle, uint8_t *data, int count);
uint8_t calculate_crc(const uint8_t *data, int len);
int validate_data(const uint8_t *data);
sensor_data_t convert_data(const uint8_t *data);
int log_data(sensor_data_t data);
void print_data(sensor_data_t data);
void error_handler(const char *message);
void signal_handler(int signal);

// CRC-8 calculation function
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, SHTC3_ADDR, 0); // Bus 1, address 0x70, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to send a command to the SHTC3
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read data from the SHTC3
int read_data(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to validate the data using CRC-8
int validate_data(const uint8_t *data) {
    uint8_t temp_crc = calculate_crc(data, 2);
    if (temp_crc != data[2]) {
        fprintf(stderr, "Temperature CRC check failed!\n");
        return -1;
    }

    uint8_t humidity_crc = calculate_crc(data + 3, 2);
    if (humidity_crc != data[5]) {
        fprintf(stderr, "Humidity CRC check failed!\n");
        return -1;
    }

    return 0;
}

// Function to convert raw data to temperature and humidity
sensor_data_t convert_data(const uint8_t *data) {
    sensor_data_t result;
    uint16_t temp_raw = (data[0] << 8) | data[1];
    uint16_t humidity_raw = (data[3] << 8) | data[4];

    result.temperature = 175.0 * temp_raw / 65535.0 - 45.0;
    result.humidity = 100.0 * humidity_raw / 65535.0;

    return result;
}

// Function to log the data to a file
int log_data(sensor_data_t data) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Function to print the data to stdout
void print_data(sensor_data_t data) {
    printf("Temperature: %.2f C, Humidity: %.2f %%\n", data.temperature, data.humidity);
}

// Function to handle errors
void error_handler(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("shtc3_environment.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t data[6];
    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Send measurement command
        if (send_command(i2c_handle, SHTC3_MEASURE_CMD) != 0) {
            error_handler("Failed to send measurement command");
        } else {
            // Wait for conversion (minimum 12.4 ms)
            gpioDelay(15000); // 15 ms

            // Read data
            if (read_data(i2c_handle, data, 6) != 0) {
                error_handler("Failed to read data");
            } else {
                // Validate data
                if (validate_data(data) == 0) {
                    // Convert data
                    sensor_data = convert_data(data);

                    // Validate temperature and humidity range
                    if (sensor_data.temperature >= -40.0 && sensor_data.temperature <= 125.0 &&
                        sensor_data.humidity >= 0.0 && sensor_data.humidity <= 100.0) {
                        // Log data
                        log_data(sensor_data);

                        // Print data
                        print_data(sensor_data);
                    } else {
                        fprintf(stderr, "Temperature or humidity out of range!\n");
                    }
                }
            }
        }

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds
    }

    // Close I2C connection and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

