                    }
                }
            }
        }

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds
    }

    // Close I2C connection and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

