#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SI7202_ADDR 0x40
#define MAG_DATA_REG 0x00 // Example register, adjust as needed
#define TEMP_DATA_REG 0x02 // Example register, adjust as needed
#define LOG_FILE "mag_temp_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float magnetic_field;
    float temperature;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(int handle, int *magnetic_field_raw, int *temperature_raw);
sensor_data_t convert_data(int magnetic_field_raw, int temperature_raw);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// I2C initialization function
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7202_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(int handle, int *magnetic_field_raw, int *temperature_raw) {
    char buf[4]; // Assuming 2 bytes for magnetic field and 2 for temperature
    int bytes_read;

    bytes_read = i2cReadI2CBlockData(handle, MAG_DATA_REG, buf, 2); // Read magnetic field data
    if (bytes_read != 2) {
        fprintf(stderr, "Failed to read magnetic field data: %s\n", strerror(errno));
        return -1;
    }
    *magnetic_field_raw = (buf[0] << 8) | buf[1]; // Combine bytes

    bytes_read = i2cReadI2CBlockData(handle, TEMP_DATA_REG, buf + 2, 2); // Read temperature data
    if (bytes_read != 2) {
        fprintf(stderr, "Failed to read temperature data: %s\n", strerror(errno));
        return -1;
    }
    *temperature_raw = (buf[2] << 8) | buf[3]; // Combine bytes

    return 0;
}

// Function to convert raw data to physical units
sensor_data_t convert_data(int magnetic_field_raw, int temperature_raw) {
    sensor_data_t data;
    data.magnetic_field = magnetic_field_raw * 0.1;
    data.temperature = temperature_raw * 0.01 - 25.0;
    return data;
}

// Function to log data to a file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.magnetic_field, data.temperature);
    fflush(log_file); // Ensure data is written immediately

    return 0;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Magnetic Field (Gauss),Temperature (Celsius)\n");
    }
    rewind(log_file);

    int magnetic_field_raw, temperature_raw;
    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(i2c_handle, &magnetic_field_raw, &temperature_raw) == 0) {
            sensor_data = convert_data(magnetic_field_raw, temperature_raw);
            if (log_data(sensor_data) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            // Log NaN values if read fails
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[64];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
            fprintf(log_file, "%s,NaN,NaN\n", timestamp);
            fflush(log_file);
            fprintf(stderr, "Failed to read sensor data, logging NaN values\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

