#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define TEMP_SCALE 0.0078125
#define LOG_FILE "temperature_log.txt"
#define MAX_REINIT_ATTEMPTS 3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_temperature(int i2c_handle, float *temperature);
int log_temperature(float temperature, const char *filename);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        terminate = 1;
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
    }
}

// Function to read temperature from TMP117
int read_temperature(int i2c_handle, float *temperature) {
    char buf[2];
    int16_t raw_temp;
    int result;

    result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature: %d\n", result);
        return -1;
    }

    raw_temp = (buf[0] << 8) | buf[1];
    *temperature = raw_temp * TEMP_SCALE;

    return 0;
}

// Function to log temperature to file
int log_temperature(float temperature, const char *filename) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    FILE *fp;

    fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", filename);
        return -1;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Temperature: %.4f C\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, temperature);

    fclose(fp);
    return 0;
}

int main() {
    float temperature;
    int reinit_attempts = 0;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Attempt to open I2C bus
        i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
        if (i2c_handle < 0) {
            fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
            reinit_attempts++;
            if (reinit_attempts > MAX_REINIT_ATTEMPTS) {
                fprintf(stderr, "Max reinitialization attempts reached. Exiting.\n");
                break;
            }
            gpioDelay(1000); // Wait before retrying
            continue;
        }
        reinit_attempts = 0; // Reset reinit attempts on success

        // Read temperature
        if (read_temperature(i2c_handle, &temperature) == 0) {
            // Log temperature
            if (log_temperature(temperature, LOG_FILE) != 0) {
                fprintf(stderr, "Error logging temperature\n");
            }
        } else {
            fprintf(stderr, "Error reading temperature\n");
        }

        i2cClose(i2c_handle);
        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return 0;
}

