#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x49
#define LOG_FILE "flow_log.txt"
#define NUM_STALE_READS 2

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float flow_rate;
    float temperature;
} SensorData;

// Function prototypes
int initialize_i2c();
int read_sensor_data(uint8_t *data);
SensorData convert_data(uint8_t *data);
int log_data(SensorData data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(uint8_t *data) {
    int bytes_read = i2cReadDevice(i2c_handle, (char *)data, 4);
    if (bytes_read != 4) {
        fprintf(stderr, "Error reading I2C data: %d\n", bytes_read);
        return -1;
    }
    return 0;
}

// Function to convert raw data to flow rate and temperature
SensorData convert_data(uint8_t *data) {
    SensorData sensor_data;
    int16_t raw_flow = (data[0] << 8) | data[1];
    int16_t raw_temp = (data[2] << 8) | data[3];

    sensor_data.flow_rate = ((float)raw_flow / 16384.0 - 0.1) / 0.8 * 25.0;
    sensor_data.temperature = ((float)raw_temp / 4096.0 - 0.1) / 0.8 * 80.0 - 40.0;

    return sensor_data;
}

// Function to log data to file
int log_data(SensorData data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Flow: %.2f SLPM, Temperature: %.2f °C\n", timestamp, data.flow_rate, data.temperature);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Function to cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed\n");
        cleanup();
        return 1;
    }

    uint8_t stale_data[4];
    for (int i = 0; i < NUM_STALE_READS; i++) {
        if (read_sensor_data(stale_data) != 0) {
            fprintf(stderr, "Failed to read stale data, attempt %d\n", i + 1);
            i2cClose(i2c_handle);
            gpioDelay(1000); // Wait before re-initializing
            if (initialize_i2c() != 0) {
                fprintf(stderr, "I2C re-initialization failed\n");
                cleanup();
                return 1;
            }
        } else {
            fprintf(stderr, "Successfully read stale data, attempt %d\n", i + 1);
        }
        gpioDelay(100); // Small delay between stale reads
    }

    uint8_t sensor_data[4];
    SensorData data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(sensor_data) == 0) {
            data = convert_data(sensor_data);
            log_data(data);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
            i2cClose(i2c_handle);
            gpioDelay(1000); // Wait before re-initializing
            if (initialize_i2c() != 0) {
                fprintf(stderr, "I2C re-initialization failed\n");
                cleanup();
                return 1;
            }
        }
        gpioDelay(1000); // Sample every 1 second
    }

    // Cleanup resources before exiting
    cleanup();
    return 0;
}

