    gpioSetMode(DHT11_GPIO, PI_INPUT);

    // Read response signal (80 us low, 80 us high)
    unsigned int start_time = gpioTick();
    while (gpioRead(DHT11_GPIO) == 1) {
        if (gpioTick() - start_time > 100000) { // Timeout after 100 ms
            log_error("DHT11 response timeout", -1);
            return data; // Return default values on timeout
        }
