#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <sys/time.h>

// Constants
#define I2C_BUS 1
#define LM75B_ADDR 0x48
#define TEMP_REG 0x00
#define FAN_GPIO 18
#define TEMP_THRESHOLD_ON 28.0
#define TEMP_THRESHOLD_OFF 26.0
#define BUFFER_SIZE 60

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
float read_temperature();
void update_circular_buffer(float temperature);
float calculate_running_average();
void control_fan(float average_temperature);
void signal_handler(int signal);
void log_message(const char *message);

// Function to read temperature from LM75B
float read_temperature() {
    int raw_data;
    float temperature;

    raw_data = i2cReadWordData(i2c_handle, TEMP_REG);
    if (raw_data < 0) {
        log_message("Error reading temperature from I2C.");
        return -100.0; // Indicate error
    }

    // Convert raw data to temperature (signed 9-bit format)
    int16_t signed_data = (int16_t)raw_data;
    signed_data = signed_data >> 8; // Shift to get the 9-bit value
    signed_data = signed_data << 7; // Shift back to get the sign bit
    signed_data = signed_data >> 7; // Sign extend

    temperature = signed_data * 0.5;

    return temperature;
}

// Function to update the circular buffer
void update_circular_buffer(float temperature) {
    temperature_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to calculate the running average
float calculate_running_average() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += temperature_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Function to control the cooling fan
void control_fan(float average_temperature) {
    static int fan_on = 0; // Track fan state

    if (average_temperature > TEMP_THRESHOLD_ON && !fan_on) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
        fan_on = 1;
        log_message("Fan turned ON");
    } else if (average_temperature < TEMP_THRESHOLD_OFF && fan_on) {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
        fan_on = 0;
        log_message("Fan turned OFF");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    log_message("Signal received, shutting down...");
    terminate = 1;
}

// Function to log messages with timestamps
void log_message(const char *message) {
    struct timeval tv;
    struct tm *tm_info;
    char timestamp[26];

    gettimeofday(&tv, NULL);
    tm_info = localtime(&tv.tv_sec);

    strftime(timestamp, 26, "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(stderr, "%s.%06ld: %s\n", timestamp, tv.tv_usec, message);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, LM75B_ADDR, 0);
    if (i2c_handle < 0) {
        log_message("Error opening I2C bus.");
        gpioTerminate();
        return 1;
    }

    // Set FAN_GPIO as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Initialize circular buffer with 0.0
    for (int i = 0; i < BUFFER_SIZE; i++) {
        temperature_buffer[i] = 0.0;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_message("Temperature monitoring and fan control started.");

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();
        if (temperature > -99.0) { // Check for valid temperature reading
            update_circular_buffer(temperature);
            float average_temperature = calculate_running_average();
            control_fan(average_temperature);
            printf("Temperature: %.2f °C, Average: %.2f °C\n", temperature, average_temperature);
        } else {
            log_message("Failed to read temperature, skipping fan control.");
        }

        time_sleep(1.0);
    }

    // Cleanup
    gpioWrite(FAN_GPIO, 0); // Turn off fan
    i2cClose(i2c_handle); // Close I2C bus
    gpioTerminate(); // Terminate pigpio

    log_message("Temperature monitoring and fan control stopped.");

    return 0;
}

