#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <time.h>

// Constants
#define I2C_DEVICE "/dev/i2c-1"
#define STTS2004_ADDR 0x4A
#define TEMP_REG 0x00
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 27.0
#define RETRY_COUNT 3

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_byte(int fd, uint8_t reg);
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int i2c_open(const char *device);
void i2c_close(int fd);
int gpio_open_chip(const char *chipname);
void gpio_close_chip(struct gpiod_chip *chip);
int gpio_open_line(struct gpiod_chip *chip, int pin);
void gpio_close_line(struct gpiod_line *line);
int gpio_set_value(struct gpiod_line *line, int value);
float read_temperature();
void control_led(float temperature);
void signal_handler(int sig);

// I2C read byte function
int i2c_read_byte(int fd, uint8_t reg) {
    int result;
    for (int i = 0; i < RETRY_COUNT; ++i) {
        if (write(fd, &reg, 1) != 1) {
            perror("Failed to write register address");
            continue;
        }
        if (read(fd, &result, 1) == 1) {
            return result;
        } else {
            perror("Failed to read byte");
        }
    }
    fprintf(stderr, "I2C read failed after %d retries\n", RETRY_COUNT);
    return -1; // Indicate failure
}

// I2C write byte function
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    for (int i = 0; i < RETRY_COUNT; ++i) {
        if (write(fd, buf, 2) == 2) {
            return 0; // Success
        } else {
            perror("Failed to write byte");
        }
    }
    fprintf(stderr, "I2C write failed after %d retries\n", RETRY_COUNT);
    return -1; // Indicate failure
}

// I2C open function
int i2c_open(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }
    return fd;
}

// I2C close function
void i2c_close(int fd) {
    close(fd);
}

// GPIO open chip function
int gpio_open_chip(const char *chipname) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name(chipname);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }
    return 0;
}

// GPIO close chip function
void gpio_close_chip(struct gpiod_chip *chip) {
    gpiod_chip_close(chip);
}

// GPIO open line function
int gpio_open_line(struct gpiod_chip *chip, int pin) {
    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("Failed to get GPIO line");
        return -1;
    }
    return 0;
}

// GPIO close line function
void gpio_close_line(struct gpiod_line *line) {
    gpiod_line_release(line);
}

// GPIO set value function
int gpio_set_value(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        perror("Failed to set GPIO value");
        return -1;
    }
    return 0;
}

// Read temperature from STTS2004
float read_temperature() {
    int msb, lsb;
    int16_t raw_temp;

    msb = i2c_read_byte(i2c_fd, TEMP_REG);
    if (msb < 0) return -273.15; // Return absolute zero on error

    lsb = i2c_read_byte(i2c_fd, TEMP_REG + 1);
    if (lsb < 0) return -273.15; // Return absolute zero on error

    raw_temp = (msb << 8) | lsb;
    raw_temp = raw_temp >> 4; // Right shift by 4 bits

    return raw_temp * 0.0625;
}

// Control LED based on temperature
void control_led(float temperature) {
    if (temperature > TEMP_THRESHOLD_HIGH) {
        if (gpio_set_value(gpio_line, 1) != 0) {
            fprintf(stderr, "Failed to turn LED on\n");
        }
    } else if (temperature < TEMP_THRESHOLD_LOW) {
        if (gpio_set_value(gpio_line, 0) != 0) {
            fprintf(stderr, "Failed to turn LED off\n");
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting gracefully...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = i2c_open(I2C_DEVICE);
    if (i2c_fd < 0) {
        return 1;
    }

    // Initialize GPIO
    if (gpio_open_chip(GPIO_CHIP) != 0) {
        i2c_close(i2c_fd);
        return 1;
    }
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);

    if (gpio_open_line(gpio_chip, GPIO_PIN) != 0) {
        gpio_close_chip(gpio_chip);
        i2c_close(i2c_fd);
        return 1;
    }
    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);

    if (gpiod_line_request_output(gpio_line, "temperature_control", 0) != 0) {
        fprintf(stderr, "Failed to request GPIO line for output\n");
        gpio_close_line(gpio_line);
        gpio_close_chip(gpio_chip);
        i2c_close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();
        if (temperature > -273.0) {
            printf("Temperature: %.2f °C\n", temperature);
            control_led(temperature);
        } else {
            fprintf(stderr, "Failed to read temperature\n");
        }
        sleep(1);
    }

    // Cleanup
    gpio_set_value(gpio_line, 0); // Turn LED off
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);
    i2c_close(i2c_fd);

    return 0;
}

