#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define MEASURE_HUMIDITY 0xF5
#define MEASURE_TEMPERATURE 0xF3
#define RETRY_COUNT 3
#define SAMPLE_INTERVAL 60 // seconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(uint16_t *humidity, uint16_t *temperature);
float convert_temperature(uint16_t raw_temperature);
float convert_humidity(uint16_t raw_humidity);
void log_data(float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("environment.log", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        uint16_t raw_humidity, raw_temperature;
        sensor_data_t data;

        // Read sensor data
        if (read_sensor_data(&raw_humidity, &raw_temperature) == 0) {
            // Convert data
            data.temperature = convert_temperature(raw_temperature);
            data.humidity = convert_humidity(raw_humidity);

            // Log data
            log_data(data.temperature, data.humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
            fprintf(log_file, "Failed to read sensor data\n");
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Read sensor data with retries
int read_sensor_data(uint16_t *humidity, uint16_t *temperature) {
    char buf[2];
    int result;

    // Measure Humidity
    result = i2cWriteByte(i2c_handle, MEASURE_HUMIDITY);
    if (result != 0) {
        fprintf(stderr, "Error writing humidity command: %d\n", result);
        return 1;
    }
    gpioDelay(20); // Wait 20ms

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading humidity data: %d\n", result);
        return 1;
    }
    *humidity = (buf[0] << 8) | buf[1];

    // Measure Temperature
    result = i2cWriteByte(i2c_handle, MEASURE_TEMPERATURE);
    if (result != 0) {
        fprintf(stderr, "Error writing temperature command: %d\n", result);
        return 1;
    }
    gpioDelay(20); // Wait 20ms

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature data: %d\n", result);
        return 1;
    }
    *temperature = (buf[0] << 8) | buf[1];

    return 0;
}

// Convert raw temperature to Celsius
float convert_temperature(uint16_t raw_temperature) {
    return 175.72 * raw_temperature / 65536.0 - 46.85;
}

// Convert raw humidity to percentage
float convert_humidity(uint16_t raw_humidity) {
    float humidity = 125.0 * raw_humidity / 65536.0 - 6.0;
    if (humidity < 0.0) humidity = 0.0;
    if (humidity > 100.0) humidity = 100.0;
    return humidity;
}

// Log data to file and stdout
void log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(stdout, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(stdout);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

