#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// HDC1080 I2C address
#define HDC1080_ADDR 0x40

// HDC1080 register addresses
#define HDC1080_TEMP_REG 0x00
#define HDC1080_HUMID_REG 0x01
#define HDC1080_CONFIG_REG 0x02

// Global variables for I2C handle and program state
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c();
int configure_hdc1080();
int read_hdc1080(float *temperature, float *humidity);
int log_data(float temperature, float humidity);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C bus
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, HDC1080_ADDR, 0); // I2C bus 1, address 0x40, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Configure HDC1080 sensor
int configure_hdc1080() {
    // Configuration register value: 0x0000 (default)
    // This sets 14-bit temperature and humidity resolution, and disables heater
    uint16_t config_value = 0x0000;

    // Write the configuration value to the configuration register
    char buf[3];
    buf[0] = HDC1080_CONFIG_REG;
    buf[1] = (config_value >> 8) & 0xFF; // MSB
    buf[2] = config_value & 0xFF;        // LSB

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Failed to write to configuration register: %d\n", result);
        return -1;
    }

    return 0;
}

// Read temperature and humidity from HDC1080
int read_hdc1080(float *temperature, float *humidity) {
    // Trigger measurement by writing to temperature register
    char trigger_buf[1];
    trigger_buf[0] = HDC1080_TEMP_REG;

    int result = i2cWriteDevice(i2c_handle, trigger_buf, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to trigger measurement: %d\n", result);
        return -1;
    }

    // Wait for conversion (at least 20 ms)
    gpioDelay(20000); // 20 ms

    // Read 4 bytes (2 for temperature, 2 for humidity)
    char read_buf[4];
    result = i2cReadDevice(i2c_handle, read_buf, 4);
    if (result != 4) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }

    // Convert raw values to temperature and humidity
    uint16_t raw_temp = (read_buf[0] << 8) | read_buf[1];
    uint16_t raw_humidity = (read_buf[2] << 8) | read_buf[3];

    *temperature = ((float)raw_temp / 65536.0) * 165.0 - 40.0;
    *humidity = ((float)raw_humidity / 65536.0) * 100.0;

    return 0;
}

// Log data to file
int log_data(float temperature, float humidity) {
    FILE *fp = fopen("enviro_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(fp);

    return 0;
}

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Configure HDC1080
    if (configure_hdc1080() != 0) {
