#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Constants
#define I2C_DEVICE "/dev/i2c-1"
#define STS40_ADDR 0x44
#define MEASURE_CMD_HIGH 0x2C
#define MEASURE_CMD_LOW 0xE0
#define CRC8_POLYNOMIAL 0x31
#define LOG_FILE "temperature_log.txt"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;

// Function prototypes
int i2c_open(const char *device);
int i2c_set_slave_address(int fd, int address);
int i2c_write(int fd, const unsigned char *data, int len);
int i2c_read(int fd, unsigned char *data, int len);
unsigned char crc8(const unsigned char *data, int len);
float convert_to_celsius(unsigned int raw_temperature);
int log_temperature(float temperature);
void signal_handler(int signal);

// I2C open function
int i2c_open(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C device %s: %s\n", device, strerror(errno));
        return -1;
    }
    return fd;
}

// I2C set slave address function
int i2c_set_slave_address(int fd, int address) {
    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", address, strerror(errno));
        return -1;
    }
    return 0;
}

// I2C write function
int i2c_write(int fd, const unsigned char *data, int len) {
    int bytes_written = write(fd, data, len);
    if (bytes_written != len) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, unsigned char *data, int len) {
    int bytes_read = read(fd, data, len);
    if (bytes_read != len) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// CRC8 calculation function
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Temperature conversion function
float convert_to_celsius(unsigned int raw_temperature) {
    return -45.0 + 175.0 * (float)raw_temperature / 65535.0;
}

// Logging function
int log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
            return -1;
        }
    }

    fprintf(log_file, "%s, %.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = i2c_open(I2C_DEVICE);
    if (i2c_fd < 0) {
        return 1;
    }

    // Set I2C slave address
    if (i2c_set_slave_address(i2c_fd, STS40_ADDR) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Send measurement command
        unsigned char cmd[2] = {MEASURE_CMD_HIGH, MEASURE_CMD_LOW};
        if (i2c_write(i2c_fd, cmd, 2) < 0) {
            fprintf(stderr, "Error sending measurement command, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Wait for conversion (10 ms)
        usleep(10000); // 10 ms

        // Read data
        unsigned char data[6];
        if (i2c_read(i2c_fd, data, 6) < 0) {
            fprintf(stderr, "Error reading data, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // CRC validation
        if (crc8(data, 2) != data[2] || crc8(data + 3, 2) != data[5]) {
            fprintf(stderr, "CRC validation failed, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Convert to Celsius
        unsigned int raw_temperature = (data[0] << 8) | data[1];
        float temperature = convert_to_celsius(raw_temperature);

        // Log temperature
        if (log_temperature(temperature) < 0) {
            fprintf(stderr, "Error logging temperature, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Wait 5 seconds
        sleep(5);
    }

    return 0;
}

