#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define CONTINUOUS_MEASUREMENT_CMD 0x3615
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF
#define LOG_FILE "hvac_pressure_log.txt"

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int send_command(int handle, uint16_t command);
int read_data(int handle, char *buffer, int count);
uint8_t calculate_crc(const char *data, int len);
int validate_crc(const char *data, int len);
float convert_pressure(int16_t raw_pressure, int16_t scale_factor);
float convert_temperature(int16_t raw_temperature);
int log_data(float pressure, float temperature);
void signal_handler(int signal);

// CRC-8 calculation function
uint8_t calculate_crc(const char *data, int len) {
    uint8_t crc = CRC8_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC-8 validation function
int validate_crc(const char *data, int len) {
    uint8_t crc = calculate_crc(data, len - 1);
    return (crc == data[len - 1]);
}

// Initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Send command to the sensor
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from the sensor
int read_data(int handle, char *buffer, int count) {
    int result = i2cReadDevice(handle, buffer, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Convert raw pressure to Pascals
float convert_pressure(int16_t raw_pressure, int16_t scale_factor) {
    return (float)raw_pressure / scale_factor;
}

// Convert raw temperature to Celsius
float convert_temperature(int16_t raw_temperature) {
    return (float)raw_temperature / 200.0;
}

// Log data to file
int log_data(float pressure, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to open log file\n");
            return -1;
        }
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Send continuous measurement command
    if (send_command(i2c_handle, CONTINUOUS_MEASUREMENT_CMD) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        char buffer[9];
        int16_t raw_pressure, raw_temperature, scale_factor;
        float pressure, temperature;

        // Read data from sensor
        if (read_data(i2c_handle, buffer, 9) != 0) {
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[64];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
            fprintf(stderr, "%s,I2C read error\n", timestamp);
            if (log_file != NULL) {
                fprintf(log_file, "%s,I2C read error\n", timestamp);
                fflush(log_file);
            }
            sleep(1);
            continue;
        }

        // Validate CRC for pressure
        if (!validate_crc(buffer, 3)) {
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[64];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
            fprintf(stderr, "%s,Pressure CRC error\n", timestamp);
            if (log_file != NULL) {
                fprintf(log_file, "%s,Pressure CRC error\n", timestamp);
                fflush(log_file);
            }
            sleep(1);
            continue;
        }

        // Validate CRC for temperature
        if (!validate_crc(buffer + 3, 3)) {
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[64];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
            fprintf(stderr, "%s,Temperature CRC error\n", timestamp);
            if (log_file != NULL) {
                fprintf(log_file, "%s,Temperature CRC error\n", timestamp);
                fflush(log_file);
            }
            sleep(1);
            continue;
        }

        // Extract raw values
        raw_pressure = (buffer[0] << 8) | buffer[1];
        raw_temperature = (buffer[3] << 8) | buffer[4];
        scale_factor = (buffer[6] << 8) | buffer[7] | (buffer[8] << 16);

        // Convert values
        pressure = convert_pressure(raw_pressure, scale_factor);
        temperature = convert_temperature(raw_temperature);

        // Log data
        if (log_data(pressure, temperature) != 0) {
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[64];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
            fprintf(stderr, "%s,Log file error\n", timestamp);
        }

        sleep(1);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

