#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <pthread.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>

// SCD40 I2C address
#define SCD40_I2C_ADDR 0x62

// SCD40 commands
#define SCD40_START_PERIODIC_MEASUREMENT 0x21B1
#define SCD40_READ_MEASUREMENT 0xE000
#define SCD40_STOP_PERIODIC_MEASUREMENT 0x3F86

// CRC-8 polynomial
#define CRC8_POLYNOMIAL 0x31

// Circular buffer size
#define BUFFER_SIZE 100

// Data structure for sensor readings
typedef struct {
    time_t timestamp;
    float co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Circular buffer structure
typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

// Global variables
int i2c_handle;
volatile sig_atomic_t running = 1;
circular_buffer_t buffer;

// Function prototypes
int init_pigpio();
int open_i2c_bus();
int start_periodic_measurement();
int read_measurement(uint16_t *co2, uint16_t *temperature, uint16_t *humidity);
int validate_crc(uint8_t data[], int len);
void convert_data(uint16_t raw_co2, uint16_t raw_temperature, uint16_t raw_humidity, float *co2, float *temperature, float *humidity);
int stop_periodic_measurement();
void init_circular_buffer(circular_buffer_t *buffer);
int add_to_circular_buffer(circular_buffer_t *buffer, sensor_data_t data);
int write_buffer_to_file(circular_buffer_t *buffer);
void *logging_thread(void *arg);
void signal_handler(int signal);
int log_error(const char *message);

// Function to initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open the I2C bus
int open_i2c_bus() {
    i2c_handle = i2cOpen(1, SCD40_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to start periodic measurement
int start_periodic_measurement() {
    uint8_t cmd[2] = {(SCD40_START_PERIODIC_MEASUREMENT >> 8) & 0xFF, SCD40_START_PERIODIC_MEASUREMENT & 0xFF};
    int result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to start periodic measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read measurement data
int read_measurement(uint16_t *co2, uint16_t *temperature, uint16_t *humidity) {
    uint8_t cmd[2] = {(SCD40_READ_MEASUREMENT >> 8) & 0xFF, SCD40_READ_MEASUREMENT & 0xFF};
    uint8_t data[9];

    int result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write read measurement command: %d\n", result);
        return -1;
    }

    gpioDelay(1); // Wait for data to be ready

    result = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (result != 9) {
        fprintf(stderr, "Failed to read measurement data: %d\n", result);
        return -1;
    }

    // Extract raw values
    uint16_t raw_co2 = (data[0] << 8) | data[1];
    uint16_t raw_temperature = (data[3] << 8) | data[4];
    uint16_t raw_humidity = (data[6] << 8) | data[7];

    // Validate CRC
    if (!validate_crc(data, 3) || !validate_crc(data + 3, 3) || !validate_crc(data + 6, 3)) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }

    *co2 = raw_co2;
    *temperature = raw_temperature;
    *humidity = raw_humidity;

    return 0;
}

// Function to validate CRC-8
int validate_crc(uint8_t data[], int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len - 1; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == data[len - 1]);
}

// Function to convert raw data to physical values
void convert_data(uint16_t raw_co2, uint16_t raw_temperature, uint16_t raw_humidity, float *co2, float *temperature, float *humidity) {
    *co2 = raw_co2;
    *temperature = -45.0 + 175.0 * (float)raw_temperature / 65535.0;
    *humidity = 100.0 * (float)raw_humidity / 65535.0;
}

// Function to stop periodic measurement
int stop_periodic_measurement() {
    uint8_t cmd[2] = {(SCD40_STOP_PERIODIC_MEASUREMENT >> 8) & 0xFF, SCD40_STOP_PERIODIC_MEASUREMENT & 0xFF};
    int result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to stop periodic measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to initialize the circular buffer
void init_circular_buffer(circular_buffer_t *buffer) {
    buffer->head = 0;
    buffer->tail = 0;
    buffer->count = 0;
    pthread_mutex_init(&buffer->mutex, NULL);
}

// Function to add data to the circular buffer
int add_to_circular_buffer(circular_buffer_t *buffer, sensor_data_t data) {
    pthread_mutex_lock(&buffer->mutex);
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count == BUFFER_SIZE) {
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    } else {
        buffer->count++;
    }
    pthread_mutex_unlock(&buffer->mutex);
    return 0;
}

// Function to write the circular buffer to a file
int write_buffer_to_file(circular_buffer_t *buffer) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char filename[256];
    strftime(filename, sizeof(filename), "/var/log/scd40_data/scd40_data_%Y%m%d_%H%M%S.csv", t);

    FILE *fp = fopen(filename, "w");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open file for writing: %s\n", strerror(errno));
        return -1;
    }

    // Write header
    fprintf(fp, "timestamp,co2,temperature,humidity\n");

    pthread_mutex_lock(&buffer->mutex);
    int i = buffer->tail;
    for (int j = 0; j < buffer->count; j++) {
        fprintf(fp, "%ld,%.2f,%.2f,%.2f\n", buffer->data[i].timestamp, buffer->data[i].co2, buffer->data[i].temperature, buffer->data[i].humidity);
        i = (i + 1) % BUFFER_SIZE;
    }
    pthread_mutex_unlock(&buffer->mutex);

    fclose(fp);
    return 0;
}

// Logging thread function
void *logging_thread(void *arg) {
    while (running) {
        sleep(60);
        if (write_buffer_to_file(&buffer) != 0) {
            log_error("Failed to write buffer to file");
        }
    }
    return NULL;
}

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Received SIGINT, stopping...\n");
        running = 0;
    }
}

// Function to log errors to a file
int log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char filename[256];
    strftime(filename, sizeof(filename), "/var/log/scd40_error.log", t);

    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open error log file: %s\n", strerror(errno));
        return -1;
    }

    fprintf(fp, "%s: %s\n", asctime(t), message);
    fclose(fp);
    return 0;
}

int main() {
    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    if (open_i2c_bus() != 0) {
        gpioTerminate();
        return 1;
    }

    // Start periodic measurement
    if (start_periodic_measurement() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    init_circular_buffer(&buffer);

    // Create logging thread
    pthread_t logging_thread_id;
    if (pthread_create(&logging_thread_id, NULL, logging_thread, NULL) != 0) {
        log_error("Failed to create logging thread");
        running = 0; // Stop the main loop if logging fails
    }

    // Set signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        uint16_t co2, temperature, humidity;
        if (read_measurement(&co2, &temperature, &humidity) == 0) {
            float co2_ppm, temperature_c, humidity_percent;
            convert_data(co2, temperature, humidity, &co2_ppm, &temperature_c, &humidity_percent);

            sensor_data_t data;
            data.timestamp = time(NULL);
            data.co2 = co2_ppm;
            data.temperature = temperature_c;
            data.humidity = humidity_percent;

            if (add_to_circular_buffer(&buffer, data) != 0) {
                log_error("Failed to add data to circular buffer");
            }
        } else {
            log_error("Failed to read sensor data");
        }

        sleep(5);
    }

    // Stop periodic measurement
    if (stop_periodic_measurement() != 0) {
        log_error("Failed to stop periodic measurement");
    }

    // Wait for logging thread to finish
    pthread_join(logging_thread_id, NULL);

    // Write any remaining data to file
    if (write_buffer_to_file(&buffer) != 0) {
        log_error("Failed to write remaining data to file");
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

