// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASURE_CMD 0x362F
#define CRC_POLY 0x31
#define CRC_INIT 0xFF
#define LOG_FILE "sdp810_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t raw_pressure;
    int16_t raw_temperature;
    int16_t raw_scale_factor;
} sensor_data_t;

// Function prototypes
int init_i2c();
int send_command(int handle, uint16_t command);
int read_data(int handle, char *buffer, int count);
uint8_t calculate_crc(const char *data, int len);
int validate_crc(const char *data, int len);
int read_sensor_data(int handle, sensor_data_t *data);
float convert_pressure(int16_t raw_pressure, int16_t raw_scale_factor);
float convert_temperature(int16_t raw_temperature);
int log_data(float pressure, float temperature);
void signal_handler(int signal);

// CRC-8 calculation function
uint8_t calculate_crc(const char *data, int len) {
    uint8_t crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC validation function
int validate_crc(const char *data, int len) {
    uint8_t crc_calculated = calculate_crc(data, len - 1);
    return (crc_calculated == data[len - 1]);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send command to the sensor
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from the sensor
int read_data(int handle, char *buffer, int count) {
    int result = i2cReadDevice(handle, buffer, count);
    if (result != count) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(int handle, sensor_data_t *data) {
    char buffer[9];
    if (read_data(handle, buffer, 9) != 0) {
        return -1;
    }

    if (!validate_crc(buffer, 3) || !validate_crc(buffer + 3, 3) || !validate_crc(buffer + 6, 3)) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    data->raw_pressure = (buffer[0] << 8) | buffer[1];
    data->raw_temperature = (buffer[3] << 8) | buffer[4];
    data->raw_scale_factor = (buffer[6] << 8) | buffer[7];

    return 0;
}

// Convert raw pressure to Pascals
float convert_pressure(int16_t raw_pressure, int16_t raw_scale_factor) {
    return (float)raw_pressure * (float)raw_scale_factor / 1000.0;
}

// Convert raw temperature to Celsius
float convert_temperature(int16_t raw_temperature) {
    return -45.0 + 175.0 * (float)raw_temperature / 65535.0;
}

// Log data to file
int log_data(float pressure, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fflush(log_file);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Send continuous measurement command
    if (send_command(i2c_handle, MEASURE_CMD) != 0) {
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_handle, &sensor_data) == 0) {
            // Convert data
            float pressure = convert_pressure(sensor_data.raw_pressure, sensor_data.raw_scale_factor);
            float temperature = convert_temperature(sensor_data.raw_temperature);

            // Log data
            log_data(pressure, temperature);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

