// ICP-10110 I2C address
#define ICP10110_ADDR 0x63

// ICP-10110 Registers
#define WHO_AM_I 0x08
#define CALIB_START 0x05
#define CALIB_END 0x08
#define MEASURE 0x00
#define DATA_START 0x00

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Calibration coefficients
int32_t c0, c1, c00, c10, c01, c11, c20, c21;

// Function prototypes
int init_pigpio();
int open_i2c_bus();
int verify_sensor_identity();
int read_calibration_coefficients();
int trigger_measurement();
int read_sensor_data(int32_t *pressure, int32_t *temperature);
double convert_pressure(int32_t raw_pressure);
double convert_temperature(int32_t raw_temperature);
void log_data(double pressure, double temperature);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    double pressure;
    double temperature;
} sensor_data_t;

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open I2C bus
    if (open_i2c_bus() != 0) {
        fprintf(stderr, "Failed to open I2C bus. Exiting.\n");
        cleanup();
        return 1;
    }

    // Verify sensor identity
    if (verify_sensor_identity() != 0) {
        fprintf(stderr, "Failed to verify sensor identity. Exiting.\n");
        cleanup();
        return 1;
    }

    // Read calibration coefficients
    if (read_calibration_coefficients() != 0) {
        fprintf(stderr, "Failed to read calibration coefficients. Exiting.\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int32_t raw_pressure, raw_temperature;

        // Trigger measurement
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Failed to trigger measurement. Skipping sample.\n");
            sleep(5);
            continue;
        }

        // Read sensor data
        if (read_sensor_data(&raw_pressure, &raw_temperature) != 0) {
            fprintf(stderr, "Failed to read sensor data. Skipping sample.\n");
            sleep(5);
            continue;
        }

        // Convert data
        double pressure = convert_pressure(raw_pressure);
        double temperature = convert_temperature(raw_temperature);

        // Log data
        log_data(pressure, temperature);

        // Print to stdout
        printf("Pressure: %.2f hPa, Temperature: %.2f C\n", pressure, temperature);

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

