int open_i2c_bus() {
    i2c_handle = i2cOpen(1, ICP10110_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Verify sensor identity
int verify_sensor_identity() {
    char buf[1];
    int result = i2cReadI2CBlockData(i2c_handle, WHO_AM_I, buf, 1);
    if (result != 1) {
        fprintf(stderr, "Failed to read WHO_AM_I register: %d\n", result);
        return 1;
    }
    if (buf[0] != 0x41) {
        fprintf(stderr, "Incorrect WHO_AM_I value: 0x%02X\n", buf[0]);
        return 1;
    }
    return 0;
}

// Read calibration coefficients
int read_calibration_coefficients() {
    char buf[8];
    int result = i2cReadI2CBlockData(i2c_handle, CALIB_START, buf, 8);
    if (result != 8) {
        fprintf(stderr, "Failed to read calibration coefficients: %d\n", result);
        return 1;
    }

    c0 = (int32_t)((buf[0] << 24) | (buf[1] << 16) | (buf[2] << 8) | buf[3]) >> 8;
    c1 = (int32_t)((buf[4] << 24) | (buf[5] << 16) | (buf[6] << 8) | buf[7]) >> 8;

    return 0;
}

// Trigger measurement
int trigger_measurement() {
    char buf[1] = {0x00};
    int result = i2cWriteI2CBlockData(i2c_handle, MEASURE, buf, 1);
    if (result != 1) {
        fprintf(stderr, "Failed to trigger measurement: %d\n", result);
        return 1;
    }
    gpioDelay(10); // Wait 10 ms
    return 0;
}

// Read sensor data
int read_sensor_data(int32_t *pressure, int32_t *temperature) {
    char buf[6];
    int result = i2cReadI2CBlockData(i2c_handle, DATA_START, buf, 6);
    if (result != 6) {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        return 1;
    }

    *pressure = (int32_t)((buf[0] << 24) | (buf[1] << 16) | (buf[2] << 8) | buf[3]) >> 8;
    *temperature = (int32_t)((buf[4] << 24) | (buf[5] << 16) | (buf[6] << 8) | buf[7]) >> 8;

    return 0;
}

// Convert pressure to hPa
double convert_pressure(int32_t raw_pressure) {
    // Placeholder conversion formula.  Replace with actual formula from datasheet.
    return (double)raw_pressure / 100.0; // Example conversion
}

// Convert temperature to Celsius
double convert_temperature(int32_t raw_temperature) {
    // Placeholder conversion formula.  Replace with actual formula from datasheet.
    return (double)raw_temperature / 100.0; // Example conversion
}

// Log data to file
void log_data(double pressure, double temperature) {
    FILE *fp = fopen("environmental_data.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open file for logging\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fflush(fp); // Ensure data is written to disk immediately
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

