        fprintf(stderr, "Failed to read calibration coefficients: %d\n", result);
        return 1;
    }

    c0 = (int32_t)((buf[0] << 24) | (buf[1] << 16) | (buf[2] << 8) | buf[3]) >> 8;
    c1 = (int32_t)((buf[4] << 24) | (buf[5] << 16) | (buf[6] << 8) | buf[7]) >> 8;

    return 0;
}

// Trigger measurement
int trigger_measurement() {
    char buf[1] = {0x00};
    int result = i2cWriteI2CBlockData(i2c_handle, MEASURE, buf, 1);
