    *temperature = (int32_t)((buf[4] << 24) | (buf[5] << 16) | (buf[6] << 8) | buf[7]) >> 8;

    return 0;
}

// Convert pressure to hPa
double convert_pressure(int32_t raw_pressure) {
    // Placeholder conversion formula.  Replace with actual formula from datasheet.
    return (double)raw_pressure / 100.0; // Example conversion
}

// Convert temperature to Celsius
double convert_temperature(int32_t raw_temperature) {
    // Placeholder conversion formula.  Replace with actual formula from datasheet.
    return (double)raw_temperature / 100.0; // Example conversion
}

// Log data to file
void log_data(double pressure, double temperature) {
