static int i2c_fd = -1;
static struct gpiod_line *gpio_line = NULL;
static struct gpiod_chip *gpio_chip = NULL;
static volatile sig_atomic_t terminate = 0;

// Calibration coefficients
static int32_t c0, c1, c2, c3;

// Function prototypes
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_bytes(int fd, uint8_t reg, uint16_t data);
int read_calibration_coefficients(int fd);
int trigger_measurement(int fd);
int read_sensor_data(int fd, int32_t *pressure, int32_t *temperature, int32_t *crc);
