        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("Failed to read data");
        return -1;
    }
    return 0;
}

// I2C write function
int i2c_write_bytes(int fd, uint8_t reg, uint16_t data) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (data >> 8) & 0xFF;
    buf[2] = data & 0xFF;
    if (write(fd, buf, 3) != 3) {
        perror("Failed to write data");
        return -1;
    }
    return 0;
}

// Read calibration coefficients
int read_calibration_coefficients(int fd) {
    uint8_t data[4];
    if (i2c_read_bytes(fd, 0x66, data, 4) != 0) {
        fprintf(stderr, "Failed to read calibration coefficients\n");
        return -1;
    }

    c0 = (data[0] << 8) | data[1];
    c1 = (data[2] << 8) | data[3];

    return 0;
}

// Trigger measurement
int trigger_measurement(int fd) {
    if (i2c_write_bytes(fd, 0x00, MEASUREMENT_COMMAND) != 0) {
        fprintf(stderr, "Failed to trigger measurement\n");
        return -1;
    }
    return 0;
}

