    if (i2c_read_bytes(fd, 0x00, data, 6) != 0) {
        fprintf(stderr, "Failed to read sensor data\n");
        return -1;
    }

    *pressure = (data[0] << 16) | (data[1] << 8) | data[2];
    *temperature = (data[3] << 16) | (data[4] << 8) | data[5];
    *crc = data[5];

    return 0;
}

// Verify CRC
bool verify_crc(uint8_t *data, int len, uint8_t crc) {
    uint8_t crc_calculated = 0xFF;
    for (int i = 0; i < len; i++) {
        crc_calculated ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc_calculated & 0x80) {
                crc_calculated = (crc_calculated << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc_calculated <<= 1;
            }
        }
    }
    return crc_calculated == crc;
}

// Calculate pressure
float calculate_pressure(int32_t raw_pressure, int32_t raw_temperature) {
    // Placeholder implementation - replace with actual formula from datasheet
    // This is a simplified example and will not provide accurate results.
    float pressure = (float)raw_pressure; // Replace with actual calculation
    return pressure;
}

// Calculate temperature
float calculate_temperature(int32_t raw_temperature) {
    // Placeholder implementation - replace with actual formula from datasheet
    // This is a simplified example and will not provide accurate results.
    float temperature = (float)raw_temperature; // Replace with actual calculation
    return temperature;
}

// Control LED
void control_led(struct gpiod_line *line, bool on) {
    if (gpiod_line_set_value(line, on ? 1 : 0) < 0) {
        perror("Failed to set GPIO value");
    }
}

// Blink LED
void blink_led(struct gpiod_line *line, float frequency) {
    struct timespec on_time, off_time;
    on_time.tv_sec = 0;
    on_time.tv_nsec = (long)(500000000.0f / frequency); // 500ms for 1Hz, 100ms for 5Hz
    off_time.tv_sec = 0;
    off_time.tv_nsec = (long)(500000000.0f / frequency); // 500ms for 1Hz, 100ms for 5Hz

    control_led(line, true);
    nanosleep(&on_time, NULL);
    control_led(line, false);
    nanosleep(&off_time, NULL);
}

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    // Get GPIO line
    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Request GPIO line as output
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "pressure_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(gpio_line, &config, 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Read calibration coefficients
    if (read_calibration_coefficients(i2c_fd) != 0) {
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        int32_t raw_pressure, raw_temperature, crc;
        float pressure, temperature;

        // Trigger measurement
        if (trigger_measurement(i2c_fd) != 0) {
            fprintf(stderr, "Measurement failed, retrying...\n");
            sleep(1);
            continue;
        }

        // Wait for measurement to complete
        usleep(20000); // 20 ms

        // Read sensor data
        if (read_sensor_data(i2c_fd, &raw_pressure, &raw_temperature, &crc) != 0) {
            fprintf(stderr, "Sensor data read failed, retrying...\n");
            sleep(1);
            continue;
        }

        // Verify CRC
        if (!verify_crc((uint8_t *)&raw_pressure, 4, crc)) {
            fprintf(stderr, "CRC verification failed, retrying...\n");
            sleep(1);
            continue;
        }

        // Calculate pressure and temperature
        pressure = calculate_pressure(raw_pressure, raw_temperature);
        temperature = calculate_temperature(raw_temperature);

        printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);

        // Control LED based on pressure
        if (pressure < PRESSURE_THRESHOLD) {
            blink_led(gpio_line, 5.0f); // 5 Hz
        } else {
            blink_led(gpio_line, 1.0f); // 1 Hz
        }

        sleep(1);
    }

    // Cleanup
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);
    close(i2c_fd);

    return 0;
}

