#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define MLX90614_ADDR 0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define FAN_GPIO 18
#define AMBIENT_TEMP_THRESHOLD 30.0
#define OBJECT_TEMP_THRESHOLD 28.0
#define LOG_FILE "temperature_log.txt"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int open_i2c_bus();
int read_temperature(int reg, float *temp);
float convert_to_celsius(uint16_t raw_temp);
int control_fan(float object_temp);
int log_temperature(float ambient_temp, float object_temp);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data (optional)
typedef struct {
    float ambient_temp;
    float object_temp;
} sensor_data_t;

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open I2C bus
    if (open_i2c_bus() != 0) {
        fprintf(stderr, "Failed to open I2C bus. Exiting.\n");
        cleanup();
        return 1;
    }

    // Main loop
    float ambient_temp, object_temp;
    while (!terminate) {
        // Read temperatures
        if (read_temperature(AMBIENT_TEMP_REG, &ambient_temp) != 0) {
            fprintf(stderr, "Failed to read ambient temperature.\n");
            continue; // Skip to the next iteration
        }
        if (read_temperature(OBJECT_TEMP_REG, &object_temp) != 0) {
            fprintf(stderr, "Failed to read object temperature.\n");
            continue; // Skip to the next iteration
        }

        // Log temperature
        if (log_temperature(ambient_temp, object_temp) != 0) {
            fprintf(stderr, "Failed to log temperature.\n");
        }

        // Control fan
        if (control_fan(object_temp) != 0) {
            fprintf(stderr, "Failed to control fan.\n");
        }

        // Wait 2 seconds
        gpioDelay(2000000); // 2 seconds in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus() {
    i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Read temperature from sensor
int read_temperature(int reg, float *temp) {
    int retries = 0;
    uint16_t raw_temp;

    while (retries < MAX_RETRIES) {
        raw_temp = i2cReadWordData(i2c_handle, reg);
        if (raw_temp >= 0) {
            *temp = convert_to_celsius(raw_temp);
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (reg 0x%02X, retry %d): %d\n", reg, retries + 1, raw_temp);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }

    fprintf(stderr, "Failed to read temperature from register 0x%02X after %d retries.\n", reg, MAX_RETRIES);
    return 1; // Failure
}

// Convert raw temperature to Celsius
float convert_to_celsius(uint16_t raw_temp) {
    return (float)raw_temp * 0.02 - 273.15;
}

// Control fan based on object temperature
