#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_CMD 0xFD
#define PORT 8080
#define MAX_RETRIES 3

int i2c_handle;
volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Function to read temperature and humidity from SHT40
int read_sht40(float *temperature, float *humidity) {
    char buf[6];
    int result;
    unsigned int raw_temperature, raw_humidity;

    // Send measurement command
    result = i2cWriteByteData(i2c_handle, MEASURE_CMD, 0);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    // Wait for measurement (at least 10 ms)
    gpioDelay(10000); // 10 ms

    // Read 6 bytes of data
    result = i2cReadI2CBlockData(i2c_handle, 0, buf, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    // Convert raw data to temperature and humidity
    raw_temperature = (buf[0] << 8) | buf[1];
    raw_humidity = (buf[3] << 8) | buf[4];

    *temperature = -45.0 + 175.0 * (raw_temperature / 65535.0);
    *humidity = -6.0 + 125.0 * (raw_humidity / 65535.0);

    // Clamp humidity to 0-100%
    if (*humidity < 0.0) *humidity = 0.0;
    if (*humidity > 100.0) *humidity = 100.0;

    return 0;
}

// Function to format data into HTML
char* format_html(float temperature, float humidity) {
    char *html = malloc(256);
    if (html == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    sprintf(html, "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\n\r\n<html><body><h1>Temperature: %.2f &deg;C, Humidity: %.2f %%</h1></body></html>", temperature, humidity);
    return html;
}

int main() {
    int server_fd, new_socket;
    struct sockaddr_in address;
    int addrlen = sizeof(address);
    float temperature, humidity;
    char *html_response;
    int retries;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create socket
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    // Bind socket to address
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        close(server_fd);
        return 1;
    }

    // Listen for connections
    if (listen(server_fd, 3) < 0) {
        perror("listen failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        close(server_fd);
        return 1;
    }

    printf("Server listening on port %d\n", PORT);

    while (!terminate) {
        // Accept connection
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            perror("accept failed");
            continue; // Continue listening
        }

        // Read temperature and humidity with retries
        retries = 0;
        while (retries < MAX_RETRIES) {
            if (read_sht40(&temperature, &humidity) == 0) {
                break; // Success, exit retry loop
            } else {
                fprintf(stderr, "Sensor read failed, retry %d\n", retries + 1);
                retries++;
                gpioDelay(100000); // 100 ms delay
            }
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to read sensor after %d retries\n", MAX_RETRIES);
            html_response = format_html(-999.0, -999.0); // Indicate error
        } else {
            // Format data into HTML
            html_response = format_html(temperature, humidity);
        }

        if (html_response != NULL) {
            // Send response
            send(new_socket, html_response, strlen(html_response), 0);
            free(html_response);
        }

        // Close connection
        close(new_socket);
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();
    close(server_fd);

    printf("Server stopped\n");
    return 0;
}

