#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define TMP102_ADDR 0x48
#define TEMP_REG 0x00
#define CSV_FILENAME "temperature_log.csv"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
float read_temperature();
void log_temperature(float temperature);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure for program state (optional, but good practice)
typedef struct {
    int i2c_handle;
    FILE *log_file;
} ProgramState;

ProgramState state;

// Function to initialize the program
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, TMP102_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }
    state.i2c_handle = i2c_handle;

    // Open log file
    state.log_file = fopen(CSV_FILENAME, "a");
    if (state.log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to read temperature from TMP102
float read_temperature() {
    int raw_data;
    float temperature;

    // Read two bytes from register 0x00
    raw_data = i2cReadWordData(i2c_handle, TEMP_REG);
    if (raw_data < 0) {
        fprintf(stderr, "Failed to read temperature data: %s\n", strerror(errno));
        return -1000.0; // Indicate error with a very low temperature
    }

    // Convert to 12-bit two's complement
    int16_t temp_12bit = (int16_t)(raw_data >> 4);

    // Convert to Celsius
    temperature = temp_12bit * 0.0625;

    return temperature;
}

// Function to log temperature to CSV file
void log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    // Write to CSV file
    if (fprintf(state.log_file, "%s,%.2f\n", timestamp, temperature) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
    }
    fflush(state.log_file); // Ensure data is written immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C pressed. Exiting...\n");
        terminate = 1;
    }
}

// Function to cleanup resources
void cleanup() {
    if (state.i2c_handle >= 0) {
        i2cClose(state.i2c_handle);
    }
    if (state.log_file != NULL) {
        fclose(state.log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();

        if (temperature > -999.0) { // Check for valid temperature reading
            log_temperature(temperature);
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

