#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SDP800_ADDRESS 0x25
#define MEASUREMENT_COMMAND 0x362F
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF
#define MEASUREMENT_DELAY_MS 45
#define READ_DELAY_MS 500

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int calculate_crc(uint8_t data[], int len);
int read_sdp800(int i2c_handle, int *pressure, int *temperature);
void signal_handler(int signal);

// CRC-8 calculation function
int calculate_crc(uint8_t data[], int len) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from SDP800 sensor
int read_sdp800(int i2c_handle, int *pressure, int *temperature) {
    uint8_t buffer[6];
    uint8_t command[2] = {(MEASUREMENT_COMMAND >> 8) & 0xFF, MEASUREMENT_COMMAND & 0xFF};

    // Send measurement command
    if (i2cWriteDevice(i2c_handle, (char *)command, 2) != 2) {
        fprintf(stderr, "Error writing measurement command to I2C.\n");
        return -1;
    }

    // Wait for measurement to complete
    gpioDelay(MEASUREMENT_DELAY_MS * 1000); // Convert ms to microseconds

    // Read 6 bytes of data
    if (i2cReadDevice(i2c_handle, (char *)buffer, 6) != 6) {
        fprintf(stderr, "Error reading data from I2C.\n");
        return -1;
    }

    // Extract pressure and temperature values
    int16_t raw_pressure = (buffer[0] << 8) | buffer[1];
    int16_t raw_temperature = (buffer[3] << 8) | buffer[4];

    // CRC Check
    uint8_t pressure_data[2] = {buffer[0], buffer[1]};
    uint8_t temperature_data[2] = {buffer[3], buffer[4]};

    if (calculate_crc(pressure_data, 2) != buffer[2]) {
        fprintf(stderr, "Pressure CRC check failed.\n");
        return -1;
    }

    if (calculate_crc(temperature_data, 2) != buffer[5]) {
        fprintf(stderr, "Temperature CRC check failed.\n");
        return -1;
    }

    *pressure = raw_pressure;
    *temperature = raw_temperature;

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int pressure, temperature;

    // Main loop
    while (!terminate) {
        if (read_sdp800(i2c_handle, &pressure, &temperature) == 0) {
            printf("Pressure: %d, Temperature: %d\n", pressure, temperature);
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        gpioDelay(READ_DELAY_MS * 1000); // Convert ms to microseconds
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

