#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define GPIO_RELAY 17
#define LOG_FILE "reflow_log.csv"
#define PROFILE_FILE "profile.txt"
#define MAX_PROFILE_POINTS 100

// PID Constants
#define Kp 1.0
#define Ki 0.1
#define Kd 0.01

// Global Variables
static volatile int running = 1;
static int spi_handle;
static FILE *log_file;
static float target_temperature = 0.0;
static float current_temperature = 0.0;
static float pid_output = 0.0;
static float integral = 0.0;
static float previous_error = 0.0;
static float setpoint[MAX_PROFILE_POINTS];
static float time_setpoint[MAX_PROFILE_POINTS];
static int num_setpoints = 0;
static int current_setpoint_index = 0;

// Function Prototypes
int read_max6675(int spi_handle, float *temperature);
float calculate_pid(float setpoint, float actual_temperature, float *integral, float *previous_error);
void set_relay_state(int gpio_pin, float duty_cycle);
void log_data(float temperature, float setpoint, float duty_cycle);
void load_profile(const char *filename);
void signal_handler(int signal);

// Function to read temperature from MAX6675 thermocouple
int read_max6675(int spi_handle, float *temperature) {
    unsigned char data[2];
    int result = spiRead(spi_handle, data, 2);

    if (result != 2) {
        fprintf(stderr, "SPI read error: %d\n", result);
        return -1; // Indicate error
    }

    int raw = (data[0] << 8) | data[1];

    if (raw & 0x0004) {
        fprintf(stderr, "Thermocouple open circuit!\n");
        return -2; // Indicate open circuit error
    }

    raw >>= 3; // Remove status bits
    *temperature = (float)raw * 0.25;
    return 0; // Indicate success
}

// Function to calculate PID output
float calculate_pid(float setpoint, float actual_temperature, float *integral, float *previous_error) {
    float error = setpoint - actual_temperature;
    *integral += error;
    float derivative = error - *previous_error;
    float output = Kp * error + Ki * (*integral) + Kd * derivative;
    *previous_error = error;

    // Clamp output to 0.0 - 1.0
    if (output < 0.0) output = 0.0;
    if (output > 1.0) output = 1.0;

    return output;
}

// Function to set the relay state using PWM
void set_relay_state(int gpio_pin, float duty_cycle) {
    gpioPWM(gpio_pin, (int)(duty_cycle * 255.0));
}

// Function to log data to a CSV file
void log_data(float temperature, float setpoint, float duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, temperature, setpoint, duty_cycle);
    fflush(log_file); // Ensure data is written immediately
}

// Function to load the temperature profile from a file
void load_profile(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening profile file: %s\n", filename);
        exit(EXIT_FAILURE);
    }

    char line[256];
    while (fgets(line, sizeof(line), fp) != NULL && num_setpoints < MAX_PROFILE_POINTS) {
        if (sscanf(line, "%f,%f", &time_setpoint[num_setpoints], &setpoint[num_setpoints]) == 2) {
            num_setpoints++;
        } else {
            fprintf(stderr, "Invalid line in profile file: %s", line);
        }
    }

    fclose(fp);
    if (num_setpoints == 0) {
        fprintf(stderr, "No setpoints found in profile file.\n");
        exit(EXIT_FAILURE);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin for relay as output
    gpioSetMode(GPIO_RELAY, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Load temperature profile
    load_profile(PROFILE_FILE);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    time_t start_time = time(NULL);
    while (running) {
        // Read temperature from MAX6675
        float temperature;
        int read_result = read_max6675(spi_handle, &temperature);
        if (read_result == 0) {
            current_temperature = temperature;

            // Calculate PID output
            pid_output = calculate_pid(setpoint[current_setpoint_index], current_temperature, &integral, &previous_error);

            // Set relay state
            set_relay_state(GPIO_RELAY, pid_output);

            // Log data
            log_data(current_temperature, setpoint[current_setpoint_index], pid_output);

            // Update setpoint index based on elapsed time
            time_t current_time = time(NULL);
            double elapsed_time = difftime(current_time, start_time);
            while (current_setpoint_index < num_setpoints - 1 && elapsed_time >= time_setpoint[current_setpoint_index + 1]) {
                current_setpoint_index++;
            }
        } else if (read_result == -2) {
            fprintf(stderr, "Thermocouple open circuit, exiting.\n");
            running = 0;
        } else {
            fprintf(stderr, "Error reading temperature, retrying.\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Clean up
    spiClose(spi_handle);
    gpioWrite(GPIO_RELAY, 0); // Turn off relay
    fclose(log_file);
    gpioTerminate();

    return 0;
}

