float calculate_pid(float setpoint, float actual_temperature, float *integral, float *previous_error) {
    float error = setpoint - actual_temperature;
    *integral += error;
    float derivative = error - *previous_error;
    float output = Kp * error + Ki * (*integral) + Kd * derivative;
    *previous_error = error;

    // Clamp output to 0.0 - 1.0
    if (output < 0.0) output = 0.0;
    if (output > 1.0) output = 1.0;

    return output;
}

// Function to set the relay state using PWM
void set_relay_state(int gpio_pin, float duty_cycle) {
    gpioPWM(gpio_pin, (int)(duty_cycle * 255.0));
}

// Function to log data to a CSV file
void log_data(float temperature, float setpoint, float duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, temperature, setpoint, duty_cycle);
    fflush(log_file); // Ensure data is written immediately
}

// Function to load the temperature profile from a file
void load_profile(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening profile file: %s\n", filename);
        exit(EXIT_FAILURE);
    }

    char line[256];
    while (fgets(line, sizeof(line), fp) != NULL && num_setpoints < MAX_PROFILE_POINTS) {
        if (sscanf(line, "%f,%f", &time_setpoint[num_setpoints], &setpoint[num_setpoints]) == 2) {
            num_setpoints++;
        } else {
            fprintf(stderr, "Invalid line in profile file: %s", line);
        }
    }

    fclose(fp);
    if (num_setpoints == 0) {
        fprintf(stderr, "No setpoints found in profile file.\n");
        exit(EXIT_FAILURE);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin for relay as output
    gpioSetMode(GPIO_RELAY, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Load temperature profile
    load_profile(PROFILE_FILE);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    time_t start_time = time(NULL);
    while (running) {
        // Read temperature from MAX6675
        float temperature;
        int read_result = read_max6675(spi_handle, &temperature);
        if (read_result == 0) {
            current_temperature = temperature;

            // Calculate PID output
            pid_output = calculate_pid(setpoint[current_setpoint_index], current_temperature, &integral, &previous_error);

            // Set relay state
            set_relay_state(GPIO_RELAY, pid_output);

            // Log data
            log_data(current_temperature, setpoint[current_setpoint_index], pid_output);

            // Update setpoint index based on elapsed time
            time_t current_time = time(NULL);
            double elapsed_time = difftime(current_time, start_time);
            while (current_setpoint_index < num_setpoints - 1 && elapsed_time >= time_setpoint[current_setpoint_index + 1]) {
                current_setpoint_index++;
            }
        } else if (read_result == -2) {
            fprintf(stderr, "Thermocouple open circuit, exiting.\n");
            running = 0;
        } else {
            fprintf(stderr, "Error reading temperature, retrying.\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Clean up
    spiClose(spi_handle);
    gpioWrite(GPIO_RELAY, 0); // Turn off relay
    fclose(log_file);
    gpioTerminate();

    return 0;
}

