#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <dirent.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <math.h>
#include <pigpio.h>

// Configuration
#define HEATER_GPIO 17
#define PWM_GPIO 18
#define PWM_FREQUENCY 1000 // Hz
#define LOG_FILE "greenhouse.log"
#define W1_DEVICES_DIR "/sys/bus/w1/devices/"
#define MAX_SENSORS 10
#define SAMPLE_INTERVAL 5 // seconds

// Global variables (to be minimized, but needed for signal handler)
static volatile int running = 1;
static FILE *log_file = NULL;
static float setpoint_temperature = 25.0; // Default setpoint
static float Kp = 1.0; // Default Kp
static float Ki = 0.1; // Default Ki
static float Kd = 0.01; // Default Kd
static float integral = 0.0;
static float previous_error = 0.0;

// Structure to hold sensor data
typedef struct {
    char id[20];
    float temperature;
    int valid;
} sensor_data_t;

// Function prototypes
float read_temperature(const char *sensor_id);
float calculate_pid(float setpoint, float actual_temperature);
void set_pwm_duty_cycle(int duty_cycle);
void log_data(float average_temperature, float setpoint, float pid_output, int duty_cycle);
void signal_handler(int signal);
int discover_sensors(char sensor_ids[][20], int max_sensors);
float average_temperatures(const sensor_data_t *sensors, int num_sensors);

// Function to read temperature from a DS18B20 sensor
float read_temperature(const char *sensor_id) {
    char filepath[100];
    snprintf(filepath, sizeof(filepath), "%s%s/w1_slave", W1_DEVICES_DIR, sensor_id);

    int fd = open(filepath, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", filepath, strerror(errno));
        return NAN; // Indicate error
    }

    char buffer[256];
    ssize_t bytes_read = read(fd, buffer, sizeof(buffer) - 1);
    close(fd);

    if (bytes_read < 0) {
        fprintf(stderr, "Error reading %s: %s\n", filepath, strerror(errno));
        return NAN;
    }
    buffer[bytes_read] = '\0';

    char *crc_pos = strstr(buffer, "YES");
    if (crc_pos == NULL) {
        fprintf(stderr, "CRC check failed for sensor %s\n", sensor_id);
        return NAN;
    }

    char *temp_pos = strstr(buffer, "t=");
    if (temp_pos == NULL) {
        fprintf(stderr, "Temperature data not found for sensor %s\n", sensor_id);
        return NAN;
    }

    long temperature_raw = strtol(temp_pos + 2, NULL, 10);
    return (float)temperature_raw / 1000.0;
}

// Function to calculate PID output
float calculate_pid(float setpoint, float actual_temperature) {
    float error = setpoint - actual_temperature;
    integral += error * SAMPLE_INTERVAL;
    float derivative = (error - previous_error) / SAMPLE_INTERVAL;
    float output = Kp * error + Ki * integral + Kd * derivative;
    previous_error = error;
    return output;
}

// Function to set the PWM duty cycle
void set_pwm_duty_cycle(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 100) duty_cycle = 100;
    gpioPWM(PWM_GPIO, duty_cycle * 10); // pigpio uses 0-1000 for PWM range
}

// Function to log data to a file
void log_data(float average_temperature, float setpoint, float pid_output, int duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%d\n", timestamp, average_temperature, setpoint, pid_output, duty_cycle);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Function to discover DS18B20 sensors
int discover_sensors(char sensor_ids[][20], int max_sensors) {
    DIR *dir;
    struct dirent *ent;
    int count = 0;

    dir = opendir(W1_DEVICES_DIR);
    if (dir == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", W1_DEVICES_DIR, strerror(errno));
        return 0;
    }

    while ((ent = readdir(dir)) != NULL && count < max_sensors) {
        if (strncmp(ent->d_name, "28-", 3) == 0) {
            strncpy(sensor_ids[count], ent->d_name, sizeof(sensor_ids[count]) - 1);
            sensor_ids[count][sizeof(sensor_ids[count]) - 1] = '\0'; // Ensure null termination
            count++;
        }
    }
    closedir(dir);
    return count;
}

// Function to average temperatures from multiple sensors
float average_temperatures(const sensor_data_t *sensors, int num_sensors) {
    float sum = 0.0;
    int valid_count = 0;
    for (int i = 0; i < num_sensors; i++) {
        if (sensors[i].valid) {
            sum += sensors[i].temperature;
            valid_count++;
        }
    }
    if (valid_count > 0) {
        return sum / valid_count;
    } else {
        return NAN; // Indicate no valid readings
    }
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc != 5) {
        fprintf(stderr, "Usage: %s <setpoint_temperature> <Kp> <Ki> <Kd>\n", argv[0]);
        return 1;
    }

    setpoint_temperature = atof(argv[1]);
    Kp = atof(argv[2]);
    Ki = atof(argv[3]);
    Kd = atof(argv[4]);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetMode(PWM_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_GPIO, 1000); // Set PWM range to 0-1000

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    char sensor_ids[MAX_SENSORS][20];
    int num_sensors;

    // Main loop
    while (running) {
        num_sensors = discover_sensors(sensor_ids, MAX_SENSORS);
        if (num_sensors == 0) {
            fprintf(stderr, "No DS18B20 sensors found. Retrying in %d seconds...\n", SAMPLE_INTERVAL);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        sensor_data_t sensors[MAX_SENSORS];
        for (int i = 0; i < num_sensors; i++) {
            sensors[i].valid = 0; // Reset validity flag
            sensors[i].temperature = read_temperature(sensor_ids[i]);
            if (!isnan(sensors[i].temperature)) {
                sensors[i].valid = 1;
            }
        }

        float average_temperature = average_temperatures(sensors, num_sensors);

        if (isnan(average_temperature)) {
            fprintf(stderr, "No valid temperature readings. Retrying in %d seconds...\n", SAMPLE_INTERVAL);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        float pid_output = calculate_pid(setpoint_temperature, average_temperature);
        int duty_cycle = (int)pid_output; // Convert PID output to duty cycle (0-100)

        set_pwm_duty_cycle(duty_cycle);

        log_data(average_temperature, setpoint_temperature, pid_output, duty_cycle);

        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup
    set_pwm_duty_cycle(0); // Turn off heater
    gpioWrite(HEATER_GPIO, 0); // Ensure relay is off
    gpioTerminate(); // Terminate pigpio
    fclose(log_file); // Close log file

    return 0;
}

