#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define AHT20_ADDR 0x38
#define DEHUMIDIFIER_GPIO 17
#define HUMIDITY_THRESHOLD_HIGH 60.0
#define HUMIDITY_THRESHOLD_LOW 55.0
#define MEASURE_CMD 0xAC
#define MEASURE_ARG1 0x33
#define MEASURE_ARG2 0x00
#define INIT_CMD1 0xBE
#define INIT_ARG1 0x08
#define INIT_ARG2 0x00
#define INIT_DELAY 20 // milliseconds
#define MEASURE_DELAY 80 // milliseconds
#define RETRY_COUNT 3
#define POLL_INTERVAL 5 // seconds

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_aht20();
int read_humidity(float *humidity);
void control_dehumidifier(float humidity);
void log_data(float humidity);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Initialize AHT20 sensor
int init_aht20() {
    char buf[3];
    buf[0] = INIT_CMD1;
    buf[1] = INIT_ARG1;
    buf[2] = INIT_ARG2;

    if (i2cWriteDevice(i2c_handle, buf, 3) != 0) {
        fprintf(stderr, "Error writing initialization command: %d\n", i2c_handle);
        return -1;
    }
    gpioDelay(INIT_DELAY * 1000); // Delay in microseconds
    return 0;
}

// Read humidity from AHT20 sensor
int read_humidity(float *humidity) {
    char buf[3];
    char data[6];
    int retries = 0;

    buf[0] = MEASURE_CMD;
    buf[1] = MEASURE_ARG1;
    buf[2] = MEASURE_ARG2;

    while (retries < RETRY_COUNT) {
        if (i2cWriteDevice(i2c_handle, buf, 3) != 0) {
            fprintf(stderr, "Error writing measurement command (attempt %d): %d\n", retries + 1, i2c_handle);
            retries++;
            gpioDelay(10 * 1000); // 10ms delay
            continue;
        }

        gpioDelay(MEASURE_DELAY * 1000); // Delay in microseconds

        if (i2cReadDevice(i2c_handle, data, 6) != 6) {
            fprintf(stderr, "Error reading data (attempt %d): %d\n", retries + 1, i2c_handle);
            retries++;
            gpioDelay(10 * 1000); // 10ms delay
            continue;
        }

        // Check status bit (bit 7 of data[0])
        if (data[0] & 0x80) {
            fprintf(stderr, "Sensor busy (attempt %d)\n", retries + 1);
            retries++;
            gpioDelay(10 * 1000); // 10ms delay
            continue;
        }

        // Check calibration bit (bit 0 of data[0])
        if (!(data[0] & 0x08)) {
            fprintf(stderr, "Sensor not calibrated\n");
            return -1; // Not calibrated
        }

        // Convert data to humidity
        uint32_t humidity_raw = ((uint32_t)data[1] << 12) | ((uint32_t)data[2] << 4) | (data[3] >> 4);
        *humidity = ((float)humidity_raw / 0x100000) * 100;

        return 0; // Success
    }

    fprintf(stderr, "Failed to read humidity after %d retries\n", RETRY_COUNT);
    return -1; // Failure
}

// Control dehumidifier based on humidity
void control_dehumidifier(float humidity) {
    static int dehumidifier_on = 0; // Track dehumidifier state

    if (humidity > HUMIDITY_THRESHOLD_HIGH && !dehumidifier_on) {
        gpioWrite(DEHUMIDIFIER_GPIO, 1); // Turn on dehumidifier
        dehumidifier_on = 1;
        printf("Dehumidifier ON\n");
    } else if (humidity < HUMIDITY_THRESHOLD_LOW && dehumidifier_on) {
        gpioWrite(DEHUMIDIFIER_GPIO, 0); // Turn off dehumidifier
        dehumidifier_on = 0;
        printf("Dehumidifier OFF\n");
    }
}

// Log data to console
void log_data(float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Humidity: %.2f%%\n", timestamp, humidity);
}

