#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <syslog.h>
#include <signal.h>
#include <errno.h>
#include <stdint.h>

// Constants
#define I2C_DEVICE "/dev/i2c-1"
#define HTU21D_ADDR 0x40
#define MEASURE_CMD 0xE5
#define API_ENDPOINT "http://api.example.com/humidity"
#define SERVER_IP "127.0.0.1" // Replace with your server IP
#define SERVER_PORT 8080        // Replace with your server port
#define SLEEP_INTERVAL 60       // Seconds

// Global variables
int i2c_fd = -1;
int socket_fd = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_init(const char *device);
int htu21d_read_humidity(int fd, float *humidity);
uint8_t crc8(const uint8_t *data, int len);
int http_post(const char *url, const char *data);
void signal_handler(int sig);
void cleanup();

// I2C initialization function
int i2c_init(const char *device) {
  int fd = open(device, O_RDWR);
  if (fd < 0) {
    syslog(LOG_ERR, "Failed to open I2C device: %s", strerror(errno));
    return -1;
  }

  if (ioctl(fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
    syslog(LOG_ERR, "Failed to set I2C slave address: %s", strerror(errno));
    close(fd);
    return -1;
  }

  return fd;
}

// HTU21D read humidity function
int htu21d_read_humidity(int fd, float *humidity) {
  uint8_t cmd = MEASURE_CMD;
  uint8_t data[3];
  int retries = 3;

  while (retries > 0) {
    if (write(fd, &cmd, 1) != 1) {
      syslog(LOG_ERR, "Failed to write to I2C device: %s", strerror(errno));
      retries--;
      sleep(1);
      continue;
    }

    usleep(100000); // Wait for measurement (at least 50ms)

    if (read(fd, data, 3) != 3) {
      syslog(LOG_ERR, "Failed to read from I2C device: %s", strerror(errno));
      retries--;
      sleep(1);
      continue;
    }

    // CRC check
    if (crc8(data, 2) != data[2]) {
      syslog(LOG_ERR, "CRC check failed");
      retries--;
      sleep(1);
      continue;
    }

    // Convert to humidity
    uint16_t raw_humidity = (data[0] << 8) | data[1];
    *humidity = -6.0 + 125.0 * (raw_humidity / 65536.0);
    return 0; // Success
  }

  syslog(LOG_ERR, "Failed to read humidity after multiple retries");
  return -1; // Failure
}

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
  uint8_t crc = 0x00;
  for (int i = 0; i < len; i++) {
    crc ^= data[i];
    for (int j = 0; j < 8; j++) {
      if (crc & 0x80) {
        crc = (crc << 1) ^ 0x131; // Polynomial X^8 + X^5 + X^4 + 1
      } else {
        crc <<= 1;
      }
    }
  }
  return crc;
}

// HTTP POST function
int http_post(const char *url, const char *data) {
  int sock = socket(AF_INET, SOCK_STREAM, 0);
  if (sock < 0) {
    syslog(LOG_ERR, "Failed to create socket: %s", strerror(errno));
    return -1;
  }

  struct sockaddr_in server_addr;
  memset(&server_addr, 0, sizeof(server_addr));
  server_addr.sin_family = AF_INET;
  server_addr.sin_port = htons(SERVER_PORT);
  if (inet_pton(AF_INET, SERVER_IP, &server_addr.sin_addr) <= 0) {
    syslog(LOG_ERR, "Invalid address/ Address not supported");
    close(sock);
    return -1;
  }

  if (connect(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
    syslog(LOG_ERR, "Failed to connect to server: %s", strerror(errno));
    close(sock);
    return -1;
  }

  char request[512];
  snprintf(request, sizeof(request), 
           "POST %s HTTP/1.1\r\n" 
           "Host: %s\r\n" 
           "Content-Type: application/json\r\n" 
           "Content-Length: %zu\r\n" 
           "Connection: close\r\n" 
           "\r\n" 
           "%s", 
           url, SERVER_IP, strlen(data), data);

  if (send(sock, request, strlen(request), 0) < 0) {
    syslog(LOG_ERR, "Failed to send data: %s", strerror(errno));
    close(sock);
    return -1;
  }

  char buffer[1024];
  ssize_t bytes_received = recv(sock, buffer, sizeof(buffer) - 1, 0);
  if (bytes_received > 0) {
    buffer[bytes_received] = '\0';
    syslog(LOG_INFO, "Server response: %s", buffer);
  } else {
    syslog(LOG_ERR, "Failed to receive response: %s", strerror(errno));
  }

  close(sock);
  return 0;
}

// Signal handler function
void signal_handler(int sig) {
  syslog(LOG_INFO, "Signal received, terminating...");
  terminate = 1;
}

// Cleanup function
void cleanup() {
  if (i2c_fd != -1) {
    close(i2c_fd);
    syslog(LOG_INFO, "I2C device closed");
  }
  if (socket_fd != -1) {
    close(socket_fd);
    syslog(LOG_INFO, "Socket closed");
  }
  closelog();
}

int main() {
  openlog("humidity_sensor", LOG_PID | LOG_CONS, LOG_USER);
  syslog(LOG_INFO, "Starting humidity sensor program");

  // Register signal handlers
  signal(SIGINT, signal_handler);
  signal(SIGTERM, signal_handler);

  // Initialize I2C
  i2c_fd = i2c_init(I2C_DEVICE);
  if (i2c_fd < 0) {
    syslog(LOG_ERR, "I2C initialization failed, exiting");
    cleanup();
    return 1;
  }
  syslog(LOG_INFO, "I2C initialized");

  while (!terminate) {
    float humidity;
    if (htu21d_read_humidity(i2c_fd, &humidity) == 0) {
      syslog(LOG_INFO, "Humidity: %.2f%%", humidity);

      // Create JSON payload
      char json_data[64];
      snprintf(json_data, sizeof(json_data), "{\"humidity\": %.2f}", humidity);

      // Post data to API
      if (http_post("/humidity", json_data) != 0) {
        syslog(LOG_ERR, "HTTP POST failed");
      }
    } else {
      syslog(LOG_ERR, "Failed to read humidity");
    }

    sleep(SLEEP_INTERVAL);
  }

  cleanup();
  return 0;
}

