// BMP280 I2C address
#define BMP280_I2C_ADDR 0x76

// BMP280 registers
#define BMP280_REG_CHIPID 0xD0
#define BMP280_REG_CALIB_00 0x88
#define BMP280_REG_CALIB_25 0xA1
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_DATA_PRESS_MSB 0xF7

// Oversampling settings
#define BMP280_OVERSAMPLING_TEMP 1 // 1x oversampling
#define BMP280_OVERSAMPLING_PRESS 1 // 1x oversampling
#define BMP280_MODE_FORCED 0x01    // Forced mode

// Pressure thresholds
#define PRESSURE_THRESHOLD_HIGH 1020.0
#define PRESSURE_THRESHOLD_LOW 980.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Calibration data structure
typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_data;

bmp280_calib_data calib;

// Function prototypes
int init_bmp280();
int read_calibration_data();
int read_raw_data(int32_t *temperature, int32_t *pressure);
double compensate_temperature(int32_t raw_temperature);
double compensate_pressure(int32_t raw_pressure, int32_t raw_temperature);
void log_pressure_threshold_breach(double pressure);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize BMP280 sensor
int init_bmp280() {
    int retries = 3;
    int chip_id;

    while (retries > 0) {
        // Open I2C bus
        i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
        if (i2c_handle < 0) {
            fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
            retries--;
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

        // Verify chip ID
        chip_id = i2cReadByteData(i2c_handle, BMP280_REG_CHIPID);
        if (chip_id < 0) {
            fprintf(stderr, "Error reading chip ID: %d\n", chip_id);
            i2cClose(i2c_handle);
            retries--;
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

        if (chip_id != 0x58) {
            fprintf(stderr, "Incorrect chip ID: 0x%02X\n", chip_id);
            i2cClose(i2c_handle);
            retries--;
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

        printf("BMP280 initialized successfully with chip ID 0x%02X\n", chip_id);
        return 0; // Success
    }

    fprintf(stderr, "Failed to initialize BMP280 after multiple retries.\n");
    return -1; // Failure
}

// Read calibration data from BMP280
