#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define AHT20_ADDR 0x38
#define PIR_GPIO 17
#define CSV_FILE_PATH "/home/pi/sensor_data.csv"

// Global variables
int i2c_handle_tmp117 = -1;
int i2c_handle_aht20 = -1;
FILE *csv_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c(int bus, int addr);
int read_tmp117(int handle, float *temperature);
int read_aht20(int handle, float *humidity, float *temperature);
int read_pir(int gpio);
int log_data(FILE *fp, float temperature, float humidity, int motion_detected);
void signal_handler(int signal);
int check_sensor_presence(int handle);

// Signal handler
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %s\n", addr, strerror(errno));
        return -1;
    }
    return handle;
}

// Read TMP117 temperature
int read_tmp117(int handle, float *temperature) {
    char buf[2];
    int retries = 3;
    int delay_ms = 10;

    while (retries > 0) {
        if (i2cReadDevice(handle, buf, 2) == 2) {
            int16_t raw_temp = (buf[0] << 8) | buf[1];
            *temperature = raw_temp * 0.0078125;
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading TMP117: %s, retries remaining: %d\n", strerror(errno), retries);
            retries--;
            gpioDelay(delay_ms * 1000); // pigpio delay in microseconds
            delay_ms *= 2; // Exponential backoff
        }
    }
    return -1; // Failure after retries
}

// Read AHT20 humidity and temperature
int read_aht20(int handle, float *humidity, float *temperature) {
    char init_cmd[3] = {0xBE, 0x08, 0x00};
    char measure_cmd[3] = {0xAC, 0x33, 0x00};
    char buf[7];
    int retries = 3;
    int delay_ms = 10;

    // Initialize AHT20
    if (i2cWriteDevice(handle, init_cmd, 3) != 3) {
        fprintf(stderr, "Error initializing AHT20: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(20 * 1000); // Wait for initialization

    while (retries > 0) {
        if (i2cWriteDevice(handle, measure_cmd, 3) != 3) {
            fprintf(stderr, "Error sending measure command to AHT20: %s, retries remaining: %d\n", strerror(errno), retries);
            retries--;
            gpioDelay(delay_ms * 1000);
            delay_ms *= 2;
            continue;
        }

        gpioDelay(80 * 1000); // Wait for measurement

        if (i2cReadDevice(handle, buf, 7) == 7) {
            if (buf[0] & 0x80) {
                fprintf(stderr, "AHT20 busy\n");
                retries--;
                gpioDelay(delay_ms * 1000);
                delay_ms *= 2;
                continue;
            }

            unsigned int humidity_raw = ((unsigned int)buf[1] << 12) | ((unsigned int)buf[2] << 4) | (buf[3] >> 4);
            unsigned int temperature_raw = ((unsigned int)buf[3] & 0x0F) << 16 | ((unsigned int)buf[4] << 8) | buf[5];

            *humidity = ((float)humidity_raw / 0x100000) * 100;
            *temperature = ((float)temperature_raw / 0x100000) * 200 - 50;

            return 0; // Success
        } else {
            fprintf(stderr, "Error reading AHT20 data: %s, retries remaining: %d\n", strerror(errno), retries);
            retries--;
            gpioDelay(delay_ms * 1000);
            delay_ms *= 2;
        }
    }
    return -1; // Failure after retries
}

// Read PIR sensor
int read_pir(int gpio) {
    return gpioRead(gpio);
}

// Log data to CSV file
int log_data(FILE *fp, float temperature, float humidity, int motion_detected) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%.2f,%d\n", timestamp, temperature, humidity, motion_detected) < 0) {
        fprintf(stderr, "Error writing to CSV file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp); // Ensure data is written immediately
    return 0;
}

// Check sensor presence
int check_sensor_presence(int handle) {
    char buf[2];
    if (i2cReadDevice(handle, buf, 2) == 2) {
        return 1; // Sensor present
    } else {
        return 0; // Sensor not present
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set PIR GPIO as input
    gpioSetMode(PIR_GPIO, PI_INPUT);

    // Initialize I2C
    i2c_handle_tmp117 = init_i2c(I2C_BUS, TMP117_ADDR);
    i2c_handle_aht20 = init_i2c(I2C_BUS, AHT20_ADDR);

    if (i2c_handle_tmp117 < 0 || i2c_handle_aht20 < 0) {
        gpioTerminate();
        return 1;
    }

    // Check sensor presence
    if (!check_sensor_presence(i2c_handle_tmp117)) {
        fprintf(stderr, "Warning: TMP117 sensor not present\n");
    }
    if (!check_sensor_presence(i2c_handle_aht20)) {
        fprintf(stderr, "Warning: AHT20 sensor not present\n");
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE_PATH, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        i2cClose(i2c_handle_tmp117);
        i2cClose(i2c_handle_aht20);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "Timestamp,Temperature(C),Humidity(%%),MotionDetected\n");
    }

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float temperature_tmp117, humidity_aht20, temperature_aht20;
    int motion_detected;

    // Main loop
    while (program_running) {
        // Read sensor data
        int tmp117_status = read_tmp117(i2c_handle_tmp117, &temperature_tmp117);
        int aht20_status = read_aht20(i2c_handle_aht20, &humidity_aht20, &temperature_aht20);
        motion_detected = read_pir(PIR_GPIO);

        // Log data
        if (tmp117_status == 0 && aht20_status == 0) {
            log_data(csv_file, temperature_tmp117, humidity_aht20, motion_detected);
        } else {
            fprintf(stderr, "Error reading sensor data, skipping log.\n");
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Cleanup
