#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// Define CPU load file
#define CPU_STAT_FILE "/proc/stat"

// Define CPU load thresholds and corresponding colors
#define LOAD_0_RED   0
#define LOAD_0_GREEN 255
#define LOAD_0_BLUE  0

#define LOAD_50_RED  255
#define LOAD_50_GREEN 255
#define LOAD_50_BLUE 0

#define LOAD_100_RED 255
#define LOAD_100_GREEN 0
#define LOAD_100_BLUE 0

// Define PWM frequency
#define PWM_FREQUENCY 1000 // Hz

// Define sampling interval
#define SAMPLING_INTERVAL_MS 500

// Global variables
static volatile int running = 1;
static int last_user = 0;
static int last_nice = 0;
static int last_system = 0;
static int last_idle = 0;
static int last_iowait = 0;
static int last_irq = 0;
static int last_softirq = 0;
static int last_steal = 0;

// Function prototypes
int read_cpu_stats(int *user, int *nice, int *system, int *idle, int *iowait, int *irq, int *softirq, int *steal);
float calculate_cpu_load(int user, int nice, int system, int idle, int iowait, int irq, int softirq, int steal, int last_user, int last_nice, int last_system, int last_idle, int last_iowait, int last_irq, int last_softirq, int last_steal);
void map_cpu_load_to_color(float cpu_load, int *red, int *green, int *blue);
void set_led_color(int red, int green, int blue);
void signal_handler(int signal);

// Function to read CPU statistics from /proc/stat
int read_cpu_stats(int *user, int *nice, int *system, int *idle, int *iowait, int *irq, int *softirq, int *steal) {
    FILE *fp;
    char line[256];
    int ret = 0;

    fp = fopen(CPU_STAT_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open %s\n", CPU_STAT_FILE);
        return -1;
    }

    // Read the first line of the file
    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error: Could not read from %s\n", CPU_STAT_FILE);
        fclose(fp);
        return -1;
    }

    // Parse the line
    if (sscanf(line, "cpu  %d %d %d %d %d %d %d %d",
               user, nice, system, idle, iowait, irq, softirq, steal) != 8) {
        fprintf(stderr, "Error: Could not parse CPU stats from %s\n", CPU_STAT_FILE);
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to calculate CPU load
float calculate_cpu_load(int user, int nice, int system, int idle, int iowait, int irq, int softirq, int steal, int last_user, int last_nice, int last_system, int last_idle, int last_iowait, int last_irq, int last_softirq, int last_steal) {
    int total_diff = user + nice + system + idle + iowait + irq + softirq + steal -
                     (last_user + last_nice + last_system + last_idle + last_iowait + last_irq + last_softirq + last_steal);

    int idle_diff = idle + iowait -
                    (last_idle + last_iowait);

    float cpu_load = 1.0 - ((float)idle_diff / (float)total_diff);

    // Clamp CPU load to 0-1 range
    if (cpu_load < 0.0) cpu_load = 0.0;
    if (cpu_load > 1.0) cpu_load = 1.0;

    return cpu_load;
}

// Function to map CPU load to RGB color values
void map_cpu_load_to_color(float cpu_load, int *red, int *green, int *blue) {
    if (cpu_load <= 0.5) {
        // Green to Yellow
        *red = (int)(255.0 * (cpu_load / 0.5));
        *green = 255;
        *blue = 0;
    } else {
        // Yellow to Red
        *red = 255;
        *green = (int)(255.0 * (1.0 - ((cpu_load - 0.5) / 0.5)));
        *blue = 0;
    }
}

// Function to set the LED color using PWM
void set_led_color(int red, int green, int blue) {
    gpioPWM(RED_PIN, 255 - red);   // Common anode, so invert the value
    gpioPWM(GREEN_PIN, 255 - green); // Common anode, so invert the value
    gpioPWM(BLUE_PIN, 255 - blue);  // Common anode, so invert the value
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
    set_led_color(0, 0, 0); // Turn off the LED
    gpioTerminate();         // Terminate pigpio
    exit(0);
}

int main() {
    int user, nice, system, idle, iowait, irq, softirq, steal;
    float cpu_load;
    int red, green, blue;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Read CPU statistics
        if (read_cpu_stats(&user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal) == 0) {
            // Calculate CPU load
            cpu_load = calculate_cpu_load(user, nice, system, idle, iowait, irq, softirq, steal, last_user, last_nice, last_system, last_idle, last_iowait, last_irq, last_softirq, last_steal);

            // Map CPU load to color
            map_cpu_load_to_color(cpu_load, &red, &green, &blue);

            // Set LED color
            set_led_color(red, green, blue);

            // Update last CPU stats
            last_user = user;
            last_nice = nice;
            last_system = system;
            last_idle = idle;
            last_iowait = iowait;
            last_irq = irq;
            last_softirq = softirq;
            last_steal = steal;
        } else {
            fprintf(stderr, "Error: Failed to read CPU stats\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLING_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Clean up and exit
    set_led_color(0, 0, 0); // Turn off the LED
    gpioTerminate();         // Terminate pigpio
    return 0;
}

