    gpioPWM(RED_PIN, 255 - red);   // Common anode, so invert the value
    gpioPWM(GREEN_PIN, 255 - green); // Common anode, so invert the value
    gpioPWM(BLUE_PIN, 255 - blue);  // Common anode, so invert the value
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
    set_led_color(0, 0, 0); // Turn off the LED
    gpioTerminate();         // Terminate pigpio
    exit(0);
}

int main() {
    int user, nice, system, idle, iowait, irq, softirq, steal;
    float cpu_load;
    int red, green, blue;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Read CPU statistics
        if (read_cpu_stats(&user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal) == 0) {
            // Calculate CPU load
            cpu_load = calculate_cpu_load(user, nice, system, idle, iowait, irq, softirq, steal, last_user, last_nice, last_system, last_idle, last_iowait, last_irq, last_softirq, last_steal);

            // Map CPU load to color
            map_cpu_load_to_color(cpu_load, &red, &green, &blue);

            // Set LED color
            set_led_color(red, green, blue);

            // Update last CPU stats
            last_user = user;
            last_nice = nice;
            last_system = system;
            last_idle = idle;
            last_iowait = iowait;
            last_irq = irq;
            last_softirq = softirq;
            last_steal = steal;
        } else {
            fprintf(stderr, "Error: Failed to read CPU stats\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLING_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Clean up and exit
    set_led_color(0, 0, 0); // Turn off the LED
    gpioTerminate();         // Terminate pigpio
    return 0;
}

