#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

// BMP280 I2C address
#define BMP280_I2C_ADDR 0x76

// BMP280 registers
#define BMP280_REG_CHIPID 0xD0
#define BMP280_REG_CALIB_00 0x88
#define BMP280_REG_DATA_00 0xF7
#define BMP280_REG_CTRL_MEAS 0xF4

// Calibration data structure
typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_data;

// Global variables
int i2c_handle;
int udp_socket;
struct sockaddr_in server_addr;
bmp280_calib_data calib;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (udp_socket >= 0) {
        close(udp_socket);
    }
    gpioTerminate();
    exit(0);
}

// Function to read calibration data from BMP280
int read_calibration_data(int i2c_handle, bmp280_calib_data *calib) {
    uint8_t data[24];
    if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_CALIB_00, (char *)data, 24) != 24) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    calib->dig_T1 = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
    calib->dig_T2 = (int16_t)data[2] | ((int16_t)data[3] << 8);
    calib->dig_T3 = (int16_t)data[4] | ((int16_t)data[5] << 8);
    calib->dig_P1 = (uint16_t)data[6] | ((uint16_t)data[7] << 8);
    calib->dig_P2 = (int16_t)data[8] | ((int16_t)data[9] << 8);
    calib->dig_P3 = (int16_t)data[10] | ((int16_t)data[11] << 8);
    calib->dig_P4 = (int16_t)data[12] | ((int16_t)data[13] << 8);
    calib->dig_P5 = (int16_t)data[14] | ((int16_t)data[15] << 8);
    calib->dig_P6 = (int16_t)data[16] | ((int16_t)data[17] << 8);
    calib->dig_P7 = (int16_t)data[18] | ((int16_t)data[19] << 8);
    calib->dig_P8 = (int16_t)data[20] | ((int16_t)data[21] << 8);
    calib->dig_P9 = (int16_t)data[22] | ((int16_t)data[23] << 8);

    return 0;
}

// Function to read raw temperature and pressure data from BMP280
int read_raw_data(int i2c_handle, int32_t *raw_temperature, int32_t *raw_pressure) {
    uint8_t data[6];
    if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_DATA_00, (char *)data, 6) != 6) {
        fprintf(stderr, "Error reading raw data\n");
        return -1;
    }

    *raw_pressure = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | ((int32_t)data[2] >> 4);
    *raw_temperature = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | ((int32_t)data[5] >> 4);

    return 0;
}

// Function to compensate temperature
double compensate_temperature(int32_t raw_temperature, bmp280_calib_data calib, int32_t *t_fine) {
    double var1 = (raw_temperature / 16384.0 - calib.dig_T1 / 1024.0) * calib.dig_T2;
    double var2 = ((raw_temperature / 131072.0 - calib.dig_T1 / 8192.0) *
                   (raw_temperature / 131072.0 - calib.dig_T1 / 8192.0)) *
                  calib.dig_T3;
    *t_fine = (int32_t)(var1 + var2);
    double T = (*t_fine) / 5120.0;
    return T;
}

// Function to compensate pressure
double compensate_pressure(int32_t raw_pressure, int32_t t_fine, bmp280_calib_data calib) {
    double var1 = (t_fine / 2.0) - 64000.0;
    double var2 = var1 * var1 * calib.dig_P6 / 32768.0;
    var2 = var2 + var1 * calib.dig_P5 * 2.0;
    var2 = (var2 / 4.0) + (calib.dig_P4 * 65536.0);
    var1 = (calib.dig_P3 * var1 * var1 / 524288.0 + calib.dig_P2 * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * calib.dig_P1;

    if (var1 == 0)
    {
        return 0;
    }

    double p = 1048576.0 - raw_pressure;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = calib.dig_P9 * p * p / 2147483648.0;
    var2 = p * calib.dig_P8 / 32768.0;
    p = p + (var1 + var2 + calib.dig_P7) / 16.0;

    return p;
}

// Function to format data as JSON string
char* format_json(double temperature, double pressure) {
    char *json_string = (char*)malloc(100 * sizeof(char)); // Allocate memory for the JSON string
    if (json_string == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    sprintf(json_string, "{\"temperature\": %.2f, \"pressure\": %.2f}", temperature, pressure);
    return json_string;
}

// Function to send data over UDP
int send_udp_data(const char *data) {
    if (sendto(udp_socket, data, strlen(data), 0, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        fprintf(stderr, "Error sending UDP data\n");
        return -1;
    }
    return 0;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Verify chip ID
    int chip_id = i2cReadByteData(i2c_handle, BMP280_REG_CHIPID);
    if (chip_id != 0x58) {
        fprintf(stderr, "Incorrect chip ID: 0x%x\n", chip_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(i2c_handle, &calib) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure UDP socket
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        fprintf(stderr, "Error creating UDP socket\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(5000);
    if (inet_pton(AF_INET, "192.168.1.100", &server_addr.sin_addr) <= 0) {
        fprintf(stderr, "Invalid address/ Address not supported \n");
        close(udp_socket);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        int32_t raw_temperature, raw_pressure, t_fine;
        double temperature, pressure;
        char *json_string;

        // Set forced mode
        if (i2cWriteByteData(i2c_handle, BMP280_REG_CTRL_MEAS, 0x27) < 0) {
            fprintf(stderr, "Error setting forced mode\n");
            break;
        }

        // Wait for measurement to complete (adjust delay as needed)
        gpioDelay(100); // 100 ms

        // Read raw data
        if (read_raw_data(i2c_handle, &raw_temperature, &raw_pressure) != 0) {
            break;
        }

        // Compensate temperature and pressure
        temperature = compensate_temperature(raw_temperature, calib, &t_fine);
        pressure = compensate_pressure(raw_pressure, t_fine, calib);

        // Format data as JSON
        json_string = format_json(temperature, pressure);
        if (json_string == NULL) {
            break;
        }

        // Send data over UDP
        if (send_udp_data(json_string) != 0) {
            free(json_string);
            break;
        }

        free(json_string);

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup
    close(udp_socket);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

