#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define FAN_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define SPI_MODE 0
#define BUFFER_SIZE 20

// Temperature thresholds and duty cycle mappings
#define TEMP_25 25.0
#define TEMP_40 40.0
#define TEMP_60 60.0

#define DUTY_0 0
#define DUTY_50 50
#define DUTY_200 200
#define DUTY_255 255

// Structure for circular buffer entries
typedef struct {
    time_t timestamp;
    float temperature;
    int duty_cycle;
} BufferEntry;

// Circular buffer structure
typedef struct {
    BufferEntry entries[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Global variables
int spi_handle;
CircularBuffer buffer;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_max31855(float *temperature);
int process_temperature(float temperature, int *duty_cycle);
void update_fan(int duty_cycle);
void add_to_buffer(float temperature, int duty_cycle);
void print_buffer();
void signal_handler(int signal);

// Function to initialize the circular buffer
void init_buffer(CircularBuffer *buffer) {
    buffer->head = 0;
    buffer->count = 0;
}

// Function to add a new entry to the circular buffer
void add_to_buffer(float temperature, int duty_cycle) {
    time_t now = time(NULL);
    buffer->entries[buffer->head].timestamp = now;
    buffer->entries[buffer->head].temperature = temperature;
    buffer->entries[buffer->head].duty_cycle = duty_cycle;

    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Function to print the contents of the circular buffer
void print_buffer() {
    int i, index;
    printf("\n--- Circular Buffer Contents ---\n");
    for (i = 0; i < buffer.count; i++) {
        index = (buffer.head - buffer.count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char timestamp_str[30];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", localtime(&buffer.entries[index].timestamp));
        printf("Timestamp: %s, Temperature: %.2f°C, Duty Cycle: %d\n",
               timestamp_str, buffer.entries[index].temperature, buffer.entries[index].duty_cycle);
    }
    printf("--- End of Buffer ---\n");
}

// Function to read temperature from MAX31855
int read_max31855(float *temperature) {
    char tx_buf[4] = {0, 0, 0, 0};
    char rx_buf[4];
    int status;

    status = spiXfer(spi_handle, tx_buf, rx_buf, 4);
    if (status != 0) {
        fprintf(stderr, "Error during SPI transfer: %d\n", status);
        return -1; // Indicate error
    }

    // Combine the received bytes into a 32-bit integer
    uint32_t raw_data = ((uint32_t)rx_buf[0] << 24) | ((uint32_t)rx_buf[1] << 16) | ((uint32_t)rx_buf[2] << 8) | (uint32_t)rx_buf[3];

    // Check for fault bits
    if (raw_data & 0x00010000) {
