#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling setting (OSS)
#define BMP180_OSS 3

// GPIO pin for interrupt
#define INTERRUPT_GPIO 2

// Global variables
static int i2c_handle;
static FILE *log_file;
static volatile int logging_enabled = 0;
static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

// Function prototypes
int read_calibration_data(int i2c_handle);
int read_raw_temperature(int i2c_handle, int *raw_temperature);
int read_raw_pressure(int i2c_handle, int *raw_pressure);
double calculate_temperature(int raw_temperature);
double calculate_pressure(int raw_pressure, int raw_temperature);
void interrupt_handler(int gpio, int level, uint32_t tick, void *user);
void signal_handler(int signal);
int log_data(double temperature, double pressure);

// Function to read a 16-bit value from the I2C device
int16_t read_i2c_word(int i2c_handle, uint8_t reg)
{
    char buf[2];
    if (i2cWriteDevice(i2c_handle, &reg, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return -1;
    }
    return (int16_t)((buf[0] << 8) | buf[1]);
}

// Function to read an unsigned 16-bit value from the I2C device
uint16_t read_i2c_uword(int i2c_handle, uint8_t reg)
{
    char buf[2];
    if (i2cWriteDevice(i2c_handle, &reg, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return -1;
    }
    return (uint16_t)((buf[0] << 8) | buf[1]);
}

// Function to read calibration data from the BMP180
int read_calibration_data(int i2c_handle) {
    ac1 = read_i2c_word(i2c_handle, BMP180_REG_CAL_AC1);
    ac2 = read_i2c_word(i2c_handle, BMP180_REG_CAL_AC2);
    ac3 = read_i2c_word(i2c_handle, BMP180_REG_CAL_AC3);
    ac4 = read_i2c_uword(i2c_handle, BMP180_REG_CAL_AC4);
    ac5 = read_i2c_uword(i2c_handle, BMP180_REG_CAL_AC5);
    ac6 = read_i2c_uword(i2c_handle, BMP180_REG_CAL_AC6);
    b1 = read_i2c_word(i2c_handle, BMP180_REG_CAL_B1);
    b2 = read_i2c_word(i2c_handle, BMP180_REG_CAL_B2);
    mb = read_i2c_word(i2c_handle, BMP180_REG_CAL_MB);
    mc = read_i2c_word(i2c_handle, BMP180_REG_CAL_MC);
    md = read_i2c_word(i2c_handle, BMP180_REG_CAL_MD);

    if (ac1 == -1 || ac2 == -1 || ac3 == -1 || ac4 == -1 || ac5 == -1 || ac6 == -1 ||
        b1 == -1 || b2 == -1 || mb == -1 || mc == -1 || md == -1) {
        fprintf(stderr, "Error reading calibration data.\n");
        return -1;
    }

    return 0;
}

// Function to read raw temperature data from the BMP180
int read_raw_temperature(int i2c_handle, int *raw_temperature) {
    char buf[1];
    buf[0] = BMP180_REG_CONTROL;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }
    buf[0] = 0x2E; // Temperature measurement command
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }
    gpioDelay(5000); // Wait 4.5ms (minimum)

    buf[0] = BMP180_REG_MSB;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }
    char data[2];
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return -1;
    }

    *raw_temperature = (data[0] << 8) | data[1];
    return 0;
}

// Function to read raw pressure data from the BMP180
int read_raw_pressure(int i2c_handle, int *raw_pressure) {
    char buf[1];
    buf[0] = BMP180_REG_CONTROL;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }
    buf[0] = 0x34 + (BMP180_OSS << 6); // Pressure measurement command
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }
    gpioDelay(26000); // Wait 25.5ms (OSS=3)

    buf[0] = BMP180_REG_MSB;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }
    char data[3];
    if (i2cReadDevice(i2c_handle, data, 3) != 3) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return -1;
    }

    *raw_pressure = ((data[0] << 16) | (data[1] << 8) | data[2]) >> (8 - BMP180_OSS);
    return 0;
}

// Function to calculate temperature in Celsius
double calculate_temperature(int raw_temperature) {
    long x1 = (((long)raw_temperature - (long)ac6) * (long)ac5) >> 15;
    long x2 = ((long)mc << 11) / (x1 + md);
    long b5 = x1 + x2;
    double temperature = ((b5 + 8) >> 4) / 10.0;
    return temperature;
}

// Function to calculate pressure in Pascals
double calculate_pressure(int raw_pressure, int raw_temperature) {
    long x1 = (((long)raw_temperature - (long)ac6) * (long)ac5) >> 15;
    long x2 = ((long)mc << 11) / (x1 + md);
    long b5 = x1 + x2;

    long b6 = b5 - 4000;
    long x3 = ((long)b2 * (b6 * b6) >> 12) >> 11;
    long x4 = ((long)ac2 * b6) >> 11;
    long b3 = (((((long)ac1) * 4 + x3) << BMP180_OSS) + 2) >> 2;

    unsigned long x1_p = ((long)ac3 * b6) >> 13;
    unsigned long x2_p = ((long)b1 * ((b6 * b6) >> 12)) >> 16;
    unsigned long x3_p = ((x1_p + x2_p) + 2) >> 2;
    unsigned long b4 = ((unsigned long)ac4 * (x3_p + 32768)) >> 15;
    unsigned long b7 = ((unsigned long)raw_pressure - b3) * (50000 >> BMP180_OSS);

    long p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    double pressure = p + ((x1 + x2 + 3791) >> 4);

    return pressure;
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user) {
    logging_enabled = !logging_enabled;
    printf("Data logging %s\n", logging_enabled ? "enabled" : "disabled");
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Function to log data to a file
int log_data(double temperature, double pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, pressure);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(i2c_handle) != 0) {
        fprintf(stderr, "Failed to read calibration data. Exiting.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("altitude_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure GPIO2 as input with pull-up resistor
    gpioSetMode(INTERRUPT_GPIO, PI_INPUT);
    gpioSetPullUpDown(INTERRUPT_GPIO, PI_PUD_UP);

    // Set interrupt handler for falling edge
    if (gpioSetISRFuncEx(INTERRUPT_GPIO, FALLING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting interrupt handler.\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int raw_temperature, raw_pressure;
    double temperature, pressure;

    // Main loop
    while (1) {
        if (logging_enabled) {
            // Read raw temperature and pressure
            if (read_raw_temperature(i2c_handle, &raw_temperature) == 0 &&
                read_raw_pressure(i2c_handle, &raw_pressure) == 0) {

                // Calculate temperature and pressure
                temperature = calculate_temperature(raw_temperature);
                pressure = calculate_pressure(raw_pressure, raw_temperature);

                // Log the data
                if (log_data(temperature, pressure) != 0) {
                    fprintf(stderr, "Error logging data.\n");
                }
            } else {
                fprintf(stderr, "Error reading sensor data.\n");
            }
        }
        sleep(1); // Wait 1 second
    }

    // The following lines will never be reached due to the infinite loop.
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

