#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <errno.h>
#include <math.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define CS_PIN 8 // GPIO8 (CE0)
#define RTD_NOMINAL 100.0
#define REF_RESISTOR 430.0
#define LOG_FILE "rtd_log.csv"

// MAX31865 Registers
#define MAX31865_CONFIG_REG 0x00
#define MAX31865_RTD_MSB_REG 0x01
#define MAX31865_RTD_LSB_REG 0x02
#define MAX31865_FAULT_REG 0x07

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *cs_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int max31865_init(void);
int read_max31865_data(uint16_t *rtd_raw, uint8_t *fault_status);
double calculate_temperature(uint16_t rtd_raw);
int log_data(double temperature);
void signal_handler(int sig);
void cleanup(void);

// SPI Initialization
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Set SPI speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// SPI Transfer
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// MAX31865 Initialization
int max31865_init(void) {
    uint8_t tx_buf[2];
    uint8_t rx_buf[2];

    // Configure for 3-wire RTD mode, bias enabled, auto conversion
    tx_buf[0] = MAX31865_CONFIG_REG | 0x80; // Write command
    tx_buf[1] = 0xC2; // 3-wire, bias, auto conversion

    if (spi_transfer(tx_buf, rx_buf, 2) < 0) {
        fprintf(stderr, "Error writing to config register\n");
        return -1;
    }

    return 0;
}

// Read MAX31865 Data
int read_max31865_data(uint16_t *rtd_raw, uint8_t *fault_status) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // Read RTD MSB and LSB registers
    tx_buf[0] = MAX31865_RTD_MSB_REG | 0x00; // Read command
    tx_buf[1] = 0x00; // Dummy data
    tx_buf[2] = 0x00; // Dummy data

    if (spi_transfer(tx_buf, rx_buf, 3) < 0) {
        fprintf(stderr, "Error reading RTD data\n");
        return -1;
    }

    *rtd_raw = ((uint16_t)rx_buf[1] << 8) | rx_buf[2];
    *rtd_raw = (*rtd_raw >> 1) & 0x3FFF; // Remove fault bit

    // Read Fault Register
    tx_buf[0] = MAX31865_FAULT_REG | 0x00; // Read command
    tx_buf[1] = 0x00; // Dummy data
    tx_buf[2] = 0x00; // Dummy data

    if (spi_transfer(tx_buf, rx_buf, 3) < 0) {
        fprintf(stderr, "Error reading fault register\n");
        return -1;
    }

    *fault_status = rx_buf[1];

    return 0;
}

// Calculate Temperature
double calculate_temperature(uint16_t rtd_raw) {
    double rtd_resistance = ((double)rtd_raw / 32768.0) * REF_RESISTOR;
    double temperature = (rtd_resistance / RTD_NOMINAL - 1) / 0.003923; // Linear approximation
    return temperature;
}

// Log Data
int log_data(double temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
        fprintf(log_file, "Timestamp,Temperature (C)\n"); // CSV header
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk

    return 0;
}

// Signal Handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup
void cleanup(void) {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (cs_line != NULL) {
        gpiod_line_release(cs_line);
    }
    if (gpio_chip != NULL) {
        gpiod_chip_close(gpio_chip);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main(void) {
    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO for chip select
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    cs_line = gpiod_chip_get_line(gpio_chip, CS_PIN);
    if (!cs_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    if (gpiod_line_request_output(cs_line, "rtd_monitor", 1) < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Initialize SPI
    if (spi_init() < 0) {
        cleanup();
        return 1;
    }

    // Initialize MAX31865
    if (max31865_init() < 0) {
        cleanup();
        return 1;
    }

    uint16_t rtd_raw;
    uint8_t fault_status;
    double temperature;

    while (!terminate) {
        // Activate chip select
        if (gpiod_line_set_value(cs_line, 0) < 0) {
            perror("Error setting CS low");
            cleanup();
            return 1;
        }

        // Read data
        if (read_max31865_data(&rtd_raw, &fault_status) == 0) {
            // Deactivate chip select
            if (gpiod_line_set_value(cs_line, 1) < 0) {
                perror("Error setting CS high");
                cleanup();
                return 1;
            }

            // Check for faults
            if (fault_status) {
                fprintf(stderr, "Fault detected: 0x%02X\n", fault_status);
                if (fault_status & 0x01) fprintf(stderr, "  RTD High Threshold\n");
                if (fault_status & 0x02) fprintf(stderr, "  RTD Low Threshold\n");
                if (fault_status & 0x04) fprintf(stderr, "  REFIN- > 0.85 * VBIAS\n");
                if (fault_status & 0x08) fprintf(stderr, "  REFIN- < 0.85 * VBIAS\n");
                if (fault_status & 0x10) fprintf(stderr, "  RTDIN- < 0.85 * VBIAS\n");
                if (fault_status & 0x20) fprintf(stderr, "  Overvoltage/Undervoltage fault\n");
            } else {
                // Calculate temperature
                temperature = calculate_temperature(rtd_raw);

                // Log data
                if (log_data(temperature) < 0) {
                    fprintf(stderr, "Error logging data\n");
                }

                printf("Temperature: %.2f C\n", temperature);
            }
        } else {
            // Deactivate chip select
            if (gpiod_line_set_value(cs_line, 1) < 0) {
                perror("Error setting CS high");
                cleanup();
                return 1;
            }
            fprintf(stderr, "Error reading MAX31865 data\n");
        }

        sleep(5);
    }

    cleanup();
    return 0;
}

