    // Initialize GPIO for chip select
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    cs_line = gpiod_chip_get_line(gpio_chip, CS_PIN);
    if (!cs_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    if (gpiod_line_request_output(cs_line, "rtd_monitor", 1) < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Initialize SPI
    if (spi_init() < 0) {
        cleanup();
        return 1;
    }

    // Initialize MAX31865
    if (max31865_init() < 0) {
        cleanup();
        return 1;
    }

    uint16_t rtd_raw;
    uint8_t fault_status;
    double temperature;

    while (!terminate) {
        // Activate chip select
        if (gpiod_line_set_value(cs_line, 0) < 0) {
            perror("Error setting CS low");
            cleanup();
            return 1;
        }

        // Read data
        if (read_max31865_data(&rtd_raw, &fault_status) == 0) {
            // Deactivate chip select
            if (gpiod_line_set_value(cs_line, 1) < 0) {
                perror("Error setting CS high");
                cleanup();
                return 1;
            }

            // Check for faults
            if (fault_status) {
                fprintf(stderr, "Fault detected: 0x%02X\n", fault_status);
                if (fault_status & 0x01) fprintf(stderr, "  RTD High Threshold\n");
                if (fault_status & 0x02) fprintf(stderr, "  RTD Low Threshold\n");
                if (fault_status & 0x04) fprintf(stderr, "  REFIN- > 0.85 * VBIAS\n");
                if (fault_status & 0x08) fprintf(stderr, "  REFIN- < 0.85 * VBIAS\n");
                if (fault_status & 0x10) fprintf(stderr, "  RTDIN- < 0.85 * VBIAS\n");
                if (fault_status & 0x20) fprintf(stderr, "  Overvoltage/Undervoltage fault\n");
            } else {
                // Calculate temperature
                temperature = calculate_temperature(rtd_raw);

                // Log data
                if (log_data(temperature) < 0) {
                    fprintf(stderr, "Error logging data\n");
                }

                printf("Temperature: %.2f C\n", temperature);
            }
        } else {
            // Deactivate chip select
            if (gpiod_line_set_value(cs_line, 1) < 0) {
                perror("Error setting CS high");
                cleanup();
                return 1;
            }
            fprintf(stderr, "Error reading MAX31865 data\n");
        }

        sleep(5);
    }

    cleanup();
    return 0;
}

