void signal_handler(int signal);

// Function to read calibration data from the BMP180
int read_calibration_data(int i2c_handle, bmp180_calibration_data_t *calibration_data) {
    calibration_data->ac1 = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC1);
    calibration_data->ac2 = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC2);
    calibration_data->ac3 = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC3);
    calibration_data->ac4 = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC4);
    calibration_data->ac5 = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC5);
    calibration_data->ac6 = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC6);
    calibration_data->b1 = i2cReadWordData(i2c_handle, BMP180_REG_CAL_B1);
    calibration_data->b2 = i2cReadWordData(i2c_handle, BMP180_REG_CAL_B2);
    calibration_data->mb = i2cReadWordData(i2c_handle, BMP180_REG_CAL_MB);
    calibration_data->mc = i2cReadWordData(i2c_handle, BMP180_REG_CAL_MC);
    calibration_data->md = i2cReadWordData(i2c_handle, BMP180_REG_CAL_MD);

    if (calibration_data->ac1 == PI_BAD_I2C_ADDR || calibration_data->ac2 == PI_BAD_I2C_ADDR ||
        calibration_data->ac3 == PI_BAD_I2C_ADDR || calibration_data->ac4 == PI_BAD_I2C_ADDR ||
        calibration_data->ac5 == PI_BAD_I2C_ADDR || calibration_data->ac6 == PI_BAD_I2C_ADDR ||
        calibration_data->b1 == PI_BAD_I2C_ADDR || calibration_data->b2 == PI_BAD_I2C_ADDR ||
        calibration_data->mb == PI_BAD_I2C_ADDR || calibration_data->mc == PI_BAD_I2C_ADDR ||
        calibration_data->md == PI_BAD_I2C_ADDR) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    return 0;
}

// Function to read raw temperature data from the BMP180
int read_raw_temperature(int i2c_handle) {
    i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x2E);
    gpioDelay(5000); // Wait 5ms
    int msb = i2cReadByteData(i2c_handle, BMP180_REG_MSB);
    int lsb = i2cReadByteData(i2c_handle, BMP180_REG_LSB);
    if (msb == PI_BAD_I2C_ADDR || lsb == PI_BAD_I2C_ADDR) {
        fprintf(stderr, "Error reading raw temperature data\n");
        return -1;
    }
    return (msb << 8) | lsb;
}

// Function to read raw pressure data from the BMP180
int read_raw_pressure(int i2c_handle) {
    i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x34 + (BMP180_OSS << 6));
    gpioDelay(5000); // Wait 5ms
    int msb = i2cReadByteData(i2c_handle, BMP180_REG_MSB);
    int lsb = i2cReadByteData(i2c_handle, BMP180_REG_LSB);
    int xlsb = i2cReadByteData(i2c_handle, BMP180_REG_XLSB);
    if (msb == PI_BAD_I2C_ADDR || lsb == PI_BAD_I2C_ADDR || xlsb == PI_BAD_I2C_ADDR) {
        fprintf(stderr, "Error reading raw pressure data\n");
        return -1;
    }
    return ((msb << 16) | (lsb << 8) | xlsb) >> (8 - BMP180_OSS);
}

// Function to calculate temperature in degrees Celsius
float calculate_temperature(int raw_temperature, bmp180_calibration_data_t calibration_data) {
    long X1 = ((long)raw_temperature - (long)calibration_data.ac6) * ((long)calibration_data.ac5) / pow(2, 15);
    long X2 = ((long)calibration_data.mc * pow(2, 11)) / (X1 + calibration_data.md);
    long B5 = X1 + X2;
    float temperature = (B5 + 8) / pow(2, 4) / 10.0;
    return temperature;
}

// Function to calculate pressure in hPa
float calculate_pressure(int raw_pressure, int raw_temperature, bmp180_calibration_data_t calibration_data) {
    long X1 = ((long)raw_temperature - (long)calibration_data.ac6) * ((long)calibration_data.ac5) / pow(2, 15);
    long X2 = ((long)calibration_data.mc * pow(2, 11)) / (X1 + calibration_data.md);
    long B5 = X1 + X2;

    long B6 = B5 - 4000;
    long X3 = ((long)calibration_data.b2 * (B6 * B6) / pow(2, 12)) / pow(2, 11);
    long X4 = ((long)calibration_data.ac2 * B6) / pow(2, 11);
    long B3 = (((((long)calibration_data.ac1) * 4 + X3) << BMP180_OSS) + 2) / 4;

    unsigned long X5 = ((unsigned long)calibration_data.ac4 * (unsigned long)(B6 - 4000)) / pow(2, 15);
    unsigned long X6 = ((unsigned long)calibration_data.b1 * (B6 * B6) / pow(2, 12)) / pow(2, 16);
    unsigned long B4 = ((unsigned long)calibration_data.ac3 * X5) / pow(2, 15) + X6 + 32768;

    unsigned long B7 = ((unsigned long)raw_pressure - B3) * (50000 >> BMP180_OSS);
    long p;
    if (B7 < 0x80000000)
    {
        p = (B7 * 2) / B4;
    }
    else
    {
        p = (B7 / B4) * 2;
    }

    X1 = (p / pow(2, 8)) * (p / pow(2, 8));
    X1 = (X1 * 3038) / pow(2, 16);
    X2 = (-7357 * p) / pow(2, 16);

    float pressure = p + (X1 + X2 + 3791) / pow(2, 4);
    return pressure / 100.0; // Convert to hPa
}

// Function to add a pressure reading to the circular buffer
void add_pressure_reading(float pressure) {
    pressure_buffer[buffer_index].timestamp = time(NULL);
    pressure_buffer[buffer_index].pressure = pressure;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to calculate the rolling average of the pressure readings
float calculate_rolling_average() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += pressure_buffer[i].pressure;
    }
    return sum / BUFFER_SIZE;
}

// Function to trigger an alert by setting GPIO24 HIGH for 1 second
void trigger_alert() {
    gpioWrite(ALERT_GPIO, 1); // Set GPIO HIGH
    gpioDelay(1000000);       // Wait 1 second
    gpioWrite(ALERT_GPIO, 0); // Set GPIO LOW
}

// Timer callback function
void timer_callback(int timer_id, void *user_data) {
    int raw_temperature = read_raw_temperature(i2c_handle);
    int raw_pressure = read_raw_pressure(i2c_handle);

    if (raw_temperature == -1 || raw_pressure == -1) {
        fprintf(stderr, "Error reading sensor data\n");
        return;
    }

    float temperature = calculate_temperature(raw_temperature, calibration_data);
    float pressure = calculate_pressure(raw_pressure, raw_temperature, calibration_data);

    add_pressure_reading(pressure);
    float rolling_average = calculate_rolling_average();

    if (fabs(pressure - rolling_average) > 5.0) {
