}

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    gpioSetTimerFuncEx(0, 0, NULL, NULL); // Disable timer
    i2cClose(i2c_handle);                 // Close I2C handle
    gpioWrite(ALERT_GPIO, 0);             // Set alert GPIO LOW
    gpioTerminate();                      // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(i2c_handle, &calibration_data) != 0) {
        fprintf(stderr, "Failed to read calibration data. Exiting.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO24 as output
    gpioSetMode(ALERT_GPIO, PI_OUTPUT);
    gpioWrite(ALERT_GPIO, 0); // Ensure it starts LOW

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set up hardware timer (timer 0, every 50ms)
    if (gpioSetTimerFuncEx(0, 50, timer_callback, NULL) != 0) {
        fprintf(stderr, "Error setting up timer\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Keep the program running until a signal is received
    while (running) {
        sleep(1); // Sleep to reduce CPU usage
    }

    return 0;
}

