    var2 = p * ((double)dig_P8) / 32768.0;
    p = p + (var1 + var2 + ((double)dig_P7)) / 16.0;

    return p / 100.0; // Convert to hPa
}

// Log data function
void log_data(double temperature, double pressure) {
    time_t rawtime;
    struct tm *timeinfo;
