    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen("weather_data.txt", "a");
    if (fp == NULL) {
        perror("Error opening weather_data.txt");
        return;
    }

    fprintf(fp, "%s, Temperature: %.2f °C, Pressure: %.2f hPa\n", timestamp, temperature, pressure);
    fclose(fp);
