    printf("Caught signal %d, exiting...\n", signal);
}

// I2C open device function
int i2c_open_device(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }
    return fd;
}

// I2C close device function
int i2c_close_device(int fd) {
    if (close(fd) < 0) {
        perror("Error closing I2C device");
        return -1;
    }
    return 0;
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        bmp280_address = strtol(argv[1], NULL, 16);
        if (bmp280_address != 0x76 && bmp280_address != 0x77) {
            fprintf(stderr, "Invalid I2C address. Using default 0x76.\n");
            bmp280_address = 0x76;
        }
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    char i2c_device[20];
    snprintf(i2c_device, sizeof(i2c_device), "/dev/i2c-1");
    i2c_fd = i2c_open_device(i2c_device);
    if (i2c_fd < 0) {
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, bmp280_address) < 0) {
        perror("Error setting I2C slave address");
        i2c_close_device(i2c_fd);
        return 1;
    }

    // Initialize BMP280 sensor
    if (bmp280_init(i2c_fd) != 0) {
        fprintf(stderr, "Error initializing BMP280 sensor\n");
        i2c_close_device(i2c_fd);
        return 1;
    }

    // Main loop
    while (program_running) {
        int32_t raw_temperature, raw_pressure;
        if (bmp280_read_raw_data(i2c_fd, &raw_temperature, &raw_pressure) == 0) {
            double temperature = bmp280_compensate_temperature(raw_temperature);
            double pressure = bmp280_compensate_pressure(raw_pressure, temperature);
            log_data(temperature, pressure);
        } else {
            fprintf(stderr, "Error reading BMP280 data\n");
        }

        sleep(5);
    }

    // Close I2C device
    i2c_close_device(i2c_fd);

    return 0;
}

