#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <gpiod.h>
#include <gpiod/libgpiod.h>

// Configuration
#define I2C_BUS 1
#define LM75_ADDR 0x48
#define TEMP_REG 0x00
#define GPIO_PIN 18
#define SERVER_IP "127.0.0.1" // Replace with your server IP
#define SERVER_PORT 12345
#define BUFFER_SIZE 60
#define TEMP_THRESHOLD 28.0
#define TEMP_SCALE 256.0

// Global variables
static volatile int running = 1;
static int i2c_fd = -1;
static struct gpiod_line *gpio_line = NULL;
static pthread_t thread_id;
static pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;
static float temperature_buffer[BUFFER_SIZE];
static int buffer_index = 0;

// Function prototypes
float read_temperature();
void *data_acquisition_thread(void *arg);
void signal_handler(int sig);
int init_i2c();
void close_i2c();
int init_gpio();
void close_gpio();
void send_data(float temperature);
float calculate_average();
void control_led(float temperature);

// Function to read temperature from LM75 sensor
float read_temperature() {
    uint8_t data[2];
    int ret;

    ret = i2c_smbus_read_i2c_block_data(i2c_fd, TEMP_REG, 2, (char *)data);
    if (ret < 0) {
        fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
        return -273.15; // Return absolute zero on error
    }

    int16_t raw_temp = (data[0] << 8) | data[1];
    raw_temp = raw_temp >> 5; // Shift right by 5 bits

    return (float)raw_temp / TEMP_SCALE;
}

// Data acquisition thread function
void *data_acquisition_thread(void *arg) {
    while (running) {
        float temperature = read_temperature();

        pthread_mutex_lock(&buffer_mutex);
        temperature_buffer[buffer_index] = temperature;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
        pthread_mutex_unlock(&buffer_mutex);

        control_led(temperature);
        send_data(temperature);

        sleep(1);
    }
    return NULL;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    running = 0;
    printf("Caught signal %d, exiting...\n", sig);
}

// Initialize I2C bus
int init_i2c() {
    i2c_fd = i2c_smbus_open(I2C_BUS, LM75_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Close I2C bus
void close_i2c() {
    if (i2c_fd >= 0) {
        i2c_smbus_close(i2c_fd);
        i2c_fd = -1;
    }
}

// Initialize GPIO pin
int init_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line_request_config config;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    gpio_line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!gpio_line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    memset(&config, 0, sizeof(config));
    config.consumer = "temperature_monitor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(gpio_line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Close GPIO pin
void close_gpio() {
    if (gpio_line) {
        gpiod_line_release(gpio_line);
        gpio_line = NULL;
    }
}

// Send data to server
void send_data(float temperature) {
    int sockfd;
    struct sockaddr_in servaddr;
    char buffer[32];

    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        fprintf(stderr, "Socket creation failed: %s\n", strerror(errno));
        return;
    }

    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(SERVER_PORT);
    if (inet_pton(AF_INET, SERVER_IP, &servaddr.sin_addr) <= 0) {
        fprintf(stderr, "Invalid address/ Address not supported: %s\n", SERVER_IP);
        close(sockfd);
        return;
    }

    snprintf(buffer, sizeof(buffer), "%.2f", temperature);

    if (sendto(sockfd, buffer, strlen(buffer), 0, (const struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        fprintf(stderr, "Send failed: %s\n", strerror(errno));
    }

    close(sockfd);
}

// Calculate running average
float calculate_average() {
    float sum = 0.0;
    pthread_mutex_lock(&buffer_mutex);
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += temperature_buffer[i];
    }
    pthread_mutex_unlock(&buffer_mutex);
    return sum / BUFFER_SIZE;
}

// Control LED based on temperature
void control_led(float temperature) {
    if (temperature > TEMP_THRESHOLD) {
        if (gpio_line) {
            gpiod_line_set_value(gpio_line, 1);
        }
    } else {
        if (gpio_line) {
            gpiod_line_set_value(gpio_line, 0);
        }
    }
}

int main() {
    // Initialize signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        close_i2c();
        return 1;
    }

    // Create data acquisition thread
    if (pthread_create(&thread_id, NULL, data_acquisition_thread, NULL) != 0) {
        fprintf(stderr, "Thread creation failed: %s\n", strerror(errno));
        close_i2c();
        close_gpio();
        return 1;
    }

    // Main loop (optional, can be used for other tasks)
    while (running) {
        sleep(1);
    }

    // Clean up resources
    pthread_join(thread_id, NULL);
    close_i2c();
    close_gpio();
    pthread_mutex_destroy(&buffer_mutex);

    return 0;
}

