#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>
#include <jansson.h>
#include <time.h>

// Constants
#define HEATER_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000
#define TARGET_TEMP_DEFAULT 25.0
#define KP_DEFAULT 1.0
#define KI_DEFAULT 0.1
#define KD_DEFAULT 0.01
#define MAX_TEMP 80.0
#define R_REF 430.0
#define R_PT100_0 100.0
#define A 3.9083e-3
#define B -5.775e-7

// Global variables
static volatile int running = 1;
static int spi_handle;
static double target_temperature = TARGET_TEMP_DEFAULT;
static double Kp = KP_DEFAULT;
static double Ki = KI_DEFAULT;
static double Kd = KD_DEFAULT;
static double integral = 0.0;
static double previous_error = 0.0;

// Function prototypes
void signal_handler(int signal);
int initialize();
double read_temperature();
double calculate_pid(double current_temperature);
void set_heater_power(double duty_cycle);
void load_configuration();
void log_error(const char *message);

// Signal handler
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize pigpio and SPI
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // MAX31865 Initialization
    char init_data[2] = {0x80, 0xC1}; // VBIAS, auto conversion, clear faults
    spiWrite(spi_handle, init_data, 2);

    return 0;
}

// Read temperature from MAX31865
double read_temperature() {
    char read_command[1] = {0x01}; // Read RTD MSB
    char read_data[3];

    if (spiXfer(spi_handle, read_command, read_data, 3) != 0) {
        log_error("SPI transfer failed");
        return -1.0;
    }

    int rtd_code = ((read_data[1] << 8) | read_data[2]) >> 1; // 15-bit RTD code

    if (rtd_code & 0x1) {
        log_error("MAX31865 fault detected");
        return -1.0;
    }

    double rtd_resistance = ((double)rtd_code / 32768.0) * R_REF;
    double temperature = solve_rtd_equation(rtd_resistance);

    return temperature;
}

// Solve the Callendar-Van Dusen equation for temperature
double solve_rtd_equation(double rtd_resistance) {
    double rtd_ratio = rtd_resistance / R_PT100_0;
    double temperature = 0.0;

    // Use a numerical method to solve the equation
    double lower_bound = 0.0;
    double upper_bound = 100.0;
    double mid_point;

    for (int i = 0; i < 100; i++) {
        mid_point = (lower_bound + upper_bound) / 2.0;
        double rtd_calculated = R_PT100_0 * (1 + A * mid_point + B * mid_point * mid_point);

        if (rtd_calculated > rtd_resistance) {
            upper_bound = mid_point;
        } else {
            lower_bound = mid_point;
        }
    }

    temperature = (lower_bound + upper_bound) / 2.0;

    return temperature;
}

// Calculate PID output
double calculate_pid(double current_temperature) {
    double error = target_temperature - current_temperature;
    integral += error;
    double derivative = error - previous_error;
    double output = Kp * error + Ki * integral + Kd * derivative;
    previous_error = error;

    // Clamp the output to the range 0-100
    if (output < 0) output = 0;
    if (output > 100) output = 100;

    return output;
}

// Set heater power using PWM
void set_heater_power(double duty_cycle) {
    int pwm_value = (int)(duty_cycle * (PWM_RANGE / 100.0));
    gpioPWM(HEATER_GPIO, pwm_value);
}

// Load configuration from JSON file
void load_configuration() {
    json_t *root;
    json_error_t error;

    root = json_load_file("config.json", 0, &error);
    if (!root) {
        fprintf(stderr, "Error: Could not load config.json: %s\n", error.text);
        fprintf(stderr, "Using default values: target=%.2f, Kp=%.2f, Ki=%.2f, Kd=%.2f\n",
                target_temperature, Kp, Ki, Kd);
        return;
    }

    json_t *target = json_object_get(root, "target_temperature");
    json_t *kp = json_object_get(root, "Kp");
    json_t *ki = json_object_get(root, "Ki");
    json_t *kd = json_object_get(root, "Kd");

    if (json_is_real(target)) {
        target_temperature = json_real_value(target);
    }
    if (json_is_real(kp)) {
        Kp = json_real_value(kp);
    }
    if (json_is_real(ki)) {
        Ki = json_real_value(ki);
    }
    if (json_is_real(kd)) {
        Kd = json_real_value(kd);
    }

    json_decref(root);

    printf("Configuration loaded: target=%.2f, Kp=%.2f, Ki=%.2f, Kd=%.2f\n",
           target_temperature, Kp, Ki, Kd);
}

// Log errors to stderr with timestamp
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(stderr, "%d-%02d-%02d %02d:%02d:%02d: %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
