#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// BMP180 commands
#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE0 0x34 // Oss = 0
#define BMP180_CMD_PRESSURE1 0x74 // Oss = 1
#define BMP180_CMD_PRESSURE2 0xB4 // Oss = 2
#define BMP180_CMD_PRESSURE3 0xF4 // Oss = 3

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Calibration data
static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

// Function prototypes
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int bmp180_read_calibration_data(int fd);
int bmp180_read_raw_temperature(int fd, int *raw_temperature);
int bmp180_read_raw_pressure(int fd, int oss, int *raw_pressure);
double bmp180_calculate_temperature(int raw_temperature);
double bmp180_calculate_pressure(int raw_pressure, int raw_temperature, int oss);
void log_breach(double temperature, double pressure);
void signal_handler(int sig);
int setup_i2c();
void cleanup();

// I2C read function with retry
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len) {
    int retries = 3;
    int result = -1;

    while (retries > 0) {
        if (write(fd, &reg, 1) != 1) {
            perror("I2C write (register select) failed");
            retries--;
            usleep(10000); // 10ms
            continue;
        }

        result = read(fd, data, len);
        if (result == len) {
            return 0; // Success
        } else {
            perror("I2C read failed");
            retries--;
            usleep(10000); // 10ms
        }
    }

    fprintf(stderr, "I2C read failed after multiple retries.\n");
    return -1; // Failure
}

// I2C write function with retry
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    int retries = 3;
    int result = -1;

    while (retries > 0) {
        uint8_t buf[2] = {reg, value};
        result = write(fd, buf, 2);
        if (result == 2) {
            return 0; // Success
        } else {
            perror("I2C write failed");
            retries--;
            usleep(10000); // 10ms
        }
    }

    fprintf(stderr, "I2C write failed after multiple retries.\n");
    return -1; // Failure
}

// Read calibration data from BMP180
int bmp180_read_calibration_data(int fd) {
    uint8_t data[22];
    if (i2c_read_bytes(fd, BMP180_REG_CAL_AC1, data, 22) != 0) {
        fprintf(stderr, "Failed to read calibration data.\n");
        return -1;
    }

    ac1 = (data[0] << 8) | data[1];
    ac2 = (data[2] << 8) | data[3];
    ac3 = (data[4] << 8) | data[5];
    ac4 = (data[6] << 8) | data[7];
    ac5 = (data[8] << 8) | data[9];
    ac6 = (data[10] << 8) | data[11];
    b1 = (data[12] << 8) | data[13];
    b2 = (data[14] << 8) | data[15];
    mb = (data[16] << 8) | data[17];
    mc = (data[18] << 8) | data[19];
    md = (data[20] << 8) | data[21];

    return 0;
}

// Read raw temperature value from BMP180
int bmp180_read_raw_temperature(int fd, int *raw_temperature) {
    if (i2c_write_byte(fd, BMP180_REG_CONTROL, BMP180_CMD_TEMP) != 0) {
        fprintf(stderr, "Failed to write temperature command.\n");
        return -1;
    }
    usleep(5000); // Wait 4.5ms

    uint8_t data[2];
    if (i2c_read_bytes(fd, BMP180_REG_MSB, data, 2) != 0) {
        fprintf(stderr, "Failed to read raw temperature data.\n");
        return -1;
    }

    *raw_temperature = (data[0] << 8) | data[1];
    return 0;
}

// Read raw pressure value from BMP180
int bmp180_read_raw_pressure(int fd, int oss, int *raw_pressure) {
    uint8_t cmd;
    switch (oss) {
        case 0: cmd = BMP180_CMD_PRESSURE0; break;
        case 1: cmd = BMP180_CMD_PRESSURE1; break;
        case 2: cmd = BMP180_CMD_PRESSURE2; break;
        case 3: cmd = BMP180_CMD_PRESSURE3; break;
        default: cmd = BMP180_CMD_PRESSURE0; break; // Default to OSS=0
    }

    if (i2c_write_byte(fd, BMP180_REG_CONTROL, cmd) != 0) {
        fprintf(stderr, "Failed to write pressure command.\n");
        return -1;
    }

    usleep((2 + (3 << oss)) * 1000); // Wait time depends on OSS

    uint8_t data[3];
    if (i2c_read_bytes(fd, BMP180_REG_MSB, data, 3) != 0) {
        fprintf(stderr, "Failed to read raw pressure data.\n");
        return -1;
    }

    *raw_pressure = ((data[0] << 16) | (data[1] << 8) | data[2]) >> (8 - oss);
    return 0;
}

// Calculate temperature in degrees Celsius
double bmp180_calculate_temperature(int raw_temperature) {
    long x1 = (((long)raw_temperature - (long)ac6) * (long)ac5) >> 15;
    long x2 = ((long)mc << 11) / (x1 + md);
    long b5 = x1 + x2;
    double temperature = ((b5 + 8) >> 4) / 10.0;
    return temperature;
}

// Calculate pressure in hPa
double bmp180_calculate_pressure(int raw_pressure, int raw_temperature, int oss) {
    long x1 = (((long)raw_temperature - (long)ac6) * (long)ac5) >> 15;
    long x2 = ((long)mc << 11) / (x1 + md);
    long b5 = x1 + x2;

    long b6 = b5 - 4000;
    long x3 = ((long)b2 * (b6 * b6) >> 12) >> 11;
    long x4 = ((long)ac2 * b6) >> 11;
    long b3 = (((((long)ac1) * 4 + x3) << oss) + 2) >> 2;

    unsigned long x1_p = ((long)ac3 * b6) >> 13;
    unsigned long x2_p = ((long)b1 * ((b6 * b6) >> 12)) >> 16;
    unsigned long x3_p = ((x1_p + x2_p + 2) >> 2);
    unsigned long b4 = ((unsigned long)ac4 * (x3_p + 32768)) >> 15;

    unsigned long b7 = ((unsigned long)raw_pressure - b3) * (50000 >> oss);
    long p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    double pressure = p + ((x1 + x2 + 3791) >> 4);

    return pressure / 100.0; // Convert to hPa
}

// Log breach to file
void log_breach(double temperature, double pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s - Temperature: %.2f°C, Pressure: %.2f hPa\n", timestamp, temperature, pressure);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Setup I2C communication
int setup_i2c() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen("breach_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return 1;
    }

    // Initialize I2C
    if (setup_i2c() != 0) {
        fclose(log_file);
        return 1;
    }

    // Read calibration data
    if (bmp180_read_calibration_data(i2c_fd) != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int raw_temperature, raw_pressure;
        double temperature, pressure;

        // Read raw temperature
        if (bmp180_read_raw_temperature(i2c_fd, &raw_temperature) != 0) {
            fprintf(stderr, "Failed to read raw temperature, retrying in 1 second.\n");
            sleep(1);
            continue;
        }

        // Read raw pressure (OSS = 3)
        if (bmp180_read_raw_pressure(i2c_fd, 3, &raw_pressure) != 0) {
            fprintf(stderr, "Failed to read raw pressure, retrying in 1 second.\n");
            sleep(1);
            continue;
        }

        // Calculate temperature and pressure
        temperature = bmp180_calculate_temperature(raw_temperature);
        pressure = bmp180_calculate_pressure(raw_pressure, raw_temperature, 3);

        // Check for breaches
        if (temperature > 30.0 || pressure < 950.0) {
            log_breach(temperature, pressure);
        }

        sleep(1); // Sample every 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

