// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_TEMP_DATA 0xF6
#define BMP180_REG_PRESSURE_DATA 0xF6
#define BMP180_REG_CALIB_START 0xAA

// Oversampling Setting (OSS)
#define OSS 0

// GPIO pin for fan control
#define FAN_PIN 18

// Circular buffer size
#define BUFFER_SIZE 60

// Structure to hold BMP180 calibration data
typedef struct {
    int16_t ac1;
    int16_t ac2;
    int16_t ac3;
    uint16_t ac4;
    uint16_t ac5;
    uint16_t ac6;
    int16_t b1;
    int16_t b2;
    int16_t mb;
    int16_t mc;
    int16_t md;
} bmp180_calibration_data_t;

// Structure to hold sensor data
typedef struct {
    time_t timestamp;
    float temperature;
    float pressure;
} sensor_data_t;

// Circular buffer structure
typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global variables
int i2c_handle;
bmp180_calibration_data_t calibration_data;
circular_buffer_t buffer;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_calibration_data(int i2c_handle, bmp180_calibration_data_t *calibration_data);
int read_raw_temperature(int i2c_handle);
int read_raw_pressure(int i2c_handle);
