void signal_handler(int signal);

// Function to read calibration data from BMP180
int read_calibration_data(int i2c_handle, bmp180_calibration_data_t *calibration_data) {
    char data[22];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CALIB_START, data, 22) != 22) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    calibration_data->ac1 = (data[0] << 8) | data[1];
    calibration_data->ac2 = (data[2] << 8) | data[3];
    calibration_data->ac3 = (data[4] << 8) | data[5];
    calibration_data->ac4 = (data[6] << 8) | data[7];
    calibration_data->ac5 = (data[8] << 8) | data[9];
    calibration_data->ac6 = (data[10] << 8) | data[11];
    calibration_data->b1 = (data[12] << 8) | data[13];
    calibration_data->b2 = (data[14] << 8) | data[15];
    calibration_data->mb = (data[16] << 8) | data[17];
    calibration_data->mc = (data[18] << 8) | data[19];
    calibration_data->md = (data[20] << 8) | data[21];

    return 0;
}

// Function to read raw temperature data from BMP180
int read_raw_temperature(int i2c_handle) {
    char write_data[2] = {BMP180_REG_CONTROL, 0x2E};
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, write_data, 2) != 2) {
        fprintf(stderr, "Error writing temperature read command\n");
        return -1;
    }
    gpioDelay(5000); // Wait 4.5ms (minimum)

    char data[2];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_TEMP_DATA, data, 2) != 2) {
        fprintf(stderr, "Error reading raw temperature data\n");
        return -1;
    }

    return (data[0] << 8) | data[1];
}

// Function to read raw pressure data from BMP180
int read_raw_pressure(int i2c_handle) {
    char write_data[2] = {BMP180_REG_CONTROL, 0x34 + (OSS << 6)};
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, write_data, 2) != 2) {
        fprintf(stderr, "Error writing pressure read command\n");
        return -1;
    }
    gpioDelay(2 + (3 << OSS)); // Wait for conversion

    char data[2];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_PRESSURE_DATA, data, 2) != 2) {
        fprintf(stderr, "Error reading raw pressure data\n");
        return -1;
    }

    return (data[0] << 8) | data[1];
}

// Function to calculate true temperature
float calculate_true_temperature(int32_t ut, const bmp180_calibration_data_t *calibration_data) {
    int32_t x1 = (((int32_t)ut - (int32_t)calibration_data->ac6) * (int32_t)calibration_data->ac5) >> 15;
    int32_t x2 = ((int32_t)calibration_data->mc << 11) / (x1 + calibration_data->md);
    int32_t b5 = x1 + x2;
    float temperature = ((b5 + 8) >> 4) / 10.0f;
    return temperature;
}

// Function to calculate true pressure
float calculate_true_pressure(int32_t up, int32_t ut, const bmp180_calibration_data_t *calibration_data) {
