    int32_t x2 = ((int32_t)calibration_data->mc << 11) / (x1 + calibration_data->md);
    int32_t b5 = x1 + x2;

    int32_t b6 = b5 - 4000;
    x1 = (calibration_data->b2 * (b6 * b6) >> 12) >> 11;
    x2 = (calibration_data->ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)calibration_data->ac1) * 4 + x3) << OSS) + 2) >> 2;

    x1 = (calibration_data->ac3 * b6) >> 13;
    x2 = (calibration_data->b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = (calibration_data->ac4 * (uint32_t)(x3 + 32768)) >> 15;

    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> OSS);
    int32_t p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);

    return p;
}

// Function to add data to the circular buffer
void add_to_buffer(circular_buffer_t *buffer, sensor_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Function to print the contents of the circular buffer
void print_buffer(const circular_buffer_t *buffer) {
    int i;
    for (i = 0; i < buffer->count; i++) {
        int index = (buffer->head - buffer->count + i + BUFFER_SIZE) % BUFFER_SIZE;
        printf("%ld,%.2f,%.2f\n", buffer->data[index].timestamp, buffer->data[index].temperature, buffer->data[index].pressure);
    }
}

// Function to control the fan based on temperature
void control_fan(float temperature) {
    if (temperature > 30.0f) {
        gpioWrite(FAN_PIN, 1); // Turn fan on
    } else {
        gpioWrite(FAN_PIN, 0); // Turn fan off
    }
}

// Timer callback function
void timer_callback() {
    int32_t ut, up;
    float temperature, pressure;
    sensor_data_t data;

    ut = read_raw_temperature(i2c_handle);
    if (ut < 0) {
        fprintf(stderr, "Error reading raw temperature, skipping sample\n");
        return;
    }

    up = read_raw_pressure(i2c_handle);
    if (up < 0) {
        fprintf(stderr, "Error reading raw pressure, skipping sample\n");
        return;
    }

    temperature = calculate_true_temperature(ut, &calibration_data);
    pressure = calculate_true_pressure(up, ut, &calibration_data);

    data.timestamp = time(NULL);
    data.temperature = temperature;
    data.pressure = pressure;

    add_to_buffer(&buffer, data);
    print_buffer(&buffer);
    control_fan(temperature);
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(i2c_handle, &calibration_data) != 0) {
        fprintf(stderr, "Error reading calibration data, exiting\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    buffer.head = 0;
    buffer.count = 0;

    // Set GPIO pin for fan control as output
    gpioSetMode(FAN_PIN, PI_OUTPUT);
    gpioWrite(FAN_PIN, 0); // Ensure fan is off initially

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up hardware timer callback
    if (gpioSetTimerFuncEx(0, 500, timer_callback, NULL) != 0) {
        fprintf(stderr, "Error setting up timer callback\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop (wait for termination signal)
    while (!terminate) {
        sleep(1);
    }

    // Clean up
    gpioWrite(FAN_PIN, 0); // Turn fan off
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

