        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    buffer.head = 0;
    buffer.count = 0;

    // Set GPIO pin for fan control as output
    gpioSetMode(FAN_PIN, PI_OUTPUT);
    gpioWrite(FAN_PIN, 0); // Ensure fan is off initially

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up hardware timer callback
    if (gpioSetTimerFuncEx(0, 500, timer_callback, NULL) != 0) {
        fprintf(stderr, "Error setting up timer callback\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop (wait for termination signal)
    while (!terminate) {
        sleep(1);
    }

    // Clean up
    gpioWrite(FAN_PIN, 0); // Turn fan off
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

