#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define HEATER_PIN 17
#define SPI_CE0 8
#define SPI_MISO 9
#define SPI_MOSI 10
#define SPI_SCLK 11

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 2000000 // 2 MHz
#define SPI_MODE 0

// Define PI controller parameters
#define KP 1.0
#define KI 0.1
#define MAX_DUTY_CYCLE 80.0
#define MIN_DUTY_CYCLE 0.0

// Define target temperature
#define TARGET_TEMPERATURE 25.0

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
float read_temperature();
float calculate_pi(float current_temperature, float *integral, float *previous_error);
void set_heater_duty_cycle(float duty_cycle);
void log_data(float temperature, float duty_cycle);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read temperature from MAX31855
float read_temperature() {
    unsigned char data[4];
    int result;

    result = spiRead(spi_handle, data, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading SPI data: %d\n", result);
        return -1000.0; // Indicate error
    }

    // Check for fault conditions
    if (data[3] & 0x01) {
        fprintf(stderr, "MAX31855 Fault: Open circuit\n");
        return -1000.0;
    }
    if (data[3] & 0x02) {
        fprintf(stderr, "MAX31855 Fault: Short to GND\n");
        return -1000.0;
    }
    if (data[3] & 0x04) {
        fprintf(stderr, "MAX31855 Fault: Short to VCC\n");
        return -1000.0;
    }

    // Extract temperature data
    int16_t raw_temp = ((data[0] << 8) | data[1]) >> 2;
    float temperature = (float)raw_temp * 0.25;

    return temperature;
}

// Function to calculate PI controller output
float calculate_pi(float current_temperature, float *integral, float *previous_error) {
    float error = TARGET_TEMPERATURE - current_temperature;
    *integral += error;
    // Anti-windup
    if (*integral > 100.0) *integral = 100.0;
    if (*integral < -100.0) *integral = -100.0;

    float output = KP * error + KI * (*integral);

    // Limit output to safe range
    if (output > MAX_DUTY_CYCLE) output = MAX_DUTY_CYCLE;
    if (output < MIN_DUTY_CYCLE) output = MIN_DUTY_CYCLE;

    return output;
}

