#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED (common anode)
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Temperature thresholds (millidegrees Celsius)
#define TEMP_BLUE  40000
#define TEMP_GREEN 59999
#define TEMP_RED   60000

// Global flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to read CPU temperature from file
int read_cpu_temp() {
    FILE *fp;
    char buffer[10];
    int temp = -1; // Default to -1 in case of error

    fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open temperature file.\n");
        return -1;
    }

    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        if (ferror(fp)) {
            fprintf(stderr, "Error: Could not read temperature from file.\n");
        } else {
            fprintf(stderr, "Error: Empty temperature file.\n");
        }
        fclose(fp);
        return -1;
    }

    fclose(fp);

    // Convert string to integer
    char *endptr;
    temp = strtol(buffer, &endptr, 10);

    // Check for errors during conversion
    if (*endptr != '\0' && *endptr != '\n') {
        fprintf(stderr, "Error: Invalid temperature data: %s\n", buffer);
        return -1;
    }

    return temp;
}

// Function to set RGB LED color using PWM
void set_rgb_color(int red, int green, int blue) {
    // Invert the brightness values for common anode LED
    int red_pwm   = 255 - red;
    int green_pwm = 255 - green;
    int blue_pwm  = 255 - blue;

    gpioPWM(RED_PIN,   red_pwm);
    gpioPWM(GREEN_PIN, green_pwm);
    gpioPWM(BLUE_PIN,  blue_pwm);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN,   PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN,  PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(RED_PIN,   255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN,  255);

    // Set PWM frequency (e.g., 1000 Hz)
    gpioSetPWMfrequency(RED_PIN,   1000);
    gpioSetPWMfrequency(GREEN_PIN, 1000);
    gpioSetPWMfrequency(BLUE_PIN,  1000);

    // Install signal handlers
    signal(SIGINT,  signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read CPU temperature
        int temp = read_cpu_temp();

        // Check for errors
        if (temp == -1) {
            fprintf(stderr, "Error: Failed to read temperature, skipping update.\n");
            sleep(0.5);
            continue;
        }

        // Determine RGB color based on temperature
        int red   = 0;
        int green = 0;
        int blue  = 0;

        if (temp < TEMP_BLUE) {
            blue = 255;
        } else if (temp < TEMP_GREEN) {
            green = 255;
        } else {
            red = 255;
        }

        // Set RGB color
        set_rgb_color(red, green, blue);

        // Print current temperature and RGB values
        printf("Temperature: %d m°C, RGB: (%d, %d, %d)\n", temp, red, green, blue);

        // Wait for 0.5 seconds
        sleep(0.5);
    }

    // Cleanup: Turn off LED and terminate pigpio
    set_rgb_color(255, 255, 255); // Turn off (common anode)
    gpioTerminate();

    fprintf(stderr, "Program terminated cleanly.\n");
    return 0;
}

