#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <curl/curl.h>
#include <pigpio.h>
#include <time.h>

#define DHT22_GPIO 4
#define MAX_RETRIES 3
#define SERVER_URL "http://yourserver.com/api/humidity"

// Structure to hold DHT22 data
typedef struct {
    float temperature;
    float humidity;
} DHT22Data;

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to terminate the pigpio library
void terminate_gpio() {
    gpioTerminate();
}

// Function to send a start signal to the DHT22 sensor
int send_start_signal() {
    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, 0);
    gpioDelay(1); // 1 ms
    gpioWrite(DHT22_GPIO, 1);
    gpioDelay(30); // 30 us
    gpioSetMode(DHT22_GPIO, PI_INPUT);
    return 0;
}

// Function to read data from the DHT22 sensor
int read_dht22_data(unsigned char *data) {
    int i, j;

    for (i = 0; i < 5; i++) {
        data[i] = 0;
    }

    for (i = 0; i < 40; i++) {
        int count = 0;
        while (gpioRead(DHT22_GPIO) == 0 && count++ < 1000) {
            gpioDelay(1); // Wait for the line to go high
        }
        count = 0;
        while (gpioRead(DHT22_GPIO) == 1 && count++ < 1000) {
            gpioDelay(1); // Wait for the line to go low
        }

        if (count > 50) {
            data[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    return 0;
}

// Function to validate the checksum of the received data
int validate_checksum(unsigned char *data) {
    unsigned char checksum = 0;
    for (int i = 0; i < 4; i++) {
        checksum += data[i];
    }
    if (checksum != data[4]) {
        fprintf(stderr, "Checksum error: calculated %d, received %d\n", checksum, data[4]);
        return -1;
    }
    return 0;
}

// Function to parse the received data and extract temperature and humidity
int parse_dht22_data(unsigned char *data, DHT22Data *dht22_data) {
    unsigned int humidity = ((unsigned int)data[0] << 8) | data[1];
    unsigned int temperature = ((unsigned int)data[2] << 8) | data[3];

    dht22_data->humidity = (float)humidity / 10.0;
    dht22_data->temperature = (float)temperature / 10.0;

    // Handle negative temperatures
    if (temperature & 0x8000) {
        dht22_data->temperature = -(float)(temperature & 0x7FFF) / 10.0;
    }

    return 0;
}

// Function to format the data into a JSON string
int format_json_data(DHT22Data dht22_data, char *json_string, size_t json_string_size) {
    int ret = snprintf(json_string, json_string_size, "{\"temperature\": %.1f, \"humidity\": %.1f}", dht22_data.temperature, dht22_data.humidity);
    if (ret < 0 || ret >= json_string_size) {
        fprintf(stderr, "Error formatting JSON data\n");
        return -1;
    }
    return 0;
}

// Function to send a POST request to the server
int send_post_request(const char *json_data) {
    CURL *curl;
    CURLcode res;
    struct curl_slist *headers = NULL;

    curl_global_init(CURL_GLOBAL_ALL);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, SERVER_URL);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);

        headers = curl_slist_append(headers, "Content-Type: application/json");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }

        curl_easy_cleanup(curl);
        curl_slist_free_all(headers);
    }
    curl_global_cleanup();
    return (res == CURLE_OK) ? 0 : -1;
}

int main() {
    unsigned char dht22_data[5];
    DHT22Data dht22_data_struct;
    char json_data[128];
    int retries = 0;
    int result = -1;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        return 1;
    }

    while (program_running) {
        retries = 0;
        result = -1;

        while (retries < MAX_RETRIES && result != 0) {
            // Send start signal
            if (send_start_signal() != 0) {
                fprintf(stderr, "Error sending start signal, retrying...\n");
                retries++;
                continue;
            }

            // Read data
            if (read_dht22_data(dht22_data) != 0) {
                fprintf(stderr, "Error reading DHT22 data, retrying...\n");
                retries++;
                continue;
            }

            // Validate checksum
            if (validate_checksum(dht22_data) != 0) {
                fprintf(stderr, "Checksum validation failed, retrying...\n");
                retries++;
                continue;
            }

            // Parse data
            if (parse_dht22_data(dht22_data, &dht22_data_struct) != 0) {
                fprintf(stderr, "Error parsing DHT22 data, retrying...\n");
                retries++;
                continue;
            }

            // Format JSON data
            if (format_json_data(dht22_data_struct, json_data, sizeof(json_data)) != 0) {
                fprintf(stderr, "Error formatting JSON data, retrying...\n");
                retries++;
                continue;
            }

            // Send POST request
            if (send_post_request(json_data) != 0) {
                fprintf(stderr, "Error sending POST request, retrying...\n");
                retries++;
                continue;
            }

            result = 0; // Success
            break; // Exit retry loop
        }

        if (result != 0) {
            fprintf(stderr, "Failed to read DHT22 data after %d retries\n", MAX_RETRIES);
        }

        sleep(5); // Wait 5 seconds before next reading
    }

    // Terminate pigpio
    terminate_gpio();

    return 0;
}

