// Function to read raw pressure data from the BMP180
int read_raw_pressure(int *raw_pressure)
{
    char buf[1];
    buf[0] = BMP180_REG_CONTROL;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    buf[0] = 0x34 + (BMP180_OSS << 6); // Pressure measurement command
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    gpioDelay(BMP180_CONVERSION_DELAY * 1000); // Wait for conversion

    buf[0] = BMP180_REG_MSB;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    char data[3];
    if (i2cReadDevice(i2c_handle, data, 3) != 3) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
