    *raw_pressure = ((data[0] << 16) | (data[1] << 8) | data[2]) >> (8 - BMP180_OSS);
    return 0;
}

// Function to calculate pressure in hPa
double calculate_pressure(int raw_temperature, int raw_pressure)
{
    long x1, x2, x3, b3, b5, b6, p;
    unsigned long b4, b7;

    b5 = (((long)raw_temperature - (long)ac6) * (long)ac5) >> 15;
    x1 = ((long)mc << 11) / (b5 + md);
    b6 = b5 + x1;
    x1 = (b6 >> 2) * (b6 >> 2);
    x1 = (x1 * (long)ac2) >> 11;
    x2 = ((long)ac1 * b6) >> 15;
    x3 = x1 + x2;
    b3 = (((((long)ac3) * 4 + x3) << BMP180_OSS) + 2) >> 2;
    x1 = ((long)b2 * ((b6 >> 2) * (b6 >> 2))) >> 13;
    x2 = ((long)ac2 * b6) >> 11;
    x3 = ((x1 + x2) + 2) >> 2;
    b4 = ((unsigned long)ac4 * (unsigned long)(x3 + 32768)) >> 15;
    b7 = ((unsigned long)raw_pressure - b3) * (50000 >> BMP180_OSS);
    if (b7 < 0x80000000)
    {
        p = (b7 * 2) / b4;
    }
    else
    {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);

    return (double)p / 100.0; // Return pressure in hPa
}

// Function to log data to a file or send over UDP
void log_data(double pressure)
{
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (logging_enabled) {
        FILE *fp = fopen("pressure_log.txt", "a");
        if (fp == NULL) {
            fprintf(stderr, "Error opening pressure_log.txt: %s\n", strerror(errno));
            return;
        }
        fprintf(fp, "%s, %.2f hPa\n", timestamp, pressure);
        fclose(fp);
    } else {
        fprintf(stderr, "Logging disabled. Pressure: %.2f hPa\n", pressure);
    }
}

// Interrupt handler for the button
void button_interrupt_handler(int gpio, int level, uint32_t tick, void *user_data)
{
    uint32_t now = gpioTick();
    if (now - last_interrupt_time > DEBOUNCE_TIME) {
        logging_enabled = !logging_enabled;
        printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
        last_interrupt_time = now;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (socket_fd >= 0) {
        close(socket_fd);
    }
    gpioTerminate();
    exit(0);
}

// Function to set up the UDP socket
int setup_socket(const char *server_ip, int server_port)
{
    struct sockaddr_in server_addr;

    socket_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (socket_fd < 0) {
        fprintf(stderr, "Error creating socket: %s\n", strerror(errno));
        return -1;
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(server_port);
    if (inet_pton(AF_INET, server_ip, &server_addr.sin_addr) <= 0) {
        fprintf(stderr, "Invalid address/ Address not supported: %s\n", server_ip);
        close(socket_fd);
        socket_fd = -1;
        return -1;
    }

    return 0;
}

int main(int argc, char *argv[])
{
    // Parse command-line arguments
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return 1;
    }

    server_ip = argv[1];
    server_port = atoi(argv[2]);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up UDP socket
    if (setup_socket(server_ip, server_port) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up interrupt handler for the button
    gpioSetMode(BUTTON_GPIO, PI_INPUT);
    gpioSetPullUpDown(BUTTON_GPIO, PI_PUD_UP);
    gpioSetISRFuncEx(BUTTON_GPIO, FALLING_EDGE, 0, button_interrupt_handler, NULL);

    // Set up signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        int raw_temperature, raw_pressure;
        double pressure;

        if (read_raw_temperature(&raw_temperature) != 0) {
            fprintf(stderr, "Error reading raw temperature\n");
        } else if (read_raw_pressure(&raw_pressure) != 0) {
            fprintf(stderr, "Error reading raw pressure\n");
        } else {
            pressure = calculate_pressure(raw_temperature, raw_pressure);
            log_data(pressure);

            if (socket_fd >= 0) {
                char message[256];
                snprintf(message, sizeof(message), "%s,%.2f", __TIME__, pressure);
                sendto(socket_fd, message, strlen(message), 0, (struct sockaddr *)&server_addr, sizeof(server_addr));
            }
        }

        gpioDelay(2000000); // Wait 2 seconds
    }

    return 0;
}

