#define CPU_TEMP_PATH "/sys/class/thermal/thermal_zone0/temp"
#define FAN_STATE_PATH "/sys/class/thermal/cooling_device0/cur_state"
#define MAX_STATE_PATH "/sys/class/thermal/cooling_device0/max_state"
#define LOG_FILE "/var/log/fan_control.log"

volatile sig_atomic_t program_running = 1;

// Function to read temperature from file with retry
int read_temperature(const char *path) {
    int fd, retries = 3;
    char buffer[10];
    int temperature = -1;

    while (retries > 0) {
        fd = open(path, O_RDONLY);
        if (fd == -1) {
            perror("Error opening temperature file");
            retries--;
            sleep(1); // Wait before retrying
            continue;
        }

        ssize_t bytes_read = read(fd, buffer, sizeof(buffer) - 1);
        if (bytes_read == -1) {
            perror("Error reading temperature file");
            close(fd);
            retries--;
            sleep(1);
            continue;
        }

        buffer[bytes_read] = '\0';
        temperature = atoi(buffer);
        close(fd);
        break; // Exit retry loop on success
    }

    if (temperature == -1) {
        fprintf(stderr, "Failed to read temperature after multiple retries.\n");
    }

    return temperature;
}

// Function to write fan state to file with retry
int write_fan_state(const char *path, int state) {
    int fd, retries = 3;
    char buffer[2];

    while (retries > 0) {
        fd = open(path, O_WRONLY);
        if (fd == -1) {
            perror("Error opening fan state file");
            retries--;
            sleep(1);
            continue;
        }

        snprintf(buffer, sizeof(buffer), "%d", state);
        ssize_t bytes_written = write(fd, buffer, strlen(buffer));
        if (bytes_written == -1) {
            perror("Error writing fan state file");
            close(fd);
            retries--;
            sleep(1);
            continue;
        }

        close(fd);
        break; // Exit retry loop on success
