#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

// Define GPIO pins
#define HEATER_PIN 18
#define SPI_CLK 11
#define SPI_CS 8
#define SPI_DO 9

// Define SPI channel
#define SPI_CHANNEL 0

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Define PID constants
#define Kp 1.0
#define Ki 0.1
#define Kd 0.01

// Define target temperature
#define TARGET_TEMPERATURE 50.0

// Define temperature range for failsafe
#define MIN_TEMPERATURE 0.0
#define MAX_TEMPERATURE 100.0

// Define log file name
#define LOG_FILE "heater_log.txt"

// Global variables
static volatile int running = 1;
static int spi_handle;
static FILE *log_file;

// Structure to hold PID state
typedef struct {
    double integral;
    double previous_error;
} PIDState;

PIDState pid_state = {0.0, 0.0};

// Function prototypes
double read_temperature();
double calculate_pid(double current_temperature);
void set_heater_pwm(double duty_cycle);
void log_data(double temperature, double duty_cycle, double pid_output);
void handle_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Function to read temperature from MAX31855
double read_temperature() {
    unsigned char data[4];
    int result = spiRead(spi_handle, data, 4);

    if (result != 4) {
        handle_error("SPI read failed");
        return -1000.0; // Indicate error
    }

    // Parse temperature data
    int16_t raw_temp = ((data[0] << 8) | data[1]) >> 2;
    double temperature = (double)raw_temp * 0.25;

    // Check for fault bits
    if (data[3] & 0x01) {
        handle_error("Thermocouple open circuit");
        return -1000.0;
    }
    if (data[3] & 0x02) {
        handle_error("Thermocouple short to GND");
        return -1000.0;
    }
    if (data[3] & 0x04) {
        handle_error("Thermocouple short to VCC");
        return -1000.0;
    }

    return temperature;
}

// Function to calculate PID output
double calculate_pid(double current_temperature) {
    double error = TARGET_TEMPERATURE - current_temperature;
    pid_state.integral += error;
    double derivative = error - pid_state.previous_error;
    double output = Kp * error + Ki * pid_state.integral + Kd * derivative;
    pid_state.previous_error = error;
    return output;
}

// Function to set heater PWM duty cycle
void set_heater_pwm(double duty_cycle) {
    if (duty_cycle < 0.0) duty_cycle = 0.0;
    if (duty_cycle > 100.0) duty_cycle = 100.0;

    int pwm_value = (int)(duty_cycle * 255.0 / 100.0);
    gpioPWM(HEATER_PIN, pwm_value);
}

// Function to log data to file
void log_data(double temperature, double duty_cycle, double pid_output) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Temperature: %.2f, Duty Cycle: %.2f, PID Output: %.2f\n",
            timestamp, temperature, duty_cycle, pid_output);
    fflush(log_file);
}

// Function to handle errors
void handle_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, ERROR: %s\n", timestamp, message);
    fflush(log_file);
    fprintf(stderr, "%s, ERROR: %s\n", timestamp, message);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Received signal %d, shutting down...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    set_heater_pwm(0.0); // Turn off heater
    spiClose(spi_handle); // Close SPI
    gpioTerminate(); // Terminate pigpio
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(HEATER_PIN, PI_OUTPUT);
    gpioSetMode(SPI_CLK, PI_OUTPUT);
    gpioSetMode(SPI_CS, PI_OUTPUT);
    gpioSetMode(SPI_DO, PI_INPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(HEATER_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_PIN, 255);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, 500000, 0); // SPI0, 500kHz, mode 0
    if (spi_handle < 0) {
        handle_error("SPI open failed");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        double temperature = read_temperature();

        if (temperature > MIN_TEMPERATURE && temperature < MAX_TEMPERATURE) {
            double pid_output = calculate_pid(temperature);
            double duty_cycle = pid_output; // Assuming PID output is directly proportional to duty cycle

            set_heater_pwm(duty_cycle);
            log_data(temperature, duty_cycle, pid_output);
        } else {
            handle_error("Temperature out of range, disabling heater");
            set_heater_pwm(0.0);
            pid_state.integral = 0.0; // Reset PID state
            pid_state.previous_error = 0.0;
        }

        gpioDelay(1000); // Wait 1 second
    }

    cleanup();
    return 0;
}

