#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "cooling_log.csv"

volatile sig_atomic_t program_running = 1;

// Function to read CPU temperature from file
float read_cpu_temp() {
    FILE *fp;
    int temp_milli;
    float temp_celsius;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1.0; // Indicate error
    }

    if (fscanf(fp, "%d", &temp_milli) != 1) {
        fprintf(stderr, "Error reading temperature from file\n");
        fclose(fp);
        return -1.0; // Indicate error
    }

    fclose(fp);
    temp_celsius = (float)temp_milli / 1000.0;
    return temp_celsius;
}

// Function to calculate PWM duty cycle based on temperature
int calculate_duty_cycle(float temperature) {
    int duty_cycle;

    if (temperature <= 40.0) {
        duty_cycle = 0;
    } else if (temperature >= 70.0) {
        duty_cycle = 100;
    } else {
        duty_cycle = (int)(((temperature - 40.0) / (70.0 - 40.0)) * 100.0);
    }

    return duty_cycle;
}

// Function to set PWM duty cycle
void set_fan_speed(int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > 100) {
        fprintf(stderr, "Invalid duty cycle: %d\n", duty_cycle);
        return;
    }

    int pwm_value = (int)((duty_cycle / 100.0) * 255.0); // pigpio uses 0-255 range
    gpioPWM(FAN_GPIO, pwm_value);
}

// Function to log data to file
void log_data(float temperature, int duty_cycle) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    fprintf(fp, "%s,%.2f,%d\n", timestamp, temperature, duty_cycle);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, shutting down...\n", signal);
    program_running = 0;
}

int main() {
    float temperature;
    int duty_cycle;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO mode and PWM frequency
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_GPIO, 255); // Set PWM range to 0-255

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        temperature = read_cpu_temp();
        if (temperature < 0) {
            fprintf(stderr, "Error reading temperature, using previous value.\n");
