#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define sensor addresses
#define SENSOR1_ADDR 0x08
#define SENSOR2_ADDR 0x09

// Define I2C bus
#define I2C_BUS 1

// Define measurement command
#define MEASUREMENT_COMMAND 0x3608

// Define CRC polynomial
#define CRC_POLYNOMIAL 0x31

// Global variables for I2C handles and program state
int i2c_handle1 = -1;
int i2c_handle2 = -1;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_sensor(int i2c_handle, float *flow_rate);
int validate_crc(uint8_t data[], int len);
void log_data(float flow1, float flow2);
void signal_handler(int signal);

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from a sensor
int read_sensor(int i2c_handle, float *flow_rate) {
    uint8_t buffer[3];
    int retries = 3;
    int bytes_read;

    while (retries > 0) {
        // Send measurement command
        if (i2cWriteByteData(i2c_handle, (MEASUREMENT_COMMAND >> 8) & 0xFF, MEASUREMENT_COMMAND & 0xFF) != 0) {
            fprintf(stderr, "Error writing measurement command to I2C handle %d\n", i2c_handle);
            retries--;
            gpioDelay(10000); // Wait 10ms before retrying
            continue;
        }

        // Read 3 bytes of data
        bytes_read = i2cReadDevice(i2c_handle, (char *)buffer, 3);
        if (bytes_read != 3) {
            fprintf(stderr, "Error reading data from I2C handle %d: %d bytes read\n", i2c_handle, bytes_read);
            retries--;
            gpioDelay(10000); // Wait 10ms before retrying
            continue;
        }

        // Validate CRC
        if (!validate_crc(buffer, 2)) {
            fprintf(stderr, "CRC validation failed for I2C handle %d\n", i2c_handle);
            return -1; // Indicate CRC failure
        }

        // Convert raw data to flow rate
        uint16_t raw_value = (buffer[0] << 8) | buffer[1];
        *flow_rate = (float)raw_value * 0.01;
        return 0; // Indicate success
    }

    fprintf(stderr, "Failed to read sensor data from I2C handle %d after multiple retries\n", i2c_handle);
    return -1; // Indicate failure after retries
}

// Function to validate CRC
int validate_crc(uint8_t data[], int len) {
    uint8_t calculated_crc = crc8(data, len);
    return (calculated_crc == data[len]);
}

// Function to log data to a file
void log_data(float flow1, float flow2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen("flow_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening flow_log.txt for writing\n");
        return;
    }

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, flow1, flow2);
    fclose(fp);
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Received signal %d, shutting down...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C handles for both sensors
    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C device for sensor 1: %d\n", i2c_handle1);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C device for sensor 2: %d\n", i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float flow1, flow2;

    // Main loop
    while (program_running) {
        // Read data from sensor 1
        if (read_sensor(i2c_handle1, &flow1) == 0) {
            // Read data from sensor 2
            if (read_sensor(i2c_handle2, &flow2) == 0) {
                // Log the data
                log_data(flow1, flow2);
            } else {
                fprintf(stderr, "Error reading sensor 2\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor 1\n");
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    // Close I2C handles and terminate pigpio
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    gpioTerminate();

    return 0;
}

