#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins for the rotary encoder
#define ENCODER_A 17
#define ENCODER_B 18

// Define the number of pulses per revolution
#define PULSES_PER_REVOLUTION 360

// Define the log file name
#define LOG_FILE "encoder_log.txt"

// Structure to hold the current state of the encoder
typedef struct {
    int a;
    int b;
} EncoderState;

// Global variables
static volatile int encoder_count = 0;
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
EncoderState read_encoder_state();
void update_encoder_count(EncoderState current_state, EncoderState previous_state);
void log_data(int encoder_count, float angular_position);
void signal_handler(int signal);
void cleanup();

// Function to initialize the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(ENCODER_A, PI_INPUT);
    gpioSetMode(ENCODER_B, PI_INPUT);
    gpioSetPullUpDown(ENCODER_A, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER_B, PI_PUD_UP);

    return 0;
}

// Function to read the current state of the encoder
EncoderState read_encoder_state() {
    EncoderState state;
    state.a = gpioRead(ENCODER_A);
    state.b = gpioRead(ENCODER_B);
    return state;
}

// Function to update the encoder count based on the quadrature encoding
void update_encoder_count(EncoderState current_state, EncoderState previous_state) {
    if (current_state.a != previous_state.a || current_state.b != previous_state.b) {
        if (previous_state.a == 0 && previous_state.b == 0) {
            if (current_state.a == 1 && current_state.b == 0) {
                encoder_count++;
            } else if (current_state.a == 0 && current_state.b == 1) {
                encoder_count--;
            }
        } else if (previous_state.a == 0 && previous_state.b == 1) {
            if (current_state.a == 1 && current_state.b == 1) {
                encoder_count++;
            } else if (current_state.a == 0 && current_state.b == 0) {
                encoder_count--;
            }
        } else if (previous_state.a == 1 && previous_state.b == 0) {
            if (current_state.a == 1 && current_state.b == 0) {
                encoder_count--;
            } else if (current_state.a == 0 && current_state.b == 1) {
                encoder_count++;
            }
        } else if (previous_state.a == 1 && previous_state.b == 1) {
            if (current_state.a == 0 && current_state.b == 1) {
                encoder_count--;
            } else if (current_state.a == 1 && current_state.b == 0) {
                encoder_count++;
            }
        }
    }
}

// Function to log the data to a file
void log_data(int encoder_count, float angular_position) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Encoder Count: %d, Angular Position: %.2f\n", timestamp, encoder_count, angular_position);
    fflush(log_file); // Ensure data is written to the file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    EncoderState previous_state = read_encoder_state();
    EncoderState current_state;

    // Main loop
    while (running) {
        current_state = read_encoder_state();
        update_encoder_count(current_state, previous_state);
        previous_state = current_state;

        // Normalize the angular position
        float angular_position = ((float)encoder_count / PULSES_PER_REVOLUTION) * 360.0f;

        // Log the data
        log_data(encoder_count, angular_position);

        gpioDelay(10); // Delay for 10 milliseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

