// Constants
#define I2C_BUS "/dev/i2c-1"
#define ADPD144RI_ADDR 0x39
#define FIFO_REG 0x60
#define LED_PIN 17
#define IR_THRESHOLD 2000
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "adpd144ri_log.txt"

// Global variables
static int i2c_fd = -1;
static struct gpiod_line *led_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg, uint8_t *val);
int i2c_write_reg(int fd, uint8_t reg, uint8_t val);
int adpd144ri_init(int fd);
int adpd144ri_read_data(int fd, uint16_t *red, uint16_t *ir);
void led_control(struct gpiod_line *line, int state);
void log_data(FILE *fp, uint16_t red, uint16_t ir);
void signal_handler(int sig);

// I2C read function
int i2c_read_reg(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// ADPD144RI initialization function
int adpd144ri_init(int fd) {
    // Reset the sensor (example initialization sequence)
    if (i2c_write_reg(fd, 0x00, 0x01) != 0) return -1; // Example register and value
    usleep(10000); // 10ms delay
    if (i2c_write_reg(fd, 0x01, 0x02) != 0) return -1; // Example register and value
    usleep(10000); // 10ms delay
    return 0;
}

// ADPD144RI data reading function
int adpd144ri_read_data(int fd, uint16_t *red, uint16_t *ir) {
    uint8_t buf[4];
    uint8_t reg = FIFO_REG;

    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }

    if (read(fd, buf, 4) != 4) {
        perror("I2C read failed");
        return -1;
    }

    *red = (buf[0] << 8) | buf[1];
    *ir = (buf[2] << 8) | buf[3];

    return 0;
}

// LED control function
void led_control(struct gpiod_line *line, int state) {
    if (gpiod_line_set_value(line, state) < 0) {
        perror("Failed to set LED state");
    }
}

// Data logging function
void log_data(FILE *fp, uint16_t red, uint16_t ir) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%u,%u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, red, ir);
    fflush(fp); // Ensure data is written to file immediately
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADPD144RI_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize ADPD144RI sensor
    if (adpd144ri_init(i2c_fd) != 0) {
        fprintf(stderr, "ADPD144RI initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Open GPIO line for LED control
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    if (gpiod_line_request_output(led_line, "adpd144ri", 0) < 0) {
        perror("Failed to request GPIO line for output");
        gpiod_chip_close(chip);
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    uint16_t red, ir;
    while (!terminate) {
        // Read sensor data
        if (adpd144ri_read_data(i2c_fd, &red, &ir) == 0) {
            // Log data
            log_data(log_file, red, ir);

            // Control LED based on IR threshold
            if (ir > IR_THRESHOLD) {
                led_control(led_line, 1); // Turn LED on
            } else {
                led_control(led_line, 0); // Turn LED off
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        usleep(SAMPLE_INTERVAL_MS * 1000); // Sample every 100 ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (led_line) {
        gpiod_line_set_value(led_line, 0); // Turn LED off
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    printf("Exiting.\n");
    return 0;
}

