#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

#define GPIO_PIN 18
#define LOG_FILE "rpm_log.txt"

// Global variables
volatile int pulse_count = 0;
pthread_mutex_t pulse_mutex;
FILE *log_file = NULL;
int running = 1;

// Function prototypes
void pulse_callback(int gpio, int level, uint32_t tick, void *user);
void *rpm_calculator(void *arg);
void signal_handler(int signal);

// Interrupt service routine (ISR)
void pulse_callback(int gpio, int level, uint32_t tick, void *user)
{
    if (level == PI_HIGH) // Rising edge detected
    {
        pthread_mutex_lock(&pulse_mutex);
        pulse_count++;
        pthread_mutex_unlock(&pulse_mutex);
    }
}

// RPM calculation thread
void *rpm_calculator(void *arg)
{
    while (running)
    {
        int local_pulse_count;
        pthread_mutex_lock(&pulse_mutex);
        local_pulse_count = pulse_count;
        pulse_count = 0; // Reset pulse count
        pthread_mutex_unlock(&pulse_mutex);

        // Calculate RPM
        double rpm = (double)local_pulse_count * 60.0; // 1 pulse per revolution

        // Get current timestamp
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[80];

        time(&rawtime);
        timeinfo = localtime(&rawtime);

        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Log RPM to file
        if (log_file != NULL)
        {
            fprintf(log_file, "%s,%.2f\n", timestamp, rpm);
            fflush(log_file); // Flush the buffer immediately
        }
        else
        {
            fprintf(stderr, "Error: Log file is not open.\n");
        }

        sleep(1); // Calculate RPM every 1 second
    }
    return NULL;
}

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0; // Stop the main loop

    // Disable interrupt handler
    gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, NULL, NULL);

    // Destroy mutex
    pthread_mutex_destroy(&pulse_mutex);

    // Close log file
    if (log_file != NULL)
    {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input with pull-down resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    // Initialize mutex
    if (pthread_mutex_init(&pulse_mutex, NULL) != 0)
    {
        fprintf(stderr, "Mutex initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL)
    {
        fprintf(stderr, "Error opening log file!\n");
        pthread_mutex_destroy(&pulse_mutex);
        gpioTerminate();
        return 1;
    }

    // Register interrupt handler
    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, pulse_callback, NULL) != 0)
    {
        fprintf(stderr, "Error registering interrupt handler\n");
        fclose(log_file);
        pthread_mutex_destroy(&pulse_mutex);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create RPM calculation thread
    pthread_t rpm_thread;
    if (pthread_create(&rpm_thread, NULL, rpm_calculator, NULL) != 0)
    {
        fprintf(stderr, "Error creating RPM calculation thread\n");
        gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, NULL, NULL);
        fclose(log_file);
        pthread_mutex_destroy(&pulse_mutex);
        gpioTerminate();
        return 1;
    }

    // Main loop (keep the program running until a signal is received)
    while (running)
    {
        sleep(1); // Keep the main thread alive
    }

    // Clean up resources (should not reach here if signal handler works correctly)
    pthread_join(rpm_thread, NULL);
    gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, NULL, NULL);
    fclose(log_file);
    pthread_mutex_destroy(&pulse_mutex);
    gpioTerminate();

    return 0;
}

