#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define ADPD144RI_ADDR 0x39
#define PART_ID_REG 0x00
#define FIFO_DATA_REG 0x08
#define FIFO_DATA_SIZE 6 // 2 bytes red + 2 bytes IR + 2 bytes status
#define LED_GPIO 17
#define IR_THRESHOLD 2000
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t red;
    uint16_t ir;
    uint16_t status;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_part_id();
int read_sensor_data(sensor_data_t *data);
int process_data(const sensor_data_t *data);
int log_data(const sensor_data_t *data);
void cleanup();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADPD144RI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read PART_ID register
int read_part_id() {
    int part_id = i2cReadByteData(i2c_handle, PART_ID_REG);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART_ID register: %s\n", strerror(errno));
        return -1;
    }
    printf("PART_ID: 0x%02X\n", part_id);
    return 0;
}

// Read sensor data from FIFO
int read_sensor_data(sensor_data_t *data) {
    char buffer[FIFO_DATA_SIZE];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, FIFO_DATA_REG, buffer, FIFO_DATA_SIZE);

    if (bytes_read != FIFO_DATA_SIZE) {
        fprintf(stderr, "Error reading FIFO data: %s (read %d bytes, expected %d)\n", strerror(errno), bytes_read, FIFO_DATA_SIZE);
        return -1;
    }

    data->red = (buffer[1] << 8) | buffer[0];
    data->ir = (buffer[3] << 8) | buffer[2];
    data->status = (buffer[5] << 8) | buffer[4];

    return 0;
}

// Process sensor data and control LED
