    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    int previous_state = 0; // Initialize previous state

    printf("Audio event logger started. Press Ctrl+C to exit.\n");

    while (running) {
        int current_state = read_audio_input();

        if (detect_rising_edge(current_state, previous_state)) {
            log_event(1);
        }

        previous_state = current_state;
        gpioDelay(SAMPLING_INTERVAL * 1000); // Delay for 10ms (10000 microseconds)
    }

    // Cleanup (should not reach here if signal handler works correctly)
    fclose(log_file);
    gpioTerminate();

    return 0;
}

