        return -1;
    }

    *raw_flow = (int16_t)((buffer[0] << 8) | buffer[1]);
    uint8_t crc_calculated = crc8((uint8_t *)buffer, 2);
    if (!validate_crc(crc_calculated, buffer[2])) {
