#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIOCHIP "gpiochip0"
#define GPIO_PIN 17
#define CONSUMER "ttp223_tamper"
#define TOUCH_DURATION_SEC 5

struct gpiod_chip *chip = NULL;
struct gpiod_line *line = NULL;
struct timespec last_touch_time;

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
}

int main() {
    int ret;
    struct timespec current_time;
    long time_diff_sec;

    // Register signal handlers
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal(SIGINT) failed");
        return EXIT_FAILURE;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("signal(SIGTERM) failed");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name failed");
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("gpiod_chip_get_line failed");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request GPIO line as input
    ret = gpiod_line_request(line, CONSUMER, GPIOD_LINE_REQUEST_DIRECTION_INPUT);
    if (ret < 0) {
        perror("gpiod_line_request failed");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Initialize last touch time
    clock_gettime(CLOCK_MONOTONIC, &last_touch_time);

    printf("Monitoring touch sensor on GPIO %d...\n", GPIO_PIN);

    while (!terminate) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            perror("gpiod_line_get_value failed");
            break; // Exit loop on error
        }

        if (value == 1) {
            // Touch detected
            clock_gettime(CLOCK_MONOTONIC, &current_time);
            time_diff_sec = current_time.tv_sec - last_touch_time.tv_sec;

            if (time_diff_sec >= TOUCH_DURATION_SEC) {
                printf("INTRUSION ALERT: Touch detected on GPIO %d!\n", GPIO_PIN);
                clock_gettime(CLOCK_MONOTONIC, &last_touch_time); // Reset timer
            }
        } else {
            // Touch released, reset timer
            clock_gettime(CLOCK_MONOTONIC, &last_touch_time);
        }

        usleep(100000); // 100 ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

