#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <alsa/asoundlib.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define SAMPLE_RATE 44100
#define NUM_CHANNELS 2
#define FORMAT SND_PCM_FORMAT_S24_LE
#define PERIOD_SIZE 1024
#define FILENAME "audio_capture.pcm"

static volatile int keep_running = 1;
static snd_pcm_t *pcm_handle = NULL;
static FILE *output_file = NULL;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize ALSA
int init_alsa(snd_pcm_t **pcm_handle)
{
    snd_pcm_hw_params_t *hw_params;
    int err;

    if ((err = snd_pcm_open(pcm_handle, "default", SND_PCM_STREAM_CAPTURE, 0)) < 0) {
        fprintf(stderr, "Error opening PCM device: %s\n", snd_strerror(err));
        return -1;
    }

    snd_pcm_hw_params_alloca(&hw_params);

    if ((err = snd_pcm_hw_params_any(*pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_access(*pcm_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED)) < 0) {
        fprintf(stderr, "Error setting access: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_format(*pcm_handle, hw_params, FORMAT)) < 0) {
        fprintf(stderr, "Error setting format: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_channels(*pcm_handle, hw_params, NUM_CHANNELS)) < 0) {
        fprintf(stderr, "Error setting channels: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    unsigned int rate = SAMPLE_RATE;
    if ((err = snd_pcm_hw_params_set_rate_near(*pcm_handle, hw_params, &rate, 0)) < 0) {
        fprintf(stderr, "Error setting rate: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_period_size(*pcm_handle, hw_params, PERIOD_SIZE, 0)) < 0) {
        fprintf(stderr, "Error setting period size: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params(*pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    return 0;
}

// Function to initialize pigpio
int init_gpio()
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 1); // Select left channel
    return 0;
}

// Function to capture audio data
int capture_audio(snd_pcm_t *pcm_handle, FILE *output_file)
{
    int err;
    int16_t *buffer = NULL;
    int buffer_size = PERIOD_SIZE * NUM_CHANNELS * 2; // 2 bytes per 16-bit sample

    buffer = (int16_t *)malloc(buffer_size);
    if (buffer == NULL) {
        fprintf(stderr, "Error allocating buffer\n");
        return -1;
    }

    while (keep_running) {
        if ((err = snd_pcm_readi(pcm_handle, buffer, PERIOD_SIZE)) != PERIOD_SIZE) {
            fprintf(stderr, "Error reading PCM data: %s\n", snd_strerror(err));
            break;
        }

        // Process and write the data
        for (int i = 0; i < PERIOD_SIZE; i++) {
            // Extract 24-bit data and right-shift to 16 bits
            int32_t raw_sample = (int32_t)((int8_t)buffer[2 * i] | ((int8_t)buffer[2 * i + 1] << 8) | ((int8_t)buffer[2 * i + 2] << 16));
            int16_t pcm_sample = (int16_t)(raw_sample >> 8); // Right-shift by 8 bits

            if (fwrite(&pcm_sample, sizeof(int16_t), 1, output_file) != 1) {
                fprintf(stderr, "Error writing to file\n");
                free(buffer);
                return -1;
            }
        }
    }

    free(buffer);
    return 0;
}

// Function to close resources
void cleanup(snd_pcm_t *pcm_handle, FILE *output_file)
{
    if (pcm_handle) {
        snd_pcm_drain(pcm_handle);
        snd_pcm_close(pcm_handle);
    }
    if (output_file) {
        fclose(output_file);
    }
    gpioWrite(GPIO_PIN, 0); // Set GPIO low
    gpioTerminate();
}

int main()
{
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_gpio() != 0) {
        return 1;
    }

    // Initialize ALSA
    if (init_alsa(&pcm_handle) != 0) {
        cleanup(NULL, NULL);
        return 1;
    }

    // Open output file
    output_file = fopen(FILENAME, "wb");
    if (output_file == NULL) {
        fprintf(stderr, "Error opening output file\n");
        cleanup(pcm_handle, NULL);
        return 1;
    }

    // Capture audio
    if (capture_audio(pcm_handle, output_file) != 0) {
        cleanup(pcm_handle, output_file);
        return 1;
    }

    // Cleanup resources
    cleanup(pcm_handle, output_file);

    printf("Audio capture complete. File saved as %s\n", FILENAME);
    return 0;
}

