#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define FAN_PIN 18

// Define constants
#define PWM_FREQUENCY 100 // Hz
#define PWM_RANGE 1000
#define DEBOUNCE_DELAY 50 // ms
#define TIMEOUT_DURATION 10 // seconds
#define LOG_FILE "flame_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_flame_sensor();
void control_fan(int flame_detected);
void log_event(const char *event);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(FAN_PIN, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(FAN_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_PIN, PWM_RANGE);

    return 0;
}

// Function to read the flame sensor with debouncing
int read_flame_sensor() {
    int i;
    int low_count = 0;

    for (i = 0; i < 10; i++) {
        if (gpioRead(FLAME_SENSOR_PIN) == 0) {
            low_count++;
        }
        gpioDelay(DEBOUNCE_DELAY * 1000); // Convert ms to microseconds
    }

    return (low_count >= 5) ? 1 : 0; // Flame detected if LOW is detected most of the time
}

// Function to control the cooling fan
void control_fan(int flame_detected) {
    static int fan_on = 0;
    static int fan_duty_cycle = 0;
    static time_t flame_start_time = 0;
    time_t current_time;
    double elapsed_time;
    int new_duty_cycle;

    time(&current_time);

    if (flame_detected) {
        if (!fan_on) {
            fan_on = 1;
            flame_start_time = current_time;
            log_event("Flame detected");
        }

        elapsed_time = difftime(current_time, flame_start_time);

        // Exponential duty cycle calculation
        new_duty_cycle = (int)(100 * (1 - exp(-elapsed_time / 5.0))); // Adjust the divisor for desired curve
        if (new_duty_cycle > 80) new_duty_cycle = 80; // Limit to 80%
        if (new_duty_cycle < 0) new_duty_cycle = 0; // Ensure it doesn't go negative

        if (fan_duty_cycle != new_duty_cycle) {
            fan_duty_cycle = new_duty_cycle;
            gpioPWM(FAN_PIN, (int)(fan_duty_cycle * (PWM_RANGE / 100.0)));
        }
    } else {
        if (fan_on) {
            fan_on = 0;
            gpioPWM(FAN_PIN, 0); // Turn off fan
            log_event("Flame ended");
        }
    }
}

// Function to log events to a file
void log_event(const char *event) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, event);
        fflush(log_file); // Ensure immediate write
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioPWM(FAN_PIN, 0); // Turn off fan
    gpioTerminate(); // Terminate pigpio
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return 1;
    }

    log_event("System start");

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        log_event("GPIO initialization failed");
        fclose(log_file);
        return 1;
    }

    time_t last_flame_detection = 0;
    int flame_detected = 0;

    while (running) {
        int current_flame_state = read_flame_sensor();

        if (current_flame_state != flame_detected) {
            flame_detected = current_flame_state;
            control_fan(flame_detected);
        }

        time_t now;
        time(&now);
        if (!flame_detected && (difftime(now, last_flame_detection) > TIMEOUT_DURATION)) {
            // Sensor absent timeout
            log_event("Sensor absent timeout");
            running = 0; // Exit the loop
        }

        if (flame_detected) {
            last_flame_detection = now;
        }

        gpioDelay(50 * 1000); // Check every 50 ms
    }

    cleanup();
    return 0;
}

