#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define TRIGGER_PIN 23
#define DATA_READY_PIN 24
#define HEATMAP_SIZE 32768
#define MAGIC_NUMBER 0x52444144
#define CONFIG_FRAME_PERIOD 100 // milliseconds

// Configuration structure
typedef struct {
    float start_frequency;
    float end_frequency;
    int num_chirps;
    int num_samples;
    int frame_period;
} radar_config_t;

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_spi();
int initialize_gpio();
int initialize_logging();
void cleanup();
void signal_handler(int signal);
void data_ready_callback(int gpio, int level, uint32_t tick);
int read_heatmap_data(uint8_t *data);
int log_frame(uint8_t *data, int frame_number);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Initialize GPIO
int initialize_gpio() {
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", TRIGGER_PIN);
        return -1;
    }
    if (gpioSetMode(DATA_READY_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as input\n", DATA_READY_PIN);
        return -1;
    }
    if (gpioSetPullUpDown(DATA_READY_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Error setting pull-down resistor on GPIO %d\n", DATA_READY_PIN);
        return -1;
    }
    return 0;
}

// Initialize logging
int initialize_logging() {
    log_file = fopen("radar_log.bin", "wb");
    if (log_file == NULL) {
        perror("Error opening log file");
        return -1;
    }

    // Write header
    uint32_t magic_number = MAGIC_NUMBER;
    time_t timestamp = time(NULL);
    radar_config_t config = {77.0, 79.0, 64, 256, CONFIG_FRAME_PERIOD};

    if (fwrite(&magic_number, sizeof(magic_number), 1, log_file) != 1) {
        perror("Error writing magic number to log file");
        fclose(log_file);
        return -1;
    }
    if (fwrite(&timestamp, sizeof(timestamp), 1, log_file) != 1) {
        perror("Error writing timestamp to log file");
        fclose(log_file);
        return -1;
    }
    if (fwrite(&config, sizeof(config), 1, log_file) != 1) {
        perror("Error writing configuration to log file");
        fclose(log_file);
        return -1;
    }

    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Data ready callback function
void data_ready_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) { // Rising edge
        printf("Data ready!\n");
        uint8_t *heatmap_data = (uint8_t *)malloc(HEATMAP_SIZE);
        if (heatmap_data == NULL) {
            perror("Error allocating memory for heatmap data");
            cleanup();
            exit(EXIT_FAILURE);
        }

        if (read_heatmap_data(heatmap_data) == 0) {
            static int frame_number = 0;
            if (log_frame(heatmap_data, frame_number) != 0) {
                fprintf(stderr, "Error logging frame, exiting.\n");
                free(heatmap_data);
                cleanup();
                exit(EXIT_FAILURE);
            }
            frame_number++;
        } else {
            fprintf(stderr, "Error reading heatmap data, exiting.\n");
            free(heatmap_data);
            cleanup();
            exit(EXIT_FAILURE);
        }
        free(heatmap_data);
    }
}

// Read heatmap data via SPI
int read_heatmap_data(uint8_t *data) {
    int bytes_read = spiXfer(spi_handle, (char *)data, (char *)data, HEATMAP_SIZE);
    if (bytes_read != HEATMAP_SIZE) {
        fprintf(stderr, "Error reading SPI data: %d bytes read (expected %d)\n", bytes_read, HEATMAP_SIZE);
        return -1;
    }
    return 0;
}

// Log frame data to file
int log_frame(uint8_t *data, int frame_number) {
    time_t timestamp = time(NULL);
    if (fwrite(&timestamp, sizeof(timestamp), 1, log_file) != 1) {
        perror("Error writing timestamp to log file");
        return -1;
    }
    if (fwrite(&frame_number, sizeof(frame_number), 1, log_file) != 1) {
        perror("Error writing frame number to log file");
        return -1;
    }
    if (fwrite(data, 1, HEATMAP_SIZE, log_file) != HEATMAP_SIZE) {
        perror("Error writing heatmap data to log file");
        return -1;
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        cleanup();
        return 1;
    }

    // Initialize logging
    if (initialize_logging() != 0) {
        cleanup();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set callback for data ready pin
    gpioSetAlertFuncEx(DATA_READY_PIN, data_ready_callback, NULL);

    // Main loop
    while (!terminate) {
        // Trigger a frame
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(1); // Small delay to ensure trigger is high for a short time
        gpioWrite(TRIGGER_PIN, 0);

        // Wait for a short period before triggering the next frame
        gpioDelay(10); // 10 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

