#include <errno.h>
#include <gpiod.h>

// Define the GPIO chip and line number
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17

// Global variables
static volatile sig_atomic_t terminate = 0;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to get the current timestamp in the format YYYY-MM-DD HH:MM:SS
char *get_timestamp()
{
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char *)malloc(20 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to read the flame sensor value
int read_flame_sensor(struct gpiod_line *line)
{
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading line value: %s\n", strerror(-value));
        return -1; // Indicate an error
    }
    return value;
}

// Function to log the flame detection status
void log_flame_status(int flame_detected)
{
    char *timestamp = get_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp, skipping log.\n");
        return;
    }

    if (flame_detected == 0) {
        printf("%s Flame Detected: YES\n", timestamp);
    } else {
        printf("%s Flame Detected: NO\n", timestamp);
    }

    free(timestamp);
}

int main()
{
    // Install signal handler for SIGINT
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Failed to install signal handler");
        return EXIT_FAILURE;
    }

    // Open the GPIO chip
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure the GPIO line as input with pull-up resistor
    struct gpiod_line_request_config config;
    struct gpiod_line_request_settings settings;

    memset(&config, 0, sizeof(config));
    config.consumer = "flame_detect";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    memset(&settings, 0, sizeof(settings));
    settings.flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP;

    if (gpiod_line_request(line, &config, &settings) < 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        int flame_detected = read_flame_sensor(line);
        if (flame_detected != -1) {
            log_flame_status(flame_detected);
        } else {
            fprintf(stderr, "Error reading flame sensor, retrying...\n");
        }
        sleep(1);
    }

    // Cleanup
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

