// Global variable to control the main loop
volatile sig_atomic_t running = 1;

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    for (int i = 0; i < num_channels; i++) {
        if (gpioSetMode(gpio_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as input\n", gpio_pins[i]);
            gpioTerminate();
            return 1; // Indicate failure
        }

        if (gpioSetPullUpDown(gpio_pins[i], PI_PUD_DOWN) != 0) {
            fprintf(stderr, "Failed to set pull-down resistor on GPIO %d\n", gpio_pins[i]);
            gpioTerminate();
            return 1; // Indicate failure
        }
    }
    return 0; // Indicate success
}

// Function to read the sensor data
int read_sensor_data(int *data) {
    for (int i = 0; i < num_channels; i++) {
        data[i] = gpioRead(gpio_pins[i]);
        if (data[i] < 0) {
            fprintf(stderr, "Failed to read GPIO %d\n", gpio_pins[i]);
            return 1; // Indicate failure
        }
    }
    return 0; // Indicate success
}

// Function to log the sensor data
void log_sensor_data(int *data) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

    printf("[%s] ", buf);
    for (int i = 0; i < num_channels; i++) {
        printf("CH%d=%d ", i + 1, data[i]);
    }
    printf("\n");
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    int sensor_data[num_channels];

    // Main loop
    while (running) {
        // Read sensor data
        if (read_sensor_data(sensor_data) == 0) {
            // Log sensor data
            log_sensor_data(sensor_data);
        } else {
            fprintf(stderr, "Error reading sensor data. Exiting.\n");
            break; // Exit loop on error
        }

        // Delay for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Terminate pigpio
    gpioTerminate();
    printf("pigpio terminated.\n");

    return 0;
}

