#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

// Define the GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define the GPIO lines for the touch sensor channels
const int gpio_lines[] = {2, 3, 4, 17, 27, 22, 10, 9};
const int num_channels = sizeof(gpio_lines) / sizeof(gpio_lines[0]);

// Global variable to store the GPIO chip
struct gpiod_chip *chip = NULL;

// Global variable to store the GPIO lines
struct gpiod_line *lines[num_channels];

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    for (int i = 0; i < num_channels; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }

    // Close GPIO chip
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to read the state of a single GPIO line
int read_gpio_line(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line: %s\n", strerror(errno));
        return -1; // Indicate an error
    }
    return value;
}

// Function to log the sensor data to the console in CSV format
void log_sensor_data(const char *timestamp, int sensor_values[]) {
    printf("%s", timestamp);
    for (int i = 0; i < num_channels; i++) {
        printf(",%d", sensor_values[i]);
    }
    printf("\n");
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open(GPIOCHIP);
    if (chip == NULL) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Request the GPIO lines for input
    for (int i = 0; i < num_channels; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpio_lines[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Error getting GPIO line %d: %s\n", gpio_lines[i], strerror(errno));
            // Release previously acquired lines
            for (int j = 0; j < i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return 1;
        }

        struct gpiod_line_request_config config;
        memset(&config, 0, sizeof(config));
        config.consumer = "touch_sensor";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

        if (gpiod_line_request(lines[i], &config, 0) < 0) {
            fprintf(stderr, "Error requesting GPIO line %d: %s\n", gpio_lines[i], strerror(errno));
            // Release previously acquired lines
            for (int j = 0; j <= i; j++) {
                gpiod_line_release(lines[j]);
            }
            gpiod_chip_close(chip);
            return 1;
        }
    }

    // Main loop to read and log sensor data
    while (1) {
        int sensor_values[num_channels];
        char *timestamp = get_iso8601_timestamp();

        if (timestamp == NULL) {
            fprintf(stderr, "Failed to get timestamp, exiting.\n");
            break; // Exit the loop if timestamp generation fails
        }

        for (int i = 0; i < num_channels; i++) {
            sensor_values[i] = read_gpio_line(lines[i]);
            if (sensor_values[i] < 0) {
                fprintf(stderr, "Error reading sensor value for channel %d, exiting.\n", i);
                free(timestamp);
                goto cleanup; // Exit the loop if reading fails
            }
        }

        log_sensor_data(timestamp, sensor_values);
        free(timestamp);

        // Wait for 50 milliseconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 50 * 1000 * 1000; // 50 milliseconds
        nanosleep(&sleep_time, NULL);
    }

cleanup:
    // Release GPIO lines
    for (int i = 0; i < num_channels; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }

    // Close GPIO chip
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    return 0;
}

