        nanosleep(&sleep_time, NULL);
    }

cleanup:
    // Release GPIO lines
    for (int i = 0; i < num_channels; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }

    // Close GPIO chip
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    return 0;
}

