#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Si1145 I2C address
#define SI1145_ADDR 0x60

// Si1145 register addresses
#define SI1145_PART_ID 0x00
#define SI1145_HW_KEY 0x07
#define SI1145_CHLIST 0x01
#define SI1145_ALS_VIS_DATA0 0x22
#define SI1145_ALS_VIS_DATA1 0x23
#define SI1145_UV_INDEX0 0x2C
#define SI1145_ALS_FORCE 0x18

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float uv_index;
    uint16_t als_visible;
} sensor_data_t;

// Function prototypes
int init_si1145();
sensor_data_t read_sensor_data();
void log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Initialize the Si1145 sensor
int init_si1145() {
    // Verify PART ID
    int part_id = i2cReadByteData(i2c_handle, SI1145_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART ID: %d\n", part_id);
        return -1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Incorrect PART ID: 0x%02X\n", part_id);
        return -1;
    }

    // Write HW_KEY
    int status = i2cWriteByteData(i2c_handle, SI1145_HW_KEY, 0x17);
    if (status < 0) {
        fprintf(stderr, "Error writing HW_KEY: %d\n", status);
        return -1;
    }

    // Configure CHLIST
    status = i2cWriteByteData(i2c_handle, SI1145_CHLIST, 0x77); // Enable UV and ALS_VIS
    if (status < 0) {
        fprintf(stderr, "Error writing CHLIST: %d\n", status);
        return -1;
    }

    return 0;
}

// Read UV index and Visible ALS data from the sensor
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    int status;

    // Trigger measurement
    status = i2cWriteByteData(i2c_handle, SI1145_ALS_FORCE, 0x01);
    if (status < 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", status);
        data.uv_index = -1.0; // Indicate error
        data.als_visible = 0; // Indicate error
        return data;
    }

    // Wait for measurement to complete (adjust delay as needed)
    gpioDelay(10); // 10ms delay

    // Read UV index
    int uv_index_raw = i2cReadByteData(i2c_handle, SI1145_UV_INDEX0);
    if (uv_index_raw < 0) {
        fprintf(stderr, "Error reading UV index: %d\n", uv_index_raw);
        data.uv_index = -1.0; // Indicate error
    } else {
        data.uv_index = (float)uv_index_raw / 10.0; // UV index is stored as integer * 10
    }

    // Read Visible ALS data
    int als_visible_low = i2cReadByteData(i2c_handle, SI1145_ALS_VIS_DATA0);
    int als_visible_high = i2cReadByteData(i2c_handle, SI1145_ALS_VIS_DATA1);

    if (als_visible_low < 0 || als_visible_high < 0) {
        fprintf(stderr, "Error reading ALS data: %d, %d\n", als_visible_low, als_visible_high);
        data.als_visible = 0; // Indicate error
    } else {
        data.als_visible = (uint16_t)((als_visible_high << 8) | als_visible_low);
    }

    return data;
}

// Log data to CSV file
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%u\n", timestamp, data.uv_index, data.als_visible);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize Si1145 sensor
    if (init_si1145() != 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("uv_als_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,uv_index,als_visible\n");
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        sensor_data_t data = read_sensor_data();

        if (data.uv_index >= 0) {
            printf("UV Index: %.2f, Visible ALS: %u\n", data.uv_index, data.als_visible);
            log_data(data);
        } else {
            fprintf(stderr, "Error reading sensor data, skipping logging.\n");
        }

        gpioDelay(1000); // 1 second delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

