#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SENSOR1_ADDR 0x36
#define SENSOR2_ADDR 0x37
#define MEASUREMENT_CMD 0x3608
#define FLOW_SCALE_FACTOR 0.036
#define ALARM_GPIO 17
#define LOG_FILE "flow_log.txt"

// Global variables
int i2c_fd1 = -1;
int i2c_fd2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(int address);
int read_sensor(int fd, int *flow, int *temperature, uint8_t *crc);
int validate_crc(int flow, uint8_t crc);
float convert_flow(int raw_flow);
float calculate_average_flow(float flow1, float flow2);
void set_alarm(int gpio, int state);
void log_flow(float average_flow);
void signal_handler(int signal);

// CRC calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C communication
int init_i2c(int address) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Read sensor data
int read_sensor(int fd, int *flow, int *temperature, uint8_t *crc) {
    uint8_t buffer[9];
    uint8_t cmd[2] = {0x08, MEASUREMENT_CMD >> 8, MEASUREMENT_CMD & 0xFF};

    if (write(fd, cmd, 2) != 2) {
        perror("Error writing measurement command");
        return -1;
    }

    usleep(100000); // Wait 100 ms

    if (read(fd, buffer, 9) != 9) {
        perror("Error reading sensor data");
        return -1;
    }

    *flow = (buffer[0] << 8) | buffer[1];
    *temperature = (buffer[3] << 8) | buffer[4];
    *crc = buffer[6];

    return 0;
}

// Validate CRC
int validate_crc(int flow, uint8_t crc) {
    uint8_t data[2] = {(flow >> 8) & 0xFF, flow & 0xFF};
    uint8_t calculated_crc = crc8(data, 2);
    return (crc == calculated_crc);
}

// Convert raw flow to ml/min
float convert_flow(int raw_flow) {
    return raw_flow * FLOW_SCALE_FACTOR;
}

// Calculate average flow rate
float calculate_average_flow(float flow1, float flow2) {
    return (flow1 + flow2) / 2.0;
}

// Set alarm state
void set_alarm(int gpio, int state) {
    gpioWrite(gpio, state);
}

// Log flow rate to file
void log_flow(float average_flow) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %.2f\n", timestamp, average_flow);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set alarm GPIO as output
    gpioSetMode(ALARM_GPIO, PI_OUTPUT);

    // Initialize I2C
    i2c_fd1 = init_i2c(SENSOR1_ADDR);
    if (i2c_fd1 < 0) {
        fprintf(stderr, "Failed to initialize I2C for sensor 1\n");
        gpioTerminate();
        return 1;
    }

    i2c_fd2 = init_i2c(SENSOR2_ADDR);
    if (i2c_fd2 < 0) {
        fprintf(stderr, "Failed to initialize I2C for sensor 2\n");
        close(i2c_fd1);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd1);
        close(i2c_fd2);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int flow1_raw, temperature1, flow2_raw, temperature2;
    uint8_t crc1, crc2;
    float flow1, flow2, average_flow;

    // Main loop
    while (!terminate) {
        // Read sensor 1
        if (read_sensor(i2c_fd1, &flow1_raw, &temperature1, &crc1) == 0) {
            if (validate_crc(flow1_raw, crc1)) {
                flow1 = convert_flow(flow1_raw);
            } else {
                fprintf(stderr, "CRC validation failed for sensor 1\n");
                flow1 = 0.0; // Set to 0 to avoid using invalid data
            }
        } else {
            fprintf(stderr, "Failed to read sensor 1\n");
            flow1 = 0.0; // Set to 0 to avoid using invalid data
        }

        // Read sensor 2
        if (read_sensor(i2c_fd2, &flow2_raw, &temperature2, &crc2) == 0) {
            if (validate_crc(flow2_raw, crc2)) {
                flow2 = convert_flow(flow2_raw);
            } else {
                fprintf(stderr, "CRC validation failed for sensor 2\n");
                flow2 = 0.0; // Set to 0 to avoid using invalid data
            }
        } else {
            fprintf(stderr, "Failed to read sensor 2\n");
            flow2 = 0.0; // Set to 0 to avoid using invalid data
        }

        // Calculate average flow rate
        average_flow = calculate_average_flow(flow1, flow2);

        // Set alarm state
        if (average_flow < 0.5) {
            set_alarm(ALARM_GPIO, 1); // HIGH
        } else {
            set_alarm(ALARM_GPIO, 0); // LOW
        }

        // Log flow rate
        log_flow(average_flow);

        sleep(1);
    }

    // Cleanup
    close(i2c_fd1);
    close(i2c_fd2);
    fclose(log_file);
    gpioWrite(ALARM_GPIO, 0); // Ensure alarm is off
    gpioTerminate();

    return 0;
}

