#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

#define GPIO_PIN 4
#define BUFFER_SIZE 100

// Structure to hold timestamp and sensor reading
typedef struct {
    time_t timestamp;
    int reading;
} SensorData;

// Circular buffer
SensorData circularBuffer[BUFFER_SIZE];
int bufferIndex = 0;
int bufferCount = 0; // Number of elements in the buffer

// Function prototypes
int initializeGPIO();
int readSensor();
void addToBuffer(time_t timestamp, int reading);
void printBuffer();
void signalHandler(int signal);

// Global variable to indicate program termination
volatile sig_atomic_t programRunning = 1;

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signalHandler);

    // Initialize pigpio
    if (initializeGPIO() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    printf("Obstacle detection program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (programRunning) {
        int reading = readSensor();

        if (reading == 0) {
            time_t now = time(NULL);
            addToBuffer(now, reading);
            printf("Obstacle detected at: %s", ctime(&now));
        }

        gpioDelay(50); // Poll every 50 ms
    }

    // Clean up and exit
    printBuffer();
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return 0;
}

// Initializes the pigpio library and configures the GPIO pin
int initializeGPIO() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP); // Enable pull-up resistor

    return 0;
}

// Reads the sensor value from the specified GPIO pin
int readSensor() {
    return gpioRead(GPIO_PIN);
}

// Adds a new entry to the circular buffer
void addToBuffer(time_t timestamp, int reading) {
    circularBuffer[bufferIndex].timestamp = timestamp;
    circularBuffer[bufferIndex].reading = reading;

    bufferIndex = (bufferIndex + 1) % BUFFER_SIZE;
    if (bufferCount < BUFFER_SIZE) {
        bufferCount++;
    }
}

// Prints the contents of the circular buffer
void printBuffer() {
    printf("\n--- Sensor Data Log ---\n");
    int startIndex = (bufferIndex + BUFFER_SIZE - bufferCount) % BUFFER_SIZE;
    for (int i = 0; i < bufferCount; i++) {
        int index = (startIndex + i) % BUFFER_SIZE;
        char timestampStr[30];
        struct tm *tm_info = localtime(&circularBuffer[index].timestamp);
        strftime(timestampStr, sizeof(timestampStr), "%Y-%m-%d %H:%M:%S", tm_info);
        printf("Timestamp: %s, Reading: %d\n", timestampStr, circularBuffer[index].reading);
    }
    printf("--- End of Log ---\n");
}

// Signal handler for SIGINT (Ctrl+C)
void signalHandler(int signal) {
    programRunning = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

