#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define D7S_ADDR 0x55
#define MODE_CONTROL_REG 0x1D
#define OPERATING_STATUS_REG 0x1B
#define ACCEL_X_LSB_REG 0x2A
#define ACCEL_Y_LSB_REG 0x2C
#define ACCEL_Z_LSB_REG 0x2E
#define ACCEL_SCALE 0.0009765625f
#define SAMPLE_INTERVAL_MS 500
#define MAX_RETRIES 3

// Global variables
int i2c_fd = -1;
FILE *csv_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int i2c_read_byte(int fd, uint8_t reg, uint8_t *value);
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len);
int init_d7s(int fd);
int read_acceleration(int fd, float *x, float *y, float *z);
void log_data(FILE *fp, float x, float y, float z);
void signal_handler(int sig);

// I2C write function with retry
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    int retries = 0;
    int result = -1;
    while (retries < MAX_RETRIES) {
        result = i2c_smbus_write_byte_data(fd, reg, value);
        if (result == 0) {
            return 0; // Success
        }
        fprintf(stderr, "I2C write error (reg 0x%02X, value 0x%02X): %s\n", reg, value, strerror(errno));
        retries++;
        usleep(10000); // 10ms delay
    }
    return -1; // Failure after retries
}

// I2C read function with retry
int i2c_read_byte(int fd, uint8_t reg, uint8_t *value) {
    int retries = 0;
    int result = -1;
    while (retries < MAX_RETRIES) {
        result = i2c_smbus_read_byte_data(fd, reg);
        if (result >= 0) {
            *value = (uint8_t)result;
            return 0; // Success
        }
        fprintf(stderr, "I2C read error (reg 0x%02X): %s\n", reg, strerror(errno));
        retries++;
        usleep(10000); // 10ms delay
    }
    return -1; // Failure after retries
}

// I2C read multiple bytes function with retry
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len) {
    int retries = 0;
    int result = -1;
    while (retries < MAX_RETRIES) {
        result = i2c_smbus_read_i2c_block_data(fd, reg, len, buf);
        if (result == len) {
            return 0; // Success
        }
        fprintf(stderr, "I2C block read error (reg 0x%02X, len %d): %s\n", reg, len, strerror(errno));
        retries++;
        usleep(10000); // 10ms delay
    }
    return -1; // Failure after retries
}

// Initialize D7S sensor
int init_d7s(int fd) {
    uint8_t status;

    // Set MODE_CONTROL_REG to 0x10 to activate the sensor
    if (i2c_write_byte(fd, MODE_CONTROL_REG, 0x10) != 0) {
        fprintf(stderr, "Failed to set MODE_CONTROL_REG\n");
        return -1;
    }

    // Wait for the sensor to become active (bit 0 of OPERATING_STATUS_REG should be 1)
    int timeout = 1000; // 1 second timeout
    while (timeout > 0) {
        if (i2c_read_byte(fd, OPERATING_STATUS_REG, &status) != 0) {
            fprintf(stderr, "Failed to read OPERATING_STATUS_REG\n");
            return -1;
        }
        if ((status & 0x01) == 0x01) {
            break; // Sensor is active
        }
        usleep(1000); // 1ms delay
        timeout--;
    }

    if (timeout == 0) {
        fprintf(stderr, "Sensor failed to become active\n");
        return -1;
    }

    return 0;
}

// Read acceleration data from D7S sensor
int read_acceleration(int fd, float *x, float *y, float *z) {
    uint8_t buf[6];
    int16_t raw_x, raw_y, raw_z;

    if (i2c_read_bytes(fd, ACCEL_X_LSB_REG, buf, 6) != 0) {
        fprintf(stderr, "Failed to read acceleration data\n");
        return -1;
    }

    raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    raw_z = (int16_t)((buf[5] << 8) | buf[4]);

    *x = (float)raw_x * ACCEL_SCALE;
    *y = (float)raw_y * ACCEL_SCALE;
    *z = (float)raw_z * ACCEL_SCALE;

    return 0;
}

// Log data to CSV file
void log_data(FILE *fp, float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(fp, "%s,%.6f,%.6f,%.6f\n", timestamp, x, y, z);
    fflush(fp); // Ensure data is written immediately
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received (%d). Terminating...\n", sig);
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, D7S_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize D7S sensor
    if (init_d7s(i2c_fd) != 0) {
        fprintf(stderr, "D7S initialization failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    csv_file = fopen("fan_health.csv", "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Failed to open CSV file: %s\n", strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "timestamp,x,y,z\n");
    }
    rewind(csv_file);

    float x, y, z;

    // Main loop
    while (!terminate) {
        if (read_acceleration(i2c_fd, &x, &y, &z) == 0) {
            log_data(csv_file, x, y, z);
        } else {
            fprintf(stderr, "Failed to read acceleration data. Retrying...\n");
        }
        usleep(SAMPLE_INTERVAL_MS * 1000); // 500ms delay
    }

    // Cleanup
    close(i2c_fd);
    fclose(csv_file);
    gpioTerminate();

    return 0;
}

