    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(fp, "%s,%.6f,%.6f,%.6f\n", timestamp, x, y, z);
    fflush(fp); // Ensure data is written immediately
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received (%d). Terminating...\n", sig);
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, D7S_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize D7S sensor
    if (init_d7s(i2c_fd) != 0) {
        fprintf(stderr, "D7S initialization failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    csv_file = fopen("fan_health.csv", "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Failed to open CSV file: %s\n", strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "timestamp,x,y,z\n");
    }
    rewind(csv_file);

    float x, y, z;

    // Main loop
    while (!terminate) {
        if (read_acceleration(i2c_fd, &x, &y, &z) == 0) {
            log_data(csv_file, x, y, z);
        } else {
            fprintf(stderr, "Failed to read acceleration data. Retrying...\n");
        }
        usleep(SAMPLE_INTERVAL_MS * 1000); // 500ms delay
    }

    // Cleanup
    close(i2c_fd);
    fclose(csv_file);
    gpioTerminate();

    return 0;
}

