#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define LED_PIN 25

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set sensor pins as inputs
    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_1_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_2_PIN);
        gpioTerminate();
        return -1;
    }

    // Set LED pin as output
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read sensor values
int read_sensors(int *sensor1_value, int *sensor2_value) {
    *sensor1_value = gpioRead(SENSOR_1_PIN);
    *sensor2_value = gpioRead(SENSOR_2_PIN);

    if (*sensor1_value < 0 || *sensor2_value < 0) {
        fprintf(stderr, "Error reading sensor values\n");
        return -1;
    }

    return 0;
}

// Function to control the LED
void control_led(int sensor1_value, int sensor2_value) {
    if (sensor1_value == 0 || sensor2_value == 0) {
        gpioWrite(LED_PIN, 1); // Turn LED ON
    } else {
        gpioWrite(LED_PIN, 0); // Turn LED OFF
    }
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    int sensor1_value, sensor2_value;

    // Main loop
    while (program_running) {
        // Read sensor values
        if (read_sensors(&sensor1_value, &sensor2_value) == 0) {
            // Control the LED based on sensor values
            control_led(sensor1_value, sensor2_value);
        } else {
            fprintf(stderr, "Error in sensor reading, exiting...\n");
            break;
        }

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Clean up GPIO resources before exiting
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

