#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// TMAG5170 I2C address
#define TMAG5170_ADDR 0x0E

// TMAG5170 register addresses
#define TMAG5170_REG_X_AXIS 0x01
#define TMAG5170_REG_Y_AXIS 0x03
#define TMAG5170_REG_Z_AXIS 0x05
#define TMAG5170_REG_CONFIG 0x09
#define TMAG5170_REG_DEVICE_ID 0x00

// Configuration values
#define TMAG5170_CONFIG_CONTINUOUS 0x03 // Continuous conversion mode
#define TMAG5170_CONFIG_RANGE_50MT 0x00 // 50 mT range

// LSB scale factor for 50 mT range
#define TMAG5170_LSB_50MT 0.0000122 // 12.2 uT/LSB = 0.0122 mT/LSB

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float x;
    float y;
    float z;
} sensor_data_t;

// Function prototypes
int initialize_sensor();
sensor_data_t read_sensor_data();
void log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Function to initialize the TMAG5170 sensor
int initialize_sensor() {
    // Verify device ID
    int device_id = i2cReadByteData(i2c_handle, TMAG5170_REG_DEVICE_ID);
    if (device_id < 0) {
        fprintf(stderr, "Error reading device ID: %s\n", strerror(errno));
        return -1;
    }
    if (device_id != 0x8D) {
        fprintf(stderr, "Error: Incorrect device ID (0x%02X, expected 0x8D)\n", device_id);
        return -1;
    }
    printf("TMAG5170 device ID: 0x%02X\n", device_id);

    // Configure the sensor for continuous conversion mode and 50 mT range
    int config_value = (TMAG5170_CONFIG_CONTINUOUS << 6) | (TMAG5170_CONFIG_RANGE_50MT << 0);
    int write_result = i2cWriteByteData(i2c_handle, TMAG5170_REG_CONFIG, config_value);
    if (write_result < 0) {
        fprintf(stderr, "Error writing to configuration register: %s\n", strerror(errno));
        return -1;
    }

    printf("TMAG5170 configured for continuous conversion and 50 mT range.\n");
    return 0;
}

// Function to read sensor data
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    int16_t raw_x, raw_y, raw_z;

    // Read raw X axis data
    raw_x = i2cReadWordData(i2c_handle, TMAG5170_REG_X_AXIS);
    if (raw_x < 0) {
        fprintf(stderr, "Error reading X axis data: %s\n", strerror(errno));
        data.x = 0.0; // Set to 0.0 in case of error
    } else {
        data.x = (float)((int16_t)raw_x) * TMAG5170_LSB_50MT;
    }

    // Read raw Y axis data
    raw_y = i2cReadWordData(i2c_handle, TMAG5170_REG_Y_AXIS);
    if (raw_y < 0) {
        fprintf(stderr, "Error reading Y axis data: %s\n", strerror(errno));
        data.y = 0.0; // Set to 0.0 in case of error
    } else {
        data.y = (float)((int16_t)raw_y) * TMAG5170_LSB_50MT;
    }

    // Read raw Z axis data
    raw_z = i2cReadWordData(i2c_handle, TMAG5170_REG_Z_AXIS);
    if (raw_z < 0) {
        fprintf(stderr, "Error reading Z axis data: %s\n", strerror(errno));
        data.z = 0.0; // Set to 0.0 in case of error
    } else {
        data.z = (float)((int16_t)raw_z) * TMAG5170_LSB_50MT;
    }

    return data;
}

// Function to log data to a CSV file
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.6f,%.6f,%.6f\n", timestamp, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, TMAG5170_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen("magnetic_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,X,Y,Z\n");
    }
    fflush(log_file);

    // Main loop
    while (!terminate) {
        // Read sensor data
        sensor_data_t data = read_sensor_data();

        // Log the data
        log_data(data);

        // Wait for 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

