                gpioSetMode(GPIO_PIN, PI_INPUT);
                gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);
                log_event("pigpio re-initialisation successful");
            }
        }

        sleep(POLL_INTERVAL);
    }

    // Clean up and terminate pigpio
    gpioTerminate();
    printf("Water level monitoring daemon stopped.\n");
    return 0;
}

