#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define LOG_FILE "rpm_log.txt"

// Global variables
volatile int pulse_count = 0;
FILE *log_file = NULL;
pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
volatile int running = 1;

// Function prototypes
void pulse_callback(int gpio, int level, uint32_t tick, void *user);
void *timer_callback(void *arg);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure to pass data to the timer thread
typedef struct {
    int gpio;
    FILE *log_file;
} timer_data_t;

// Interrupt callback function
void pulse_callback(int gpio, int level, uint32_t tick, void *user) {
    if (level == PI_HIGH) { // Rising edge
        pthread_mutex_lock(&pulse_mutex);
        pulse_count++;
        pthread_mutex_unlock(&pulse_mutex);
    }
}

// Timer callback function (runs in a separate thread)
void *timer_callback(void *arg) {
    timer_data_t *data = (timer_data_t *)arg;
    int gpio = data->gpio;
    FILE *log_file = data->log_file;
    int local_pulse_count;
    double rpm;

    // Disable interrupts temporarily
    gpioSetAlertFuncEx(gpio, NULL, NULL); // Disable callback

    // Read and reset pulse count atomically
    pthread_mutex_lock(&pulse_mutex);
    local_pulse_count = pulse_count;
    pulse_count = 0;
    pthread_mutex_unlock(&pulse_mutex);

    // Re-enable interrupts
    gpioSetAlertFuncEx(gpio, pulse_callback, NULL); // Re-enable callback

    // Calculate RPM
    rpm = (double)local_pulse_count * 60.0;

    // Get current timestamp
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Log to file and stdout
    fprintf(log_file, "%s %.2f\n", timestamp, rpm);
    fflush(log_file); // Ensure immediate write
    printf("%s %.2f\n", timestamp, rpm);

    return NULL;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    cleanup();
    exit(0);
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input with pull-up resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Set up interrupt callback
    if (gpioSetAlertFuncEx(GPIO_PIN, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Error setting up interrupt callback\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    // Disable interrupt callback
    gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    pthread_t timer_thread;
    timer_data_t timer_data;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    // Prepare data for the timer thread
    timer_data.gpio = GPIO_PIN;
    timer_data.log_file = log_file;

    // Create timer thread
    if (pthread_create(&timer_thread, NULL, timer_callback, &timer_data) != 0) {
        fprintf(stderr, "Error creating timer thread\n");
        cleanup();
        return 1;
    }

    // Main loop (keep the program running until a signal is received)
    while (running) {
        sleep(1); // Sleep for 1 second
    }

    // Wait for the timer thread to finish
    pthread_join(timer_thread, NULL);

    // Cleanup (should not reach here if signal handler works correctly)
    cleanup();

    return 0;
}

