#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins for the Hall-effect sensors
#define SENSOR_A_PIN 17
#define SENSOR_B_PIN 27

// Define the log file name
#define LOG_FILE "rotation_log.txt"

// Define the number of quadrature states
#define NUM_QUADRATURE_STATES 4

// Define the quadrature states
typedef enum {
    STATE_00,
    STATE_01,
    STATE_11,
    STATE_10
} QuadratureState;

// Structure to hold the current state of the quadrature decoder
typedef struct {
    QuadratureState currentState;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    volatile int running;
} QuadratureDecoderState;

// Global variable to store the quadrature decoder state
QuadratureDecoderState decoderState;

// Function prototypes
void initializeQuadratureDecoder(QuadratureDecoderState *state);
void decodeQuadrature(QuadratureDecoderState *state, int sensorAValue, int sensorBValue);
void logRotationEvent(const char *direction);
void signalHandler(int signal);
void *sensorMonitoringThread(void *arg);

// Function to initialize the quadrature decoder state
void initializeQuadratureDecoder(QuadratureDecoderState *state) {
    state->currentState = STATE_00;
    pthread_mutex_init(&state->mutex, NULL);
    pthread_cond_init(&state->cond, NULL);
    state->running = 1;
}

// Function to decode the quadrature signal and determine the direction of rotation
void decodeQuadrature(QuadratureDecoderState *state, int sensorAValue, int sensorBValue) {
    QuadratureState newState;

    // Determine the new state based on the sensor values
    if (sensorAValue == 0 && sensorBValue == 0) {
        newState = STATE_00;
    } else if (sensorAValue == 0 && sensorBValue == 1) {
        newState = STATE_01;
    } else if (sensorAValue == 1 && sensorBValue == 1) {
        newState = STATE_11;
    } else {
        newState = STATE_10;
    }

    // Determine the direction of rotation based on the state transition
    char direction[10];
    if (newState == STATE_01 && state->currentState == STATE_00) {
        strcpy(direction, "CW");
    } else if (newState == STATE_11 && state->currentState == STATE_01) {
        strcpy(direction, "CW");
    } else if (newState == STATE_10 && state->currentState == STATE_11) {
        strcpy(direction, "CW");
    } else if (newState == STATE_00 && state->currentState == STATE_10) {
        strcpy(direction, "CW");
    } else if (newState == STATE_00 && state->currentState == STATE_01) {
        strcpy(direction, "CCW");
    } else if (newState == STATE_01 && state->currentState == STATE_11) {
        strcpy(direction, "CCW");
    } else if (newState == STATE_11 && state->currentState == STATE_10) {
        strcpy(direction, "CCW");
    } else if (newState == STATE_10 && state->currentState == STATE_00) {
        strcpy(direction, "CCW");
    } else {
        strcpy(direction, "Unknown");
    }

    // Update the current state
    pthread_mutex_lock(&state->mutex);
    state->currentState = newState;
    pthread_mutex_unlock(&state->mutex);

    // Log the rotation event
    logRotationEvent(direction);
}

// Function to log the rotation event to a file
void logRotationEvent(const char *direction) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    // Get the current time
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    // Format the timestamp
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", ts.tv_nsec / 1000000);

    // Write the log entry
    fprintf(fp, "%s %s\n", timestamp, direction);

    // Close the file
    fclose(fp);
}

// Signal handler function
void signalHandler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);

    // Stop the sensor monitoring thread
    decoderState.running = 0;
    pthread_cond_signal(&decoderState.cond);

    // Destroy the mutex and condition variable
    pthread_mutex_destroy(&decoderState.mutex);
    pthread_cond_destroy(&decoderState.cond);

    // Terminate the pigpio library
    gpioTerminate();

    exit(0);
}

// Thread function to monitor the sensor values
void *sensorMonitoringThread(void *arg) {
    int sensorAValue, sensorBValue;

    while (decoderState.running) {
        // Read the sensor values
        sensorAValue = gpioRead(SENSOR_A_PIN);
        sensorBValue = gpioRead(SENSOR_B_PIN);

        // Decode the quadrature signal
        decodeQuadrature(&decoderState, sensorAValue, sensorBValue);

        // Sleep for a short period
        gpioDelay(1000); // 1ms
    }

    pthread_exit(NULL);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pins as inputs
    gpioSetMode(SENSOR_A_PIN, PI_INPUT);
    gpioSetMode(SENSOR_B_PIN, PI_INPUT);

    // Set the pull-up resistors
    gpioSetPullUpDown(SENSOR_A_PIN, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR_B_PIN, PI_PUD_UP);

    // Initialize the quadrature decoder state
    initializeQuadratureDecoder(&decoderState);

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    // Create the sensor monitoring thread
    pthread_t sensorThread;
    if (pthread_create(&sensorThread, NULL, sensorMonitoringThread, NULL) != 0) {
        perror("Error creating sensor monitoring thread");
        gpioTerminate();
        return 1;
    }

    // Wait for the sensor monitoring thread to finish
    pthread_join(sensorThread, NULL);

    // Clean up resources
    pthread_mutex_destroy(&decoderState.mutex);
    pthread_cond_destroy(&decoderState.cond);
    gpioTerminate();

    return 0;
}

