#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 23
#define LED_PIN 18

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variables
static volatile int running = 1;
static int led_state = 0; // 0 = off, 1 = on

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
int control_led(int state);
void log_event(const char *message);
void signal_handler(int signal);
void cleanup();

int main() {
    // Open syslog for logging
    openlog("touch_sensor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        log_event("GPIO initialization failed. Exiting.");
        closelog();
        return 1;
    }

    log_event("Touch sensor monitoring started.");

    // Main loop
    while (running) {
        int touch_detected = read_touch_sensor();

        if (touch_detected == 1) {
            if (led_state == 0) {
                if (control_led(1) == 0) {
                    led_state = 1;
                    log_event("Touch detected. LED turned ON.");
                } else {
                    log_event("Failed to turn LED ON.");
                }
            }
        } else if (touch_detected == 0) {
            if (led_state == 1) {
                if (control_led(0) == 0) {
                    led_state = 0;
                    log_event("Touch released. LED turned OFF.");
                } else {
                    log_event("Failed to turn LED OFF.");
                }
            }
        } else {
            log_event("Error reading touch sensor.");
        }

        gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
    }

    // Cleanup and exit
    cleanup();
    closelog();
    return 0;
}

// Initialize GPIO using pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0); // Ensure LED is initially off

    return 0;
}

// Read the touch sensor state
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Control the LED state
int control_led(int state) {
    if (gpioWrite(LED_PIN, state) != 0) {
        syslog(LOG_ERR, "Failed to write to LED pin");
        return -1;
    }
    return 0;
}

// Log events to syslog
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    char log_message[256];
    snprintf(log_message, sizeof(log_message), "%s: %s", timestamp, message);
    syslog(LOG_INFO, "%s", log_message);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    log_event("Received signal. Shutting down...");
    running = 0;
}

// Cleanup resources before exiting
void cleanup() {
    log_event("Cleaning up resources...");
    control_led(0); // Turn off LED
    gpioTerminate(); // Terminate pigpio
    log_event("Cleanup complete. Exiting.");
}

