#define LED_PIN 18

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global variables
static volatile int running = 1;
static volatile unsigned long last_touch_time = 0;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
void toggle_led();
void cleanup_gpio();
void signal_handler(int signal);

// Structure to hold GPIO configuration
typedef struct {
    int touch_pin;
    int led_pin;
} gpio_config_t;

// Global configuration
gpio_config_t gpio_config = {TOUCH_SENSOR_PIN, LED_PIN};

// Function to initialize GPIO using pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set touch sensor pin as input
    gpioSetMode(gpio_config.touch_pin, PI_INPUT);

    // Set LED pin as output
    gpioSetMode(gpio_config.led_pin, PI_OUTPUT);

    // Initially turn the LED off
    gpioWrite(gpio_config.led_pin, 0);

    return 0;
}

// Function to read the touch sensor
int read_touch_sensor() {
    return gpioRead(gpio_config.touch_pin);
}

// Function to toggle the LED
void toggle_led() {
    int current_level = gpioRead(gpio_config.led_pin);
    gpioWrite(gpio_config.led_pin, !current_level);
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    gpioWrite(gpio_config.led_pin, 0); // Turn off LED
    gpioTerminate();
    fprintf(stderr, "GPIO cleanup complete\n");
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    running = 0;
    fprintf(stderr, "Received signal %d, shutting down...\n", signal);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    fprintf(stderr, "GPIO initialized successfully\n");

    // Main loop
    while (running) {
        // Read touch sensor
        int touch_detected = read_touch_sensor();

        // Debounce and toggle LED
        if (touch_detected == 1) {
            unsigned long current_time = gpioTick();
            if (current_time - last_touch_time > DEBOUNCE_TIME * 1000) {
                toggle_led();
                last_touch_time = current_time;
            }
        }

        // Small delay to avoid busy-waiting
        gpioDelay(1000); // 1 ms delay
    }

    // Cleanup GPIO before exiting
    cleanup_gpio();

    return 0;
}

