        fprintf(stderr, "Failed to set mode for LED_1_PIN\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LED_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set mode for LED_2_PIN\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to read sensor value
int read_sensor(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Failed to read sensor value from pin %d\n", pin);
        return -1; // Indicate error
    }
    return value;
}

// Function to control LED state
void control_led(int pin, int state) {
    if (gpioWrite(pin, state) != 0) {
        fprintf(stderr, "Failed to write to LED pin %d\n", pin);
    }
}

// Function to log event
void log_event(int sensor_pin, int state) {
    time_t now = time(NULL);
    log_buffer[log_index].sensor_pin = sensor_pin;
    log_buffer[log_index].timestamp = now;
    log_buffer[log_index].state = state;
    log_index = (log_index + 1) % LOG_BUFFER_SIZE;

    if (log_index == 0) {
        log_overflow_count++;
    }
}

// Function to print log buffer
void print_log_buffer() {
    printf("Log Buffer:\n");
    for (int i = 0; i < LOG_BUFFER_SIZE; i++) {
        int index = (log_index + i) % LOG_BUFFER_SIZE;
        printf("  [%d] Sensor: %d, Timestamp: %ld, State: %d\n", i, log_buffer[index].sensor_pin, log_buffer[index].timestamp, log_buffer[index].state);
    }
    printf("Log Overflow Count: %d\n", log_overflow_count);
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);

    // Turn off LEDs
    control_led(LED_1_PIN, 0);
    control_led(LED_2_PIN, 0);

    // Print log buffer
    print_log_buffer();

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Touch sensor control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor values
        int sensor_1_value = read_sensor(SENSOR_1_PIN);
        int sensor_2_value = read_sensor(SENSOR_2_PIN);

        // Check for errors during sensor reading
        if (sensor_1_value == -1 || sensor_2_value == -1) {
            // Handle the error, e.g., by logging it or retrying
            gpioDelay(50); // Small delay to prevent busy-waiting on error
            continue;       // Skip to the next iteration
        }

        // Control LEDs based on sensor values
        control_led(LED_1_PIN, sensor_1_value);
        control_led(LED_2_PIN, sensor_2_value);

        // Log events
        log_event(SENSOR_1_PIN, sensor_1_value);
        log_event(SENSOR_2_PIN, sensor_2_value);

        // Delay for debouncing
        gpioDelay(50);
    }

    return 0;
}

