#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define GPIO pins for the Hall-Effect sensors
#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18

// Debounce time in milliseconds
#define DEBOUNCE_TIME 5

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold sensor states
typedef struct {
    int sensor1_state;
    int sensor2_state;
} sensor_states_t;

// Function prototypes
int initialize_gpio();
void cleanup_gpio();
void log_sensor_data(sensor_states_t states);
void signal_handler(int signal);
void rpm_callback(int gpio, int level, uint32_t tick, void *user_data);

// Global variables for RPM calculation
static volatile uint32_t last_tick = 0;
static volatile double rpm = 0.0;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);

    // Set pull-up resistors (optional, depending on sensor wiring)
    gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP);

    return 0;
}

// Function to cleanup GPIO pins
void cleanup_gpio() {
    gpioTerminate();
}

// Function to log sensor data to a CSV file
void log_sensor_data(sensor_states_t states) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%d,%d\n", timestamp, states.sensor1_state, states.sensor2_state);
        fflush(log_file); // Ensure data is written to file immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Callback function for RPM calculation
void rpm_callback(int gpio, int level, uint32_t tick, void *user_data) {
    static uint32_t last_tick = 0;
    double time_diff;

    if (last_tick != 0) {
        time_diff = (double)(tick - last_tick) / 1000000.0; // Time difference in seconds
        if (time_diff > 0) {
            rpm = 60.0 / time_diff; // RPM calculation (2 pulses per revolution)
        }
    }
    last_tick = tick;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("shaft_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup_gpio();
        return 1;
    }

    // Set up interrupt handlers for both sensors
    if (gpioSetISRFuncEx(SENSOR1_GPIO, EITHER_EDGE, 0, rpm_callback, NULL) < 0) {
        fprintf(stderr, "Error setting ISR for sensor 1\n");
        fclose(log_file);
        cleanup_gpio();
        return 1;
    }
    if (gpioSetISRFuncEx(SENSOR2_GPIO, EITHER_EDGE, 0, rpm_callback, NULL) < 0) {
        fprintf(stderr, "Error setting ISR for sensor 2\n");
        fclose(log_file);
        cleanup_gpio();
        return 1;
    }

    printf("RPM monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read sensor states
        int sensor1_state = gpioRead(SENSOR1_GPIO);
        int sensor2_state = gpioRead(SENSOR2_GPIO);

        // Log sensor data
        sensor_states_t states = {sensor1_state, sensor2_state};
        log_sensor_data(states);

        // Print RPM to console
        printf("RPM: %.2f\n", rpm);

        gpioDelay(100); // Delay for 100ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    cleanup_gpio();

    return 0;
}

