#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Si1182 I2C address
#define SI1182_ADDR 0x28

// Si1182 register addresses
#define PART_ID 0x00
#define CONFIG 0x30
#define HEART_RATE 0x02
#define SPO2 0x04

// Global variables for I2C handle and log file
int i2c_handle = -1;
FILE *log_file = NULL;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Function to read a single byte from an I2C register
int read_register(int handle, uint8_t reg) {
    int value = i2cReadByteData(handle, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, value);
        return -1;
    }
    return value;
}

// Function to write a single byte to an I2C register
int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to initialize the Si1182 sensor
int initialize_sensor(int handle) {
    // Verify sensor presence by reading PART_ID
    int part_id = read_register(handle, PART_ID);
    if (part_id < 0) {
        return -1;
    }
    printf("Si1182 PART_ID: 0x%02X\n", part_id);

    // Configure the sensor for continuous measurement
    if (write_register(handle, CONFIG, 0x01) < 0) {
        return -1;
    }

    return 0;
}

// Function to read heart rate data from the sensor
int read_heart_rate(int handle) {
    int heart_rate = read_register(handle, HEART_RATE);
    if (heart_rate < 0) {
        return -1;
    }
    return heart_rate;
}

// Function to read SpO2 data from the sensor
int read_spo2(int handle) {
    int spo2 = read_register(handle, SPO2);
    if (spo2 < 0) {
        return -1;
    }
    return spo2;
}

// Function to log data to a file
void log_data(int heart_rate, int spo2) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, Heart Rate: %d BPM, SpO2: %d%%\n", timestamp, heart_rate, spo2);
    fflush(log_file);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor(i2c_handle) < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read heart rate and SpO2 data
        int heart_rate = read_heart_rate(i2c_handle);
        int spo2 = read_spo2(i2c_handle);

        // Log the data
        if (heart_rate >= 0 && spo2 >= 0) {
            log_data(heart_rate, spo2);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    // The following lines will never be reached because of the infinite loop.
    // However, they are included for completeness and to avoid compiler warnings.
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

