volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_sensor(int pin);
void activate_alarm();
void deactivate_alarm();
void log_event(const char *event_type, int sensor1_state, int sensor2_state);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor states
typedef struct {
    int sensor1_state;
    int sensor2_state;
    time_t alarm_start_time;
    int alarm_active;
} SensorData;

SensorData sensor_data = {0, 0, 0, 0};

int main() {
    // Register signal handlers for clean shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR_1_PIN);
        int sensor2_value = read_sensor(SENSOR_2_PIN);

        // Update sensor data
        sensor_data.sensor1_state = sensor1_value;
        sensor_data.sensor2_state = sensor2_value;

        // Check for alarm conditions
        if (sensor1_value == 1 || sensor2_value == 1) {
            if (!sensor_data.alarm_active) {
                // Alarm started
                time(&sensor_data.alarm_start_time);
                sensor_data.alarm_active = 1;
                activate_alarm();
                log_event("Tilt-Start", sensor1_value, sensor2_value);
            } else {
                // Check if alarm has been active for more than 2 seconds
                time_t current_time;
                time(&current_time);
                double time_diff = difftime(current_time, sensor_data.alarm_start_time);
                if (time_diff > 2.0) {
                    // Alarm threshold exceeded
                    log_event("Threshold-Exceeded", sensor1_value, sensor2_value);
                }
            }
        } else {
            // Both sensors are LOW
            if (sensor_data.alarm_active) {
                // Alarm deactivated
                deactivate_alarm();
                sensor_data.alarm_active = 0;
                log_event("Tilt-End", sensor1_value, sensor2_value);
            }
        }

        // Delay for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

