    gpioWrite(ALARM_PIN, 1);
}

// Deactivate the alarm
void deactivate_alarm() {
    gpioWrite(ALARM_PIN, 0);
}

// Log an event to the log file
void log_event(const char *event_type, int sensor1_state, int sensor2_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(log_file, "%s - %s - Sensor 1: %d, Sensor 2: %d\n", timestamp, event_type, sensor1_state, sensor2_state);
    fflush(log_file); // Ensure the log is written immediately
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    program_running = 0;
}

