#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO pins for the flame sensors
#define GPIO_2 2
#define GPIO_3 3
#define GPIO_4 4
#define GPIO_17 17
#define GPIO_27 27

// Define the log file path
#define LOG_FILE "/var/log/flame_events.log"

// Define the debounce time in milliseconds
#define DEBOUNCE_TIME_MS 50

// Structure to hold GPIO line information
typedef struct {
    struct gpiod_line *line;
    int pin;
    int sensor_id;
} gpio_line_t;

// Global variables
static volatile sig_atomic_t running = 1;
static struct gpiod_chip *chip = NULL;
static gpio_line_t gpio_lines[5];

// Function prototypes
int init_gpio(void);
int read_sensor(int pin);
int log_event(int sensor_id, int pin);
void signal_handler(int sig);
void cleanup(void);

// Signal handler function
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, exiting...");
    running = 0;
}

// Cleanup function to release resources
void cleanup(void) {
    syslog(LOG_INFO, "Cleaning up resources...");

    // Release GPIO lines
    for (int i = 0; i < 5; i++) {
        if (gpio_lines[i].line) {
            gpiod_line_release(gpio_lines[i].line);
        }
    }

    // Close the GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Close syslog
    closelog();

    syslog(LOG_INFO, "Cleanup complete.");
}

// Initialize GPIO lines
int init_gpio(void) {
    int ret;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %s", strerror(errno));
        return -1;
    }

    // Request GPIO lines for each sensor
    gpio_lines[0].pin = GPIO_2;
    gpio_lines[0].sensor_id = 1;
    gpio_lines[0].line = gpiod_chip_get_line(chip, GPIO_2);
    if (!gpio_lines[0].line) {
        syslog(LOG_ERR, "Failed to get GPIO line %d: %s", GPIO_2, strerror(errno));
        return -1;
    }

    gpio_lines[1].pin = GPIO_3;
    gpio_lines[1].sensor_id = 2;
    gpio_lines[1].line = gpiod_chip_get_line(chip, GPIO_3);
    if (!gpio_lines[1].line) {
        syslog(LOG_ERR, "Failed to get GPIO line %d: %s", GPIO_3, strerror(errno));
        return -1;
    }

    gpio_lines[2].pin = GPIO_4;
    gpio_lines[2].sensor_id = 3;
    gpio_lines[2].line = gpiod_chip_get_line(chip, GPIO_4);
    if (!gpio_lines[2].line) {
        syslog(LOG_ERR, "Failed to get GPIO line %d: %s", GPIO_4, strerror(errno));
        return -1;
    }

    gpio_lines[3].pin = GPIO_17;
    gpio_lines[3].sensor_id = 4;
    gpio_lines[3].line = gpiod_chip_get_line(chip, GPIO_17);
    if (!gpio_lines[3].line) {
        syslog(LOG_ERR, "Failed to get GPIO line %d: %s", GPIO_17, strerror(errno));
        return -1;
    }

    gpio_lines[4].pin = GPIO_27;
    gpio_lines[4].sensor_id = 5;
    gpio_lines[4].line = gpiod_chip_get_line(chip, GPIO_27);
    if (!gpio_lines[4].line) {
        syslog(LOG_ERR, "Failed to get GPIO line %d: %s", GPIO_27, strerror(errno));
        return -1;
    }

    // Request lines for input
    for (int i = 0; i < 5; i++) {
        ret = gpiod_line_request(gpio_lines[i].line, NULL, GPIOD_LINE_REQUEST_DIRECTION_INPUT);
        if (ret < 0) {
            syslog(LOG_ERR, "Failed to request GPIO line %d for input: %s", gpio_lines[i].pin, strerror(errno));
            return -1;
        }
    }

    return 0;
}

// Read sensor value with debouncing
int read_sensor(int pin) {
    int value;
    int ret;

    // Read the initial value
    ret = gpiod_line_get_value(gpio_lines[pin - 2].line);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to read GPIO line %d: %s", pin, strerror(errno));
        return -1;
    }
    value = ret;

    // Debounce: wait for DEBOUNCE_TIME_MS milliseconds
    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = DEBOUNCE_TIME_MS * 1000000; // Convert milliseconds to nanoseconds
    nanosleep(&ts, NULL);

    // Read the value again to confirm the transition
    ret = gpiod_line_get_value(gpio_lines[pin - 2].line);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to read GPIO line %d: %s", pin, strerror(errno));
        return -1;
    }

    if (ret != value) {
        // Transition not confirmed, return the initial value
        return value;
    }

    return ret;
}

// Log event to file
int log_event(int sensor_id, int pin) {
    FILE *fp;
    time_t t;
    struct tm *tm_info;
    char timestamp[20];

    // Get current time in UTC
    time(&t);
    tm_info = gmtime(&t);

    // Format the timestamp in ISO 8601 format
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);

    // Open the log file in append mode
    fp = fopen(LOG_FILE, "a");
    if (!fp) {
        syslog(LOG_ERR, "Failed to open log file %s: %s", LOG_FILE, strerror(errno));
        return -1;
    }

    // Acquire exclusive lock on the file
    if (flock(fileno(fp), LOCK_EX) == -1) {
        syslog(LOG_ERR, "Failed to acquire lock on log file %s: %s", LOG_FILE, strerror(errno));
        fclose(fp);
        return -1;
    }

    // Write the log entry
    fprintf(fp, "%s - Sensor ID: %d (GPIO %d) - Flame Detected\n", timestamp, sensor_id, pin);

    // Release the lock
    if (flock(fileno(fp), LOCK_UN) == -1) {
        syslog(LOG_ERR, "Failed to release lock on log file %s: %s", LOG_FILE, strerror(errno));
    }

    // Flush the buffer to ensure the log is written immediately
    fflush(fp);

    // Close the file
    fclose(fp);

    return 0;
}

int main(void) {
    int i, flame_detected;

    // Open syslog
    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    syslog(LOG_INFO, "Starting flame monitor...");

    // Initialize GPIO
    if (init_gpio() < 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting.");
        closelog();
        return 1;
    }

    // Main loop
    while (running) {
        for (i = 0; i < 5; i++) {
            flame_detected = read_sensor(gpio_lines[i].pin);

            if (flame_detected == 0) {
                // Flame detected
                if (log_event(gpio_lines[i].sensor_id, gpio_lines[i].pin) < 0) {
                    syslog(LOG_ERR, "Failed to log event for sensor %d (GPIO %d)", gpio_lines[i].sensor_id, gpio_lines[i].pin);
                }
            }
        }

        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

