#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

// Define the GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define the GPIO pins for the touch sensor channels
const int gpio_pins[] = {5, 6, 13, 19, 26, 12, 16, 20};
const int num_channels = sizeof(gpio_pins) / sizeof(gpio_pins[0]);

// Global variables for GPIO chip and lines
struct gpiod_chip *chip = NULL;
struct gpiod_line *lines[num_channels];
volatile sig_atomic_t program_running = 1;

// Function to handle SIGINT signal (Ctrl+C)
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    program_running = 0;
    printf("\nCaught signal, exiting gracefully...\n");
}

// Function to get the current timestamp in ISO-8601 format
void get_iso8601_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = gmtime(&rawtime);
    strftime(timestamp, 21, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
}

// Function to read the touch sensor states
int read_touch_sensors(int *states) {
    for (int i = 0; i < num_channels; i++) {
        int value = gpiod_line_get_value(lines[i]);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO line %d: %s\n", gpio_pins[i], strerror(errno));
            return -1; // Indicate an error
        }
        states[i] = value;
    }
    return 0; // Indicate success
}

// Function to log a touch event
void log_touch_event(int channel, int state) {
    char timestamp[21];
    get_iso8601_timestamp(timestamp);
    printf("%s - Channel %d (GPIO %d) %s\n", timestamp, channel, gpio_pins[channel], state ? "Touched" : "Released");
}

int main() {
    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIOCHIP, strerror(errno));
        return 1;
    }

    // Request the GPIO lines for input
    for (int i = 0; i < num_channels; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpio_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error getting GPIO line %d: %s\n", gpio_pins[i], strerror(errno));
            goto cleanup;
        }

        struct gpiod_line_request_config config;
        memset(&config, 0, sizeof(config));
        config.consumer = "touch_sensor";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

        if (gpiod_line_request(lines[i], &config, 0) < 0) {
            fprintf(stderr, "Error requesting GPIO line %d: %s\n", gpio_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    // Initialize previous states
    int previous_states[num_channels];
    for (int i = 0; i < num_channels; i++) {
        previous_states[i] = -1; // Initialize to an invalid state
    }

    // Main loop
    while (program_running) {
        int current_states[num_channels];
        if (read_touch_sensors(current_states) == 0) {
            for (int i = 0; i < num_channels; i++) {
                if (current_states[i] != previous_states[i]) {
                    log_touch_event(i, current_states[i]);
                    previous_states[i] = current_states[i];
                }
            }
        } else {
            fprintf(stderr, "Error reading touch sensors, exiting...\n");
            break;
        }

        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 50000000; // 50 milliseconds
        nanosleep(&sleep_time, NULL);
    }

cleanup:
    // Release GPIO lines
    for (int i = 0; i < num_channels; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 0;
}

