            break;
        }

        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 50000000; // 50 milliseconds
        nanosleep(&sleep_time, NULL);
    }

cleanup:
    // Release GPIO lines
    for (int i = 0; i < num_channels; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 0;
}

