int open_i2c_connection();
int configure_veml7700();
int read_als_data(unsigned int *raw_data);
float convert_to_lux(unsigned int raw_data);
int set_led_brightness(float lux);
int log_data(float lux, int brightness, int error_code);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int veml7700_address;
    int led_gpio;
    int pwm_frequency;
    int pwm_range;
} system_config_t;

int main() {
    system_config_t config = {
        .i2c_bus = I2C_BUS,
        .veml7700_address = VEML7700_ADDR,
        .led_gpio = LED_GPIO,
        .pwm_frequency = PWM_FREQUENCY,
        .pwm_range = PWM_RANGE
    };

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open I2C connection
    if (open_i2c_connection() != 0) {
        fprintf(stderr, "Failed to open I2C connection. Exiting.\n");
        cleanup();
        return 1;
    }

    // Configure VEML7700
    if (configure_veml7700() != 0) {
        fprintf(stderr, "Failed to configure VEML7700. Exiting.\n");
        cleanup();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(config.led_gpio, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(config.led_gpio, config.pwm_frequency);

    // Set PWM range
    gpioSetPWMrange(config.led_gpio, config.pwm_range);

