        return 1;
    }
    return 0;
}

// Open I2C connection
int open_i2c_connection() {
    i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Configure VEML7700
int configure_veml7700() {
    // ALS gain 1/8 (0x00) and ALS integration time 100 ms (0x00)
    unsigned char config_data[2] = {0x00, 0x00};
    int result = i2cWriteDevice(i2c_handle, config_data, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write to config register: %d\n", result);
        return 1;
    }
    return 0;
}

// Read ALS data
int read_als_data(unsigned int *raw_data) {
    char buffer[2];
    int result = i2cReadDevice(i2c_handle, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read ALS data: %d\n", result);
        return 1;
    }

    // Combine the two bytes into a 16-bit value (little-endian)
    *raw_data = (buffer[1] << 8) | buffer[0];
    return 0;
}

// Convert to lux
float convert_to_lux(unsigned int raw_data) {
    return raw_data * 0.0576;
}

// Set LED brightness
int set_led_brightness(float lux) {
    int brightness;
    if (lux < 100) {
        brightness = 100;
    } else if (lux < 500) {
        brightness = 75;
    } else if (lux < 1000) {
        brightness = 50;
    } else {
        brightness = 25;
    }

    gpioPWM(LED_GPIO, brightness);
    return brightness;
}

// Log data
int log_data(float lux, int brightness, int error_code) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, Lux: %.2f, Brightness: %d, Error: %d\n", timestamp, lux, brightness, error_code);
    fflush(log_file);
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioPWM(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
}

