#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <errno.h>

// Define GPIO pins
#define LED_PIN 17
#define TOUCH_PIN_1 2
#define TOUCH_PIN_2 3
#define TOUCH_PIN_3 4
#define TOUCH_PIN_4 5
#define TOUCH_PIN_5 6
#define TOUCH_PIN_6 7
#define TOUCH_PIN_7 8
#define TOUCH_PIN_8 9

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_touch_sensors(int *channel_states);
int debounce_channel(int gpio_pin, int current_state);
int log_touch_event(int channel);
int control_led(int state);
void signal_handler(int signal);
int setup_logging();
void cleanup();

// Structure to hold the previous state of each channel
struct ChannelState {
    int last_state;
};

struct ChannelState channel_states[8];

int main() {
    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Error initializing GPIO. Exiting.\n");
        return 1;
    }

    // Setup signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Setup logging
    if (setup_logging() != 0) {
        fprintf(stderr, "Error setting up logging. Exiting.\n");
        cleanup();
        return 1;
    }

    int channel_states_array[8] = {0}; // Initialize all channels to untouched

    // Main loop
    while (program_running) {
        if (read_touch_sensors(channel_states_array) != 0) {
            fprintf(stderr, "Error reading touch sensors.\n");
        }

        // Check if any channel has changed state
        int led_state = 0; // Assume all channels are untouched initially
        for (int i = 0; i < 8; i++) {
            if (debounce_channel(i + 2, channel_states_array[i]) != 0) {
                fprintf(stderr, "Error debouncing channel %d.\n", i + 2);
            }
            if (channel_states_array[i] != channel_states[i].last_state) {
                if (log_touch_event(i + 1) != 0) {
                    fprintf(stderr, "Error logging touch event for channel %d.\n", i + 1);
                }
                channel_states[i].last_state = channel_states_array[i];
                led_state = 1; // At least one channel is touched
            }
        }

        // Control the LED based on touch sensor states
        if (control_led(led_state) != 0) {
            fprintf(stderr, "Error controlling LED.\n");
        }

        gpioDelay(50); // Poll every 50ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Set touch sensor pins as inputs with pull-down resistors
    int pins[] = {TOUCH_PIN_1, TOUCH_PIN_2, TOUCH_PIN_3, TOUCH_PIN_4, TOUCH_PIN_5, TOUCH_PIN_6, TOUCH_PIN_7, TOUCH_PIN_8};
    for (int i = 0; i < 8; i++) {
        gpioSetMode(pins[i], PI_INPUT);
        gpioSetPullUpDown(pins[i], PI_PUD_DOWN);
        channel_states[i].last_state = 0; // Initialize last state to untouched
    }

    return 0;
}

// Read touch sensor values
int read_touch_sensors(int *channel_states) {
    int pins[] = {TOUCH_PIN_1, TOUCH_PIN_2, TOUCH_PIN_3, TOUCH_PIN_4, TOUCH_PIN_5, TOUCH_PIN_6, TOUCH_PIN_7, TOUCH_PIN_8};
    for (int i = 0; i < 8; i++) {
        channel_states[i] = gpioRead(pins[i]);
    }
    return 0;
}

// Debounce a single channel
int debounce_channel(int gpio_pin, int current_state) {
    static int last_debounce_time[8] = {0}; // Array to store last debounce time for each channel
    static int last_state[8] = {0}; // Array to store last state for each channel
    int index = gpio_pin - 2; // Calculate index for the arrays

    int reading = gpioRead(gpio_pin);

    if (reading != last_state[index]) {
        last_debounce_time[index] = gpioTick();
    }

    if ((gpioTick() - last_debounce_time[index]) > DEBOUNCE_DELAY) {
        if (reading != channel_states[index]) {
            channel_states[index] = reading;
        }
    }

    last_state[index] = reading;
    return 0;
}

// Log a touch event to file
int log_touch_event(int channel) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Channel %d Touched\n", timestamp, channel);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return 1;
    }
}

// Control the LED
int control_led(int state) {
    gpioWrite(LED_PIN, state);
    return 0;
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Setup logging
int setup_logging() {
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources.\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate(); // Release pigpio resources
}

