#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define CONFIG_WORD 0xC810 // Continuous conversion, auto range, 100ms
#define LUX_SCALE 0.01
#define LOG_FILE "light_data.txt"

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int configure_sensor();
int read_sensor_data(uint16_t *raw_data);
double calculate_lux(uint16_t raw_data);
int log_data(double lux_value);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure the OPT3001 sensor
int configure_sensor() {
    uint16_t config_word = CONFIG_WORD;
    // Byte swap the config word
    uint8_t config_bytes[2];
    config_bytes[0] = (config_word >> 8) & 0xFF;
    config_bytes[1] = config_word & 0xFF;

    int result = i2cWriteI2CBlockData(i2c_handle, CONFIG_REG, (char *)config_bytes, 2);
    if (result < 0) {
        fprintf(stderr, "Error writing to configuration register: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(uint16_t *raw_data) {
    char buffer[2];
    int result = i2cReadI2CBlockData(i2c_handle, RESULT_REG, buffer, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading from result register: %d\n", result);
        return -1;
    }

    // Byte swap the result
    *raw_data = ((uint16_t)buffer[0] << 8) | (uint16_t)buffer[1];
    return 0;
}

// Calculate lux value
double calculate_lux(uint16_t raw_data) {
    int exponent = (raw_data >> 12) & 0x0F;
    int mantissa = raw_data & 0x0FFF;
    return mantissa * LUX_SCALE * (1 << exponent);
}

