void log_event(int flame_detected) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Flame detected: %s\n", timestamp, flame_detected ? "YES" : "NO");
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to trigger the alert (LED blink)
void trigger_alert() {
    gpioWrite(ALERT_LED_PIN, 1); // Set LED HIGH
    gpioDelay(1000);             // Wait for 1 second
    gpioWrite(ALERT_LED_PIN, 0); // Set LED LOW
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0; // Stop the main loop

    // Close the log file if it's open
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    // Reset GPIO pins
    gpioWrite(FLAME_SENSOR_PIN, 0); // Set to LOW
    gpioWrite(ALERT_LED_PIN, 0);    // Set to LOW
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT); // Set to input
    gpioSetMode(ALERT_LED_PIN, PI_OUTPUT);   // Set to output

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(ALERT_LED_PIN, PI_OUTPUT);

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int flame_detected = read_flame_sensor();
        if (flame_detected == 0) {
            log_event(1);
            trigger_alert();
        } else if (flame_detected == 1) {
            log_event(0);
        } else {
            fprintf(stderr, "Error reading sensor, skipping logging.\n");
        }

        gpioDelay(500); // Wait 500 milliseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    fclose(log_file);
    gpioTerminate();

    return 0;
}

