#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 4
#define DEBOUNCE_MS 50

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function to get the current timestamp in the specified format
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; //YYYY-MM-DD HH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log a touch event to the file
int log_touch_event(const char *event_type) {
    char *timestamp = get_timestamp();
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s: %s\n", timestamp, event_type);
    fflush(log_file); // Ensure the data is written to the file immediately

    return 0;
}

// Function to read the touch sensor state with debouncing
int read_touch_sensor() {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO value: %s\n", strerror(-value));
        return -1;
    }

    // Debounce: Wait for the signal to stabilize
    struct timespec delay = {0, DEBOUNCE_MS * 1000000L}; // 50ms
    nanosleep(&delay, NULL);

    return value;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting gracefully.\n");
    terminate = 1;
}

int main() {
    int last_state = 0; // 0 = released, 1 = pressed

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line as input with pull-down resistor
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "touch_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Open log file
    log_file = fopen("touch_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    fprintf(stderr, "Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int current_state = read_touch_sensor();
        if (current_state < 0) {
            break; // Exit loop on error
        }

        if (current_state != last_state) {
            if (current_state == 1) {
                if (log_touch_event("Touch Detected") != 0) {
                    fprintf(stderr, "Error logging touch event.\n");
                }
            } else {
                if (log_touch_event("Touch Released") != 0) {
                    fprintf(stderr, "Error logging touch event.\n");
                }
            }
            last_state = current_state;
        }
        usleep(10000); // Check every 10ms
    }

    // Cleanup
    fprintf(stderr, "Cleaning up resources.\n");
    if (log_file) {
        fclose(log_file);
    }
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    fprintf(stderr, "Exiting.\n");
    return 0;
}

