#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SLF3S_ADDR 0x08
#define MEASURE_CMD 0x3608
#define FLOW_SCALE_FACTOR 90.0
#define FLOW_MIN 0.0
#define FLOW_MAX 100.0
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int start_measurement();
int read_sensor_data(int16_t *raw_flow, uint8_t *crc);
uint8_t calculate_crc(const uint8_t *data, int len);
int validate_crc(const uint8_t *data, int len);
float convert_flow(int16_t raw_flow);
char *get_status(float flow_rate);
int log_data(float flow_rate, int flags, char *status);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int16_t raw_flow;
    uint8_t crc;
    float flow_rate;
    int flags;
    char status[10];
} sensor_data_t;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("cooling_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Flow Rate (ml/min),Status\n");
    }
    rewind(log_file);

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    int16_t raw_flow;
    uint8_t crc;
    sensor_data_t sensor_data;

    while (!terminate) {
        // Start measurement
        if (start_measurement() != 0) {
            fprintf(stderr, "Failed to start measurement\n");
            log_data(-1.0, -1, "ERROR");
            continue; // Retry
        }

        // Read sensor data
        if (read_sensor_data(&raw_flow, &crc) != 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            log_data(-1.0, -1, "ERROR");
            continue; // Retry
        }

        // Validate CRC
        if (validate_crc((uint8_t*)&raw_flow, 2) != 0) {
            fprintf(stderr, "CRC validation failed\n");
            log_data(-1.0, -1, "ERROR");
            continue; // Retry
        }

        // Convert flow rate
        sensor_data.flow_rate = convert_flow(raw_flow);

        // Get status
        strcpy(sensor_data.status, get_status(sensor_data.flow_rate));

        // Log data
        log_data(sensor_data.flow_rate, 0, sensor_data.status);

        // Sleep for 1 second
        sleep(1);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Start continuous measurement
int start_measurement() {
    char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write measurement command: %d\n", result);
        return 1;
    }
    gpioDelay(2); // Wait at least 2 ms
    return 0;
}

// Read sensor data
int read_sensor_data(int16_t *raw_flow, uint8_t *crc) {
    char buffer[3];
    int result = i2cReadDevice(i2c_handle, buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        return 1;
    }

    *raw_flow = (buffer[0] << 8) | buffer[1];
    *crc = buffer[2];

    return 0;
}

// Calculate CRC-8
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = CRC_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC
int validate_crc(const uint8_t *data, int len) {
    uint8_t calculated_crc = calculate_crc(data, len);
    return (calculated_crc != data[len]);
}

// Convert flow rate
float convert_flow(int16_t raw_flow) {
    return (float)raw_flow / FLOW_SCALE_FACTOR;
}

// Get status
char *get_status(float flow_rate) {
    static char status[10];
    if (flow_rate < FLOW_MIN) {
        strcpy(status, "INVALID");
    } else if (flow_rate > FLOW_MAX) {
        strcpy(status, "INVALID");
    } else {
        strcpy(status, "OK");
    }
    return status;
}

// Log data
int log_data(float flow_rate, int flags, char *status) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%s\n", timestamp, flow_rate, status);
    fflush(log_file);
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

