#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <stdbool.h>
#include <gpiod.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR_PIN 17
#define MIDDLE_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN 22

// Define the GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Define the log file name
#define LOG_FILE "path_log.csv"

// Structure to hold GPIO line information
struct gpio_line {
    struct gpiod_line *line;
    int pin;
};

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpio_line left_line, middle_line, right_line;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int setup_gpio(void);
int read_sensor(struct gpio_line *line);
char *get_iso8601_timestamp(char *timestamp_buffer, size_t buffer_size);
int log_data(FILE *fp, int left, int middle, int right, const char *timestamp);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        terminate = 1;
    }
}

// Function to set up the GPIO lines
int setup_gpio(void) {
    int ret;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    // Get the GPIO lines for each sensor
    left_line.line = gpiod_chip_get_line(chip, LEFT_SENSOR_PIN);
    if (!left_line.line) {
        fprintf(stderr, "Error getting left sensor line: %s\n", strerror(errno));
        goto cleanup_chip;
    }
    left_line.pin = LEFT_SENSOR_PIN;

    middle_line.line = gpiod_chip_get_line(chip, MIDDLE_SENSOR_PIN);
    if (!middle_line.line) {
        fprintf(stderr, "Error getting middle sensor line: %s\n", strerror(errno));
        goto cleanup_left_line;
    }
    middle_line.pin = MIDDLE_SENSOR_PIN;

    right_line.line = gpiod_chip_get_line(chip, RIGHT_SENSOR_PIN);
    if (!right_line.line) {
        fprintf(stderr, "Error getting right sensor line: %s\n", strerror(errno));
        goto cleanup_middle_line;
    }
    right_line.pin = RIGHT_SENSOR_PIN;

    // Request the GPIO lines as inputs
    ret = gpiod_line_request_input(left_line.line, "obstacle_avoidance");
    if (ret < 0) {
        fprintf(stderr, "Error requesting left sensor line as input: %s\n", strerror(errno));
        goto cleanup_right_line;
    }

    ret = gpiod_line_request_input(middle_line.line, "obstacle_avoidance");
    if (ret < 0) {
        fprintf(stderr, "Error requesting middle sensor line as input: %s\n", strerror(errno));
        goto cleanup_left_line_request;
    }

    ret = gpiod_line_request_input(right_line.line, "obstacle_avoidance");
    if (ret < 0) {
        fprintf(stderr, "Error requesting right sensor line as input: %s\n", strerror(errno));
        goto cleanup_middle_line_request;
    }

    return 0;

cleanup_middle_line_request:
    gpiod_line_release(middle_line.line);
cleanup_left_line_request:
    gpiod_line_release(left_line.line);
cleanup_right_line:
    gpiod_line_release(right_line.line);
cleanup_middle_line:
    gpiod_line_release(middle_line.line);
cleanup_left_line:
    gpiod_line_release(left_line.line);
cleanup_chip:
    gpiod_chip_close(chip);
    return -1;
}

// Function to read the sensor value
int read_sensor(struct gpio_line *line) {
    int value = gpiod_line_get_value(line->line);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor value from pin %d: %s\n", line->pin, strerror(errno));
        return -1;
    }
    return value;
}

// Function to get the current timestamp in ISO-8601 format
char *get_iso8601_timestamp(char *timestamp_buffer, size_t buffer_size) {
    time_t timer;
    struct tm* tm_info;

    time(&timer);
    tm_info = localtime(&timer);

    strftime(timestamp_buffer, buffer_size, "%Y-%m-%dT%H:%M:%SZ", tm_info);
    return timestamp_buffer;
}

// Function to log the data to the CSV file
int log_data(FILE *fp, int left, int middle, int right, const char *timestamp) {
    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, left, middle, right) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to clean up the GPIO lines
void cleanup_gpio(void) {
    if (left_line.line) {
        gpiod_line_release(left_line.line);
    }
    if (middle_line.line) {
        gpiod_line_release(middle_line.line);
    }
    if (right_line.line) {
        gpiod_line_release(right_line.line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
    }
}

int main(void) {
    int left_value, middle_value, right_value;
    char timestamp_buffer[32];

    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Set up the GPIO lines
    if (setup_gpio() < 0) {
        fprintf(stderr, "GPIO setup failed, exiting.\n");
        return EXIT_FAILURE;
    }

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        // Read sensor values
        left_value = read_sensor(&left_line);
        middle_value = read_sensor(&middle_line);
        right_value = read_sensor(&right_line);

        if (left_value < 0 || middle_value < 0 || right_value < 0) {
            fprintf(stderr, "Error reading sensor values, exiting.\n");
            break;
        }

        // Get the current timestamp
        get_iso8601_timestamp(timestamp_buffer, sizeof(timestamp_buffer));

        // Log the data
        if (log_data(log_file, left_value, middle_value, right_value, timestamp_buffer) < 0) {
            fprintf(stderr, "Error logging data, exiting.\n");
            break;
        }

        // Flush the log file to ensure data is written
        fflush(log_file);

        // Wait for 50 ms
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 50000000; // 50 ms
        nanosleep(&sleep_time, NULL);
    }

    // Clean up and exit
    cleanup_gpio();
    return EXIT_SUCCESS;
}

