#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 23
#define LED_PIN 24

// Define GPIO chip
#define GPIO_CHIP "gpiochip4"

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *touch_line = NULL;
static struct gpiod_line *led_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio(void);
int read_touch_sensor(void);
int toggle_led(void);
int log_event(int led_state);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Initialize GPIO lines
int initialize_gpio(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    // Get touch sensor line
    touch_line = gpiod_chip_get_line(chip, TOUCH_SENSOR_PIN);
    if (!touch_line) {
        fprintf(stderr, "Error getting touch sensor line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    // Get LED line
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Error getting LED line: %s\n", strerror(errno));
        gpiod_line_release(touch_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request touch sensor line as input
    ret = gpiod_line_request(touch_line, NULL, GPIOD_LINE_REQUEST_DIRECTION_INPUT);
    if (ret < 0) {
        fprintf(stderr, "Error requesting touch sensor line as input: %s\n", strerror(errno));
        gpiod_line_release(led_line);
        gpiod_line_release(touch_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request LED line as output
    ret = gpiod_line_request(led_line, NULL, GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
    if (ret < 0) {
        fprintf(stderr, "Error requesting LED line as output: %s\n", strerror(errno));
        gpiod_line_release(touch_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Read touch sensor state
int read_touch_sensor(void) {
    int value = gpiod_line_get_value(touch_line);
    if (value < 0) {
        fprintf(stderr, "Error reading touch sensor value: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

// Toggle LED state
int toggle_led(void) {
    int current_value = gpiod_line_get_value(led_line);
    if (current_value < 0) {
        fprintf(stderr, "Error reading current LED value: %s\n", strerror(errno));
        return -1;
    }

    int new_value = !current_value;
    int ret = gpiod_line_set_value(led_line, new_value);
    if (ret < 0) {
        fprintf(stderr, "Error setting LED value: %s\n", strerror(errno));
        return -1;
    }
    return new_value;
}

// Log event to file
int log_event(int led_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file == NULL) {
        log_file = fopen("touch_log.txt", "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
            return -1;
        }
    }

    fprintf(log_file, "%s, LED: %s\n", timestamp, led_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Cleanup GPIO resources
void cleanup_gpio(void) {
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (touch_line) {
        gpiod_line_release(touch_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main(void) {
    int touch_detected;
    int led_state = 0; // 0 = off, 1 = on

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        touch_detected = read_touch_sensor();
        if (touch_detected < 0) {
            fprintf(stderr, "Error reading touch sensor. Continuing...\n");
            sleep(1); // Avoid spamming errors
            continue;
        }

        if (touch_detected) {
            led_state = toggle_led();
            if (led_state < 0) {
                fprintf(stderr, "Error toggling LED. Continuing...\n");
            } else {
                if (log_event(led_state) < 0) {
                    fprintf(stderr, "Error logging event. Continuing...\n");
                }
            }
            sleep(1); // Debounce
        }
        sleep(1); // Poll every 1 second
    }

    // Cleanup and exit
    printf("Cleaning up and exiting...\n");
    cleanup_gpio();
    return EXIT_SUCCESS;
}

