#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define LED_PIN 17

// Debounce time in milliseconds
#define DEBOUNCE_TIME 200

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
int toggle_led();
int log_touch_event();
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    return 0;
}

// Function to read the touch sensor
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to toggle the LED
int toggle_led() {
    int current_state = gpioRead(LED_PIN);
    gpioWrite(LED_PIN, !current_state);
    return 0;
}

// Function to log the touch event with timestamp
int log_touch_event() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        if (fprintf(log_file, "%s\n", timestamp) < 0) {
            fprintf(stderr, "Error writing to log file\n");
            return -1;
        }
        fflush(log_file); // Ensure data is written to disk
    } else {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Received signal %d, shutting down...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(LED_PIN, 0); // Turn off LED
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    int last_state = 0; // Initialize last state
    int current_state;
    unsigned int last_change_time = 0; // Initialize last change time

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        current_state = read_touch_sensor();

        if (current_state == 1 && last_state == 0) {
            // Rising edge detected
            unsigned int current_time = gpioTick();
            if (current_time - last_change_time > DEBOUNCE_TIME * 1000) { // Debounce
                toggle_led();
                if (log_touch_event() != 0) {
                    fprintf(stderr, "Error logging touch event\n");
                }
                last_change_time = current_time;
            }
        }

        last_state = current_state;
        gpioDelay(10); // Poll every 10 ms
    }

    cleanup();
    return 0;
}

