#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define GPIO pins for the sensors
#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define SENSOR3_GPIO 27

// Define the log file name
#define LOG_FILE "magnet_log.txt"

// Structure to hold sensor data
typedef struct {
    int gpio;
    int state;
    char *id;
} sensor_t;

// Global variables
FILE *log_file = NULL;
sensor_t sensors[3];

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio);
int log_state_change(int gpio, int state);
void signal_handler(int signal);
void cleanup();

// Function to initialize the pigpio library and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO modes to input with pull-up resistors
    if (gpioSetMode(SENSOR1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", SENSOR1_GPIO);
        return -1;
    }
    if (gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up for GPIO %d\n", SENSOR1_GPIO);
        return -1;
    }

    if (gpioSetMode(SENSOR2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", SENSOR2_GPIO);
        return -1;
    }
    if (gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up for GPIO %d\n", SENSOR2_GPIO);
        return -1;
    }

    if (gpioSetMode(SENSOR3_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", SENSOR3_GPIO);
        return -1;
    }
    if (gpioSetPullUpDown(SENSOR3_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up for GPIO %d\n", SENSOR3_GPIO);
        return -1;
    }

    return 0;
}

// Function to read the state of a sensor
int read_sensor(int gpio) {
    int state = gpioRead(gpio);
    if (state < 0) {
        fprintf(stderr, "Failed to read GPIO %d: %s\n", gpio, strerror(errno));
        return -1;
    }
    return state;
}

// Function to log a state change to the log file
int log_state_change(int gpio, int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - GPIO %d: %s\n", timestamp, gpio, (state == 0) ? "Magnet Present" : "Magnet Removed");
        fflush(log_file); // Ensure the log is written immediately
        return 0;
    } else {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Cleanup function to close the log file and terminate pigpio
void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize sensors
    sensors[0].gpio = SENSOR1_GPIO;
    sensors[0].state = read_sensor(SENSOR1_GPIO);
    sensors[0].id = "Sensor 1";

    sensors[1].gpio = SENSOR2_GPIO;
    sensors[1].state = read_sensor(SENSOR2_GPIO);
    sensors[1].id = "Sensor 2";

    sensors[2].gpio = SENSOR3_GPIO;
    sensors[2].state = read_sensor(SENSOR3_GPIO);
    sensors[2].id = "Sensor 3";

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (1) {
        for (int i = 0; i < 3; i++) {
            int new_state = read_sensor(sensors[i].gpio);
            if (new_state >= 0 && new_state != sensors[i].state) {
                log_state_change(sensors[i].gpio, new_state);
                sensors[i].state = new_state;
            }
        }
        gpioDelay(100); // Delay for 100 ms
    }

    return 0;
}

