#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x4A
#define PART_ID_REG 0x00
#define HW_REV_REG 0x01
#define LED_CURRENT_REG 0x3F
#define AVERAGING_REG 0x04
#define ENABLE_REG 0x01
#define HEART_RATE_REG 0x2A
#define MOVING_AVG_SIZE 5

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_sensor();
int read_sensor_data(uint16_t *heart_rate);
float calculate_bpm(uint16_t raw_value);
float apply_moving_average(float new_value, float *moving_average, int *index, int size);
int validate_bpm(float bpm);
int log_data(float bpm);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the Si1182 sensor
int initialize_sensor() {
    int status;

    // Verify PART_ID and HW_REV
    int part_id = i2cReadByteData(i2c_handle, PART_ID_REG);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART_ID: %d\n", part_id);
        return -1;
    }
    if (part_id != 0x02) {
        fprintf(stderr, "Error: Incorrect PART_ID (0x%02X)\n", part_id);
        return -1;
    }

    int hw_rev = i2cReadByteData(i2c_handle, HW_REV_REG);
    if (hw_rev < 0) {
        fprintf(stderr, "Error reading HW_REV: %d\n", hw_rev);
        return -1;
    }
    if (hw_rev != 0x01) {
        fprintf(stderr, "Error: Incorrect HW_REV (0x%02X)\n", hw_rev);
        return -1;
    }

    // Configure sensor registers
    status = i2cWriteByteData(i2c_handle, LED_CURRENT_REG, 0x7F); // Max LED current
    if (status < 0) {
        fprintf(stderr, "Error writing LED_CURRENT_REG: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, AVERAGING_REG, 0x03); // Averaging
    if (status < 0) {
        fprintf(stderr, "Error writing AVERAGING_REG: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, ENABLE_REG, 0x01); // Enable sensor
    if (status < 0) {
        fprintf(stderr, "Error writing ENABLE_REG: %d\n", status);
        return -1;
    }

    return 0;
}

// Function to read heart-rate data from the sensor
int read_sensor_data(uint16_t *heart_rate) {
    int status;
    status = i2cReadWordData(i2c_handle, HEART_RATE_REG);
    if (status < 0) {
        fprintf(stderr, "Error reading HEART_RATE_REG: %d\n", status);
        return -1;
    }
    *heart_rate = (uint16_t)status;
    return 0;
}

// Function to calculate BPM from raw heart-rate data
float calculate_bpm(uint16_t raw_value) {
    return (float)raw_value * 0.5;
}

// Function to apply a moving average filter
float apply_moving_average(float new_value, float *moving_average, int *index, int size) {
    float sum = 0.0;
    moving_average[*index] = new_value;
    *index = (*index + 1) % size;

    for (int i = 0; i < size; i++) {
        sum += moving_average[i];
    }

    return sum / size;
}

// Function to validate the BPM value
int validate_bpm(float bpm) {
    return (bpm >= 30.0 && bpm <= 220.0);
}

// Function to log the BPM data to a file
int log_data(float bpm) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f\n", timestamp, bpm);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("heart_rate.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Moving average filter
    float moving_average[MOVING_AVG_SIZE] = {0.0};
    int moving_average_index = 0;
    uint16_t raw_heart_rate;
    float bpm, filtered_bpm;

    // Main loop
    while (program_running) {
        // Read sensor data
        if (read_sensor_data(&raw_heart_rate) == 0) {
            // Calculate BPM
            bpm = calculate_bpm(raw_heart_rate);

            // Apply moving average filter
            filtered_bpm = apply_moving_average(bpm, moving_average, &moving_average_index, MOVING_AVG_SIZE);

            // Validate BPM
            if (validate_bpm(filtered_bpm)) {
                // Log data
                log_data(filtered_bpm);
                printf("BPM: %.2f\n", filtered_bpm);
            } else {
                fprintf(stderr, "Invalid BPM value: %.2f\n", filtered_bpm);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        // Wait for 1 second
        time_sleep(1.0);
    }

    // Close I2C bus and log file
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

