#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

// Configuration
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define LOG_FILE "flame_log.txt"
#define POLL_INTERVAL_MS 100

// Global variables (to be cleaned up in signal handler)
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;

// Function prototypes
int setup_gpio(void);
int read_sensor(void);
int log_event(void);
void cleanup_gpio(void);
void signal_handler(int sig);

// Structure to hold GPIO configuration
typedef struct {
    const char *chip_name;
    int pin;
    const char *log_file_name;
    int poll_interval_ms;
} gpio_config_t;

// Setup GPIO line as input with pull-up resistor
int setup_gpio(void) {
    int ret;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "flame_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return -1;
    }

    return 0;
}

// Read the sensor value
int read_sensor(void) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        return -1;
    }
    return value;
}

// Log the event to file
int log_event(void) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s FLAME DETECTED\n", timestamp);
    fflush(log_file); // Ensure immediate write to disk

    return 0;
}

// Cleanup GPIO resources
void cleanup_gpio(void) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);
    cleanup_gpio();
    exit(0);
}

int main(void) {
    int prev_value = 1; // Initialize to HIGH (no flame)
    int current_value;
    int ret;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return 1;
    }

    // Setup GPIO
    if (setup_gpio() != 0) {
        fclose(log_file);
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        current_value = read_sensor();
        if (current_value < 0) {
            fprintf(stderr, "Error reading sensor, exiting...\n");
            break;
        }

        // Detect falling edge (HIGH to LOW)
        if (prev_value == 1 && current_value == 0) {
            printf("FLAME DETECTED\n");
            if (log_event() != 0) {
                fprintf(stderr, "Error logging event, exiting...\n");
                break;
            }
        }

        prev_value = current_value;
        usleep(POLL_INTERVAL_MS * 1000); // Sleep for 100ms
    }

    // Cleanup and exit
    cleanup_gpio();
    return 0;
}

