#define OUTPUT_GPIO_START 17
#define OUTPUT_GPIO_END 24

// Define number of channels
#define NUM_CHANNELS 8

// Global variables
struct gpiod_chip *chip;
struct gpiod_line *sensor_lines[NUM_CHANNELS];
struct gpiod_line *output_lines[NUM_CHANNELS];
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_sensor_channel(struct gpiod_line *line);
int set_output_channel(struct gpiod_line *line, int value);
int update_binary_counter(int current_counter);
int log_touch_event(int channel, int counter);
void signal_handler(int signal);
int setup_gpio();
void cleanup_gpio();

// Function to read the state of a sensor channel
int read_sensor_channel(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor channel: %s\n", strerror(errno));
        return -1; // Indicate error
    }
    return value;
}

// Function to set the state of an output channel
int set_output_channel(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting output channel: %s\n", strerror(errno));
        return -1; // Indicate error
    }
    return 0;
}

// Function to update the binary counter
int update_binary_counter(int current_counter) {
    return (current_counter + 1) % 256;
}

// Function to log a touch event
int log_touch_event(int channel, int counter) {
    FILE *fp = fopen("touch_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Warning: Could not open touch_log.txt for appending: %s\n", strerror(errno));
        return -1; // Indicate warning
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(fp, "%s, Channel: %d, Counter: %d\n", timestamp, channel, counter);
    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Function to setup GPIO lines
int setup_gpio() {
    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    // Request sensor lines for input
    for (int i = 0; i < NUM_CHANNELS; i++) {
        sensor_lines[i] = gpiod_chip_get_line(chip, SENSOR_GPIO_START + i);
        if (!sensor_lines[i]) {
            fprintf(stderr, "Error getting sensor line %d: %s\n", SENSOR_GPIO_START + i, strerror(errno));
            goto cleanup;
        }

        struct gpiod_line_request_config config;
        memset(&config, 0, sizeof(config));
        config.consumer = "touch_counter";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

        int ret = gpiod_line_request(sensor_lines[i], &config, 0);
        if (ret < 0) {
            fprintf(stderr, "Error requesting sensor line %d: %s\n", SENSOR_GPIO_START + i, strerror(errno));
            goto cleanup;
        }
    }

    // Request output lines for output
    for (int i = 0; i < NUM_CHANNELS; i++) {
        output_lines[i] = gpiod_chip_get_line(chip, OUTPUT_GPIO_START + i);
        if (!output_lines[i]) {
            fprintf(stderr, "Error getting output line %d: %s\n", OUTPUT_GPIO_START + i, strerror(errno));
            goto cleanup;
        }

        struct gpiod_line_request_config config;
        memset(&config, 0, sizeof(config));
        config.consumer = "touch_counter";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

        int ret = gpiod_line_request(output_lines[i], &config, 0);
        if (ret < 0) {
            fprintf(stderr, "Error requesting output line %d: %s\n", OUTPUT_GPIO_START + i, strerror(errno));
            goto cleanup;
        }
    }

    return 0;

cleanup:
    cleanup_gpio();
    return -1;
}

// Function to cleanup GPIO lines
void cleanup_gpio() {
    // Release sensor lines
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (sensor_lines[i]) {
            gpiod_line_release(sensor_lines[i]);
            sensor_lines[i] = NULL;
        }
    }

    // Release output lines
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (output_lines[i]) {
            gpiod_line_release(output_lines[i]);
            output_lines[i] = NULL;
        }
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Setup GPIO
    if (setup_gpio() != 0) {
        fprintf(stderr, "GPIO setup failed, exiting.\n");
        return 1;
    }

    // Stabilization delay
    struct timespec delay = {0, 200000000}; // 200 ms
    nanosleep(&delay, NULL);

    int current_counter = 0;
    int previous_states[NUM_CHANNELS] = {0}; // Initialize previous states

    // Main loop
    while (program_running) {
        int new_counter = current_counter;
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int sensor_value = read_sensor_channel(sensor_lines[i]);
            if (sensor_value < 0) {
                fprintf(stderr, "Error reading sensor channel %d, skipping.\n", SENSOR_GPIO_START + i);
                continue; // Skip to the next channel
            }

            if (sensor_value == 1 && previous_states[i] == 0) {
                // Rising edge detected
                new_counter = update_binary_counter(new_counter);
                log_touch_event(i + 1, new_counter);
                printf("Touch on channel %d | Counter: %d\n", i + 1, new_counter);
                previous_states[i] = 1; // Update previous state
            } else if (sensor_value == 0) {
                // Falling edge detected, update previous state
                previous_states[i] = 0;
            }
        }

        // Update output lines
        for (int i = 0; i < NUM_CHANNELS; i++) {
            if (set_output_channel(output_lines[i], (new_counter >> i) & 1) != 0) {
                fprintf(stderr, "Error setting output channel %d, continuing.\n", OUTPUT_GPIO_START + i);
            }
        }

        current_counter = new_counter;

        // Delay
        struct timespec delay = {0, 10000000}; // 10 ms
        nanosleep(&delay, NULL);
    }

    // Cleanup GPIO before exiting
    cleanup_gpio();

    return 0;
}

