#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO chip and line numbers
#define GPIOCHIP "gpiochip0"
#define GPIO_17 17
#define GPIO_18 18
#define GPIO_27 27
#define GPIO_22 22

// Define CSV file name
#define CSV_FILE "tracking_log.csv"

// Structure to hold GPIO lines
struct gpiod_line *lines[4];

// File pointer for the CSV file
FILE *csv_file = NULL;

// Function prototypes
int read_sensor(int gpio_pin);
int log_data(FILE *fp, int sensor1, int sensor2, int sensor3, int sensor4);
void signal_handler(int signum);
int setup_gpio(int gpio_pin, struct gpiod_line **line);
int cleanup_gpio(struct gpiod_line **lines);

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signum);
        cleanup_gpio(lines);
        if (csv_file != NULL) {
            fclose(csv_file);
        }
        exit(0);
    }
}

// Function to read sensor value
int read_sensor(int gpio_pin) {
    int value = gpiod_line_get_value(lines[gpio_pin - GPIO_17]);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", gpio_pin, strerror(errno));
        return -1; // Indicate error
    }
    return value;
}

// Function to log data to CSV file
int log_data(FILE *fp, int sensor1, int sensor2, int sensor3, int sensor4) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d,%d\n", timestamp, sensor1, sensor2, sensor3, sensor4) < 0) {
        fprintf(stderr, "Error writing to CSV file: %s\n", strerror(errno));
        return -1; // Indicate error
    }

    fflush(fp); // Flush the buffer to ensure data is written immediately
    return 0;
}

// Function to setup GPIO line
int setup_gpio(int gpio_pin, struct gpiod_line **line) {
    struct gpiod_chip *chip;
    struct gpiod_line_request_config config;

    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIOCHIP, strerror(errno));
        return -1;
    }

    *line = gpiod_chip_get_line(chip, gpio_pin);
    if (!*line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", gpio_pin, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    memset(&config, 0, sizeof(config));
    config.consumer = "ir_tracking";

    if (gpiod_line_request_input(*line, &config) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as input: %s\n", gpio_pin, strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(*line);
        return -1;
    }

    gpiod_chip_close(chip);
    return 0;
}

// Function to cleanup GPIO lines
int cleanup_gpio(struct gpiod_line **lines) {
    for (int i = 0; i < 4; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open CSV file for appending
    csv_file = fopen(CSV_FILE, "a");
    if (!csv_file) {
        fprintf(stderr, "Error opening CSV file %s: %s\n", CSV_FILE, strerror(errno));
        return 1;
    }

    // Check if the file is empty and write the header if needed
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "timestamp,sensor1,sensor2,sensor3,sensor4\n");
    }
    fseek(csv_file, 0, SEEK_END); // Reset file pointer to the end for appending

    // Setup GPIO lines
    if (setup_gpio(GPIO_17, &lines[0]) != 0 ||
        setup_gpio(GPIO_18, &lines[1]) != 0 ||
        setup_gpio(GPIO_27, &lines[2]) != 0 ||
        setup_gpio(GPIO_22, &lines[3]) != 0) {
        cleanup_gpio(lines);
        fclose(csv_file);
        return 1;
    }

    // Main loop
    while (1) {
        int sensor1 = read_sensor(GPIO_17);
        int sensor2 = read_sensor(GPIO_18);
        int sensor3 = read_sensor(GPIO_27);
        int sensor4 = read_sensor(GPIO_22);

        if (sensor1 == -1 || sensor2 == -1 || sensor3 == -1 || sensor4 == -1) {
            fprintf(stderr, "Error reading sensors, retrying...\n");
            // Optionally add a delay before retrying
            struct timespec delay = {0, 100000000}; // 100ms
            nanosleep(&delay, NULL);
            continue; // Skip logging and delay, retry immediately
        }

        if (log_data(csv_file, sensor1, sensor2, sensor3, sensor4) != 0) {
            fprintf(stderr, "Error logging data, retrying...\n");
        }

        struct timespec delay = {0, 100000000}; // 100ms
        nanosleep(&delay, NULL);
    }

    return 0;
}

