#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define SENSOR1_PIN 17
#define SENSOR2_PIN 27
#define LED_PIN 22

// Global variables for signal handling
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int read_sensor(int gpio_pin);
int control_led(int gpio_pin, int state);
int log_data(FILE *fp, int sensor1_value, int sensor2_value, int led_state);
void signal_handler(int signal);

// Function to read sensor value
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to control LED state
int control_led(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
    return 0; // pigpio doesn't return error codes directly, so return 0 for success
}

// Function to log data to file
int log_data(FILE *fp, int sensor1_value, int sensor2_value, int led_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, sensor1_value, sensor2_value, led_state) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("obstacle_log.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Obstacle avoidance system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR1_PIN);
        int sensor2_value = read_sensor(SENSOR2_PIN);

        // Determine LED state
        int led_state = (sensor1_value == 0 && sensor2_value == 0) ? 1 : 0;

        // Control LED
        control_led(LED_PIN, led_state);

        // Log data
        if (log_data(log_file, sensor1_value, sensor2_value, led_state) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Delay
        gpioDelay(100); // 100 ms
    }

    // Cleanup
    control_led(LED_PIN, 0); // Turn off LED
    fclose(log_file);
    gpioTerminate();

    printf("Obstacle avoidance system stopped.\n");

    return 0;
}

