#define SAMPLE_RATE 8000 // Hz
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE) // microseconds

// Global flag for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, stopping program...\n", signal);
    program_running = 0;
}

// Function to read the microphone data
int read_microphone() {
    return gpioRead(MIC_PIN);
}

// Function to trigger the LED
void trigger_led() {
    gpioWrite(LED_PIN, 1); // Turn LED on
    gpioDelay(100);        // Wait 100 ms
    gpioWrite(LED_PIN, 0); // Turn LED off
}

// Function to get the current timestamp in milliseconds
void get_timestamp(char *timestamp) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long milliseconds = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);
    sprintf(timestamp, "%ld", milliseconds);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MIC_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Microphone peak detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read microphone data
        int mic_value = read_microphone();

        // Check for peak
        if (mic_value == 1) {
