            char timestamp[20];
            get_timestamp(timestamp);

            // Print timestamp
            printf("%s\n", timestamp);

            // Trigger LED
            trigger_led();
        }

        // Delay for sampling period
        gpioDelay(SAMPLE_PERIOD_US);
    }

    // Clean up and exit
    gpioWrite(LED_PIN, 0); // Ensure LED is off
    gpioTerminate();       // Terminate pigpio
    printf("Program terminated gracefully.\n");
    return 0;
}

