#define CENTER_SENSOR 27
#define RIGHT_SENSOR 22

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the sensor value from a given GPIO pin
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to log the sensor states to the console
void log_sensor_states(int left, int center, int right) {
    printf("Left: %d, Center: %d, Right: %d\n", left, center, right);
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(LEFT_SENSOR, PI_INPUT);
    gpioSetPullUpDown(LEFT_SENSOR, PI_PUD_UP);
    gpioSetMode(CENTER_SENSOR, PI_INPUT);
    gpioSetPullUpDown(CENTER_SENSOR, PI_PUD_UP);
    gpioSetMode(RIGHT_SENSOR, PI_INPUT);
    gpioSetPullUpDown(RIGHT_SENSOR, PI_PUD_UP);

    // Main loop to read and log sensor states
    while (program_running) {
        int left_value = read_sensor(LEFT_SENSOR);
        int center_value = read_sensor(CENTER_SENSOR);
        int right_value = read_sensor(RIGHT_SENSOR);

        if (left_value == -1 || center_value == -1 || right_value == -1) {
            // An error occurred during sensor reading, exit the loop
            break;
        }

        log_sensor_states(left_value, center_value, right_value);

        gpioDelay(100); // Delay for 100 milliseconds
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();

    return 0;
}

