#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

// Define the GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define the GPIO lines for the touch sensor channels
const int gpio_lines[] = {5, 6, 13, 19, 26, 12, 16, 20};
const int num_channels = sizeof(gpio_lines) / sizeof(gpio_lines[0]);

// Global variables for signal handling and resource management
static volatile sig_atomic_t terminate = 0;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *lines[num_channels];

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize the GPIO lines
int initialize_gpio()
{
    int i;
    struct gpiod_line_request_config config;

    // Open the GPIO chip
    chip = gpiod_chip_open(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIOCHIP, strerror(errno));
        return -1;
    }

    // Request each GPIO line as an input
    for (i = 0; i < num_channels; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpio_lines[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error getting line %d: %s\n", gpio_lines[i], strerror(errno));
            goto cleanup;
        }

        memset(&config, 0, sizeof(config));
        config.consumer = "touch_sensor";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

        if (gpiod_line_request(lines[i], &config, 0) < 0) {
            fprintf(stderr, "Error requesting line %d as input: %s\n", gpio_lines[i], strerror(errno));
            goto cleanup;
        }
    }

    return 0;

cleanup:
    // Release resources if initialization fails
    for (int j = 0; j < i; j++) {
        if (lines[j]) {
            gpiod_line_release(lines[j]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return -1;
}

// Function to read the state of a single GPIO line
int read_gpio_line(struct gpiod_line *line)
{
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading line: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

// Function to log the sensor data to the console
void log_sensor_data()
{
    struct timespec ts;
    char timestamp[30];
    int i;
    int values[num_channels];

    // Get the current monotonic time
    if (clock_gettime(CLOCK_MONOTONIC, &ts) == -1) {
        fprintf(stderr, "Error getting monotonic time: %s\n", strerror(errno));
        return;
    }

    // Read the value of each GPIO line
    for (i = 0; i < num_channels; i++) {
        values[i] = read_gpio_line(lines[i]);
        if (values[i] < 0) {
            // Error already logged in read_gpio_line
            return; // Exit the function if there's an error
        }
    }

    // Format the timestamp
    snprintf(timestamp, sizeof(timestamp), "[%ld.%03ld] ", ts.tv_sec, ts.tv_nsec / 1000000);

    // Print the sensor data in the specified format
    printf("%sCH1=%d CH2=%d CH3=%d CH4=%d CH5=%d CH6=%d CH7=%d CH8=%d\n",
           timestamp, values[0], values[1], values[2], values[3], values[4], values[5], values[6], values[7]);
}

int main()
{
    // Install signal handlers for graceful shutdown
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error installing signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Initialize the GPIO lines
    if (initialize_gpio() < 0) {
        return EXIT_FAILURE;
    }

    // Main loop to read and log sensor data
    while (!terminate) {
        log_sensor_data();
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 200000000; // 200 milliseconds
        nanosleep(&sleep_time, NULL);
    }

    // Release resources before exiting
    for (int i = 0; i < num_channels; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return EXIT_SUCCESS;
}

