#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define TCS34725_ADDRESS 0x29
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define RED_THRESHOLD 200
#define CALIBRATION_RED 1.0
#define CALIBRATION_GREEN 1.0
#define CALIBRATION_BLUE 1.0
#define CALIBRATION_CLEAR 1.0
#define OFFSET_RED 0
#define OFFSET_GREEN 0
#define OFFSET_BLUE 0
#define OFFSET_CLEAR 0

// TCS34725 Registers
#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME 0x81
#define TCS34725_CONTROL 0x8F
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A
#define TCS34725_ID 0x12

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int i2c_read_byte(int fd, uint8_t reg, uint8_t *value);
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len);
int tcs34725_init(int fd);
int tcs34725_read_data(int fd, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue);
void gpio_set_value(struct gpiod_line *line, int value);
void signal_handler(int sig);

// I2C write function
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read_byte(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address for read");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

// I2C read multiple bytes function
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address for read");
        return -1;
    }
    if (read(fd, buf, len) != len) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

// TCS34725 initialization function
int tcs34725_init(int fd) {
    uint8_t id;

    // Check sensor ID
    if (i2c_read_byte(fd, TCS34725_ID, &id) != 0) {
        fprintf(stderr, "Error reading sensor ID\n");
        return -1;
    }
    if (id != 0x44) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02x\n", id);
        return -1;
    }

    // Enable power and RGBC
    if (i2c_write_byte(fd, TCS34725_ENABLE, 0x03) != 0) {
        fprintf(stderr, "Error enabling power and RGBC\n");
        return -1;
    }

    // Set integration time to 154ms (ATIME=0x00)
    if (i2c_write_byte(fd, TCS34725_ATIME, 0x00) != 0) {
        fprintf(stderr, "Error setting integration time\n");
        return -1;
    }

    // Set gain to 1x (CONTROL=0x00)
    if (i2c_write_byte(fd, TCS34725_CONTROL, 0x00) != 0) {
        fprintf(stderr, "Error setting gain\n");
        return -1;
    }

    return 0;
}

// TCS34725 read data function
int tcs34725_read_data(int fd, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    uint8_t buf[8];

    if (i2c_read_bytes(fd, TCS34725_CDATA, buf, 8) != 0) {
        fprintf(stderr, "Error reading color data\n");
        return -1;
    }

    *clear = (buf[1] << 8) | buf[0];
    *red   = (buf[3] << 8) | buf[2];
    *green = (buf[5] << 8) | buf[4];
    *blue  = (buf[7] << 8) | buf[6];

    return 0;
}

// GPIO set value function
void gpio_set_value(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        perror("Failed to set GPIO value");
    }
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

int main() {
    uint16_t clear, red, green, blue;
    struct timespec sleep_time = {0, 200000000}; // 200ms

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Initialize TCS34725
    if (tcs34725_init(i2c_fd) != 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    // Get GPIO line
    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Request GPIO line for output
    if (gpiod_line_request_output(gpio_line, "color_sensor", 0) < 0) {
        perror("Failed to request GPIO line for output");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read color data
        if (tcs34725_read_data(i2c_fd, &clear, &red, &green, &blue) == 0) {
            // Apply calibration and offset
            float calibrated_red   = (float)(red   + OFFSET_RED)   * CALIBRATION_RED;
            float calibrated_green = (float)(green + OFFSET_GREEN) * CALIBRATION_GREEN;
            float calibrated_blue  = (float)(blue  + OFFSET_BLUE)  * CALIBRATION_BLUE;
            float calibrated_clear = (float)(clear + OFFSET_CLEAR) * CALIBRATION_CLEAR;

            // Print calibrated values
            printf("C: %d, R: %.2f, G: %.2f, B: %.2f\n", clear, calibrated_red, calibrated_green, calibrated_blue);

            // Control LED based on red value
            if (calibrated_red > RED_THRESHOLD) {
                gpio_set_value(gpio_line, 1); // HIGH
            } else {
                gpio_set_value(gpio_line, 0); // LOW
            }
        } else {
            fprintf(stderr, "Failed to read sensor data, re-initializing...\n");
            // Re-initialize I2C and sensor
            close(i2c_fd);
            i2c_fd = open(I2C_BUS, O_RDWR);
            if (i2c_fd < 0) {
                perror("Failed to open I2C device");
                terminate = 1; // Exit loop if re-initialization fails
                continue;       // Skip the rest of the loop
            }
            if (tcs34725_init(i2c_fd) != 0) {
                fprintf(stderr, "TCS34725 re-initialization failed\n");
                terminate = 1; // Exit loop if re-initialization fails
                continue;       // Skip the rest of the loop
            }
        }

        // Sleep for 200ms
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    gpio_set_value(gpio_line, 0); // Turn off LED
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);
    close(i2c_fd);

    return 0;
}

