#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>
#include <time.h>

// Constants
#define LED_GPIO 18
#define NUM_LEDS 10
#define BH1750_ADDR 0x23
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define I2C_BUS 1
#define MAX_LUX 1000.0
#define MAX_BRIGHTNESS 255
#define PWM_FREQUENCY 800000 // 800 kHz

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_bh1750(float *lux);
int map_lux_to_brightness(float lux);
int set_led_brightness(int brightness);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read lux value from BH1750
int read_bh1750(float *lux) {
    char config_cmd = BH1750_CONTINUOUS_HIGH_RES_MODE;
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cWriteDevice(i2c_handle, &config_cmd, 1);
        if (result == 0) break; // Success
        fprintf(stderr, "I2C write error, retrying...\n");
        gpioDelay(10); // Small delay before retry
        retries--;
    }

    if (retries == 0) {
        fprintf(stderr, "Failed to configure BH1750 after multiple retries.\n");
        return -1;
    }

    gpioDelay(180); // Wait for measurement (at least 180ms)

    char data[2];
    retries = 3;
    while (retries > 0) {
        result = i2cReadDevice(i2c_handle, data, 2);
        if (result == 2) break; // Success
        fprintf(stderr, "I2C read error, retrying...\n");
        gpioDelay(10); // Small delay before retry
        retries--;
    }

    if (retries == 0) {
        fprintf(stderr, "Failed to read BH1750 data after multiple retries.\n");
        return -1;
    }

    uint16_t raw_value = (data[0] << 8) | data[1];
    *lux = (float)raw_value / 1.2;
    return 0;
}

// Map lux value to brightness (logarithmic)
int map_lux_to_brightness(float lux) {
    if (lux <= 0) return 0;
    if (lux >= MAX_LUX) return MAX_BRIGHTNESS;

    // Logarithmic mapping
    float log_lux = log10(lux);
    float log_max_lux = log10(MAX_LUX);
    float brightness_float = (log_lux / log_max_lux) * MAX_BRIGHTNESS;
    int brightness = (int)brightness_float;

    return brightness;
}

// Set LED brightness using hardware PWM
int set_led_brightness(int brightness) {
    gpioPWM(LED_GPIO, brightness);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO mode for PWM
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(LED_GPIO, PWM_FREQUENCY);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float lux;
    int brightness;

    printf("Starting light-controlled LED strip...\n");

    while (!terminate) {
        // Read lux value
        if (read_bh1750(&lux) == 0) {
            // Map lux to brightness
            brightness = map_lux_to_brightness(lux);

            // Set LED brightness
            set_led_brightness(brightness);

            printf("Lux: %.2f, Brightness: %d\n", lux, brightness);
        } else {
            fprintf(stderr, "Failed to read lux value.\n");
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Clean up
    set_led_brightness(0); // Turn off LEDs
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

