#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <time.h>
#include <sys/time.h>

// Configuration
#define BH1750_ADDR 0x23
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define NUM_LEDS 10
#define LUX_MIN 10
#define LUX_MAX 300
#define BRIGHTNESS_MIN 0
#define BRIGHTNESS_MAX 31

// Global variables
int i2c_fd = -1;
int spi_fd = -1;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_init(int address);
int spi_init(const char *device);
int bh1750_read_lux(float *lux);
int apa102_send_frame(uint8_t brightness, uint8_t blue, uint8_t green, uint8_t red);
void signal_handler(int sig);
void cleanup();

// I2C initialization function
int i2c_init(int address) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI initialization function
int spi_init(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Error setting SPI bits per word");
        close(fd);
        return -1;
    }

    // Set SPI speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// BH1750 read lux function
int bh1750_read_lux(float *lux) {
    uint8_t config_cmd = 0x20; // One-Time High-Resolution Mode
    uint8_t buffer[2];
    int ret;

    // Send configuration command
    ret = write(i2c_fd, &config_cmd, 1);
    if (ret != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    // Wait for measurement (at least 180ms)
    usleep(200000); // 200 ms

    // Read 2 bytes of data
    ret = read(i2c_fd, buffer, 2);
    if (ret != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    // Convert to lux
    uint16_t raw_value = (buffer[0] << 8) | buffer[1];
    *lux = (float)raw_value / 1.2;

    return 0;
}

// APA102 send frame function
int apa102_send_frame(uint8_t brightness, uint8_t blue, uint8_t green, uint8_t red) {
    uint8_t frame[4];
    frame[0] = 0xE0 | (brightness & 0x1F); // Global brightness
    frame[1] = blue;
    frame[2] = green;
    frame[3] = red;

    ssize_t ret = write(spi_fd, frame, 4);
    if (ret != 4) {
        perror("Error writing to SPI device");
        return -1;
    }

    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        program_running = 0;
    }
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");

    // Turn off LEDs (set brightness to 0)
    for (int i = 0; i < NUM_LEDS; i++) {
        apa102_send_frame(0, 0, 0, 0);
    }

    // Send end frame
    uint8_t end_frame[4] = {0xFF, 0xFF, 0xFF, 0xFF};
    write(spi_fd, end_frame, 4);

    // Close file descriptors
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (spi_fd != -1) {
        close(spi_fd);
    }
}

int main() {
    float lux;
    uint8_t brightness;
    uint8_t blue, green, red;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = i2c_init(BH1750_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Send start frame (32 bits of 0x00)
    uint8_t start_frame[4] = {0x00, 0x00, 0x00, 0x00};
    write(spi_fd, start_frame, 4);

    // Main loop
    while (program_running) {
        // Read lux value
        if (bh1750_read_lux(&lux) == 0) {
            printf("Lux: %.2f\n", lux);

            // Map lux to brightness
            if (lux < LUX_MIN) {
                brightness = BRIGHTNESS_MIN;
            } else if (lux > LUX_MAX) {
                brightness = BRIGHTNESS_MAX;
            } else {
                brightness = (uint8_t)(((lux - LUX_MIN) / (LUX_MAX - LUX_MIN)) * (BRIGHTNESS_MAX - BRIGHTNESS_MIN) + BRIGHTNESS_MIN);
            }

            // Set LED color (white)
            blue = 0xFF;
            green = 0xFF;
            red = 0xFF;

            // Send APA102 frame
            for (int i = 0; i < NUM_LEDS; i++) {
                apa102_send_frame(brightness, blue, green, red);
            }
        } else {
            fprintf(stderr, "Failed to read lux value.\n");
        }

        // Wait 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

