int read_bh1750(int i2c_handle);
float calculate_average_lux(int lux_values[], int num_sensors);
int map_lux_to_brightness(float average_lux);
void set_apa102_brightness(int brightness);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

// Function to read lux value from BH1750 sensor
int read_bh1750(int i2c_handle) {
    char config_cmd = 0x21; // One-Time High-Resolution Mode 2
    char buffer[2];
    int lux = -1; // Initialize to -1 to indicate error

    if (i2cWriteDevice(i2c_handle, &config_cmd, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }

    gpioDelay(180); // Wait for conversion (at least 180ms)

    if (i2cReadDevice(i2c_handle, buffer, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return -1;
    }

    lux = (buffer[0] << 8) | buffer[1];
    return lux;
}

// Function to calculate the average lux value
float calculate_average_lux(int lux_values[], int num_sensors) {
    float sum = 0.0;
    int valid_sensors = 0;

    for (int i = 0; i < num_sensors; i++) {
        if (lux_values[i] >= 0) {
            sum += lux_values[i];
            valid_sensors++;
        }
    }

    if (valid_sensors > 0) {
        return sum / valid_sensors;
    } else {
        return 0.0; // Return 0 if no valid sensors
    }
}

// Function to map lux value to brightness level (0-31)
int map_lux_to_brightness(float average_lux) {
    // Invert the mapping: lower lux -> higher brightness
    int brightness = 31 - (int)(average_lux / 100.0); // Scale lux to 0-31
    if (brightness < 0) brightness = 0;
    if (brightness > 31) brightness = 31;
    return brightness;
}

// Function to set the APA102 strip brightness
void set_apa102_brightness(int brightness) {
    unsigned char data[4];
    data[0] = 0x00; // Start frame (0x00 0x00 0x00 0x00)
    data[1] = 0x00;
    data[2] = 0x00;
    data[3] = 0x00;

    spiWrite(spi_handle, (char *)data, 4);

    // Data frame: 0x01 [B] [G] [R] [W] (0x00)
    for (int i = 0; i < NUM_LEDS; i++) {
        unsigned char frame[4];
        frame[0] = 0x01; // Global brightness
        frame[1] = brightness; // Blue
        frame[2] = brightness; // Green
        frame[3] = brightness; // Red
        spiWrite(spi_handle, (char *)frame, 4);
    }

    // End frame (0xFF 0xFF 0xFF 0xFF)
    data[0] = 0xFF;
    data[1] = 0xFF;
    data[2] = 0xFF;
    data[3] = 0xFF;
    spiWrite(spi_handle, (char *)data, 4);
