    i2c_handles[1] = i2cOpen(I2C_BUS, BH1750_ADDR_HIGH, 0);

    // Initialize SPI handle
    spi_handle = spiOpen(0, 1000000, 0); // SPI channel 0, 1MHz, mode 0

    if (i2c_handles[0] < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", BH1750_ADDR_LOW, i2c_handles[0]);
        i2c_handles[0] = -1; // Mark as invalid
    }
    if (i2c_handles[1] < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", BH1750_ADDR_HIGH, i2c_handles[1]);
        i2c_handles[1] = -1; // Mark as invalid
    }
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI device: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    int lux_values[NUM_SENSORS] = {0};
    int current_brightness = 0;
    int target_brightness = 0;

    while (!terminate) {
        // Read lux values from sensors
        for (int i = 0; i < NUM_SENSORS; i++) {
            if (i2c_handles[i] != -1) {
                lux_values[i] = read_bh1750(i2c_handles[i]);
                if (lux_values[i] < 0) {
                    fprintf(stderr, "Error reading sensor %d, marking as invalid.\n", i);
                    i2c_handles[i] = -1; // Mark as invalid
                }
            } else {
                lux_values[i] = -1; // Ensure invalid sensors are skipped
            }
        }

        // Calculate average lux
        float average_lux = calculate_average_lux(lux_values, NUM_SENSORS);

        // Map lux to brightness
        target_brightness = map_lux_to_brightness(average_lux);

        // Smoothly fade brightness
        int brightness_diff = target_brightness - current_brightness;
        int step = (brightness_diff > 0) ? 1 : -1;
        int num_steps = abs(brightness_diff);
        for (int i = 0; i < num_steps; i++) {
            current_brightness += step;
            set_apa102_brightness(current_brightness);
            gpioDelay(5); // 5ms delay for smooth fading
        }

        // Delay before next cycle
        gpioDelay(100);
    }

    // Cleanup
    set_apa102_brightness(0); // Turn off LEDs
    spiClose(spi_handle);

    for (int i = 0; i < NUM_SENSORS; i++) {
        if (i2c_handles[i] != -1) {
            i2cClose(i2c_handles[i]);
        }
    }

    gpioTerminate();
    return 0;
}

