#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <math.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

// Configuration
#define I2C_BUS "/dev/i2c-1"
#define VEML7700_ADDR 0x10
#define WS2812B_GPIO 18
#define NUM_LEDS 1
#define LUX_MAX 120000.0
#define GAMMA 2.2
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 100
#define LOOP_DELAY_MS 200

// Global variables (to be cleaned up by signal handler)
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static int i2c_fd = -1;

// Function prototypes
int veml7700_init(int fd);
int veml7700_read_als(int fd, uint16_t *als_value);
float veml7700_calculate_lux(uint16_t als_value);
uint8_t map_lux_to_brightness(float lux);
int ws2812b_set_brightness(uint8_t brightness);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", sig);

    if (gpio_line) {
        gpiod_line_set_value(gpio_line, 0); // Turn off LED
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    exit(0);
}

// VEML7700 initialization function
int veml7700_init(int fd) {
    uint16_t config_value = 0x0000; // IT=100ms, Gain=1/8
    uint8_t buf[3];
    buf[0] = 0x00; // Configuration register address
    buf[1] = config_value & 0xFF;
    buf[2] = (config_value >> 8) & 0xFF;

    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "Error writing to VEML7700 configuration register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// VEML7700 ALS reading function
int veml7700_read_als(int fd, uint16_t *als_value) {
    uint8_t buf[1];
    uint8_t read_buf[2];
    buf[0] = 0x04; // ALS data register address

    if (write(fd, buf, 1) != 1) {
        fprintf(stderr, "Error writing to VEML7700 ALS register address: %s\n", strerror(errno));
        return -1;
    }

    if (read(fd, read_buf, 2) != 2) {
        fprintf(stderr, "Error reading from VEML7700 ALS register: %s\n", strerror(errno));
        return -1;
    }

    *als_value = (read_buf[1] << 8) | read_buf[0];
    return 0;
}

// VEML7700 lux calculation function
float veml7700_calculate_lux(uint16_t als_value) {
    return als_value * 0.0288;
}

// Brightness mapping function with gamma correction
uint8_t map_lux_to_brightness(float lux) {
    float brightness_float = 255.0 * pow(lux / LUX_MAX, 1.0 / GAMMA);
    uint8_t brightness = (uint8_t) brightness_float;
    return brightness;
}

// WS2812B LED strip control function
int ws2812b_set_brightness(uint8_t brightness) {
    // This is a placeholder.  A real implementation would
    // generate the appropriate PWM signal to control the LED.
    // For simplicity, we just print the brightness value.
    printf("Setting brightness to: %d\n", brightness);

    // In a real implementation, you would use the gpiod library
    // to toggle the GPIO pin at a high frequency (e.g., 800 kHz)
    // with a duty cycle proportional to the brightness value.
    // This would involve setting the pin high or low for specific
    // durations based on the brightness value.

    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Initialize VEML7700
    if (veml7700_init(i2c_fd) < 0) {
        fprintf(stderr, "Error initializing VEML7700\n");
        close(i2c_fd);
        return 1;
    }

    // Initialize GPIO
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, WS2812B_GPIO);
    if (!gpio_line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    if (gpiod_line_request_output(gpio_line, "ws2812b", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line for output: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        uint16_t als_value;
        float lux;
        uint8_t brightness;

        // Read ALS value with retry
        int retry = 0;
        while (retry < RETRY_COUNT) {
            if (veml7700_read_als(i2c_fd, &als_value) == 0) {
                break;
            } else {
                fprintf(stderr, "I2C read failed, retrying (%d/%d)...\n", retry + 1, RETRY_COUNT);
                retry++;
                usleep(RETRY_DELAY_MS * 1000); // Delay in microseconds
            }
        }
        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Failed to read ALS value after %d retries\n", RETRY_COUNT);
            continue; // Skip to the next iteration
        }

        // Calculate lux
        lux = veml7700_calculate_lux(als_value);

        // Map lux to brightness
        brightness = map_lux_to_brightness(lux);

        // Set LED brightness
        ws2812b_set_brightness(brightness);

        // Print values
        printf("Lux: %.2f, Brightness: %d\n", lux, brightness);

        // Delay
        usleep(LOOP_DELAY_MS * 1000);
    }

    // Cleanup (should not reach here in normal execution due to signal handler)
    gpiod_line_set_value(gpio_line, 0); // Turn off LED
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);
    close(i2c_fd);

    return 0;
}

