    if (ioctl(i2c_fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Initialize VEML7700
    if (veml7700_init(i2c_fd) < 0) {
        fprintf(stderr, "Error initializing VEML7700\n");
        close(i2c_fd);
        return 1;
    }

    // Initialize GPIO
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, WS2812B_GPIO);
    if (!gpio_line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    if (gpiod_line_request_output(gpio_line, "ws2812b", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line for output: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        uint16_t als_value;
        float lux;
        uint8_t brightness;

        // Read ALS value with retry
        int retry = 0;
        while (retry < RETRY_COUNT) {
            if (veml7700_read_als(i2c_fd, &als_value) == 0) {
                break;
            } else {
                fprintf(stderr, "I2C read failed, retrying (%d/%d)...\n", retry + 1, RETRY_COUNT);
                retry++;
                usleep(RETRY_DELAY_MS * 1000); // Delay in microseconds
            }
        }
        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Failed to read ALS value after %d retries\n", RETRY_COUNT);
            continue; // Skip to the next iteration
        }

        // Calculate lux
        lux = veml7700_calculate_lux(als_value);

        // Map lux to brightness
        brightness = map_lux_to_brightness(lux);

        // Set LED brightness
        ws2812b_set_brightness(brightness);

        // Print values
        printf("Lux: %.2f, Brightness: %d\n", lux, brightness);

        // Delay
        usleep(LOOP_DELAY_MS * 1000);
    }

    // Cleanup (should not reach here in normal execution due to signal handler)
    gpiod_line_set_value(gpio_line, 0); // Turn off LED
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);
    close(i2c_fd);

    return 0;
}

