// Self-test function
void self_test(struct gpiod_chip *chip, struct gpiod_line *flame_line, struct gpiod_line *led_line) {
    struct gpiod_line *buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
