    }

    if (!flame_detected) {
        log_event("Self-test failed: Flame sensor not consistently LOW.");
        // Rapid LED blinking
        for (int i = 0; i < 5; i++) {
            activate_led(led_line);
            usleep(100000); // 100 ms
            deactivate_led(led_line);
            usleep(100000); // 100 ms
        }

        // Buzzer pattern: short-short-long-short
        activate_buzzer(buzzer_line);
