    if (sig == SIGINT) {
        log_event("Received SIGINT. Cleaning up and exiting.");

        // Deactivate buzzer and LED
        deactivate_buzzer(buzzer_line);
        deactivate_led(led_line);

        // Release GPIO lines
        if (flame_line) gpiod_line_release(flame_line);
        if (buzzer_line) gpiod_line_release(buzzer_line);
        if (led_line) gpiod_line_release(led_line);

        // Close GPIO chip
        if (chip) gpiod_chip_close(chip);

        exit(0);
    }
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIOCHIP);
        log_event("Error: Could not open GPIO chip.");
        return 1;
    }

    // Get flame sensor line
    flame_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
