        gpiod_line_release(flame_line);
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set flame sensor line as input
    if (gpiod_line_request(flame_line, NULL, GPIOD_LINE_REQUEST_DIRECTION_INPUT) < 0) {
        fprintf(stderr, "Error requesting flame sensor line as input: %s\n", gpiod_line_get_name(flame_line));
        log_event("Error: Could not request flame sensor line as input.");
        gpiod_line_release(flame_line);
        gpiod_line_release(buzzer_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set buzzer line as output
    if (gpiod_line_request(buzzer_line, NULL, GPIOD_LINE_REQUEST_DIRECTION_OUTPUT) < 0) {
        fprintf(stderr, "Error requesting buzzer line as output: %s\n", gpiod_line_get_name(buzzer_line));
