        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Run self-test
    self_test(chip, flame_line, led_line);

    // Main loop
    while (1) {
        int flame_detected = read_flame_sensor(flame_line);
        if (flame_detected == 0) {
            // Flame detected
            log_event("Flame detected!");
            activate_buzzer(buzzer_line);
            activate_led(led_line);

            // Wait for flame to go away
            while (read_flame_sensor(flame_line) == 0) {
                usleep(50000); // 50 ms
            }

            // Flame gone
            log_event("Flame gone!");
            deactivate_buzzer(buzzer_line);
            deactivate_led(led_line);
        } else if (flame_detected < 0) {
            // Error reading flame sensor, exit
            log_event("Error reading flame sensor. Exiting.");
