        usleep(50000); // 50 ms
    }

    // Cleanup (should not reach here if self-test fails)
    deactivate_buzzer(buzzer_line);
    deactivate_led(led_line);
    gpiod_line_release(flame_line);
    gpiod_line_release(buzzer_line);
    gpiod_line_release(led_line);
    gpiod_chip_close(chip);

    return 0;
}

