#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_DEVICE "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define GPIO_PIN 17
#define BUFFER_SIZE 60

// Global variables
int i2c_fd = -1;
int gpio_fd = -1;
volatile sig_atomic_t program_running = 1;

// Circular buffer for lux readings
float lux_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int i2c_read_word(int fd, uint8_t reg);
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
float convert_to_lux(uint16_t raw_value);
void add_to_buffer(float lux);
float calculate_average_lux();
void set_led_blink_rate(float avg_lux);
void signal_handler(int signal);
int gpio_export(int pin);
int gpio_unexport(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_set_value(int pin, int value);

// I2C read function
int i2c_read_word(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    uint8_t data[2];
    if (read(fd, data, 2) != 2) {
        perror("Failed to read data");
        return -1;
    }
    return (data[0] << 8) | data[1];
}

// I2C write function
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write data");
        return -1;
    }
    return 0;
}

// Convert raw value to lux
float convert_to_lux(uint16_t raw_value) {
    return (float)raw_value / 1.2;
}

// Add lux reading to circular buffer
void add_to_buffer(float lux) {
    lux_buffer[buffer_index] = lux;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Calculate average lux
float calculate_average_lux() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += lux_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

