void set_led_blink_rate(float avg_lux) {
    float rate = 0.5 + (avg_lux / 1000.0) * 4.5;
    if (rate < 0.5) rate = 0.5;
    if (rate > 5.0) rate = 5.0;

    // Calculate on/off times in nanoseconds
    long on_time = (long)(0.5 * 1000000000.0 / rate);
    long off_time = (long)(0.5 * 1000000000.0 / rate);

    // Set GPIO high
    if (gpio_set_value(GPIO_PIN, 1) != 0) {
        fprintf(stderr, "Error setting GPIO high\n");
        return;
    }
    struct timespec on_ts = {0, on_time};
    nanosleep(&on_ts, NULL);

    // Set GPIO low
    if (gpio_set_value(GPIO_PIN, 0) != 0) {
        fprintf(stderr, "Error setting GPIO low\n");
        return;
    }
    struct timespec off_ts = {0, off_time};
    nanosleep(&off_ts, NULL);
}

