        close(fd);
        return -1;
    }
    char val_str[2];
    snprintf(val_str, sizeof(val_str), "%d", value);
    if (write(fd, val_str, 1) != 1) {
        perror("Failed to write to value file");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

