#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

// Define GPIO pins
#define DATA_PIN 17
#define CLOCK_PIN 18
#define LATCH_PIN 27

// Define the seven-segment display patterns for digits 0-9
const unsigned char digit_patterns[] = {
    0x3F, // 0
    0x06, // 1
    0x5B, // 2
    0x4F, // 3
    0x66, // 4
    0x6D, // 5
    0x7D, // 6
    0x07, // 7
    0x7F, // 8
    0x6F  // 9
};

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *data_line;
struct gpiod_line *clock_line;
struct gpiod_line *latch_line;

// Signal handler for Ctrl+C
void signal_handler(int sig);

// Function to initialize GPIO lines
int initialize_gpio();

// Function to shift out data to the 74HC595
void shift_out(unsigned char data);

// Function to display a digit on the seven-segment display
void display_digit(unsigned char digit);

// Function to blink the digit
void blink_digit(unsigned char digit, int duration_ms);

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO lines
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO lines. Exiting.\n");
        return 1;
    }

    // Blink the digit '5' indefinitely
    while (1) {
        blink_digit(digit_patterns[5], 500); // Display '5' for 500ms
    }

    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up and exiting...\n", sig);

    // Release GPIO lines
    if (data_line) {
        gpiod_line_release(data_line);
    }
    if (clock_line) {
        gpiod_line_release(clock_line);
    }
    if (latch_line) {
        gpiod_line_release(latch_line);
    }

    // Close the GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to initialize GPIO lines
int initialize_gpio() {
    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get the data line
    data_line = gpiod_chip_get_line(chip, DATA_PIN);
    if (!data_line) {
        perror("Error getting data line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Get the clock line
    clock_line = gpiod_chip_get_line(chip, CLOCK_PIN);
    if (!clock_line) {
        perror("Error getting clock line");
        gpiod_line_release(data_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Get the latch line
    latch_line = gpiod_chip_get_line(chip, LATCH_PIN);
    if (!latch_line) {
        perror("Error getting latch line");
        gpiod_line_release(data_line);
        gpiod_line_release(clock_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request the data line as output
    if (gpiod_line_request_output(data_line, "seven_segment", 0) < 0) {
        perror("Error requesting data line as output");
        gpiod_line_release(data_line);
        gpiod_line_release(clock_line);
        gpiod_line_release(latch_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request the clock line as output
    if (gpiod_line_request_output(clock_line, "seven_segment", 0) < 0) {
        perror("Error requesting clock line as output");
        gpiod_line_release(data_line);
        gpiod_line_release(clock_line);
        gpiod_line_release(latch_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request the latch line as output
    if (gpiod_line_request_output(latch_line, "seven_segment", 0) < 0) {
        perror("Error requesting latch line as output");
        gpiod_line_release(data_line);
        gpiod_line_release(clock_line);
        gpiod_line_release(latch_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to shift out data to the 74HC595
void shift_out(unsigned char data) {
    for (int i = 0; i < 8; i++) {
        // Set the data line based on the current bit
        if (data & (1 << (7 - i))) {
            gpiod_line_set_value(data_line, 1);
        } else {
            gpiod_line_set_value(data_line, 0);
        }

        // Toggle the clock line
        gpiod_line_set_value(clock_line, 1);
        usleep(1); // Small delay for clock stability
        gpiod_line_set_value(clock_line, 0);
        usleep(1); // Small delay for clock stability
    }
}

// Function to display a digit on the seven-segment display
void display_digit(unsigned char digit) {
    shift_out(digit);
    gpiod_line_set_value(latch_line, 1);
    usleep(1); // Small delay for latch stability
    gpiod_line_set_value(latch_line, 0);
}

// Function to blink the digit
void blink_digit(unsigned char digit, int duration_ms) {
    display_digit(digit);
    usleep(duration_ms * 1000); // Convert milliseconds to microseconds
    display_digit(0x00); // Turn off the display
    usleep(duration_ms * 1000); // Convert milliseconds to microseconds
}

