// Define GPIO pins
#define LED_PIN 17
#define BUTTON_PIN 18

// Define GPIO chip
#define GPIOCHIP "gpiochip0"

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *led_line = NULL;
static struct gpiod_line *button_line = NULL;
static volatile sig_atomic_t running = 1;

// Function prototypes
int setup_gpio(void);
void cleanup_gpio(void);
void signal_handler(int sig);
int blink_led(void);
int button_event(void);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully.\n");
        running = 0;
    }
}

// Setup GPIO function
int setup_gpio(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Request LED line as output
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Error getting LED line");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(led_line, "blink_button", 0);
    if (ret < 0) {
        perror("Error requesting LED line as output");
        gpiod_chip_close(chip);
        return -1;
    }

    // Request button line as input with pull-up and falling edge event detection
    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        perror("Error getting button line");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_rising_edge_events(button_line, "blink_button");
    if (ret < 0) {
        perror("Error requesting button line for rising edge events");
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Cleanup GPIO function
void cleanup_gpio(void) {
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (button_line) {
        gpiod_line_release(button_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

// Blink LED function
int blink_led(void) {
    struct timespec on_time = {1, 0};  // 1 second
    struct timespec off_time = {1, 0}; // 1 second
    int ret;

    while (running) {
        // Turn LED on
        ret = gpiod_line_set_value(led_line, 1);
        if (ret < 0) {
            perror("Error setting LED value");
            return -1;
        }
        nanosleep(&on_time, NULL);

        // Turn LED off
        ret = gpiod_line_set_value(led_line, 0);
        if (ret < 0) {
            perror("Error setting LED value");
            return -1;
        }
        nanosleep(&off_time, NULL);
    }

    return 0;
}

// Button event function
int button_event(void) {
    struct gpiod_line_event event;
    struct gpiod_line_event_request event_req;
    struct timespec timeout = {1, 0}; // 1 second timeout
    int ret;

    // Initialize event request
    event_req.consumer = "blink_button";
    event_req.event_types = GPIOD_LINE_EVENT_RISING_EDGE;
    event_req.flags = 0;

    // Wait for button event with timeout
    ret = gpiod_line_event_wait(button_line, &timeout);
    if (ret < 0) {
        perror("Error waiting for button event");
        return -1;
    }

    // Get the event
    ret = gpiod_line_event_read(button_line, &event);
    if (ret < 0) {
        perror("Error reading button event");
        return -1;
    }

    // Stop blinking and turn off LED
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
    }

    printf("Button pressed! Exiting.\n");
    return 0;
}

int main(void) {
    int ret;

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Setup GPIO
    if (setup_gpio() < 0) {
        fprintf(stderr, "GPIO setup failed. Exiting.\n");
        return 1;
    }

    printf("Blinking LED on GPIO %d (BCM), waiting for button press on GPIO %d (BCM).\n", LED_PIN, BUTTON_PIN);

    // Blink LED and wait for button event
    ret = blink_led();
    if (ret < 0) {
        fprintf(stderr, "LED blinking failed.\n");
        cleanup_gpio();
        return 1;
    }

    ret = button_event();
    if (ret < 0) {
        fprintf(stderr, "Button event failed.\n");
    }

    // Cleanup GPIO
    cleanup_gpio();

    return 0;
}

