#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define LED_GPIO 5

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0;
    }
}

int main() {
    int pigpio_init_result;

    // Initialize pigpio
    pigpio_init_result = gpioInitialise();
    if (pigpio_init_result < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", pigpio_init_result);
        return 1; // Exit with an error code
    }

    // Set GPIO5 as an output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Blinking LED on GPIO %d. Press Ctrl+C to exit.\n", LED_GPIO);

    // Blink the LED indefinitely
    while (program_running) {
        // Turn the LED on
        gpioWrite(LED_GPIO, 1);
        printf("LED ON\n");
        fflush(stdout); // Flush stdout to ensure immediate output

        // Wait for 750ms
        gpioDelay(750000); // pigpioDelay takes microseconds

        // Turn the LED off
        gpioWrite(LED_GPIO, 0);
        printf("LED OFF\n");
        fflush(stdout); // Flush stdout to ensure immediate output

        // Wait for 750ms
        gpioDelay(750000); // pigpioDelay takes microseconds
    }

    // Clean up and exit
    gpioWrite(LED_GPIO, 0); // Turn off the LED
    gpioTerminate(); // Terminate pigpio

    printf("Program terminated.\n");
    return 0;
}

