        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request LED line as output
    ret = gpiod_line_request_output(led_line, "led_control", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting LED line as output: %s\n", strerror(errno));
        gpiod_line_release(button_line);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request button line as input with pull-down
    ret = gpiod_line_request_input(button_line, "button_control");
    if (ret < 0) {
        fprintf(stderr, "Error requesting button line as input: %s\n", strerror(errno));
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

