void control_led(int button_state)
{
    if (button_state == 0) { // Button pressed
        // Blink the LED
        gpiod_line_set_value(led_line, 1);
        usleep(500000); // 500ms
        gpiod_line_set_value(led_line, 0);
        usleep(500000); // 500ms
    } else { // Button released
        // Turn the LED off
        gpiod_line_set_value(led_line, 0);
    }
}

