            fprintf(stderr, "Error reading button value: %s\n", strerror(errno));
            break; // Exit loop on error
        }

        // Control LED based on button state
        control_led(button_value);

        // Small delay to avoid busy-waiting
        usleep(10000); // 10ms
    }

    // Cleanup GPIO resources
    cleanup_gpio();

    fprintf(stderr, "GPIO cleanup complete. Exiting.\n");

    return 0;
}

