#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// LSM303DLHC I2C address
#define LSM303_ADDR 0x19

// LSM303DLHC register addresses
#define CTRL_REG1_A 0x20
#define CTRL_REG4_A 0x23
#define OUT_X_L_A 0x28

// GPIO pin for impact indication
#define IMPACT_PIN 17

// Default G-force threshold
#define DEFAULT_THRESHOLD 2.0

// Global variables
int i2c_handle;
double g_force_threshold = DEFAULT_THRESHOLD;
FILE *log_file = NULL;

// Structure to hold accelerometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

// Function prototypes
int initialize_i2c();
int configure_sensor();
accelerometer_data_t read_accelerometer_data();
double calculate_g_force_magnitude(accelerometer_data_t data);
void log_impact_data(accelerometer_data_t data);
void handle_impact();
void signal_handler(int signal);
void cleanup();

// Function to initialize the I2C interface
int initialize_i2c() {
    i2c_handle = i2cOpen(1, LSM303_ADDR, 0); // Bus 1, address 0x19, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to configure the LSM303DLHC sensor
int configure_sensor() {
    // Enable all axes, 100 Hz data rate
    if (i2cWriteByteData(i2c_handle, CTRL_REG1_A, 0x27) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1_A\n");
        return -1;
    }

    // 2G full-scale, sensitivity 16384 LSB/G
    if (i2cWriteByteData(i2c_handle, CTRL_REG4_A, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4_A\n");
        return -1;
    }

    return 0;
}

// Function to read accelerometer data
accelerometer_data_t read_accelerometer_data() {
    accelerometer_data_t data;
    char buffer[6];

    // Read 6 bytes starting from OUT_X_L_A with auto-increment
    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L_A | 0x80, buffer, 6) < 0) {
        fprintf(stderr, "Error reading accelerometer data\n");
        data.x = 0; data.y = 0; data.z = 0; // Return zeroed data on error
        return data;
    }

    // Combine high and low bytes for each axis
    data.x = (int16_t)((buffer[1] << 8) | buffer[0]);
    data.y = (int16_t)((buffer[3] << 8) | buffer[2]);
    data.z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return data;
}

// Function to calculate the total G-force magnitude
double calculate_g_force_magnitude(accelerometer_data_t data) {
    // Sensitivity is 16384 LSB/G
    double x_g = (double)data.x / 16384.0;
    double y_g = (double)data.y / 16384.0;
    double z_g = (double)data.z / 16384.0;

    return sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

// Function to log impact data to a file
void log_impact_data(accelerometer_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d, %d, %d\n", timestamp, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to handle impact events
void handle_impact() {
    gpioWrite(IMPACT_PIN, 1); // Set GPIO HIGH
    gpioDelay(50);           // Wait for 50 ms
    gpioWrite(IMPACT_PIN, 0); // Set GPIO LOW
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                g_force_threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(IMPACT_PIN, PI_OUTPUT);

    // Initialize I2C
    if (initialize_i2c() < 0) {
        cleanup();
        return 1;
    }

    // Configure the sensor
    if (configure_sensor() < 0) {
        cleanup();
        return 1;
    }

    // Open the log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read accelerometer data
        accelerometer_data_t data = read_accelerometer_data();

        // Calculate G-force magnitude
        double g_force = calculate_g_force_magnitude(data);

        // Check for impact
        if (g_force > g_force_threshold) {
            printf("Impact detected! G-force: %.2f\n", g_force);
            handle_impact();
            log_impact_data(data);
        }

        // Delay for 100 ms (10 Hz polling rate)
        gpioDelay(100);
    }

    return 0;
}

