#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define ADPD188BI_ADDR 0x39
#define MODE_REG 0x0D
#define ALS_LSB_REG 0x64
#define ALS_MSB_REG 0x65
#define RED_REG 0x66
#define GREEN_REG 0x68
#define BLUE_REG 0x6A
#define LED_GPIO 18
#define PWM_FREQUENCY 1000 // Hz
#define ALS_MAX 65535
#define PWM_MAX 255

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_16bit_register(int reg);
int read_als_data(uint16_t *als);
int read_rgb_data(uint16_t *red, uint16_t *green, uint16_t *blue);
void map_als_to_pwm(uint16_t als_value, int *pwm_value);
void log_data(uint16_t als, uint16_t red, uint16_t green, uint16_t blue);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioPWM(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
}

// Initialize the ADPD188BI sensor
int initialize_sensor() {
    int result;
    int retries = 3;

    while (retries > 0) {
        result = i2cWriteByteData(i2c_handle, MODE_REG, 0x01);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error writing to MODE register: %d, retrying...\n", result);
            gpioDelay(100); // Wait 100ms
            retries--;
        }
    }
    fprintf(stderr, "Failed to initialize sensor after multiple retries.\n");
    return -1; // Failure
}

// Read a 16-bit register from the sensor
int read_16bit_register(int reg) {
    int result;
    int retries = 3;
    uint8_t lsb, msb;

    while (retries > 0) {
        result = i2cReadByteData(i2c_handle, reg);
        if (result >= 0) {
            lsb = (uint8_t)result;

            result = i2cReadByteData(i2c_handle, reg + 1);
            if (result >= 0) {
                msb = (uint8_t)result;
                return (msb << 8) | lsb;
            } else {
                fprintf(stderr, "Error reading MSB from register 0x%02X: %d, retrying...\n", reg + 1, result);
                gpioDelay(100);
                retries--;
            }
        } else {
            fprintf(stderr, "Error reading LSB from register 0x%02X: %d, retrying...\n", reg, result);
            gpioDelay(100);
            retries--;
        }
    }
    fprintf(stderr, "Failed to read 16-bit register after multiple retries.\n");
    return -1; // Failure
}

// Read ALS data
int read_als_data(uint16_t *als) {
    int result = read_16bit_register(ALS_LSB_REG);
    if (result >= 0) {
        *als = (uint16_t)result;
        return 0;
    } else {
