// FXOS8700CQ I2C address
#define FXOS8700CQ_ADDR 0x1F

// FXOS8700CQ register addresses
#define FXOS8700CQ_WHO_AM_I 0x0D
#define FXOS8700CQ_XYZ_DATA_CFG 0x0E
#define FXOS8700CQ_CTRL_REG1 0x2A
#define FXOS8700CQ_OUT_X_MSB 0x01

// Impact threshold (2g in m/s^2)
#define IMPACT_THRESHOLD 19.62

// Sensitivity (counts/g) for ±2g range
#define SENSITIVITY 4096.0

// Acceleration due to gravity (m/s^2)
#define GRAVITY 9.81

// I2C handle
int i2c_handle;

// File pointer for logging
FILE *log_file;

// Function prototypes
int init_fxos8700cq();
int read_acceleration(float *x, float *y, float *z);
float calculate_magnitude(float x, float y, float z);
int log_impact(float x, float y, float z, float magnitude);
void signal_handler(int signal);

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Function to initialize the FXOS8700CQ sensor
int init_fxos8700cq() {
    // Verify sensor ID
    int who_am_i = i2cReadByteData(i2c_handle, FXOS8700CQ_WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0xC7) {
        fprintf(stderr, "Error: Incorrect WHO_AM_I value: 0x%02X\n", who_am_i);
        return -1;
    }

    // Set to standby mode
    if (i2cWriteByteData(i2c_handle, FXOS8700CQ_CTRL_REG1, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1 (standby): %d\n", i2c_handle);
        return -1;
    }

    // Configure for ±2g range
    if (i2cWriteByteData(i2c_handle, FXOS8700CQ_XYZ_DATA_CFG, 0x00) < 0) {
        fprintf(stderr, "Error writing to XYZ_DATA_CFG: %d\n", i2c_handle);
        return -1;
    }

    // Set to active mode, 200 Hz ODR
    if (i2cWriteByteData(i2c_handle, FXOS8700CQ_CTRL_REG1, 0x01) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1 (active): %d\n", i2c_handle);
        return -1;
    }

    return 0;
}

// Function to read acceleration data from the FXOS8700CQ
int read_acceleration(float *x, float *y, float *z) {
    char buffer[6];
    int result = i2cReadI2CBlockData(i2c_handle, FXOS8700CQ_OUT_X_MSB, buffer, 6);
    if (result < 0) {
        fprintf(stderr, "Error reading acceleration data: %d\n", result);
        return -1;
    }

    // Combine MSB and LSB, shift right by 2 bits, and convert to m/s^2
    int16_t raw_x = (int16_t)((buffer[0] << 8) | buffer[1]) >> 2;
    int16_t raw_y = (int16_t)((buffer[2] << 8) | buffer[3]) >> 2;
    int16_t raw_z = (int16_t)((buffer[4] << 8) | buffer[5]) >> 2;

    *x = (float)raw_x / SENSITIVITY * GRAVITY;
    *y = (float)raw_y / SENSITIVITY * GRAVITY;
    *z = (float)raw_z / SENSITIVITY * GRAVITY;

    return 0;
}

// Function to calculate the magnitude of the acceleration vector
float calculate_magnitude(float x, float y, float z) {
    return sqrt(x * x + y * y + z * z);
}

// Function to log impact data to a file
int log_impact(float x, float y, float z, float magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f\n", timestamp, x, y, z, magnitude);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, FXOS8700CQ_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_fxos8700cq() < 0) {
        fprintf(stderr, "FXOS8700CQ initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    float x, y, z, magnitude;
    while (1) {
        if (read_acceleration(&x, &y, &z) == 0) {
            magnitude = calculate_magnitude(x, y, z);

            if (magnitude > IMPACT_THRESHOLD) {
                log_impact(x, y, z, magnitude);
                printf("Impact detected: x=%.3f, y=%.3f, z=%.3f, magnitude=%.3f\n", x, y, z, magnitude);
            }
        } else {
            fprintf(stderr, "Error reading acceleration, retrying...\n");
        }

        gpioDelay(50); // Sample every 50 ms
    }

    return 0;
}

