#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// ADXL345 I2C address
#define ADXL345_ADDR 0x53

// ADXL345 registers
#define ADXL345_DEVID 0x00
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_DATAX0 0x32
#define ADXL345_DATAX1 0x33
#define ADXL345_DATAY0 0x34
#define ADXL345_DATAY1 0x35
#define ADXL345_DATAZ0 0x36
#define ADXL345_DATAZ1 0x37

// LED GPIO pin
#define LED_PIN 17

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Function prototypes
int initialize_adxl345();
accelerometer_data_t read_acceleration();
void log_data(accelerometer_data_t data);
void control_led(accelerometer_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Function to initialize the ADXL345
int initialize_adxl345() {
    // Verify DEVID register
    int devid = i2cReadByteData(i2c_handle, ADXL345_DEVID);
    if (devid < 0) {
        fprintf(stderr, "Error reading DEVID register: %d\n", devid);
        return -1;
    }
    if (devid != 0xE5) {
        fprintf(stderr, "Incorrect DEVID value: 0x%02X\n", devid);
        return -1;
    }

    // Set data format: full resolution, ±2g range
    int status = i2cWriteByteData(i2c_handle, ADXL345_DATA_FORMAT, 0x0B);
    if (status < 0) {
        fprintf(stderr, "Error writing to DATA_FORMAT register: %d\n", status);
        return -1;
    }

    // Set power control: measure mode
    status = i2cWriteByteData(i2c_handle, ADXL345_POWER_CTL, 0x08);
    if (status < 0) {
        fprintf(stderr, "Error writing to POWER_CTL register: %d\n", status);
        return -1;
    }

    return 0;
}

// Function to read acceleration data from the ADXL345
accelerometer_data_t read_acceleration() {
    accelerometer_data_t data;
    char raw_data[6];

    // Read 6 bytes of data starting at DATAX0
    int bytes_read = i2cReadI2CBlockData(i2c_handle, ADXL345_DATAX0, raw_data, 6);
    if (bytes_read != 6) {
        fprintf(stderr, "Error reading acceleration data: %d\n", bytes_read);
        data.x = 0.0; // Set to 0 to avoid garbage values
        data.y = 0.0;
        data.z = 0.0;
        return data;
    }

    // Combine high and low bytes for each axis
    int16_t x = (int16_t)((raw_data[1] << 8) | raw_data[0]);
    int16_t y = (int16_t)((raw_data[3] << 8) | raw_data[2]);
    int16_t z = (int16_t)((raw_data[5] << 8) | raw_data[4]);

    // Convert to g units (assuming full resolution and ±2g range)
    data.x = (float)x / 256.0;
    data.y = (float)y / 256.0;
    data.z = (float)z / 256.0;

    return data;
}

// Function to log data to a file
void log_data(accelerometer_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to control the LED based on acceleration data
void control_led(accelerometer_data_t data) {
    if (fabs(data.x) > 2.0 || fabs(data.y) > 2.0 || fabs(data.z) > 2.0) {
        gpioWrite(LED_PIN, 1); // Turn LED on
    } else {
        gpioWrite(LED_PIN, 0); // Turn LED off
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, ADXL345_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (initialize_adxl345() != 0) {
        fprintf(stderr, "ADXL345 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("accel_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read acceleration data
        accelerometer_data_t data = read_acceleration();

        // Log data
        log_data(data);

        // Control LED
        control_led(data);

        // Wait 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_PIN, 0); // Turn off LED
    fclose(log_file);
    gpioTerminate();

    return 0;
}

