#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// LSM303DLHC I2C addresses
#define ACCEL_ADDR 0x19
#define MAG_ADDR 0x1E

// LSM303DLHC register addresses
#define CTRL_REG1_A 0x20
#define OUT_X_L_A 0x28
#define OUT_X_H_M 0x03
#define MR_REG_M 0x02

// Scaling factors
#define ACCEL_SCALE 0.001 // 1 mg/LSB = 0.001 g/LSB
#define MAG_SCALE 0.001 // 1 mGauss/LSB

// Global variables
int i2c_handle_accel = -1;
int i2c_handle_mag = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float accel_x, accel_y, accel_z;
    float mag_x, mag_y, mag_z;
    float heading;
} sensor_data_t;

// Function prototypes
int init_i2c();
int init_accelerometer();
int init_magnetometer();
int read_accelerometer(int16_t *x, int16_t *y, int16_t *z);
int read_magnetometer(int16_t *x, int16_t *y, int16_t *z);
sensor_data_t process_data(int16_t accel_x, int16_t accel_y, int16_t accel_z, int16_t mag_x, int16_t mag_y, int16_t mag_z);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize I2C bus
int init_i2c() {
    i2c_handle_accel = i2cOpen(1, ACCEL_ADDR, 0); // I2C bus 1, accelerometer address
    if (i2c_handle_accel < 0) {
        fprintf(stderr, "Error opening I2C device for accelerometer: %d\n", i2c_handle_accel);
        return -1;
    }

    i2c_handle_mag = i2cOpen(1, MAG_ADDR, 0); // I2C bus 1, magnetometer address
    if (i2c_handle_mag < 0) {
        fprintf(stderr, "Error opening I2C device for magnetometer: %d\n", i2c_handle_mag);
        i2cClose(i2c_handle_accel);
        return -1;
    }

    return 0;
}

// Initialize accelerometer
int init_accelerometer() {
    int result = i2cWriteByteData(i2c_handle_accel, CTRL_REG1_A, 0x27); // 50 Hz, all axes enabled
    if (result < 0) {
        fprintf(stderr, "Error writing to accelerometer CTRL_REG1_A: %d\n", result);
        return -1;
    }
    return 0;
}

// Initialize magnetometer
int init_magnetometer() {
    int result = i2cWriteByteData(i2c_handle_mag, MR_REG_M, 0x00); // Continuous-conversion mode
    if (result < 0) {
        fprintf(stderr, "Error writing to magnetometer MR_REG_M: %d\n", result);
        return -1;
    }
    return 0;
}

// Read accelerometer data
int read_accelerometer(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int result = i2cReadI2CBlockData(i2c_handle_accel, OUT_X_L_A | 0x80, buffer, 6); // Read 6 bytes with auto-increment
    if (result < 0) {
        fprintf(stderr, "Error reading accelerometer data: %d\n", result);
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Read magnetometer data
int read_magnetometer(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int result = i2cReadI2CBlockData(i2c_handle_mag, OUT_X_H_M, buffer, 6); // Read 6 bytes
    if (result < 0) {
        fprintf(stderr, "Error reading magnetometer data: %d\n", result);
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Process raw data and calculate heading
sensor_data_t process_data(int16_t accel_x, int16_t accel_y, int16_t accel_z, int16_t mag_x, int16_t mag_y, int16_t mag_z) {
    sensor_data_t data;
    float accel_mag = sqrt(accel_x * accel_x + accel_y * accel_y + accel_z * accel_z);

    // Convert raw values to g and gauss
    data.accel_x = accel_x * ACCEL_SCALE;
    data.accel_y = accel_y * ACCEL_SCALE;
    data.accel_z = accel_z * ACCEL_SCALE;
    data.mag_x = mag_x * MAG_SCALE;
    data.mag_y = mag_y * MAG_SCALE;
    data.mag_z = mag_z * MAG_SCALE;

    // Tilt compensation
    float roll = atan2(data.accel_y, data.accel_z);
    float pitch = atan2(-data.accel_x, sqrt(data.accel_y * data.accel_y + data.accel_z * data.accel_z));

    float mag_x_comp = data.mag_x * cos(pitch) + data.mag_z * sin(pitch);
    float mag_y_comp = data.mag_x * sin(roll) * sin(pitch) + data.mag_y * cos(roll) - data.mag_z * sin(roll) * cos(pitch);

    // Calculate heading
    data.heading = atan2(mag_y_comp, mag_x_comp) * 180 / M_PI;
    if (data.heading < 0) {
        data.heading += 360;
    }

    return data;
}

// Log data to file
int log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n",
            timestamp, data.accel_x, data.accel_y, data.accel_z,
            data.mag_x, data.mag_y, data.mag_z, data.heading);
    fflush(log_file);

    return 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle_accel >= 0) {
        i2cClose(i2c_handle_accel);
    }
    if (i2c_handle_mag >= 0) {
        i2cClose(i2c_handle_mag);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize accelerometer and magnetometer
    if (init_accelerometer() != 0 || init_magnetometer() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("compass_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Write CSV header if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Accel_X(g),Accel_Y(g),Accel_Z(g),Mag_X(Gauss),Mag_Y(Gauss),Mag_Z(Gauss),Heading(deg)\n");
    }
    rewind(log_file);

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t accel_x, accel_y, accel_z;
    int16_t mag_x, mag_y, mag_z;
    sensor_data_t data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_accelerometer(&accel_x, &accel_y, &accel_z) == 0 &&
            read_magnetometer(&mag_x, &mag_y, &mag_z) == 0) {
            // Process data
            data = process_data(accel_x, accel_y, accel_z, mag_x, mag_y, mag_z);

            // Log data
            log_data(data);
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        // Delay for 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

