#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x68
#define SENSOR2_ADDR 0x69
#define DATA_REG 0x01
#define CONTROL_REG 0x00
#define CONTROL_VALUE 0x80
#define SAMPLE_INTERVAL_US 10000 // 10 ms
#define RETRY_DELAY_MS 10
#define MAX_RETRIES 3

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t sample;
    struct timespec timestamp;
} sensor_data_t;

// Function prototypes
int initialize_i2c(int bus, int addr);
int configure_sensor(int handle);
int read_sensor_data(int handle);
void calculate_tdoa(int16_t sensor1_sample, int16_t sensor2_sample, struct timespec sensor1_timestamp, struct timespec sensor2_timestamp, long long *tdoa_sec, long long *tdoa_nsec);
int log_data(struct timespec timestamp, int16_t sensor1_sample, int16_t sensor2_sample, long long tdoa_sec, long long tdoa_nsec);
void signal_handler(int signal);

// Function to initialize I2C
int initialize_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02x: %s\n", addr, strerror(errno));
        return -1;
    }
    return handle;
}

// Function to configure the sensor
int configure_sensor(int handle) {
    if (i2cWriteByteData(handle, CONTROL_REG, CONTROL_VALUE) != 0) {
        fprintf(stderr, "Error writing to control register: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(int handle) {
    char buf[2];
    if (i2cReadI2CBlockData(handle, DATA_REG, buf, 2) != 2) {
        fprintf(stderr, "Error reading data register: %s\n", strerror(errno));
        return -1;
    }
    return (int16_t)((buf[0] << 8) | buf[1]);
}

// Function to calculate TDOA
void calculate_tdoa(int16_t sensor1_sample, int16_t sensor2_sample, struct timespec sensor1_timestamp, struct timespec sensor2_timestamp, long long *tdoa_sec, long long *tdoa_nsec) {
    long long sensor1_ns = (long long)sensor1_timestamp.tv_sec * 1000000000LL + sensor1_timestamp.tv_nsec;
    long long sensor2_ns = (long long)sensor2_timestamp.tv_sec * 1000000000LL + sensor2_timestamp.tv_nsec;
    long long diff_ns = sensor1_ns - sensor2_ns;

    // Basic TDOA calculation (assuming constant speed of sound)
    // tdoa = (sensor1_sample - sensor2_sample) / speed_of_sound
    // For simplicity, we'll just use the time difference between the samples
    *tdoa_sec = diff_ns / 1000000000LL; // seconds
    *tdoa_nsec = diff_ns % 1000000000LL; // nanoseconds
}

// Function to log data to file
int log_data(struct timespec timestamp, int16_t sensor1_sample, int16_t sensor2_sample, long long tdoa_sec, long long tdoa_nsec) {
    if (fprintf(log_file, "%ld,%ld,%d,%d,%lld,%lld\n", timestamp.tv_sec, timestamp.tv_nsec, sensor1_sample, sensor2_sample, tdoa_sec, tdoa_nsec) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open log file
    log_file = fopen("audio_log.dat", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize I2C for both sensors
    i2c_handle1 = initialize_i2c(I2C_BUS, SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Failed to initialize sensor 1, exiting.\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = initialize_i2c(I2C_BUS, SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Failed to initialize sensor 2, exiting.\n");
        i2cClose(i2c_handle1);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Configure both sensors
    if (configure_sensor(i2c_handle1) != 0) {
        fprintf(stderr, "Failed to configure sensor 1, exiting.\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (configure_sensor(i2c_handle2) != 0) {
        fprintf(stderr, "Failed to configure sensor 2, exiting.\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    struct timespec ts1, ts2;
    int16_t sample1, sample2;
    long long tdoa_sec, tdoa_nsec;

    while (!terminate) {
        // Read data from sensor 1
        sample1 = read_sensor_data(i2c_handle1);
        if (sample1 == -1) {
            fprintf(stderr, "Error reading sensor 1, retrying in %d ms.\n", RETRY_DELAY_MS);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }
        clock_gettime(CLOCK_REALTIME, &ts1);

        // Read data from sensor 2
        sample2 = read_sensor_data(i2c_handle2);
        if (sample2 == -1) {
            fprintf(stderr, "Error reading sensor 2, retrying in %d ms.\n", RETRY_DELAY_MS);
