int spi_read_register(int handle, uint8_t reg_addr, int16_t *data) {
    char tx_buf[2];
    char rx_buf[2];

    // Construct the transmit buffer (MSB = 0, register address)
    tx_buf[0] = (reg_addr << 1) & 0x7F; // Ensure MSB is 0
    tx_buf[1] = 0x00; // Dummy byte for reading

    if (spiXfer(handle, tx_buf, rx_buf, 2) < 0) {
        fprintf(stderr, "Error during SPI transfer (read): %d\n", handle);
        return -1;
    }

    // Combine the received bytes into a 16-bit value
    *data = (rx_buf[0] << 8) | rx_buf[1];

    return 0;
}

