int spi_write_register(int handle, uint8_t reg_addr, int16_t data) {
    char tx_buf[2];
    char rx_buf[2];

    // Construct the transmit buffer (MSB = 1, register address)
    tx_buf[0] = (reg_addr << 1) | 0x80; // Set MSB to 1 for write
    tx_buf[1] = data & 0xFF; //LSB

    if (spiXfer(handle, tx_buf, rx_buf, 2) < 0) {
        fprintf(stderr, "Error during SPI transfer (write): %d\n", handle);
        return -1;
    }

