#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

// Constants
#define SPI_BUS 0
#define SPI_CHIP_SELECT 0
#define SPI_DEVICE_PATH "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 8
#define SPI_MODE SPI_MODE_3
#define SPI_SPEED 1000000 // 1 MHz
#define GYRO_SCALE_FACTOR 0.02f // dps/LSB
#define ACCEL_SCALE_FACTOR 0.00025f // g/LSB

// ADIS16448 Register Addresses
#define XGYRO_OUT 0x04
#define YGYRO_OUT 0x06
#define ZGYRO_OUT 0x08
#define XACCL_OUT 0x0A
#define YACCL_OUT 0x0C
#define ZACCL_OUT 0x0E

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int read_register(uint8_t reg_addr, int16_t *data);
void process_data(int16_t gyro_x_raw, int16_t gyro_y_raw, int16_t gyro_z_raw, int16_t accel_x_raw, int16_t accel_y_raw, int16_t accel_z_raw, float *gyro_x_dps, float *gyro_y_dps, float *gyro_z_dps, float *accel_x_g, float *accel_y_g, float *accel_z_g);
void log_data(float gyro_x_dps, float gyro_y_dps, float gyro_z_dps, float accel_x_g, float accel_y_g, float accel_z_g);
void cleanup(void);
void signal_handler(int sig);

// SPI Initialization
int spi_init(void) {
    spi_fd = open(SPI_DEVICE_PATH, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set SPI speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// SPI Transfer
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error performing SPI transfer");
        return -1;
    }

    return 0;
}

// Read Register
int read_register(uint8_t reg_addr, int16_t *data) {
    uint8_t tx_buf[2];
    uint8_t rx_buf[2];

