#define X_ACCL_OUT 0x0A
#define Y_ACCL_OUT 0x0C
#define Z_ACCL_OUT 0x0E

// Scaling factors
#define GYRO_SCALE 0.05  // deg/sec/LSB
#define ACCL_SCALE 0.00025 // g/LSB

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_register(int handle, unsigned short reg_addr);
void signal_handler(int signal);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCtrl+C pressed. Exiting...\n");
}

// Function to read a register from the ADIS16448
int read_register(int handle, unsigned short reg_addr) {
    char tx_buf[2];
    char rx_buf[2];
    int result;

    // Set the register address for reading (bit 15 set)
    tx_buf[0] = (reg_addr | 0x8000) >> 8;
    tx_buf[1] = reg_addr & 0xFF;

    result = spiXfer(handle, tx_buf, rx_buf, 2);
    if (result != 0) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1; // Indicate error
    }

    // Combine the received bytes into a 16-bit value
    return ((rx_buf[0] << 8) | rx_buf[1]);
}

