    float x_accl, y_accl, z_accl;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        x_gyro_raw = read_register(spi_handle, X_GYRO_OUT);
        y_gyro_raw = read_register(spi_handle, Y_GYRO_OUT);
        z_gyro_raw = read_register(spi_handle, Z_GYRO_OUT);

