        if (x_gyro_raw == -1 || y_gyro_raw == -1 || z_gyro_raw == -1 ||
            x_accl_raw == -1 || y_accl_raw == -1 || z_accl_raw == -1) {
            fprintf(stderr, "Error reading IMU data. Retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;       // Skip to the next iteration
        }

