        x_gyro = x_gyro_raw * GYRO_SCALE;
        y_gyro = y_gyro_raw * GYRO_SCALE;
        z_gyro = z_gyro_raw * GYRO_SCALE;
        x_accl = x_accl_raw * ACCL_SCALE;
        y_accl = y_accl_raw * ACCL_SCALE;
        z_accl = z_accl_raw * ACCL_SCALE;

        // Print the data
        printf("Gyro: X=%.2f deg/s, Y=%.2f deg/s, Z=%.2f deg/s | ", x_gyro, y_gyro, z_gyro);
        printf("Accel: X=%.4f g, Y=%.4f g, Z=%.4f g\n", x_accl, y_accl, z_accl);

        gpioDelay(100); // Wait 100 ms
    }

