#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define MMA8451Q_ADDR 0x1D
#define MMA8451Q_WHO_AM_I 0x0D
#define MMA8451Q_STATUS 0x00
#define MMA8451Q_OUT_X_MSB 0x01
#define MMA8451Q_OUT_X_LSB 0x02
#define MMA8451Q_OUT_Y_MSB 0x03
#define MMA8451Q_OUT_Y_LSB 0x04
#define MMA8451Q_OUT_Z_MSB 0x05
#define MMA8451Q_OUT_Z_LSB 0x06
#define MMA8451Q_CTRL_REG1 0x2A
#define ACCEL_RANGE_2G 0x00
#define ACCEL_RANGE_4G 0x08
#define ACCEL_RANGE_8G 0x10
#define ACCEL_SENSITIVITY_2G 0.244 // mg/LSB at 2g range
#define ACCEL_SENSITIVITY_4G 0.488 // mg/LSB at 4g range
#define ACCEL_SENSITIVITY_8G 0.976 // mg/LSB at 8g range
#define ACCEL_THRESHOLD 2.0 // g
#define LED_GPIO 17
#define IMPACT_LOG_FILE "impact_log.txt"
#define SAMPLE_RATE_MS 100

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
bool running = true;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int init_mma8451q(int fd);
int read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z);
float convert_to_g(int16_t raw_value, float sensitivity);
bool check_threshold(float x, float y, float z, float threshold);
void control_led(int gpio, int state);
void log_impact(const char *timestamp);
void signal_handler(int signal);

// I2C read function
int i2c_read_reg(int fd, uint8_t reg) {
    int result = i2c_smbus_read_byte_data(fd, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return result;
}

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    int result = i2c_smbus_write_byte_data(fd, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X with value 0x%02X: %s\n", reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

// Initialize MMA8451Q
int init_mma8451q(int fd) {
    // Verify sensor ID
    int who_am_i = i2c_read_reg(fd, MMA8451Q_WHO_AM_I);
    if (who_am_i != 0x1A) {
        fprintf(stderr, "Error: Incorrect WHO_AM_I value: 0x%02X\n", who_am_i);
        return -1;
    }

    // Set to active mode and 100 Hz data rate
    if (i2c_write_reg(fd, MMA8451Q_CTRL_REG1, 0x01) < 0) {
        return -1;
    }

    // Set accelerometer range to +-2g
    if (i2c_write_reg(fd, MMA8451Q_CTRL_REG1, ACCEL_RANGE_2G) < 0) {
        return -1;
    }

    return 0;
}

// Read acceleration data
int read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z) {
    int x_msb = i2c_read_reg(fd, MMA8451Q_OUT_X_MSB);
    int x_lsb = i2c_read_reg(fd, MMA8451Q_OUT_X_LSB);
    int y_msb = i2c_read_reg(fd, MMA8451Q_OUT_Y_MSB);
    int y_lsb = i2c_read_reg(fd, MMA8451Q_OUT_Y_LSB);
    int z_msb = i2c_read_reg(fd, MMA8451Q_OUT_Z_MSB);
    int z_lsb = i2c_read_reg(fd, MMA8451Q_OUT_Z_LSB);

    if (x_msb < 0 || x_lsb < 0 || y_msb < 0 || y_lsb < 0 || z_msb < 0 || z_lsb < 0) {
        return -1;
    }

    *x = (int16_t)((x_msb << 8) | x_lsb) >> 4; // 12-bit data, right-aligned
    *y = (int16_t)((y_msb << 8) | y_lsb) >> 4;
    *z = (int16_t)((z_msb << 8) | z_lsb) >> 4;

    return 0;
}

// Convert raw acceleration data to g
float convert_to_g(int16_t raw_value, float sensitivity) {
    return (float)raw_value * sensitivity / 1000.0; // Convert mg to g
}

// Check if acceleration magnitude exceeds threshold
bool check_threshold(float x, float y, float z, float threshold) {
    float magnitude = sqrt(x * x + y * y + z * z);
    return magnitude > threshold;
}

// Control LED
void control_led(int gpio, int state) {
    gpioWrite(gpio, state);
}

// Log impact event
void log_impact(const char *timestamp) {
    if (log_file != NULL) {
        fprintf(log_file, "%s: Impact detected\n", timestamp);
        fflush(log_file); // Ensure data is written to file immediately
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = false;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Open I2C bus
    char i2c_device[20];
    snprintf(i2c_device, sizeof(i2c_device), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MMA8451Q_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize MMA8451Q
    if (init_mma8451q(i2c_fd) < 0) {
        fprintf(stderr, "Error initializing MMA8451Q\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(IMPACT_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    int16_t x_raw, y_raw, z_raw;
    float x_g, y_g, z_g;
    struct timespec ts;
    char timestamp[30];

    // Main loop
    while (running) {
        // Read acceleration data
        if (read_acceleration(i2c_fd, &x_raw, &y_raw, &z_raw) == 0) {
            // Convert to g
            x_g = convert_to_g(x_raw, ACCEL_SENSITIVITY_2G);
            y_g = convert_to_g(y_raw, ACCEL_SENSITIVITY_2G);
            z_g = convert_to_g(z_raw, ACCEL_SENSITIVITY_2G);

            // Check threshold
            if (check_threshold(x_g, y_g, z_g, ACCEL_THRESHOLD)) {
                // Get timestamp
                if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
                    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", ts.tv_nsec / 1000000);

                    // Log impact
                    log_impact(timestamp);

                    // Control LED
                    control_led(LED_GPIO, 1);
                    gpioDelay(500); // 500 ms
                    control_led(LED_GPIO, 0);
                } else {
                    fprintf(stderr, "Error getting timestamp: %s\n", strerror(errno));
                }
            }
        } else {
            fprintf(stderr, "Error reading acceleration data\n");
        }

        gpioDelay(SAMPLE_RATE_MS); // 100 ms
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

