    gpioWrite(gpio, state);
}

// Log impact event
void log_impact(const char *timestamp) {
    if (log_file != NULL) {
        fprintf(log_file, "%s: Impact detected\n", timestamp);
        fflush(log_file); // Ensure data is written to file immediately
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = false;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Open I2C bus
    char i2c_device[20];
    snprintf(i2c_device, sizeof(i2c_device), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MMA8451Q_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize MMA8451Q
    if (init_mma8451q(i2c_fd) < 0) {
        fprintf(stderr, "Error initializing MMA8451Q\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(IMPACT_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    int16_t x_raw, y_raw, z_raw;
    float x_g, y_g, z_g;
    struct timespec ts;
    char timestamp[30];

    // Main loop
    while (running) {
        // Read acceleration data
        if (read_acceleration(i2c_fd, &x_raw, &y_raw, &z_raw) == 0) {
            // Convert to g
            x_g = convert_to_g(x_raw, ACCEL_SENSITIVITY_2G);
            y_g = convert_to_g(y_raw, ACCEL_SENSITIVITY_2G);
            z_g = convert_to_g(z_raw, ACCEL_SENSITIVITY_2G);

            // Check threshold
            if (check_threshold(x_g, y_g, z_g, ACCEL_THRESHOLD)) {
                // Get timestamp
                if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
                    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", ts.tv_nsec / 1000000);

                    // Log impact
                    log_impact(timestamp);

                    // Control LED
                    control_led(LED_GPIO, 1);
                    gpioDelay(500); // 500 ms
                    control_led(LED_GPIO, 0);
                } else {
                    fprintf(stderr, "Error getting timestamp: %s\n", strerror(errno));
                }
            }
        } else {
            fprintf(stderr, "Error reading acceleration data\n");
        }

        gpioDelay(SAMPLE_RATE_MS); // 100 ms
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

