#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <math.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define ADXL345_ADDR 0x53
#define INT1_PIN 17 // Physical pin 11
#define ADXL345_INT1_PIN 1 // ADXL345 INT1 pin (GPIO17)

// ADXL345 Registers
#define ADXL345_REG_DEVID 0x00
#define ADXL345_REG_THRESH_FF 0x0A
#define ADXL345_REG_TIME_FF 0x20
#define ADXL345_REG_INT_ENABLE 0x2E
#define ADXL345_REG_INT_MAP 0x2F
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_REG_INT_SOURCE 0x30

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *int1_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int i2c_read_byte(int fd, uint8_t reg, uint8_t *value);
int i2c_read_block(int fd, uint8_t reg, uint8_t *data, int len);
int adxl345_init(int fd);
int adxl345_read_acceleration(int fd, float *x, float *y, float *z);
void interrupt_handler(void *userdata);
void signal_handler(int sig);
void cleanup(void);

// Helper function to get current timestamp
void get_timestamp(char *timestamp)
{
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(timestamp + 19, 5, ".%03ld", ts.tv_nsec / 1000000);
}

// I2C write function
int i2c_write_byte(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read_byte(int fd, uint8_t reg, uint8_t *value)
{
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// I2C block read function
int i2c_read_block(int fd, uint8_t reg, uint8_t *data, int len)
{
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("I2C block read failed");
        return -1;
    }
    return 0;
}

// ADXL345 initialization function
int adxl345_init(int fd)
{
    uint8_t devid;

    // Verify device ID
    if (i2c_read_byte(fd, ADXL345_REG_DEVID, &devid) != 0) {
        fprintf(stderr, "Error reading device ID\n");
        return -1;
    }
    if (devid != 0xE5) {
        fprintf(stderr, "Incorrect device ID: 0x%02X\n", devid);
        return -1;
    }

    // Set THRESH_FF (0x0A) to ~300 mg (0x30)
    if (i2c_write_byte(fd, ADXL345_REG_THRESH_FF, 0x30) != 0) {
        fprintf(stderr, "Error writing THRESH_FF\n");
        return -1;
    }

    // Set TIME_FF (0x20) to ~100 ms (0x0A)
    if (i2c_write_byte(fd, ADXL345_REG_TIME_FF, 0x0A) != 0) {
        fprintf(stderr, "Error writing TIME_FF\n");
        return -1;
    }

    // Enable freefall interrupt via INT_ENABLE (0x2E) bit 2
    if (i2c_write_byte(fd, ADXL345_REG_INT_ENABLE, 0x04) != 0) {
        fprintf(stderr, "Error writing INT_ENABLE\n");
        return -1;
    }

    // Map freefall interrupt to INT1 via INT_MAP (0x2F) = 0x00
    if (i2c_write_byte(fd, ADXL345_REG_INT_MAP, 0x00) != 0) {
        fprintf(stderr, "Error writing INT_MAP\n");
        return -1;
    }

    // Enter measurement mode by setting POWER_CTL (0x2D) to 0x08
    if (i2c_write_byte(fd, ADXL345_REG_POWER_CTL, 0x08) != 0) {
        fprintf(stderr, "Error writing POWER_CTL\n");
        return -1;
    }

    return 0;
}

// ADXL345 read acceleration function
int adxl345_read_acceleration(int fd, float *x, float *y, float *z)
{
    uint8_t data[6];
    int16_t raw_x, raw_y, raw_z;

    if (i2c_read_block(fd, ADXL345_REG_DATAX0, data, 6) != 0) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    raw_x = (int16_t)((data[1] << 8) | data[0]);
    raw_y = (int16_t)((data[3] << 8) | data[2]);
    raw_z = (int16_t)((data[5] << 8) | data[4]);

    // Convert to g-force units (assuming +/- 2g range)
    *x = (float)raw_x / 256.0f;
    *y = (float)raw_y / 256.0f;
    *z = (float)raw_z / 256.0f;

    return 0;
}

// Interrupt handler function
void interrupt_handler(void *userdata)
{
    uint8_t int_source;
    float x, y, z;
    char timestamp[25];

    // Read INT_SOURCE to clear the interrupt
    if (i2c_read_byte(i2c_fd, ADXL345_REG_INT_SOURCE, &int_source) != 0) {
        fprintf(stderr, "Error reading INT_SOURCE in interrupt handler\n");
        return;
    }

    // Check if freefall interrupt is set
    if (!(int_source & 0x04)) {
        return; // Not a freefall event
    }

    // Read acceleration data
    if (adxl345_read_acceleration(i2c_fd, &x, &y, &z) != 0) {
        fprintf(stderr, "Error reading acceleration data in interrupt handler\n");
        return;
    }

    // Get timestamp
    get_timestamp(timestamp);

    // Log data to file
    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fflush(log_file);
}

// Signal handler function
void signal_handler(int sig)
{
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Cleanup function
void cleanup(void)
{
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (int1_line) {
        gpiod_line_release(int1_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main()
{
    struct gpiod_line_request_config config;
    struct gpiod_line_event event;
    int ret;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Initialize ADXL345
    if (adxl345_init(i2c_fd) != 0) {
        fprintf(stderr, "ADXL345 initialization failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("freefall_log.csv", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    fflush(log_file);

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        cleanup();
        return 1;
    }

    // Get GPIO line for INT1
    int1_line = gpiod_chip_get_line(gpio_chip, ADXL345_INT1_PIN);
    if (!int1_line) {
        perror("Failed to get GPIO line");
        cleanup();
        return 1;
    }

    // Request GPIO line for input with rising edge detection
    memset(&config, 0, sizeof(config));
    config.consumer = "adxl345_interrupt";
    config.request_type = GPIOD_LINE_REQUEST_EVENT_RISING_EDGE;
    config.event_buffer_size = 1; // Only need one event at a time

    ret = gpiod_line_request(int1_line, &config, 0);
    if (ret < 0) {
        perror("Failed to request GPIO line");
        cleanup();
        return 1;
    }

    // Set up interrupt handler
    gpiod_line_event_wait(int1_line, NULL); // Clear any pending events
    gpiod_line_event_read(int1_line, &event); // Read any pending events
    gpiod_line_event_wait(int1_line, NULL); // Clear any pending events

    // Main loop
    while (!terminate) {
        ret = gpiod_line_event_wait(int1_line, NULL);
        if (ret < 0) {
            perror("Error waiting for GPIO event");
            break;
        }

        ret = gpiod_line_event_read(int1_line, &event);
        if (ret < 0) {
            perror("Error reading GPIO event");
            break;
        }

        interrupt_handler(NULL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

