#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// LSM6DSR I2C address
#define LSM6DSR_ADDR 0x6A

// LSM6DSR register addresses
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_H_G 0x23
#define OUTY_L_G 0x24
#define OUTY_H_G 0x25
#define OUTZ_L_G 0x26
#define OUTZ_H_G 0x27
#define OUTX_L_XL 0x28
#define OUTX_H_XL 0x29
#define OUTY_L_XL 0x2A
#define OUTY_H_XL 0x2B
#define OUTZ_L_XL 0x2C
#define OUTZ_H_XL 0x2D
#define WHO_AM_I 0x0F

// Configuration values
#define ACCEL_FS_2G 0x00
#define GYRO_FS_250DPS 0x00
#define ODR_104HZ 0x60

// Scaling factors
#define ACCEL_SCALE 0.061 // mg/LSB, for +-2g range
#define GYRO_SCALE 8.75  // mdps/LSB, for +-250 dps range

// Fall detection thresholds
#define FREEFALL_THRESHOLD 0.2f // g
#define IMPACT_THRESHOLD 2.5f   // g

// Fall detection window
#define WINDOW_SIZE 10
#define WINDOW_DURATION (WINDOW_SIZE * 0.01) // seconds (10 readings at 104Hz)

// State machine states
typedef enum {
    IDLE,
    FREEFALL,
    IMPACT
} State;

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float accel_x, accel_y, accel_z;
    float gyro_x, gyro_y, gyro_z;
} sensor_data_t;

// Function prototypes
int init_i2c();
int config_lsm6dsr();
sensor_data_t read_sensor_data();
float calculate_magnitude(sensor_data_t data);
void log_data(sensor_data_t data, float magnitude);
void fall_detection(float magnitude);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0); // I2C bus 1, address 0x6A, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure LSM6DSR
int config_lsm6dsr() {
    // Configure accelerometer: +-2g range, 104 Hz ODR
    if (i2cWriteByteData(i2c_handle, CTRL1_XL, ACCEL_FS_2G | ODR_104HZ) < 0) {
        fprintf(stderr, "Error writing to CTRL1_XL\n");
        return -1;
    }

    // Configure gyroscope: +-250 dps range, 104 Hz ODR
    if (i2cWriteByteData(i2c_handle, CTRL2_G, GYRO_FS_250DPS | ODR_104HZ) < 0) {
        fprintf(stderr, "Error writing to CTRL2_G\n");
        return -1;
    }

    return 0;
}

// Read sensor data
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    int16_t raw_accel_x, raw_accel_y, raw_accel_z;
    int16_t raw_gyro_x, raw_gyro_y, raw_gyro_z;

    // Read accelerometer data
    raw_accel_x = (int16_t)(i2cReadByteData(i2c_handle, OUTX_L_XL) | (i2cReadByteData(i2c_handle, OUTX_H_XL) << 8));
    raw_accel_y = (int16_t)(i2cReadByteData(i2c_handle, OUTY_L_XL) | (i2cReadByteData(i2c_handle, OUTY_H_XL) << 8));
    raw_accel_z = (int16_t)(i2cReadByteData(i2c_handle, OUTZ_L_XL) | (i2cReadByteData(i2c_handle, OUTZ_H_XL) << 8));

    // Read gyroscope data
    raw_gyro_x = (int16_t)(i2cReadByteData(i2c_handle, OUTX_L_G) | (i2cReadByteData(i2c_handle, OUTX_H_G) << 8));
    raw_gyro_y = (int16_t)(i2cReadByteData(i2c_handle, OUTY_L_G) | (i2cReadByteData(i2c_handle, OUTY_H_G) << 8));
    raw_gyro_z = (int16_t)(i2cReadByteData(i2c_handle, OUTZ_L_G) | (i2cReadByteData(i2c_handle, OUTZ_H_G) << 8));

    // Convert to g and dps
    data.accel_x = (float)raw_accel_x * ACCEL_SCALE / 1000.0f;
    data.accel_y = (float)raw_accel_y * ACCEL_SCALE / 1000.0f;
    data.accel_z = (float)raw_accel_z * ACCEL_SCALE / 1000.0f;
    data.gyro_x = (float)raw_gyro_x * GYRO_SCALE / 1000.0f;
    data.gyro_y = (float)raw_gyro_y * GYRO_SCALE / 1000.0f;
    data.gyro_z = (float)raw_gyro_z * GYRO_SCALE / 1000.0f;

    return data;
}

// Calculate acceleration magnitude
float calculate_magnitude(sensor_data_t data) {
    return sqrt(data.accel_x * data.accel_x + data.accel_y * data.accel_y + data.accel_z * data.accel_z);
}

// Log data to file
void log_data(sensor_data_t data, float magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n",
            timestamp, data.accel_x, data.accel_y, data.accel_z,
            data.gyro_x, data.gyro_y, data.gyro_z, magnitude);
    fflush(log_file); // Ensure data is written to file immediately
}

// Fall detection logic
void fall_detection(float magnitude) {
    static State state = IDLE;
    static float magnitude_buffer[WINDOW_SIZE];
    static int buffer_index = 0;
    static int freefall_count = 0;
    static int impact_count = 0;
    static float sum_magnitude = 0.0f;

    magnitude_buffer[buffer_index] = magnitude;
    sum_magnitude -= magnitude_buffer[buffer_index];
    sum_magnitude += magnitude;
    buffer_index = (buffer_index + 1) % WINDOW_SIZE;

    if (buffer_index == 0) {
        float average_magnitude = sum_magnitude / WINDOW_SIZE;

        switch (state) {
            case IDLE:
                if (average_magnitude < FREEFALL_THRESHOLD) {
                    state = FREEFALL;
                    freefall_count = 0;
                    printf("Entering FREEFALL state\n");
                }
                break;
            case FREEFALL:
                if (average_magnitude > IMPACT_THRESHOLD) {
                    state = IMPACT;
                    impact_count = 0;
                    printf("Entering IMPACT state\n");
                } else {
                    freefall_count++;
                    if (freefall_count > 5) { // Exit FREEFALL if no impact detected for 5 windows
                        state = IDLE;
                        printf("Exiting FREEFALL state (no impact)\n");
                    }
                }
                break;
            case IMPACT:
                state = IDLE;
                printf("Exiting IMPACT state\n");
                break;
        }
    }
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() < 0) {
        cleanup();
        return 1;
    }

    // Verify sensor presence
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0 || who_am_i != 0x69) {
        fprintf(stderr, "LSM6DSR not found or communication error. WHO_AM_I: 0x%X\n", who_am_i);
        cleanup();
        return 1;
    }

    // Configure LSM6DSR
    if (config_lsm6dsr() < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("motion_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    sensor_data_t sensor_data;
    float magnitude;

    while (!terminate) {
        // Read sensor data
        sensor_data = read_sensor_data();

        // Calculate acceleration magnitude
        magnitude = calculate_magnitude(sensor_data);

        // Log data
        log_data(sensor_data, magnitude);

        // Fall detection
        fall_detection(magnitude);

        // Delay for approximately 104 Hz (9.6 ms)
        gpioDelay(9600); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

