            timestamp, data.accel_x, data.accel_y, data.accel_z,
            data.gyro_x, data.gyro_y, data.gyro_z, magnitude);
    fflush(log_file); // Ensure data is written to file immediately
}

// Fall detection logic
void fall_detection(float magnitude) {
    static State state = IDLE;
    static float magnitude_buffer[WINDOW_SIZE];
    static int buffer_index = 0;
    static int freefall_count = 0;
    static int impact_count = 0;
    static float sum_magnitude = 0.0f;

    magnitude_buffer[buffer_index] = magnitude;
    sum_magnitude -= magnitude_buffer[buffer_index];
    sum_magnitude += magnitude;
    buffer_index = (buffer_index + 1) % WINDOW_SIZE;

    if (buffer_index == 0) {
        float average_magnitude = sum_magnitude / WINDOW_SIZE;

        switch (state) {
            case IDLE:
                if (average_magnitude < FREEFALL_THRESHOLD) {
                    state = FREEFALL;
                    freefall_count = 0;
                    printf("Entering FREEFALL state\n");
                }
                break;
            case FREEFALL:
                if (average_magnitude > IMPACT_THRESHOLD) {
                    state = IMPACT;
                    impact_count = 0;
                    printf("Entering IMPACT state\n");
                } else {
                    freefall_count++;
                    if (freefall_count > 5) { // Exit FREEFALL if no impact detected for 5 windows
                        state = IDLE;
                        printf("Exiting FREEFALL state (no impact)\n");
                    }
                }
                break;
            case IMPACT:
                state = IDLE;
                printf("Exiting IMPACT state\n");
                break;
        }
    }
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() < 0) {
        cleanup();
        return 1;
    }

    // Verify sensor presence
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0 || who_am_i != 0x69) {
        fprintf(stderr, "LSM6DSR not found or communication error. WHO_AM_I: 0x%X\n", who_am_i);
        cleanup();
        return 1;
    }

    // Configure LSM6DSR
    if (config_lsm6dsr() < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("motion_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    sensor_data_t sensor_data;
    float magnitude;

    while (!terminate) {
        // Read sensor data
        sensor_data = read_sensor_data();

        // Calculate acceleration magnitude
        magnitude = calculate_magnitude(sensor_data);

        // Log data
        log_data(sensor_data, magnitude);

        // Fall detection
        fall_detection(magnitude);

        // Delay for approximately 104 Hz (9.6 ms)
        gpioDelay(9600); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

