#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define D7S_I2C_ADDR 0x53
#define ACCEL_X_LSB_REG 0x28
#define ACCEL_X_MSB_REG 0x29
#define ACCEL_Y_LSB_REG 0x2A
#define ACCEL_Y_MSB_REG 0x2B
#define ACCEL_Z_LSB_REG 0x2C
#define ACCEL_Z_MSB_REG 0x2D
#define SAMPLE_INTERVAL_MS 100
#define CSV_FILENAME "vibration_log.csv"

// Global variables
int i2c_fd = -1;
FILE *csv_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z);
char *get_iso8601_timestamp(char *timestamp_str, size_t timestamp_str_size);
int log_data(FILE *fp, const char *timestamp, int16_t x, int16_t y, int16_t z);
void signal_handler(int signum);

// I2C read register function
int i2c_read_reg(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    uint8_t value;
    if (read(fd, &value, 1) != 1) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

// I2C write register function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read acceleration data function
int read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z) {
    int x_lsb = i2c_read_reg(fd, ACCEL_X_LSB_REG);
    int x_msb = i2c_read_reg(fd, ACCEL_X_MSB_REG);
    int y_lsb = i2c_read_reg(fd, ACCEL_Y_LSB_REG);
    int y_msb = i2c_read_reg(fd, ACCEL_Y_MSB_REG);
    int z_lsb = i2c_read_reg(fd, ACCEL_Z_LSB_REG);
    int z_msb = i2c_read_reg(fd, ACCEL_Z_MSB_REG);

    if (x_lsb == -1 || x_msb == -1 || y_lsb == -1 || y_msb == -1 || z_lsb == -1 || z_msb == -1) {
        return -1; // Indicate failure
    }

    *x = (int16_t)((x_msb << 8) | x_lsb);
    *y = (int16_t)((y_msb << 8) | y_lsb);
    *z = (int16_t)((z_msb << 8) | z_lsb);

    return 0; // Indicate success
}

// Get ISO-8601 timestamp function
char *get_iso8601_timestamp(char *timestamp_str, size_t timestamp_str_size) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp_str, timestamp_str_size, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp_str;
}

// Log data to CSV file function
int log_data(FILE *fp, const char *timestamp, int16_t x, int16_t y, int16_t z) {
    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "Error writing to CSV file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("Caught SIGINT, exiting gracefully...\n");
        program_running = 0;
    }
}

int main() {
    // Install signal handler
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return 1;
    }

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, D7S_I2C_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Open CSV file for appending
    csv_file = fopen(CSV_FILENAME, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Write header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "Timestamp,X,Y,Z\n");
    }
    rewind(csv_file);

    // Main loop
    int16_t x, y, z;
    char timestamp_str[32];
    while (program_running) {
        // Read acceleration data
        if (read_acceleration(i2c_fd, &x, &y, &z) == 0) {
            // Get timestamp
            get_iso8601_timestamp(timestamp_str, sizeof(timestamp_str));

            // Log data to CSV file
            if (log_data(csv_file, timestamp_str, x, y, z) != 0) {
                fprintf(stderr, "Error logging data, skipping.\n");
            }
        } else {
            fprintf(stderr, "Error reading acceleration data, skipping.\n");
        }

        // Sleep for the specified interval
        usleep(SAMPLE_INTERVAL_MS * 1000); // Convert milliseconds to microseconds
    }

    // Close I2C bus and CSV file
    close(i2c_fd);
    fclose(csv_file);

    return 0;
}

