#include <time.h>
#include <string.h>

// Define GPIO pins for the sensors
#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 27

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Structure to hold GPIO configuration
typedef struct {
    int sensor1_gpio;
    int sensor2_gpio;
} gpio_config_t;

// Function prototypes
int initialize_gpio(gpio_config_t *config);
int read_sensor(int gpio_pin);
void log_data(FILE *fp, int sensor1_state, int sensor2_state);
void halt_conveyor();
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Function to initialize GPIO pins
int initialize_gpio(gpio_config_t *config) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(config->sensor1_gpio, PI_INPUT);
    gpioSetPullUpDown(config->sensor1_gpio, PI_PUD_UP);

    gpioSetMode(config->sensor2_gpio, PI_INPUT);
    gpioSetPullUpDown(config->sensor2_gpio, PI_PUD_UP);

    return 0;
}

// Function to read the state of a sensor
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to log data to a file
void log_data(FILE *fp, int sensor1_state, int sensor2_state) {
    struct timespec ts;
