#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define MMA8452Q_ADDR 0x1D
#define MMA8452Q_WHO_AM_I 0x0D
#define MMA8452Q_CTRL_REG1 0x2A
#define MMA8452Q_DATA_START 0x01
#define MMA8452Q_DATA_LENGTH 6
#define SAMPLE_RATE_MS 10
#define TILT_THRESHOLD_DEG 45.0

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int i2c_read_block(int fd, uint8_t reg, uint8_t *data, int len);
int init_mma8452q(int fd);
int read_accelerometer_data(int fd, int16_t *x, int16_t *y, int16_t *z);
double calculate_tilt_angle(int16_t x, int16_t y, int16_t z);
void log_data(FILE *fp, int16_t x, int16_t y, int16_t z);
void signal_handler(int sig);

// I2C read register function
int i2c_read_reg(int fd, uint8_t reg) {
    uint8_t buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }
    if (read(fd, buf, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return buf[0];
}

// I2C write register function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// I2C read block function
int i2c_read_block(int fd, uint8_t reg, uint8_t *data, int len) {
    uint8_t buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("I2C read block failed");
        return -1;
    }
    return 0;
}

// Initialize MMA8452Q sensor
int init_mma8452q(int fd) {
    int who_am_i = i2c_read_reg(fd, MMA8452Q_WHO_AM_I);
    if (who_am_i != 0x2A) {
        fprintf(stderr, "Error: Incorrect WHO_AM_I value: 0x%02X\n", who_am_i);
        return -1;
    }

    // Set to standby mode
    if (i2c_write_reg(fd, MMA8452Q_CTRL_REG1, 0x00) != 0) {
        return -1;
    }

    // Set data rate to 100 Hz and active mode
    if (i2c_write_reg(fd, MMA8452Q_CTRL_REG1, 0x11) != 0) {
        return -1;
    }

    return 0;
}

// Read accelerometer data
int read_accelerometer_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[MMA8452Q_DATA_LENGTH];
    if (i2c_read_block(fd, MMA8452Q_DATA_START, data, MMA8452Q_DATA_LENGTH) != 0) {
        return -1;
    }

    *x = ((int16_t)data[0] << 8 | data[1]) >> 4;
    *y = ((int16_t)data[2] << 8 | data[3]) >> 4;
    *z = ((int16_t)data[4] << 8 | data[5]) >> 4;

    return 0;
}

// Calculate tilt angle
double calculate_tilt_angle(int16_t x, int16_t y, int16_t z) {
    double x_g = (double)x / 2048.0; // Assuming +/- 2g range
    double y_g = (double)y / 2048.0;
    double z_g = (double)z / 2048.0;
    return atan2(x_g, sqrt(y_g * y_g + z_g * z_g)) * 180.0 / M_PI;
}

// Log data to file
void log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(fp); // Ensure data is written immediately
}

// Signal handler
void signal_handler(int sig) {
    program_running = 0;
    fprintf(stderr, "Signal received, exiting...\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MMA8452Q_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize MMA8452Q sensor
    if (init_mma8452q(i2c_fd) != 0) {
        fprintf(stderr, "Failed to initialize MMA8452Q sensor\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("fall_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    int16_t x, y, z;
    double tilt_angle;

    // Main loop
    while (program_running) {
        // Read accelerometer data
        if (read_accelerometer_data(i2c_fd, &x, &y, &z) == 0) {
            // Calculate tilt angle
            tilt_angle = calculate_tilt_angle(x, y, z);

            // Check for fall condition
            if (fabs(tilt_angle) > TILT_THRESHOLD_DEG) {
                log_data(log_file, x, y, z);
            }
        } else {
            fprintf(stderr, "Failed to read accelerometer data\n");
        }

        // Delay for 10 ms
        usleep(SAMPLE_RATE_MS * 1000); // microseconds
    }

    // Close I2C bus and log file
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

