#define CTRL_REG4 0x23
#define OUT_X_L 0x28

// Calibration constants
#define X_OFFSET 0.0
#define Y_OFFSET 0.0
#define Z_OFFSET 0.0
#define X_SCALE 1.0
#define Y_SCALE 1.0
#define Z_SCALE 1.0

// Metal detection threshold (milliGauss)
#define METAL_THRESHOLD 800.0

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len);
int lis3mdl_init(int fd);
int read_magnetic_data(int fd, float *x, float *y, float *z);
void apply_calibration(float *x, float *y, float *z);
float convert_to_mGauss(float raw_value);
void log_data(float x, float y, float z);
void check_metal_detection(float x, float y, float z);
void signal_handler(int sig);

// I2C write function with retry
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    int retries = 3;
    int result = -1;
    while (retries > 0) {
        result = i2c_smbus_write_byte_data(fd, reg, value);
        if (result == 0) {
            return 0; // Success
        }
        fprintf(stderr, "I2C write error: %s. Retrying...\n", strerror(errno));
        retries--;
        usleep(10000); // 10ms delay
    }
    fprintf(stderr, "I2C write failed after multiple retries.\n");
    return -1; // Failure
}

// I2C read function with retry
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len) {
    int retries = 3;
    int result = -1;
    while (retries > 0) {
        result = i2c_smbus_read_i2c_block_data(fd, reg, len, data);
        if (result == len) {
            return 0; // Success
        }
        fprintf(stderr, "I2C read error: %s. Retrying...\n", strerror(errno));
        retries--;
        usleep(10000); // 10ms delay
    }
    fprintf(stderr, "I2C read failed after multiple retries.\n");
    return -1; // Failure
}

// LIS3MDL initialization function
int lis3mdl_init(int fd) {
    // Check WHO_AM_I register
    uint8_t who_am_i;
    if (i2c_read_bytes(fd, WHO_AM_I, &who_am_i, 1) != 0) {
        fprintf(stderr, "Error reading WHO_AM_I register.\n");
        return -1;
    }
    if (who_am_i != 0x3D) {
        fprintf(stderr, "WHO_AM_I returned 0x%02X, expected 0x3D.\n", who_am_i);
        return -1;
    }

    // Configure CTRL_REG1: Continuous-conversion mode, 80 Hz ODR
    if (i2c_write_byte(fd, CTRL_REG1, 0x70) != 0) {
        fprintf(stderr, "Error writing to CTRL_REG1.\n");
        return -1;
    }

    // Configure CTRL_REG3: Continuous-conversion mode
    if (i2c_write_byte(fd, CTRL_REG3, 0x00) != 0) {
        fprintf(stderr, "Error writing to CTRL_REG3.\n");
        return -1;
    }

    // Configure CTRL_REG4: +-4 gauss sensitivity
    if (i2c_write_byte(fd, CTRL_REG4, 0x0C) != 0) {
        fprintf(stderr, "Error writing to CTRL_REG4.\n");
        return -1;
    }

    return 0;
}

// Function to read magnetic data
int read_magnetic_data(int fd, float *x, float *y, float *z) {
    uint8_t data[6];
    if (i2c_read_bytes(fd, OUT_X_L, data, 6) != 0) {
        fprintf(stderr, "Error reading magnetic data.\n");
        return -1;
    }

    // Combine high and low bytes, convert to signed 16-bit integer
    int16_t raw_x = (int16_t)((data[1] << 8) | data[0]);
    int16_t raw_y = (int16_t)((data[3] << 8) | data[2]);
    int16_t raw_z = (int16_t)((data[5] << 8) | data[4]);

    *x = (float)raw_x;
    *y = (float)raw_y;
    *z = (float)raw_z;

    return 0;
}

// Function to apply calibration
void apply_calibration(float *x, float *y, float *z) {
    *x += X_OFFSET;
    *y += Y_OFFSET;
    *z += Z_OFFSET;
    *x *= X_SCALE;
    *y *= Y_SCALE;
    *z *= Z_SCALE;
}

// Function to convert raw value to milliGauss
float convert_to_mGauss(float raw_value) {
    return raw_value * 0.146; // Sensitivity: 0.146 mG/LSB
}

// Function to log data to file
void log_data(float x, float y, float z) {
    if (log_file != NULL) {
        fprintf(log_file, "%.2f,%.2f,%.2f\n", x, y, z);
        fflush(log_file); // Ensure data is written immediately
    } else {
        fprintf(stderr, "Log file is not open.\n");
    }
}

// Function to check for metal detection
void check_metal_detection(float x, float y, float z) {
    float magnitude = sqrt(x * x + y * y + z * z);
    if (magnitude > METAL_THRESHOLD) {
        fprintf(stderr, "Metal detected! Magnitude: %.2f mG\n", magnitude);
    }
}

// Signal handler for graceful shutdown
