#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// ADXL354B Register Addresses
#define PARTID 0x01
#define POWER_CTL 0x2D
#define STATUS 0x04
#define XDATA_L 0x08
#define XDATA_M 0x09
#define XDATA_H 0x0A
#define YDATA_L 0x0B
#define YDATA_M 0x0C
#define YDATA_H 0x0D
#define ZDATA_L 0x0E
#define ZDATA_M 0x0F
#define ZDATA_H 0x10
#define RESET 0x1F

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Sensitivity
#define SENSITIVITY 0.0000039 // 3.9 microg/LSB

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(int handle, uint8_t reg);
int spi_write_register(int handle, uint8_t reg, uint8_t value);
int adxl354b_init(int handle);
int read_acceleration_data(int handle, int16_t *x, int16_t *y, int16_t *z);
void log_data(FILE *fp, int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// SPI Read Register Function
int spi_read_register(int handle, uint8_t reg) {
    char tx[2], rx[2];
    tx[0] = (reg | 0x80) & 0x7F; // Read bit set, multi-byte clear
    tx[1] = 0x00; // Dummy byte for reading

    if (spiXfer(handle, tx, rx, 2) != 0) {
        fprintf(stderr, "SPI read error for register 0x%02X\n", reg);
        return -1;
    }

    return rx[1];
}

// SPI Write Register Function
int spi_write_register(int handle, uint8_t reg, uint8_t value) {
    char tx[2];
    tx[0] = (reg | 0x40) & 0x7F; // Write bit set, multi-byte clear
    tx[1] = value;

    if (spiWrite(handle, tx, 2) != 0) {
        fprintf(stderr, "SPI write error for register 0x%02X\n", reg);
        return -1;
    }

    return 0;
}

// ADXL354B Initialization Function
int adxl354b_init(int handle) {
    // Reset the device
    if (spi_write_register(handle, RESET, 0x52) != 0) {
        fprintf(stderr, "Failed to reset ADXL354B\n");
        return -1;
    }
    gpioDelay(1000); // Wait 1 ms

    // Verify PARTID
    int partid = spi_read_register(handle, PARTID);
    if (partid != 0x1D) {
        fprintf(stderr, "Incorrect PARTID: 0x%02X\n", partid);
        return -1;
    }

    // Set measurement mode (start measurement)
    if (spi_write_register(handle, POWER_CTL, 0x00) != 0) { // Clear RUN bit
        fprintf(stderr, "Failed to clear RUN bit\n");
        return -1;
    }
    gpioDelay(1000); // Wait for STABLE bit

    // Check STABLE bit
    int status = spi_read_register(handle, STATUS);
    if (!(status & 0x08)) {
        fprintf(stderr, "STABLE bit not set\n");
        return -1;
    }

    // Set RUN bit to start measurement
    if (spi_write_register(handle, POWER_CTL, 0x02) != 0) { // Set RUN bit
        fprintf(stderr, "Failed to set RUN bit\n");
        return -1;
    }

    return 0;
}

// Read Acceleration Data Function
int read_acceleration_data(int handle, int16_t *x, int16_t *y, int16_t *z) {
    char tx[7], rx[7];
    tx[0] = (XDATA_L | 0x80) & 0x7F; // Read bit set, multi-byte set
    memset(tx + 1, 0x00, 6); // Dummy bytes for reading

    if (spiXfer(handle, tx, rx, 7) != 0) {
        fprintf(stderr, "SPI read error for acceleration data\n");
        return -1;
    }

    *x = ((int32_t)rx[2] << 12) | ((int32_t)rx[1] << 4) | ((int32_t)rx[0] >> 4);
    *y = ((int32_t)rx[5] << 12) | ((int32_t)rx[4] << 4) | ((int32_t)rx[3] >> 4);
    *z = ((int32_t)rx[8] << 12) | ((int32_t)rx[7] << 4) | ((int32_t)rx[6] >> 4);

    // Sign extend 20-bit data to 32-bit
    if (*x & 0x80000) *x |= 0xFFF00000;
    if (*y & 0x80000) *y |= 0xFFF00000;
    if (*z & 0x80000) *z |= 0xFFF00000;

    return 0;
}

// Log Data Function
void log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s, %d, %d, %d\n", timestamp, x, y, z);
    fflush(fp); // Ensure data is written to file immediately
}

// Signal Handler Function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL354B
    if (adxl354b_init(spi_handle) != 0) {
        fprintf(stderr, "ADXL354B initialization failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("vibration_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;

    // Main loop
    while (!terminate) {
        if (read_acceleration_data(spi_handle, &x, &y, &z) == 0) {
            log_data(log_file, x, y, z);
        } else {
            fprintf(stderr, "Failed to read acceleration data\n");
        }
        gpioDelay(100000); // 100 ms
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

