int read_register(uint8_t reg_addr, uint16_t *data);
imu_data_t read_imu_data();
imu_data_t process_imu_data(uint16_t x_gyro_raw, uint16_t y_gyro_raw, uint16_t z_gyro_raw, uint16_t x_accel_raw, uint16_t y_accel_raw, uint16_t z_accel_raw);
int log_data(imu_data_t data);
void signal_handler(int signal);
