int init_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read data from a register
int read_register(uint8_t reg_addr, uint16_t *data) {
    char tx_buf[2];
    char rx_buf[2];
    int result;

    // Set MSB to read (1) and prepare the register address
    tx_buf[0] = (reg_addr | 0x80) << 1; // ADIS16362 uses left-shifted addresses
    tx_buf[1] = 0x00; // Dummy byte

    result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (result != 2) {
