    data.y_gyro = (double)((int16_t)y_gyro_raw) * 0.05;
    data.z_gyro = (double)((int16_t)z_gyro_raw) * 0.05;
    data.x_accel = (double)((int16_t)x_accel_raw) * 0.0025; // Scale to g
    data.y_accel = (double)((int16_t)y_accel_raw) * 0.0025;
    data.z_accel = (double)((int16_t)z_accel_raw) * 0.0025;
