#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>
#include <unistd.h>

#define GPIOCHIP_NAME "gpiochip4"
#define GPIO_LINE_NUMBER 17

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function to handle SIGINT signal (Ctrl+C)
void sigint_handler(int sig)
{
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully.\n", sig);
}

// Function to initialize the GPIO line
int initialize_gpio()
{
    int ret;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Open the GPIO line
    line = gpiod_line_open(chip, GPIO_LINE_NUMBER, GPIOD_LINE_REQUEST_DIRECTION_INPUT);
    if (!line) {
        perror("Error opening GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to read the GPIO line value
int read_gpio_value()
{
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Error reading GPIO value");
        return -1;
    }
    return value;
}

// Function to log a message with a timestamp
void log_message(const char *message)
{
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
}

// Function to perform the self-parking sequence
void self_parking_sequence()
{
    log_message("Self-parking sequence started");
    // Simulate parking sequence
    sleep(2);
    log_message("Self-parking sequence completed");
}

// Function to cleanup GPIO resources
void cleanup_gpio()
{
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main()
{
    // Register the SIGINT handler
    signal(SIGINT, sigint_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("IR obstacle sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int value = read_gpio_value();
        if (value < 0) {
            fprintf(stderr, "Error reading sensor value. Exiting.\n");
            break;
        }

        if (value == 0) {
            self_parking_sequence();
        }

        sleep(1);
    }

    // Cleanup GPIO resources before exiting
    cleanup_gpio();

    printf("Exiting.\n");
    return 0;
}

