#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for the sensors
#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 27

// Global variables for graceful shutdown
static volatile int running = 1;
static int pi = -1; // pigpio handle

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read sensor values
int read_sensors(int pi, int gpio1, int gpio2) {
    int level1 = gpioRead(gpio1);
    int level2 = gpioRead(gpio2);
    return (level1 << 1) | level2; // Combine sensor readings
}

// Function to log obstacle detection status
void log_status(int sensor1_status, int sensor2_status) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Sensor 1: %s, Sensor 2: %s\n", timestamp,
           sensor1_status == 0 ? "Obstacle Detected" : "Clear",
           sensor2_status == 0 ? "Obstacle Detected" : "Clear");
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    pi = gpioInitialise();
    if (pi < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", pi);
        return 1;
    }

    // Set GPIO modes for input
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);

    printf("Obstacle avoidance system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int sensor_values = read_sensors(pi, SENSOR1_GPIO, SENSOR2_GPIO);
        int sensor1_status = sensor_values & 0x01;
        int sensor2_status = (sensor_values >> 1) & 0x01;

        log_status(sensor1_status, sensor2_status);

        gpioDelay(100); // Delay for 100 milliseconds
    }

    // Clean up and exit
    gpioTerminate();
    printf("pigpio terminated.\n");
    return 0;
}

