        int sensor1_status = sensor_values & 0x01;
        int sensor2_status = (sensor_values >> 1) & 0x01;

        log_status(sensor1_status, sensor2_status);

        gpioDelay(100); // Delay for 100 milliseconds
    }

    // Clean up and exit
    gpioTerminate();
    printf("pigpio terminated.\n");
    return 0;
}

