#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define CS_PIN 8 // GPIO8 (CE0)
#define SPI_MODE SPI_MODE_3
#define SPI_SPEED 1000000 // 1 MHz
#define DATA_READY_REG 0x24
#define X_RATE_REG 0x04
#define Y_RATE_REG 0x06
#define Z_RATE_REG 0x08
#define SCALE_FACTOR 0.02 // deg/sec/LSB
#define READ_COMMAND 0x80 // MSB set for read

// Global variables
static int spi_fd = -1;
static struct gpiod_line *cs_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} gyro_data_t;

// Function prototypes
int spi_init(const char *device);
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int cs_control(int level);
int adis16266_write_register(uint8_t reg, uint8_t value);
int adis16266_read_register(uint8_t reg, uint8_t *value);
gyro_data_t read_gyro_data();
void log_data(gyro_data_t data);
void signal_handler(int sig);

// SPI Initialization
int spi_init(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set SPI speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI Transfer
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 1) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// CS Control
int cs_control(int level) {
    if (cs_line == NULL) {
        fprintf(stderr, "CS line not initialized\n");
        return -1;
    }

    int ret = gpiod_line_set_value(cs_line, level);
    if (ret < 0) {
        perror("Error setting CS line value");
        return -1;
    }

    return 0;
}

// ADIS16266 Write Register
int adis16266_write_register(uint8_t reg, uint8_t value) {
    uint8_t tx_buf[2];
    uint8_t rx_buf[2];

    tx_buf[0] = reg;
    tx_buf[1] = value;

    if (cs_control(0) < 0) return -1; // CS low
    if (spi_transfer(tx_buf, rx_buf, 2) < 0) {
        cs_control(1); // CS high
        return -1;
    }
    if (cs_control(1) < 0) return -1; // CS high

    return 0;
}

// ADIS16266 Read Register
int adis16266_read_register(uint8_t reg, uint8_t *value) {
    uint8_t tx_buf[2];
    uint8_t rx_buf[2];

    tx_buf[0] = READ_COMMAND | reg;
    tx_buf[1] = 0x00; // Dummy byte for reading

    if (cs_control(0) < 0) return -1; // CS low
    if (spi_transfer(tx_buf, rx_buf, 2) < 0) {
        cs_control(1); // CS high
        return -1;
    }
    if (cs_control(1) < 0) return -1; // CS high

    *value = rx_buf[1];
    return 0;
}

// Read Gyro Data
gyro_data_t read_gyro_data() {
    gyro_data_t data;
    uint8_t x_msb, x_lsb, y_msb, y_lsb, z_msb, z_lsb;

    if (adis16266_read_register(X_RATE_REG, &x_msb) < 0) {
        data.x = 0; // Indicate error
    } else if (adis16266_read_register(X_RATE_REG + 1, &x_lsb) < 0) {
        data.x = 0; // Indicate error
    } else {
        data.x = (int16_t)((x_msb << 8) | x_lsb);
    }

    if (adis16266_read_register(Y_RATE_REG, &y_msb) < 0) {
        data.y = 0; // Indicate error
    } else if (adis16266_read_register(Y_RATE_REG + 1, &y_lsb) < 0) {
        data.y = 0; // Indicate error
    } else {
        data.y = (int16_t)((y_msb << 8) | y_lsb);
    }

    if (adis16266_read_register(Z_RATE_REG, &z_msb) < 0) {
        data.z = 0; // Indicate error
    } else if (adis16266_read_register(Z_RATE_REG + 1, &z_lsb) < 0) {
        data.z = 0; // Indicate error
    } else {
        data.z = (int16_t)((z_msb << 8) | z_lsb);
    }

    return data;
}

// Log Data
void log_data(gyro_data_t data) {
    printf("X: %.2f deg/sec, Y: %.2f deg/sec, Z: %.2f deg/sec\n",
           data.x * SCALE_FACTOR, data.y * SCALE_FACTOR, data.z * SCALE_FACTOR);
}

// Signal Handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting...\n");
    terminate = 1;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE);
    if (spi_fd < 0) {
        return 1;
    }

    // Initialize CS line
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        close(spi_fd);
        return 1;
    }

    cs_line = gpiod_chip_get_line(chip, CS_PIN);
    if (!cs_line) {
        perror("Error getting CS line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "gyro_cs";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    int ret = gpiod_line_request(cs_line, &config, 0);
    if (ret < 0) {
        perror("Error requesting CS line");
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    // Configure ADIS16266 for data ready mode
    if (adis16266_write_register(DATA_READY_REG, 0x03) < 0) {
        fprintf(stderr, "Error configuring ADIS16266\n");
        gpiod_line_release(cs_line);
        gpiod_chip_close(chip);
        close(spi_fd);
        return 1;
    }

    // Main loop
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 100000000; // 100 ms

    while (!terminate) {
        gyro_data_t data = read_gyro_data();
        log_data(data);
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    gpiod_line_release(cs_line);
    gpiod_chip_close(chip);
    close(spi_fd);

    return 0;
}

