#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// LSM6DSR I2C address
#define LSM6DSR_ADDR 0x6B

// LSM6DSR register addresses
#define WHO_AM_I 0x0F
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_L_XL 0x28

// Sensitivity values
#define GYRO_SENSITIVITY 0.00875f // dps/LSB
#define ACCEL_SENSITIVITY 0.000061f // g/LSB

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Function to read a single byte from an I2C register
int i2c_read_register(int handle, uint8_t reg) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return result;
}

// Function to write a single byte to an I2C register
int i2c_write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X with value 0x%02X: %d\n", reg, value, result);
        return -1;
    }
    return 0;
}

// Function to initialize the LSM6DSR sensor
int init_lsm6dsr(int handle) {
    // Verify WHO_AM_I register
    int who_am_i = i2c_read_register(handle, WHO_AM_I);
    if (who_am_i < 0 || who_am_i != 0x6B) {
        fprintf(stderr, "Error: WHO_AM_I register returned 0x%02X, expected 0x6B\n", who_am_i);
        return -1;
    }

    // Configure accelerometer: +-2g, 104 Hz
    if (i2c_write_register(handle, CTRL1_XL, 0x42) < 0) {
        return -1;
    }

    // Configure gyroscope: +-250 dps, 104 Hz
    if (i2c_write_register(handle, CTRL2_G, 0x42) < 0) {
        return -1;
    }

    return 0;
}

// Function to read accelerometer and gyroscope data
int read_sensor_data(int handle, float *gyro_x, float *gyro_y, float *gyro_z, float *accel_x, float *accel_y, float *accel_z) {
    char buffer[12];
    int result = i2cReadI2CBlockData(handle, OUTX_L_G, buffer, 12);
    if (result < 0) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    // Extract gyroscope data
    int16_t gyro_x_raw = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t gyro_y_raw = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t gyro_z_raw = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Extract accelerometer data
    int16_t accel_x_raw = (int16_t)((buffer[7] << 8) | buffer[6]);
    int16_t accel_y_raw = (int16_t)((buffer[9] << 8) | buffer[8]);
    int16_t accel_z_raw = (int16_t)((buffer[11] << 8) | buffer[10]);

    // Convert to physical units
    *gyro_x = (float)gyro_x_raw * GYRO_SENSITIVITY;
    *gyro_y = (float)gyro_y_raw * GYRO_SENSITIVITY;
    *gyro_z = (float)gyro_z_raw * GYRO_SENSITIVITY;
    *accel_x = (float)accel_x_raw * ACCEL_SENSITIVITY;
    *accel_y = (float)accel_y_raw * ACCEL_SENSITIVITY;
    *accel_z = (float)accel_z_raw * ACCEL_SENSITIVITY;

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LSM6DSR sensor
    if (init_lsm6dsr(i2c_handle) < 0) {
        fprintf(stderr, "LSM6DSR initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    float gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_handle, &gyro_x, &gyro_y, &gyro_z, &accel_x, &accel_y, &accel_z) == 0) {
            // Print sensor data
            printf("Gyro: X=%.2f dps, Y=%.2f dps, Z=%.2f dps, Accel: X=%.2f g, Y=%.2f g, Z=%.2f g\n",
                   gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        // Delay for 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

