#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// ADXL345 I2C address
#define ADXL345_ADDR 0x53

// ADXL345 registers
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_REG_DATAY0 0x34
#define ADXL345_REG_DATAZ0 0x36

// Scaling factor for +/- 2g range
#define SCALE_FACTOR 0.0039 // 3.9mg/LSB

// Tilt threshold (degrees)
#define TILT_THRESHOLD 30.0

// I2C handle
int i2c_handle;

// Function prototypes
int initialize_adxl345();
int read_acceleration(int16_t *x, int16_t *y, int16_t *z);
double calculate_tilt_angle(int16_t raw_value);
void log_tilt_event(double x_angle, double y_angle, double z_angle);
void signal_handler(int signal);

// Structure to hold accelerometer data
typedef struct {
    double x;
    double y;
    double z;
} accelerometer_data_t;

// Global flag to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the ADXL345
int initialize_adxl345() {
    // Set POWER_CTL register to start measurement
    if (i2cWriteByteData(i2c_handle, ADXL345_REG_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error: Could not write to POWER_CTL register.\n");
        return -1;
    }
    return 0;
}

// Function to read acceleration data from the ADXL345
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char data[6];

    if (i2cReadI2CBlockData(i2c_handle, ADXL345_REG_DATAX0, data, 6) != 6) {
        fprintf(stderr, "Error: Could not read acceleration data.\n");
        return -1;
    }

    *x = (int16_t)((data[1] << 8) | data[0]);
    *y = (int16_t)((data[3] << 8) | data[2]);
    *z = (int16_t)((data[5] << 8) | data[4]);

    return 0;
}

// Function to calculate tilt angle in degrees
double calculate_tilt_angle(int16_t raw_value) {
    double g_value = raw_value * SCALE_FACTOR;
    return atan2(g_value, 1.0) * 180.0 / M_PI;
}

// Function to log tilt events to a file
void log_tilt_event(double x_angle, double y_angle, double z_angle) {
    FILE *fp = fopen("/var/log/tilt_events.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file.\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s - X: %.2f, Y: %.2f, Z: %.2f\n", s, x_angle, y_angle, z_angle);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, ADXL345_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device. %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (initialize_adxl345() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int16_t raw_x, raw_y, raw_z;
    double x_angle, y_angle, z_angle;

    // Main loop
    while (program_running) {
        // Read acceleration data
        if (read_acceleration(&raw_x, &raw_y, &raw_z) == 0) {
            // Calculate tilt angles
            x_angle = calculate_tilt_angle(raw_x);
            y_angle = calculate_tilt_angle(raw_y);
            z_angle = calculate_tilt_angle(raw_z);

            // Log tilt event if threshold is exceeded
            if (fabs(x_angle) > TILT_THRESHOLD || fabs(y_angle) > TILT_THRESHOLD || fabs(z_angle) > TILT_THRESHOLD) {
                log_tilt_event(x_angle, y_angle, z_angle);
            }
        } else {
            fprintf(stderr, "Error: Failed to read acceleration data. Retrying...\n");
        }

        // Delay for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Close I2C device and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

