#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins for Door A and Door B
#define GPIO_A 17
#define GPIO_B 27

// Define the path to the GPIO chip
#define GPIOCHIP "gpiochip0"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
struct gpiod_chip *chip;
struct gpiod_line *line_a, *line_b;
FILE *log_file;

// Function prototypes
int generate_code();
int validate_code(int code, int user_code);
void unlock_door_a();
void lock_door_a();
void unlock_door_b();
void lock_door_b();
void log_access(int code);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully.\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");

    // Lock doors
    lock_door_a();
    lock_door_b();

    // Release GPIO lines
    if (line_a) {
        gpiod_line_release(line_a);
    }
    if (line_b) {
        gpiod_line_release(line_b);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }

    printf("Cleanup complete. Exiting.\n");
}

// Function to generate a random 6-digit code
int generate_code() {
    return (rand() % 900000) + 100000; // Generates a number between 100000 and 999999
}

// Function to validate the user-entered code
int validate_code(int code, int user_code) {
    return (code == user_code);
}

// Function to unlock Door A
void unlock_door_a() {
    int ret = gpiod_line_set_value(line_a, 1);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO %d value: %s\n", GPIO_A, strerror(-ret));
    }
}

// Function to lock Door A
void lock_door_a() {
    int ret = gpiod_line_set_value(line_a, 0);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO %d value: %s\n", GPIO_A, strerror(-ret));
    }
}

// Function to unlock Door B
void unlock_door_b() {
    int ret = gpiod_line_set_value(line_b, 1);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO %d value: %s\n", GPIO_B, strerror(-ret));
    }
}

// Function to lock Door B
void lock_door_b() {
    int ret = gpiod_line_set_value(line_b, 0);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO %d value: %s\n", GPIO_B, strerror(-ret));
    }
}

// Function to log access to the file
void log_access(int code) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%d\n", timestamp, code);
    fflush(log_file); // Ensure data is written to the file immediately
}

int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get the GPIO lines for Door A and Door B
    line_a = gpiod_chip_get_line(chip, GPIO_A);
    if (!line_a) {
        fprintf(stderr, "Error getting GPIO %d line: %s\n", GPIO_A, strerror(errno));
        cleanup();
        return 1;
    }

    line_b = gpiod_chip_get_line(chip, GPIO_B);
    if (!line_b) {
        fprintf(stderr, "Error getting GPIO %d line: %s\n", GPIO_B, strerror(errno));
        cleanup();
        return 1;
    }

    // Request the GPIO lines as outputs
    int ret_a = gpiod_line_request_output(line_a, "door_access", 0);
    if (ret_a < 0) {
        fprintf(stderr, "Error requesting GPIO %d as output: %s\n", GPIO_A, strerror(-ret_a));
        cleanup();
        return 1;
    }

    int ret_b = gpiod_line_request_output(line_b, "door_access", 0);
    if (ret_b < 0) {
        fprintf(stderr, "Error requesting GPIO %d as output: %s\n", GPIO_B, strerror(-ret_b));
        cleanup();
        return 1;
    }

    // Open the log file
    log_file = fopen("access_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Generate the initial security code
    int code = generate_code();
    printf("Initial security code: %d\n", code);

    // Main loop
    while (program_running) {
        int user_code;

        // Prompt the user for the security code
        printf("Enter security code: ");
        if (scanf("%d", &user_code) != 1) {
            // Handle invalid input
            fprintf(stderr, "Invalid input. Please enter a valid 6-digit number.\n");
            while (getchar() != '\n'); // Clear the input buffer
            continue;
        }

        // Validate the security code
        if (validate_code(code, user_code)) {
            printf("Access granted!\n");

            // Unlock Door A for 5 seconds
            unlock_door_a();
            sleep(5);
            lock_door_a();

            // Log the access
            log_access(code);

            // Generate a new security code
            code = generate_code();
            printf("New security code: %d\n", code);
        } else {
            printf("Access denied\n");
        }
    }

    // Cleanup resources before exiting
    cleanup();

    return 0;
}

