#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define ONE_TIME_HIGH_RES_MODE_2 0x21
#define LUX_CONVERSION_FACTOR 5.0 / 6.0
#define LOG_FILE "light_log.txt"
#define SLEEP_DURATION_SEC 5

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_write_byte(int fd, uint8_t addr, uint8_t reg, uint8_t value);
int i2c_read_bytes(int fd, uint8_t addr, uint8_t reg, uint8_t *buf, int len);
float calculate_lux(uint16_t raw_value);
int log_data(FILE *fp, float lux_value);
void signal_handler(int signum);
int setup_i2c();
void cleanup();

// I2C write function
int i2c_write_byte(int fd, uint8_t addr, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read_bytes(int fd, uint8_t addr, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Lux calculation function
float calculate_lux(uint16_t raw_value) {
    return (float)raw_value * LUX_CONVERSION_FACTOR;
}

// Data logging function
int log_data(FILE *fp, float lux_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "Timestamp: %s, Lux: %.2f\n", timestamp, lux_value) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("Received SIGINT, exiting gracefully...\n");
        program_running = 0;
    }
}

// I2C setup function
int setup_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

// Cleanup function
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (setup_i2c() != 0) {
        fprintf(stderr, "I2C setup failed, exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Main loop
    while (program_running) {
        uint8_t data[2];
        uint16_t raw_value;
        float lux_value;

        // Send One-Time High-Resolution Mode 2 command
        if (i2c_write_byte(i2c_fd, BH1750_ADDR, 0x00, ONE_TIME_HIGH_RES_MODE_2) != 0) {
            fprintf(stderr, "Error sending command, retrying I2C setup.\n");
            cleanup();
            if (setup_i2c() != 0) {
                fprintf(stderr, "I2C setup failed, exiting.\n");
                break;
            }
            continue; // Retry the loop
        }

        // Wait for conversion time (180ms)
        usleep(180000); // 180ms

        // Read 2 bytes of data
        if (i2c_read_bytes(i2c_fd, BH1750_ADDR, 0x00, data, 2) != 0) {
            fprintf(stderr, "Error reading data, retrying I2C setup.\n");
            cleanup();
            if (setup_i2c() != 0) {
                fprintf(stderr, "I2C setup failed, exiting.\n");
                break;
            }
            continue; // Retry the loop
        }

        // Combine the bytes into a 16-bit value
        raw_value = (data[0] << 8) | data[1];

        // Calculate lux value
        lux_value = calculate_lux(raw_value);

        // Log the data
        if (log_data(log_file, lux_value) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        // Sleep for 5 seconds
        sleep(SLEEP_DURATION_SEC);
    }

    // Cleanup resources before exiting
    cleanup();

    return 0;
}

