#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define PWM_GPIO 18
#define PWM_FREQ 1000
#define PWM_RANGE 1000
#define PORT 12345
#define SECRET_KEY "MySecretKey"
#define MOTION_MESSAGE_PREFIX "MOTION_DETECTED:"

// Global variables
int i2c_handle;
int server_fd, new_socket;
FILE *log_file;

// Function prototypes
int initialize_mpr121();
int read_mpr121_data(int *electrode_data);
float map_touch_to_frequency(int max_electrode_value);
void play_tone(float frequency);
void stop_tone();
void log_frequency(float frequency);
void handle_client(int client_socket);
void signal_handler(int signum);

// Signal handler
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, shutting down...\n", signum);
        stop_tone();
        if (i2c_handle >= 0) i2cClose(i2c_handle);
        if (server_fd >= 0) close(server_fd);
        if (new_socket >= 0) close(new_socket);
        gpioTerminate();
        if (log_file != NULL) fclose(log_file);
        exit(0);
    }
}

// Initialize MPR121
int initialize_mpr121() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        fprintf(stderr, "Error: Failed to reset MPR121\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Electrode configuration
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x0C) < 0) { // Set Electrode Configuration
        fprintf(stderr, "Error: Failed to set electrode configuration\n");
        return -1;
    }

    // Touch and release thresholds (example values)
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, 0x41 + 2 * i, 0x30) < 0) { // Touch threshold
            fprintf(stderr, "Error: Failed to set touch threshold for electrode %d\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, 0x42 + 2 * i, 0x10) < 0) { // Release threshold
            fprintf(stderr, "Error: Failed to set release threshold for electrode %d\n", i);
            return -1;
        }
    }

    // Enable all electrodes
    if (i2cWriteByteData(i2c_handle, 0x5B, 0x0F) < 0) {
        fprintf(stderr, "Error: Failed to enable electrodes\n");
        return -1;
    }

    // Start sensing
    if (i2cWriteByteData(i2c_handle, 0x5C, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to start sensing\n");
        return -1;
    }

    return 0;
}

// Read MPR121 data
int read_mpr121_data(int *electrode_data) {
    char buf[24];
    if (i2cReadI2CBlockData(i2c_handle, 0x04, buf, 24) < 0) {
        fprintf(stderr, "Error: Failed to read MPR121 data\n");
        return -1;
    }

    for (int i = 0; i < 12; i++) {
        electrode_data[i] = ((buf[2 * i + 1] << 8) | buf[2 * i]) & 0x0FFF; // Combine MSB and LSB
    }

    return 0;
}

// Map touch data to frequency
float map_touch_to_frequency(int max_electrode_value) {
    // Logarithmic scale: 220Hz to 880Hz
    float frequency = 220.0 * pow(2.0, (float)max_electrode_value / 1000.0 * 9.0); // 9 octaves
    if (frequency > 880.0) frequency = 880.0;
    return frequency;
}

// Play tone using hardware PWM
void play_tone(float frequency) {
    int duty_cycle = (int)(PWM_RANGE * 0.5); // 50% duty cycle
    gpioPWM(PWM_GPIO, duty_cycle);
}

// Stop tone
void stop_tone() {
    gpioPWM(PWM_GPIO, 0); // Stop PWM
}

// Log frequency to file
void log_frequency(float frequency) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, Frequency: %.2f Hz\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, frequency);
    fflush(log_file); // Ensure data is written to file immediately
}

// Handle client connection
void handle_client(int client_socket) {
    char buffer[1024] = {0};
    ssize_t valread = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
    if (valread > 0) {
        buffer[valread] = '\0';
        printf("Received: %s\n", buffer);

        // Validate message format and secret key
        if (strncmp(buffer, MOTION_MESSAGE_PREFIX, strlen(MOTION_MESSAGE_PREFIX)) == 0) {
            char *key_start = buffer + strlen(MOTION_MESSAGE_PREFIX);
            if (strncmp(key_start, SECRET_KEY, strlen(SECRET_KEY)) == 0) {
                printf("Valid motion event received.\n");

                // Play theremin tones for 5 seconds
                int electrode_data[12];
                for (int i = 0; i < 50; i++) { // 5 seconds, 20ms interval
                    if (read_mpr121_data(electrode_data) == 0) {
                        int max_electrode_value = 0;
                        for (int j = 0; j < 12; j++) {
                            if (electrode_data[j] > max_electrode_value) {
                                max_electrode_value = electrode_data[j];
                            }
                        }

                        float frequency = map_touch_to_frequency(max_electrode_value);
                        play_tone(frequency);
                        log_frequency(frequency);
                        gpioDelay(20); // 20ms delay
                    } else {
                        fprintf(stderr, "Error reading MPR121 data during playback.\n");
                        break;
                    }
                }
                stop_tone();
            } else {
                fprintf(stderr, "Error: Invalid secret key\n");
            }
        } else {
            fprintf(stderr, "Error: Invalid message format\n");
        }
    } else if (valread == 0) {
        printf("Client disconnected.\n");
    } else {
        perror("recv failed");
    }
    close(client_socket);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set PWM GPIO mode
    gpioSetMode(PWM_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQ);
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (initialize_mpr121() != 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("frequency_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd == 0) {
        perror("socket failed");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Bind socket to address and port
    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        close(server_fd);
        return 1;
    }

    // Listen for connections
    if (listen(server_fd, 3) < 0) {
        perror("listen failed");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        close(server_fd);
        return 1;
    }

    printf("Listening on port %d...\n", PORT);

    // Accept connections in a loop
    while (1) {
        struct sockaddr_in client_address;
        int addrlen = sizeof(client_address);
        new_socket = accept(server_fd, (struct sockaddr *)&client_address, (socklen_t*)&addrlen);
        if (new_socket < 0) {
            perror("accept failed");
            continue; // Continue listening for other connections
        }

        printf("Connection accepted from %s:%d\n", inet_ntoa(client_address.sin_addr), ntohs(client_address.sin_port));

        handle_client(new_socket);
    }

    // The following lines will never be reached due to the infinite loop.
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    close(server_fd);
    return 0;
}

