#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <math.h>
#include <time.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define MAGNETOMETER_ADDRESS 0x1E
#define CTRL_REG1_M 0x20
#define OUT_X_L_M 0x08
#define LED_GPIO 17
#define PWM_CHIP 0
#define PWM_CHANNEL 0
#define SAMPLE_INTERVAL_MS 100
#define Z_AXIS_MAGNITUDE_THRESHOLD 100.0 // Example threshold

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *led_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len);
int initialize_magnetometer(int fd);
int read_magnetometer_data(int fd, int16_t *x, int16_t *y, int16_t *z);
double calculate_z_magnitude(int16_t x, int16_t y, int16_t z);
int set_led_brightness(int brightness);
void signal_handler(int sig);
void cleanup();

// I2C write function
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        fprintf(log_file, "%s", "Error writing to I2C device\n");
        perror("I2C write error");
        return -1;
    }
    return 0;
