#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>

// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L register addresses
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Z_LSB 0x06
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_DATA_Y_LSB 0x08

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Hard-iron offsets
double x_offset = 0.0;
double y_offset = 0.0;
double z_offset = 0.0;

// Number of samples for offset calculation
#define NUM_SAMPLES 100

// Circular buffer for raw data
int16_t x_buffer[NUM_SAMPLES];
int16_t y_buffer[NUM_SAMPLES];
int16_t z_buffer[NUM_SAMPLES];
int buffer_index = 0;

// Function prototypes
int init_hmc5883l();
int read_hmc5883l(int16_t *x, int16_t *y, int16_t *z);
void calculate_hard_iron_offsets();
void apply_hard_iron_offsets(int16_t raw_x, int16_t raw_y, int16_t raw_z, double *corrected_x, double *corrected_y, double *corrected_z);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize the HMC5883L
int init_hmc5883l() {
    // Configuration Register A: 8-sample averaging, 15 Hz output rate
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to Configuration Register A\n");
        return -1;
    }

    // Configuration Register B: Gain setting of 1.3 Gauss
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0x20) < 0) {
        fprintf(stderr, "Error writing to Configuration Register B\n");
        return -1;
    }

    // Mode register: Continuous measurement mode
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing to Mode register\n");
        return -1;
    }

    return 0;
}

// Read raw data from the HMC5883L
int read_hmc5883l(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, buffer, 6) != 6) {
        fprintf(stderr, "Error reading data from HMC5883L\n");
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *z = (int16_t)((buffer[2] << 8) | buffer[3]);
    *y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Calculate hard-iron offsets
void calculate_hard_iron_offsets() {
    double x_sum = 0.0;
    double y_sum = 0.0;
    double z_sum = 0.0;

    for (int i = 0; i < NUM_SAMPLES; i++) {
        x_sum += x_buffer[i];
        y_sum += y_buffer[i];
        z_sum += z_buffer[i];
    }

    x_offset = x_sum / NUM_SAMPLES;
    y_offset = y_sum / NUM_SAMPLES;
    z_offset = z_sum / NUM_SAMPLES;

    printf("Hard-iron offsets: X=%.2f, Y=%.2f, Z=%.2f\n", x_offset, y_offset, z_offset);
}

// Apply hard-iron offsets to raw data
void apply_hard_iron_offsets(int16_t raw_x, int16_t raw_y, int16_t raw_z, double *corrected_x, double *corrected_y, double *corrected_z) {
    *corrected_x = raw_x - x_offset;
    *corrected_y = raw_y - y_offset;
    *corrected_z = raw_z - z_offset;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize HMC5883L
    if (init_hmc5883l() < 0) {
        fprintf(stderr, "HMC5883L initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t raw_x, raw_y, raw_z;
    double corrected_x, corrected_y, corrected_z;

    // Main loop
    while (!terminate) {
        // Read raw data
        if (read_hmc5883l(&raw_x, &raw_y, &raw_z) == 0) {
            // Store raw data in circular buffer
            x_buffer[buffer_index] = raw_x;
            y_buffer[buffer_index] = raw_y;
            z_buffer[buffer_index] = raw_z;

            // Increment buffer index (wrap around if necessary)
            buffer_index = (buffer_index + 1) % NUM_SAMPLES;

            // Apply hard-iron offsets
            apply_hard_iron_offsets(raw_x, raw_y, raw_z, &corrected_x, &corrected_y, &corrected_z);

            // Print corrected data
            printf("X: %.2f, Y: %.2f, Z: %.2f\n", corrected_x, corrected_y, corrected_z);
        } else {
            fprintf(stderr, "Error reading data, retrying...\n");
        }

        // Calculate hard-iron offsets every 500 ms
        if (gpioTick() % 500000 == 0) {
            calculate_hard_iron_offsets();
        }

        gpioDelay(10); // Delay for 10 ms
    }

    // Close I2C device and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

