            // Increment buffer index (wrap around if necessary)
            buffer_index = (buffer_index + 1) % NUM_SAMPLES;

            // Apply hard-iron offsets
            apply_hard_iron_offsets(raw_x, raw_y, raw_z, &corrected_x, &corrected_y, &corrected_z);

            // Print corrected data
            printf("X: %.2f, Y: %.2f, Z: %.2f\n", corrected_x, corrected_y, corrected_z);
        } else {
            fprintf(stderr, "Error reading data, retrying...\n");
        }

        // Calculate hard-iron offsets every 500 ms
        if (gpioTick() % 500000 == 0) {
            calculate_hard_iron_offsets();
        }

        gpioDelay(10); // Delay for 10 ms
    }

    // Close I2C device and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

