    }
}

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        program_running = 0;
    }
}

// Initialize function
int initialize() {
    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, LSM303D_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return -1;
    }

    // Verify WHO_AM_I register
    int who_am_i = i2c_read_byte(i2c_fd, WHO_AM_I);
    if (who_am_i != 0x49) {
        fprintf(stderr, "Error: WHO_AM_I register returned 0x%02X, expected 0x49\n", who_am_i);
        close(i2c_fd);
        return -1;
    }

    // Configure accelerometer
    if (i2c_write_byte(i2c_fd, CTRL_REG1, 0x57) < 0) return -1; // 50 Hz ODR, all axes enabled
    if (i2c_write_byte(i2c_fd, CTRL_REG4, 0x00) < 0) return -1; // +-2g full-scale
    if (i2c_write_byte(i2c_fd, INT1_CFG, 0x2A) < 0) return -1; // Any-axis high interrupt
    if (i2c_write_byte(i2c_fd, INT1_THS_L, THRESHOLD) < 0) return -1; // Threshold value
    if (i2c_write_byte(i2c_fd, INT1_DURATION, 0x00) < 0) return -1; // Duration 0

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        close(i2c_fd);
        return -1;
    }

    // Request GPIO line
    if (gpio_request_line(gpio_chip, INT1_GPIO_PIN) < 0) {
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return -1;
    }

    // Set GPIO line direction to input
    gpio_line = gpiod_chip_get_line(gpio_chip, INT1_GPIO_PIN);
    if (!gpio_line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return -1;
    }

    if (gpio_set_direction(gpio_line, GPIOD_LINE_REQUEST_DIRECTION_INPUT) < 0) {
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return -1;
    }

    // Set GPIO line edge to rising
    if (gpio_set_edge(gpio_line, GPIOD_LINE_REQUEST_EDGE_RISING) < 0) {
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    // Disable accelerometer
    if (i2c_fd >= 0) {
        i2c_write_byte(i2c_fd, CTRL_REG1, 0x00);
        close(i2c_fd);
    }

    // Release GPIO line
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }

    // Close GPIO chip
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize
    if (initialize() < 0) {
        cleanup();
        return 1;
    }

    printf("LSM303D monitor started. Press Ctrl-C to exit.\n");

    // Main loop
    while (program_running) {
        // Read accelerometer data
        int16_t x = (i2c_read_byte(i2c_fd, OUT_X_L_A + 0) | (i2c_read_byte(i2c_fd, OUT_X_L_A + 1) << 8));
        int16_t y = (i2c_read_byte(i2c_fd, OUT_X_L_A + 2) | (i2c_read_byte(i2c_fd, OUT_X_L_A + 3) << 8));
        int16_t z = (i2c_read_byte(i2c_fd, OUT_X_L_A + 4) | (i2c_read_byte(i2c_fd, OUT_X_L_A + 5) << 8));

        // Add data to circular buffer
        accelerometer_data_t data = {x, y, z};
        buffer_add(data);

        // Check for interrupt
        int value = gpio_get_value(gpio_line);
        if (value > 0) {
            print_buffer();
        }

        // Delay
        usleep(10000); // 10 ms
    }

    // Cleanup
    cleanup();

    return 0;
}

