#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

// Define GPIO pins
#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_line *solenoid1_line = NULL;
struct gpiod_line *solenoid2_line = NULL;
struct gpiod_chip *chip = NULL;

// Function prototypes
int set_gpio_output(struct gpiod_line *line, int value);
int set_gpio_low(struct gpiod_line *line);
int nanosleep_ms(int milliseconds);
void signal_handler(int signum);

// Function to set GPIO line value
int set_gpio_output(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO line value: %s\n", strerror(-ret));
        return -1;
    }
    return 0;
}

// Function to set GPIO line to LOW
int set_gpio_low(struct gpiod_line *line) {
    return set_gpio_output(line, 0);
}

// Function to sleep for a specified number of milliseconds
int nanosleep_ms(int milliseconds) {
    struct timespec req;
    req.tv_sec = milliseconds / 1000;
    req.tv_nsec = (milliseconds % 1000) * 1000000;
    return nanosleep(&req, NULL);
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signum);

        // De-energize solenoids
        if (solenoid1_line) {
            set_gpio_low(solenoid1_line);
        }
        if (solenoid2_line) {
            set_gpio_low(solenoid2_line);
        }

        // Release GPIO lines
        if (solenoid1_line) {
            gpiod_line_release(solenoid1_line);
        }
        if (solenoid2_line) {
            gpiod_line_release(solenoid2_line);
        }

        // Close GPIO chip
        if (chip) {
            gpiod_chip_close(chip);
        }

        exit(0);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get GPIO lines for solenoids
    solenoid1_line = gpiod_chip_get_line(chip, SOLENOID_1_PIN);
    if (!solenoid1_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", SOLENOID_1_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    solenoid2_line = gpiod_chip_get_line(chip, SOLENOID_2_PIN);
    if (!solenoid2_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", SOLENOID_2_PIN, strerror(errno));
        gpiod_line_release(solenoid1_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines as output
    if (gpiod_line_request_output(solenoid1_line, "solenoid1", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", SOLENOID_1_PIN, strerror(errno));
        gpiod_line_release(solenoid1_line);
        gpiod_line_release(solenoid2_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(solenoid2_line, "solenoid2", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", SOLENOID_2_PIN, strerror(errno));
        gpiod_line_release(solenoid1_line);
        gpiod_line_release(solenoid2_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // De-energize solenoids at startup
    set_gpio_low(solenoid1_line);
    set_gpio_low(solenoid2_line);

    // Main loop
