#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <signal.h>
#include <time.h>
#include <sys/select.h>
#include <pigpio.h>

// Define GPIO pins for the door locks
#define LOCK1_GPIO 17
#define LOCK2_GPIO 27

// Define the expected authentication code
#define EXPECTED_CODE "123456"

// Define the timeout duration in seconds
#define TIMEOUT_SECONDS 5

// Define the lock duration in seconds
#define LOCK_DURATION_SECONDS 2

// Global variables for serial port file descriptors
int serial0_fd = -1;
int serial1_fd = -1;

// Function prototypes
int initialize_pigpio();
int initialize_serial0();
int initialize_serial1();
int read_code(int fd, char *buffer, int timeout_seconds);
int authenticate_code(const char *code);
int control_lock(int gpio, int state);
void cleanup(int signum);

// Signal handler for clean shutdown
void cleanup(int signum) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signum);

    // Lock both doors
    control_lock(LOCK1_GPIO, 0);
    control_lock(LOCK2_GPIO, 0);

    // Close serial ports
    if (serial0_fd != -1) {
        close(serial0_fd);
    }
    if (serial1_fd != -1) {
        close(serial1_fd);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Function to initialize the pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO pins as outputs and initialize to LOW (locked)
    gpioSetMode(LOCK1_GPIO, PI_OUTPUT);
    gpioSetMode(LOCK2_GPIO, PI_OUTPUT);
    gpioWrite(LOCK1_GPIO, 0);
    gpioWrite(LOCK2_GPIO, 0);

    return 0;
}

// Function to initialize the primary serial port (UART0)
int initialize_serial0() {
    serial0_fd = open("/dev/serial0", O_RDWR | O_NOCTTY | O_NDELAY);
    if (serial0_fd == -1) {
        perror("Error opening /dev/serial0");
        return -1;
    }

    struct termios options;
    tcgetattr(serial0_fd, &options);
    options.c_cflag = B9600 | CS8 | CLOCAL | CREAD;
    options.c_iflag = IGNPAR;
    options.c_oflag = 0;
    options.c_lflag = 0;
    tcflush(serial0_fd, TCIFLUSH);
    tcsetattr(serial0_fd, TCSANOW, &options);

    return 0;
}

// Function to initialize the secondary serial port (UART1)
int initialize_serial1() {
    serial1_fd = open("/dev/serial1", O_RDWR | O_NOCTTY | O_NDELAY);
    if (serial1_fd == -1) {
        perror("Error opening /dev/serial1");
        return -1;
    }

    struct termios options;
    tcgetattr(serial1_fd, &options);
    options.c_cflag = B9600 | CS8 | CLOCAL | CREAD;
    options.c_iflag = IGNPAR;
    options.c_oflag = 0;
    options.c_lflag = 0;
    tcflush(serial1_fd, TCIFLUSH);
    tcsetattr(serial1_fd, TCSANOW, &options);

    return 0;
}

// Function to read a 6-digit code from the specified serial port with a timeout
int read_code(int fd, char *buffer, int timeout_seconds) {
    fd_set readfds;
    struct timeval timeout;
    int ret;

    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);

    timeout.tv_sec = timeout_seconds;
    timeout.tv_usec = 0;

    ret = select(fd + 1, &readfds, NULL, NULL, &timeout);

    if (ret == -1) {
        perror("select() error");
        return -1;
    } else if (ret == 0) {
        fprintf(stderr, "Timeout reading from serial port\n");
        return -1; // Timeout
    } else {
        int i = 0;
        while (i < 6) {
            char c;
            ssize_t bytes_read = read(fd, &c, 1);
            if (bytes_read == -1) {
                perror("read() error");
                return -1;
            } else if (bytes_read == 0) {
                // No data available, but select() returned, so it's not an error
                break;
            }

            if (c >= '0' && c <= '9') {
                buffer[i++] = c;
            } else {
                fprintf(stderr, "Non-digit character received, resetting buffer\n");
                i = 0; // Reset buffer on non-digit characters
            }
        }
        buffer[i] = '\0'; // Null-terminate the string
        return 0;
    }
}

// Function to authenticate the received code against the expected code
int authenticate_code(const char *code) {
    if (strcmp(code, EXPECTED_CODE) == 0) {
        return 0; // Authentication successful
    } else {
        return -1; // Authentication failed
    }
}

// Function to control the state of a door lock (GPIO pin)
int control_lock(int gpio, int state) {
    if (gpioWrite(gpio, state) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

int main() {
    // Install signal handlers for clean shutdown
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize serial ports
    if (initialize_serial0() != 0) {
        gpioTerminate();
        return 1;
    }
    if (initialize_serial1() != 0) {
        close(serial0_fd);
        gpioTerminate();
        return 1;
    }

    char code0[7] = {0}; // Buffer for code from serial0
    char code1[7] = {0}; // Buffer for code from serial1
    time_t start_time0, start_time1;

    fprintf(stderr, "Dual-factor authentication system started\n");

    while (1) {
        // Read code from serial0
        if (serial0_fd != -1) {
            time(&start_time0);
            if (read_code(serial0_fd, code0, TIMEOUT_SECONDS) == 0) {
                fprintf(stderr, "Received code from serial0: %s\n", code0);
            }
        }

        // Read code from serial1
        if (serial1_fd != -1) {
            time(&start_time1);
            if (read_code(serial1_fd, code1, TIMEOUT_SECONDS) == 0) {
                fprintf(stderr, "Received code from serial1: %s\n", code1);
            }
        }

        // Check if both codes have been received and are valid
        if (strlen(code0) == 6 && strlen(code1) == 6) {
            if (authenticate_code(code0) == 0 && authenticate_code(code1) == 0) {
                if (strcmp(code0, code1) == 0) {
                    fprintf(stderr, "Authentication successful!\n");

                    // Unlock both doors
                    if (control_lock(LOCK1_GPIO, 1) == 0 && control_lock(LOCK2_GPIO, 1) == 0) {
                        sleep(LOCK_DURATION_SECONDS);

                        // Lock both doors
                        if (control_lock(LOCK1_GPIO, 0) == 0 && control_lock(LOCK2_GPIO, 0) == 0) {
                            fprintf(stderr, "Doors locked.\n");
                        } else {
                            fprintf(stderr, "Error locking doors.\n");
                        }
                    } else {
                        fprintf(stderr, "Error unlocking doors.\n");
                    }

                    // Reset buffers
                    memset(code0, 0, sizeof(code0));
                    memset(code1, 0, sizeof(code1));
                } else {
                    fprintf(stderr, "Codes do not match.\n");
                }
            } else {
                fprintf(stderr, "Invalid code received.\n");
            }
        }

        // Reset buffers if timeout occurs
        if (serial0_fd != -1 && strlen(code0) == 6 && (time(NULL) - start_time0) > TIMEOUT_SECONDS) {
            fprintf(stderr, "Timeout on serial0, resetting buffer.\n");
            memset(code0, 0, sizeof(code0));
        }
        if (serial1_fd != -1 && strlen(code1) == 6 && (time(NULL) - start_time1) > TIMEOUT_SECONDS) {
            fprintf(stderr, "Timeout on serial1, resetting buffer.\n");
            memset(code1, 0, sizeof(code1));
        }

        usleep(100000); // Sleep for 100ms to reduce CPU usage
    }

    return 0;
}

