#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define PIR_PIN 4
#define RELAY_PIN 17

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define relay activation duration (in seconds)
#define RELAY_DURATION 1

// Define failsafe timeout (in seconds)
#define FAILSAFE_TIMEOUT 10

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *pir_line = NULL;
static struct gpiod_line *relay_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio(void);
int read_pir_sensor(void);
int control_relay(int state);
void failsafe_procedure(void);
void log_message(int priority, const char *message);
void signal_handler(int sig);
void cleanup_gpio(void);

// Function to initialize GPIO lines
int initialize_gpio(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        log_message(LOG_ERR, "Failed to open GPIO chip");
        return -1;
    }

    // Get PIR sensor line
    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        log_message(LOG_ERR, "Failed to get PIR sensor line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Request PIR sensor line as input
    ret = gpiod_line_request_input(pir_line, "motion_detector");
    if (ret < 0) {
        log_message(LOG_ERR, "Failed to request PIR sensor line as input");
        gpiod_chip_close(chip);
        return -1;
    }

    // Get relay line
    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        log_message(LOG_ERR, "Failed to get relay line");
        gpiod_line_release(pir_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request relay line as output
    ret = gpiod_line_request_output(relay_line, "motion_detector", 0);
    if (ret < 0) {
        log_message(LOG_ERR, "Failed to request relay line as output");
        gpiod_line_release(pir_line);
        gpiod_chip_close(chip);
        return -1;
    }

    log_message(LOG_INFO, "GPIO initialization complete");
    return 0;
}

// Function to read the PIR sensor value
int read_pir_sensor(void) {
    int value = gpiod_line_get_value(pir_line);
    if (value < 0) {
        log_message(LOG_ERR, "Failed to read PIR sensor value");
        return -1;
    }
    return value;
}

// Function to control the relay
int control_relay(int state) {
    int ret = gpiod_line_set_value(relay_line, state);
    if (ret < 0) {
        log_message(LOG_ERR, "Failed to set relay state");
        return -1;
    }
    return 0;
}

// Function to handle failsafe procedure
void failsafe_procedure(void) {
    log_message(LOG_WARNING, "Failsafe triggered: PIR sensor stuck HIGH");
    control_relay(0); // De-energize the relay
}

// Function to log messages to syslog
