#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <unistd.h>
#include <time.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define the number of relays
#define NUM_RELAYS 4

// Define the activation and deactivation durations (in seconds)
#define ACTIVATION_DURATION 300
#define DEACTIVATION_DURATION 60

// Define the timer interval (in seconds)
#define TIMER_INTERVAL 60

// Define the number of actions in the sequence
#define NUM_ACTIONS (NUM_RELAYS * 2 + (NUM_RELAYS - 1))

// Define the action types
typedef enum {
    RELAY_ON,
    RELAY_OFF,
    PAUSE
} action_type_t;

// Define the action structure
typedef struct {
    action_type_t type;
    int relay_num;
} action_t;

// Global variables
volatile sig_atomic_t running = 1; // Flag to control the main loop
int current_relay = 0; // Current relay being activated
int current_action_index = 0; // Current action index in the sequence

// Action sequence
action_t action_sequence[NUM_ACTIONS];

// Function prototypes
void initialize_gpio();
void initialize_action_sequence();
void activate_relay(int relay_num);
void deactivate_relay(int relay_num);
void timer_callback(int timer_id, void *user_data);
void signal_handler(int signal);
void log_message(int priority, const char *message);

int main() {
    // Open syslog
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Initialize GPIO pins
    initialize_gpio();

    // Initialize the action sequence
    initialize_action_sequence();

    // Set up signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up the timer callback function
    gpioSetTimerFuncEx(0, TIMER_INTERVAL * 1000, timer_callback, NULL);

    // Main loop
    while (running) {
        sleep(1); // Sleep for 1 second
    }

    // Clean up and exit
    gpioTerminate();
    closelog();
    return 0;
}

// Function to initialize the GPIO pins
void initialize_gpio() {
    // Set the GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Initialize all relays to OFF (HIGH)
    gpioWrite(RELAY1_PIN, 1);
    gpioWrite(RELAY2_PIN, 1);
    gpioWrite(RELAY3_PIN, 1);
    gpioWrite(RELAY4_PIN, 1);

    log_message(LOG_INFO, "GPIO pins initialized");
}

// Function to initialize the action sequence
void initialize_action_sequence() {
    int i;

    // Relay activation/deactivation sequence
    for (i = 0; i < NUM_RELAYS; i++) {
        action_sequence[i].type = RELAY_ON;
        action_sequence[i].relay_num = i + 1;
    }
    for (i = 0; i < NUM_RELAYS; i++) {
        action_sequence[NUM_RELAYS + i].type = RELAY_OFF;
        action_sequence[NUM_RELAYS + i].relay_num = i + 1;
    }

    // Pause sequence
    for (i = 0; i < NUM_RELAYS - 1; i++) {
        action_sequence[NUM_RELAYS * 2 + i].type = PAUSE;
        action_sequence[NUM_RELAYS * 2 + i].relay_num = 0; // Pause has no relay number
    }

    log_message(LOG_INFO, "Action sequence initialized");
}

// Function to activate a relay
void activate_relay(int relay_num) {
    int pin;

    switch (relay_num) {
        case 1:
            pin = RELAY1_PIN;
            break;
        case 2:
            pin = RELAY2_PIN;
            break;
        case 3:
            pin = RELAY3_PIN;
            break;
        case 4:
            pin = RELAY4_PIN;
            break;
        default:
            log_message(LOG_ERR, "Invalid relay number");
            return;
    }

    gpioWrite(pin, 0); // Activate the relay (active-LOW)
    char message[100];
    snprintf(message, sizeof(message), "Relay %d activated", relay_num);
    log_message(LOG_INFO, message);
}

// Function to deactivate a relay
void deactivate_relay(int relay_num) {
    int pin;

    switch (relay_num) {
        case 1:
            pin = RELAY1_PIN;
            break;
        case 2:
            pin = RELAY2_PIN;
            break;
        case 3:
            pin = RELAY3_PIN;
            break;
        case 4:
            pin = RELAY4_PIN;
            break;
        default:
            log_message(LOG_ERR, "Invalid relay number");
            return;
    }

    gpioWrite(pin, 1); // Deactivate the relay (active-LOW)
    char message[100];
    snprintf(message, sizeof(message), "Relay %d deactivated", relay_num);
    log_message(LOG_INFO, message);
}

// Timer callback function
void timer_callback(int timer_id, void *user_data) {
    static int current_action_index = 0; // Static variable to keep track of the current action index

    if (current_action_index < NUM_ACTIONS) {
        action_t current_action = action_sequence[current_action_index];

        switch (current_action.type) {
            case RELAY_ON:
                activate_relay(current_action.relay_num);
                current_relay = current_action.relay_num;
                break;
            case RELAY_OFF:
                deactivate_relay(current_action.relay_num);
                break;
            case PAUSE:
                // No action needed for pause, just log it
                log_message(LOG_INFO, "Pause");
                break;
        }

        current_action_index++;
    } else {
        // Reset the action index to the beginning of the sequence
        current_action_index = 0;
    }
}

// Signal handler function
void signal_handler(int signal) {
    char message[50];
    snprintf(message, sizeof(message), "Received signal %d, shutting down...", signal);
    log_message(LOG_INFO, message);

    // Deactivate all relays
    deactivate_relay(1);
    deactivate_relay(2);
    deactivate_relay(3);
    deactivate_relay(4);

    // Set the running flag to 0 to exit the main loop
    running = 0;

    // Terminate pigpio
    gpioTerminate();

    // Close syslog
    closelog();

    // Exit the program
    exit(0);
}

// Function to log messages to syslog
void log_message(int priority, const char *message) {
    time_t now;
    struct tm *timeinfo;
    char timestamp[20];

    time(&now);
    timeinfo = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    char log_message[200];
    snprintf(log_message, sizeof(log_message), "%s: %s", timestamp, message);
    syslog(priority, "%s", log_message);
}

