#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <syslog.h>
#include <string.h>
#include <errno.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define ACCEL_XOUT_H 0x3B

// Circular buffer size
#define BUFFER_SIZE 100

// Sampling rate (Hz)
#define SAMPLE_RATE 100

// I2C device path
#define I2C_DEVICE "/dev/i2c-1"

// Sysfs paths
#define SYSFS_DIR "/sys/kernel/mpu6050_accel"
#define SYSFS_LATEST "latest"
#define SYSFS_DATA "data"

// Global variables
static int i2c_fd = -1;
static int timer_fd = -1;
static volatile sig_atomic_t running = 1;

// Circular buffer structure
typedef struct {
    float x[BUFFER_SIZE];
    float y[BUFFER_SIZE];
    float z[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

static circular_buffer_t accel_buffer;

// Function prototypes
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len);
int mpu6050_init(int fd);
int read_acceleration(int fd, float *x, float *y, float *z);
void timer_handler(int signum);
void signal_handler(int signum);
int create_sysfs_files();
int write_latest_data(float x, float y, float z);
int write_circular_buffer_to_file();

// I2C write function
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        syslog(LOG_ERR, "I2C write failed: %s", strerror(errno));
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        syslog(LOG_ERR, "I2C write (register select) failed: %s", strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        syslog(LOG_ERR, "I2C read failed: %s", strerror(errno));
        return -1;
    }
    return 0;
}

// MPU6050 initialization function
int mpu6050_init(int fd) {
    // Wake up the MPU6050
    if (i2c_write_byte(fd, PWR_MGMT_1, 0x00) != 0) {
        syslog(LOG_ERR, "Failed to wake up MPU6050");
        return -1;
    }

    // Set accelerometer range to +-2g
