// Define GPIO chip and line numbers
#define GPIOCHIP "gpiochip0"
#define GPIO18 18
#define GPIO23 23
#define GPIO24 24
#define GPIO25 25

// Prime numbers for timing intervals (seconds)
#define PRIME1 2
#define PRIME2 3
#define PRIME3 5
#define PRIME4 7

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line18, *line23, *line24, *line25;

// Function prototypes
int gpio_init(void);
int set_gpio_output(struct gpiod_line *line);
int set_gpio_value(struct gpiod_line *line, int value);
int toggle_gpio(struct gpiod_line *line, int prime_number);
void cleanup_gpio(void);
void signal_handler(int signum);

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("\nCaught signal %d, cleaning up and exiting...\n", signum);
        cleanup_gpio();
        exit(0);
    }
}

// Initialize GPIO lines
int gpio_init(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get GPIO lines
    line18 = gpiod_chip_get_line(chip, GPIO18);
    line23 = gpiod_chip_get_line(chip, GPIO23);
    line24 = gpiod_chip_get_line(chip, GPIO24);
    line25 = gpiod_chip_get_line(chip, GPIO25);

    if (!line18 || !line23 || !line24 || !line25) {
        perror("Error getting GPIO line");
        cleanup_gpio();
        return -1;
    }

    // Request GPIO lines for output
    ret = gpiod_line_request_output(line18, "relay18", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 18");
        cleanup_gpio();
        return -1;
    }

    ret = gpiod_line_request_output(line23, "relay23", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 23");
        cleanup_gpio();
        return -1;
    }

    ret = gpiod_line_request_output(line24, "relay24", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 24");
        cleanup_gpio();
        return -1;
    }

    ret = gpiod_line_request_output(line25, "relay25", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line 25");
        cleanup_gpio();
        return -1;
    }

    return 0;
}

// Set GPIO line to output mode
int set_gpio_output(struct gpiod_line *line) {
    int ret;
    ret = gpiod_line_request_output(line, "relay", 0);
    if (ret < 0) {
        perror("Error setting GPIO line to output");
        return -1;
    }
    return 0;
}

