        return -1;
    }

    int new_value = !current_value;

    if (set_gpio_value(line, new_value) < 0) {
        return -1;
    }

    struct timespec sleep_time;
    sleep_time.tv_sec = prime_number;
    sleep_time.tv_nsec = 0;
