#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define RELAY_PIN 27

// Define constants
#define ALARM_DURATION 3 // seconds
#define DEBOUNCE_DELAY 5 // seconds

// Global variables
static volatile int running = 1;
static volatile int alarm_active = 0;
static time_t last_alarm_time = 0;

// Function prototypes
int initialize_gpio();
int read_sound_sensor();
void activate_alarm();
void log_alarm_event();
void cleanup_gpio();
void signal_handler(int signal);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Ensure relay is initially off

    return 0; // Indicate success
}

// Function to read the sound sensor
int read_sound_sensor() {
    return gpioRead(SOUND_SENSOR_PIN);
}

// Function to activate the alarm (relay)
void activate_alarm() {
    if (alarm_active) return; // Debounce: Do nothing if already active

    alarm_active = 1;
    gpioWrite(RELAY_PIN, 1); // Turn on relay
    printf("Alarm activated!\n");
    log_alarm_event();

    gpioDelay(ALARM_DURATION * 1000000); // Wait for alarm duration (microseconds)

    gpioWrite(RELAY_PIN, 0); // Turn off relay
    alarm_active = 0;
    printf("Alarm deactivated.\n");
}

// Function to log alarm events to a file
void log_alarm_event() {
    FILE *fp = fopen("alarm_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening alarm_log.txt for writing\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s: Alarm triggered\n", s);
    fclose(fp);
}

// Function to cleanup GPIO pins and terminate pigpio
void cleanup_gpio() {
    printf("Cleaning up and exiting...\n");
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off
    gpioTerminate();
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    cleanup_gpio();
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int sound_detected = read_sound_sensor();

        if (sound_detected == 1) {
            time_t current_time = time(NULL);
            if (difftime(current_time, last_alarm_time) >= DEBOUNCE_DELAY) {
                activate_alarm();
                last_alarm_time = current_time;
            }
        }

        gpioDelay(100000); // Poll every 100ms (microseconds)
    }

    return 0;
}

