#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Configuration
#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define GYRO_XOUT_H 0x43
#define WHO_AM_I 0x75
#define PWR_MGMT_1 0x6B
#define SAMPLE_RATE_HZ 100
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)
#define GYRO_SENSITIVITY 131.0 // LSB/deg/s
#define THRESHOLD 50.0          // degrees/second
#define BUFFER_SIZE 100

// Data structure for gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Circular buffer structure
typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global variables
int i2c_fd;
circular_buffer_t gyro_buffer;
bool running = true;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int init_mpu6050(int fd);
int read_gyro_data(int fd, gyro_data_t *data);
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data);
gyro_data_t get_latest_data(circular_buffer_t *buffer);
float calculate_magnitude(gyro_data_t data);
void check_threshold(gyro_data_t data, void (*callback)(gyro_data_t));
void threshold_exceeded_callback(gyro_data_t data);
void signal_handler(int signal);
void init_circular_buffer(circular_buffer_t *buffer);

// I2C read function
int i2c_read_reg(int fd, uint8_t reg) {
    uint8_t buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }
    if (read(fd, buf, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return buf[0];
}

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// MPU-6050 initialization function
int init_mpu6050(int fd) {
    // Wake up the MPU-6050
    if (i2c_write_reg(fd, PWR_MGMT_1, 0) != 0) {
        fprintf(stderr, "Failed to wake up MPU-6050\n");
        return -1;
    }

    // Verify device ID
    int who_am_i = i2c_read_reg(fd, WHO_AM_I);
    if (who_am_i != MPU6050_ADDR) {
        fprintf(stderr, "MPU-6050 not found. WHO_AM_I returned 0x%x\n", who_am_i);
        return -1;
    }

    printf("MPU-6050 initialized successfully\n");
    return 0;
}

// Read gyroscope data function
int read_gyro_data(int fd, gyro_data_t *data) {
    uint8_t buf[6];
    uint8_t reg = GYRO_XOUT_H;

    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }

    if (read(fd, buf, 6) != 6) {
        perror("I2C read failed");
        return -1;
    }

    // Combine high and low bytes, convert to degrees/second
    data->x = (float)((int16_t)((buf[0] << 8) | buf[1])) / GYRO_SENSITIVITY;
    data->y = (float)((int16_t)((buf[2] << 8) | buf[3])) / GYRO_SENSITIVITY;
    data->z = (float)((int16_t)((buf[4] << 8) | buf[5])) / GYRO_SENSITIVITY;

    return 0;
}

// Initialize circular buffer
void init_circular_buffer(circular_buffer_t *buffer) {
    buffer->head = 0;
    buffer->count = 0;
}

// Add data to circular buffer
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Get latest data from circular buffer
gyro_data_t get_latest_data(circular_buffer_t *buffer) {
    if (buffer->count > 0) {
        int index = (buffer->head - 1 + BUFFER_SIZE) % BUFFER_SIZE;
        return buffer->data[index];
    } else {
        // Return zeroed data if buffer is empty
        gyro_data_t zero_data = {0.0, 0.0, 0.0};
        return zero_data;
    }
}

// Calculate magnitude of gyroscope data
float calculate_magnitude(gyro_data_t data) {
    return sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
}

// Threshold exceeded callback function
void threshold_exceeded_callback(gyro_data_t data) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

    printf("%s - Threshold exceeded! X: %.2f, Y: %.2f, Z: %.2f\n", buf, data.x, data.y, data.z);
}

// Check threshold and call callback if exceeded
void check_threshold(gyro_data_t data, void (*callback)(gyro_data_t)) {
    float magnitude = calculate_magnitude(data);
    if (magnitude > THRESHOLD) {
        callback(data);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = false;
}

int main() {
    // Initialize circular buffer
    init_circular_buffer(&gyro_buffer);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050(i2c_fd) != 0) {
        fprintf(stderr, "MPU-6050 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    gyro_data_t gyro_data;

    // Main loop
    while (running) {
        // Read gyroscope data
        if (read_gyro_data(i2c_fd, &gyro_data) == 0) {
            // Add data to circular buffer
            add_to_buffer(&gyro_buffer, gyro_data);

            // Check threshold
            check_threshold(gyro_data, threshold_exceeded_callback);
        } else {
            fprintf(stderr, "Failed to read gyroscope data\n");
        }

        // Delay for sample period
        usleep(SAMPLE_PERIOD_US);
    }

    // Close I2C bus
    close(i2c_fd);

    printf("Program finished\n");
    return 0;
}

