        gyro_data_t zero_data = {0.0, 0.0, 0.0};
        return zero_data;
    }
}

// Calculate magnitude of gyroscope data
float calculate_magnitude(gyro_data_t data) {
    return sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
}

// Threshold exceeded callback function
void threshold_exceeded_callback(gyro_data_t data) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

    printf("%s - Threshold exceeded! X: %.2f, Y: %.2f, Z: %.2f\n", buf, data.x, data.y, data.z);
}

// Check threshold and call callback if exceeded
void check_threshold(gyro_data_t data, void (*callback)(gyro_data_t)) {
    float magnitude = calculate_magnitude(data);
    if (magnitude > THRESHOLD) {
        callback(data);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = false;
}

int main() {
    // Initialize circular buffer
    init_circular_buffer(&gyro_buffer);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050(i2c_fd) != 0) {
        fprintf(stderr, "MPU-6050 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    gyro_data_t gyro_data;

    // Main loop
    while (running) {
        // Read gyroscope data
        if (read_gyro_data(i2c_fd, &gyro_data) == 0) {
            // Add data to circular buffer
            add_to_buffer(&gyro_buffer, gyro_data);

            // Check threshold
            check_threshold(gyro_data, threshold_exceeded_callback);
        } else {
            fprintf(stderr, "Failed to read gyroscope data\n");
        }

        // Delay for sample period
        usleep(SAMPLE_PERIOD_US);
    }

    // Close I2C bus
    close(i2c_fd);

    printf("Program finished\n");
    return 0;
}

