#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE 9600
#define READ_COMMAND {0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x79}
#define CHECKSUM_ERROR -1
#define TIMEOUT_ERROR -2
#define INVALID_DATA_ERROR -3
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define LOG_FILE "co2_log.json"
#define ERROR_LOG_FILE "co2_error.log"

// Global variables
int uart_handle = -1;
FILE *log_file = NULL;
FILE *error_log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_co2(int uart_handle, int *co2_ppm);
int validate_checksum(unsigned char *data, int len);
int write_log(FILE *fp, int co2_ppm, int error);
void signal_handler(int signal);
int log_error(const char *message);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Function to log errors
int log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(error_log_file, "%s: %s\n", timestamp, message);
    fflush(error_log_file);
    return 0;
}

// Function to read CO2 concentration from the sensor
int read_co2(int uart_handle, int *co2_ppm) {
    unsigned char read_command[] = READ_COMMAND;
    unsigned char response[9];
    int bytes_read;
    int retries = 0;
    time_t start_time;

    // Send the read command
    if (serWrite(uart_handle, read_command, sizeof(read_command)) != sizeof(read_command)) {
        log_error("Failed to write read command to UART.");
        return INVALID_DATA_ERROR;
    }

    // Wait for data to be available with timeout
    start_time = time(NULL);
    while (serDataAvailable(uart_handle) < 9 && (time(NULL) - start_time) < 1) {
        gpioDelay(1000); // Wait 1 ms
    }

    if (serDataAvailable(uart_handle) < 9) {
        log_error("Timeout waiting for data from UART.");
        return TIMEOUT_ERROR;
    }

    // Read the response
    bytes_read = serRead(uart_handle, response, sizeof(response));

    if (bytes_read != sizeof(response)) {
        char error_message[100];
        snprintf(error_message, sizeof(error_message), "Failed to read all bytes from UART. Read %d bytes.", bytes_read);
        log_error(error_message);
        return INVALID_DATA_ERROR;
    }

    // Validate the checksum
    if (validate_checksum(response, 8) != 0) {
        log_error("Checksum validation failed.");
        return CHECKSUM_ERROR;
    }

    // Extract CO2 concentration
    *co2_ppm = (response[2] << 8) | response[3];

    return 0;
}

// Function to validate the checksum
int validate_checksum(unsigned char *data, int len) {
    unsigned char checksum = 0;
    for (int i = 1; i < len; i++) {
        checksum += data[i];
    }
    checksum = ~checksum + 1; // Invert and increment

    if (checksum != data[len]) {
        return CHECKSUM_ERROR;
    }

    return 0;
}

// Function to write log entry
int write_log(FILE *fp, int co2_ppm, int error) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[50];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

    fprintf(fp, "{\"timestamp\": \"%s.%06ld\", \"co2_ppm\": %d, \"error\": %d}\n", timestamp, ts.tv_nsec / 1000, co2_ppm, error);
    fflush(fp);

    // Print to stdout as well
    printf("{\"timestamp\": \"%s.%06ld\", \"co2_ppm\": %d, \"error\": %d}\n", timestamp, ts.tv_nsec / 1000, co2_ppm, error);

    return 0;
}

int main() {
    int co2_ppm;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open error log file
    error_log_file = fopen(ERROR_LOG_FILE, "a");
    if (error_log_file == NULL) {
        perror("Failed to open error log file");
        gpioTerminate();
        return 1;
    }

    // Open UART
    uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0); // 0 for default flags
    if (uart_handle < 0) {
        log_error("Failed to open UART.");
        fclose(error_log_file);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        log_error("Failed to open log file.");
        serClose(uart_handle);
        fclose(error_log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        result = read_co2(uart_handle, &co2_ppm);

        if (result == 0) {
            write_log(log_file, co2_ppm, 0);
        } else {
            write_log(log_file, 0, result);
        }

        gpioDelay(5000000); // 5 seconds
    }

    // Cleanup
    serClose(uart_handle);
    fclose(log_file);
    fclose(error_log_file);
    gpioTerminate();

    return 0;
}

