#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <math.h>
#include <string.h>

// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L register addresses
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Z_LSB 0x06
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_DATA_Y_LSB 0x08

// GPIO pin for output
#define GPIO_PIN 17

// Hard-iron offsets
#define HARD_IRON_X 100.0
#define HARD_IRON_Y -50.0

// Target heading
#define TARGET_HEADING 90.0

// Deviation threshold
#define DEVIATION_THRESHOLD 10.0

// Circular buffer size
#define BUFFER_SIZE 100

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float heading_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int initialize_hmc5883l();
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z);
float calculate_heading(int16_t x, int16_t y);
void compensate_heading(float *heading);
void set_gpio_output(int state);
void add_to_buffer(float heading);
void print_buffer();
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize HMC5883L
int initialize_hmc5883l() {
    // Configure CONFIG_A (0x00)
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to CONFIG_A register\n");
        return -1;
    }

    // Configure CONFIG_B (0x01)
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0x20) < 0) {
        fprintf(stderr, "Error writing to CONFIG_B register\n");
        return -1;
    }

    // Configure MODE (0x02)
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing to MODE register\n");
        return -1;
    }

    return 0;
}

// Read magnetometer data
int read_magnetometer_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, buffer, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *z = (int16_t)((buffer[2] << 8) | buffer[3]);
    *y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Calculate heading in degrees
float calculate_heading(int16_t x, int16_t y) {
    float heading = atan2(y, x) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }
    return heading;
}

// Compensate heading for hard-iron distortion
void compensate_heading(float *heading) {
    *heading -= HARD_IRON_X;
    *heading -= HARD_IRON_Y;
}

// Set GPIO output
void set_gpio_output(int state) {
    gpioWrite(GPIO_PIN, state);
}

// Add heading to circular buffer
void add_to_buffer(float heading) {
    heading_buffer[buffer_index] = heading;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Print circular buffer (for debugging)
void print_buffer() {
    printf("Heading buffer: ");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        printf("%f ", heading_buffer[i]);
    }
    printf("\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize HMC5883L
    if (initialize_hmc5883l() < 0) {
        fprintf(stderr, "HMC5883L initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;
    float heading;

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        if (read_magnetometer_data(&x, &y, &z) == 0) {
            // Calculate heading
            heading = calculate_heading(x, y);

            // Compensate heading
            compensate_heading(&heading);

            // Add heading to buffer
            add_to_buffer(heading);

            // Set GPIO output based on deviation from target heading
            if (fabs(heading - TARGET_HEADING) > DEVIATION_THRESHOLD) {
                set_gpio_output(1); // High
            } else {
                set_gpio_output(0); // Low
            }

            // Print heading (for debugging)
            printf("Heading: %f\n", heading);
        } else {
            fprintf(stderr, "Error reading magnetometer data, retrying...\n");
            // Attempt to re-initialize I2C
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus\n");
                terminate = 1; // Exit if re-initialization fails
            } else {
                if (initialize_hmc5883l() < 0) {
                    fprintf(stderr, "HMC5883L re-initialisation failed\n");
                    terminate = 1;
                }
            }
        }

        // Delay for 100 ms
        gpioDelay(100000); // 100 ms
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

