    if (initialize_hmc5883l() < 0) {
        fprintf(stderr, "HMC5883L initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;
    float heading;

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        if (read_magnetometer_data(&x, &y, &z) == 0) {
            // Calculate heading
            heading = calculate_heading(x, y);

            // Compensate heading
            compensate_heading(&heading);

            // Add heading to buffer
            add_to_buffer(heading);

            // Set GPIO output based on deviation from target heading
            if (fabs(heading - TARGET_HEADING) > DEVIATION_THRESHOLD) {
                set_gpio_output(1); // High
            } else {
                set_gpio_output(0); // Low
            }

            // Print heading (for debugging)
            printf("Heading: %f\n", heading);
        } else {
            fprintf(stderr, "Error reading magnetometer data, retrying...\n");
            // Attempt to re-initialize I2C
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus\n");
                terminate = 1; // Exit if re-initialization fails
            } else {
                if (initialize_hmc5883l() < 0) {
                    fprintf(stderr, "HMC5883L re-initialisation failed\n");
                    terminate = 1;
                }
            }
        }

        // Delay for 100 ms
        gpioDelay(100000); // 100 ms
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

