#define LUX_THRESHOLD_GREEN 150.0
#define LUX_THRESHOLD_BLUE 300.0

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *red_line = NULL;
static struct gpiod_line *green_line = NULL;
static struct gpiod_line *blue_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(const char *bus);
int init_gpio(int pin, const char *chipname);
int read_bh1750(int fd);
float calculate_lux(uint16_t raw_value);
void control_relays(float lux);
void log_data(float lux, int red_state, int green_state, int blue_state);
void signal_handler(int sig);
void cleanup();

// I2C initialization function
int init_i2c(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// GPIO initialization function
int init_gpio(int pin, const char *chipname) {
    struct gpiod_line *line;
    struct gpiod_chip *chip = gpiod_chip_open_by_name(chipname);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(line, "lighting_system", 0) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// BH1750 sensor reading function
int read_bh1750(int fd) {
    uint8_t config_cmd = 0x10; // Continuous high-resolution mode
    uint8_t buffer[2];
    int retries = 3;

    if (write(fd, &config_cmd, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    usleep(120000); // Wait for at least 120ms

    while (retries > 0) {
        if (read(fd, buffer, 2) == 2) {
            return (buffer[0] << 8) | buffer[1];
        } else {
            perror("Error reading from I2C device");
            retries--;
            usleep(10000); // Wait before retrying
        }
    }

    fprintf(stderr, "Failed to read BH1750 after multiple retries.\n");
    return -1;
}

// Lux calculation function
float calculate_lux(uint16_t raw_value) {
    return (float)raw_value / 1.2;
}

// Relay control function
void control_relays(float lux) {
    int red_state = 0;
    int green_state = 0;
    int blue_state = 0;

    if (lux < LUX_THRESHOLD_RED) {
        red_state = 1;
    } else if (lux < LUX_THRESHOLD_GREEN) {
        green_state = 1;
    } else if (lux < LUX_THRESHOLD_BLUE) {
        blue_state = 1;
    } else {
        red_state = 1;
        green_state = 1;
        blue_state = 1;
    }

    if (red_state) {
        if (gpiod_line_set_value(red_line, 1) < 0) {
            perror("Error setting RED relay state");
        }
    } else {
        if (gpiod_line_set_value(red_line, 0) < 0) {
            perror("Error setting RED relay state");
        }
    }

    if (green_state) {
        if (gpiod_line_set_value(green_line, 1) < 0) {
            perror("Error setting GREEN relay state");
        }
    } else {
        if (gpiod_line_set_value(green_line, 0) < 0) {
            perror("Error setting GREEN relay state");
        }
    }

    if (blue_state) {
        if (gpiod_line_set_value(blue_line, 1) < 0) {
            perror("Error setting BLUE relay state");
        }
    } else {
        if (gpiod_line_set_value(blue_line, 0) < 0) {
            perror("Error setting BLUE relay state");
        }
    }
}

// Data logging function
void log_data(float lux, int red_state, int green_state, int blue_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

