    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (red_line) {
        gpiod_line_set_value(red_line, 0); // Turn off relay
        gpiod_line_release(red_line);
    }
    if (green_line) {
        gpiod_line_set_value(green_line, 0); // Turn off relay
        gpiod_line_release(green_line);
    }
    if (blue_line) {
        gpiod_line_set_value(blue_line, 0); // Turn off relay
        gpiod_line_release(blue_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
