        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int raw_value = read_bh1750(i2c_fd);
        if (raw_value < 0) {
            fprintf(stderr, "Error reading BH1750 sensor. Retrying in 1 second.\n");
            sleep(1);
            continue;
        }

        float lux = calculate_lux((uint16_t)raw_value);
        control_relays(lux);
        int red_state = gpiod_line_get_value(red_line);
        int green_state = gpiod_line_get_value(green_line);
