#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Motor A GPIO pins
#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18

// Motor B GPIO pins
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

// PWM frequency
#define PWM_FREQUENCY 1000

// Distance range
#define MIN_DISTANCE 10
#define MAX_DISTANCE 100

// Global flag for program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, stopping motors and exiting...\n");
}

// Function to map distance to PWM duty cycle
int distance_to_duty_cycle(int distance) {
    if (distance < MIN_DISTANCE) {
        return 255;
    } else if (distance > MAX_DISTANCE) {
        return 0;
    } else {
        return 255 - ((distance - MIN_DISTANCE) * 255 / (MAX_DISTANCE - MIN_DISTANCE));
    }
}

// Function to control motor A
void control_motor_a(int distance) {
    int duty_cycle = distance_to_duty_cycle(distance);

    if (distance < 50) {
        // Forward
        gpioWrite(MOTOR_A_IN1, 1);
        gpioWrite(MOTOR_A_IN2, 0);
        gpioPWM(MOTOR_A_IN2, duty_cycle);
    } else {
        // Backward
        gpioWrite(MOTOR_A_IN1, 0);
        gpioWrite(MOTOR_A_IN2, 1);
        gpioPWM(MOTOR_A_IN2, duty_cycle);
    }
}

// Function to control motor B
void control_motor_b(int distance) {
    int duty_cycle = distance_to_duty_cycle(distance);

    if (distance < 50) {
        // Forward
        gpioWrite(MOTOR_B_IN3, 1);
        gpioWrite(MOTOR_B_IN4, 0);
        gpioPWM(MOTOR_B_IN4, duty_cycle);
    } else {
        // Backward
        gpioWrite(MOTOR_B_IN3, 0);
        gpioWrite(MOTOR_B_IN4, 1);
        gpioPWM(MOTOR_B_IN4, duty_cycle);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR_A_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN4, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_A_IN2, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_B_IN4, PWM_FREQUENCY);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Simulate distance readings
        int distance_a = (rand() % (MAX_DISTANCE - MIN_DISTANCE + 1)) + MIN_DISTANCE;
        int distance_b = (rand() % (MAX_DISTANCE - MIN_DISTANCE + 1)) + MIN_DISTANCE;

        // Control motors
        control_motor_a(distance_a);
        control_motor_b(distance_b);

        // Print distance readings and duty cycles (for debugging)
        int duty_a = distance_to_duty_cycle(distance_a);
        int duty_b = distance_to_duty_cycle(distance_b);
        printf("Motor A: Distance = %d cm, Duty Cycle = %d\n", distance_a, duty_a);
        printf("Motor B: Distance = %d cm, Duty Cycle = %d\n", distance_b, duty_b);

        // Wait 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Stop motors
    gpioWrite(MOTOR_A_IN1, 0);
    gpioWrite(MOTOR_A_IN2, 0);
    gpioWrite(MOTOR_B_IN3, 0);
    gpioWrite(MOTOR_B_IN4, 0);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

