    int duty_cycle = distance_to_duty_cycle(distance);

    if (distance < 50) {
        // Forward
        gpioWrite(MOTOR_B_IN3, 1);
        gpioWrite(MOTOR_B_IN4, 0);
        gpioPWM(MOTOR_B_IN4, duty_cycle);
    } else {
        // Backward
        gpioWrite(MOTOR_B_IN3, 0);
        gpioWrite(MOTOR_B_IN4, 1);
        gpioPWM(MOTOR_B_IN4, duty_cycle);
    }
