    printf("Caught signal %d, cleaning up...\n", signal);
    program_running = 0;
    gpioWrite(MOTOR_PIN_1, 0);
    gpioWrite(MOTOR_PIN_2, 0);
    gpioWrite(MOTOR_PIN_3, 0);
    gpioWrite(MOTOR_PIN_4, 0);
    gpioTerminate();
    exit(0);
}

