    gpioSetMode(MOTOR_PIN_1, PI_OUTPUT);
    gpioSetMode(MOTOR_PIN_2, PI_OUTPUT);
    gpioSetMode(MOTOR_PIN_3, PI_OUTPUT);
    gpioSetMode(MOTOR_PIN_4, PI_OUTPUT);

    // Set GPIO modes for buttons with pull-up resistors
    gpioSetMode(LOCK_BUTTON, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON, PI_INPUT);
    gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP);

    // Set up interrupt handlers for button presses
    gpioSetAlertFunc(LOCK_BUTTON, button_callback);
    gpioSetAlertFunc(UNLOCK_BUTTON, button_callback);

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Automatic Door Lock System running. Press Ctrl+C to exit.\n");

    // Main loop (keep the program running until a signal is received)
    while (program_running) {
        sleep(1); // Reduce CPU usage
    }

    return 0;
}

