#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>

// Constants
#define MPU6050_ADDR 0x68
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H 0x43
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG 0x1B
#define SERVO_PIN 18
#define PWM_CHIP 2
#define PWM_NUM 0
#define PWM_PERIOD 20000 // 20ms
#define LOG_FILE "solar_tracker.log"
#define MAX_RETRIES 5
#define RETRY_DELAY_BASE_MS 10

// Global variables
static volatile sig_atomic_t keep_running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

// Function prototypes
int init_i2c(int addr);
int read_i2c_reg(int fd, int reg);
int write_i2c_reg(int fd, int reg, int val);
void init_mpu6050(int fd);
void read_accel_gyro_data(int fd, int *accel_x, int *accel_y, int *accel_z, int *gyro_x, int *gyro_y, int *gyro_z);
float calculate_pitch(int accel_x, int accel_y, int accel_z);
float calculate_roll(int accel_x, int accel_y, int accel_z);
int map_angle_to_servo_position(float angle);
void set_servo_position(int position);
void log_data(float pitch, float roll, int servo_position);
void signal_handler(int sig);
void cleanup();

// I2C initialization function
int init_i2c(int addr) {
    int fd = wiringPiI2CSetup(addr);
    if (fd == -1) {
        perror("Failed to initialize I2C");
        return -1;
    }
    return fd;
}

// I2C read function with retry and exponential backoff
int read_i2c_reg(int fd, int reg) {
    int result, retries = 0;
    while (retries < MAX_RETRIES) {
        result = wiringPiI2CReadReg8(fd, reg);
        if (result != -1) {
            return result;
        }
        fprintf(stderr, "I2C read error (reg 0x%02X), retrying (%d/%d)...\n", reg, retries + 1, MAX_RETRIES);
        retries++;
        usleep(RETRY_DELAY_BASE_MS * (1 << retries) * 1000); // Exponential backoff
    }
    fprintf(stderr, "I2C read failed after %d retries (reg 0x%02X)\n", MAX_RETRIES, reg);
    return -1; // Indicate failure
}

// I2C write function with retry and exponential backoff
int write_i2c_reg(int fd, int reg, int val) {
    int result, retries = 0;
    while (retries < MAX_RETRIES) {
        result = wiringPiI2CWriteReg8(fd, reg, val);
        if (result != -1) {
            return 0; // Success
        }
        fprintf(stderr, "I2C write error (reg 0x%02X, val 0x%02X), retrying (%d/%d)...\n", reg, val, retries + 1, MAX_RETRIES);
        retries++;
        usleep(RETRY_DELAY_BASE_MS * (1 << retries) * 1000); // Exponential backoff
    }
    fprintf(stderr, "I2C write failed after %d retries (reg 0x%02X, val 0x%02X)\n", MAX_RETRIES, reg, val);
    return -1; // Indicate failure
}

// MPU-6050 initialization function
void init_mpu6050(int fd) {
    // Wake up the MPU-6050
    if (write_i2c_reg(fd, PWR_MGMT_1, 0) != 0) {
        fprintf(stderr, "Failed to wake up MPU-6050\n");
    }

    // Configure accelerometer range to +/- 2g
    if (write_i2c_reg(fd, ACCEL_CONFIG, 0x00) != 0) {
        fprintf(stderr, "Failed to configure accelerometer range\n");
    }

    // Configure gyroscope range to +/- 250 degrees/second
    if (write_i2c_reg(fd, GYRO_CONFIG, 0x00) != 0) {
        fprintf(stderr, "Failed to configure gyroscope range\n");
    }
}

// Function to read accelerometer and gyroscope data
void read_accel_gyro_data(int fd, int *accel_x, int *accel_y, int *accel_z, int *gyro_x, int *gyro_y, int *gyro_z) {
    *accel_x = (read_i2c_reg(fd, ACCEL_XOUT_H) << 8) | read_i2c_reg(fd, ACCEL_XOUT_H + 1);
    *accel_y = (read_i2c_reg(fd, ACCEL_XOUT_H + 2) << 8) | read_i2c_reg(fd, ACCEL_XOUT_H + 3);
    *accel_z = (read_i2c_reg(fd, ACCEL_XOUT_H + 4) << 8) | read_i2c_reg(fd, ACCEL_XOUT_H + 5);
    *gyro_x = (read_i2c_reg(fd, GYRO_XOUT_H) << 8) | read_i2c_reg(fd, GYRO_XOUT_H + 1);
    *gyro_y = (read_i2c_reg(fd, GYRO_XOUT_H + 2) << 8) | read_i2c_reg(fd, GYRO_XOUT_H + 3);
    *gyro_z = (read_i2c_reg(fd, GYRO_XOUT_H + 4) << 8) | read_i2c_reg(fd, GYRO_XOUT_H + 5);
}

// Function to calculate pitch angle
float calculate_pitch(int accel_x, int accel_y, int accel_z) {
    float pitch = atan2(accel_x, sqrt(accel_y * accel_y + accel_z * accel_z)) * 180 / M_PI;
    return pitch;
}

// Function to calculate roll angle
float calculate_roll(int accel_x, int accel_y, int accel_z) {
    float roll = atan2(accel_y, sqrt(accel_x * accel_x + accel_z * accel_z)) * 180 / M_PI;
    return roll;
}

// Function to map angle to servo position
int map_angle_to_servo_position(float angle) {
    // Assuming angle range is -90 to 90 degrees
    // and servo position range is 1000 to 2000 us
    int position = (int)((angle + 90.0) / 180.0 * 1000.0 + 1000.0);
    return position;
}

// Function to set servo position using sysfs
void set_servo_position(int position) {
    char path[64];
    char value_str[16];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/duty_cycle", PWM_CHIP, PWM_NUM);
    snprintf(value_str, sizeof(value_str), "%d", position);

    fd = open(path, O_WRONLY);
    if (fd == -1) {
        perror("Failed to open duty_cycle file");
        return;
    }

    if (write(fd, value_str, strlen(value_str)) == -1) {
        perror("Failed to write duty_cycle");
    }

    close(fd);
}

// Function to log data to file
void log_data(float pitch, float roll, int servo_position) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f,%d\n", timestamp, pitch, roll, servo_position);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received (%d). Shutting down...\n", sig);
    keep_running = 0;
}

// Cleanup function to release resources
void cleanup() {
    fprintf(stderr, "Cleaning up resources...\n");

    // Stop PWM signal
    char path[64];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/enable", PWM_CHIP, PWM_NUM);
    fd = open(path, O_WRONLY);
    if (fd != -1) {
        if (write(fd, "0", 1) == -1) {
            perror("Failed to disable PWM");
        }
        close(fd);
    }

    // Close I2C device
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    fprintf(stderr, "Cleanup complete. Exiting.\n");
}

int main() {
    // Initialize WiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Failed to initialize WiringPi\n");
        return 1;
    }

    // Initialize I2C
    i2c_fd = init_i2c(MPU6050_ADDR);
    if (i2c_fd == -1) {
        return 1;
    }

    // Initialize MPU-6050
    init_mpu6050(i2c_fd);

    // Initialize PWM
    char path[64];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/export", PWM_CHIP);
    fd = open(path, O_WRONLY);
    if (fd != -1) {
        if (write(fd, "0", 1) == -1) {
            perror("Failed to export PWM");
        }
        close(fd);
    }

    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/period", PWM_CHIP, PWM_NUM);
    fd = open(path, O_WRONLY);
    if (fd != -1) {
        char period_str[16];
        snprintf(period_str, sizeof(period_str), "%d", PWM_PERIOD);
        if (write(fd, period_str, strlen(period_str)) == -1) {
            perror("Failed to set PWM period");
        }
        close(fd);
    }

    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/enable", PWM_CHIP, PWM_NUM);
    fd = open(path, O_WRONLY);
    if (fd != -1) {
        if (write(fd, "1", 1) == -1) {
            perror("Failed to enable PWM");
        }
        close(fd);
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
    float pitch, roll;
    int servo_position;

    // Main loop
    while (keep_running) {
        // Read sensor data
        read_accel_gyro_data(i2c_fd, &accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z);

        // Calculate pitch and roll angles
        pitch = calculate_pitch(accel_x, accel_y, accel_z);
        roll = calculate_roll(accel_x, accel_y, accel_z);

        // Map angle to servo position
        servo_position = map_angle_to_servo_position(pitch);

        // Set servo position
        set_servo_position(servo_position);

        // Log data
        log_data(pitch, roll, servo_position);

        // Delay
        usleep(100000); // 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

