#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_GPIO 4
#define RELAY2_GPIO 17
#define RELAY3_GPIO 27
#define RELAY4_GPIO 22

// Define PWM frequency
#define PWM_FREQUENCY 100

// Define PWM range
#define PWM_RANGE 100

// Define schedule file name
#define SCHEDULE_FILE "lighting_schedule.txt"

// Structure to represent a schedule entry
typedef struct {
    int hour;
    int minute;
    int second;
    int relay_number;
    int on_off;
} schedule_entry_t;

// Global variables
static volatile int running = 1;
static int current_relay = 0;
static int current_state = 0; // 0: off, 1: on
static int target_state = 0;
static int fade_direction = 1; // 1: increasing, -1: decreasing
static int fade_step = 0;
static int fade_steps = 1800; // 30 minutes * 60 seconds / 10 milliseconds
static int pwm_duty = 0;

// Function prototypes
int read_schedule(schedule_entry_t *schedule, int *schedule_size);
int parse_schedule_line(const char *line, schedule_entry_t *entry);
int check_schedule(const schedule_entry_t *schedule, int schedule_size, int *relay, int *state);
void set_relay_state(int relay, int state);
void fade_lamp(int relay, int state);
void signal_handler(int signal);
void cleanup();

// Function to read the schedule from the file
int read_schedule(schedule_entry_t *schedule, int *schedule_size) {
    FILE *fp = fopen(SCHEDULE_FILE, "r");
    if (fp == NULL) {
        perror("Error opening schedule file");
        return -1;
    }

    char line[256];
    int i = 0;
    while (fgets(line, sizeof(line), fp) != NULL && i < 100) { // Limit to 100 entries
        if (parse_schedule_line(line, &schedule[i]) == 0) {
            i++;
        }
    }

    fclose(fp);
    *schedule_size = i;
    return 0;
}

// Function to parse a single line from the schedule file
int parse_schedule_line(const char *line, schedule_entry_t *entry) {
    if (sscanf(line, "%d:%d:%d,%d,%d", &entry->hour, &entry->minute, &entry->second, &entry->relay_number, &entry->on_off) == 5) {
        return 0;
    } else {
        fprintf(stderr, "Error parsing schedule line: %s\n", line);
        return -1;
    }
}

// Function to check the schedule against the current time
int check_schedule(const schedule_entry_t *schedule, int schedule_size, int *relay, int *state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    int current_hour = t->tm_hour;
    int current_minute = t->tm_min;
    int current_second = t->tm_sec;

    for (int i = 0; i < schedule_size; i++) {
        if (schedule[i].hour == current_hour &&
            schedule[i].minute == current_minute &&
            schedule[i].second == current_second) {
            *relay = schedule[i].relay_number;
            *state = schedule[i].on_off;
            return 1; // Schedule entry found
        }
    }

    return 0; // No schedule entry found
}

// Function to set the relay state
void set_relay_state(int relay, int state) {
    int gpio_pin;

    switch (relay) {
        case 1:
            gpio_pin = RELAY1_GPIO;
            break;
        case 2:
            gpio_pin = RELAY2_GPIO;
            break;
        case 3:
            gpio_pin = RELAY3_GPIO;
            break;
        case 4:
            gpio_pin = RELAY4_GPIO;
            break;
        default:
            fprintf(stderr, "Invalid relay number: %d\n", relay);
            return;
    }

    gpioWrite(gpio_pin, state);
}

// Function to fade the lamp brightness
void fade_lamp(int relay, int state) {
    if (current_relay != relay) {
        current_relay = relay;
        current_state = 0; // Reset current state when changing relay
        target_state = state;
        fade_direction = (state == 1) ? 1 : -1; // Fade in if turning on, fade out if turning off
        fade_step = 0;
        pwm_duty = 0;
    }

    if (current_state != target_state) {
        fade_step++;
        if (fade_step >= fade_steps) {
            fade_step = fade_steps;
            current_state = target_state;
        }

        if (fade_direction == 1) {
            pwm_duty = (int)(((float)fade_step / fade_steps) * PWM_RANGE);
        } else {
            pwm_duty = (int)(((float)(fade_steps - fade_step) / fade_steps) * PWM_RANGE);
        }

        gpioPWM(current_relay, pwm_duty);
    }
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
}

// Cleanup function
void cleanup() {
    // Turn off all relays
    set_relay_state(1, 0);
    set_relay_state(2, 0);
    set_relay_state(3, 0);
    set_relay_state(4, 0);

    // Stop PWM
    gpioPWM(RELAY1_GPIO, 0);
    gpioPWM(RELAY2_GPIO, 0);
    gpioPWM(RELAY3_GPIO, 0);
    gpioPWM(RELAY4_GPIO, 0);

    // Release GPIO resources
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY2_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY3_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY4_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(RELAY1_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY2_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY3_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY4_GPIO, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(RELAY1_GPIO, PWM_RANGE);
    gpioSetPWMrange(RELAY2_GPIO, PWM_RANGE);
    gpioSetPWMrange(RELAY3_GPIO, PWM_RANGE);
    gpioSetPWMrange(RELAY4_GPIO, PWM_RANGE);

    // Read the schedule
    schedule_entry_t schedule[100];
    int schedule_size;
    if (read_schedule(schedule, &schedule_size) != 0) {
        fprintf(stderr, "Failed to read schedule, exiting\n");
        cleanup();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        int relay, state;
        if (check_schedule(schedule, schedule_size, &relay, &state)) {
            fade_lamp(relay, state);
        } else {
            // No schedule entry found, maintain current state
            fade_lamp(current_relay, current_state);
        }

        gpioDelay(10); // Delay for 10 milliseconds
    }

    cleanup();

    return 0;
}

