#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18

// Define constants
#define MIN_DISTANCE 2.0  // Minimum distance in cm
#define MAX_DISTANCE 30.0 // Maximum distance in cm
#define MIN_FREQUENCY 200.0 // Minimum frequency in Hz
#define MAX_FREQUENCY 2000.0 // Maximum frequency in Hz
#define TIMEOUT_US 50000   // Timeout in microseconds (50ms)

// Global variable for program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 microseconds
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse width
long measure_pulse_width() {
    long start_tick, end_tick, pulse_width;

    // Wait for the echo pin to go high
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        gpioDelay(1); // Small delay to avoid busy-waiting
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo pulse timeout (start)\n");
        return -1; // Indicate timeout error
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go low
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        gpioDelay(1);
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo pulse timeout (end)\n");
        return -1; // Indicate timeout error
    }

    end_tick = gpioTick();

    pulse_width = end_tick - start_tick;
    if (pulse_width < 0) {
        // Handle tick rollover
        pulse_width += 0xFFFFFFFF + 1; // Add one to account for rollover
    }

    return pulse_width;
}

// Function to calculate the distance in centimeters
float calculate_distance(long pulse_width) {
    if (pulse_width < 0) {
        return -1.0; // Indicate error
    }
    // Speed of sound in air (approx. 343 m/s) and conversion to cm/us
    // Distance = (Time * Speed of Sound) / 2
    // Distance in cm = (Time in us * 0.0343 cm/us) / 2
    return (float)pulse_width * 0.0343 / 2.0;
}

// Function to map distance to frequency
float map_distance_to_frequency(float distance) {
    if (distance < MIN_DISTANCE) {
        return MIN_FREQUENCY;
    } else if (distance > MAX_DISTANCE) {
        return MAX_FREQUENCY;
    } else {
        // Linear mapping
