#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <math.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to set the color of the RGB LED using PWM
void set_color(int red, int green, int blue) {
    gpioPWM(RED_PIN, red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN, blue);
}

// Function to generate a proximity value based on a sine wave
float generate_proximity_value() {
    static float angle = 0.0;
    float proximity = 0.5 + 0.5 * sin(angle);
    angle += 0.01;
    if (angle > 2 * M_PI) {
        angle -= 2 * M_PI;
    }
    return proximity;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM frequency for all pins
    gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    fprintf(stderr, "Color-based proximity alert simulation started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Generate proximity value
        float proximity = generate_proximity_value();

        // Map proximity value to RGB color
        int red   = (int)(255 * proximity);
        int green = (int)(255 * (1.0 - proximity));
        int blue  = (int)(255 * (1.0 - proximity));

        // Set LED color
        set_color(red, green, blue);

        // Delay for 10 milliseconds
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    // Turn off the LED
    set_color(0, 0, 0);

    // Terminate pigpio library
    gpioTerminate();

    fprintf(stderr, "Program terminated gracefully.\n");

    return 0;
}

