#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43

// Sensitivity scale factor
#define GYRO_SCALE 131.0

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, uint16_t len);
void wake_mpu6050(int fd);
void read_gyro_data(int fd, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z);
void convert_to_degrees(int16_t gyro_x, int16_t gyro_y, int16_t gyro_z, float *deg_x, float *deg_y, float *deg_z);
void log_data(float gyro_x, float gyro_y, float gyro_z);
void signal_handler(int sig);

// I2C write function
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, uint16_t len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

// Wake up the MPU-6050
void wake_mpu6050(int fd) {
    if (i2c_write_byte(fd, PWR_MGMT_1, 0x00) != 0) {
        fprintf(stderr, "Failed to wake MPU-6050\n");
    }
}

// Read gyroscope data
void read_gyro_data(int fd, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    uint8_t data[6];
    if (i2c_read_bytes(fd, GYRO_XOUT_H, data, 6) != 0) {
        fprintf(stderr, "Failed to read gyroscope data\n");
        *gyro_x = *gyro_y = *gyro_z = 0; // Set to zero to avoid garbage values
        return;
    }

    *gyro_x = (int16_t)((data[0] << 8) | data[1]);
    *gyro_y = (int16_t)((data[2] << 8) | data[3]);
    *gyro_z = (int16_t)((data[4] << 8) | data[5]);
}

// Convert raw gyroscope data to degrees/second
void convert_to_degrees(int16_t gyro_x, int16_t gyro_y, int16_t gyro_z, float *deg_x, float *deg_y, float *deg_z) {
    *deg_x = (float)gyro_x / GYRO_SCALE;
    *deg_y = (float)gyro_y / GYRO_SCALE;
    *deg_z = (float)gyro_z / GYRO_SCALE;
}

// Log data to file
void log_data(float gyro_x, float gyro_y, float gyro_z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, gyro_x, gyro_y, gyro_z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting gracefully...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Wake up the MPU-6050
    wake_mpu6050(i2c_fd);

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    int16_t gyro_x, gyro_y, gyro_z;
    float deg_x, deg_y, deg_z;

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        read_gyro_data(i2c_fd, &gyro_x, &gyro_y, &gyro_z);

        // Convert to degrees/second
        convert_to_degrees(gyro_x, gyro_y, gyro_z, &deg_x, &deg_y, &deg_z);

        // Log data
        log_data(deg_x, deg_y, deg_z);

        // Wait 100 ms
        usleep(100000); // 100 ms = 100000 microseconds
    }

    // Close I2C device and log file
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

