#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define BUTTON_GPIO 17
#define BUZZER_GPIO 18

// Define PWM frequency and duty cycle
#define PWM_FREQUENCY 440 // Example frequency (Hz)
#define PWM_DUTY_CYCLE 128 // 50% duty cycle (0-255)

// Define melody lookup table (example)
const int melody[] = {440, 494, 523, 587, 659, 698, 784, 880, 0}; // Frequencies in Hz (0 indicates pause)
const int melody_length = sizeof(melody) / sizeof(melody[0]);

// Global variables
volatile int button_pressed = 0;
volatile int melody_playing = 0;
volatile int melody_index = 0;

// Function prototypes
void button_interrupt_handler(int gpio, int level, uint32_t tick, void *user);
void play_melody();
void stop_melody();
void signal_handler(int signal);

// Button interrupt handler
void button_interrupt_handler(int gpio, int level, uint32_t tick, void *user) {
    if (level == 0) { // Button pressed (active low)
        button_pressed = 1;
    }
}

// Play melody function
void play_melody() {
    melody_playing = 1;
    melody_index = 0;
    while (melody_playing && melody_index < melody_length) {
        if (melody[melody_index] != 0) {
            if (gpioHardwarePWM(BUZZER_GPIO, melody[melody_index], PWM_DUTY_CYCLE) != 0) {
                fprintf(stderr, "Error setting PWM frequency.\n");
                stop_melody();
                return;
            }
        } else {
            gpioDelay(200); // Pause
        }
        melody_index++;
        gpioDelay(100); // Delay between notes
    }
    stop_melody();
