#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define LOG_FILE "vibration_events.log"
#define WINDOW_SIZE 5

// Global variables
static volatile sig_atomic_t terminate = 0;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;
static int event_window[WINDOW_SIZE];
static int window_index = 0;

// Function prototypes
int init_gpio(void);
int read_sensor(void);
int log_event(int value);
int check_earthquake_alert(void);
void signal_handler(int sig);
void cleanup(void);

// Structure to hold GPIO configuration
typedef struct {
    const char *chipname;
    int line_num;
} gpio_config_t;

// Function to initialize GPIO
int init_gpio(void) {
    struct gpiod_chip *chip;
    struct gpiod_line_request_config config;

    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    memset(&config, 0, sizeof(config));
    config.consumer = "vibration_sensor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to read sensor value
int read_sensor(void) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        return -1;
    }
    return value;
}

// Function to log event to file
int log_event(int value) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", tm_info);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
            return -1;
        }
    }

    fprintf(log_file, "%s %d\n", timestamp, value);
    fflush(log_file); // Ensure immediate write

    // Alternative: Use fsync to ensure data is written to disk
    // if (fsync(fileno(log_file)) == -1) {
    //     fprintf(stderr, "Error syncing log file: %s\n", strerror(errno));
    //     return -1;
    // }

    return 0;
}

// Function to check for earthquake alert
int check_earthquake_alert(void) {
    int high_count = 0;
    for (int i = 0; i < WINDOW_SIZE; i++) {
        if (event_window[i] == 1) {
            high_count++;
        }
    }

    if (high_count >= 3) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", tm_info);
        printf("EARTHQUAKE ALERT: %s\n", timestamp);
        return 1; // Alert triggered
    }
    return 0; // No alert
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal %d received, terminating...\n", sig);
    terminate = 1;
}

// Cleanup function
void cleanup(void) {
    if (line) {
        gpiod_line_release(line);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main(int argc, char *argv[]) {
    int timeout_ms = 1000; // Default timeout
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                timeout_ms = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t timeout_ms]\n", argv[0]);
                return 1;
        }
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        return 1;
    }

    // Initialize event window
    for (int i = 0; i < WINDOW_SIZE; i++) {
        event_window[i] = 0;
    }

    struct timespec timeout;
    timeout.tv_sec = timeout_ms / 1000;
    timeout.tv_nsec = (timeout_ms % 1000) * 1000000;

    // Main loop
    while (!terminate) {
        int value = read_sensor();
        if (value < 0) {
            fprintf(stderr, "Error reading sensor, exiting...\n");
            break;
        }

        if (log_event(value) < 0) {
            fprintf(stderr, "Error logging event, exiting...\n");
            break;
        }

        // Update event window
        event_window[window_index] = value;
        window_index = (window_index + 1) % WINDOW_SIZE;

        // Check for earthquake alert
        check_earthquake_alert();

        // Wait for next event
        int ret = gpiod_line_event_wait(line, &timeout);
        if (ret < 0) {
            if (errno == EINTR) {
                // Interrupted by signal, exit loop
                break;
            }
            fprintf(stderr, "Error waiting for event: %s\n", strerror(errno));
            break;
        }
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

