#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// LSM303DLHC Magnetometer I2C address
#define LSM303_ADDRESS 0x1E

// LSM303DLHC Magnetometer Registers
#define CRA_REG_M 0x00
#define MR_REG_M 0x02
#define OUT_X_H_M 0x03
#define OUT_X_L_M 0x04
#define OUT_Z_H_M 0x05
#define OUT_Z_L_M 0x06
#define OUT_Y_H_M 0x07
#define OUT_Y_L_M 0x08

// Hard-iron calibration offsets
#define X_OFFSET 10.0f
#define Y_OFFSET -5.0f
#define Z_OFFSET 20.0f

// Global variables for I2C file descriptor and CSV file pointer
int i2c_fd = -1;
FILE *csv_file = NULL;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Close I2C file descriptor if open
    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    // Close CSV file if open
    if (csv_file != NULL) {
        fclose(csv_file);
    }

    exit(0);
}

// Function to initialize the I2C interface
int init_i2c(int address) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to write a byte to a specific register
int write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }

    return 0;
}

// Function to read multiple bytes from a specific register
int read_registers(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing register address for read");
        return -1;
    }

    if (read(fd, buf, len) != len) {
        perror("Error reading from I2C device");
        return -1;
    }

    return 0;
}

// Function to read magnetometer data
int read_magnetometer_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buffer[6];

    if (read_registers(fd, OUT_X_H_M, buffer, 6) != 0) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *z = (int16_t)((buffer[2] << 8) | buffer[3]);
    *y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Function to apply hard-iron calibration
void apply_calibration(int16_t x, int16_t y, int16_t z, float *calibrated_x, float *calibrated_y, float *calibrated_z) {
    *calibrated_x = (float)x - X_OFFSET;
    *calibrated_y = (float)y - Y_OFFSET;
    *calibrated_z = (float)z - Z_OFFSET;
}

// Function to calculate compass heading
void calculate_heading(float calibrated_x, float calibrated_y, float *heading) {
    *heading = atan2f(calibrated_y, calibrated_x) * 180.0f / M_PI;
    if (*heading < 0) {
        *heading += 360.0f;
    }
}

// Function to map heading to compass direction
const char *map_heading_to_direction(float heading) {
    if (heading >= 337.5f || heading < 22.5f) return "N";
    if (heading >= 22.5f && heading < 67.5f) return "NE";
    if (heading >= 67.5f && heading < 112.5f) return "E";
    if (heading >= 112.5f && heading < 157.5f) return "SE";
    if (heading >= 157.5f && heading < 202.5f) return "S";
    if (heading >= 202.5f && heading < 247.5f) return "SW";
    if (heading >= 247.5f && heading < 292.5f) return "W";
    return "NW";
}

// Function to log data to CSV file
int log_data(FILE *fp, int16_t x, int16_t y, int16_t z, float heading, const char *direction) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d,%.2f,%s\n", timestamp, x, y, z, heading, direction) < 0) {
        perror("Error writing to CSV file");
        return -1;
    }

    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(LSM303_ADDRESS);
    if (i2c_fd < 0) {
        return 1;
    }

    // Configure magnetometer for continuous conversion mode
    if (write_register(i2c_fd, MR_REG_M, 0x00) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Set output data rate to 15 Hz
    if (write_register(i2c_fd, CRA_REG_M, 0x14) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Open CSV file for logging
    csv_file = fopen("mag_log.csv", "a");
    if (csv_file == NULL) {
        perror("Error opening CSV file");
        close(i2c_fd);
        return 1;
    }

    // Write header row if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading,Direction\n");
    }
    rewind(csv_file);

    int16_t x, y, z;
    float calibrated_x, calibrated_y, calibrated_z;
    float heading;
    const char *direction;

    // Main loop
    while (1) {
        // Read magnetometer data
        if (read_magnetometer_data(i2c_fd, &x, &y, &z) == 0) {
            // Apply hard-iron calibration
            apply_calibration(x, y, z, &calibrated_x, &calibrated_y, &calibrated_z);

            // Calculate compass heading
            calculate_heading(calibrated_x, calibrated_y, &heading);

            // Map heading to compass direction
            direction = map_heading_to_direction(heading);

            // Print heading to console
            printf("Heading: %.2f degrees (%s)\n", heading, direction);

            // Log data to CSV file
            if (log_data(csv_file, x, y, z, heading, direction) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading magnetometer data, skipping sample\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // The following lines will never be reached due to the infinite loop.
    // However, they are included for completeness and to demonstrate
    // proper resource cleanup in case the loop is ever modified.
    close(i2c_fd);
    fclose(csv_file);

    return 0;
}

