#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Debounce time in milliseconds
#define DEBOUNCE_TIME 200

// Global variables
static volatile int relay_state = 0; // 0 = OFF, 1 = ON
static volatile unsigned long last_touch_time = 0;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
void toggle_relay();
void log_relay_state(int state);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Initialize relay to OFF

    return 0;
}

// Function to read the touch sensor state
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to toggle the relay state
void toggle_relay() {
    relay_state = !relay_state;
    gpioWrite(RELAY_PIN, relay_state);
}

// Function to log the relay state to a file
void log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];
    char relay_state_str[4];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (state == 1) {
        strcpy(relay_state_str, "ON");
    } else {
        strcpy(relay_state_str, "OFF");
    }

    fprintf(log_file, "{\"timestamp\":\"%s\",\"relay_state\":\"%s\"}\n", timestamp, relay_state_str);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C pressed. Exiting...\n");
        cleanup();
        exit(0);
    }
}

// Cleanup function to turn off the relay and close the log file
void cleanup() {
    gpioWrite(RELAY_PIN, 0); // Turn off the relay
    if (log_file != NULL) {
        log_relay_state(0); // Log the final state
        fclose(log_file);
    }
    gpioTerminate(); // Terminate pigpio
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen("relay_log.json", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    printf("Relay control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        int touch_detected = read_touch_sensor();

        if (touch_detected == 1) {
            unsigned long current_time = gpioTick();
            if (current_time - last_touch_time > DEBOUNCE_TIME * 1000) { // Convert ms to microseconds
                toggle_relay();
                log_relay_state(relay_state);
                last_touch_time = current_time;
            }
        }

        gpioDelay(10); // Small delay to prevent busy-waiting
    }

    return 0;
}

