#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

// Define the GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define the log file name
#define LOG_FILE "irrigation_log.txt"

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay1_line = NULL;
static struct gpiod_line *relay2_line = NULL;
static struct gpiod_line *relay3_line = NULL;
static struct gpiod_line *relay4_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int setup_gpio(void);
int read_soil_moisture(void);
void irrigate(int moisture_level);
void log_data(int relay_number, int moisture_level);
void cleanup_gpio(void);
void signal_handler(int sig);

// Function to format the current timestamp in ISO 8601 format
char* get_iso8601_timestamp(char* timestamp_buffer, size_t buffer_size) {
    time_t timer;
    struct tm* tm_info;

    time(&timer);
    tm_info = localtime(&timer);

    strftime(timestamp_buffer, buffer_size, "%Y-%m-%dT%H:%M:%SZ", tm_info);
    return timestamp_buffer;
}

// Function to set the state of a relay (0 for ON, 1 for OFF)
int set_relay_state(struct gpiod_line *line, int state) {
    int ret = gpiod_line_set_value(line, state);
    if (ret < 0) {
        fprintf(stderr, "Error setting relay state: %s\n", strerror(-ret));
        return -1;
    }
    return 0;
}

// Function to setup the GPIO lines
int setup_gpio(void) {
    int ret;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    // Get the lines for the relays
    relay1_line = gpiod_chip_get_line(chip, RELAY1_PIN);
    relay2_line = gpiod_chip_get_line(chip, RELAY2_PIN);
    relay3_line = gpiod_chip_get_line(chip, RELAY3_PIN);
    relay4_line = gpiod_chip_get_line(chip, RELAY4_PIN);

    if (!relay1_line || !relay2_line || !relay3_line || !relay4_line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        cleanup_gpio();
        return -1;
    }

    // Request the lines as outputs with an initial value of 1 (inactive)
    ret = gpiod_line_request_output(relay1_line, "irrigation", 1);
    ret = gpiod_line_request_output(relay2_line, "irrigation", 1);
    ret = gpiod_line_request_output(relay3_line, "irrigation", 1);
    ret = gpiod_line_request_output(relay4_line, "irrigation", 1);

    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line as output: %s\n", strerror(-ret));
        cleanup_gpio();
        return -1;
    }

    return 0;
}

// Function to read the simulated soil moisture value
int read_soil_moisture(void) {
    return rand() % 101; // Returns a value between 0 and 100
}

// Function to irrigate the plants
void irrigate(int moisture_level) {
    if (moisture_level < 30) {
        printf("Moisture level below threshold. Irrigating...\n");
        int relays[] = {relay1_line, relay2_line, relay3_line, relay4_line};
        for (int i = 0; i < 4; i++) {
            char timestamp[32];
            get_iso8601_timestamp(timestamp, sizeof(timestamp));
            log_data(i + 1, moisture_level);
            if (set_relay_state(relays[i], 0) == 0) {
                printf("Relay %d ON\n", i + 1);
                sleep(5);
                if (set_relay_state(relays[i], 1) == 0) {
                    printf("Relay %d OFF\n", i + 1);
                }
            }
            sleep(1);
        }
    } else {
        printf("Moisture level sufficient. No irrigation needed.\n");
    }
}

// Function to log the data to a file
void log_data(int relay_number, int moisture_level) {
    char timestamp[32];
    get_iso8601_timestamp(timestamp, sizeof(timestamp));

    if (log_file != NULL) {
        fprintf(log_file, "%s, Relay %d, Moisture Level: %d\n", timestamp, relay_number, moisture_level);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to cleanup the GPIO lines and close the chip
void cleanup_gpio(void) {
    if (relay1_line) {
        gpiod_line_release(relay1_line);
    }
    if (relay2_line) {
        gpiod_line_release(relay2_line);
    }
    if (relay3_line) {
        gpiod_line_release(relay3_line);
    }
    if (relay4_line) {
        gpiod_line_release(relay4_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    printf("Signal received (%d). Cleaning up and exiting...\n", sig);
    terminate = 1;
}

int main(void) {
    // Seed the random number generator
    srand(time(NULL));

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Setup GPIO
    if (setup_gpio() != 0) {
        fprintf(stderr, "GPIO setup failed. Exiting.\n");
        fclose(log_file);
        return 1;
    }

    printf("Smart Irrigation System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int moisture_level = read_soil_moisture();
        printf("Soil Moisture: %d\n", moisture_level);
        irrigate(moisture_level);
        sleep(10);
    }

    // Cleanup GPIO before exiting
    cleanup_gpio();

    printf("Smart Irrigation System stopped.\n");
    return 0;
}

