}

// Function to log the data to a file
void log_data(int relay_number, int moisture_level) {
    char timestamp[32];
    get_iso8601_timestamp(timestamp, sizeof(timestamp));

    if (log_file != NULL) {
        fprintf(log_file, "%s, Relay %d, Moisture Level: %d\n", timestamp, relay_number, moisture_level);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to cleanup the GPIO lines and close the chip
void cleanup_gpio(void) {
    if (relay1_line) {
        gpiod_line_release(relay1_line);
    }
    if (relay2_line) {
        gpiod_line_release(relay2_line);
    }
    if (relay3_line) {
        gpiod_line_release(relay3_line);
    }
    if (relay4_line) {
        gpiod_line_release(relay4_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    printf("Signal received (%d). Cleaning up and exiting...\n", sig);
    terminate = 1;
}

int main(void) {
    // Seed the random number generator
    srand(time(NULL));

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Setup GPIO
    if (setup_gpio() != 0) {
        fprintf(stderr, "GPIO setup failed. Exiting.\n");
        fclose(log_file);
        return 1;
    }

    printf("Smart Irrigation System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int moisture_level = read_soil_moisture();
        printf("Soil Moisture: %d\n", moisture_level);
        irrigate(moisture_level);
        sleep(10);
    }

    // Cleanup GPIO before exiting
    cleanup_gpio();

    printf("Smart Irrigation System stopped.\n");
    return 0;
}

