#define MOISTURE_THRESHOLD 50

// Define servo pulse widths
#define VALVE_CLOSED 500
#define VALVE_OPEN 2500
#define NOZZLE_0 500
#define NOZZLE_45 1000
#define NOZZLE_90 1500
#define NOZZLE_135 2000
#define NOZZLE_180 2500

// Define watering cycle parameters
#define WATERING_DURATION 2 // seconds
#define HOLD_DURATION 5      // seconds

// Global variable for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int set_servo_pulse_width(int pin, int pulse_width);
int open_valve(int pin);
int close_valve(int pin);
int sweep_nozzle(int pin, int duration);
int check_moisture(int moisture_level);
void signal_handler(int signal);

// Function to set servo pulse width with retry mechanism
int set_servo_pulse_width(int pin, int pulse_width) {
    int retries = 3;
    int delay_ms = 100;
    int result;

    while (retries > 0) {
        result = gpioServo(pin, pulse_width);
        if (result == 0) {
            return 0; // Success
        }
        fprintf(stderr, "Error setting servo pulse width for pin %d, retrying...\n", pin);
        gpioDelay(delay_ms * 1000); // Convert ms to us
        delay_ms *= 2; // Exponential backoff
        retries--;
    }
    fprintf(stderr, "Critical warning: Failed to set servo pulse width for pin %d after multiple retries.\n", pin);
    return -1; // Failure
}

// Function to open the valve
int open_valve(int pin) {
    if (set_servo_pulse_width(pin, VALVE_OPEN) != 0) {
        fprintf(stderr, "Error opening valve.\n");
        return -1;
    }
    return 0;
}

