int sweep_nozzle(int pin, int duration) {
    int positions[] = {NOZZLE_0, NOZZLE_45, NOZZLE_90, NOZZLE_135, NOZZLE_180};
    int num_positions = sizeof(positions) / sizeof(positions[0]);

    for (int i = 0; i < num_positions; i++) {
        if (set_servo_pulse_width(pin, positions[i]) != 0) {
            fprintf(stderr, "Error setting nozzle position %d.\n", positions[i]);
            return -1;
        }
        gpioDelay(duration * 1000000); // Convert seconds to microseconds
    }
    return 0;
}

