    program_running = 0;
    printf("Caught signal %d, stopping...\n", signal);
    close_valve(VALVE_SERVO_PIN);
    set_servo_pulse_width(NOZZLE_SERVO_PIN, 0); // Stop nozzle
    gpioTerminate();
    exit(0);
}

