            if (open_valve(VALVE_SERVO_PIN) != 0) {
                fprintf(stderr, "Failed to open valve, skipping watering.\n");
                moisture_index = (moisture_index + 1) % num_moisture_levels;
                gpioDelay(5000000); // Wait 5 seconds
                continue;
