            if (sweep_nozzle(NOZZLE_SERVO_PIN, WATERING_DURATION) != 0) {
                fprintf(stderr, "Failed to sweep nozzle, closing valve.\n");
            }

            close_valve(VALVE_SERVO_PIN);
        } else {
            printf("Moisture level above threshold, skipping watering.\n");
        }

        moisture_index = (moisture_index + 1) % num_moisture_levels;
        gpioDelay(5000000); // Wait 5 seconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    close_valve(VALVE_SERVO_PIN);
    set_servo_pulse_width(NOZZLE_SERVO_PIN, 0);
    gpioTerminate();

    return 0;
}

