#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <sys/time.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43

// Sensitivity scale factor
#define GYRO_SCALE 131.0

// I2C device file
#define I2C_DEVICE "/dev/i2c-1"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len);
void wake_mpu6050(int fd);
int read_gyro_data(int fd, int16_t *x, int16_t *y, int16_t *z);
float convert_to_degrees_per_second(int16_t raw_value);
void log_data(FILE *fp, struct timeval tv, float x, float y, float z);
void signal_handler(int signal);

// I2C write function
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// Wake up MPU-6050
void wake_mpu6050(int fd) {
    if (i2c_write_byte(fd, PWR_MGMT_1, 0x00) != 0) {
        fprintf(stderr, "Failed to wake MPU-6050\n");
    }
}

// Read gyroscope data
int read_gyro_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];

    if (i2c_read_bytes(fd, GYRO_XOUT_H, data, 6) != 0) {
        fprintf(stderr, "Failed to read gyroscope data\n");
        return -1;
    }

    *x = (int16_t)((data[0] << 8) | data[1]);
    *y = (int16_t)((data[2] << 8) | data[3]);
    *z = (int16_t)((data[4] << 8) | data[5]);

    return 0;
}

// Convert raw data to degrees per second
float convert_to_degrees_per_second(int16_t raw_value) {
    return (float)raw_value / GYRO_SCALE;
}

// Log data to file
void log_data(FILE *fp, struct timeval tv, float x, float y, float z) {
    fprintf(fp, "%ld.%06ld,%.3f,%.3f,%.3f\n", tv.tv_sec, tv.tv_usec, x, y, z);
    fflush(fp); // Ensure data is written to disk immediately
}

// Signal handler
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

int main() {
    struct timeval tv;
    int16_t raw_x, raw_y, raw_z;
    float x, y, z;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Wake up MPU-6050
    wake_mpu6050(i2c_fd);

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read gyroscope data
        if (read_gyro_data(i2c_fd, &raw_x, &raw_y, &raw_z) == 0) {
            // Convert to degrees per second
            x = convert_to_degrees_per_second(raw_x);
            y = convert_to_degrees_per_second(raw_y);
            z = convert_to_degrees_per_second(raw_z);

            // Get timestamp
            gettimeofday(&tv, NULL);

            // Log data
            log_data(log_file, tv, x, y, z);
        } else {
            fprintf(stderr, "Error reading gyroscope data. Retrying...\n");
        }

        // Delay for 100 ms (10 Hz sampling rate)
        usleep(100000); // 100000 microseconds = 100 milliseconds
    }

    // Close resources
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

