#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define timeout duration (50ms)
#define TIMEOUT_US 50000

// Define minimum guard time (60ms)
#define MIN_GUARD_US 60000

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;
static FILE *log_file;
static volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio(void);
void trigger_pulse(void);
long measure_pulse_width(void);
float calculate_distance(long pulse_width);
void log_distance(float distance);
void signal_handler(int signal);
void cleanup(void);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully.\n", signal);
}

// Initialize GPIO lines
int initialize_gpio(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    // Get trigger line
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        fprintf(stderr, "Error getting trigger line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    // Get echo line
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Error getting echo line: %s\n", strerror(errno));
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request trigger line as output
    ret = gpiod_line_request_output(trigger_line, "ultrasonic_sensor", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting trigger line as output: %s\n", strerror(errno));
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request echo line as input
    ret = gpiod_line_request_input(echo_line, "ultrasonic_sensor");
    if (ret < 0) {
        fprintf(stderr, "Error requesting echo line as input: %s\n", strerror(errno));
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Generate a 10 microsecond high pulse on the trigger line
void trigger_pulse(void) {
    int ret;

    // Set trigger high
    ret = gpiod_line_set_value(trigger_line, 1);
    if (ret < 0) {
        fprintf(stderr, "Error setting trigger high: %s\n", strerror(errno));
        return;
    }

    // Wait 10 microseconds
    struct timespec ts;
    ts.tv_sec = 0;
    ts.tv_nsec = 10000;
    nanosleep(&ts, NULL);

    // Set trigger low
    ret = gpiod_line_set_value(trigger_line, 0);
    if (ret < 0) {
        fprintf(stderr, "Error setting trigger low: %s\n", strerror(errno));
    }
}

// Measure the echo pulse width with a timeout
long measure_pulse_width(void) {
    struct timespec start, end;
    int ret;
    long pulse_width = -1; // Initialize to error value

    // Wait for rising edge
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (1) {
        ret = gpiod_line_get_value(echo_line);
        if (ret < 0) {
            fprintf(stderr, "Error reading echo line: %s\n", strerror(errno));
            return -1;
        }
        if (ret == 1) {
            break;
        }
        clock_gettime(CLOCK_MONOTONIC, &end);
        if (((end.tv_sec - start.tv_sec) * 1000000000LL + (end.tv_nsec - start.tv_nsec)) > TIMEOUT_US * 1000) {
            fprintf(stderr, "Timeout waiting for rising edge\n");
            return -1;
        }
    }

    // Measure pulse width
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (1) {
        ret = gpiod_line_get_value(echo_line);
        if (ret < 0) {
            fprintf(stderr, "Error reading echo line: %s\n", strerror(errno));
            return -1;
        }
        if (ret == 0) {
            break;
        }
        clock_gettime(CLOCK_MONOTONIC, &end);
        if (((end.tv_sec - start.tv_sec) * 1000000000LL + (end.tv_nsec - start.tv_nsec)) > TIMEOUT_US * 1000) {
            fprintf(stderr, "Timeout waiting for falling edge\n");
            return -1;
        }
    }
    clock_gettime(CLOCK_MONOTONIC, &end);

    // Calculate pulse width in microseconds
    pulse_width = ((end.tv_sec - start.tv_sec) * 1000000000LL + (end.tv_nsec - start.tv_nsec)) / 1000;

    return pulse_width;
}

// Convert pulse width to distance in centimeters
float calculate_distance(long pulse_width) {
    return (float)pulse_width * 0.01715;
}

// Log the distance to the log file
void log_distance(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Get current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Write to log file
    fprintf(log_file, "%s,%.2f\n", timestamp, distance);
    fflush(log_file); // Ensure data is written immediately
}

// Cleanup function to release resources
void cleanup(void) {
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main(void) {
    long pulse_width;
    float distance;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Main loop
    while (program_running) {
        // Wait for the minimum guard time
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = MIN_GUARD_US;
        nanosleep(&ts, NULL);

        // Trigger the sensor
        trigger_pulse();

        // Measure the pulse width
        pulse_width = measure_pulse_width();

        // Calculate the distance
        if (pulse_width > 0) {
            distance = calculate_distance(pulse_width);
        } else {
            distance = -1.0;
        }

        // Log the distance
        log_distance(distance);

        // Wait for 1 second
        ts.tv_sec = 1;
        ts.tv_nsec = 0;
        nanosleep(&ts, NULL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

