#include <pigpio.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_RELAY 18
#define DISTANCE_THRESHOLD 50 // cm
#define I2C_RETRY_COUNT 3

// VL53L1X register addresses
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x0000
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x0001
#define VL53L1X_REG_PRE_RANGE_CONFIG_TIMEOUT_MACROP_HI 0x0050
#define VL53L1X_REG_FINAL_RANGE_CONFIG_TIMEOUT_MACROP_HI 0x0070
#define VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG 0x0081
#define VL53L1X_REG_SYSRANGE_START 0x000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance(uint16_t *distance);
void control_relay(int distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// VL53L1X initialization function
int vl53l1x_init() {
    int status = 0;
    uint8_t data[2];
    int retries;

    // Software reset
    data[0] = 0x00; // Reset value
    retries = I2C_RETRY_COUNT;
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, 0x0000, data[0]);
        if (status == 0) break;
        fprintf(stderr, "Error writing to VL53L1X (reset): %d, retries left: %d\n", status, retries);
        gpioDelay(1000); // Wait 1ms
        retries--;
    }
    if (status != 0) {
        fprintf(stderr, "Failed to reset VL53L1X after multiple retries.\n");
        return -1;
    }
    gpioDelay(10000); // Wait 10ms for reset to complete

    // Configure for short distance mode
    data[0] = 0x01; // Short distance mode
    retries = I2C_RETRY_COUNT;
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, 0x0081, data[0]);
        if (status == 0) break;
        fprintf(stderr, "Error writing to VL53L1X (short distance mode): %d, retries left: %d\n", status, retries);
        gpioDelay(1000); // Wait 1ms
        retries--;
    }
    if (status != 0) {
        fprintf(stderr, "Failed to set short distance mode after multiple retries.\n");
        return -1;
    }

    // Start continuous ranging
    data[0] = 0x01; // Start ranging
    retries = I2C_RETRY_COUNT;
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, 0x0000, data[0]);
        if (status == 0) break;
        fprintf(stderr, "Error writing to VL53L1X (start ranging): %d, retries left: %d\n", status, retries);
        gpioDelay(1000); // Wait 1ms
        retries--;
    }
    if (status != 0) {
        fprintf(stderr, "Failed to start ranging after multiple retries.\n");
        return -1;
    }

    return 0;
}

// VL53L1X read distance function
int vl53l1x_read_distance(uint16_t *distance) {
    int status = 0;
    uint8_t data[2];
    int retries;

    // Check data ready status
    retries = I2C_RETRY_COUNT;
    while (retries > 0) {
        status = i2cReadByteData(i2c_handle, 0x0044);
        if (status >= 0) break;
        fprintf(stderr, "Error reading data ready status: %d, retries left: %d\n", status, retries);
        gpioDelay(1000); // Wait 1ms
        retries--;
    }
    if (status < 0) {
        fprintf(stderr, "Failed to read data ready status after multiple retries.\n");
        return -1;
    }

    if (status & 0x01) { // Data ready
        // Read distance
        retries = I2C_RETRY_COUNT;
        while (retries > 0) {
            status = i2cReadI2CBlockData(i2c_handle, 0x0096, (char *)data, 2);
            if (status == 2) break;
            fprintf(stderr, "Error reading distance: %d, retries left: %d\n", status, retries);
            gpioDelay(1000); // Wait 1ms
            retries--;
        }
        if (status != 2) {
            fprintf(stderr, "Failed to read distance after multiple retries.\n");
            return -1;
        }

        *distance = (data[0] << 8) | data[1];
        return 0;
    } else {
        return -1; // Data not ready
    }
}

// Relay control function
void control_relay(int distance) {
    if (distance <= DISTANCE_THRESHOLD) {
        gpioWrite(GPIO_RELAY, 1); // HIGH
    } else {
        gpioWrite(GPIO_RELAY, 0); // LOW
    }
}

int main() {
    int status;
    uint16_t distance;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init() != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(GPIO_RELAY, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read distance from VL53L1X
        status = vl53l1x_read_distance(&distance);
        if (status == 0) {
            // Control relay based on distance
            control_relay(distance);

            // Log distance to stdout
            printf("Distance: %d mm\n", distance);
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }

        // Wait 100ms
        gpioDelay(100000);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(GPIO_RELAY, 0); // Set relay LOW
    gpioTerminate();

    return 0;
}

