#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO chip and line numbers
#define GPIOCHIP "gpiochip0"
#define GPIO17 17
#define GPIO18 18
#define GPIO27 27
#define GPIO22 22

// Define watering cycle parameters
#define WATERING_DURATION 5 // seconds
#define TOTAL_DURATION 86400 // seconds (24 hours)

// Define polling interval
#define POLLING_INTERVAL 60 // seconds

// Global variables for GPIO chip and lines
struct gpiod_chip *chip = NULL;
struct gpiod_line *line17 = NULL;
struct gpiod_line *line18 = NULL;
struct gpiod_line *line27 = NULL;
struct gpiod_line *line22 = NULL;

// Function prototypes
int initialize_gpio();
int set_gpio_output(struct gpiod_line *line, int value);
int activate_relay(struct gpiod_line *line, int duration);
int log_watering_event(int gpio_pin);
void cleanup_gpio();
void signal_handler(int signum);

// Function to initialize GPIO lines
int initialize_gpio() {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip %s\n", GPIOCHIP);
        return -1;
    }

    // Get GPIO lines
    line17 = gpiod_chip_get_line(chip, GPIO17);
    line18 = gpiod_chip_get_line(chip, GPIO18);
    line27 = gpiod_chip_get_line(chip, GPIO27);
    line22 = gpiod_chip_get_line(chip, GPIO22);

    if (!line17 || !line18 || !line27 || !line22) {
        fprintf(stderr, "Error: Could not get one or more GPIO lines\n");
        cleanup_gpio();
        return -1;
    }

    // Request GPIO lines as outputs with active-low semantics
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "watering_system";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    ret = gpiod_line_request(line17, &config, 1); // Initial value HIGH (inactive)
    ret = gpiod_line_request(line18, &config, 1);
    ret = gpiod_line_request(line27, &config, 1);
    ret = gpiod_line_request(line22, &config, 1);

    if (ret < 0) {
        fprintf(stderr, "Error: Could not request GPIO lines as outputs\n");
        cleanup_gpio();
        return -1;
    }

    return 0;
}

// Function to set GPIO line value
int set_gpio_output(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set GPIO line value\n");
        return -1;
    }
    return 0;
}

// Function to activate a relay for a specified duration
int activate_relay(struct gpiod_line *line, int duration) {
    int ret = set_gpio_output(line, 0); // Activate relay (active-low)
    if (ret < 0) return -1;
    sleep(duration);
    ret = set_gpio_output(line, 1); // Deactivate relay
    if (ret < 0) return -1;
    return 0;
}

// Function to log watering event to file
int log_watering_event(int gpio_pin) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    // Open log file in append mode
    fp = fopen("watering_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        return -1;
    }

    // Write log entry
    fprintf(fp, "%s - GPIO %d activated\n", timestamp, gpio_pin);

    // Close log file
    fclose(fp);
    return 0;
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    if (line17) {
        gpiod_line_release(line17);
    }
    if (line18) {
        gpiod_line_release(line18);
    }
    if (line27) {
        gpiod_line_release(line27);
    }
    if (line22) {
        gpiod_line_release(line22);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signum) {
    printf("Received signal %d, cleaning up...\n", signum);
    cleanup_gpio();
    exit(0);
}

int main() {
    int ret;
    time_t start_time = time(NULL);
    time_t current_time;
    int gpio_pins[] = {GPIO17, GPIO18, GPIO27, GPIO22};
    int num_pins = sizeof(gpio_pins) / sizeof(gpio_pins[0]);
    int i;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        return 1;
    }

