    while (1) {
        current_time = time(NULL);
        double elapsed_time = difftime(current_time, start_time);

        for (i = 0; i < num_pins; i++) {
            // Calculate the watering time for each relay
            int watering_time = (int)(elapsed_time % TOTAL_DURATION);

            // Check if it's time to water this relay
            if (watering_time == 0) {
                printf("Watering GPIO %d...\n", gpio_pins[i]);
                ret = activate_relay((gpio_pins[i] == GPIO17) ? line17 : ((gpio_pins[i] == GPIO18) ? line18 : ((gpio_pins[i] == GPIO27) ? line27 : line22)), WATERING_DURATION);
                if (ret < 0) {
                    fprintf(stderr, "Error: Failed to activate relay for GPIO %d\n", gpio_pins[i]);
                } else {
                    ret = log_watering_event(gpio_pins[i]);
                    if (ret < 0) {
                        fprintf(stderr, "Error: Failed to log watering event for GPIO %d\n", gpio_pins[i]);
                    }
                }
            }
        }

        sleep(POLLING_INTERVAL);
    }

    return 0;
}

