#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_GPIO 17
#define RELAY2_GPIO 18
#define RELAY3_GPIO 27
#define RELAY4_GPIO 22

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Define sunrise duration (in seconds)
#define SUNRISE_DURATION 1800

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int set_gpio_mode(int gpio, int mode);
int set_pwm_frequency(int gpio, int frequency);
int set_pwm_duty_cycle(int gpio, int duty_cycle);
int calculate_duty_cycle(int time_elapsed);
void log_event(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    log_event("Signal received, shutting down...");
}

// Function to initialize the pigpio library
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to set the mode of a GPIO pin
int set_gpio_mode(int gpio, int mode) {
    if (gpioSetMode(gpio, mode) != 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

// Function to set the PWM frequency for a GPIO pin
int set_pwm_frequency(int gpio, int frequency) {
    if (gpioSetPWMfrequency(gpio, frequency) != 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

// Function to set the PWM duty cycle for a GPIO pin
int set_pwm_duty_cycle(int gpio, int duty_cycle) {
    if (gpioPWM(gpio, duty_cycle) != 0) {
        fprintf(stderr, "Failed to set PWM duty cycle for GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

// Function to calculate the duty cycle based on time elapsed
int calculate_duty_cycle(int time_elapsed) {
    // Linearly increase duty cycle from 0 to 255 over SUNRISE_DURATION seconds
    return (int)(((float)time_elapsed / SUNRISE_DURATION) * 255.0);
}

// Function to log events to a file
void log_event(const char *message) {
    FILE *fp = fopen("smart_lighting.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Set GPIO modes to output
    if (set_gpio_mode(RELAY1_GPIO, PI_OUTPUT) != 0 ||
        set_gpio_mode(RELAY2_GPIO, PI_OUTPUT) != 0 ||
        set_gpio_mode(RELAY3_GPIO, PI_OUTPUT) != 0 ||
        set_gpio_mode(RELAY4_GPIO, PI_OUTPUT) != 0) {
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency for all GPIO pins
    if (set_pwm_frequency(RELAY1_GPIO, PWM_FREQUENCY) != 0 ||
        set_pwm_frequency(RELAY2_GPIO, PWM_FREQUENCY) != 0 ||
        set_pwm_frequency(RELAY3_GPIO, PWM_FREQUENCY) != 0 ||
        set_pwm_frequency(RELAY4_GPIO, PWM_FREQUENCY) != 0) {
        gpioTerminate();
        return 1;
    }

    log_event("Smart lighting system started");

    // Sunrise simulation loop
    for (int i = 0; i <= SUNRISE_DURATION && program_running; ++i) {
        // Calculate duty cycle
        int duty_cycle = calculate_duty_cycle(i);

        // Set duty cycle for all relays
        if (set_pwm_duty_cycle(RELAY1_GPIO, duty_cycle) != 0 ||
            set_pwm_duty_cycle(RELAY2_GPIO, duty_cycle) != 0 ||
            set_pwm_duty_cycle(RELAY3_GPIO, duty_cycle) != 0 ||
            set_pwm_duty_cycle(RELAY4_GPIO, duty_cycle) != 0) {
            gpioTerminate();
            return 1;
        }

        // Log the current duty cycle
        char log_message[100];
        snprintf(log_message, sizeof(log_message), "Duty cycle set to %d", duty_cycle);
        log_event(log_message);

        // Wait for 1 second
        gpioDelay(1000); // Delay in milliseconds
    }

    // Ensure all relays are off after sunrise
    if (program_running) {
        log_event("Sunrise simulation complete");
        set_pwm_duty_cycle(RELAY1_GPIO, 0);
        set_pwm_duty_cycle(RELAY2_GPIO, 0);
        set_pwm_duty_cycle(RELAY3_GPIO, 0);
        set_pwm_duty_cycle(RELAY4_GPIO, 0);
        log_event("All relays turned off");
    }

    // Terminate pigpio
    gpioTerminate();
    log_event("Smart lighting system stopped");

    return 0;
}

