#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <math.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define SMPLRT_DIV 0x19
#define GYRO_CONFIG 0x1B
#define WHO_AM_I 0x75
#define GYRO_XOUT_H 0x43

// LED GPIO pin
#define LED_PIN 17

// Circular buffer size
#define BUFFER_SIZE 100

// Structure to hold gyroscope data and timestamp
typedef struct {
    int16_t x, y, z;
    struct timespec timestamp;
} gyro_data_t;

// Circular buffer
gyro_data_t gyro_buffer[BUFFER_SIZE];
int buffer_index = 0;

// I2C handle
int i2c_handle;

// Function prototypes
int init_mpu6050();
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z);
void add_to_buffer(int16_t x, int16_t y, int16_t z);
void check_thresholds(int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Initialize MPU-6050
    if (init_mpu6050() != 0) {
        fprintf(stderr, "MPU-6050 initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;

    // Main loop
    while (program_running) {
        // Read gyroscope data
        if (read_gyro_data(&x, &y, &z) == 0) {
            // Add data to circular buffer
            add_to_buffer(x, y, z);

            // Check thresholds and control LED
            check_thresholds(x, y, z);
        } else {
