#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 8
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define GYRO_XOUT_H 0x43
#define GYRO_XOUT_L 0x44
#define GYRO_YOUT_H 0x45
#define GYRO_YOUT_L 0x46
#define GYRO_ZOUT_H 0x47
#define GYRO_ZOUT_L 0x48
#define GYRO_SCALE 131.0f // Sensitivity scale factor for ±250 dps range
#define RETRY_COUNT 3
#define LOG_FILE "gyro_log.txt"

// Global variables
static int spi_fd = -1;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z);
float convert_to_dps(int16_t raw_value);
int log_data(float x_rate, float y_rate, float z_rate);
void signal_handler(int sig);
void cleanup(void);

// SPI initialization function
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device: %s\n", strerror(errno));
        return -1;
    }

    // Set SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    // Set bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting bits per word: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    // Set SPI speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    return 0;
}

// SPI transfer function with retry mechanism
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    int ret;
    for (int i = 0; i < RETRY_COUNT; ++i) {
        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer);
        if (ret >= 0) {
            return 0; // Success
        }
        fprintf(stderr, "SPI transfer failed (attempt %d): %s\n", i + 1, strerror(errno));
        usleep(10000); // Wait 10ms before retrying
    }

    fprintf(stderr, "SPI transfer failed after %d attempts.\n", RETRY_COUNT);
    return -1; // Failure after retries
}

// Function to read gyroscope data
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t tx_buf[1] = {GYRO_XOUT_H | 0x80}; // Read command for XOUT_H
    uint8_t rx_buf[6]; // Buffer to store received data

    if (spi_transfer(tx_buf, rx_buf, 7) != 0) { // Send read command and receive 6 bytes
        fprintf(stderr, "Error reading gyroscope data.\n");
        return -1;
    }

    // Combine high and low bytes to form 16-bit values
    *x = (int16_t)((rx_buf[1] << 8) | rx_buf[2]);
    *y = (int16_t)((rx_buf[3] << 8) | rx_buf[4]);
    *z = (int16_t)((rx_buf[5] << 8) | rx_buf[6]);

    return 0;
}

// Function to convert raw data to degrees per second
float convert_to_dps(int16_t raw_value) {
    return (float)raw_value / GYRO_SCALE;
}

// Function to log data to file
int log_data(float x_rate, float y_rate, float z_rate) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        fprintf(stderr, "Error getting timestamp: %s\n", strerror(errno));
        return -1;
    }

    char timestamp[30];
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%09ldZ", ts.tv_nsec);

    if (fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, x_rate, y_rate, z_rate) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received (%d). Terminating...\n", sig);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup(void) {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (gpio_line != NULL) {
        gpiod_line_release(gpio_line);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main(void) {
    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    struct gpiod_chip *chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    gpio_line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!gpio_line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(gpio_line, "gyro_cs", 1) < 0) {
        fprintf(stderr, "Error requesting GPIO line as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Initialize SPI
    if (spi_init() != 0) {
        fprintf(stderr, "SPI initialization failed.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    int16_t x_raw, y_raw, z_raw;
    float x_rate, y_rate, z_rate;

    // Main loop
    while (!terminate) {
        // Assert chip select
        if (gpiod_line_set_value(gpio_line, 0) < 0) {
            fprintf(stderr, "Error setting GPIO line value: %s\n", strerror(errno));
            cleanup();
            return 1;
        }

        // Read gyroscope data
        if (read_gyro_data(&x_raw, &y_raw, &z_raw) == 0) {
            // Convert to degrees per second
            x_rate = convert_to_dps(x_raw);
            y_rate = convert_to_dps(y_raw);
            z_rate = convert_to_dps(z_raw);

            // Log data
            if (log_data(x_rate, y_rate, z_rate) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Error reading gyro data.\n");
        }

        // De-assert chip select
        if (gpiod_line_set_value(gpio_line, 1) < 0) {
            fprintf(stderr, "Error setting GPIO line value: %s\n", strerror(errno));
            cleanup();
            return 1;
        }

        usleep(10000); // 10 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

