#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define CS_PIN 8
#define LED_PIN 17
#define SPI_SPEED 3900000 // 3.9 MHz
#define GYRO_SENSITIVITY 131.0 // LSB/deg/s
#define BUFFER_SIZE 64
#define THRESHOLD 200.0 // deg/s
#define BLINK_DELAY 500 // ms

// MPU-6050 Registers
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47

// Data structure for circular buffer
typedef struct {
    struct timespec timestamp;
    float x;
    float y;
    float z;
} gyro_data_t;

// Global variables
int spi_fd = -1;
int gpio_cs_fd = -1;
gyro_data_t gyro_buffer[BUFFER_SIZE];
int buffer_index = 0;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int spi_init(const char *device, int speed, int mode);
int cs_assert(int gpio_cs_fd);
int cs_deassert(int gpio_cs_fd);
int read_gyro_data(int spi_fd, int gyro_x, int gyro_y, int gyro_z);
void convert_to_degrees(int16_t raw_x, int16_t raw_y, int16_t raw_z, float *deg_x, float *deg_y, float *deg_z);
void store_data(gyro_data_t *buffer, int buffer_size, struct timespec timestamp, float x, float y, float z);
void check_threshold_and_blink(float x, float y, float z);
void print_buffer(gyro_data_t *buffer, int buffer_size);
void signal_handler(int signal);
void cleanup();

// SPI Initialization
int spi_init(const char *device, int speed, int mode) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    int mode_set = mode;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_set) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set SPI speed
    int speed_set = speed;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_set) == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// Chip Select Assertion
int cs_assert(int gpio_cs_fd) {
    if (gpioWrite(gpio_cs_fd, 0) != 0) { // CS low
        perror("Error asserting CS");
        return -1;
    }
    return 0;
}

// Chip Select De-assertion
int cs_deassert(int gpio_cs_fd) {
    if (gpioWrite(gpio_cs_fd, 1) != 0) { // CS high
        perror("Error de-asserting CS");
        return -1;
    }
    return 0;
}

// Read Gyroscope Data
int read_gyro_data(int spi_fd, int gyro_x, int gyro_y, int gyro_z) {
    uint8_t tx_buf[6];
    uint8_t rx_buf[6];
    struct spi_ioc_transfer transfer[1];

    // Construct the transmit buffer to read the gyroscope data
    tx_buf[0] = 0x80 | GYRO_XOUT_H; // Read command for X axis
    tx_buf[1] = 0x00; // Dummy byte for reading X axis
    tx_buf[2] = 0x00; // Dummy byte for reading Y axis
    tx_buf[3] = 0x00; // Dummy byte for reading Y axis
    tx_buf[4] = 0x00; // Dummy byte for reading Z axis
    tx_buf[5] = 0x00; // Dummy byte for reading Z axis

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 6;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = 8;

    if (cs_assert(gpio_cs_fd) != 0) return -1;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error during SPI transfer");
        cs_deassert(gpio_cs_fd);
        return -1;
    }

    if (cs_deassert(gpio_cs_fd) != 0) return -1;

    // Combine high and low bytes to form 16-bit values
    int16_t raw_x = (rx_buf[0] << 8) | rx_buf[1];
    int16_t raw_y = (rx_buf[2] << 8) | rx_buf[3];
    int16_t raw_z = (rx_buf[4] << 8) | rx_buf[5];

    return (raw_x << 16) | (raw_y << 8) | raw_z; // Return combined data
}

// Convert Raw Data to Degrees per Second
void convert_to_degrees(int16_t raw_x, int16_t raw_y, int16_t raw_z, float *deg_x, float *deg_y, float *deg_z) {
    *deg_x = (float)raw_x / GYRO_SENSITIVITY;
    *deg_y = (float)raw_y / GYRO_SENSITIVITY;
    *deg_z = (float)raw_z / GYRO_SENSITIVITY;
}

// Store Data in Circular Buffer
void store_data(gyro_data_t *buffer, int buffer_size, struct timespec timestamp, float x, float y, float z) {
    buffer[buffer_index].timestamp = timestamp;
    buffer[buffer_index].x = x;
    buffer[buffer_index].y = y;
    buffer[buffer_index].z = z;

    buffer_index = (buffer_index + 1) % buffer_size;
}

// Check Threshold and Blink LED
void check_threshold_and_blink(float x, float y, float z) {
    if (fabs(x) > THRESHOLD || fabs(y) > THRESHOLD || fabs(z) > THRESHOLD) {
        gpioWrite(LED_PIN, 1); // LED on
        gpioDelay(BLINK_DELAY * 1000); // Delay in microseconds
        gpioWrite(LED_PIN, 0); // LED off
        gpioDelay(BLINK_DELAY * 1000); // Delay in microseconds
    }
}

// Print Circular Buffer as CSV
void print_buffer(gyro_data_t *buffer, int buffer_size) {
    for (int i = 0; i < buffer_size; i++) {
        struct timespec ts = buffer[i].timestamp;
        printf("%ld.%09ld,%f,%f,%f\n", ts.tv_sec, ts.tv_nsec, buffer[i].x, buffer[i].y, buffer[i].z);
    }
}

// Signal Handler for Ctrl+C
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        program_running = 0;
    }
}

// Cleanup Function
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (gpio_cs_fd != -1) {
        gpioWrite(gpio_cs_fd, 1); // De-assert CS
        gpioSetMode(gpio_cs_fd, PI_INPUT); // Set back to input
    }
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set CS pin as output
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_SPEED, 0); // Mode 0
    if (spi_fd < 0) {
        cleanup();
        return 1;
    }

    // Open GPIO chip for CS control
    char gpio_chip[64];
    snprintf(gpio_chip, sizeof(gpio_chip), "/dev/gpiochip0");
    int gpio_chip_fd = open(gpio_chip, O_RDWR);
    if (gpio_chip_fd < 0) {
        perror("Error opening GPIO chip");
        cleanup();
        return 1;
    }

    int gpio_cs_pin = CS_PIN; // GPIO8
    int gpio_cs_pin_num = 8; // GPIO number

    // Export GPIO pin for CS control
    char gpio_export[64];
    snprintf(gpio_export, sizeof(gpio_export), "/sys/class/gpio/export");
    int export_fd = open(gpio_export, O_WRONLY);
    if (export_fd < 0) {
        perror("Error opening GPIO export");
        cleanup();
        return 1;
    }
    char pin_str[4];
    snprintf(pin_str, sizeof(pin_str), "%d", gpio_cs_pin_num);
    if (write(export_fd, pin_str, strlen(pin_str)) < 0) {
        perror("Error writing to GPIO export");
        close(export_fd);
        cleanup();
        return 1;
    }
    close(export_fd);

    // Set GPIO direction to output
    char gpio_direction[64];
    snprintf(gpio_direction, sizeof(gpio_direction), "/sys/class/gpio/gpio%d/direction", gpio_cs_pin_num);
    int direction_fd = open(gpio_direction, O_WRONLY);
    if (direction_fd < 0) {
        perror("Error opening GPIO direction");
        cleanup();
        return 1;
    }
    if (write(direction_fd, "out", 3) < 0) {
        perror("Error writing to GPIO direction");
        close(direction_fd);
        cleanup();
        return 1;
    }
    close(direction_fd);

    // Open GPIO value file for CS control
    char gpio_value[64];
    snprintf(gpio_value, sizeof(gpio_value), "/sys/class/gpio/gpio%d/value", gpio_cs_pin_num);
    gpio_cs_fd = open(gpio_value, O_WRONLY);
    if (gpio_cs_fd < 0) {
        perror("Error opening GPIO value");
        cleanup();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Starting data acquisition...\n");

    while (program_running) {
        struct timespec ts;
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("clock_gettime");
            break;
        }

        int combined_data = read_gyro_data(spi_fd, GYRO_XOUT_H, GYRO_YOUT_H, GYRO_ZOUT_H);
        if (combined_data == -1) {
            fprintf(stderr, "Error reading gyro data, retrying...\n");
            gpioDelay(10000); // 10ms delay
            continue;
        }

        int16_t raw_x = (combined_data >> 16) & 0xFFFF;
        int16_t raw_y = (combined_data >> 8) & 0xFF;
        int16_t raw_z = combined_data & 0xFF;

        float deg_x, deg_y, deg_z;
        convert_to_degrees(raw_x, raw_y, raw_z, &deg_x, &deg_y, &deg_z);

        store_data(gyro_buffer, BUFFER_SIZE, ts, deg_x, deg_y, deg_z);
        check_threshold_and_blink(deg_x, deg_y, deg_z);

        gpioDelay(10000); // 10ms delay
    }

    // Print the buffer before exiting
    print_buffer(gyro_buffer, BUFFER_SIZE);

    cleanup();
    return 0;
}

