    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C connection\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("tilt_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    int16_t accel_x, accel_y, accel_z;
    double roll, pitch;

    // Main loop
    while (program_running) {
        // Read raw data
        if (read_raw_data(&accel_x, &accel_y, &accel_z) == 0) {
            // Calculate roll and pitch
            roll = calculate_roll(accel_y, accel_z);
            pitch = calculate_pitch(accel_x, accel_y, accel_z);

            // Control LED
            control_led(roll, pitch);

            // Log data
            log_data(roll, pitch);

            // Print to console
            printf("Roll: %.2f, Pitch: %.2f\n", roll, pitch);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data. Retrying...\n");
        }

        // Delay for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup
    gpioWrite(LED_GPIO, 0); // Turn off LED
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

