#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SI1145_ADDR 0x5A
#define AMBIENT_LIGHT_REG 0x20
#define PROXIMITY_REG 0x22
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define LOG_FILE "biometric_log.txt"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define PROXIMITY_THRESHOLD 100

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int read_sensor_data(int fd, uint16_t *ambient_light, uint16_t *proximity);
void log_data(FILE *fp, uint16_t ambient_light, uint16_t proximity);
void set_gpio_value(struct gpiod_line *line, int value);
void signal_handler(int sig);
int setup();
void cleanup();

// I2C read function with retry
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    int retries = RETRY_COUNT;
    int result = -1;

    while (retries > 0) {
        if (write(fd, &reg, 1) != 1) {
            perror("I2C write (register select) failed");
            retries--;
            usleep(RETRY_DELAY_MS * 1000); // 10ms delay
            continue;
        }

        if (read(fd, value, 1) != 1) {
            perror("I2C read failed");
            retries--;
            usleep(RETRY_DELAY_MS * 1000); // 10ms delay
            continue;
        }

        result = 0; // Success
        break;
    }

    if (result != 0) {
        fprintf(stderr, "I2C read failed after %d retries\n", RETRY_COUNT);
    }

    return result;
}

// I2C write function with retry
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    int retries = RETRY_COUNT;
    int result = -1;
    uint8_t buf[2];

    buf[0] = reg;
    buf[1] = value;

    while (retries > 0) {
        if (write(fd, buf, 2) != 2) {
            perror("I2C write failed");
            retries--;
            usleep(RETRY_DELAY_MS * 1000); // 10ms delay
            continue;
        }

        result = 0; // Success
        break;
    }

    if (result != 0) {
        fprintf(stderr, "I2C write failed after %d retries\n", RETRY_COUNT);
    }

    return result;
}

// Read sensor data
int read_sensor_data(int fd, uint16_t *ambient_light, uint16_t *proximity) {
    uint8_t ambient_light_lsb, ambient_light_msb, proximity_lsb, proximity_msb;

    if (i2c_read_reg(fd, AMBIENT_LIGHT_REG, &ambient_light_lsb) != 0) return -1;
    if (i2c_read_reg(fd, AMBIENT_LIGHT_REG + 1, &ambient_light_msb) != 0) return -1;
    if (i2c_read_reg(fd, PROXIMITY_REG, &proximity_lsb) != 0) return -1;
    if (i2c_read_reg(fd, PROXIMITY_REG + 1, &proximity_msb) != 0) return -1;

    *ambient_light = (ambient_light_msb << 8) | ambient_light_lsb;
    *proximity = (proximity_msb << 8) | proximity_lsb;

    return 0;
}

// Log data to file
void log_data(FILE *fp, uint16_t ambient_light, uint16_t proximity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,AmbientLight:%u,Proximity:%u\n", timestamp, ambient_light, proximity);
    fflush(fp); // Ensure data is written to disk immediately
}

// Set GPIO value
void set_gpio_value(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        perror("Failed to set GPIO value");
    }
}

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Setup function
int setup() {
    // I2C setup
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return -1;
    }

    // GPIO setup
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_LINE);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return -1;
    }

    if (gpiod_line_request_output(gpio_line, "biometric_sensor", 0) < 0) {
        perror("Failed to request GPIO line for output");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return -1;
    }

    // Log file setup
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
}

int main() {
    uint16_t ambient_light, proximity;

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Setup
    if (setup() != 0) {
        fprintf(stderr, "Setup failed, exiting\n");
        return 1;
    }

    // Main loop
    while (!terminate) {
        if (read_sensor_data(i2c_fd, &ambient_light, &proximity) == 0) {
            log_data(log_file, ambient_light, proximity);
            set_gpio_value(gpio_line, (proximity > PROXIMITY_THRESHOLD) ? 1 : 0);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        usleep(100000); // 100ms delay
    }

    // Cleanup
    cleanup();

    return 0;
}

