        perror("Failed to open log file");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
}

int main() {
    uint16_t ambient_light, proximity;

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Setup
    if (setup() != 0) {
        fprintf(stderr, "Setup failed, exiting\n");
        return 1;
    }

    // Main loop
    while (!terminate) {
        if (read_sensor_data(i2c_fd, &ambient_light, &proximity) == 0) {
            log_data(log_file, ambient_light, proximity);
            set_gpio_value(gpio_line, (proximity > PROXIMITY_THRESHOLD) ? 1 : 0);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        usleep(100000); // 100ms delay
    }

    // Cleanup
    cleanup();

    return 0;
}

