#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define ALERT_PIN 17

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Alert duration in seconds
#define ALERT_DURATION 2

// Global variables
FILE *log_file = NULL;
volatile int running = 1;

// Function prototypes
void sensor_callback(int gpio, int level, uint32_t tick, void *user_data);
void signal_handler(int signal);
int log_event(const char *message);

// Structure to hold sensor state
typedef struct {
    int last_level;
    uint32_t last_tick;
} sensor_state_t;

sensor_state_t sensor1_state = {0, 0};
sensor_state_t sensor2_state = {0, 0};

// Callback function for both sensors
void sensor_callback(int gpio, int level, uint32_t tick, void *user_data) {
    uint32_t current_tick = gpioTick();
    uint32_t diff = current_tick - sensor1_state.last_tick;

    if (diff < DEBOUNCE_TIME * 1000) {
        return; // Debounce
    }

    if (gpio == SENSOR_1_PIN) {
        sensor1_state.last_level = level;
        sensor1_state.last_tick = current_tick;
    } else if (gpio == SENSOR_2_PIN) {
        sensor2_state.last_level = level;
        sensor2_state.last_tick = current_tick;
    }

    if (sensor1_state.last_level == 1 && sensor2_state.last_level == 1) {
        // Both sensors are HIGH
        gpioWrite(ALERT_PIN, 1); // Set ALERT_PIN HIGH
        gpioDelay(ALERT_DURATION * 1000000); // Wait for ALERT_DURATION seconds
        gpioWrite(ALERT_PIN, 0); // Set ALERT_PIN LOW

        // Log the seismic event
        if (log_event("Seismic event detected!") != 0) {
            fprintf(stderr, "Error logging seismic event.\n");
        }
    }
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    // Set ALERT_PIN LOW
    gpioWrite(ALERT_PIN, 0);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Function to log events to a file
int log_event(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s - %s\n", timestamp, message);
    fflush(log_file); // Ensure the data is written to the file immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetMode(ALERT_PIN, PI_OUTPUT);

    // Set pull-down resistors
    gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN);

    // Open the log file
    log_file = fopen("seismic_events.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Register callbacks for both sensors
    if (gpioSetAlertFuncEx(SENSOR_1_PIN, sensor_callback, NULL) != 0) {
        fprintf(stderr, "Error registering callback for sensor 1!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    if (gpioSetAlertFuncEx(SENSOR_2_PIN, sensor_callback, NULL) != 0) {
        fprintf(stderr, "Error registering callback for sensor 2!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Seismic monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        sleep(1); // Sleep to reduce CPU usage
    }

    return 0;
}

