#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define LED_GPIO 17
#define BUFFER_SIZE 100
#define ANGULAR_RATE_THRESHOLD 20.0 // deg/s

// ADXRS290 Register Addresses
#define RATE_XL 0x02
#define RATE_XH 0x03

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure for storing timestamped data
typedef struct {
    struct timespec timestamp;
    int16_t angular_rate;
} DataPoint;

// Circular buffer
DataPoint circular_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int read_gyroscope_data(int spi_handle, int16_t *angular_rate);
double convert_to_degrees_per_second(int16_t raw_data);
void store_data(struct timespec timestamp, int16_t angular_rate);
void check_threshold_and_control_led(double angular_rate);
void signal_handler(int signal);

// Function to read gyroscope data from ADXRS290
int read_gyroscope_data(int spi_handle, int16_t *angular_rate) {
    char tx_buffer[2];
    char rx_buffer[2];
    int result;

    // Set MSB of register address to 1 for read operation
    tx_buffer[0] = (RATE_XL | 0x80) << 1; // Shift left to get the correct byte order
    tx_buffer[1] = 0x00; // Dummy byte for reading the high byte

    result = spiXfer(spi_handle, tx_buffer, rx_buffer, 2);

    if (result != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1; // Indicate failure
    }

    // Combine the two bytes to form the 16-bit angular rate
    *angular_rate = (int16_t)((rx_buffer[0] << 8) | rx_buffer[1]);

    return 0; // Indicate success
}

// Function to convert raw data to degrees per second
double convert_to_degrees_per_second(int16_t raw_data) {
    return (double)raw_data / 200.0; // 200 LSB/deg/s
}

// Function to store data in the circular buffer
void store_data(struct timespec timestamp, int16_t angular_rate) {
    circular_buffer[buffer_index].timestamp = timestamp;
    circular_buffer[buffer_index].angular_rate = angular_rate;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to check the angular rate threshold and control the LED
void check_threshold_and_control_led(double angular_rate) {
    if (fabs(angular_rate) > ANGULAR_RATE_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn on LED
    } else {
        gpioWrite(LED_GPIO, 0); // Turn off LED
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    int result;
    int16_t raw_angular_rate;
    double angular_rate_deg_per_sec;
    struct timespec timestamp;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0); // Ensure LED is off initially

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read gyroscope data
