#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the lamps
#define LAMP1_GPIO 17
#define LAMP2_GPIO 18
#define LAMP3_GPIO 27

// Define PWM frequency
#define PWM_FREQUENCY 100

// Define PWM range
#define PWM_RANGE 255

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
    program_running = 0;
}

// Function to set the PWM duty cycle for a given GPIO pin
int set_pwm_duty_cycle(int gpio, int duty_cycle) {
    if (gpioPWM(gpio, duty_cycle) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle for GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

// Function to fade a lamp from full brightness to off
int fade_lamp(int gpio, int duration_seconds) {
    int i;
    int duty_cycle;
    float step_size = (float)PWM_RANGE / (float)duration_seconds;

    printf("Fading lamp on GPIO %d for %d seconds...\n", gpio, duration_seconds);

    for (i = PWM_RANGE; i >= 0; i -= (int)step_size) {
        if (!program_running) {
            break;
        }
        duty_cycle = (i < 0) ? 0 : (int)i; // Ensure duty cycle is within range
        if (set_pwm_duty_cycle(gpio, duty_cycle) != 0) {
            return -1;
        }
        gpioDelay(1000); // Delay for 1 millisecond
    }

    printf("Lamp on GPIO %d faded to off.\n", gpio);
    return 0;
}

int main(int argc, char *argv[]) {
    int duration_seconds;
    int i;

    // Check for command-line argument
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <duration_seconds>\n", argv[0]);
        return 1;
    }

    // Parse command-line argument
    duration_seconds = atoi(argv[1]);

    // Validate duration
    if (duration_seconds < 1 || duration_seconds > 3600) {
        fprintf(stderr, "Error: Duration must be between 1 and 3600 seconds.\n");
        return 1;
    }

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers for graceful termination
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set GPIO pins as outputs
    gpioSetMode(LAMP1_GPIO, PI_OUTPUT);
    gpioSetMode(LAMP2_GPIO, PI_OUTPUT);
    gpioSetMode(LAMP3_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(LAMP1_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(LAMP2_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(LAMP3_GPIO, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(LAMP1_GPIO, PWM_RANGE);
    gpioSetPWMrange(LAMP2_GPIO, PWM_RANGE);
    gpioSetPWMrange(LAMP3_GPIO, PWM_RANGE);

    // Fade each lamp sequentially
    int lamps[] = {LAMP1_GPIO, LAMP2_GPIO, LAMP3_GPIO};
    int num_lamps = sizeof(lamps) / sizeof(lamps[0]);

    for (i = 0; i < num_lamps; i++) {
        if (!program_running) {
            break;
        }
        if (fade_lamp(lamps[i], duration_seconds) != 0) {
            fprintf(stderr, "Error fading lamp on GPIO %d\n", lamps[i]);
            break;
        }
    }

    // Turn off all lamps
    printf("Turning off all lamps...\n");
    set_pwm_duty_cycle(LAMP1_GPIO, 0);
    set_pwm_duty_cycle(LAMP2_GPIO, 0);
    set_pwm_duty_cycle(LAMP3_GPIO, 0);

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

