// Define GPIO pins for the relays
#define RED_PIN   17
#define YELLOW_PIN 22
#define GREEN_PIN  23
#define BLUE_PIN   24

// Define the duration of each state in seconds
#define RED_DURATION   10
#define RED_YELLOW_DURATION 2
#define GREEN_DURATION 10
#define YELLOW_DURATION 3

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to set the state of a relay
int set_relay_state(int pin, int state) {
    int result = gpioWrite(pin, state);
    if (result != 0) {
        fprintf(stderr, "Error writing to GPIO %d: %d\n", pin, result);
        return -1;
    }
    return 0;
}

// Function to control the traffic light sequence
void traffic_light_sequence() {
    // Red state
    if (set_relay_state(RED_PIN, 0) != 0) return; // Active low
    if (set_relay_state(YELLOW_PIN, 1) != 0) return; // Active low
    if (set_relay_state(GREEN_PIN, 1) != 0) return; // Active low
    if (set_relay_state(BLUE_PIN, 1) != 0) return; // Active low
    printf("State: Red\n");
    sleep(RED_DURATION);

    // Red + Yellow state
    if (set_relay_state(YELLOW_PIN, 0) != 0) return; // Active low
    printf("State: Red + Yellow\n");
    sleep(RED_YELLOW_DURATION);

    // Green state
    if (set_relay_state(RED_PIN, 1) != 0) return; // Active low
    if (set_relay_state(YELLOW_PIN, 1) != 0) return; // Active low
    if (set_relay_state(GREEN_PIN, 0) != 0) return; // Active low
    if (set_relay_state(BLUE_PIN, 1) != 0) return; // Active low
    printf("State: Green\n");
    sleep(GREEN_DURATION);

    // Yellow state
    if (set_relay_state(GREEN_PIN, 1) != 0) return; // Active low
    if (set_relay_state(BLUE_PIN, 1) != 0) return; // Active low
    printf("State: Yellow\n");
    sleep(YELLOW_DURATION);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(YELLOW_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set initial state to all relays OFF
    if (set_relay_state(RED_PIN, 1) != 0) return 1;   // Active low
    if (set_relay_state(YELLOW_PIN, 1) != 0) return 1; // Active low
    if (set_relay_state(GREEN_PIN, 1) != 0) return 1;  // Active low
    if (set_relay_state(BLUE_PIN, 1) != 0) return 1;   // Active low

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        traffic_light_sequence();
    }

    // Cleanup and exit
    gpioTerminate();
    return 0;
}

