#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define RELAY_GPIO 17
#define MPR121_ADDR 0x5A
#define I2C_BUS 1

// MPR121 Registers
#define MPR121_RESET 0x80
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_ELECTRODE_ENABLE 0x5D
#define MPR121_TOUCH_THRESHOLD 0x41
#define MPR121_RELEASE_THRESHOLD 0x42
#define MPR121_DEBOUNCE 0x5B
#define MPR121_CHARGE_TIME 0x5C
#define MPR121_RUN_MODE 0x5E

// Global variables
int i2c_handle;
FILE *log_file;
int relay_state = 0; // 0 = off, 1 = on
int touch_detected = 0;
struct timespec last_touch_time;

// Function prototypes
int initialize_pigpio();
int initialize_i2c();
int configure_mpr121();
int read_touch_status();
void toggle_relay();
void log_message(const char *message);
void signal_handler(int signal);

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        log_message("pigpio initialisation failed");
        return -1;
    }
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Initialize relay to OFF
    return 0;
}

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        log_message("I2C open failed");
        return -1;
    }
    return 0;
}

// Function to configure MPR121
int configure_mpr121() {
    // Reset MPR121
    if (i2cWriteByteData(i2c_handle, MPR121_RESET, 0x63) < 0) {
        log_message("MPR121 reset failed");
        return -1;
    }
    gpioDelay(100); // Wait for reset

    // Stop mode
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG, 0x00) < 0) {
        log_message("MPR121 stop mode failed");
        return -1;
    }

    // Enable electrode 0
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_ENABLE, 0x01) < 0) {
        log_message("MPR121 electrode enable failed");
        return -1;
    }

    // Touch threshold
    if (i2cWriteByteData(i2c_handle, MPR121_TOUCH_THRESHOLD, 0x0A) < 0) {
        log_message("MPR121 touch threshold failed");
        return -1;
    }

    // Release threshold
    if (i2cWriteByteData(i2c_handle, MPR121_RELEASE_THRESHOLD, 0x08) < 0) {
        log_message("MPR121 release threshold failed");
        return -1;
    }

    // Debounce
    if (i2cWriteByteData(i2c_handle, MPR121_DEBOUNCE, 0x21) < 0) {
        log_message("MPR121 debounce failed");
        return -1;
    }

    // Charge time
    if (i2cWriteByteData(i2c_handle, MPR121_CHARGE_TIME, 0x0D) < 0) {
        log_message("MPR121 charge time failed");
        return -1;
    }

    // Run mode
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG, 0x0D) < 0) {
        log_message("MPR121 run mode failed");
        return -1;
    }

    return 0;
}

// Function to read touch status from MPR121
int read_touch_status() {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, MPR121_TOUCHSTATUS_L, buf, 2) != 2) {
        log_message("MPR121 read failed");
        return -1;
    }
    return ((buf[1] << 8) | buf[0]);
}

// Function to toggle the relay state
void toggle_relay() {
    relay_state = !relay_state;
    gpioWrite(RELAY_GPIO, relay_state);
    char message[50];
    sprintf(message, "Relay toggled to %d", relay_state);
    log_message(message);
}

// Function to log messages with timestamps
void log_message(const char *message) {
    time_t now = time(NULL);
