#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18
#define LED_PIN 23

// Define debounce parameters
#define DEBOUNCE_READS 3
#define DEBOUNCE_DELAY_MS 50

// Define log file path
#define LOG_FILE "flame_log.txt"

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *flame_line, *buzzer_line, *led_line;
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_flame_sensor(struct gpiod_line *line);
int debounce(struct gpiod_line *line);
void activate_alarm(struct gpiod_line *buzzer_line, struct gpiod_line *led_line);
void deactivate_alarm(struct gpiod_line *buzzer_line, struct gpiod_line *led_line);
void log_event(const char *message);
void signal_handler(int sig);
int setup_gpio(int pin, const char *consumer, int direction);
void cleanup_gpio(void);

// Function to read the flame sensor value
int read_flame_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading flame sensor value: %d\n", value);
        return -1; // Indicate error
    }
    return value;
}

// Function to debounce the flame sensor reading
int debounce(struct gpiod_line *line) {
    int reads[DEBOUNCE_READS];
    int i, sum = 0;

    for (i = 0; i < DEBOUNCE_READS; i++) {
        reads[i] = read_flame_sensor(line);
        if (reads[i] < 0) return -1; // Propagate error
        usleep(DEBOUNCE_DELAY_MS * 1000); // Delay in microseconds
    }

    for (i = 0; i < DEBOUNCE_READS; i++) {
        sum += reads[i];
    }

    // Consider it a valid reading if the sum is less than half the reads (active-low)
    return (sum < DEBOUNCE_READS / 2) ? 0 : 1; // Return 0 if flame detected (LOW), 1 otherwise
}

// Function to activate the buzzer and LED
void activate_alarm(struct gpiod_line *buzzer_line, struct gpiod_line *led_line) {
    int ret;

    ret = gpiod_line_set_value(buzzer_line, 1);
    if (ret < 0) {
        fprintf(stderr, "Error setting buzzer value: %d\n", ret);
    }

    ret = gpiod_line_set_value(led_line, 1);
    if (ret < 0) {
        fprintf(stderr, "Error setting LED value: %d\n", ret);
    }
}

// Function to deactivate the buzzer and LED
void deactivate_alarm(struct gpiod_line *buzzer_line, struct gpiod_line *led_line) {
    int ret;

    ret = gpiod_line_set_value(buzzer_line, 0);
    if (ret < 0) {
        fprintf(stderr, "Error setting buzzer value: %d\n", ret);
    }

    ret = gpiod_line_set_value(led_line, 0);
    if (ret < 0) {
        fprintf(stderr, "Error setting LED value: %d\n", ret);
    }
}

// Function to log an event to the log file
void log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure the log is written immediately
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to setup a GPIO pin
int setup_gpio(int pin, const char *consumer, int direction) {
    struct gpiod_line *line;
    int ret;

    line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d\n", pin);
        return -1;
    }

    ret = gpiod_line_request(line, consumer, direction);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d: %d\n", pin, ret);
        gpiod_line_release(line);
        return -1;
    }

    if (direction == GPIOD_LINE_REQUEST_DIRECTION_INPUT) {
        // Set pull-up resistor if input
        ret = gpiod_line_set_direction(line, GPIOD_LINE_REQUEST_DIRECTION_INPUT);
        if (ret < 0) {
            fprintf(stderr, "Error setting direction for GPIO line %d: %d\n", pin, ret);
            gpiod_line_release(line);
            return -1;
        }
    }

    return 0;
}

// Function to cleanup GPIO resources
void cleanup_gpio(void) {
    if (flame_line) {
        gpiod_line_release(flame_line);
    }
    if (buzzer_line) {
        gpiod_line_release(buzzer_line);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    int flame_detected;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip\n");
        return 1;
    }

    // Setup GPIO pins
    if (setup_gpio(FLAME_SENSOR_PIN, "flame_sensor", GPIOD_LINE_REQUEST_DIRECTION_INPUT) != 0) {
        cleanup_gpio();
        return 1;
    }
    if (setup_gpio(BUZZER_PIN, "buzzer", GPIOD_LINE_REQUEST_DIRECTION_OUTPUT) != 0) {
        cleanup_gpio();
        return 1;
    }
    if (setup_gpio(LED_PIN, "led", GPIOD_LINE_REQUEST_DIRECTION_OUTPUT) != 0) {
        cleanup_gpio();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file\n");
        cleanup_gpio();
        return 1;
    }

    flame_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    led_line = gpiod_chip_get_line(chip, LED_PIN);

    if (!flame_line || !buzzer_line || !led_line) {
        fprintf(stderr, "Error getting lines for GPIO pins\n");
        cleanup_gpio();
        return 1;
    }

    if (gpiod_line_request(flame_line, "flame_sensor", GPIOD_LINE_REQUEST_DIRECTION_INPUT) < 0) {
        fprintf(stderr, "Error requesting flame sensor line\n");
        cleanup_gpio();
        return 1;
    }

    if (gpiod_line_request(buzzer_line, "buzzer", GPIOD_LINE_REQUEST_DIRECTION_OUTPUT) < 0) {
        fprintf(stderr, "Error requesting buzzer line\n");
        cleanup_gpio();
        return 1;
    }

    if (gpiod_line_request(led_line, "led", GPIOD_LINE_REQUEST_DIRECTION_OUTPUT) < 0) {
        fprintf(stderr, "Error requesting LED line\n");
        cleanup_gpio();
        return 1;
    }

    // Main loop
    while (!terminate) {
        flame_detected = debounce(flame_line);
        if (flame_detected < 0) {
            fprintf(stderr, "Error during debounce, exiting...\n");
            break;
        }

        if (flame_detected == 0) { // Flame detected (LOW)
            activate_alarm(buzzer_line, led_line);
            log_event("Flame Detected");
        } else {
            deactivate_alarm(buzzer_line, led_line);
        }

        usleep(100000); // Check every 100ms
    }

    // Cleanup and exit
    cleanup_gpio();
    return 0;
}

