#include <string.h>

// Define GPIO pins for solenoids
#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27

// Define dispense duration and delay
#define TOTAL_DURATION_MS 1000
#define SOLENOID_ON_TIME_MS (TOTAL_DURATION_MS / 2)

// Global flag to signal program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int activate_solenoid(int pin);
int deactivate_solenoid(int pin);
int dispense_cycle();
int log_dispense_event(int solenoid1_pin, int solenoid2_pin, int duration_ms);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        fprintf(stderr, "\nCtrl+C detected. Deactivating solenoids and exiting.\n");
        program_running = 0;
    }
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(SOLENOID_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", SOLENOID_1_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", SOLENOID_2_PIN);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to activate a solenoid
int activate_solenoid(int pin) {
    if (gpioWrite(pin, 1) != 0) {
        fprintf(stderr, "Failed to activate solenoid on GPIO%d\n", pin);
        return 1;
    }
    return 0;
}

// Function to deactivate a solenoid
int deactivate_solenoid(int pin) {
    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "Failed to deactivate solenoid on GPIO%d\n", pin);
        return 1;
    }
    return 0;
}

// Function to perform a dispense cycle
int dispense_cycle() {
    // Activate solenoid 1
    if (activate_solenoid(SOLENOID_1_PIN) != 0) {
        return 1;
    }
    gpioDelay(SOLENOID_ON_TIME_MS * 1000); // Delay in microseconds

    // Activate solenoid 2
    if (activate_solenoid(SOLENOID_2_PIN) != 0) {
        deactivate_solenoid(SOLENOID_1_PIN); // Clean up solenoid 1
        return 1;
    }
    gpioDelay(SOLENOID_ON_TIME_MS * 1000); // Delay in microseconds

    // Deactivate both solenoids
    if (deactivate_solenoid(SOLENOID_1_PIN) != 0) {
        return 1;
    }
    if (deactivate_solenoid(SOLENOID_2_PIN) != 0) {
        return 1;
    }

    return 0;
}

// Function to log dispense event to file
int log_dispense_event(int solenoid1_pin, int solenoid2_pin, int duration_ms) {
    FILE *fp = fopen("dispense_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open dispense_log.txt for writing\n");
        return 1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, GPIO%d, GPIO%d, %d\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, solenoid1_pin, solenoid2_pin, duration_ms);

    fclose(fp);
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    fprintf(stderr, "Dispensing system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        if (dispense_cycle() != 0) {
            fprintf(stderr, "Error during dispense cycle\n");
        }

        gpioDelay(5000000); // Delay for 5 seconds (5000000 microseconds)
    }

    // Deactivate solenoids before exiting
    deactivate_solenoid(SOLENOID_1_PIN);
    deactivate_solenoid(SOLENOID_2_PIN);

    // Terminate pigpio
    gpioTerminate();

    fprintf(stderr, "Dispensing system stopped.\n");
    return 0;
}

