#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Motor A GPIOs
#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18
#define MOTOR_A_ENABLE 24

// Motor B GPIOs
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23
#define MOTOR_B_ENABLE 25

// PID Constants
#define Kp 1.0
#define Ki 0.01
#define Kd 0.1

// Obstacle Avoidance Threshold
#define OBSTACLE_THRESHOLD 20.0

// Global Variables
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Structure to hold motor speeds
typedef struct {
    int motor_a_speed;
    int motor_b_speed;
} MotorSpeeds;

// Function Prototypes
float generate_tilt_error();
float generate_distance();
MotorSpeeds pid_control(float tilt_error, float distance, MotorSpeeds previous_speeds);
void set_motor_speed(int motor, int speed);
void stop_motors();
void signal_handler(int signal);
void log_data(float tilt_error, float distance, MotorSpeeds speeds);

// Signal Handler
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C detected. Stopping motors and exiting.\n");
        program_running = 0;
    }
}

// Generate Tilt Error
float generate_tilt_error() {
    return ((float)rand() / RAND_MAX) * 20.0 - 10.0;
}

// Generate Distance
float generate_distance() {
    return ((float)rand() / RAND_MAX) * 380.0 + 2.0;
}

// PID Control
MotorSpeeds pid_control(float tilt_error, float distance, MotorSpeeds previous_speeds) {
    static float integral = 0.0;
    static float previous_error = 0.0;

    // Obstacle Avoidance
    if (distance < OBSTACLE_THRESHOLD) {
        set_motor_speed('A', -128);
        set_motor_speed('B', -128);
        return previous_speeds; // Return previous speeds to avoid abrupt changes
    }

    float derivative = tilt_error - previous_error;
    integral += tilt_error;

    float output = Kp * tilt_error + Ki * integral + Kd * derivative;

    // Clamp output
    if (output > 255.0) output = 255.0;
    if (output < -255.0) output = -255.0;

    MotorSpeeds speeds;
    speeds.motor_a_speed = (int)output;
    speeds.motor_b_speed = (int)output;

    previous_error = tilt_error;
    return speeds;
}

// Set Motor Speed
void set_motor_speed(int motor, int speed) {
    int forward_pin, backward_pin, enable_pin;

    if (motor == 'A') {
        forward_pin = MOTOR_A_FORWARD;
        backward_pin = MOTOR_A_BACKWARD;
        enable_pin = MOTOR_A_ENABLE;
    } else if (motor == 'B') {
        forward_pin = MOTOR_B_FORWARD;
        backward_pin = MOTOR_B_BACKWARD;
        enable_pin = MOTOR_B_ENABLE;
    } else {
        fprintf(stderr, "Error: Invalid motor character: %c\n", motor);
        return;
    }

    // Clamp speed
    if (speed > 255) speed = 255;
    if (speed < -255) speed = -255;

    // Set direction
    if (speed > 0) {
        gpioWrite(forward_pin, 1);
        gpioWrite(backward_pin, 0);
        gpioPWM(enable_pin, speed);
    } else if (speed < 0) {
        gpioWrite(forward_pin, 0);
        gpioWrite(backward_pin, 1);
        gpioPWM(enable_pin, -speed);
    } else {
        gpioWrite(forward_pin, 0);
        gpioWrite(backward_pin, 0);
        gpioPWM(enable_pin, 0);
    }
}

// Stop Motors
void stop_motors() {
    set_motor_speed('A', 0);
    set_motor_speed('B', 0);
}

// Log Data
void log_data(float tilt_error, float distance, MotorSpeeds speeds) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n", timestamp, tilt_error, distance, speeds.motor_a_speed, speeds.motor_b_speed);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_ENABLE, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(MOTOR_A_ENABLE, 255);
    gpioSetPWMrange(MOTOR_B_ENABLE, 255);

    // Open log file
    log_file = fopen("balance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Seed random number generator
    srand(time(NULL));

    // Register signal handler
    signal(SIGINT, signal_handler);

    MotorSpeeds current_speeds = {0, 0};
    float tilt_error, distance;

    // Main loop
    while (program_running) {
        // Generate sensor data
        tilt_error = generate_tilt_error();
        distance = generate_distance();

        // PID control
        current_speeds = pid_control(tilt_error, distance, current_speeds);

        // Set motor speeds
        set_motor_speed('A', current_speeds.motor_a_speed);
        set_motor_speed('B', current_speeds.motor_b_speed);

        // Log data
        log_data(tilt_error, distance, current_speeds);

        // Delay
        gpioDelay(50000); // 50 ms
    }

    // Stop motors
    stop_motors();

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

