#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Global variable to store the relay state
int relay_state = 0;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
void toggle_relay();
void cleanup_gpio();
void signal_handler(int signal);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO4 as input with pull-up resistor
    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_UP);

    // Set GPIO17 as output
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    return 0; // Indicate success
}

// Function to read the touch sensor
int read_touch_sensor() {
    // Read the digital value from GPIO4
    int sensor_value = gpioRead(TOUCH_SENSOR_PIN);

    // Debounce the sensor reading
    gpioDelay(50); // 50ms debounce delay

    return sensor_value;
}

// Function to toggle the relay state
void toggle_relay() {
    // Toggle the relay state
    relay_state = !relay_state;

    // Set GPIO17 to the new relay state
    gpioWrite(RELAY_PIN, relay_state);

    printf("Relay toggled to state: %d\n", relay_state);
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    // Set GPIO17 to LOW before exiting
    gpioWrite(RELAY_PIN, 0);

    // Terminate the pigpio library
    gpioTerminate();

    printf("GPIO cleanup complete. Exiting.\n");
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d\n", signal);
    cleanup_gpio();
    exit(0);
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO pins
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Smart Light Switch Program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Read the touch sensor
        int touch_detected = (read_touch_sensor() == 0); // TTP223 outputs LOW when touched

        // Toggle the relay if a touch is detected
        if (touch_detected) {
            toggle_relay();
        }

        // Delay to prevent excessive CPU usage
        gpioDelay(10); // 10ms delay
    }

    return 0; // This line will never be reached due to the infinite loop
}

