void map_amplitude_to_rgb(float rms_amplitude, int *red, int *green, int *blue) {
    // Non-linear transition: cool colors (blue) for low amplitude, warm colors (red) for high amplitude
    float normalized_amplitude = rms_amplitude / 1000.0; // Scale amplitude for mapping
    if (normalized_amplitude > 1.0) normalized_amplitude = 1.0; //Clamp
