        fprintf(stderr, "Error reading data: %s\n", strerror(errno));
        return -1;
    }

    // Extract clear, red, green, and blue values
    *clear = (uint16_t)buf[1] << 8 | (uint16_t)buf[0];
    *red   = (uint16_t)buf[3] << 8 | (uint16_t)buf[2];
    *green = (uint16_t)buf[5] << 8 | (uint16_t)buf[4];
    *blue  = (uint16_t)buf[7] << 8 | (uint16_t)buf[6];

    return 0;
}

// Log data to CSV file
void log_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%u,%u,%u,%u\n", timestamp, clear, red, green, blue);
    fflush(fp); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, TCS34725_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (tcs34725_init() < 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    fp = fopen("color_data.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is new
    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize == 0) {
        fprintf(fp, "Timestamp,Clear,Red,Green,Blue\n");
    }
    rewind(fp);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t clear, red, green, blue;

    // Main loop
    while (!terminate) {
        // Read color data
        if (tcs34725_read_data(&clear, &red, &green, &blue) == 0) {
            // Log the data
            log_data(clear, red, green, blue);
        } else {
            // Log 0s if there's an error
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[20];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            fprintf(fp, "%s,0,0,0,0\n", timestamp);
            fflush(fp);
        }

        // Wait for 500ms
        gpioDelay(500000); // 500ms = 500000 microseconds
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    fclose(fp);
    gpioTerminate();

    return 0;
}

