#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>
#include <math.h>

// Define GPIO pins for the relays (BCM numbering)
#define RELAY1_PIN 17
#define RELAY2_PIN 27
#define RELAY3_PIN 22
#define RELAY4_PIN 23

// Define the GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Define the duration of each phase in seconds
#define SUNRISE_DURATION 3600
#define DAYTIME_DURATION 21600
#define SUNSET_DURATION 3600
#define NIGHTTIME_DURATION 518400 // 14.4 hours

// Define the number of brightness levels
#define NUM_BRIGHTNESS_LEVELS 100

// Global variables for signal handling
static volatile sig_atomic_t terminate = 0;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay1_line = NULL;
static struct gpiod_line *relay2_line = NULL;
static struct gpiod_line *relay3_line = NULL;
static struct gpiod_line *relay4_line = NULL;

// Function prototypes
void signal_handler(int sig);
int initialize_gpio(void);
void cleanup_gpio(void);
void set_relay_state(struct gpiod_line *line, int state);
void sunrise_phase(void);
void daytime_phase(void);
void sunset_phase(void);
void nighttime_phase(void);
void set_brightness(int brightness_level);
int calculate_brightness_level(double elapsed_time, double duration);

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up and exiting...\n");
    terminate = 1;
}

// Function to initialize the GPIO lines
int initialize_gpio(void) {
    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIO_CHIP);
        return -1;
    }

    // Get the lines for the relays
    relay1_line = gpiod_chip_get_line(chip, RELAY1_PIN);
    relay2_line = gpiod_chip_get_line(chip, RELAY2_PIN);
    relay3_line = gpiod_chip_get_line(chip, RELAY3_PIN);
    relay4_line = gpiod_chip_get_line(chip, RELAY4_PIN);

    if (!relay1_line || !relay2_line || !relay3_line || !relay4_line) {
        fprintf(stderr, "Error getting relay line(s)\n");
        cleanup_gpio();
        return -1;
    }

    // Request the lines as output
    if (gpiod_line_request_output(relay1_line, "relay1", 0) < 0 ||
        gpiod_line_request_output(relay2_line, "relay2", 0) < 0 ||
        gpiod_line_request_output(relay3_line, "relay3", 0) < 0 ||
        gpiod_line_request_output(relay4_line, "relay4", 0) < 0) {
        fprintf(stderr, "Error requesting relay line(s) as output\n");
        cleanup_gpio();
        return -1;
    }

    return 0;
}

// Function to cleanup the GPIO lines
void cleanup_gpio(void) {
    // Release the lines
    if (relay1_line) gpiod_line_release(relay1_line);
    if (relay2_line) gpiod_line_release(relay2_line);
    if (relay3_line) gpiod_line_release(relay3_line);
    if (relay4_line) gpiod_line_release(relay4_line);

    // Close the chip
    if (chip) gpiod_chip_close(chip);
}

// Function to set the state of a relay (0 = on, 1 = off)
void set_relay_state(struct gpiod_line *line, int state) {
    if (gpiod_line_set_value(line, state) < 0) {
        fprintf(stderr, "Error setting relay state\n");
    }
}

// Function to set the brightness of all relays using PWM-like toggling
void set_brightness(int brightness_level) {
    // Calculate the on/off duration for each relay
    int on_duration = (int)((double)brightness_level / NUM_BRIGHTNESS_LEVELS * 1000000); // microseconds
    int off_duration = 1000000 - on_duration; // microseconds

    // Set the relay state based on the brightness level
    if (brightness_level > 0) {
        set_relay_state(relay1_line, 0); // Turn on relay 1
        set_relay_state(relay2_line, 0); // Turn on relay 2
        set_relay_state(relay3_line, 0); // Turn on relay 3
        set_relay_state(relay4_line, 0); // Turn on relay 4
        usleep(on_duration);
        set_relay_state(relay1_line, 1); // Turn off relay 1
        set_relay_state(relay2_line, 1); // Turn off relay 2
        set_relay_state(relay3_line, 1); // Turn off relay 3
        set_relay_state(relay4_line, 1); // Turn off relay 4
        usleep(off_duration);
    } else {
        set_relay_state(relay1_line, 1); // Turn off relay 1
        set_relay_state(relay2_line, 1); // Turn off relay 2
        set_relay_state(relay3_line, 1); // Turn off relay 3
        set_relay_state(relay4_line, 1); // Turn off relay 4
    }
}

// Function to calculate the brightness level based on elapsed time and duration
int calculate_brightness_level(double elapsed_time, double duration) {
    double fraction = elapsed_time / duration;
    if (fraction < 0.0) fraction = 0.0;
    if (fraction > 1.0) fraction = 1.0;
    return (int)(fraction * NUM_BRIGHTNESS_LEVELS);
}

// Function to simulate the sunrise phase
void sunrise_phase(void) {
    time_t start_time = time(NULL);
    while (time(NULL) - start_time < SUNRISE_DURATION && !terminate) {
        int brightness_level = calculate_brightness_level(time(NULL) - start_time, SUNRISE_DURATION);
        set_brightness(brightness_level);
        usleep(100000); // 100ms delay
    }
    set_brightness(NUM_BRIGHTNESS_LEVELS); // Ensure full brightness at the end
}

// Function to simulate the daytime phase
void daytime_phase(void) {
    while (!terminate) {
        set_brightness(NUM_BRIGHTNESS_LEVELS);
        sleep(1); // Check for termination every second
    }
}

// Function to simulate the sunset phase
void sunset_phase(void) {
    time_t start_time = time(NULL);
    while (time(NULL) - start_time < SUNSET_DURATION && !terminate) {
        int brightness_level = calculate_brightness_level(SUNSET_DURATION - (time(NULL) - start_time), SUNSET_DURATION);
        set_brightness(brightness_level);
        usleep(100000); // 100ms delay
    }
    set_brightness(0); // Ensure all relays are off at the end
}

// Function to simulate the nighttime phase
void nighttime_phase(void) {
    while (!terminate) {
        set_brightness(0);
        sleep(1); // Check for termination every second
    }
}

int main(void) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        return 1;
    }

    // Main loop
    while (!terminate) {
        time_t now = time(NULL);
        struct tm *timeinfo = localtime(&now);
        long seconds_since_midnight = (timeinfo->tm_hour * 3600) + (timeinfo->tm_min * 60) + timeinfo->tm_sec;

        if (seconds_since_midnight >= 0 && seconds_since_midnight < SUNRISE_DURATION) {
            sunrise_phase();
        } else if (seconds_since_midnight >= SUNRISE_DURATION && seconds_since_midnight < (SUNRISE_DURATION + DAYTIME_DURATION)) {
            daytime_phase();
        } else if (seconds_since_midnight >= (SUNRISE_DURATION + DAYTIME_DURATION) && seconds_since_midnight < (SUNRISE_DURATION + DAYTIME_DURATION + SUNSET_DURATION)) {
            sunset_phase();
        } else {
            nighttime_phase();
        }
    }

    // Cleanup GPIO before exiting
    cleanup_gpio();

    return 0;
}

