#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SENSOR_PIN 17
#define RECORD_DURATION 5 // seconds
#define DEBOUNCE_INTERVAL 200 // milliseconds

FILE *log_file = NULL;

// Function to generate an ISO 8601 timestamp string
char* generate_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string
    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y%m%d_%H%M%S", timeinfo);
    return timestamp;
}

// Function to record a video using raspivid
int record_video(const char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "raspivid -o /home/pi/videos/%s.h264 -t %d000", filename, RECORD_DURATION);
    int status = system(command);
    if (status == -1) {
        perror("Failed to execute raspivid command");
        return -1;
    }
    return 0;
}

// Function to log a motion event to a file
int log_motion(const char *timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s Motion detected\n", timestamp);
    fflush(log_file); // Ensure the log is written immediately
    return 0;
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 17 as an input
    gpioSetMode(SENSOR_PIN, PI_INPUT);

    // Open the log file
    log_file = fopen("/home/pi/logs/motion_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Read the sensor value
        int sensor_value = gpioRead(SENSOR_PIN);

        // Check for motion (active-low signal)
        if (sensor_value == 0) {
            // Generate timestamp
            char *timestamp = generate_timestamp();
            if (timestamp != NULL) {
                // Record the video
                if (record_video(timestamp) == 0) {
                    // Log the motion event
                    if (log_motion(timestamp) != 0) {
                        fprintf(stderr, "Failed to log motion event.\n");
                    }
                } else {
                    fprintf(stderr, "Failed to record video.\n");
                }
                free(timestamp); // Free the allocated memory
            } else {
                fprintf(stderr, "Failed to generate timestamp.\n");
            }

            // Debounce: Wait for DEBOUNCE_INTERVAL milliseconds
            gpioDelay(DEBOUNCE_INTERVAL * 1000); // Convert milliseconds to microseconds
        }

        // Small delay to avoid busy-waiting
        gpioDelay(10000); // 10ms
    }

    // The program should never reach here due to the infinite loop and signal handler.
    return 0;
}

