// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define SMPLRT_DIV 0x19
#define GYRO_CONFIG 0x1B
#define GYRO_XOUT_H 0x43
#define GYRO_XOUT_L 0x44
#define GYRO_YOUT_H 0x45
#define GYRO_YOUT_L 0x46
#define GYRO_ZOUT_H 0x47
#define GYRO_ZOUT_L 0x48

// Sensitivity scale factor
#define GYRO_SCALE 131.0

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_mpu6050();
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z);
double convert_to_degps(int16_t raw_value);
void log_data(double timestamp, double x_degps, double y_degps, double z_degps);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize MPU-6050
int init_mpu6050() {
    int retries = 3;
    int status;

    while (retries > 0) {
        // Wake up the MPU-6050
        status = i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00);
        if (status != 0) {
            fprintf(stderr, "Error writing to PWR_MGMT_1: %d\n", status);
            retries--;
            gpioDelay(100000); // 100ms delay
            continue;
        }

        // Set sample rate divider to 125 Hz
        status = i2cWriteByteData(i2c_handle, SMPLRT_DIV, 0x07);
        if (status != 0) {
            fprintf(stderr, "Error writing to SMPLRT_DIV: %d\n", status);
            retries--;
            gpioDelay(100000); // 100ms delay
            continue;
        }

        // Set gyroscope full-scale range to ±250°/s
        status = i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00);
        if (status != 0) {
            fprintf(stderr, "Error writing to GYRO_CONFIG: %d\n", status);
            retries--;
            gpioDelay(100000); // 100ms delay
            continue;
        }

        return 0; // Success
    }

    fprintf(stderr, "Failed to initialize MPU-6050 after multiple retries.\n");
    return -1; // Failure
}

// Read gyroscope data
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int status;

    status = i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buffer, 6);
    if (status != 6) {
        fprintf(stderr, "Error reading gyroscope data: %d\n", status);
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Convert raw gyroscope value to degrees per second
double convert_to_degps(int16_t raw_value) {
    return (double)raw_value / GYRO_SCALE;
}

// Log data to CSV file
void log_data(double timestamp, double x_degps, double y_degps, double z_degps) {
    fprintf(log_file, "%.6f,%.6f,%.6f,%.6f\n", timestamp, x_degps, y_degps, z_degps);
    fflush(log_file); // Ensure data is written to disk immediately
}

