    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() != 0) {
        fprintf(stderr, "MPU-6050 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,X_degps,Y_degps,Z_degps\n");
    }

    // Set up signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x_raw, y_raw, z_raw;
    double x_degps, y_degps, z_degps;
    struct timespec ts;
    double timestamp;

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(&x_raw, &y_raw, &z_raw) == 0) {
            // Convert raw values to degrees per second
            x_degps = convert_to_degps(x_raw);
            y_degps = convert_to_degps(y_raw);
            z_degps = convert_to_degps(z_raw);

            // Get timestamp
            if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
                timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0;
                // Log data
                log_data(timestamp, x_degps, y_degps, z_degps);
            } else {
                fprintf(stderr, "Error getting timestamp\n");
            }
        } else {
            fprintf(stderr, "Error reading gyroscope data, attempting re-initialization.\n");
            // Attempt to re-initialize the MPU-6050
            if (init_mpu6050() != 0) {
                fprintf(stderr, "MPU-6050 re-initialization failed.\n");
            }
        }

        // Delay for 10 ms (100 Hz sampling rate)
        gpioDelay(10000); // 10 ms
    }

    // Close log file and I2C handle
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

