// Define GPIO pins for the relays
#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define moisture threshold
#define MOISTURE_THRESHOLD 30

// Global variable for the log file
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_moisture_sensor();
void control_relay(int relay_pin, int moisture_level);
void log_data(int moisture_level, int relay1_state, int relay2_state, int relay3_state, int relay4_state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Deactivate all relays
    gpioWrite(RELAY1_PIN, 1);
    gpioWrite(RELAY2_PIN, 1);
    gpioWrite(RELAY3_PIN, 1);
    gpioWrite(RELAY4_PIN, 1);

    // Close the log file if it's open
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Initialize all relays to OFF (HIGH)
    gpioWrite(RELAY1_PIN, 1);
    gpioWrite(RELAY2_PIN, 1);
    gpioWrite(RELAY3_PIN, 1);
    gpioWrite(RELAY4_PIN, 1);

    return 0; // Indicate success
}

// Function to read moisture sensor data
int read_moisture_sensor() {
    // Seed the random number generator with the current time
    srand(time(NULL));

    // Generate a random number between 0 and 100
    return rand() % 101;
}

// Function to control the relay based on moisture level
void control_relay(int relay_pin, int moisture_level) {
    if (moisture_level < MOISTURE_THRESHOLD) {
        // Activate the relay (set LOW)
        gpioWrite(relay_pin, 0);
    } else {
        // Deactivate the relay (set HIGH)
        gpioWrite(relay_pin, 1);
    }
}

// Function to log data to a file
void log_data(int moisture_level, int relay1_state, int relay2_state, int relay3_state, int relay4_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Moisture: %d, Relay1: %d, Relay2: %d, Relay3: %d, Relay4: %d\n",
            timestamp, moisture_level, relay1_state, relay2_state, relay3_state, relay4_state);
    fflush(log_file); // Ensure data is written to the file immediately
}

int main() {
    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    // Open the log file
    log_file = fopen("irrigation_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    printf("Smart Greenhouse Irrigation System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Read moisture levels from sensors
        int moisture1 = read_moisture_sensor();
        int moisture2 = read_moisture_sensor();
        int moisture3 = read_moisture_sensor();
        int moisture4 = read_moisture_sensor();

        // Control relays based on moisture levels
        control_relay(RELAY1_PIN, moisture1);
        control_relay(RELAY2_PIN, moisture2);
        control_relay(RELAY3_PIN, moisture3);
        control_relay(RELAY4_PIN, moisture4);

        // Log the data
        log_data(moisture1, !gpioRead(RELAY1_PIN), !gpioRead(RELAY2_PIN), !gpioRead(RELAY3_PIN), !gpioRead(RELAY4_PIN));

        // Wait for 5 seconds
        gpioDelay(5000); // pigpio's delay function (milliseconds)
    }

    return 0; // This line will never be reached due to the infinite loop
}

