// Freefall duration (seconds)
#define FREEFALL_DURATION 0.5

// Freefall confirmation delay (seconds)
#define FREEFALL_CONFIRMATION_DELAY 0.5

// Scale factor (LSB/g)
#define SCALE_FACTOR 256.0

// I2C handle
int i2c_handle;

// File pointer for logging
FILE *log_file;

// Flag to indicate program termination
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Function prototypes
int initialize_adxl345();
accelerometer_data_t read_accelerometer_data();
int detect_freefall(accelerometer_data_t data);
void log_freefall_event(accelerometer_data_t data);
