#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define TRIG_PIN 4
#define ECHO_PIN 18

// Define constants
#define TRIGGER_PULSE_WIDTH 10 // microseconds
#define TIMEOUT_DURATION 100  // milliseconds
#define MAX_PULSE_WIDTH 23200  // microseconds (4 meters)
#define SPEED_OF_SOUND 34300   // cm/s

// Global variables
volatile uint32_t pulse_start_tick = 0;
volatile uint32_t pulse_end_tick = 0;
volatile int pulse_width_valid = 0;
pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
FILE *log_file = NULL;
volatile int running = 1;

// Function prototypes
void trigger_pulse();
void echo_rising_edge_callback(int gpio, int level, uint32_t tick);
void echo_falling_edge_callback(int gpio, int level, uint32_t tick);
double calculate_distance(uint32_t pulse_width);
void log_distance(double distance);
void signal_handler(int signal);

// Function to generate a trigger pulse
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(TRIGGER_PULSE_WIDTH);
    gpioWrite(TRIG_PIN, 0);
}

// Interrupt callback for rising edge of the echo signal
void echo_rising_edge_callback(int gpio, int level, uint32_t tick) {
    pthread_mutex_lock(&pulse_mutex);
    pulse_start_tick = tick;
    pulse_width_valid = 0; // Reset validity flag
    pthread_mutex_unlock(&pulse_mutex);
}

// Interrupt callback for falling edge of the echo signal
void echo_falling_edge_callback(int gpio, int level, uint32_t tick) {
    pthread_mutex_lock(&pulse_mutex);
    pulse_end_tick = tick;
    pulse_width_valid = 1; // Set validity flag
    pthread_mutex_unlock(&pulse_mutex);
}

// Function to calculate distance in centimeters
double calculate_distance(uint32_t pulse_width) {
    return (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 1000000.0 to convert us to s, and by 2 for one-way distance
}

// Function to log distance to a file
void log_distance(double distance) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    uint64_t timestamp_ns = (uint64_t)ts.tv_sec * 1000000000ULL + (uint64_t)ts.tv_nsec;

    if (log_file != NULL) {
        fprintf(log_file, "%llu,%.2f\n", timestamp_ns, distance);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL); // Disable interrupt callbacks
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate(); // Terminate pigpio
    pthread_mutex_destroy(&pulse_mutex); // Destroy mutex
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on ECHO pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Set interrupt callbacks
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_rising_edge_callback, NULL) != 0) {
        fprintf(stderr, "Error setting rising edge callback!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_falling_edge_callback, NULL) != 0) {
        fprintf(stderr, "Error setting falling edge callback!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        trigger_pulse();

        // Wait for pulse width to be measured or timeout
        int timeout_count = 0;
        while (!pulse_width_valid && timeout_count < (TIMEOUT_DURATION * 1000)) { // Check every 1 us
            gpioDelay(1);
            timeout_count++;
        }

        if (pulse_width_valid) {
            uint32_t pulse_width;
            pthread_mutex_lock(&pulse_mutex);
            pulse_width = pulse_end_tick - pulse_start_tick;
            pthread_mutex_unlock(&pulse_mutex);

            // Handle wrap-around
            if (pulse_width > MAX_PULSE_WIDTH) {
                fprintf(stderr, "Warning: Pulse width exceeds maximum range (%d us).\n", MAX_PULSE_WIDTH);
            } else {
                double distance = calculate_distance(pulse_width);
                log_distance(distance);
                printf("Distance: %.2f cm\n", distance);
            }
        } else {
            fprintf(stderr, "Warning: Timeout waiting for echo pulse.\n");
        }

        gpioDelay(200); // Trigger every 200 ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL); // Disable interrupt callbacks
    fclose(log_file);
    gpioTerminate(); // Terminate pigpio
    pthread_mutex_destroy(&pulse_mutex); // Destroy mutex

    return 0;
}

