} accelerometer_data_t;

int main(int argc, char *argv[]) {
    float freefall_threshold = DEFAULT_FREEFALL_THRESHOLD;
    float impact_threshold = DEFAULT_IMPACT_THRESHOLD;

    // Parse command-line arguments
    if (argc > 1) {
        freefall_threshold = atof(argv[1]);
    }
    if (argc > 2) {
        impact_threshold = atof(argv[2]);
    }

    // Initialize pigpio
    if (init_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
