// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, LIS3DH_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Initialize LIS3DH
int init_lis3dh(float freefall_threshold, float impact_threshold) {
    // Configure CTRL_REG1 for 100 Hz data rate and enable all axes
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x77) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG1\n");
        return 1;
    }

    // Configure CTRL_REG4 for ±2g full scale
    if (i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG4\n");
        return 1;
    }

    return 0;
}

// Read acceleration data
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int retries = 3;

    while (retries > 0) {
        if (i2cReadI2CBlockData(i2c_handle, OUT_X_L, buffer, 6) == 6) {
            *x = (int16_t)((buffer[1] << 8) | buffer[0]);
            *y = (int16_t)((buffer[3] << 8) | buffer[2]);
            *z = (int16_t)((buffer[5] << 8) | buffer[4]);
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed, retrying...\n");
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }

    fprintf(stderr, "I2C read failed after multiple retries.\n");
    return 1; // Failure
}

// Calculate acceleration magnitude
float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    float x_g = (float)x / 16384.0;
    float y_g = (float)y / 16384.0;
    float z_g = (float)z / 16384.0;
    return sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

// Detect fall
void detect_fall(float magnitude, float freefall_threshold, float impact_threshold) {
    static int in_freefall = 0;

    if (magnitude < freefall_threshold) {
        if (!in_freefall) {
            printf("Freefall detected!\n");
            in_freefall = 1;
        }
    } else if (magnitude > impact_threshold) {
        if (in_freefall) {
            printf("Impact detected!\n");
            activate_buzzer();
            in_freefall = 0;
        }
    }
}

// Activate buzzer
void activate_buzzer() {
    gpioWrite(BUZZER_GPIO, 1); // Turn buzzer on
    gpioDelay(1000000);       // Wait for 1 second
    gpioWrite(BUZZER_GPIO, 0); // Turn buzzer off
}

// Cleanup
void cleanup() {
    i2cClose(i2c_handle);
    gpioTerminate();
}

// Signal handler
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Exiting.\n");
    terminate = 1;
}

