#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

// LIS3DH Registers
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D

// Default values
#define DEFAULT_I2C_ADDRESS 0x18
#define DEFAULT_THRESHOLD 2.0f
#define DEFAULT_SERVER_IP "127.0.0.1"
#define DEFAULT_SERVER_PORT 5000

// Global variables
int i2c_handle;
int i2c_address = DEFAULT_I2C_ADDRESS;
float threshold = DEFAULT_THRESHOLD;
char *server_ip = DEFAULT_SERVER_IP;
int server_port = DEFAULT_SERVER_PORT;
int running = 1;

// Function prototypes
int initialize_i2c(int address);
int configure_sensor(int i2c_handle);
int read_acceleration(int i2c_handle, int16_t *x, int16_t *y, int16_t *z);
float convert_to_g(int16_t raw_value);
void log_event(float x, float y, float z);
void send_data_to_server(float x, float y, float z);
void signal_handler(int signal);

// Function to initialize I2C
int initialize_i2c(int address) {
    i2c_handle = i2cOpen(1, address, 0); // Bus 1, address, flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to configure the LIS3DH sensor
int configure_sensor(int i2c_handle) {
    // Configure CTRL_REG1: 100 Hz, Normal mode, enable all axes
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x57) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // Configure CTRL_REG4: ±2g range, high-resolution mode
    if (i2cWriteByteData(i2c_handle, CTRL_REG4, 0x88) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4\n");
        return -1;
    }

    return 0;
}

// Function to read acceleration data from the sensor
int read_acceleration(int i2c_handle, int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L, buffer, 6) != 6) {
        fprintf(stderr, "Error reading acceleration data\n");
        *x = 0; *y = 0; *z = 0; // Return 0s to avoid further issues
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Function to convert raw acceleration data to g
float convert_to_g(int16_t raw_value) {
    return (float)(raw_value >> 4) * 0.0009765625f; // 2g / 2048
}

// Function to log an event to a file
void log_event(float x, float y, float z) {
    FILE *fp = fopen("/var/log/high_acceleration.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, X: %.4f g, Y: %.4f g, Z: %.4f g\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            x, y, z);

    fclose(fp);
}

// Function to send data to the server
void send_data_to_server(float x, float y, float z) {
    int sockfd;
    struct sockaddr_in servaddr;

    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket creation failed");
        return;
    }

    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(server_port);
    if (inet_pton(AF_INET, server_ip, &servaddr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(sockfd);
        return;
    }

    char message[256];
    snprintf(message, sizeof(message), "X: %.4f g, Y: %.4f g, Z: %.4f g", x, y, z);

    if (sendto(sockfd, (const char *)message, strlen(message), 0, (const struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        perror("sendto failed");
    }

    close(sockfd);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:t:i:p:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 16);
                if (i2c_address < 0x08 || i2c_address > 0x77) {
                    fprintf(stderr, "Invalid I2C address. Must be between 0x08 and 0x77.\n");
                    return 1;
                }
                break;
            case 't':
                threshold = strtof(optarg, NULL);
                if (threshold <= 0) {
                    fprintf(stderr, "Invalid threshold. Must be greater than 0.\n");
                    return 1;
                }
                break;
            case 'i':
                server_ip = optarg;
                break;
            case 'p':
                server_port = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold] [-i server_ip] [-p server_port]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c(i2c_address) < 0) {
        gpioTerminate();
        return 1;
    }

    // Configure sensor
    if (configure_sensor(i2c_handle) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    int16_t x_raw, y_raw, z_raw;
    float x_g, y_g, z_g;

    // Main loop
    while (running) {
        // Read acceleration data
        if (read_acceleration(i2c_handle, &x_raw, &y_raw, &z_raw) == 0) {
            // Convert to g
            x_g = convert_to_g(x_raw);
            y_g = convert_to_g(y_raw);
            z_g = convert_to_g(z_raw);

            // Check for threshold exceedance
            if (fabs(x_g) > threshold || fabs(y_g) > threshold || fabs(z_g) > threshold) {
                log_event(x_g, y_g, z_g);
                send_data_to_server(x_g, y_g, z_g);
                system("sudo shutdown -h now");
                break; // Exit the loop after shutdown is triggered
            }
        } else {
            fprintf(stderr, "Error reading acceleration data. Continuing...\n");
        }

        gpioDelay(100); // 10 Hz sampling rate
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

