#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define LEFT_SENSOR_PIN 4
#define CENTER_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27
#define ALERT_PIN 22

// Define motor control pins (placeholders)
#define MOTOR_LEFT_FORWARD 5
#define MOTOR_LEFT_BACKWARD 6
#define MOTOR_RIGHT_FORWARD 12
#define MOTOR_RIGHT_BACKWARD 13

// Define circular buffer size
#define BUFFER_SIZE 5

// Define alert duration
#define ALERT_DURATION 2 // seconds

// Define motor speed (PWM duty cycle)
#define MOTOR_SPEED 150

// Global variables
volatile sig_atomic_t program_running = 1;

// Circular buffer structure
typedef struct {
    int buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int read_sensor(int gpio_pin);
void add_to_buffer(CircularBuffer *cb, int value);
int get_from_buffer(CircularBuffer *cb, int index);
void move_forward();
void turn_left();
void turn_right();
void stop();
void alert();
void signal_handler(int signal);
void initialize_gpio();
void cleanup_gpio();

// Circular buffer functions
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Function to read sensor value
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to add value to circular buffer
void add_to_buffer(CircularBuffer *cb, int value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Function to get value from circular buffer
int get_from_buffer(CircularBuffer *cb, int index) {
    if (index < 0 || index >= cb->count) {
        fprintf(stderr, "Error: Index out of bounds\n");
        return -1; // Indicate error
    }
    int real_index = (cb->head - cb->count + index + BUFFER_SIZE) % BUFFER_SIZE;
    return cb->buffer[real_index];
}

