#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SI7210_ADDR 0x30
#define RELAY_GPIO 17
#define FIELD_THRESHOLD 5000 // 5.0 mT * 100
#define SAMPLE_INTERVAL_MS 100
#define TIMEOUT_ATTEMPTS 50

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize();
int read_field_strength(int *field_raw);
float convert_to_mT(int field_raw);
void control_relay(int state);
void log_event(const char *message);
void signal_handler(int signal);

// Function to initialize the system
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_event("pigpio initialisation failed");
        return -1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI7210_ADDR, 0);
    if (i2c_handle < 0) {
        log_event("I2C open failed");
        gpioTerminate();
        return -1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Initially off

    // Open log file
    log_file = fopen("magnetic_events.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read the magnetic field strength from the Si7210
int read_field_strength(int *field_raw) {
    int attempts = 0;
    int status;

    // Start a conversion
    if (i2cWriteByteData(i2c_handle, 0xC1, 0x01) < 0) {
        log_event("Failed to start conversion");
        return -1;
    }

    // Poll until conversion is complete
    do {
        status = i2cReadByteData(i2c_handle, 0xC1);
        if (status < 0) {
            log_event("Failed to read conversion status");
            return -1;
        }
        if (status != 0x00) {
            gpioDelay(1000); // Wait 1 ms
            attempts++;
        }
    } while (status != 0x00 && attempts < TIMEOUT_ATTEMPTS);

    if (status != 0x00) {
        log_event("Timeout waiting for conversion");
        return -1;
    }

    // Read the raw data
    int lsb = i2cReadByteData(i2c_handle, 0xC0);
    if (lsb < 0) {
        log_event("Failed to read LSB");
        return -1;
    }

    int msb = i2cReadByteData(i2c_handle, 0xC0 + 1);
    if (msb < 0) {
        log_event("Failed to read MSB");
        return -1;
    }

    *field_raw = (msb << 8) | lsb;
    return 0;
}

// Function to convert the raw data to milliTesla
float convert_to_mT(int field_raw) {
    return (float)field_raw * 25.0 / 1000.0;
}

// Function to control the relay
void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
}

// Function to log events to a file
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file);
    printf("%s: %s\n", timestamp, message);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    log_event("Received signal, shutting down...");
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize the system
    if (initialize() != 0) {
        return 1;
    }

    int field_raw;
    float field_mT;
    int relay_state = 0; // 0 = off, 1 = on

    // Main loop
    while (program_running) {
        // Read field strength
        if (read_field_strength(&field_raw) == 0) {
            // Convert to milliTesla
            field_mT = convert_to_mT(field_raw);

            // Log the reading
            char message[100];
            snprintf(message, sizeof(message), "Field strength: %.2f mT", field_mT);
            log_event(message);

            // Control the relay
            if (field_mT > FIELD_THRESHOLD) {
                if (relay_state == 0) {
                    control_relay(1);
                    relay_state = 1;
                    log_event("Relay activated");
                }
            } else {
                if (relay_state == 1) {
                    control_relay(0);
                    relay_state = 0;
                    log_event("Relay deactivated");
                }
            }
        } else {
            log_event("Failed to read field strength");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Convert ms to us
    }

    // Cleanup
    i2cClose(i2c_handle);
    control_relay(0);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

