#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define PORT 5000
#define GPIO_PIN 18
#define BUFFER_SIZE 1024

// Global variables for graceful shutdown
int server_socket = -1;
FILE *log_file = NULL;

// Function prototypes
int setup_gpio();
int setup_socket();
void handle_client(int client_socket);
void log_event(const char *message);
void cleanup();
void signal_handler(int signum);

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (setup_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Create and configure the server socket
    server_socket = setup_socket();
    if (server_socket == -1) {
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("relay_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    log_event("Server started");

    // Main server loop
    struct sockaddr_in client_addr;
    socklen_t client_len = sizeof(client_addr);
    int client_socket;

    while (1) {
        client_socket = accept(server_socket, (struct sockaddr *)&client_addr, &client_len);
        if (client_socket == -1) {
            perror("Accept failed");
            log_event("Error: Accept failed");
            continue; // Continue listening for new connections
        }

        log_event("Client connected");

        handle_client(client_socket);

        close(client_socket);
        log_event("Client disconnected");
    }

    return 0;
}

// Function to initialize the pigpio library and set the GPIO pin as output
int setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Initialize relay to OFF state
    return 0;
}

// Function to create and configure the server socket
int setup_socket() {
    int server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket == -1) {
        perror("Socket creation failed");
        return -1;
    }

    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(PORT);

    if (bind(server_socket, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Bind failed");
        close(server_socket);
        return -1;
    }

    if (listen(server_socket, 3) < 0) {
        perror("Listen failed");
        close(server_socket);
        return -1;
    }

    printf("Listening on port %d\n", PORT);
    return server_socket;
}

// Function to handle client connections and process commands
void handle_client(int client_socket) {
    char buffer[BUFFER_SIZE];
    ssize_t bytes_received;

    while ((bytes_received = recv(client_socket, buffer, BUFFER_SIZE - 1, 0)) > 0) {
        buffer[bytes_received] = '\0'; // Null-terminate the received data
        char *command = strtok(buffer, "\r\n"); // Remove trailing whitespace

        if (command != NULL) {
            if (strcasecmp(command, "ON") == 0) {
                gpioWrite(GPIO_PIN, 1); // Turn relay ON
                log_event("Relay turned ON");
                send(client_socket, "Relay ON", strlen("Relay ON"), 0);
            } else if (strcasecmp(command, "OFF") == 0) {
                gpioWrite(GPIO_PIN, 0); // Turn relay OFF
                log_event("Relay turned OFF");
                send(client_socket, "Relay OFF", strlen("Relay OFF"), 0);
            } else {
                log_event("Invalid command received");
                send(client_socket, "Invalid command", strlen("Invalid command"), 0);
            }
        }
    }

    if (bytes_received < 0) {
        perror("Receive failed");
        log_event("Error: Receive failed");
    }
}

// Function to log events to a file with a timestamp
void log_event(const char *message) {
    if (log_file != NULL) {
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[26];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

        fprintf(log_file, "[%s] %s\n", timestamp, message);
        fflush(log_file); // Ensure the log is written immediately
    }
}

// Function to perform cleanup operations before exiting
void cleanup() {
    log_event("Server shutting down");

    if (server_socket != -1) {
        close(server_socket);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioWrite(GPIO_PIN, 0); // Turn off the relay
    gpioTerminate(); // Terminate pigpio
}

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, shutting down...\n", signum);
        cleanup();
        exit(0);
    }
}

