    for (int i = 0; i < DEBOUNCE_READS; i++) {
        if (gpioRead(RAIN_SENSOR_PIN) == 1) {
            dry_count++;
        }
        gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Convert ms to microseconds
    }
    return (dry_count == DEBOUNCE_READS);
}

