            motor_running = 1;
            gpioDelay(MOTOR_RUN_TIME_MS * 1000); // Convert ms to microseconds
            control_motor(0); // Stop motor
            motor_running = 0;
            consecutive_dry = 0; // Reset counter after motor run
        }
    } else {
        consecutive_dry = 0; // Reset counter if rain is detected
    }
}

