#include <string.h>

// Define GPIO pins
#define PIR_PIN 4
#define LED_PIN 17

// Define log file name
#define LOG_FILE "security_log.txt"

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
int control_led(int state);
int log_event(const char *event_type, const char *timestamp, int duration);
int cleanup();
void signal_handler(int signal);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PIR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    return 0;
}

// Function to read the PIR sensor
int read_pir_sensor() {
    return gpioRead(PIR_PIN);
}

// Function to control the LED
int control_led(int state) {
    gpioWrite(LED_PIN, state);
    return 0;
}

// Function to log events to a file
int log_event(const char *event_type, const char *timestamp, int duration) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return 1;
    }

    fprintf(log_file, "%s: %s, Duration: %d seconds\n", event_type, timestamp, duration);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Function to cleanup resources before exiting
int cleanup() {
    printf("Cleaning up and exiting...\n");

    // Turn off the LED
    control_led(0);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

// Signal handler for Ctrl+C and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("Signal received (%d).  Shutting down...\n", signal);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        cleanup();
        return 1;
    }

    printf("Smart Security Light System started. Press Ctrl+C to exit.\n");

    time_t start_time, end_time;
    int motion_detected = 0;
    int led_on = 0;
    int led_duration = 60; // LED on duration in seconds

    while (program_running) {
        int pir_value = read_pir_sensor();

        if (pir_value == 1 && !motion_detected) {
            // Motion detected
            motion_detected = 1;
            time(&start_time);
            control_led(1);
            led_on = 1;

            // Log motion detection event
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[80];

            time(&rawtime);
            timeinfo = localtime(&rawtime);

            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);
            log_event("Motion Detected", timestamp, 0); // Duration is not known yet
        }

        if (led_on && motion_detected) {
            time(&end_time);
            double elapsed_time = difftime(end_time, start_time);
            int elapsed_seconds = (int)elapsed_time;

            if (elapsed_seconds >= led_duration) {
                // LED duration reached
                control_led(0);
                led_on = 0;
                motion_detected = 0;

                // Log LED deactivation event
                time_t rawtime;
                struct tm *timeinfo;
                char timestamp[80];

                time(&rawtime);
                timeinfo = localtime(&rawtime);

                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);
                log_event("LED Deactivated", timestamp, led_duration);
            }
        }

        gpioDelay(100); // Poll every 100ms
    }

    // Cleanup resources before exiting
    cleanup();

    return 0;
}

