#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define DEBOUNCE_TIME 200 // milliseconds

// Global variables
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int mpr121_init();
int read_touch_status(uint16_t *touch_status);
int toggle_relay(int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    toggle_relay(0); // Ensure relay is OFF on exit
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// MPR121 initialization function
int mpr121_init() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        fprintf(stderr, "Error: MPR121 soft reset failed\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure baseline filtering
    if (i2cWriteByteData(i2c_handle, 0x2B, 0x01) < 0) return -1; // MHD_R
    if (i2cWriteByteData(i2c_handle, 0x2C, 0x01) < 0) return -1; // NHD_R
