    if (i2cWriteByteData(i2c_handle, 0x7B, 0x01) < 0) return -1; // Electrode config
    if (i2cWriteByteData(i2c_handle, 0x7C, 0x01) < 0) return -1; // Electrode config
    if (i2cWriteByteData(i2c_handle, 0x7D, 0x00) < 0) return -1; // Electrode config

