#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <syslog.h>
#include <pthread.h>
#include <time.h>
#include <gpiod.h>
#include <stdarg.h>
#include <errno.h>

// Configuration
#define GPIO_CHIP "gpiochip0"
#define SERVO_PIN 17
#define PIR_PIN 4
#define TCP_PORT 5000
#define SERVO_MIN_PULSE_WIDTH 1000 // microseconds
#define SERVO_MAX_PULSE_WIDTH 2000 // microseconds
#define SERVO_FREQUENCY 50          // Hz
#define PWM_PERIOD (1000000 / SERVO_FREQUENCY) // microseconds
#define LOG_FILE "security.log"

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *servo_line = NULL;
static struct gpiod_line *pir_line = NULL;
static int server_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
void log_message(int priority, const char *format, ...);
void log_error(const char *format, ...);
void signal_handler(int sig);
void *servo_thread(void *arg);
int set_servo_angle(int angle);
int read_pir_sensor();
void handle_client(int client_fd);
void cleanup();

// Logging function
void log_message(int priority, const char *format, ...) {
    va_list args;
    va_start(args, format);
    char buffer[256];
    vsnprintf(buffer, sizeof(buffer), format, args);
    va_end(args);

    // Syslog
    syslog(priority, "%s", buffer);

    // File log
    if (log_file != NULL) {
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);
        fprintf(log_file, "%s %s\n", timestamp, buffer);
        fflush(log_file);
    }
}

// Error logging function
void log_error(const char *format, ...) {
    va_list args;
    va_start(args, format);
    char buffer[256];
    vsnprintf(buffer, sizeof(buffer), format, args);
    va_end(args);

    // Syslog
    syslog(LOG_ERR, "%s", buffer);

    // File log
    if (log_file != NULL) {
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);
        fprintf(log_file, "%s ERROR: %s\n", timestamp, buffer);
        fflush(log_file);
    }
}

// Signal handler
void signal_handler(int sig) {
    log_message(LOG_INFO, "Signal received: %d. Terminating...", sig);
    terminate = 1;
}

// Servo thread function
void *servo_thread(void *arg) {
    struct gpiod_line *line = (struct gpiod_line *)arg;
    int angle = 0;
    int pulse_width = SERVO_MIN_PULSE_WIDTH;
    struct timespec on_time, off_time;
    on_time.tv_sec = 0;
    on_time.tv_nsec = pulse_width * 1000; // Convert microseconds to nanoseconds
    off_time.tv_sec = 0;
    off_time.tv_nsec = PWM_PERIOD * 1000 - pulse_width * 1000;

    while (!terminate) {
        if (gpiod_line_set_value(line, 1) < 0) {
            log_error("Failed to set servo line value high");
            break;
        }
        nanosleep(&on_time, NULL);

        if (gpiod_line_set_value(line, 0) < 0) {
            log_error("Failed to set servo line value low");
            break;
        }
        nanosleep(&off_time, NULL);
    }

    pthread_exit(NULL);
    return NULL;
}

// Set servo angle
int set_servo_angle(int angle) {
    if (angle < 0 || angle > 180) {
        log_error("Invalid servo angle: %d. Must be between 0 and 180.", angle);
        return -1;
    }

    // Calculate pulse width based on angle
    int pulse_width = SERVO_MIN_PULSE_WIDTH + (int)(((float)angle / 180.0) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH));

    // Update pulse width (this is a placeholder, the actual PWM is done in the servo thread)
    // In a real application, you would need to communicate the new pulse width to the servo thread.
    // For simplicity, we just log the intended angle and pulse width here.
    log_message(LOG_INFO, "Setting servo angle to %d, pulse width: %d", angle, pulse_width);

    return 0;
}

// Read PIR sensor
int read_pir_sensor() {
    int value = gpiod_line_get_value(pir_line);
    if (value < 0) {
        log_error("Failed to read PIR sensor value");
        return -1;
    }
    return value;
}

// Handle client connection
void handle_client(int client_fd) {
    char buffer[1024];
    ssize_t bytes_received;

    while ((bytes_received = recv(client_fd, buffer, sizeof(buffer) - 1, 0)) > 0) {
        buffer[bytes_received] = '\0';
        log_message(LOG_INFO, "Received command: %s", buffer);

        if (strncmp(buffer, "SERVO", 5) == 0) {
            int angle = atoi(buffer + 6);
            if (set_servo_angle(angle) != 0) {
                send(client_fd, "ERROR: Invalid servo angle\n", strlen("ERROR: Invalid servo angle\n"), 0);
            } else {
                send(client_fd, "OK\n", strlen("OK\n"), 0);
            }
        } else if (strncmp(buffer, "PIR", 3) == 0) {
            int pir_value = read_pir_sensor();
            if (pir_value == 0 || pir_value == 1) {
                char response[32];
                snprintf(response, sizeof(response), "PIR:%d\n", pir_value);
                send(client_fd, response, strlen(response), 0);
            } else {
                send(client_fd, "ERROR: Failed to read PIR sensor\n", strlen("ERROR: Failed to read PIR sensor\n"), 0);
            }
        } else {
            send(client_fd, "ERROR: Invalid command\n", strlen("ERROR: Invalid command\n"), 0);
        }
    }

    if (bytes_received < 0) {
        log_error("Error receiving data from client");
    }

    close(client_fd);
    log_message(LOG_INFO, "Client disconnected");
}

// Cleanup function
void cleanup() {
    log_message(LOG_INFO, "Cleaning up resources...");

    // Stop servo thread (if running)
    if (servo_line != NULL) {
        gpiod_line_set_value(servo_line, 0); // Set to 0 before releasing
    }

    // Release GPIO resources
    if (servo_line != NULL) {
        gpiod_line_release(servo_line);
    }
    if (pir_line != NULL) {
        gpiod_line_release(pir_line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    // Close socket
    if (server_fd != -1) {
        close(server_fd);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Close syslog
    closelog();

    log_message(LOG_INFO, "Cleanup complete. Exiting.");
}

int main() {
    // Initialize syslog
    openlog("security_system", LOG_PID | LOG_CONS, LOG_USER);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        log_error("Failed to open log file: %s", strerror(errno));
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize libgpiod
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        log_error("Failed to open GPIO chip: %s", strerror(errno));
        cleanup();
        return 1;
    }

    servo_line = gpiod_chip_get_line(chip, SERVO_PIN);
    if (!servo_line) {
        log_error("Failed to get servo line: %s", strerror(errno));
        cleanup();
        return 1;
    }

    pir_line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!pir_line) {
        log_error("Failed to get PIR line: %s", strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(servo_line, "servo", 0) < 0) {
        log_error("Failed to request servo line as output: %s", strerror(errno));
        cleanup();
        return 1;
    }

    if (gpiod_line_request_input(pir_line, "pir") < 0) {
        log_error("Failed to request PIR line as input: %s", strerror(errno));
        cleanup();
        return 1;
    }

    // Create TCP socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd == -1) {
        log_error("Failed to create socket: %s", strerror(errno));
        cleanup();
        return 1;
    }

    // Bind socket to address and port
    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(TCP_PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        log_error("Failed to bind socket: %s", strerror(errno));
        cleanup();
        return 1;
    }

    // Listen for connections
    if (listen(server_fd, 3) < 0) {
        log_error("Failed to listen on socket: %s", strerror(errno));
        cleanup();
        return 1;
    }

    log_message(LOG_INFO, "Listening on port %d", TCP_PORT);

    // Accept connections and handle them
    while (!terminate) {
        struct sockaddr_in client_address;
        socklen_t client_len = sizeof(client_address);
        int client_fd = accept(server_fd, (struct sockaddr *)&client_address, &client_len);
        if (client_fd < 0) {
            if (terminate) break; // Exit if accept fails due to termination signal
            log_error("Failed to accept connection: %s", strerror(errno));
            continue; // Continue listening
        }

        log_message(LOG_INFO, "Client connected from %s:%d", inet_ntoa(client_address.sin_addr), ntohs(client_address.sin_port));

        handle_client(client_fd);
    }

    // Cleanup resources before exiting
    cleanup();

    return 0;
}

