#include <string.h>
#include <errno.h>

// Constants
#define BH1750_ADDR 0x23
#define GROW_LIGHT_GPIO 23
#define LUX_THRESHOLD 150.0
#define I2C_BUS 1
#define I2C_FLAGS 0
#define BH1750_COMMAND 0x20
#define LOG_FILE "grow_log.txt"

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_bh1750(float *lux);
int control_relay(int state);
int log_data(float lux);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int bh1750_address;
    int grow_light_pin;
    float lux_threshold;
    int i2c_bus;
    int i2c_flags;
    char *log_file_name;
} config_t;

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, I2C_FLAGS);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read lux value from BH1750 sensor
int read_bh1750(float *lux) {
    char buf[2];
    int result;

    // Send One-Time High-Resolution mode command
    result = i2cWriteByte(i2c_handle, BH1750_COMMAND);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    // Wait for at least 120ms for measurement
    gpioDelay(120000); // 120 ms

    // Read 2 bytes from the sensor
    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    // Convert raw data to lux
    uint16_t raw_value = (buf[0] << 8) | buf[1];
    *lux = (float)raw_value / 1.2;

    return 0;
}

// Control the grow light relay
int control_relay(int state) {
    gpioWrite(GROW_LIGHT_GPIO, state);
    return 0;
}

// Log data to file
int log_data(float lux) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s, %.2f\n", timestamp, lux);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(GROW_LIGHT_GPIO, 0); // Deactivate relay
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO23 as output for the relay
    gpioSetMode(GROW_LIGHT_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float lux;
    int relay_state = 0; // 0 = off, 1 = on

    // Main loop
    while (!terminate) {
        if (read_bh1750(&lux) == 0) {
            printf("Lux: %.2f\n", lux);

            if (lux < LUX_THRESHOLD && relay_state == 0) {
                control_relay(1); // Activate relay
                relay_state = 1;
                printf("Activating grow light\n");
            } else if (lux >= LUX_THRESHOLD && relay_state == 1) {
                control_relay(0); // Deactivate relay
                relay_state = 0;
                printf("Deactivating grow light\n");
            }

            log_data(lux);
        } else {
            fprintf(stderr, "Error reading BH1750. Retrying...\n");
            // Attempt to re-initialize I2C
            i2cClose(i2c_handle);
            if (init_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C. Continuing without sensor.\n");
            }
        }

        gpioDelay(2000000); // 2 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

