#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define DOUT_PIN 23
#define SCK_PIN 24
#define SOLENOID_PIN 25

// Default values
#define DEFAULT_THRESHOLD 1000.0
#define DEFAULT_SCALE 1.0
#define DEFAULT_DURATION 200
#define DEFAULT_TARE_READINGS 10
#define DEFAULT_MEASUREMENT_READINGS 5

// Global variables
static volatile int running = 1;
static double threshold = DEFAULT_THRESHOLD;
static double scale = DEFAULT_SCALE;
static int duration = DEFAULT_DURATION;
static int tare_readings = DEFAULT_TARE_READINGS;
static int measurement_readings = DEFAULT_MEASUREMENT_READINGS;
static double tare_offset = 0.0;

// Function prototypes
int read_hx711();
double calculate_weight(int raw_value);
void tare_load_cell();
void control_solenoid(double weight);
void signal_handler(int signal);
void log_message(int priority, const char *message);

// HX711 read function
int read_hx711() {
    int data = 0;
    int timeout = 1000; // Timeout in milliseconds
    unsigned long start_time = gpioTick();

    // Wait for DOUT to go LOW
    while (gpioRead(DOUT_PIN) == 1) {
        if (gpioTick() - start_time > timeout * 1000) {
            log_message(LOG_ERR, "HX711 timeout waiting for DOUT to go LOW");
            return -1; // Indicate error
        }
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    // Clock out 24 bits
    for (int i = 0; i < 24; i++) {
        gpioWrite(SCK_PIN, 1);
        gpioDelay(1); // Clock high
        data = data << 1;
        if (gpioRead(DOUT_PIN) == 1) {
            data++;
        }
        gpioWrite(SCK_PIN, 0);
        gpioDelay(1); // Clock low
    }

    // Send one additional clock pulse to select Channel A / Gain 128
    gpioWrite(SCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(SCK_PIN, 0);
    gpioDelay(1);

    // Convert to signed 32-bit integer
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Calculate weight from raw value
double calculate_weight(int raw_value) {
    return (raw_value - tare_offset) / scale;
}

// Tare the load cell
void tare_load_cell() {
    double sum = 0.0;
    for (int i = 0; i < tare_readings; i++) {
        int raw_value = read_hx711();
        if (raw_value == -1) {
            log_message(LOG_ERR, "Error reading HX711 during tare");
            return; // Exit tare if there's an error
        }
        sum += raw_value;
        gpioDelay(10); // Small delay between readings
    }
    tare_offset = sum / tare_readings;
    log_message(LOG_INFO, "Tare complete");
}

// Control the solenoid lock
void control_solenoid(double weight) {
    if (weight > threshold) {
        log_message(LOG_INFO, "Weight exceeds threshold, activating solenoid");
        gpioWrite(SOLENOID_PIN, 1); // Activate solenoid
        gpioDelay(duration);         // Keep solenoid active for specified duration
        gpioWrite(SOLENOID_PIN, 0); // Deactivate solenoid
        log_message(LOG_INFO, "Solenoid deactivated");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_message(LOG_INFO, "Received signal, shutting down...");
}

// Log messages to syslog
void log_message(int priority, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    char log_message[256];
    snprintf(log_message, sizeof(log_message), "%s: %s", timestamp, message);
    syslog(priority, "%s", log_message);
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "t:s:d:r:m:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            case 's':
                scale = atof(optarg);
                break;
            case 'd':
                duration = atoi(optarg);
                break;
            case 'r':
                tare_readings = atoi(optarg);
                break;
            case 'm':
                measurement_readings = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-s scale] [-d duration] [-r tare_readings] [-m measurement_readings]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize syslog
    openlog("weight_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(DOUT_PIN, PI_INPUT);
    gpioSetMode(SCK_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Set solenoid pin low initially
    gpioWrite(SOLENOID_PIN, 0);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Tare the load cell
    tare_load_cell();

    // Main loop
    while (running) {
        double sum = 0.0;
        for (int i = 0; i < measurement_readings; i++) {
            int raw_value = read_hx711();
            if (raw_value == -1) {
                log_message(LOG_ERR, "Error reading HX711, retrying...");
                i--; // Retry the reading
                gpioDelay(100); // Wait before retrying
                continue;
            }
            sum += raw_value;
            gpioDelay(10); // Small delay between readings
        }
        double average_raw = sum / measurement_readings;
        double weight = calculate_weight(average_raw);

        char log_buffer[128];
        snprintf(log_buffer, sizeof(log_buffer), "Weight: %.2f grams", weight);
        log_message(LOG_INFO, log_buffer);

        control_solenoid(weight);

        gpioDelay(500); // Poll every 500 ms
    }

    // Cleanup
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is off
    gpioTerminate();            // Terminate pigpio
    closelog();                 // Close syslog

    return 0;
}

