                scale = atof(optarg);
                break;
            case 'd':
                duration = atoi(optarg);
                break;
            case 'r':
                tare_readings = atoi(optarg);
                break;
            case 'm':
                measurement_readings = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-s scale] [-d duration] [-r tare_readings] [-m measurement_readings]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize syslog
    openlog("weight_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(DOUT_PIN, PI_INPUT);
    gpioSetMode(SCK_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Set solenoid pin low initially
    gpioWrite(SOLENOID_PIN, 0);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Tare the load cell
    tare_load_cell();

    // Main loop
    while (running) {
        double sum = 0.0;
        for (int i = 0; i < measurement_readings; i++) {
            int raw_value = read_hx711();
            if (raw_value == -1) {
                log_message(LOG_ERR, "Error reading HX711, retrying...");
                i--; // Retry the reading
                gpioDelay(100); // Wait before retrying
                continue;
            }
            sum += raw_value;
            gpioDelay(10); // Small delay between readings
        }
        double average_raw = sum / measurement_readings;
        double weight = calculate_weight(average_raw);

        char log_buffer[128];
        snprintf(log_buffer, sizeof(log_buffer), "Weight: %.2f grams", weight);
        log_message(LOG_INFO, log_buffer);

        control_solenoid(weight);

        gpioDelay(500); // Poll every 500 ms
    }

    // Cleanup
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is off
    gpioTerminate();            // Terminate pigpio
    closelog();                 // Close syslog

    return 0;
}

