#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <time.h>
#include <mosquitto.h>
#include <pigpio.h>

#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_TOPIC "home/lights/control"
#define GPIO_PIN 17

static struct mosquitto *mosq = NULL;
static volatile int running = 1;

// Function to set the relay state
int set_relay_state(int state) {
    if (gpioWrite(GPIO_PIN, state) != 0) {
        syslog(LOG_ERR, "Failed to write to GPIO %d", GPIO_PIN);
        return -1;
    }
    return 0;
}

// Message callback function
void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        char *payload = (char *)message->payload;
        syslog(LOG_INFO, "Received message on topic %s: %s", message->topic, payload);

        if (strcmp(payload, "ON") == 0) {
            if (set_relay_state(1) != 0) {
                syslog(LOG_ERR, "Failed to set relay ON");
            }
        } else if (strcmp(payload, "OFF") == 0) {
            if (set_relay_state(0) != 0) {
                syslog(LOG_ERR, "Failed to set relay OFF");
            }
        } else {
            syslog(LOG_ERR, "Invalid payload received: %s", payload);
        }
    } else {
        syslog(LOG_ERR, "Empty payload received");
    }
}

// Connect callback function
void connect_callback(struct mosquitto *mosq, void *userdata, int result) {
    if (!result) {
        syslog(LOG_INFO, "Connected to MQTT broker");
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    } else {
        syslog(LOG_ERR, "Connection failed: %s", mosquitto_connack_string(result));
    }
}

// Disconnect callback function
void disconnect_callback(struct mosquitto *mosq, void *userdata, int rc) {
    syslog(LOG_INFO, "Disconnected from MQTT broker with code %d", rc);
}

// Function to handle signals
void signal_handler(int signum) {
    syslog(LOG_INFO, "Signal received: %d. Shutting down...", signum);
    running = 0;
}

int main() {
    // Initialize syslog
    openlog("mqtt_relay", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    // Initialize relay to OFF state
    set_relay_state(0);

    // Initialize libmosquitto
    mosquitto_lib_init();

    // Create a new mosquitto client instance
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create mosquitto client instance");
        gpioTerminate();
        closelog();
        mosquitto_lib_cleanup();
        return 1;
    }

    // Set callbacks
    mosquitto_connect_callback_set(mosq, connect_callback);
    mosquitto_disconnect_callback_set(mosq, disconnect_callback);
    mosquitto_message_callback_set(mosq, message_callback);

    // Connect to the MQTT broker
    int rc = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(rc));
        gpioTerminate();
        closelog();
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        rc = mosquitto_loop(mosq, -1, 1);
        if (rc != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "mosquitto_loop error: %s", mosquitto_strerror(rc));
            mosquitto_destroy(mosq);
            mosquitto_lib_cleanup();
            sleep(5);
            mosquitto_lib_init();
            mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
            if (!mosq) {
                syslog(LOG_ERR, "Failed to create mosquitto client instance after reconnect");
                gpioTerminate();
                closelog();
                mosquitto_lib_cleanup();
                return 1;
            }
            mosquitto_connect_callback_set(mosq, connect_callback);
            mosquitto_disconnect_callback_set(mosq, disconnect_callback);
            mosquitto_message_callback_set(mosq, message_callback);
            rc = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
            if (rc != MOSQ_ERR_SUCCESS) {
                syslog(LOG_ERR, "Failed to reconnect to MQTT broker: %s", mosquitto_strerror(rc));
                running = 0; // Exit loop if reconnection fails repeatedly
            }
        }
    }

    // Cleanup
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioWrite(GPIO_PIN, 0); // Ensure relay is off on exit
    gpioTerminate();
    closelog();

    return 0;
}

