#define SERVO1_PULSE_WIDTH 1000
#define SERVO2_PULSE_WIDTH 1500
#define SERVO3_PULSE_WIDTH 2000
#define SERVO4_PULSE_WIDTH 500
#define SERVO5_PULSE_WIDTH 2500

// Define PWM frequency and range
#define PWM_FREQUENCY 50
#define PWM_RANGE 20000 // 20ms period * 1000000 us/second / 50 Hz

// Function to set the pulse width for a servo
void set_servo_pulse_width(int pin, int pulse_width) {
    gpioPWM(pin, pulse_width);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set PWM frequency and range for each servo pin
    gpioSetPWMfrequency(SERVO1_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(SERVO1_PIN, PWM_RANGE);
    gpioSetPWMfrequency(SERVO2_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(SERVO2_PIN, PWM_RANGE);
    gpioSetPWMfrequency(SERVO3_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(SERVO3_PIN, PWM_RANGE);
    gpioSetPWMfrequency(SERVO4_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(SERVO4_PIN, PWM_RANGE);
    gpioSetPWMfrequency(SERVO5_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(SERVO5_PIN, PWM_RANGE);

    // Set the pulse widths for each servo
    set_servo_pulse_width(SERVO1_PIN, SERVO1_PULSE_WIDTH);
    set_servo_pulse_width(SERVO2_PIN, SERVO2_PULSE_WIDTH);
    set_servo_pulse_width(SERVO3_PIN, SERVO3_PULSE_WIDTH);
    set_servo_pulse_width(SERVO4_PIN, SERVO4_PULSE_WIDTH);
    set_servo_pulse_width(SERVO5_PIN, SERVO5_PULSE_WIDTH);

    // Wait for 3 seconds
    sleep(3);

    // Stop PWM and terminate pigpio
    gpioPWM(SERVO1_PIN, 0);
    gpioPWM(SERVO2_PIN, 0);
    gpioPWM(SERVO3_PIN, 0);
    gpioPWM(SERVO4_PIN, 0);
    gpioPWM(SERVO5_PIN, 0);
    gpioTerminate();

    return 0;
}

