#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define GPIO_RELAY 17
#define LUX_THRESHOLD_DUSK 50.0
#define LUX_THRESHOLD_DAWN 200.0
#define LUX_HYSTERESIS 10.0
#define I2C_READ_DELAY_MS 180
#define POLL_INTERVAL_S 5

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize();
int read_bh1750(float *lux);
int control_relay(int state);
int log_data(float lux, int relay_state);
void signal_handler(int signal);
void cleanup();

// Structure to hold program state
typedef struct {
    int relay_state;
    float last_lux;
} ProgramState;

ProgramState state = {0, 0.0}; // Initialize relay state to OFF and last lux to 0.0

int main() {
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float lux;
    int relay_state = state.relay_state; // Initialize relay state from struct

    while (program_running) {
        if (read_bh1750(&lux) == 0) {
            state.last_lux = lux; // Update last lux reading

            if (lux < LUX_THRESHOLD_DUSK && relay_state == 0) {
                // Dusk: Turn on the relay
                if (control_relay(1) == 0) {
                    relay_state = 1; // Update relay state in struct
                    log_data(lux, relay_state);
                }
            } else if (lux > LUX_THRESHOLD_DAWN + LUX_HYSTERESIS && relay_state == 1) {
                // Dawn: Turn off the relay
                if (control_relay(0) == 0) {
                    relay_state = 0; // Update relay state in struct
                    log_data(lux, relay_state);
                }
            } else {
                // No change in relay state
                log_data(lux, relay_state);
            }
        } else {
            fprintf(stderr, "Error reading BH1750 sensor.\n");
            control_relay(0); // Turn off relay on error
            log_data(-1.0, 0); // Log error
        }

        sleep(POLL_INTERVAL_S);
    }

    cleanup();
    return 0;
}

int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO 17 as output
    gpioSetMode(GPIO_RELAY, PI_OUTPUT);
    gpioWrite(GPIO_RELAY, 0); // Initialize relay to OFF

    // Open log file
    log_file = fopen("chicken_coop_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

int read_bh1750(float *lux) {
    // Send One-Time High-Resolution Mode 2 command
    if (i2cWriteByteData(i2c_handle, 0x00, 0x21) < 0) {
        fprintf(stderr, "Failed to write to I2C device\n");
        return 1;
    }

    // Delay for 180ms
    gpioDelay(I2C_READ_DELAY_MS * 1000); // Delay in microseconds

    // Read 2 bytes of lux data
    char buffer[2];
    if (i2cReadI2CBlockData(i2c_handle, 0x00, buffer, 2) != 2) {
        fprintf(stderr, "Failed to read from I2C device\n");
        return 1;
    }

    // Convert raw data to lux
    unsigned int raw_value = (buffer[0] << 8) | buffer[1];
    *lux = (float)raw_value / 1.2;

    return 0;
}

int control_relay(int state) {
    // Set GPIO 17 to the desired state
    gpioWrite(GPIO_RELAY, state);
    return 0;
}

int log_data(float lux, int relay_state) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s: Lux = %.2f, Relay = %s\n", timestamp, lux, relay_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to file immediately
    return 0;
}

void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    program_running = 0;
}

void cleanup() {
    // Turn off the relay
    control_relay(0);

    // Close I2C bus
    i2cClose(i2c_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

