#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variable to store the current relay state
static int relay_state = 0;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
int debounce_touch();
int toggle_relay();
int log_relay_state(int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        gpioWrite(RELAY_PIN, 0); // Turn off the relay
        gpioTerminate(); // Release pigpio resources
        exit(0);
    }
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO 4 as input
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }

    // Set GPIO 17 as output
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_PIN);
        gpioTerminate();
        return 1;
    }

    return 0; // Indicate success
}

// Function to read the touch sensor state
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to debounce the touch sensor
int debounce_touch() {
    int initial_state = read_touch_sensor();
    gpioDelay(DEBOUNCE_DELAY * 1000); // Delay for debounce
    int final_state = read_touch_sensor();

    if (initial_state == final_state && initial_state == 1) {
        return 1; // Valid touch
    } else {
        return 0; // Invalid touch
    }
}

// Function to toggle the relay state
int toggle_relay() {
    relay_state = !relay_state; // Toggle the state
    gpioWrite(RELAY_PIN, relay_state); // Set the GPIO pin
    return relay_state;
}

// Function to log the relay state with timestamp
int log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    printf("%s Relay is now %s\n", timestamp, state ? "ON" : "OFF");
    return 0;
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Relay control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        if (read_touch_sensor() == 1) {
            if (debounce_touch()) {
                int new_state = toggle_relay();
                log_relay_state(new_state);
            }
        }
        gpioDelay(10000); // Sleep for 10 milliseconds
    }

    return 0; // This line will never be reached due to the infinite loop
}

