#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <jansson.h>

// Configuration structure
typedef struct {
    int hx711_data_pin;
    int hx711_clock_pin;
    int servo_pin;
    double calibration_factor;
    char server_ip[20];
    int server_port;
} Config;

// Global variables
static volatile int running = 1;
static int socket_desc;
static Config config;

// Function prototypes
int read_config(const char *filename, Config *config);
int init_gpio();
int init_socket();
double read_hx711();
double calibrate_hx711(double known_weight);
void set_servo_pulse_width(int pulse_width);
double map_weight_to_pulse_width(double target_weight);
int send_data(int socket, const char *data);
int receive_data(int socket, char *buffer, int buffer_size);
void log_dispensing_event(double target_weight, double actual_weight, const char *error_message);
void signal_handler(int signal);

// HX711 read function
double read_hx711() {
    int i;
    int data = 0;
    int timeout = 1000; // Timeout after 1000 attempts

    gpioSetMode(config.hx711_data_pin, PI_INPUT);
    gpioSetMode(config.hx711_clock_pin, PI_OUTPUT);

    // Wait for the HX711 to be ready
    int attempts = 0;
    while (gpioRead(config.hx711_data_pin) == 1 && attempts < timeout) {
        gpioDelay(1); // Wait 1 us
        attempts++;
    }

    if (attempts >= timeout) {
        log_dispensing_event(0.0, 0.0, "HX711 timeout: DATA pin HIGH after clock pulses.");
        return -1.0; // Indicate error
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(config.hx711_clock_pin, 1);
        gpioDelay(1); // 1 us
        data = data << 1;
        if (gpioRead(config.hx711_data_pin)) {
            data++;
        }
        gpioWrite(config.hx711_clock_pin, 0);
        gpioDelay(1); // 1 us
    }

    // Pulse the clock pin 1 more time to set the gain to 128
    gpioWrite(config.hx711_clock_pin, 1);
    gpioDelay(1); // 1 us
    gpioWrite(config.hx711_clock_pin, 0);
    gpioDelay(1); // 1 us

    // Convert to signed 2's complement
    if (data & 0x800000) {
        data |= ~0xffffff;
    }

    return (double)data;
}

// HX711 calibration function
double calibrate_hx711(double known_weight) {
    double raw_value = read_hx711();
    if (raw_value < 0) return -1.0; // Indicate error
    return known_weight / raw_value;
}

// Servo control function
void set_servo_pulse_width(int pulse_width) {
    if (pulse_width < 1000 || pulse_width > 2000) {
        log_dispensing_event(0.0, 0.0, "Invalid pulse width. Must be between 1000 and 2000.");
        return;
    }

    gpioServo(config.servo_pin, pulse_width);
}

// Weight mapping function
double map_weight_to_pulse_width(double target_weight) {
    // Assuming a linear relationship between target weight and pulse width
    // Adjust the constants as needed based on your specific setup
    double pulse_width = 1000.0 + (target_weight / 100.0) * 1000.0; // Example mapping
    return pulse_width;
}

// Network communication functions
int send_data(int socket, const char *data) {
    if (send(socket, data, strlen(data), 0) < 0) {
        perror("Send failed");
        return -1;
    }
    return 0;
}

int receive_data(int socket, char *buffer, int buffer_size) {
    memset(buffer, 0, buffer_size);
    if (recv(socket, buffer, buffer_size - 1, 0) < 0) {
        perror("Receive failed");
        return -1;
    }
    return 0;
}

// Logging function
void log_dispensing_event(double target_weight, double actual_weight, const char *error_message) {
    json_t *root = json_object();
    json_object_set_new(root, "timestamp", json_string(time(NULL)));
    json_object_set_new(root, "target_weight", json_real(target_weight));
    json_object_set_new(root, "actual_weight", json_real(actual_weight));
    json_object_set_new(root, "error_message", json_string(error_message));

    char *json_str = json_dumps(root, JSON_INDENT(4));
    if (json_str) {
        FILE *fp = fopen("dispensing_log.json", "a");
        if (fp) {
            fprintf(fp, "%s\n", json_str);
            fclose(fp);
        } else {
            perror("Failed to open dispensing_log.json");
        }
        free(json_str);
    } else {
        perror("Failed to serialize JSON");
    }

    json_decref(root);
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    gpioTerminate();
    close(socket_desc);
    exit(0);
}

// Configuration reading function
int read_config(const char *filename, Config *config) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Error: Could not open config file %s. Using default values.\n", filename);
        // Set default values
        config->hx711_data_pin = 23;
        config->hx711_clock_pin = 24;
        config->servo_pin = 18;
        config->calibration_factor = 1.0; // Default calibration factor
        strcpy(config->server_ip, "127.0.0.1");
        config->server_port = 12345;
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        // Remove newline character
        line[strcspn(line, "\n")] = 0;

        // Skip comments and empty lines
        if (line[0] == '#' || line[0] == '\0') continue;

        char *key = strtok(line, "=");
        char *value = strtok(NULL, "=");

        if (key && value) {
            if (strcmp(key, "hx711_data_pin") == 0) {
                config->hx711_data_pin = atoi(value);
            } else if (strcmp(key, "hx711_clock_pin") == 0) {
                config->hx711_clock_pin = atoi(value);
            } else if (strcmp(key, "servo_pin") == 0) {
                config->servo_pin = atoi(value);
            } else if (strcmp(key, "calibration_factor") == 0) {
                config->calibration_factor = atof(value);
            } else if (strcmp(key, "server_ip") == 0) {
                strcpy(config->server_ip, value);
            } else if (strcmp(key, "server_port") == 0) {
                config->server_port = atoi(value);
            }
        }
    }

    fclose(fp);
    return 0;
}

// GPIO initialization function
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(config.servo_pin, PI_OUTPUT);
    gpioSetPWMfrequency(config.servo_pin, 50); // 50 Hz for SG90 servo
    gpioSetPWMrange(config.servo_pin, 2000); // Set PWM range to 2000 for finer control

    return 0;
}

// Socket initialization function
int init_socket() {
    struct sockaddr_in server_addr;

    // Create socket
    socket_desc = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_desc < 0) {
        perror("Could not create socket");
        return -1;
    }

    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = inet_addr(config.server_ip);
    server_addr.sin_port = htons(config.server_port);

    // Connect to remote server
    if (connect(socket_desc, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Connect failed");
        close(socket_desc);
        return -1;
    }

    printf("Connected to server\n");
    return 0;
}

int main() {
    // Read configuration
    if (read_config("config.ini", &config) != 0) {
        printf("Using default configuration.\n");
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        return 1;
    }

    // Initialize socket
    if (init_socket() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    char buffer[256];
    double target_weight, actual_weight;
    int pulse_width;

    while (running) {
        // Receive target weight from server
        if (receive_data(socket_desc, buffer, sizeof(buffer)) == 0) {
            target_weight = atof(buffer);
            printf("Received target weight: %.2f grams\n", target_weight);

            // Open servo
            pulse_width = (int)map_weight_to_pulse_width(target_weight);
            set_servo_pulse_width(pulse_width);
            gpioDelay(1000); // Wait 1 second

            // Read actual weight from HX711
            actual_weight = read_hx711();
            if (actual_weight < 0) {
                log_dispensing_event(target_weight, 0.0, "Error reading HX711.");
                send_data(socket_desc, "Error reading HX711");
            } else {
                printf("Actual weight: %.2f grams\n", actual_weight);

                // Send actual weight back to server
                snprintf(buffer, sizeof(buffer), "%.2f", actual_weight);
                if (send_data(socket_desc, buffer) != 0) {
                    log_dispensing_event(target_weight, actual_weight, "Error sending data to server.");
                }

                // Log dispensing event
                log_dispensing_event(target_weight, actual_weight, "");
            }
        } else {
            printf("No data received from server.\n");
            log_dispensing_event(0.0, 0.0, "No data received from server.");
        }

        sleep(1); // Check for new data every 1 second
    }

    // Clean up
    gpioTerminate();
    close(socket_desc);

    return 0;
}

