        return -1;
    }

    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = inet_addr(config.server_ip);
    server_addr.sin_port = htons(config.server_port);

    // Connect to remote server
    if (connect(socket_desc, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Connect failed");
        close(socket_desc);
        return -1;
    }

    printf("Connected to server\n");
    return 0;
}

int main() {
    // Read configuration
    if (read_config("config.ini", &config) != 0) {
        printf("Using default configuration.\n");
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        return 1;
    }

    // Initialize socket
    if (init_socket() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    char buffer[256];
    double target_weight, actual_weight;
    int pulse_width;

    while (running) {
        // Receive target weight from server
        if (receive_data(socket_desc, buffer, sizeof(buffer)) == 0) {
            target_weight = atof(buffer);
            printf("Received target weight: %.2f grams\n", target_weight);

            // Open servo
            pulse_width = (int)map_weight_to_pulse_width(target_weight);
            set_servo_pulse_width(pulse_width);
            gpioDelay(1000); // Wait 1 second

            // Read actual weight from HX711
            actual_weight = read_hx711();
            if (actual_weight < 0) {
                log_dispensing_event(target_weight, 0.0, "Error reading HX711.");
                send_data(socket_desc, "Error reading HX711");
            } else {
                printf("Actual weight: %.2f grams\n", actual_weight);

                // Send actual weight back to server
                snprintf(buffer, sizeof(buffer), "%.2f", actual_weight);
                if (send_data(socket_desc, buffer) != 0) {
                    log_dispensing_event(target_weight, actual_weight, "Error sending data to server.");
                }

                // Log dispensing event
                log_dispensing_event(target_weight, actual_weight, "");
            }
        } else {
            printf("No data received from server.\n");
            log_dispensing_event(0.0, 0.0, "No data received from server.");
        }

        sleep(1); // Check for new data every 1 second
    }

    // Clean up
    gpioTerminate();
    close(socket_desc);

    return 0;
}

