#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Global variable to store the relay state
int relay_state = 0; // 0 = OFF, 1 = ON

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
int toggle_relay();
void log_relay_state(int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioWrite(RELAY_PIN, 0); // Turn off the relay
    gpioTerminate(); // Release pigpio resources
    exit(0);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    gpioWrite(RELAY_PIN, 0); // Initialize relay to OFF state
    return 0; // Indicate success
}

// Function to read the touch sensor with debouncing
int read_touch_sensor() {
    int stable_count = 0;
    int current_value;
    int debounce_delay = 50; // Default debounce delay in milliseconds

    // Check if a command-line argument is provided for debounce delay
    if (argc > 1) {
        char *endptr;
        long delay = strtol(argv[1], &endptr, 10);

        if (*endptr != '\0' || delay <= 0) {
            fprintf(stderr, "Invalid debounce delay argument. Using default value of 50ms.\n");
        } else {
            debounce_delay = (int)delay;
        }
    }

    // Read the sensor value and check for stability
    for (int i = 0; i < 5; i++) {
        current_value = gpioRead(TOUCH_SENSOR_PIN);
        gpioDelay(debounce_delay * 1000); // Delay in microseconds
        if (gpioRead(TOUCH_SENSOR_PIN) == current_value) {
            stable_count++;
        }
    }

    // If the sensor value is stable for 4 out of 5 readings, return the value
    if (stable_count >= 4) {
        return current_value;
    } else {
        return -1; // Indicate unstable reading
    }
}

// Function to toggle the relay state
int toggle_relay() {
    relay_state = !relay_state; // Toggle the state
    gpioWrite(RELAY_PIN, relay_state);
    return relay_state;
}

// Function to log the relay state with a timestamp
void log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (state == 1) {
        printf("%s Relay: ON\n", timestamp);
    } else {
        printf("%s Relay: OFF\n", timestamp);
    }
}

int main(int argc, char *argv[]) {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Touch-controlled relay switch started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        int sensor_value = read_touch_sensor();

        if (sensor_value == 1) {
            int new_relay_state = toggle_relay();
            log_relay_state(new_relay_state);
        } else if (sensor_value == -1) {
            fprintf(stderr, "Touch sensor reading unstable. Skipping toggle.\n");
        }

        gpioDelay(10000); // Delay for 10ms to avoid busy-waiting
    }

    return 0; // This line will never be reached due to the infinite loop
}

