#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <termios.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define PWM_FREQUENCY 50
#define PULSE_WIDTH_MIN 500
#define PULSE_WIDTH_MAX 2500
#define ANGLE_MIN 0
#define ANGLE_MAX 180

static struct termios original_termios;
static volatile int running = 1;

// Function to handle SIGINT (Ctrl+C)
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the terminal for non-blocking keyboard input
int init_terminal() {
    struct termios new_termios;

    // Save the original terminal settings
    if (tcgetattr(STDIN_FILENO, &original_termios) != 0) {
        perror("tcgetattr");
        return -1;
    }

    // Set the new terminal settings
    new_termios = original_termios;
    new_termios.c_lflag &= ~(ICANON | ECHO); // Disable canonical mode and echo
    new_termios.c_cc[VMIN] = 0;              // Read non-blocking
    new_termios.c_cc[VTIME] = 0;             // No timeout

    if (tcsetattr(STDIN_FILENO, TCSANOW, &new_termios) != 0) {
        perror("tcsetattr");
        return -1;
    }

    return 0;
}

// Function to restore the terminal settings
void restore_terminal() {
    if (tcsetattr(STDIN_FILENO, TCSANOW, &original_termios) != 0) {
        perror("tcsetattr (restore)");
    }
}

// Function to calculate pulse width from angle
int calculate_pulse_width(int angle) {
    if (angle < ANGLE_MIN) {
        angle = ANGLE_MIN;
    } else if (angle > ANGLE_MAX) {
        angle = ANGLE_MAX;
    }

    return (int)(((float)(angle - ANGLE_MIN) / (ANGLE_MAX - ANGLE_MIN)) * (PULSE_WIDTH_MAX - PULSE_WIDTH_MIN) + PULSE_WIDTH_MIN);
}

// Function to set the servo angle using gpioServo
int set_servo_angle(int angle) {
    int pulse_width = calculate_pulse_width(angle);
    if (pulse_width < PULSE_WIDTH_MIN || pulse_width > PULSE_WIDTH_MAX) {
        fprintf(stderr, "Error: Pulse width out of range: %d\n", pulse_width);
        return -1;
    }

    gpioServo(SERVO_PIN, pulse_width);
    return 0;
}

int main() {
    int angle = 90; // Initial angle
    int input;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(SERVO_PIN, PWM_FREQUENCY);

    // Initialize terminal
    if (init_terminal() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Servo control program. Press + to increase angle, - to decrease, q to quit.\n");

    // Main loop
    while (running) {
        input = getchar();

        if (input == '+') {
            angle += 10;
        } else if (input == '-') {
            angle -= 10;
        } else if (input == 'q') {
            running = 0;
        } else {
            // Ignore other input
            continue;
        }

        if (set_servo_angle(angle) != 0) {
            fprintf(stderr, "Failed to set servo angle\n");
        }

        printf("Angle: %d\n", angle);
    }

    // Stop PWM
    gpioServo(SERVO_PIN, 0);

    // Restore terminal settings
    restore_terminal();

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

