        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    memset(&config, 0, sizeof(config));
    config.consumer = "motor_rpm_monitor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return -1;
    }

    // Enable pull-up resistor
    if (gpiod_line_set_bias(line, GPIOD_LINE_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "Error setting pull-up bias on GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to cleanup GPIO
void cleanup_gpio(void) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_fp) {
        fclose(log_fp);
    }
}

// Function to read sensor with debouncing
int read_sensor(void) {
    struct timespec now;
    int value;
    int ret;

    ret = gpiod_line_event_wait(line, &now);
    if (ret < 0) {
        if (errno == EINTR) {
            // Interrupted by signal, return 0 to avoid false positive
            return 0;
        }
        fprintf(stderr, "Error waiting for event: %s\n", strerror(errno));
        return -1;
    }

    if (ret == 0) {
        // Timeout, no event
        return 0;
    }

    ret = gpiod_line_get_value(line);
    if (ret < 0) {
        fprintf(stderr, "Error getting line value: %s\n", strerror(errno));
        return -1;
    }

    value = ret;

    clock_gettime(CLOCK_MONOTONIC, &now);
    if (now.tv_nsec - program_state.last_edge_time.tv_nsec < DEBOUNCE_NS) {
        // Debounce: ignore the edge
        return 0;
    }

    program_state.last_edge_time = now;
    program_state.pulse_count++;

    return 1;
}

// Function to calculate RPM
double calculate_rpm(int pulse_count) {
    return (double)pulse_count / 5.0 * 60.0;
}

// Function to log RPM to file
int log_rpm(double rpm) {
    char *timestamp = iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Error generating timestamp\n");
        return -1;
    }

    fprintf(log_fp, "%s,%.2f\n", timestamp, rpm);
    fflush(log_fp);
    free(timestamp);

    return 0;
}

// Function to generate ISO 8601 timestamp
char* iso8601_timestamp(void) {
    struct timespec ts;
    char *buf = malloc(30 * sizeof(char)); // Allocate memory for the timestamp string
    if (buf == NULL) {
        perror("malloc");
        return NULL;
    }

    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm *tm_info = localtime(&ts.tv_sec);

    strftime(buf, 30, "%Y-%m-%dT%H:%M:%S", tm_info);
    snprintf(buf + strlen(buf), 30 - strlen(buf), ".%09ldZ", ts.tv_nsec);

    return buf;
}

int main(void) {
    struct timespec sleep_time;
    int ret;
    double rpm;
    program_state.last_edge_time.tv_sec = 0;
    program_state.last_edge_time.tv_nsec = 0;
    program_state.pulse_count = 0;

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        return EXIT_FAILURE;
    }

    // Open log file
    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    // Set sleep time for 5 seconds
    sleep_time.tv_sec = 5;
    sleep_time.tv_nsec = 0;

    // Main loop
    while (!terminate) {
        ret = read_sensor();
        if (ret < 0) {
            fprintf(stderr, "Error reading sensor, exiting...\n");
            break;
        }

        nanosleep(&sleep_time, NULL);

        rpm = calculate_rpm(program_state.pulse_count);
        printf("RPM: %.2f\n", rpm);

        if (log_rpm(rpm) < 0) {
            fprintf(stderr, "Error logging RPM, exiting...\n");
            break;
        }

        program_state.pulse_count = 0; // Reset pulse count after logging
    }

    // Cleanup and exit
    cleanup_gpio();
    return EXIT_SUCCESS;
}

