#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Define constants
#define RELAY_ON 1
#define RELAY_OFF 0
#define TOUCH_DEBOUNCE_MS 50
#define TOUCH_TIMEOUT_S 10

// Global variables
volatile sig_atomic_t program_running = 1;
int relay_state = RELAY_OFF; // Initial relay state is OFF
time_t touch_start_time = 0; // Time when touch is detected
int touch_detected = 0; // Flag to indicate if a touch is currently detected

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
int toggle_relay();
int control_relay(int state);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", RELAY_PIN);
        gpioTerminate();
        return 1;
    }

    return 0; // Indicate success
}

// Function to read the touch sensor with debouncing
int read_touch_sensor() {
    int touch_value = gpioRead(TOUCH_SENSOR_PIN);
    if (touch_value < 0) {
        fprintf(stderr, "Error reading GPIO%d: %d\n", TOUCH_SENSOR_PIN, touch_value);
        return -1; // Indicate error
    }

    if (touch_value == 1) {
        // Touch detected, debounce
        gpioDelay(TOUCH_DEBOUNCE_MS * 1000); // Debounce for 50ms
        if (gpioRead(TOUCH_SENSOR_PIN) == 1) {
            return 1; // Valid touch
        }
    }

    return 0; // No touch or debouncing failed
}

// Function to toggle the relay state
int toggle_relay() {
    relay_state = !relay_state;
    return control_relay(relay_state);
}

// Function to control the relay
int control_relay(int state) {
    if (gpioWrite(RELAY_PIN, state) != 0) {
        fprintf(stderr, "Failed to write to GPIO%d\n", RELAY_PIN);
        return 1; // Indicate failure
    }
    return 0; // Indicate success
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    control_relay(RELAY_OFF); // Ensure relay is OFF
    gpioTerminate(); // Terminate pigpio
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Touch-activated relay control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int touch = read_touch_sensor();

        if (touch == 1) {
            if (!touch_detected) {
                // First touch detection
                touch_detected = 1;
                touch_start_time = time(NULL);
                printf("Touch detected! Toggling relay.\n");
                toggle_relay();
            } else {
                // Touch still detected, check timeout
                time_t current_time = time(NULL);
                if (difftime(current_time, touch_start_time) > TOUCH_TIMEOUT_S) {
                    // Touch timeout, force relay OFF
                    printf("Touch timeout! Forcing relay OFF.\n");
                    control_relay(RELAY_OFF);
                    touch_detected = 0; // Reset touch detection
                }
            }
        } else if (touch == 0) {
            // No touch detected, reset timeout and touch detection
            touch_detected = 0;
        } else {
            // Error reading touch sensor
            fprintf(stderr, "Error reading touch sensor. Continuing...\n");
        }

        gpioDelay(10000); // Poll every 10ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

