#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define VALVE_GPIO 18
#define ENABLE_GPIO 23
#define FLOW_SENSOR_GPIO 24
#define TARGET_FLOW_RATE_ARG "-t"
#define PULSES_PER_LITER 450.0
#define KP 1.0
#define PWM_FREQUENCY 1000 // Hz
#define LOG_FILE "flow_log.csv"

// Global variables
static volatile int pulse_count = 0;
static FILE *log_file = NULL;
static double target_flow_rate = 0.0;
static int running = 1;

// Function prototypes
void pulse_counter_isr(int gpio, int level, uint32_t tick, void *user_data);
double calculate_flow_rate(int pulse_count, double time_interval);
int calculate_pwm_duty_cycle(double flow_rate, double target_flow_rate, double kp);
void log_data(double timestamp_ms, double flow_rate, int valve_position);
void signal_handler(int signal);
int initialize();
void cleanup();

// Interrupt service routine for flow sensor pulses
void pulse_counter_isr(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio; // unused
    (void)level; // unused
    (void)tick; // unused
    (void)user_data; // unused
    pulse_count++;
}

// Calculate flow rate in L/min
double calculate_flow_rate(int pulse_count, double time_interval) {
    return (double)pulse_count / PULSES_PER_LITER / time_interval * 60.0;
}

// Calculate PWM duty cycle using proportional control
int calculate_pwm_duty_cycle(double flow_rate, double target_flow_rate, double kp) {
    double error = target_flow_rate - flow_rate;
    double duty_cycle = kp * error;

    // Clamp duty cycle to [0, 255]
    if (duty_cycle < 0) {
        duty_cycle = 0;
    } else if (duty_cycle > 255) {
        duty_cycle = 255;
    }

    return (int)duty_cycle;
}

// Log data to CSV file
void log_data(double timestamp_ms, double flow_rate, int valve_position) {
    if (log_file != NULL) {
        fprintf(log_file, "%.3f,%.3f,%d\n", timestamp_ms, flow_rate, valve_position);
        fflush(log_file); // Ensure data is written to disk immediately
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal; // unused
    running = 0;
    printf("\nCaught signal, exiting gracefully...\n");
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(VALVE_GPIO, PI_OUTPUT);
    gpioSetMode(ENABLE_GPIO, PI_OUTPUT);
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(VALVE_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(VALVE_GPIO, 255); // Set PWM range to 0-255

    // Enable the valve
    gpioWrite(ENABLE_GPIO, 1);

    // Register interrupt service routine for flow sensor
    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, pulse_counter_isr, NULL) != 0) {
        fprintf(stderr, "Failed to register ISR function\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    // Disable the valve
    gpioWrite(ENABLE_GPIO, 0);
    gpioPWM(VALVE_GPIO, 0); // Set PWM to 0

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    int target_flow_rate_index = -1;
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], TARGET_FLOW_RATE_ARG) == 0) {
            target_flow_rate_index = i + 1;
            break;
        }
    }

    if (target_flow_rate_index == -1) {
        fprintf(stderr, "Usage: %s %s <target_flow_rate_L/min>\n", argv[0], TARGET_FLOW_RATE_ARG);
        return 1;
    }

    if (target_flow_rate_index < argc) {
        char *endptr;
        target_flow_rate = strtod(argv[target_flow_rate_index], &endptr);

        if (*endptr != '\0' || target_flow_rate <= 0) {
            fprintf(stderr, "Invalid target flow rate: %s\n", argv[target_flow_rate_index]);
            return 1;
        }
    } else {
        fprintf(stderr, "Missing target flow rate argument\n");
        return 1;
    }

    // Initialize
    if (initialize()) {
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int last_pulse_count = 0;
    double last_time = time_time();
    while (running) {
        // Sample flow rate every 100 ms
        double current_time = time_time();
        double time_interval = current_time - last_time;

        if (time_interval >= 0.1) {
            // Calculate flow rate
            int current_pulse_count = pulse_count;
            int pulse_count_diff = current_pulse_count - last_pulse_count;
            double flow_rate = calculate_flow_rate(pulse_count_diff, time_interval);

            // Calculate PWM duty cycle
            int pwm_duty_cycle = calculate_pwm_duty_cycle(flow_rate, target_flow_rate, KP);

            // Set PWM duty cycle
            gpioPWM(VALVE_GPIO, pwm_duty_cycle);

            // Log data
            double timestamp_ms = (current_time - (int)current_time) * 1000.0;
            log_data(timestamp_ms, flow_rate, pwm_duty_cycle);

            // Update last pulse count and time
            last_pulse_count = current_pulse_count;
            last_time = current_time;
        }

        gpioDelay(10); // Sleep for 10 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

