// Define log file path
const char *log_file_path = "/var/log/door_access.log";

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_rfid_tag(unsigned char *tag_data);
int authenticate_tag(const unsigned char *tag_data, const unsigned char *valid_tag);
int read_button();
void engage_lock(int lock_pin);
void disengage_lock(int lock_pin);
void log_event(const char *event_message);
void signal_handler(int signal);

// Function to read RFID tag via SPI
int read_rfid_tag(unsigned char *tag_data) {
    char tx_buf[10] = {0}; // Dummy data to send
    char rx_buf[10];

    if (spiXfer(spi_handle, tx_buf, rx_buf, 10) != 0) {
        log_event("RFID read failure");
        return -1;
    }

    memcpy(tag_data, rx_buf, 10);

    // Check for no tag present (all zeros)
    int all_zeros = 1;
    for (int i = 0; i < 10; i++) {
        if (tag_data[i] != 0) {
            all_zeros = 0;
            break;
        }
    }

    if (all_zeros) {
        log_event("No tag present");
        return -1;
    }

    return 0;
}

// Function to authenticate RFID tag
int authenticate_tag(const unsigned char *tag_data, const unsigned char *valid_tag) {
    if (memcmp(tag_data, valid_tag, 10) == 0) {
        return 0; // Authentication successful
    } else {
        log_event("Invalid tag");
        return -1; // Authentication failed
    }
}

// Function to read button state
int read_button() {
    return gpioRead(BUTTON_PIN);
}

// Function to engage the lock
void engage_lock(int lock_pin) {
    gpioWrite(lock_pin, 1); // Set GPIO HIGH to engage the lock
}

// Function to disengage the lock
void disengage_lock(int lock_pin) {
    gpioWrite(lock_pin, 0); // Set GPIO LOW to disengage the lock
    gpioDelay(5000);        // Wait for 5 seconds
    gpioWrite(lock_pin, 1); // Re-engage the lock
}

// Function to log events to file
void log_event(const char *event_message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s: %s\n", timestamp, event_message);
    fflush(log_file); // Ensure the log is written immediately
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(log_file_path, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LOCK1_PIN, PI_OUTPUT);
    gpioSetMode(LOCK2_PIN, PI_OUTPUT);
    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP); // Enable pull-up resistor

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // SPI channel 0, 100kHz, mode 0
    if (spi_handle < 0) {
        log_event("SPI open failed");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    unsigned char tag_data[10];

    printf("Two-factor authentication system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read RFID tag
        if (read_rfid_tag(tag_data) == 0) {
            // Authenticate tag
            if (authenticate_tag(tag_data, valid_tag) == 0) {
                // Read button
                if (read_button() == 0) {
                    // Authenticate button press
                    log_event("Authentication successful");
                    disengage_lock(LOCK1_PIN);
                    disengage_lock(LOCK2_PIN);
                } else {
                    log_event("Button press without valid tag");
                }
            }
        }

        gpioDelay(100); // Small delay to avoid busy-waiting
    }

    // Clean up
    spiClose(spi_handle);
    engage_lock(LOCK1_PIN); // Engage locks on exit
    engage_lock(LOCK2_PIN);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

