#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <pigpio.h>

// Motor 1
#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25

// Motor 2
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20

// Encoder 1
#define ENCODER1_A 5
#define ENCODER1_B 6

// Encoder 2
#define ENCODER2_A 26
#define ENCODER2_B 19

// PID Constants
#define KP 1.0
#define KI 0.1
#define KD 0.01

// Target RPMs
#define TARGET_RPM1 60.0
#define TARGET_RPM2 60.0

// PWM Frequency
#define PWM_FREQUENCY 100

// Encoder Pulses per Revolution
#define PPR 600.0

// Global Variables
volatile long encoder1_count = 0;
volatile long encoder2_count = 0;
double motor1_speed = 0.0;
double motor2_speed = 0.0;

FILE *log_file = NULL;
pthread_mutex_t encoder_mutex = PTHREAD_MUTEX_INITIALIZER;

// Structure to pass arguments to the encoder thread
typedef struct {
    int a_pin;
    int b_pin;
    long *encoder_count;
} encoder_args_t;

// Function Prototypes
void *encoder_thread(void *arg);
void set_motor_speed(int motor, int speed);
double calculate_pid(double target_rpm, double actual_rpm, double *integral, double *previous_error);
void log_data(double motor1_rpm, double motor2_rpm, double motor1_p, double motor1_i, double motor1_d, double motor1_output, double motor2_p, double motor2_i, double motor2_d, double motor2_output);
void signal_handler(int signal);
int initialize_gpio();
void cleanup_gpio();

// PID Controller Structure
typedef struct {
    double kp;
    double ki;
    double kd;
    double integral;
    double previous_error;
} pid_controller_t;

pid_controller_t motor1_pid = {KP, KI, KD, 0.0, 0.0};
pid_controller_t motor2_pid = {KP, KI, KD, 0.0, 0.0};

int main() {
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("motor_log.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup_gpio();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Motor1_RPM,Motor2_RPM,Motor1_P,Motor1_I,Motor1_D,Motor1_Output,Motor2_P,Motor2_I,Motor2_D,Motor2_Output\n");
    }
    fflush(log_file);

    // Create encoder threads
    pthread_t encoder_thread1, encoder_thread2;
    encoder_args_t encoder1_args = {ENCODER1_A, ENCODER1_B, &encoder1_count};
    encoder_args_t encoder2_args = {ENCODER2_A, ENCODER2_B, &encoder2_count};

    if (pthread_create(&encoder_thread1, NULL, encoder_thread, &encoder1_args) != 0) {
        perror("Failed to create encoder thread 1");
        cleanup_gpio();
        fclose(log_file);
        return 1;
    }

    if (pthread_create(&encoder_thread2, NULL, encoder_thread, &encoder2_args) != 0) {
        perror("Failed to create encoder thread 2");
        cleanup_gpio();
        fclose(log_file);
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main control loop
    while (1) {
        // Calculate RPMs
        pthread_mutex_lock(&encoder_mutex);
        motor1_speed = (double)encoder1_count * 60.0 / PPR;
        motor2_speed = (double)encoder2_count * 60.0 / PPR;
        encoder1_count = 0;
        encoder2_count = 0;
        pthread_mutex_unlock(&encoder_mutex);

        // Calculate PID outputs
        double motor1_output = calculate_pid(TARGET_RPM1, motor1_speed, &motor1_pid.integral, &motor1_pid.previous_error);
        double motor2_output = calculate_pid(TARGET_RPM2, motor2_speed, &motor2_pid.integral, &motor2_pid.previous_error);

        // Set motor speeds
        set_motor_speed(1, (int)motor1_output);
        set_motor_speed(2, (int)motor2_output);

        // Log data
        log_data(motor1_speed, motor2_speed, KP, KI, KD, motor1_output, KP, KI, KD, motor2_output);

        // Sleep for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    return 0;
}

void *encoder_thread(void *arg) {
    encoder_args_t *args = (encoder_args_t *)arg;
    int a_pin = args->a_pin;
    int b_pin = args->b_pin;
    long *encoder_count = args->encoder_count;
    int last_a_state = gpioRead(a_pin);
    int b_state = gpioRead(b_pin);

    while (1) {
        int a_state = gpioRead(a_pin);
        if (a_state != last_a_state) {
            if (a_state == 1) {
                if (gpioRead(b_pin) != b_state) {
                    pthread_mutex_lock(&encoder_mutex);
                    (*encoder_count)++;
                    pthread_mutex_unlock(&encoder_mutex);
                }
            } else {
                if (gpioRead(b_pin) == b_state) {
                    pthread_mutex_lock(&encoder_mutex);
                    (*encoder_count)++;
                    pthread_mutex_unlock(&encoder_mutex);
                }
            }
            last_a_state = a_state;
        }
        gpioDelay(1000); // Check every 1ms
    }
    return NULL;
}

void set_motor_speed(int motor, int speed) {
    int ena_pin, in1_pin, in2_pin;

    if (motor == 1) {
        ena_pin = MOTOR1_ENA;
        in1_pin = MOTOR1_IN1;
        in2_pin = MOTOR1_IN2;
    } else if (motor == 2) {
        ena_pin = MOTOR2_ENB;
        in1_pin = MOTOR2_IN3;
        in2_pin = MOTOR2_IN4;
    } else {
        fprintf(stderr, "Invalid motor number: %d\n", motor);
        return;
    }

    if (speed > 0) {
        gpioWrite(in1_pin, 1);
        gpioWrite(in2_pin, 0);
        gpioPWM(ena_pin, speed);
    } else if (speed < 0) {
        gpioWrite(in1_pin, 0);
        gpioWrite(in2_pin, 1);
        gpioPWM(ena_pin, -speed);
    } else {
        gpioWrite(in1_pin, 0);
        gpioWrite(in2_pin, 0);
        gpioPWM(ena_pin, 0);
    }
}

double calculate_pid(double target_rpm, double actual_rpm, double *integral, double *previous_error) {
    double error = target_rpm - actual_rpm;
    *integral += error;
    double derivative = error - *previous_error;
    double output = KP * error + KI * (*integral) + KD * derivative;
    *previous_error = error;
    return output;
}

void log_data(double motor1_rpm, double motor2_rpm, double motor1_p, double motor1_i, double motor1_d, double motor1_output, double motor2_p, double motor2_i, double motor2_d, double motor2_output) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
            timestamp, motor1_rpm, motor2_rpm, motor1_p, motor1_i, motor1_d, motor1_output, motor2_p, motor2_i, motor2_d, motor2_output);
    fflush(log_file);
}

void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    set_motor_speed(1, 0);
    set_motor_speed(2, 0);
    cleanup_gpio();
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Motor 1
    gpioSetMode(MOTOR1_ENA, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN2, PI_OUTPUT);

    // Motor 2
    gpioSetMode(MOTOR2_ENB, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN4, PI_OUTPUT);

    // Encoder 1
    gpioSetMode(ENCODER1_A, PI_INPUT);
    gpioSetMode(ENCODER1_B, PI_INPUT);
    gpioSetPullUpDown(ENCODER1_A, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER1_B, PI_PUD_UP);

    // Encoder 2
    gpioSetMode(ENCODER2_A, PI_INPUT);
    gpioSetMode(ENCODER2_B, PI_INPUT);
    gpioSetPullUpDown(ENCODER2_A, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER2_B, PI_PUD_UP);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR1_ENA, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR2_ENB, PWM_FREQUENCY);

    return 0;
}

void cleanup_gpio() {
    gpioTerminate();
}

