        set_motor_speed(1, (int)motor1_output);
        set_motor_speed(2, (int)motor2_output);

        // Log data
        log_data(motor1_speed, motor2_speed, KP, KI, KD, motor1_output, KP, KI, KD, motor2_output);

        // Sleep for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    return 0;
}

void *encoder_thread(void *arg) {
    encoder_args_t *args = (encoder_args_t *)arg;
    int a_pin = args->a_pin;
    int b_pin = args->b_pin;
    long *encoder_count = args->encoder_count;
    int last_a_state = gpioRead(a_pin);
    int b_state = gpioRead(b_pin);

    while (1) {
        int a_state = gpioRead(a_pin);
        if (a_state != last_a_state) {
            if (a_state == 1) {
                if (gpioRead(b_pin) != b_state) {
                    pthread_mutex_lock(&encoder_mutex);
                    (*encoder_count)++;
                    pthread_mutex_unlock(&encoder_mutex);
                }
            } else {
                if (gpioRead(b_pin) == b_state) {
                    pthread_mutex_lock(&encoder_mutex);
                    (*encoder_count)++;
                    pthread_mutex_unlock(&encoder_mutex);
                }
            }
            last_a_state = a_state;
        }
        gpioDelay(1000); // Check every 1ms
    }
    return NULL;
}

void set_motor_speed(int motor, int speed) {
    int ena_pin, in1_pin, in2_pin;

    if (motor == 1) {
        ena_pin = MOTOR1_ENA;
        in1_pin = MOTOR1_IN1;
        in2_pin = MOTOR1_IN2;
    } else if (motor == 2) {
        ena_pin = MOTOR2_ENB;
        in1_pin = MOTOR2_IN3;
        in2_pin = MOTOR2_IN4;
    } else {
        fprintf(stderr, "Invalid motor number: %d\n", motor);
        return;
    }

    if (speed > 0) {
        gpioWrite(in1_pin, 1);
        gpioWrite(in2_pin, 0);
        gpioPWM(ena_pin, speed);
    } else if (speed < 0) {
        gpioWrite(in1_pin, 0);
        gpioWrite(in2_pin, 1);
        gpioPWM(ena_pin, -speed);
    } else {
        gpioWrite(in1_pin, 0);
        gpioWrite(in2_pin, 0);
        gpioPWM(ena_pin, 0);
    }
}

double calculate_pid(double target_rpm, double actual_rpm, double *integral, double *previous_error) {
    double error = target_rpm - actual_rpm;
    *integral += error;
    double derivative = error - *previous_error;
    double output = KP * error + KI * (*integral) + KD * derivative;
    *previous_error = error;
    return output;
}

void log_data(double motor1_rpm, double motor2_rpm, double motor1_p, double motor1_i, double motor1_d, double motor1_output, double motor2_p, double motor2_i, double motor2_d, double motor2_output) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
            timestamp, motor1_rpm, motor2_rpm, motor1_p, motor1_i, motor1_d, motor1_output, motor2_p, motor2_i, motor2_d, motor2_output);
    fflush(log_file);
}

void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    set_motor_speed(1, 0);
    set_motor_speed(2, 0);
    cleanup_gpio();
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Motor 1
    gpioSetMode(MOTOR1_ENA, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN2, PI_OUTPUT);

    // Motor 2
    gpioSetMode(MOTOR2_ENB, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN4, PI_OUTPUT);

    // Encoder 1
    gpioSetMode(ENCODER1_A, PI_INPUT);
    gpioSetMode(ENCODER1_B, PI_INPUT);
    gpioSetPullUpDown(ENCODER1_A, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER1_B, PI_PUD_UP);

    // Encoder 2
    gpioSetMode(ENCODER2_A, PI_INPUT);
    gpioSetMode(ENCODER2_B, PI_INPUT);
    gpioSetPullUpDown(ENCODER2_A, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER2_B, PI_PUD_UP);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR1_ENA, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR2_ENB, PWM_FREQUENCY);

    return 0;
}

void cleanup_gpio() {
    gpioTerminate();
}

