#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17

// MPR121 Register Addresses
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_SOFTRESET 0x80

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int mpr121_init();
int read_touch_status(uint16_t *touch_status);
void control_relay(int state);
void log_relay_state(int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C detected. Shutting down...\n");
        program_running = 0;
        control_relay(0); // Deactivate relay
        if (i2c_handle >= 0) {
            i2cClose(i2c_handle);
        }
        if (log_file != NULL) {
            fclose(log_file);
        }
        gpioTerminate();
        exit(0);
    }
}

// MPR121 Initialization function
int mpr121_init() {
    // Soft Reset
    if (i2cWriteByteData(i2c_handle, MPR121_SOFTRESET, 0x63) < 0) {
        fprintf(stderr, "Error: MPR121 soft reset failed.\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure Electrode Filter
    if (i2cWriteByteData(i2c_handle, 0x2B, 0x01) < 0) { //MHDR
        fprintf(stderr, "Error: Failed to write MHDR register.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x2C, 0x01) < 0) { //NHDR
        fprintf(stderr, "Error: Failed to write NHDR register.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x2D, 0x00) < 0) { //NFDR
        fprintf(stderr, "Error: Failed to write NFDR register.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x2E, 0x00) < 0) { //NCLR
        fprintf(stderr, "Error: Failed to write NCLR register.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x2F, 0x00) < 0) { //FDLR
        fprintf(stderr, "Error: Failed to write FDLR register.\n");
        return -1;
    }

    // Set Touch and Release Thresholds
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, 0x41 + (i * 2), 0x30) < 0) { // Touch Threshold
            fprintf(stderr, "Error: Failed to write touch threshold for electrode %d.\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, 0x42 + (i * 2), 0x10) < 0) { // Release Threshold
            fprintf(stderr, "Error: Failed to write release threshold for electrode %d.\n", i);
            return -1;
        }
    }

    // Enable Electrodes
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG, 0x0C) < 0) {
        fprintf(stderr, "Error: Failed to enable electrodes.\n");
        return -1;
    }

    return 0;
}

// Function to read touch status from MPR121
int read_touch_status(uint16_t *touch_status) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, MPR121_TOUCHSTATUS_L, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read touch status.\n");
        return -1;
    }
    *touch_status = ((uint16_t)buf[1] << 8) | (uint16_t)buf[0];
    return 0;
}

// Function to control the relay
void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
}

// Function to log relay state to file
void log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Relay: %s\n", timestamp, state ? "ON" : "OFF");
    fflush(log_file); // Ensure immediate write to file
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed.\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO 17 as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("relay_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    uint16_t touch_status = 0;
    int relay_state = 0; // 0 = OFF, 1 = ON

    // Main loop
    while (program_running) {
        if (read_touch_status(&touch_status) == 0) {
            if (touch_status > 0) {
                // Any electrode is touched
                if (relay_state == 0) {
                    control_relay(1);
                    log_relay_state(1);
                    relay_state = 1;
                }
            } else {
                // No electrodes are touched
                if (relay_state == 1) {
                    control_relay(0);
                    log_relay_state(0);
                    relay_state = 0;
                }
            }
        } else {
            fprintf(stderr, "Error: Failed to read touch status. Retrying...\n");
        }

        gpioDelay(50); // Poll every 50ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_relay(0); // Deactivate relay
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

