#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO chip and line numbers
#define GPIOCHIP "gpiochip0"
#define VALVE1_LINE 17
#define VALVE2_LINE 18

// Define valve activation times (milliseconds)
#define VALVE1_DURATION 500
#define VALVE2_DURATION 1000

// Define pause times (seconds)
#define VALVE1_PAUSE 5
#define VALVE2_PAUSE 10

// Define log file name
#define LOG_FILE "valve_log.txt"

// Global variables for GPIO lines and log file
struct gpiod_line *valve1_line = NULL;
struct gpiod_line *valve2_line = NULL;
FILE *log_file = NULL;

// Function prototypes
int valve1_on();
int valve1_off();
int valve2_on();
int valve2_off();
void log_event(int valve_number, int duration_ms);
void signal_handler(int signal);

// Function to activate Valve 1
int valve1_on() {
    int ret = gpiod_line_set_value(valve1_line, 1);
    if (ret < 0) {
        fprintf(stderr, "Error setting Valve 1 HIGH: %s\n", strerror(-ret));
        return -1;
    }
    return 0;
}

// Function to deactivate Valve 1
int valve1_off() {
    int ret = gpiod_line_set_value(valve1_line, 0);
    if (ret < 0) {
        fprintf(stderr, "Error setting Valve 1 LOW: %s\n", strerror(-ret));
        return -1;
    }
    return 0;
}

// Function to activate Valve 2
int valve2_on() {
    int ret = gpiod_line_set_value(valve2_line, 1);
    if (ret < 0) {
        fprintf(stderr, "Error setting Valve 2 HIGH: %s\n", strerror(-ret));
        return -1;
    }
    return 0;
}

// Function to deactivate Valve 2
int valve2_off() {
    int ret = gpiod_line_set_value(valve2_line, 0);
    if (ret < 0) {
        fprintf(stderr, "Error setting Valve 2 LOW: %s\n", strerror(-ret));
        return -1;
    }
    return 0;
}

// Function to log valve activation events
void log_event(int valve_number, int duration_ms) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s - Valve %d activated for %d ms\n", timestamp, valve_number, duration_ms);
    fflush(log_file); // Ensure the log is written immediately
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Deactivate valves
    if (valve1_line != NULL) {
        valve1_off();
    }
    if (valve2_line != NULL) {
        valve2_off();
    }

    // Release GPIO lines
    if (valve1_line != NULL) {
        gpiod_line_release(valve1_line);
    }
    if (valve2_line != NULL) {
        gpiod_line_release(valve2_line);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

int main() {
    struct gpiod_chip *chip;
    int ret;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIOCHIP, strerror(errno));
        fclose(log_file);
        return 1;
    }

    // Get GPIO line for Valve 1
    valve1_line = gpiod_chip_get_line(chip, VALVE1_LINE);
    if (!valve1_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", VALVE1_LINE, strerror(errno));
        gpiod_chip_close(chip);
        fclose(log_file);
        return 1;
    }

    // Request GPIO line for Valve 1 as output
    ret = gpiod_line_request_output(valve1_line, "valve_control", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", VALVE1_LINE, strerror(-ret));
        gpiod_chip_close(chip);
        fclose(log_file);
        return 1;
    }

    // Get GPIO line for Valve 2
    valve2_line = gpiod_chip_get_line(chip, VALVE2_LINE);
    if (!valve2_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", VALVE2_LINE, strerror(errno));
        gpiod_line_release(valve1_line);
        gpiod_chip_close(chip);
        fclose(log_file);
        return 1;
    }

    // Request GPIO line for Valve 2 as output
    ret = gpiod_line_request_output(valve2_line, "valve_control", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", VALVE2_LINE, strerror(-ret));
        gpiod_line_release(valve1_line);
        gpiod_chip_close(chip);
        fclose(log_file);
        return 1;
    }

    // Main loop
    while (1) {
        // Activate Valve 1
        if (valve1_on() == 0) {
            log_event(1, VALVE1_DURATION);
            usleep(VALVE1_DURATION * 1000); // Convert milliseconds to microseconds
        } else {
            fprintf(stderr, "Error activating Valve 1\n");
        }

        // Pause
        sleep(VALVE1_PAUSE);

        // Activate Valve 2
        if (valve2_on() == 0) {
            log_event(2, VALVE2_DURATION);
            usleep(VALVE2_DURATION * 1000); // Convert milliseconds to microseconds
        } else {
            fprintf(stderr, "Error activating Valve 2\n");
        }

        // Pause
        sleep(VALVE2_PAUSE);
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness in case the loop is ever modified.
    gpiod_line_release(valve1_line);
    gpiod_line_release(valve2_line);
    gpiod_chip_close(chip);
    fclose(log_file);

    return 0;
