#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define MPR121_ADDR 0x5A
#define RELAY_PIN 17
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile int running = 1;

// Function prototypes
int initialize_mpr121();
int read_touch_status(unsigned char *touch_status);
void toggle_relay();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

// Function to initialize the MPR121
int initialize_mpr121() {
    // Stop mode
    if (i2cWriteByteData(i2c_handle, 0x2B, 0x00) < 0) {
        fprintf(stderr, "Error writing to MPR121 register 0x2B.\n");
        return -1;
    }

    // Touch and release thresholds
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, 0x41 + 2 * i, 0x10) < 0) {
            fprintf(stderr, "Error writing touch threshold for electrode %d.\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, 0x42 + 2 * i, 0x0A) < 0) {
            fprintf(stderr, "Error writing release threshold for electrode %d.\n", i);
            return -1;
        }
    }

    // Filter/charge time and electrode current
    if (i2cWriteByteData(i2c_handle, 0x2C, 0x20) < 0) {
        fprintf(stderr, "Error writing filter/charge time.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x2D, 0x01) < 0) {
        fprintf(stderr, "Error writing electrode current.\n");
        return -1;
    }

    // Run mode with ELE_EN=1
    if (i2cWriteByteData(i2c_handle, 0x2B, 0x01) < 0) {
        fprintf(stderr, "Error writing to MPR121 register 0x2B.\n");
        return -1;
    }

    // Wait for stabilization
    gpioDelay(100000); // 100ms

    return 0;
}

// Function to read the touch status
int read_touch_status(unsigned char *touch_status) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2) != 2) {
        fprintf(stderr, "Error reading touch status.\n");
        return -1;
    }

    touch_status[0] = buf[0];
    touch_status[1] = buf[1];

    return 0;
}

// Function to toggle the relay
void toggle_relay() {
    int current_level = gpioRead(RELAY_PIN);
    gpioWrite(RELAY_PIN, !current_level);
    printf("Relay toggled to %d\n", !current_level);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set relay pin as output
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Initially off

    // Initialize MPR121
    if (initialize_mpr121() < 0) {
        fprintf(stderr, "MPR121 initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    unsigned char touch_status[2];
    while (running) {
        if (read_touch_status(touch_status) == 0) {
            int touch_count = (touch_status[1] << 8) | touch_status[0];
            if (touch_count > 0) {
                toggle_relay();
            }
        } else {
            fprintf(stderr, "Error reading touch status, retrying...\n");
        }
        gpioDelay(100000); // 100ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off on exit
    gpioTerminate();

    return 0;
}

