#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define PIR_SENSOR_1 17
#define PIR_SENSOR_2 22
#define RELAY_PIN 18

// Define constants
#define RELAY_DURATION_MS 500
#define RATE_LIMIT_MS 2000

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio_pin);
void activate_relay(int gpio_pin, int duration_ms);
void log_event(const char *event_type, int gpio_pin);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor states and last unlock times
typedef struct {
    int sensor1_state;
    int sensor2_state;
    unsigned long last_unlock_time;
} SensorData;

SensorData sensor_data = {0, 0, 0};

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize pigpio and GPIO pins
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("door_events.log", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read sensor values
        int pir1_value = read_sensor(PIR_SENSOR_1);
        int pir2_value = read_sensor(PIR_SENSOR_2);

        // Check for motion detection on sensor 1
        if (pir1_value == 1 && sensor_data.sensor1_state == 0) {
            // Check rate limiting
            if (time(NULL) * 1000 - sensor_data.last_unlock_time > RATE_LIMIT_MS) {
                log_event("Motion Detected", PIR_SENSOR_1);
                activate_relay(RELAY_PIN, RELAY_DURATION_MS);
                sensor_data.last_unlock_time = time(NULL) * 1000;
            } else {
                log_event("Rate Limited", PIR_SENSOR_1);
            }
            sensor_data.sensor1_state = 1;
        } else if (pir1_value == 0 && sensor_data.sensor1_state == 1) {
            sensor_data.sensor1_state = 0;
        }

        // Check for motion detection on sensor 2
        if (pir2_value == 1 && sensor_data.sensor2_state == 0) {
            // Check rate limiting
            if (time(NULL) * 1000 - sensor_data.last_unlock_time > RATE_LIMIT_MS) {
                log_event("Motion Detected", PIR_SENSOR_2);
                activate_relay(RELAY_PIN, RELAY_DURATION_MS);
                sensor_data.last_unlock_time = time(NULL) * 1000;
            } else {
                log_event("Rate Limited", PIR_SENSOR_2);
            }
            sensor_data.sensor2_state = 1;
        } else if (pir2_value == 0 && sensor_data.sensor2_state == 1) {
            sensor_data.sensor2_state = 0;
        }

        // Delay for 50ms
        gpioDelay(50000); // 50ms = 50000 microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PIR_SENSOR_1, PI_INPUT);
    gpioSetPullUpDown(PIR_SENSOR_1, PI_PUD_DOWN);
    gpioSetMode(PIR_SENSOR_2, PI_INPUT);
    gpioSetPullUpDown(PIR_SENSOR_2, PI_PUD_DOWN);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Ensure relay is initially off

    return 0;
}

// Read sensor value
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Activate relay for a specified duration
void activate_relay(int gpio_pin, int duration_ms) {
    gpioWrite(gpio_pin, 1); // Activate relay
    gpioDelay(duration_ms * 1000); // Delay for specified duration
    gpioWrite(gpio_pin, 0); // Deactivate relay
}

// Log event to file
void log_event(const char *event_type, int gpio_pin) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - %s - GPIO: %d\n", timestamp, event_type, gpio_pin);
    fflush(log_file); // Ensure immediate write to file
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Cleanup function
void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off
    gpioTerminate();
}

