#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins for the vibration motors
#define MOTOR1_PIN 17
#define MOTOR2_PIN 27

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// Define minimum and maximum values for duty cycle and duration
#define MIN_DUTY_CYCLE 0
#define MAX_DUTY_CYCLE 255
#define MIN_DURATION 50
#define MAX_DURATION 200

// Define minimum and maximum values for pattern length
#define MIN_PATTERN_LENGTH 5
#define MAX_PATTERN_LENGTH 15

// Global variable to indicate program termination
volatile sig_atomic_t shutdown = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, shutting down...\n");
        shutdown = 1;
    }
}

// Function to generate a random integer within a specified range
int generate_random_int(int min, int max) {
    return min + (rand() % (max - min + 1));
}

// Function to generate a random duty cycle for a motor
int generate_random_duty_cycle() {
    return generate_random_int(MIN_DUTY_CYCLE, MAX_DUTY_CYCLE);
}

// Function to generate a random duration for a step
int generate_random_duration() {
    return generate_random_int(MIN_DURATION, MAX_DURATION);
}

// Function to generate a random pattern of steps
void generate_random_pattern(int *pattern, int pattern_length) {
    for (int i = 0; i < pattern_length; i++) {
        pattern[i * 2] = generate_random_duty_cycle();
        pattern[i * 2 + 1] = generate_random_duration();
    }
}

// Function to play a pattern of steps
void play_pattern(int *pattern, int pattern_length) {
    for (int i = 0; i < pattern_length; i++) {
        gpioPWM(MOTOR1_PIN, pattern[i * 2]);
        gpioPWM(MOTOR2_PIN, pattern[i * 2]);
        gpioDelay(pattern[i * 2 + 1] * 1000); // Convert milliseconds to microseconds
    }
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(MOTOR1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR2_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR1_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR2_PIN, PWM_FREQUENCY);

    // Seed the random number generator
    srand(time(NULL));

    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Haptic feedback generator started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!shutdown) {
        // Generate a random pattern length
        int pattern_length = generate_random_int(MIN_PATTERN_LENGTH, MAX_PATTERN_LENGTH);

        // Allocate memory for the pattern
        int *pattern = (int *)malloc(pattern_length * 2 * sizeof(int));
        if (pattern == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            break; // Exit the loop if memory allocation fails
        }

        // Generate the pattern
        generate_random_pattern(pattern, pattern_length);

        // Play the pattern
        play_pattern(pattern, pattern_length);

        // Free the allocated memory
        free(pattern);

        // Introduce a delay before generating the next pattern
        gpioDelay(generate_random_int(1000, 5000) * 1000); // Delay between 1 and 5 seconds
    }

    // Stop the motors
    gpioPWM(MOTOR1_PIN, 0);
    gpioPWM(MOTOR2_PIN, 0);

    // Terminate the pigpio library
    gpioTerminate();

    printf("Haptic feedback generator stopped.\n");

    return 0;
}

