#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Define constants
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "weight_log.txt"
#define CALIBRATION_READINGS 100
#define TIMEOUT_US 500000 // 0.5 seconds
#define WEIGHT_THRESHOLD 10.0 // kg
#define SCALE_FACTOR_DEFAULT 1.0
#define OFFSET_DEFAULT 0.0

// Global variables
double scale_factor = SCALE_FACTOR_DEFAULT;
double offset = OFFSET_DEFAULT;
FILE *log_file = NULL;

// Function prototypes
int read_hx711();
double convert_to_weight(int raw_value);
int calibrate_hx711();
int load_calibration();
int save_calibration();
void log_weight(double weight);
void control_solenoid(double weight);
void signal_handler(int signal);

// Function to read raw data from HX711
int read_hx711() {
    int data = 0;
    int timeout = 0;

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);

    // Wait for data pin to go low
    while (gpioRead(HX711_DATA_PIN) == 1) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout++;
        if (timeout > TIMEOUT_US) {
            fprintf(stderr, "HX711 timeout!\n");
            return -1; // Indicate timeout error
        }
    }

    // Read 24 bits of data
    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // Clock pulse width
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // Clock pulse width
    }

    // Pulse the clock pin 1 more time to set the gain to 128
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1);

    // Convert to signed 2's complement
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Function to convert raw value to weight
double convert_to_weight(int raw_value) {
    return (raw_value - offset) / scale_factor;
}

// Function to calibrate the HX711
int calibrate_hx711() {
    double sum = 0.0;
    int raw_value;

    printf("Starting calibration. Please ensure no load is applied.\n");
    gpioDelay(2000); // Wait 2 seconds

    for (int i = 0; i < CALIBRATION_READINGS; i++) {
        raw_value = read_hx711();
        if (raw_value == -1) {
            fprintf(stderr, "Calibration failed: HX711 read error.\n");
            return -1;
        }
        sum += raw_value;
        gpioDelay(10); // Small delay between readings
    }

    offset = sum / CALIBRATION_READINGS;
    printf("Calibration complete. Offset: %lf\n", offset);

    if (save_calibration() != 0) {
        fprintf(stderr, "Calibration failed: Failed to save calibration data.\n");
        return -1;
    }

    return 0;
}

// Function to load calibration data from file
int load_calibration() {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (fp == NULL) {
        printf("Calibration file not found. Using default values.\n");
        return -1;
    }

    if (fscanf(fp, "%lf %lf", &scale_factor, &offset) != 2) {
        fprintf(stderr, "Calibration file format error. Using default values.\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    printf("Calibration data loaded: scale_factor = %lf, offset = %lf\n", scale_factor, offset);
    return 0;
}

// Function to save calibration data to file
int save_calibration() {
    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening calibration file for writing!\n");
        return -1;
    }

    fprintf(fp, "%lf %lf", scale_factor, offset);
    fclose(fp);
    printf("Calibration data saved: scale_factor = %lf, offset = %lf\n", scale_factor, offset);
    return 0;
}

// Function to log weight data to file
void log_weight(double weight) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, %.2lf\n", timestamp, weight);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to control the solenoid lock
void control_solenoid(double weight) {
    if (weight > WEIGHT_THRESHOLD) {
        gpioWrite(SOLENOID_PIN, 1); // Lock
        printf("Weight above threshold. Locking solenoid.\n");
    } else {
        gpioWrite(SOLENOID_PIN, 0); // Unlock
        printf("Weight below threshold. Unlocking solenoid.\n");
    }
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d. Shutting down...\n", signal);
    gpioWrite(SOLENOID_PIN, 0); // Unlock solenoid on shutdown
    gpioTerminate(); // Release GPIO resources
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set solenoid pin as output
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Load calibration data
    if (load_calibration() != 0) {
        // If calibration file is not found or invalid, calibrate
        if (calibrate_hx711() != 0) {
            fprintf(stderr, "Calibration failed. Exiting.\n");
            gpioTerminate();
            return 1;
        }
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        int raw_value = read_hx711();
        if (raw_value == -1) {
            fprintf(stderr, "HX711 read error. Skipping.\n");
            gpioDelay(500); // Wait before next iteration
            continue;
        }

        double weight = convert_to_weight(raw_value);
        printf("Weight: %.2lf kg\n", weight);

        log_weight(weight);
        control_solenoid(weight);

        gpioDelay(500); // Wait 500 ms
    }

    return 0; // This line will never be reached due to the infinite loop
}

