#define MOTOR_DUTY_CYCLE 150  // 0-255
#define MOTOR_DURATION 5      // seconds

// Define debounce parameters
#define DEBOUNCE_READINGS 5
#define DEBOUNCE_INTERVAL 50 // milliseconds

// Define rain detection threshold
#define RAIN_DETECTED_THRESHOLD 3

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_rain_sensor();
int debounce_rain_sensor();
void close_window();
void stop_window();
void log_event(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    log_event("Received signal, stopping program...");
    stop_window();
    gpioTerminate();
    closelog();
    exit(0);
}

// Function to read the rain sensor
int read_rain_sensor() {
    return gpioRead(RAIN_SENSOR_PIN);
}

// Function to debounce the rain sensor
int debounce_rain_sensor() {
    int low_count = 0;
    for (int i = 0; i < DEBOUNCE_READINGS; i++) {
        if (read_rain_sensor() == 0) {
            low_count++;
        }
        gpioDelay(DEBOUNCE_INTERVAL * 1000); // Convert ms to us
    }
    return (low_count >= RAIN_DETECTED_THRESHOLD) ? 0 : 1;
}

// Function to close the window
void close_window() {
    log_event("Closing window...");
    gpioWrite(MOTOR_IN1_PIN, 1);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioPWM(MOTOR_PWM_PIN, MOTOR_DUTY_CYCLE);
    gpioDelay(MOTOR_DURATION * 1000000); // Convert seconds to microseconds
    stop_window();
    log_event("Window closed.");
}

// Function to stop the window motor
void stop_window() {
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioPWM(MOTOR_PWM_PIN, 0);
    log_event("Motor stopped.");
}

// Function to log events to syslog
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    char log_message[256];
    snprintf(log_message, sizeof(log_message), "%s: %s", timestamp, message);
    syslog(LOG_INFO, "%s", log_message);
}

int main() {
    // Initialize syslog
    openlog("window_control", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_event("pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_PWM_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_PWM_PIN, MOTOR_FREQUENCY);

    log_event("Program started");

    while (program_running) {
        if (debounce_rain_sensor() == 0) {
            close_window();
            gpioDelay(60000000); // Wait 60 seconds before checking again
        } else {
            gpioDelay(60000000); // Check every 60 seconds
        }
    }

    // Cleanup
    stop_window();
    gpioTerminate();
    closelog();

    return 0;
}

