#include <signal.h>
#include <string.h>

// Define GPIO pins
#define HX711_DT 23
#define HX711_SCK 24
#define SOLENOID_PIN 17

// Define constants
#define WEIGHT_THRESHOLD 100.0 // grams
#define SOLENOID_DURATION 5 // seconds
#define HX711_TIMEOUT 100 // milliseconds

// Global variables
static volatile int running = 1;
FILE *log_file = NULL;

// Function prototypes
int read_hx711();
double convert_to_grams(int raw_value);
void activate_solenoid();
void log_event(const char *event);
void signal_handler(int signal);

// Function to read raw data from HX711
int read_hx711() {
    int data = 0;
    int timeout_counter = 0;

    gpioSetMode(HX711_DT, PI_INPUT);
    gpioSetMode(HX711_SCK, PI_OUTPUT);

    // Wait for DT to go low
    while (gpioRead(HX711_DT) == 1) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout_counter++;
        if (timeout_counter > HX711_TIMEOUT) {
            fprintf(stderr, "Error: HX711 timeout waiting for DT low.\n");
            return -1; // Indicate timeout error
        }
    }

    // Read 24 bits of data
    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK, 1);
        gpioDelay(1); // Small delay
        data = data << 1;
        if (gpioRead(HX711_DT) == 1) {
            data++;
        }
        gpioWrite(HX711_SCK, 0);
        gpioDelay(1); // Small delay
    }

    // Pulse SCK 25th time to set gain to 128
    gpioWrite(HX711_SCK, 1);
    gpioDelay(1); // Small delay
    gpioWrite(HX711_SCK, 0);
    gpioDelay(1); // Small delay

    // Convert to signed 2's complement
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Function to convert raw value to grams (replace with your calibration)
double convert_to_grams(int raw_value) {
    // This is a placeholder.  You MUST calibrate your load cell and HX711.
    // The calibration involves determining the relationship between the raw
    // ADC value and the actual weight in grams.  This relationship is
    // typically linear, but can be non-linear depending on the load cell.
    // You can use a simple linear equation:
    // grams = (raw_value - offset) * scale_factor
    // Where 'offset' is the raw value at 0 grams, and 'scale_factor' is
    // the number of raw units per gram.
    // For example, if your load cell gives 1000 raw units at 100 grams,
    // and 0 raw units at 0 grams, then:
    // offset = 0
    // scale_factor = 100.0 / 1000.0 = 0.1
    // grams = (raw_value - 0) * 0.1 = raw_value * 0.1
    // In this example, the conversion function would be:
    // return (double)raw_value * 0.1;
    // You MUST replace this with your actual calibration.
    return (double)raw_value * 0.01; // Example conversion
}

// Function to activate the solenoid lock
void activate_solenoid() {
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);
    gpioWrite(SOLENOID_PIN, 1); // Activate solenoid
    gpioDelay(SOLENOID_DURATION * 1000); // Delay for 5 seconds
    gpioWrite(SOLENOID_PIN, 0); // Deactivate solenoid
}

// Function to log events to a file
void log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, event);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("stock_events.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Stock monitoring system started. Press Ctrl+C to exit.\n");

    while (running) {
        int raw_value = read_hx711();
        if (raw_value == -1) {
            fprintf(stderr, "Error reading HX711, skipping.\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        double weight = convert_to_grams(raw_value);
        printf("Weight: %.2f grams\n", weight);

        if (weight < WEIGHT_THRESHOLD) {
            printf("Weight below threshold, activating solenoid.\n");
            activate_solenoid();
            log_event("Solenoid activated due to low stock.");
        }

        gpioDelay(1000); // Check every 1 second
    }

    // Clean up
    fclose(log_file);
    gpioTerminate();

    return 0;
}

