#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Calibration file
#define CALIBRATION_FILE "calibration.txt"

// Log file
#define LOG_FILE "security.log"

// Timeout duration (milliseconds)
#define TIMEOUT_DURATION 100

// Global variables
static volatile int running = 1;
static double calibration_factor = 1.0; // Default calibration factor
static FILE *log_file = NULL;

// Function prototypes
int read_hx711();
double calibrate_load_cell();
double convert_to_kg(int raw_value);
void control_solenoid(int state);
void log_event(double weight);
void signal_handler(int signal);
int load_calibration();
int save_calibration(double factor);

// Function to read raw data from HX711
int read_hx711() {
    int data = 0;
    int timeout = 0;

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);

    // Wait for data line to go low
    while (gpioRead(HX711_DATA_PIN) == 1 && timeout < TIMEOUT_DURATION) {
        gpioDelay(1); // Wait 1 ms
        timeout++;
    }

    if (timeout >= TIMEOUT_DURATION) {
        fprintf(stderr, "Error: HX711 timeout waiting for data line to go low.\n");
        return -1; // Indicate timeout error
    }

    // Read 24 bits of data
    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // Clock high delay
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // Clock low delay
    }

    // Pulse the clock pin 1 more time to set the gain to 128
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1);

    // Convert to signed 24-bit integer
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Function to calibrate the load cell
double calibrate_load_cell() {
    double known_weight;
    int raw_value;

    printf("Enter the known weight in kilograms: ");
    if (scanf("%lf", &known_weight) != 1) {
        fprintf(stderr, "Error: Invalid input for known weight.\n");
        return -1.0;
    }

    printf("Placing the known weight on the load cell...\n");
    gpioDelay(2000); // Allow time for weight to settle

    raw_value = read_hx711();
    if (raw_value == -1) {
        fprintf(stderr, "Error: Failed to read raw value during calibration.\n");
        return -1.0;
    }

    return (double)raw_value / known_weight;
}

// Function to convert raw value to kilograms
double convert_to_kg(int raw_value) {
    return (double)raw_value / calibration_factor;
}

// Function to control the solenoid
void control_solenoid(int state) {
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);
    gpioWrite(SOLENOID_PIN, state);
}

// Function to log events to a file
void log_event(double weight) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Weight: %.2f kg\n", timestamp, weight);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, unlocking solenoid and exiting...\n", signal);
    running = 0;
    control_solenoid(0); // Unlock the solenoid
    gpioTerminate(); // Terminate pigpio
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

// Function to load calibration factor from file
int load_calibration() {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Warning: Could not open calibration file. Using default calibration factor.\n");
        return -1; // Indicate failure to open file
    }

    if (fscanf(fp, "%lf", &calibration_factor) != 1) {
        fprintf(stderr, "Warning: Could not read calibration factor from file. Using default calibration factor.\n");
        fclose(fp);
        return -1; // Indicate failure to read calibration factor
    }

    fclose(fp);
    printf("Calibration factor loaded: %.6f\n", calibration_factor);
    return 0; // Indicate success
}

// Function to save calibration factor to file
int save_calibration(double factor) {
    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open calibration file for writing.\n");
        return -1; // Indicate failure
    }

    if (fprintf(fp, "%.6f", factor) < 0) {
        fprintf(stderr, "Error: Could not write calibration factor to file.\n");
        fclose(fp);
        return -1; // Indicate failure
    }

    fclose(fp);
    printf("Calibration factor saved: %.6f\n", factor);
    return 0; // Indicate success
}

int main() {
    int raw_value;
    double weight;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Load calibration factor from file
    if (load_calibration() != 0) {
        // If loading fails, calibrate the load cell
        printf("Calibration file not found or invalid. Starting calibration...\n");
        calibration_factor = calibrate_load_cell();
        if (calibration_factor < 0) {
            fprintf(stderr, "Error: Calibration failed.\n");
            gpioTerminate();
            return 1;
        }
        // Save the calibration factor to file
        if (save_calibration(calibration_factor) != 0) {
            fprintf(stderr, "Warning: Could not save calibration factor.\n");
        }
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file.\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Weight monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        raw_value = read_hx711();
        if (raw_value == -1) {
            fprintf(stderr, "Error: Failed to read raw value.\n");
            gpioDelay(1000); // Wait before retrying
            continue;
        }

        weight = convert_to_kg(raw_value);
        printf("Weight: %.2f kg\n", weight);

        if (weight > 5.0) {
            printf("Weight exceeds 5.0 kg. Logging event and locking door.\n");
            log_event(weight);
            control_solenoid(1); // Lock the door
            gpioDelay(5000);      // Keep locked for 5 seconds
            control_solenoid(0); // Unlock the door
        }

        gpioDelay(100); // Delay between readings
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_solenoid(0); // Unlock the solenoid
    gpioTerminate();     // Terminate pigpio
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

