}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, unlocking solenoid and exiting...\n", signal);
    running = 0;
    control_solenoid(0); // Unlock the solenoid
    gpioTerminate(); // Terminate pigpio
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

// Function to load calibration factor from file
int load_calibration() {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Warning: Could not open calibration file. Using default calibration factor.\n");
        return -1; // Indicate failure to open file
    }

    if (fscanf(fp, "%lf", &calibration_factor) != 1) {
        fprintf(stderr, "Warning: Could not read calibration factor from file. Using default calibration factor.\n");
        fclose(fp);
        return -1; // Indicate failure to read calibration factor
    }

    fclose(fp);
    printf("Calibration factor loaded: %.6f\n", calibration_factor);
    return 0; // Indicate success
}

// Function to save calibration factor to file
int save_calibration(double factor) {
    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open calibration file for writing.\n");
        return -1; // Indicate failure
    }

    if (fprintf(fp, "%.6f", factor) < 0) {
        fprintf(stderr, "Error: Could not write calibration factor to file.\n");
        fclose(fp);
        return -1; // Indicate failure
    }

    fclose(fp);
    printf("Calibration factor saved: %.6f\n", factor);
    return 0; // Indicate success
}

int main() {
    int raw_value;
    double weight;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Load calibration factor from file
    if (load_calibration() != 0) {
        // If loading fails, calibrate the load cell
        printf("Calibration file not found or invalid. Starting calibration...\n");
        calibration_factor = calibrate_load_cell();
        if (calibration_factor < 0) {
            fprintf(stderr, "Error: Calibration failed.\n");
            gpioTerminate();
            return 1;
        }
        // Save the calibration factor to file
        if (save_calibration(calibration_factor) != 0) {
            fprintf(stderr, "Warning: Could not save calibration factor.\n");
        }
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file.\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Weight monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        raw_value = read_hx711();
        if (raw_value == -1) {
            fprintf(stderr, "Error: Failed to read raw value.\n");
            gpioDelay(1000); // Wait before retrying
            continue;
        }

        weight = convert_to_kg(raw_value);
        printf("Weight: %.2f kg\n", weight);

        if (weight > 5.0) {
            printf("Weight exceeds 5.0 kg. Logging event and locking door.\n");
            log_event(weight);
            control_solenoid(1); // Lock the door
            gpioDelay(5000);      // Keep locked for 5 seconds
            control_solenoid(0); // Unlock the door
        }

        gpioDelay(100); // Delay between readings
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_solenoid(0); // Unlock the solenoid
    gpioTerminate();     // Terminate pigpio
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

