// Define GPIO pins
#define SENSOR_PIN 16
#define RELAY_PIN 20

// Define GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip = NULL;
struct gpiod_line *sensor_line = NULL;
struct gpiod_line *relay_line = NULL;

// Function prototypes
int read_sensor(struct gpiod_line *line);
int control_relay(struct gpiod_line *line, int state);
int log_event(const char *event);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (sensor_line) {
        gpiod_line_release(sensor_line);
    }
    if (relay_line) {
        gpiod_line_release(relay_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to read the sensor value
int read_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor value: %s\n", strerror(errno));
        return -1; // Indicate error
    }
    return value;
}

// Function to control the relay
int control_relay(struct gpiod_line *line, int state) {
    int ret = gpiod_line_set_value(line, state);
    if (ret < 0) {
        fprintf(stderr, "Error setting relay state: %s\n", strerror(errno));
        return -1; // Indicate error
    }
    return 0;
}

// Function to log events to a file
int log_event(const char *event) {
    FILE *fp = fopen("relay_events.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1; // Indicate error
    }

    time_t t = time(NULL);
    struct tm *tm = gmtime(&t);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    fprintf(fp, "%s: %s\n", timestamp, event);
    fclose(fp);
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get GPIO lines
    sensor_line = gpiod_chip_get_line(chip, SENSOR_PIN);
    if (!sensor_line) {
        fprintf(stderr, "Error getting sensor line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    relay_line = gpiod_chip_get_line(chip, RELAY_PIN);
    if (!relay_line) {
        fprintf(stderr, "Error getting relay line: %s\n", strerror(errno));
        gpiod_line_release(sensor_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for input and output
    if (gpiod_line_request_bulk_inputs(sensor_line, "obstacle_sensor") < 0) {
        fprintf(stderr, "Error requesting sensor line as input: %s\n", strerror(errno));
        gpiod_line_release(sensor_line);
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_bulk_outputs(relay_line, "relay_control", 0) < 0) {
        fprintf(stderr, "Error requesting relay line as output: %s\n", strerror(errno));
        gpiod_line_release(sensor_line);
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    int relay_state = 0; // 0 = OFF, 1 = ON
    int sensor_value;
    while (1) {
        sensor_value = read_sensor(sensor_line);
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor, exiting...\n");
            break;
        }

        if (sensor_value == 0) { // Obstacle detected (active low)
            relay_state = !relay_state; // Toggle relay state
            if (control_relay(relay_line, relay_state) == 0) {
                const char *event = (relay_state == 1) ? "Relay ON" : "Relay OFF";
                if (log_event(event) != 0) {
                    fprintf(stderr, "Error logging event, but continuing...\n");
                }
            } else {
                fprintf(stderr, "Error controlling relay, exiting...\n");
                break;
            }
        }

        // Small delay to avoid busy-waiting
        struct timespec delay;
        delay.tv_sec = 0;
        delay.tv_nsec = 100 * 1000 * 1000; // 100 milliseconds
        nanosleep(&delay, NULL);
    }

    // Cleanup (in case the loop breaks due to an error)
    gpiod_line_release(sensor_line);
    gpiod_line_release(relay_line);
    gpiod_chip_close(chip);

    return 0;
}

