    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get line for PIR sensor
    pir_line = gpiod_chip_get_line(chip, PIR_SENSOR_PIN);
    if (!pir_line) {
        perror("Error getting PIR sensor line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Request PIR sensor line as input
    if (gpiod_line_request_input(pir_line, "motion_detector") < 0) {
        perror("Error requesting PIR sensor line as input");
        gpiod_chip_close(chip);
        gpiod_line_release(pir_line);
        return -1;
    }

    // Get line for buzzer
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        perror("Error getting buzzer line");
        gpiod_chip_close(chip);
        gpiod_line_release(pir_line);
        return -1;
    }

    // Request buzzer line as output
