        return 1;
    }

    // Open log file
    log_file = fopen("motion_log.txt", "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int pir_value = read_pir_sensor();
        if (pir_value < 0) {
            fprintf(stderr, "Error reading PIR sensor. Continuing.\n");
            sleep(1); // Avoid spamming errors
            continue;
        }

        if (pir_value == 1) {
            printf("Motion detected!\n");
            activate_buzzer();
            log_motion_event();
            usleep(2000000); // 2 seconds
            deactivate_buzzer();
        }

        usleep(100000); // Check every 0.1 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

