    if (fp == NULL) {
        log_message("Error opening config file, using default duration (60 seconds).");
        *duration = 60;
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        log_message("Error reading config file, using default duration (60 seconds).");
        fclose(fp);
        *duration = 60;
        return -1;
    }

    if (strncmp(line, "duration=", 9) != 0) {
        log_message("Malformed config file, using default duration (60 seconds).");
        fclose(fp);
        *duration = 60;
        return -1;
    }

    char *endptr;
    *duration = strtol(line + 9, &endptr, 10);

    if (*endptr != '\n' && *endptr != '\0') {
