#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define LEFT_SENSOR 4
#define MIDDLE_SENSOR 17
#define RIGHT_SENSOR 27

#define LEFT_PWM_PIN 22
#define LEFT_DIR_PIN 23
#define RIGHT_PWM_PIN 24
#define RIGHT_DIR_PIN 25

// Define motor speeds
#define STRAIGHT_SPEED 150
#define TURN_SPEED 75

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Global variables
FILE *log_file;
int running = 1;

// Function prototypes
int read_sensors(int left_pin, int middle_pin, int right_pin);
void control_motors(int left_pin, int left_dir_pin, int right_pin, int right_dir_pin, int left_speed, int right_speed);
void log_data(FILE *log_file, int left_sensor, int middle_sensor, int right_sensor, int left_speed, int right_speed);
void signal_handler(int signal);

// Function to read sensor values
int read_sensors(int left_pin, int middle_pin, int right_pin) {
    int left_value = gpioRead(left_pin);
    int middle_value = gpioRead(middle_pin);
    int right_value = gpioRead(right_pin);

    return (left_value << 2) | (middle_value << 1) | right_value;
}

// Function to control motor speeds and directions
void control_motors(int left_pin, int left_dir_pin, int right_pin, int right_dir_pin, int left_speed, int right_speed) {
    gpioPWM(left_pin, left_speed);
    gpioWrite(left_dir_pin, 1); // Forward

    gpioPWM(right_pin, right_speed);
    gpioWrite(right_dir_pin, 1); // Forward
}

// Function to log data to a file
void log_data(FILE *log_file, int left_sensor, int middle_sensor, int right_sensor, int left_speed, int right_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d,%d,%d\n", timestamp, left_sensor, middle_sensor, right_sensor, left_speed, right_speed);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, stopping motors and exiting...\n", signal);
    running = 0;
    control_motors(LEFT_PWM_PIN, LEFT_DIR_PIN, RIGHT_PWM_PIN, RIGHT_DIR_PIN, 0, 0); // Stop motors
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LEFT_SENSOR, PI_INPUT);
    gpioSetMode(MIDDLE_SENSOR, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR, PI_INPUT);

    gpioSetMode(LEFT_PWM_PIN, PI_OUTPUT);
    gpioSetMode(LEFT_DIR_PIN, PI_OUTPUT);
    gpioSetMode(RIGHT_PWM_PIN, PI_OUTPUT);
    gpioSetMode(RIGHT_DIR_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(LEFT_PWM_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RIGHT_PWM_PIN, PWM_FREQUENCY);

    // Open log file
    log_file = fopen("trace_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        int sensor_values = read_sensors(LEFT_SENSOR, MIDDLE_SENSOR, RIGHT_SENSOR);
        int left_sensor = sensor_values & 1;
        int middle_sensor = (sensor_values >> 1) & 1;
        int right_sensor = (sensor_values >> 2) & 1;

        int left_speed = 0;
        int right_speed = 0;

        if (middle_sensor == 0) {
            left_speed = STRAIGHT_SPEED;
            right_speed = STRAIGHT_SPEED;
        } else if (left_sensor == 0) {
            left_speed = TURN_SPEED;
            right_speed = STRAIGHT_SPEED;
        } else if (right_sensor == 0) {
            left_speed = STRAIGHT_SPEED;
            right_speed = TURN_SPEED;
        }

        control_motors(LEFT_PWM_PIN, LEFT_DIR_PIN, RIGHT_PWM_PIN, RIGHT_DIR_PIN, left_speed, right_speed);
        log_data(log_file, left_sensor, middle_sensor, right_sensor, left_speed, right_speed);

        gpioDelay(10000); // 10 ms delay
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_motors(LEFT_PWM_PIN, LEFT_DIR_PIN, RIGHT_PWM_PIN, RIGHT_DIR_PIN, 0, 0); // Stop motors
    fclose(log_file);
    gpioTerminate(); // Terminate pigpio

    return 0;
}

