#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define BH1750_ADDR 0x23
#define GROW_LAMP_GPIO 23
#define LUX_THRESHOLD 150.0
#define I2C_BUS 1
#define I2C_FLAGS 0
#define I2C_SPEED 100000 // 100kHz

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c();
float read_bh1750();
void control_relay(int state);
void log_data(float lux, int relay_state);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int bh1750_address;
    int grow_lamp_pin;
    float lux_threshold;
} config_t;

config_t config = {BH1750_ADDR, GROW_LAMP_GPIO, LUX_THRESHOLD};

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("grow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (program_running) {
        float lux = read_bh1750();

        if (lux >= 0) {
            // Control relay based on lux reading
            int relay_state = (lux < config.lux_threshold) ? 1 : 0;
            control_relay(relay_state);

            // Log data
            log_data(lux, relay_state);
        } else {
            fprintf(stderr, "Failed to read lux value\n");
        }

        gpioDelay(1000); // Check every 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, config.bh1750_address, I2C_FLAGS);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }

    // Set continuous high-resolution mode
    if (i2cWriteByteData(i2c_handle, 0x00, 0x10) < 0) {
        fprintf(stderr, "Failed to set BH1750 mode\n");
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Read illuminance from BH1750
