// Define GPIO pins
#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22

// Define servo pulse width limits
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500

// Define lock and unlock pulse widths
#define LOCK_PULSE_WIDTH 1000
#define UNLOCK_PULSE_WIDTH 2000

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 100

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
void set_servo_pulse_width(int pulse_width);
int read_lock_button();
int read_unlock_button();
void lock_door();
void unlock_door();
void cleanup_gpio();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0;
    }
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set servo pin as output
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set button pins as input with pull-up resistors
    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP);

    return 0; // Indicate success
}

// Function to set the servo pulse width
void set_servo_pulse_width(int pulse_width) {
    // Constrain pulse width to safe range
    if (pulse_width < SERVO_MIN_PULSE_WIDTH) {
        pulse_width = SERVO_MIN_PULSE_WIDTH;
    } else if (pulse_width > SERVO_MAX_PULSE_WIDTH) {
        pulse_width = SERVO_MAX_PULSE_WIDTH;
    }

    gpioServo(SERVO_PIN, pulse_width);
}

// Function to read the lock button state
int read_lock_button() {
    return !gpioRead(LOCK_BUTTON_PIN); // Active low
}

// Function to read the unlock button state
int read_unlock_button() {
    return !gpioRead(UNLOCK_BUTTON_PIN); // Active low
}

// Function to lock the door
void lock_door() {
    printf("Locking door...\n");
    set_servo_pulse_width(LOCK_PULSE_WIDTH);
    gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce
}

// Function to unlock the door
void unlock_door() {
    printf("Unlocking door...\n");
    set_servo_pulse_width(UNLOCK_PULSE_WIDTH);
    gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce
}

// Function to cleanup GPIO pins
void cleanup_gpio() {
    printf("Cleaning up GPIO...\n");
    gpioServo(SERVO_PIN, 0); // Stop servo
    gpioTerminate();
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Door lock control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        if (read_lock_button()) {
            lock_door();
        } else if (read_unlock_button()) {
            unlock_door();
        }

        gpioDelay(10000); // Check buttons every 10ms
    }

    // Cleanup GPIO before exiting
    cleanup_gpio();

    return 0;
}

