#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for the vibration motors
#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27

// Define pulse durations (in milliseconds)
#define MOTOR1_PULSE_DURATION 200
#define MOTOR2_PULSE_DURATION 300

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating program...\n", signal);
    program_running = 0;
}

// Function to set the GPIO pin value
int set_gpio_value(int gpio, int value) {
    int result = gpioWrite(gpio, value);
    if (result != 0) {
        fprintf(stderr, "Error writing to GPIO %d: %d\n", gpio, result);
        return -1;
    }
    return 0;
}

// Function to pulse the vibration motor
int pulse_motor(int gpio, int duration_ms) {
    if (set_gpio_value(gpio, 1) != 0) {
        return -1;
    }
    gpioDelay(duration_ms * 1000); // Convert milliseconds to microseconds
    if (set_gpio_value(gpio, 0) != 0) {
        return -1;
    }
    return 0;
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal(SIGINT) failed");
        return 1;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("signal(SIGTERM) failed");
        return 1;
    }

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(MOTOR1_GPIO, PI_OUTPUT);
    gpioSetMode(MOTOR2_GPIO, PI_OUTPUT);

    // Main loop
    while (program_running) {
        // Pulse motor 1
        if (pulse_motor(MOTOR1_GPIO, MOTOR1_PULSE_DURATION) != 0) {
            fprintf(stderr, "Error pulsing motor 1\n");
            break;
        }

        // Pulse motor 2
        if (pulse_motor(MOTOR2_GPIO, MOTOR2_PULSE_DURATION) != 0) {
            fprintf(stderr, "Error pulsing motor 2\n");
            break;
        }
    }

    // Stop motors and terminate pigpio
    set_gpio_value(MOTOR1_GPIO, 0);
    set_gpio_value(MOTOR2_GPIO, 0);
    gpioTerminate();

    fprintf(stderr, "Program terminated gracefully.\n");
    return 0;
}

