#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>
#include <zmq.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 27

// Define ZeroMQ address
#define ZMQ_ADDRESS "tcp://*:5555"

// Define ZeroMQ topic
#define ZMQ_TOPIC "SOUND_ALERTS"

// Global variables for signal handling
volatile sig_atomic_t terminate = 0;
void *zmq_context = NULL;
void *zmq_socket = NULL;

// Function prototypes
int initialize_gpio();
int initialize_zmq();
void sound_sensor_mode();
void alarm_node_mode();
void publish_alert(const char *message);
void subscribe_alerts();
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize GPIO using pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    gpioSetMode(ALARM_LED_PIN, PI_OUTPUT);
    gpioWrite(ALARM_LED_PIN, 0); // Ensure LED is off initially

    return 0;
}

// Initialize ZeroMQ
int initialize_zmq() {
    zmq_context = zmq_ctx_new();
    if (!zmq_context) {
        perror("zmq_ctx_new failed");
        return -1;
    }

    zmq_socket = zmq_socket(zmq_context, ZMQ_PUB);
    if (!zmq_socket) {
        perror("zmq_socket failed");
        zmq_ctx_destroy(zmq_context);
        return -1;
    }

    int rc = zmq_bind(zmq_socket, ZMQ_ADDRESS);
    if (rc != 0) {
        perror("zmq_bind failed");
        zmq_close(zmq_socket);
        zmq_ctx_destroy(zmq_context);
        return -1;
    }

    return 0;
}

// Sound sensor mode
void sound_sensor_mode() {
    printf("Sound sensor mode started. Monitoring GPIO%d...\n", SOUND_SENSOR_PIN);
    while (!terminate) {
        int sound_detected = gpioRead(SOUND_SENSOR_PIN) == 0; // Active low

        if (sound_detected) {
            printf("Sound detected!\n");
            publish_alert("SOUND_ALERT");
            gpioDelay(1000); // Debounce delay
        }
        gpioDelay(10); // Poll every 10ms
    }
}

// Alarm node mode
void alarm_node_mode() {
    printf("Alarm node mode started. Subscribing to %s...\n", ZMQ_ADDRESS);
    subscribe_alerts();
}

