        pulse_length = current_tick - last_tick;
        last_tick = current_tick;

        pthread_mutex_lock(&pulse_mutex);
        if (pulse_count < PULSE_BUFFER_SIZE) {
            pulse_buffer[pulse_count++] = pulse_length;
        } else {
            syslog(LOG_ERR, "Pulse buffer overflow!");
        }
        pthread_mutex_unlock(&pulse_mutex);
    }
}

// NEC Decoding Function
int decode_nec(unsigned int *pulse_buffer, int pulse_count, unsigned int *address, unsigned int *command) {
    int i;
    unsigned int address_data = 0;
    unsigned int command_data = 0;

    // Check for valid header
    if (pulse_count < 34) {
        syslog(LOG_ERR, "Not enough pulses for NEC frame.");
        return -1;
    }

    if (pulse_buffer[0] < NEC_HEADER_MARK * 0.8 || pulse_buffer[0] > NEC_HEADER_MARK * 1.2) {
        syslog(LOG_ERR, "Invalid header mark: %u", pulse_buffer[0]);
        return -1;
    }

    if (pulse_buffer[1] < NEC_HEADER_SPACE * 0.8 || pulse_buffer[1] > NEC_HEADER_SPACE * 1.2) {
        syslog(LOG_ERR, "Invalid header space: %u", pulse_buffer[1]);
        return -1;
    }

    // Decode address and command
    for (i = 2; i < 34; i += 2) {
        if (pulse_buffer[i] < NEC_BIT_MARK * 0.8 || pulse_buffer[i] > NEC_BIT_MARK * 1.2) {
            syslog(LOG_ERR, "Invalid bit mark at index %d: %u", i, pulse_buffer[i]);
            return -1;
        }

        if (pulse_buffer[i + 1] > NEC_ONE_SPACE * 0.8 && pulse_buffer[i + 1] < NEC_ONE_SPACE * 1.2) {
            if (i < 18) {
                address_data = (address_data << 1) | 1;
            } else {
                command_data = (command_data << 1) | 1;
            }
        } else if (pulse_buffer[i + 1] > NEC_ZERO_SPACE * 0.8 && pulse_buffer[i + 1] < NEC_ZERO_SPACE * 1.2) {
            if (i < 18) {
                address_data = (address_data << 1) | 0;
            } else {
                command_data = (command_data << 1) | 0;
            }
        } else {
            syslog(LOG_ERR, "Invalid space at index %d: %u", i + 1, pulse_buffer[i + 1]);
            return -1;
        }
    }

    // Validate checksum
    unsigned int address_checksum = (address_data >> 4) ^ (address_data & 0x0F);
    if (address_checksum != (address_data & 0x0F)) {
        syslog(LOG_ERR, "Address checksum error: %u != %u", address_checksum, address_data & 0x0F);
        return -1;
    }

    unsigned int command_checksum = (*command >> 4) ^ (*command & 0x0F);
    if (command_checksum != (*command & 0x0F)) {
        syslog(LOG_ERR, "Command checksum error: %u != %u", command_checksum, *command & 0x0F);
        return -1;
    }

    *address = address_data >> 4; // Get upper 4 bits
    *command = command_data >> 4;   // Get upper 4 bits

    return 0;
}

// MQTT Publishing Function
void publish_mqtt(unsigned int address, unsigned int command) {
    char payload[100];
    snprintf(payload, sizeof(payload), "{\"address\":%u,\"command\":%u}", address, command);

    int ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT publish error: %s", mosquitto_strerror(ret));
    }
}

// Signal Handler Function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Received signal %d, shutting down...", signal);
    running = 0;
}

// MQTT Initialization Function
int init_mqtt(void) {
    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create MQTT client.");
        return -1;
    }

    int ret = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(ret));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return -1;
    }

    mosquitto_loop_start(mosq);
    return 0;
}

// MQTT Cleanup Function
void cleanup_mqtt(void) {
    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
}

int main(void) {
    // Initialize syslog
    openlog("ir_decoder", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Initialize MQTT
    if (init_mqtt() != 0) {
        gpioTerminate();
        closelog();
        return 1;
    }

    // Set GPIO mode and register callback
    gpioSetMode(IR_GPIO, PI_INPUT);
    gpioSetAlertFuncEx(IR_GPIO, ir_callback, NULL);

    syslog(LOG_INFO, "IR decoder started");

    unsigned int address, command;
    struct timespec last_decode_time = {0, 0};

    while (running) {
        pthread_mutex_lock(&pulse_mutex);
        if (pulse_count > 0) {
            if (decode_nec(pulse_buffer, pulse_count, &address, &command) == 0) {
                // Debounce
                struct timespec current_time;
                clock_gettime(CLOCK_MONOTONIC, &current_time);
                long time_diff_ms = (current_time.tv_sec - last_decode_time.tv_sec) * 1000 + (current_time.tv_nsec - last_decode_time.tv_nsec) / 1000000;

                if (time_diff_ms > DEBOUNCE_MS) {
                    syslog(LOG_INFO, "Decoded NEC: Address=0x%02X, Command=0x%02X", address, command);
                    publish_mqtt(address, command);
                    last_decode_time = current_time;
                }
            }
            pulse_count = 0;
        }
        pthread_mutex_unlock(&pulse_mutex);
        gpioDelay(1000); // Check every 1 ms
    }

    // Cleanup
    gpioSetAlertFuncEx(IR_GPIO, NULL, NULL); // Disable callback
    cleanup_mqtt();
    gpioTerminate();
    closelog();
    pthread_mutex_destroy(&pulse_mutex);

    return 0;
}

