#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>
#include <math.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005
#define BH1750_ADDR_BASE 0x23
#define BH1750_ADDR_OFFSET 1
#define BH1750_CMD 0x20
#define BH1750_DATA_LEN 2
#define LUX_SCALE 1.2
#define SLEEP_SEC 1

// Global flag for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler
void signal_handler(int sig) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully.\n", sig);
}

// Function to read lux value from a single BH1750 sensor
float read_bh1750(int i2c_fd, int sensor_id) {
    unsigned char addr = BH1750_ADDR_BASE + BH1750_ADDR_OFFSET * (sensor_id - 1);
    unsigned char cmd = BH1750_CMD;
    unsigned char data[BH1750_DATA_LEN];
    int retries = 3;

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02x: %s\n", addr, strerror(errno));
        return NAN;
    }

    // Write command to start measurement
    while (retries > 0) {
        if (write(i2c_fd, &cmd, 1) == 1) {
            break;
        } else {
            fprintf(stderr, "Error writing to I2C device 0x%02x (sensor %d): %s, retries left: %d\n", addr, sensor_id, strerror(errno), retries);
            retries--;
            usleep(10000); // 10ms delay
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to write to I2C device 0x%02x after multiple retries (sensor %d).\n", addr, sensor_id);
        return NAN;
    }

    // Wait for measurement (at least 180ms)
    usleep(180000);

    // Read data from sensor
    retries = 3;
    while (retries > 0) {
        if (read(i2c_fd, data, BH1750_DATA_LEN) == BH1750_DATA_LEN) {
            break;
        } else {
            fprintf(stderr, "Error reading from I2C device 0x%02x (sensor %d): %s, retries left: %d\n", addr, sensor_id, strerror(errno), retries);
            retries--;
            usleep(10000); // 10ms delay
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read from I2C device 0x%02x after multiple retries (sensor %d).\n", addr, sensor_id);
        return NAN;
    }

    // Convert data to lux
    unsigned int raw_value = (data[0] << 8) | data[1];
    float lux = (float)raw_value / LUX_SCALE;

    return lux;
}

// Function to format sensor data into a string
char* format_data(float lux1, float lux2, float lux3, float lux4) {
    char* data_string = (char*)malloc(256 * sizeof(char)); // Allocate memory
    if (data_string == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }
    snprintf(data_string, 256, "1,%.1f;2,%.1f;3,%.1f;4,%.1f", lux1, lux2, lux3, lux4);
    return data_string;
}

// Function to send data via UDP multicast
int send_udp_multicast(const char* data) {
    int sockfd;
    struct sockaddr_in addr;
    int ttl = 1; // Time-to-live for multicast packets

    // Create socket
    if ((sockfd = socket(AF_INET, SOCK_DGRAM, 0)) < 0) {
        fprintf(stderr, "Socket creation failed: %s\n", strerror(errno));
        return -1;
    }

    // Set multicast TTL
    if (setsockopt(sockfd, IPPROTO_IP, IP_MULTICAST_TTL, (void *)&ttl, sizeof(ttl)) < 0) {
        fprintf(stderr, "Setting TTL failed: %s\n", strerror(errno));
        close(sockfd);
        return -1;
    }

    // Configure destination address
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    // Send data
    if (sendto(sockfd, data, strlen(data), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "Sending data failed: %s\n", strerror(errno));
        close(sockfd);
        return -1;
    }

    // Close socket
    close(sockfd);
    return 0;
}

int main() {
    int i2c_fd;
    float lux1, lux2, lux3, lux4;
    char* data_string;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read sensor values
        lux1 = read_bh1750(i2c_fd, 1);
        lux2 = read_bh1750(i2c_fd, 2);
        lux3 = read_bh1750(i2c_fd, 3);
        lux4 = read_bh1750(i2c_fd, 4);

        // Format data
        data_string = format_data(lux1, lux2, lux3, lux4);
        if (data_string != NULL) {
            // Send data
            if (send_udp_multicast(data_string) != 0) {
                fprintf(stderr, "Failed to send UDP multicast.\n");
            }
            free(data_string); // Free allocated memory
        } else {
            fprintf(stderr, "Failed to format data.\n");
        }

        // Sleep for 1 second
        sleep(SLEEP_SEC);
    }

    // Close I2C bus
    close(i2c_fd);

    return 0;
}

