#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x28
#define FLOW_SCALE_FACTOR 0.1
#define FLOW_OFFSET 3277.0
#define LOG_FILE "airflow_log.txt"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_read_bytes(int fd, uint8_t *data, int len);
int i2c_write_bytes(int fd, uint8_t *data, int len);
int read_airflow_data(int fd, uint16_t *raw_flow);
float convert_to_slpm(uint16_t raw_flow);
int log_data(FILE *fp, float flow_rate);
void signal_handler(int signum);

// I2C read function with retry mechanism
int i2c_read_bytes(int fd, uint8_t *data, int len) {
    int retries = 0;
    int bytes_read = 0;

    while (retries < MAX_RETRIES) {
        bytes_read = read(fd, data, len);
        if (bytes_read == len) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d/%d): %s\n", retries + 1, MAX_RETRIES, strerror(errno));
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "I2C read failed after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// I2C write function with retry mechanism
int i2c_write_bytes(int fd, uint8_t *data, int len) {
    int retries = 0;
    int bytes_written = 0;

    while (retries < MAX_RETRIES) {
        bytes_written = write(fd, data, len);
        if (bytes_written == len) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C write failed (attempt %d/%d): %s\n", retries + 1, MAX_RETRIES, strerror(errno));
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    fprintf(stderr, "I2C write failed after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to read airflow data from the sensor
int read_airflow_data(int fd, uint16_t *raw_flow) {
    uint8_t data[2];

    // Start condition (zero-length write)
    if (i2c_write_bytes(fd, NULL, 0) != 0) {
        fprintf(stderr, "Failed to issue start condition.\n");
        return -1;
    }

    // Read 2 bytes of data
    if (i2c_read_bytes(fd, data, 2) != 0) {
        fprintf(stderr, "Failed to read airflow data.\n");
        return -1;
    }

    // Combine the bytes into a 14-bit value
    *raw_flow = (data[0] << 6) | (data[1] >> 2);

    // Mask with 0x3FFF to ensure only 14 bits are used
    *raw_flow &= 0x3FFF;

    return 0;
}

// Function to convert raw flow data to SLPM
float convert_to_slpm(uint16_t raw_flow) {
    return (raw_flow - FLOW_OFFSET) * FLOW_SCALE_FACTOR;
}

// Function to log data to a file
int log_data(FILE *fp, float flow_rate) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s, %.2f\n", timestamp, flow_rate) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("Received SIGINT. Shutting down...\n");
        program_running = 0;
    }
}

int main() {
    uint16_t raw_flow;
    float flow_rate;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read airflow data
        if (read_airflow_data(i2c_fd, &raw_flow) == 0) {
            // Convert to SLPM
            flow_rate = convert_to_slpm(raw_flow);

            // Log data
            if (log_data(log_file, flow_rate) != 0) {
                fprintf(stderr, "Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Failed to read airflow data. Skipping logging.\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Close I2C bus and log file
    close(i2c_fd);
    fclose(log_file);

    printf("Program terminated.\n");
    return 0;
}

