// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting gracefully...\n");
    stop_flag = 1;
}

int main() {
    uint16_t f1, f2, f3, f4, f5, f6, f7, f8, clear, nir;
    float lux;

