void signal_handler(int sig);

// I2C write function with retry
int i2c_write(int fd, uint8_t reg, uint8_t value) {
    int retries = 3;
    int delay_ms = 10;
    int result = -1;

    while (retries > 0) {
        result = i2c_smbus_write_byte_data(fd, reg, value);
        if (result == 0) {
            return 0; // Success
        }
        log_error("I2C write failed, retrying...");
        usleep(delay_ms * 1000); // Convert ms to microseconds
        delay_ms *= 2; // Exponential backoff
        retries--;
    }
    log_error("I2C write failed after multiple retries.");
    return -1; // Failure
}

// I2C read function with retry
int i2c_read(int fd, uint8_t reg, uint8_t *value) {
    int retries = 3;
    int delay_ms = 10;
    int result = -1;

    while (retries > 0) {
        result = i2c_smbus_read_byte_data(fd, reg);
        if (result >= 0) {
            *value = (uint8_t)result;
            return 0; // Success
        }
        log_error("I2C read failed, retrying...");
        usleep(delay_ms * 1000); // Convert ms to microseconds
        delay_ms *= 2; // Exponential backoff
        retries--;
    }
    log_error("I2C read failed after multiple retries.");
    return -1; // Failure
}

