    int delay_ms = 10;
    int result = -1;

    while (retries > 0) {
        result = i2c_smbus_read_i2c_block_data(fd, reg, len, data);
        if (result == len) {
            return 0; // Success
        }
        log_error("I2C block read failed, retrying...");
        usleep(delay_ms * 1000); // Convert ms to microseconds
        delay_ms *= 2; // Exponential backoff
        retries--;
    }
    log_error("I2C block read failed after multiple retries.");
    return -1; // Failure
}

