    if (file == NULL) {
        log_error("Failed to open data file.");
        return -1;
    }
    return 0;
}

// Close data file
void close_data_file(FILE *file) {
    if (file != NULL) {
        fclose(file);
    }
}

// Open error file
int open_error_file(const char *filename) {
    FILE *file = fopen(filename, "a");
    if (file == NULL) {
        perror("Failed to open error file");
        return -1;
    }
    return 0;
}

// Close error file
void close_error_file(FILE *file) {
    if (file != NULL) {
        fclose(file);
    }
}

// Log error message with timestamp
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(error_file, "%s: %s (errno: %d)\n", timestamp, message, errno);
    fflush(error_file);
    perror(message); // Also print to stderr
}

// Read sensor data
int read_sensor_data(int fd, sensor_data_t *data) {
    uint8_t buffer[6];

    if (i2c_read_block(fd, REG_X_L, buffer, 6) != 0) {
        log_error("Failed to read sensor data.");
        return -1;
    }

    data->x = (int16_t)((buffer[1] << 8) | buffer[0]);
    data->y = (int16_t)((buffer[3] << 8) | buffer[2]);
    data->z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

