        return 1;
    }

    // Open I2C device
    i2c_fd = open_i2c_device(i2c_address);
    if (i2c_fd < 0) {
        fclose(error_file);
        return 1;
    }

    // Open data file
    if (open_data_file(filename) != 0) {
        close_i2c_device(i2c_fd);
        fclose(error_file);
        return 1;
    }

    sensor_data_t raw_data;
    double x_g, y_g, z_g;

    // Main loop
    while (running) {
        if (read_sensor_data(i2c_fd, &raw_data) == 0) {
