#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>

// Constants
#define I2C_DEVICE "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5000
#define TTL 1

// Global variables
int i2c_fd = -1;
int udp_socket = -1;

// Function prototypes
int init_i2c(const char *device);
int init_bh1750(int fd);
int read_bh1750(int fd, unsigned int *raw_value);
float convert_to_lux(unsigned int raw_value);
int send_udp_multicast(float lux);
void signal_handler(int signum);

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, cleaning up...\n", signum);
        if (i2c_fd != -1) {
            close(i2c_fd);
        }
        if (udp_socket != -1) {
            close(udp_socket);
        }
        exit(0);
    }
}

// Initialize I2C bus
int init_i2c(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }
    return fd;
}

// Initialize BH1750 sensor
int init_bh1750(int fd) {
    unsigned char power_on_cmd = 0x01;
    unsigned char mode_cmd = CONTINUOUS_HIGH_RES_MODE;

    if (write(fd, &power_on_cmd, 1) != 1) {
        perror("Error writing power-on command");
        return -1;
    }
    usleep(100000); // Wait for sensor to power on

    if (write(fd, &mode_cmd, 1) != 1) {
        perror("Error writing mode command");
        return -1;
    }
    usleep(100000); // Wait for mode to be set

    return 0;
}

// Read raw light value from BH1750 sensor
int read_bh1750(int fd, unsigned int *raw_value) {
    unsigned char buffer[2];

    if (read(fd, buffer, 2) != 2) {
        perror("Error reading data from BH1750");
        return -1;
    }

    *raw_value = (buffer[0] << 8) | buffer[1];
    return 0;
}

// Convert raw value to lux
float convert_to_lux(unsigned int raw_value) {
    return (float)raw_value / 1.2;
}

// Send lux value over UDP multicast
int send_udp_multicast(float lux) {
    struct sockaddr_in addr;
    socklen_t addrlen = sizeof(addr);
    char lux_str[20];

    snprintf(lux_str, sizeof(lux_str), "%.2f", lux);

    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    if (sendto(udp_socket, lux_str, strlen(lux_str), 0, (struct sockaddr *)&addr, addrlen) < 0) {
        perror("Error sending UDP multicast");
        return -1;
    }
    return 0;
}

int main() {
    unsigned int raw_value;
    float lux;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_DEVICE);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Initialize BH1750 sensor
    if (init_bh1750(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize BH1750 sensor. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Create UDP socket
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        perror("Error creating UDP socket");
        close(i2c_fd);
        return 1;
    }

    // Set TTL for multicast
    int ttl = TTL;
    if (setsockopt(udp_socket, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        perror("Error setting TTL for multicast");
        close(i2c_fd);
        close(udp_socket);
        return 1;
    }

    // Main loop
    while (1) {
        // Read light value
        if (read_bh1750(i2c_fd, &raw_value) == 0) {
            // Convert to lux
            lux = convert_to_lux(raw_value);

            // Send over UDP multicast
            if (send_udp_multicast(lux) != 0) {
                fprintf(stderr, "Failed to send UDP multicast. Retrying I2C initialization.\n");
                close(i2c_fd);
                i2c_fd = init_i2c(I2C_DEVICE);
                if (i2c_fd < 0) {
                    fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                    close(udp_socket);
                    return 1;
                }
                if (init_bh1750(i2c_fd) < 0) {
                    fprintf(stderr, "Failed to re-initialize BH1750 sensor. Exiting.\n");
                    close(i2c_fd);
                    close(udp_socket);
                    return 1;
                }
            }
        } else {
            fprintf(stderr, "Failed to read light value. Retrying I2C initialization.\n");
            close(i2c_fd);
            i2c_fd = init_i2c(I2C_DEVICE);
            if (i2c_fd < 0) {
                fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                close(udp_socket);
                return 1;
            }
            if (init_bh1750(i2c_fd) < 0) {
                fprintf(stderr, "Failed to re-initialize BH1750 sensor. Exiting.\n");
                close(i2c_fd);
                close(udp_socket);
                return 1;
            }
        }

        sleep(1);
    }

    return 0;
}

