#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// Configuration
#define UART_DEVICE "/dev/ttyS0"
#define BAUD_RATE 921600
#define MAGIC_WORD_SIZE 8
#define MAGIC_WORD_1 0x0204
#define MAGIC_WORD_2 0x0306
#define MAGIC_WORD_3 0x0805
#define MAGIC_WORD_4 0x0709
#define TLV_TYPE_DETECTED_OBJECTS 6
#define CSV_FILE "radar_data.csv"
#define MAX_FRAME_SIZE 65535 // Maximum frame size (adjust as needed)

// Global variables
int uart_handle;
FILE *csv_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold TLV data
typedef struct {
    uint16_t type;
    uint16_t length;
    uint8_t *value;
} tlv_t;

// Function prototypes
int initialize_uart();
int read_uart(uint8_t *buffer, int max_len);
int parse_tlv(uint8_t *buffer, int len, tlv_t *tlv);
int validate_tlv(tlv_t tlv);
int extract_objects(tlv_t tlv, float *ranges, float *velocities, int *num_objects);
int write_to_csv(float range, float velocity);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize UART
int initialize_uart() {
    uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0); // 0 for default flags
    if (uart_handle < 0) {
        fprintf(stderr, "Error opening UART: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read from UART
int read_uart(uint8_t *buffer, int max_len) {
    int bytes_read = serRead(uart_handle, buffer, max_len);
    if (bytes_read < 0) {
        fprintf(stderr, "Error reading from UART: %s\n", strerror(errno));
        return -1;
    }
    return bytes_read;
}

// Parse TLV
int parse_tlv(uint8_t *buffer, int len, tlv_t *tlv) {
    if (len < 4) {
        fprintf(stderr, "Error: TLV too short\n");
        return -1;
    }

    tlv->type = *((uint16_t *)buffer);
    tlv->length = *((uint16_t *)(buffer + 2));

    if (tlv->length > len - 4) {
        fprintf(stderr, "Error: TLV length exceeds buffer size\n");
        return -1;
    }

    tlv->value = buffer + 4;

    return 0;
}

// Validate TLV
int validate_tlv(tlv_t tlv) {
    if (tlv.type != TLV_TYPE_DETECTED_OBJECTS) {
        fprintf(stderr, "Error: Invalid TLV type: %d\n", tlv.type);
        return -1;
    }
    return 0;
}

// Extract objects from TLV
int extract_objects(tlv_t tlv, float *ranges, float *velocities, int *num_objects) {
    if (tlv.length % 8 != 0) {
        fprintf(stderr, "Error: Invalid object list length: %d\n", tlv.length);
        return -1;
    }

    *num_objects = tlv.length / 8;

    for (int i = 0; i < *num_objects; i++) {
        ranges[i] = *((float *)(tlv.value + i * 8));
        velocities[i] = *((float *)(tlv.value + i * 8 + 4));
    }

    return 0;
}

// Write to CSV
int write_to_csv(float range, float velocity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (csv_file == NULL) {
        fprintf(stderr, "Error: CSV file not opened\n");
        return -1;
    }

    fprintf(csv_file, "%s,%.2f,%.2f\n", timestamp, range, velocity);
    fflush(csv_file); // Ensure data is written immediately

    return 0;
}

// Cleanup function
void cleanup() {
    if (uart_handle >= 0) {
        serClose(uart_handle);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    gpioTerminate();
}

int main() {
    uint8_t buffer[MAX_FRAME_SIZE];
    int bytes_read;
    tlv_t tlv;
    float ranges[10]; // Assuming a maximum of 10 objects
    float velocities[10];
    int num_objects;
    uint32_t magic_word = 0;
    int magic_word_index = 0;
    uint16_t magic_word_words[4] = {MAGIC_WORD_1, MAGIC_WORD_2, MAGIC_WORD_3, MAGIC_WORD_4};

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio\n");
        return 1;
    }

    // Initialize UART
    if (initialize_uart() != 0) {
        cleanup();
        return 1;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "timestamp,object_index,range_m,velocity_mps\n");
    }
    rewind(csv_file);

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "Starting radar data acquisition...\n");

    while (!terminate) {
        bytes_read = read_uart(buffer, MAX_FRAME_SIZE);
        if (bytes_read > 0) {
            for (int i = 0; i < bytes_read; i++) {
                magic_word = (magic_word << 8) | buffer[i];

                if (magic_word_index < MAGIC_WORD_SIZE) {
                    if ((magic_word & 0xFF) == ((uint8_t*)&magic_word_words[magic_word_index])[MAGIC_WORD_SIZE - 1 - magic_word_index]) {
                        magic_word_index++;
                    } else {
                        magic_word_index = 0;
                    }
                }

                if (magic_word_index == MAGIC_WORD_SIZE) {
                    // Synchronization successful
                    magic_word_index = 0;

                    if (parse_tlv(buffer, bytes_read, &tlv) == 0) {
                        if (validate_tlv(tlv) == 0) {
                            if (extract_objects(tlv, ranges, velocities, &num_objects) == 0) {
                                for (int j = 0; j < num_objects; j++) {
                                    if (write_to_csv(ranges[j], velocities[j]) != 0) {
                                        fprintf(stderr, "Error writing to CSV\n");
                                    }
                                }
                            } else {
                                fprintf(stderr, "Error extracting objects\n");
                            }
                        } else {
                            fprintf(stderr, "Error validating TLV\n");
                        }
                    } else {
                        fprintf(stderr, "Error parsing TLV\n");
                    }
                }
            }
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading from UART, retrying...\n");
            gpioDelay(100); // Wait before retrying
        }
    }

    cleanup();
    fprintf(stderr, "Program terminated.\n");
    return 0;
}

