#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define TIMEOUT_SEC 2
#define TIMEOUT_USEC 500000 // 0.5 seconds
#define LINE_BUFFER_SIZE 256

volatile sig_atomic_t program_running = 1;
int uart_fd = -1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully.\n", signal);
}

int setup_uart(const char *device, speed_t baud_rate) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = baud_rate | CS8 | CLOCAL | CREAD;  // 8N1, no parity, ignore modem control lines, enable receiver
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0; // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read at least 0 characters
    tty.c_cc[VTIME] = 5; // Timeout of 0.5 seconds (5 * 0.1s)

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

int read_uart_data(int fd, char *buffer, int buffer_size) {
    fd_set readfds;
    struct timeval timeout;

    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);

    timeout.tv_sec = TIMEOUT_SEC;
    timeout.tv_usec = TIMEOUT_USEC;

    int retval = select(fd + 1, &readfds, NULL, NULL, &timeout);

    if (retval == -1) {
        perror("Error in select");
        return -1;
    } else if (retval) {
        ssize_t bytes_read = read(fd, buffer, buffer_size - 1);
        if (bytes_read == -1) {
            perror("Error reading from UART");
            return -1;
        } else {
            buffer[bytes_read] = '\0';
            return bytes_read;
        }
    } else {
        // Timeout occurred
        return 0;
    }
}

int parse_data(const char *line, time_t *timestamp, float *range) {
    char *timestamp_str = strtok((char *)line, ",");
    char *range_str = strtok(NULL, "\n");

    if (timestamp_str == NULL || range_str == NULL) {
        return -1; // Invalid format
    }

    char *endptr;
    *timestamp = strtol(timestamp_str, &endptr, 10);
    if (*endptr != '\0') {
        return -1; // Invalid timestamp
    }

    *range = strtof(range_str, &endptr);
    if (*endptr != '\0') {
        return -1; // Invalid range
    }

    return 0;
}

void log_data(time_t timestamp, float range) {
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("Timestamp: %s, Range: %.2f meters\n", timestamp_str, range);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uart_fd = setup_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd == -1) {
        return EXIT_FAILURE;
    }

    char line_buffer[LINE_BUFFER_SIZE];
    int line_index = 0;

    while (program_running) {
        int bytes_read = read_uart_data(uart_fd, line_buffer + line_index, LINE_BUFFER_SIZE - line_index - 1);
        if (bytes_read > 0) {
            line_index += bytes_read;

            // Process the line buffer
            while (line_index > 0 && line_buffer[line_index - 1] == '\n') {
                line_buffer[line_index - 1] = '\0'; // Null-terminate the line
                time_t timestamp;
                float range;

                if (parse_data(line_buffer, &timestamp, &range) == 0) {
                    log_data(timestamp, range);
                } else {
                    fprintf(stderr, "Error parsing data: %s\n", line_buffer);
                }

                // Shift the remaining data to the beginning of the buffer
                memmove(line_buffer, line_buffer + strlen(line_buffer) + 1, line_index - strlen(line_buffer) - 1);
                line_index = strlen(line_buffer);
            }
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading from UART, exiting.\n");
            break;
        }
    }

    close(uart_fd);
    return EXIT_SUCCESS;
}

