#include <termios.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR_PIN 4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27

// Define the serial port
#define SERIAL_PORT "/dev/ttyAMA0"

// Define the baud rate
#define BAUD_RATE 115200

// Global variable for the serial file descriptor
int serial_fd = -1;

// Function prototypes
int read_sensor(int gpio_pin);
void log_sensor_data(int left, int middle, int right);
void emergency_stop();
void signal_handler(int signal);

// Function to read the state of a sensor
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to log the sensor data with a timestamp
void log_sensor_data(int left, int middle, int right) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Left: %d, Middle: %d, Right: %d\n", timestamp, left, middle, right);
}

// Function to handle the emergency stop condition
void emergency_stop() {
    const char *message = "EMERGENCY STOP!\n";
    if (serial_fd != -1) {
        ssize_t bytes_written = write(serial_fd, message, strlen(message));
        if (bytes_written < 0) {
            fprintf(stderr, "Error writing to serial port: %m\n");
        }
    } else {
        fprintf(stderr, "Serial port not initialized.\n");
    }
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Close the serial port if it's open
    if (serial_fd != -1) {
        close(serial_fd);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP);
    gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(MIDDLE_SENSOR_PIN, PI_PUD_UP);
    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP);

    // Open the serial port
    serial_fd = open(SERIAL_PORT, O_WRONLY | O_NOCTTY | O_NDELAY);
    if (serial_fd == -1) {
        fprintf(stderr, "Error opening serial port %s: %m\n", SERIAL_PORT);
        gpioTerminate();
        return 1;
    }

    // Configure the serial port
    struct termios tty;
    if (tcgetattr(serial_fd, &tty) != 0) {
        fprintf(stderr, "Error getting serial port attributes: %m\n");
        close(serial_fd);
        gpioTerminate();
        return 1;
    }

    tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD;  // Set baud rate, 8 data bits, ignore modem control lines, enable receiver
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;                                // Raw output
    tty.c_lflag = 0;                                // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read doesn't block
    tty.c_cc[VTIME] = 5; // 0.5 seconds read timeout

    if (tcsetattr(serial_fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error setting serial port attributes: %m\n");
        close(serial_fd);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        int left = read_sensor(LEFT_SENSOR_PIN);
        int middle = read_sensor(MIDDLE_SENSOR_PIN);
        int right = read_sensor(RIGHT_SENSOR_PIN);

        if (left == -1 || middle == -1 || right == -1) {
            fprintf(stderr, "Error reading sensor data, continuing...\n");
            gpioDelay(100); // Delay 100ms
            continue;
        }

        log_sensor_data(left, middle, right);

        if (left == 0 && middle == 0 && right == 0) {
            emergency_stop();
        }

        gpioDelay(100); // Delay 100ms
    }

    return 0;
}

